-- Sources: data/i18n/svSE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:1012"] = {n="Insane Druids",s="När Kayneth Stillwind undersöker Forsaken-intrång i östra Ashenvale upptäcker han en tragisk massaker djupt inne i Dor'Danil Barrow Den. De bofasta druidernas sömn förgiftades och de slaktades av odöda agenter, så deras vansinniga andar blev kvar i plåga. Alliansens äventyrare får i uppdrag att ge deras dödade ledare evig vila och lindra den plågsamma andliga förbannelsen.",h="När Kayneth Stillwind undersöker Forsaken-intrång i östra Ashenvale upptäcker han en tragisk massaker djupt...",kw={"ashenvale","the dor'danil barrow den","forest song","forsaken","vansinniga druider","kayneth stillwind","mavoris cloudsbreak","taneel darkwood","uthil mooncall"},ang={["class:Druid"]="Att slå ner Taneel Darkwood, Uthil Mooncall och Mavoris Cloudsbreak är en högtidlig nådegärning som befriar Cenarion-konstens utövare från alkemiskt vansinne.",["faction:Alliance"]="Denna tragedi visar hur långt Horde's Forsaken sträcker sig och hur grymma de är: de smugglar lömska farsoter långt bortom Lordaeron för att slakta oskyldiga som sover.",["race:NightElf"]="Vanhelgandet av Dor'Danil Barrow Den och slakten av sovande druider är ett upprörande brott mot naturen och Kaldorei, som kräver snabb hämnd på Forsaken."},sec={{t="En syn av slakt",b="Medan nattalven Kayneth Stillwind kämpade mot verkningarna av de virulenta Forsaken-gifter som han hittat i östra Ashenvale, drabbades han av en skrämmande vaken syn. Under de närbelägna jordhögarna i Dor'Danil Barrow Den såg han ett illdåd: druiderna som vilade där hade tyst förgiftats och slaktats av odöda infiltratörer. I stället för att fridfullt gå in i naturens famn slets deras själar våldsamt från sina kroppar och förvreds av onaturligt gift till skriande, irrande vålnader."},{t="Nåd för de dödade ledarna",b="Druidernas vålnader har drivits till vansinne av de onaturliga omständigheterna kring deras död och hemsöker Dor'Danils underjordiska kamrar, oförmögna att finna befrielse. För att tysta den ekande smärtan under jorden ber Kayneth mästare bege sig ner i djupet och slå ner de kvardröjande andarna efter cirkelns tre vördnadsvärda ledare: Taneel Darkwood, Uthil Mooncall och Mavoris Cloudsbreak. Först när dessa plågade gestalter fått vila kan den hemsökta boplatsen börja läka från vanhelgandet."}},faq={{q="Vem förgiftade druiderna i Dor'Danil Barrow Den?",a="Druiderna förgiftades och mördades av Forsaken-infiltratörer. Kayneth Stillwind uppfattade detta avskyvärda brott i en syn när han led av verkningarna från Forsaken-gifter som samlats in från odöda agenter verksamma i Ashenvale.",al={"vem dödade dor'danils druider","vem mördade druiderna","forsaken gift druider"}},{q="Varför blev druiderna vansinniga spöken?",a="Druiderna dödades plötsligt medan de vilade i sina gravhögar. De avskyvärda alkemiska gifterna från Forsaken slet på onaturligt och plågsamt vis deras själar från kropparna och förvred deras kroppslösa andar med vansinne.",al={"varför är druiderna spöken","varför är druider vansinniga","varför vansinniga druider"}},{q="Vilka är Taneel Darkwood, Uthil Mooncall och Mavoris Cloudsbreak?",a="De var de vördnadsvärda ledarna för den druidska cirkel som bodde i Dor'Danil Barrow Den. Efter döden förankrar deras andar vansinnet i boplatsen, så de måste förgöras för att ge de andra hemsökande andarna frid.",al={"druidledare","taneel darkwood","uthil mooncall","mavoris cloudsbreak"}},{q="Var ligger Dor'Danil Barrow Den?",a="Dor'Danil Barrow Den är en underjordisk jordgrav byggd av nattalver, belägen i sydöstra Ashenvale, inte långt söder om ruinerna av Forest Song.",al={"dor'danils plats","var ligger dor danil","gravhög i ashenvale"}},{q="Vem ger uppdraget att ge druiderna ro?",a="Kayneth Stillwind, en nattalv stationerad vid Forest Song i östra Ashenvale, erbjuder uppdraget efter att du hjälpt honom att undersöka Forsaken-sjukdomar.",al={"vem ger insane druids","kayneth stillwinds uppdrag","var börjar insane druids"}},{q="Renar man hela boplatsen genom att dräpa ledarna?",a="Att förgöra de tre ledarna minskar den andliga smärta som griper tag i jordgraven avsevärt, men Kayneth påpekar att det bara är ett steg mot att låta de återstående vansinniga andarna gradvis finna frid.",al={"är dor'danil räddat","blir boplatsen renad"}}},fx={["7181097d"]={q="Varför vill Kayneth Stillwind att druidledarna förgörs?",a="Medan Kayneth kämpade mot Forsakens gifter fick han en syn av sina fränders fasansfulla öde i The Dor'Danil Barrow Den. De mördade druiderna dröjer sig kvar som plågade, vansinniga spöken, och deras ständiga vånda hemsöker hans drömmar. Kayneth hoppas att deras forna ledare ska kunna ge dem ro genom att förgöras, så att de kvarvarande oroliga andarna i gravkullarna äntligen kan finna frid.",al={"kayneths motiv","varför döda vansinniga druider","varför förgöra druidernas andar"}}},fp="13,208,21.394.0,27.385.0,48.202.0,40.169.0,65.203.0,42.104.0,46.139.0,48.160.0"}
P.entries["quest:1013"] = {n="The Book of Ur",s="The Book of Ur är ett uppdrag från Keeper Bel'dugur i Undercitys Apothecarium. Bel'dugur ger Hordens hjältar i uppdrag att infiltrera Shadowfang Keep och hämta Ur's magiska avhandling. Ur var en avliden magiker från Dalaran. The Forsaken söker Ur's forskning om andra plan, med avsikten att göra hans magiska insikter till vapen. Han var för samvetsgrann för att själv utnyttja dem.",h="The Book of Ur är ett uppdrag från Keeper Bel'dugur i Undercitys Apothecarium.",kw={"apothecarium","arugal","bel'dugur","the book of ur","dalaran","fenrus","kirin tor","shadowfang keep","worgen"},ang={["class:Mage"]="The Book of Ur är en mörk relik från Kirin Tors historia. Den visar hur Dalarans teoretiska forskning om utomvärldsliga väsen kunde förvridas till apokalyptiska förbannelser av instabila utövare som Arugal.",["class:Warlock"]="Ur's vilja att blicka bortom den dödliga verkligheten påminner om en häxmästares hunger efter kunskap om andra plan. Bel'dugur menar dock att Ur misslyckades för att han saknade modet att använda det han upptäckt.",["faction:Horde"]="Att rensa Shadowfang Keep och säkra Arugal's källor hjälper till att stabilisera Silverpine Forest och hejda hotet från de vilda worgen som tränger in på Hordens territorium.",["race:Undead"]="Att hämta boken tjänar Lady Sylvanas och Royal Apothecary Society direkt. Det stärker The Forsakens tro på att överlevnad kräver att man anammar förbjuden kunskap utan dödlig kräsenhet."},sec={{t="En relik från andra världar",b="Innan det tredje kriget ödelade Dalaran ägnade en begåvad mänsklig trollkarl vid namn Ur sin forskning åt världar bortom Azeroth. Till skillnad från Kirin Tors vanliga lära, som strikt reglerade frammaning och kontakter med yttre plan, katalogiserade Ur väsen från andra dimensioner, däribland de vilda worgen. Trots sin nyfikenhet tvekade Ur till slut att manipulera dessa främmande krafter. Han ansåg att de var farligt svårkontrollerade. Men hans återhållsamhet gjorde hans skrifter till ett eftertraktat pris för dem som saknar sådana moraliska betänkligheter."},{t="I mörka händer",b="Archmage Arugal fick tag på Ur's avhandling och använde forskningen innan han bosatte sig i Shadowfang Keep. Arugal saknade Ur's etiska betänkligheter och använde bokens innehåll för att kalla fram blodtörstiga worgen till Silverpine. Då släppte han lös en förbannelse som slukade Pyrewood och de omgivande dalarna. Boken ligger nu bortglömd i tornrummen i borgen, bevakad av Arugal's vildsinta husdjur."},{t="The Forsaken's ambitioner",b="För Royal Apothecary Society och Keeper Bel'dugur är Ur's fall ingen varnande berättelse om hybris, utan ett exempel på dödlig svaghet. Bel'dugur tror att Ur dog för att samvetet lamslog honom i krisens stund. Genom att säkra The Book of Ur åt Undercity tänker The Forsaken rensa bort textens akademiska tvekan. De vill bemästra läran om andra dimensioner för att säkra sin överlevnad och befästa Sylvanas Windrunner's herravälde över Lordaeron."}},faq={{q="Vem var Ur?",a="Ur var en framstående magiker från Dalaran som studerade magiska fenomen och andra världar före det tredje kriget. Han forskade ingående om varelser från andra dimensioner, däribland worgen, innan han dödades under Scourges invasion av Dalaran.",al={"ur berättelse","vem är ur","magikern ur"}},{q="Var finns The Book of Ur?",a="Boken finns i Shadowfang Keep, på en bokhylla i kammaren som tillhör Fenrus the Devourer, djupt inne i fästningen.",al={"var finns boken","the book of ur plats","shadowfang book plats"}},{q="Vem är Keeper Bel'dugur?",a="Keeper Bel'dugur är en arkivarie och forskare bland The Forsaken, stationerad i Undercitys Apothecarium. Han samlar på mörk, magisk och utomvärldslig kunskap för att stärka The Forsakens makt och överlevnad.",al={"beldugur","keeper bel dugur","uppdragsgivare"}},{q="Varför vill The Forsaken ha boken?",a="Bel'dugur och hans följe vill åt Ur's forskning om väsen från andra plan. The Forsaken tror att Ur inte överlevde Scourge enbart för att hans samvete hindrade honom från att utnyttja krafterna han upptäckt. Undercity tänker inte göra samma misstag.",al={"varför vill the forsaken ha ur's bok","undercitys syfte med the book of ur"}},{q="Hur hamnade boken i Shadowfang Keep?",a="Efter Dalarans fall fick Archmage Arugal tag på Ur's anteckningar och använde dem för att kalla fram worgen till Lordaeron. Arugal tog med sig forskningen till Shadowfang Keep när han intog fästningen.",al={"hur fick arugal tag på boken","varför finns boken i sfk"}},{q="Har The Book of Ur något samband med worgenförbannelsen?",a="Ja. Ur's forskning beskrev den skrämmande dimension där worgen har sitt ursprung. Arugal använde avhandlingen för att släppa lös dessa bestar i Silverpine Forest, vilket ledde till det plågande angreppet i området.",al={"worgens ursprung i boken","the book of ur och worgen"}}},fx={["8665acc9"]={q="Vad är The Book of Ur?",a="The Book of Ur är en värdefull magisk skrift som skrevs av Dalaran-magikern Ur innan Scourge föll över Lordaeron. Ur ägnade sina studier åt dimensioner bortom vår egen och märkliga, främmande bestar, däribland de vilda worgen. Ur hade enorma magiska kunskaper, men hans samvete hindrade honom till slut från att utforska dessa dödliga krafter alltför djupt. För Forsaken, som föraktar sådana etiska betänkligheter, innehåller hans forskning ovärderliga hemligheter om andra världar och farliga varelser från andra plan.",al={"vad är the book of ur","the book of ur bakgrund","innehållet i the book of ur"}}},fp="14,223,29.437.0,24.315.0,23.411.1,11.195.0,32.123.0,24.186.0,36.260.0,43.174.0,46.168.0"}
P.entries["quest:1014"] = {n="Arugal Must Die",s="Arugal Must Die är ett avgörande uppdrag från Horden, utfärdat av Dalar Dawnweaver vid The Sepulcher. Uppdraget går ut på att modiga kämpar stormar Shadowfang Keep, dödar den förrädiske ärkemagikern Archmage Arugal och hämtar hans avhuggna huvud. Att röja Arugal ur vägen är avgörande för att Lady Sylvanas Windrunner ska kunna bryta varulvshotet och säkra Silverpine Forest åt de Fördömda.",h="Arugal Must Die är ett avgörande uppdrag från Horden, utfärdat av Dalar Dawnweaver vid The Sepulcher.",kw={"arugal","dalar dawnweaver","head of arugal","the sepulcher","shadowfang keep","silverpine","sylvanas","varulvar"},ang={["class:Mage"]="Konfrontationen med Arugal är en varnande berättelse om magisk hybris, där utövare av magins konst ställs mot en Kirin Tor-magiker som förvridits av åkallelser från andra världar.",["faction:Horde"]="När Arugal besegras visar det hur Hordens militära räckvidd växer i Eastern Kingdoms. En befäst trollkarl krossas och viktiga vägar frigörs.",["race:Undead"]="För de Fördömda säkrar Arugals död deras sydvästra gräns och tryggar lederna mellan The Sepulcher och Undercity."},sec={{t="En nagel i den mörka damens öga",b="De Fördömda har skapat en bas i The Sepulcher, men Silverpine Forest är fortfarande förrädisk och hårt omstridd. Högt uppe på klipporna med utsikt över skogen ligger Shadowfang Keep, Archmage Arugals näste. Driven till vansinne av skuld och mörk trolldom släppte Arugal lös de vilda varulvarna över Lordaeron. Hans glupska bestar stryker längs skogsstigarna och hindrar direkt Lady Sylvanas Windrunners försök att skapa ett befäst strategiskt fäste i området."},{t="Slå odjuret där det gör ont",b="Dalar Dawnweaver inser att det aldrig kommer att räcka med att jaga kringströvande bestar i skogen för att rena landet. Fördärvets hjärta slår inne i själva Shadowfang Keep. Hordens kämpar måste ta sig in i det urgamla fästet, kämpa sig igenom Arugals hängivna varulvsflock och konfrontera den vansinnige trollkarlen i hans näste. När hans huvud förs tillbaka till The Sepulcher bryts till sist hans magiska grepp om området, och vägen röjs för de Fördömdas herravälde."}},faq={{q="Varför vill Dalar Dawnweaver att Arugal ska dö?",a="Dalar Dawnweaver lyder den mörka damens order. Arugals varulvar översvämmar Silverpine Forest och gör det omöjligt för de Fördömda att göra området till ett säkert strategiskt fäste innan den vansinnige magikern dödas.",al={"varför döda arugal","dalar dawnweavers mål","arugals mål"}},{q="Var kan Arugal hittas?",a="Archmage Arugal håller till allra högst upp i Shadowfang Keep, en dyster fästning som tornar upp sig över södra Silverpine Forest.",al={"var finns arugal","arugals plats","hitta arugal"}},{q="Vilket bevis krävs för att slutföra uppdraget?",a="Dalar Dawnweaver kräver ett konkret bevis på trollkarlens död: kämparna måste hämta och överlämna Head of Arugal.",al={"vad behöver dalar","arugals huvud uppdrag","dödsbevis"}},{q="Vilket hot utgör Arugal mot Horden?",a="Utöver sina kraftfulla offensiva besvärjelser leder Arugal legioner av förbannade varulvar som trakasserar Hordens styrkor och hotar de Fördömdas kontroll över hela Silverpine Forest.",al={"varför är arugal farlig","varulvshotet i silverpine","är arugal ett hot"}},{q="Vem tjänar Dalar Dawnweaver?",a="Dalar Dawnweaver tjänar Lady Sylvanas Windrunner och de Fördömda. Han verkar från The Sepulcher för att befästa de Fördömdas kontroll över Lordaeron.",al={"vem arbetar dawnweaver för","ledningen i sepulcher"}},{q="Vad händer efter att Arugal besegrats?",a="När Arugal dör bryts hans vidriga magiska grepp om Silverpine, så att de Fördömda kan utöka sitt herravälde över västra Lordaeron utan att behöva frukta hans samordnade varulvsflockar.",al={"efter arugals död","följden av arugals död"}}},fx={["375fc177"]={q="Vad ska Head of Arugal användas till?",a="Dalar Dawnweaver kräver Archmage Arugals avhuggna huvud som ett obestridligt bevis på att den galne trollkarlens välde över Shadowfang Keep är över. Dalar tänker också själv undersöka kvarlevorna för att avslöja och utplåna den vidriga magi Arugal lade över Silverpine Forest, så att hans förbannelse aldrig mer kan hota Forsaken.",al={"head of arugals syfte","varför ta arugals huvud","vad gör dalar med arugals huvud"}},["62d569dd"]={q="Vem är Archmage Arugal?",a="Archmage Arugal var en gång en trollkarl i Kirin Tor i Dalaran. Driven till vansinne släppte han lös de våldsamma worgen över Lordaeron för att bekämpa Scourge, men förlorade kontrollen över bestarna. Han drog sig tillbaka till Shadowfang Keep, mördade Baron Silverlaine och tog fästningen för sig själv. Där tog han de vildsinta monstren till sina förbannade ”barn”, och sedan dess har han terroriserat Silverpine Forest.",al={"vem är arugal","shadowfang keeps boss arugal","varför är arugal i shadowfang"}}},fp="15,184,31.394.0,30.335.0,43.162.0,26.87.0,47.86.0,42.164.0,32.143.0,38.167.1"}
P.entries["quest:1016"] = {n="Elemental Bracers",s="Vattenelementärer har börjat förorena Ashenvales klara sjöar och bäckar, till nattalvernas oro vid Silverwind Refuge. Sentinel Velene Starstrike ber resande samla in hela armband från varelserna för att utröna vilken förbrytarbesvärjare som frammanat dem.",h="Vattenelementärer har börjat förorena Ashenvales klara sjöar och bäckar, till nattalvernas oro vid Silverwind...",kw={"ashenvale","divined scroll","divining scroll","elemental bracers","mage summoner","mystral lake","sentinel velene starstrike","silverwind refuge"},ang={["class:Mage"]="De band som frammanade elementärer bär på sin mästares tydliga arkaniska signatur, vilket gör att ett tränat öga kan spåra vårdslös frammaning tillbaka till dess källa.",["faction:Alliance"]="Genom att hjälpa Silverwind Sentinels stärker du Alliansens ställning i Ashenvales omstridda centrala områden.",["race:NightElf"]="Ashenvales naturliga dammar är helig mark. Att se arkaniska besvärjare medvetet föra in främmande fördärv är en outhärdlig skymf mot Kaldorei."},sec={{t="Förgiftade vatten",b="Ashenvales heliga vatten plågas av en onaturlig farsot och översvämmas av vattenelementärer på villovägar. Till skillnad från de vilda andar som naturligt lever i världen bär dessa väsen spår av att ha frammanats på konstgjord väg. För väktarna vid Silverwind Refuge är de fientliga elementärernas plötsliga ankomst ett alarmerande tecken på yttre fördärv som tränger allt djupare in i skogens rena vattendrag."},{t="Spåra besvärjaren",b="Eftersom Sentinel Velene Starstrike tror att elementärerna medvetet har bundits och släppts lösa, ger hon dig en magisk spådomsrulle för att avslöja den skyldige. Besvärjelsen kräver råmaterial med koppling till de frammanade varelserna, närmare bestämt hela armband som bärgats från andarna innan de skingras. När rullen riktas mot dessa förtrollade band läser magin av den kvarvarande arkaniska signaturen från den som ursprungligen kallade elementärerna till världen."},{t="En trollkarls inblandning",b="När rullen har lästs över de hela armbanden bekräftar de arkaniska resterna Velene värsta farhågor: en ensam magiker rör medvetet upp fördärvade elementärer i Ashenvales dammar. Upptäckten gör nattalvförsvararna ursinniga och bäddar för snabb vedergällning mot besvärjaren som hotar skogsmarkens helgd."}},faq={{q="Varför finns det vattenelementärer i Ashenvale?",a="De fientliga vattenelementärer som hemsöker Ashenvale hör inte naturligt hemma där och lever inte i harmoni med skogen. De har frammanats på konstgjord väg av en utomstående besvärjare, som stör de heliga dammarna och väcker nattalvernas vrede.",al={"varför finns elementärer här","vattenelementärer i ashenvale","varifrån kom elementärerna"}},{q="Vem ger uppdraget Elemental Bracers?",a="Uppdraget ges av Sentinel Velene Starstrike, en officer vid Silverwind Refuge, vid stranden av Mystral Lake i Ashenvale.",al={"uppdragsgivare","vem startar elemental bracers","var hämtar man elemental bracers"}},{q="Vad är syftet med Divining Scroll?",a="Divining Scroll är ett förtrollat pergament som är skapat för att läsa av den magiska signatur som finns kvar på elementärerna. När den läses över fem hela armband spårar den den arkaniska förbindelsen tillbaka till besvärjaren som skapade dem.",al={"vad gör rullen","divining scrolls syfte","varför använda divining scroll"}},{q="Varför fungerar bara hela armband i ritualen?",a="När en elementär förgörs skadas eller krossas ofta dess magiska armband. Endast armband som fortfarande är hela har tillräckligt stabil arkanisk resonans för att rullens magi ska kunna analysera dem och avslöja besvärjaren.",al={"varför hela armband","trasiga armband","hela elementärarmband"}},{q="Vad händer efter att rullen har lästs?",a="När du återlämnar Divined Scroll till Sentinel Velene Starstrike identifierar hon den förbrytarbesvärjare som bär ansvaret och ger dig genast i uppdrag att jaga besvärjaren i det efterföljande uppdraget Mage Summoner.",al={"fortsättning på elemental bracers","what comes next","nästa uppdrag efter elemental bracers"}},{q="Varför bryr sig Sentinel Velene så mycket om dessa elementärer?",a="Nattalver vördar den naturliga renheten i Ashenvales skogar och vatten. Att en dödlig trollkarl medvetet förorenar och rubbar balansen i deras sjöar med fördärvade elementärer är en outhärdlig förolämpning mot deras väktarskap.",al={"sentinel velene motiv","varför nattalver bryr sig om elementärer"}}},fx={b81920f2={q="Vad ska Divined Scroll användas till?",a="Divined Scroll innehåller de mystiska spår som samlats från elementarvarelsernas hela armband. Genom att utföra spådomsritualen präglar du vattenelementarvarelsernas magiska signaturer på pergamentet. När du återlämnar den färdiga skriftrullen till Sentinel Velene Starstrike får Sentinels de viktiga magiska ledtrådar de behöver för att hitta den exakta magiker som på egen hand kallade de fördärvade varelserna till Ashenvales rena vatten.",al={"divined scroll syfte","varför divined scroll","vad gör divined scroll"}}},fp="17,231,14.320.0,21.401.0,19.325.1,44.187.0,38.126.0,43.164.0,47.200.0,39.183.1,61.197.0"}
P.entries["quest:1017"] = {n="Mage Summoner",s="Mage Summoner är ett alliansuppdrag lett av Sentinel Velene Starstrike från Silverwind Refuge. Efter att ha undersökt fördärvade vattenelementarer nära Mystral Lake skickar Sentinels äventyrare över gränsen till The Barrens för att döda den odöda magikern Sarilus Foulborne på toppen av Dreadmist Peak.",h="Mage Summoner är ett alliansuppdrag lett av Sentinel Velene Starstrike från Silverwind Refuge.",kw={"ashenvale","dreadmist peak","light of elune","sarilus foulborne","silverwind refuge","the barrens","velene starstrike","vattenelementarer"},ang={["class:Mage"]="Konfrontationen med Foulborne ställer alliansens disciplinerade arkanister mot en förrymd odöd utövare som tänjer vårdslöst på gränserna för elementarbesvärjelser.",["class:Priest"]="Att få Light of Elune direkt från Sentinels knyter uppdraget till Gudinnans sällsynta, mirakulösa nåd mot de odödas fördärv.",["faction:Alliance"]="Ett angrepp mot ett Forsaken-mål djupt inne i The Barrens blir en djärv kraftdemonstration mot Hordes intrång längs Ashenvales södra gräns.",["race:NightElf"]="Sarilus magiska vanhelgande av naturen precis på andra sidan skogsgränsen är en förolämpning mot Kaldorei. Hans avrättning handlar därför både om skogens balans och om stolthet."},sec={{t="En gränsövergång",b="Nattalver skickar sällan spejare söderut till The Barrens solstekta savanner utan allvarliga skäl. Efter att ha undersökt onaturliga störningar bland vattenelementarerna kring Mystral Lake spårar Sentinel Velene Starstrike inblandningen direkt till Sarilus Foulborne, en Forsaken-besvärjare som utövar sina konster strax på andra sidan gränsen. För Sentinels som vaktar Silverwind Refuge är det outhärdligt att låta en fiendemagiker vanhelga naturen precis utanför deras dörr."},{t="Besvärjaren på toppen",b="Sarilus Foulborne har slagit sig ner högt uppe på Dreadmist Peak, ett klippigt berg där Burning Blade-kultister myllrar. Härifrån kallar han fram led efter led av vattenelementarer och böjer dem efter sin vilja, samtidigt som han hånar nattalvernas auktoritet från Horde-kontrollerat land. För att fälla honom måste du trotsa fiendeland, kämpa dig igenom hans framkallade styrkor och hugga av honom huvudet som bevis på att Sentinels hämnd når bortom skogsbrynet."},{t="Elunes välsignelse",b="När Velene Starstrike får Foulbornes avhuggna huvud suddar hon ut magikerns hån och belönar dråparen med en enastående gåva: Light of Elune. Denna heliga dryck av månljus är en högt skattad skyddande brygd bland prästinnorna och Sentinels. Den ger fullständig osårbarhet när döden är nära. Den påminner kraftfullt om nattalvernas gudomliga gunst mot den onda magi som kryper in i Kalimdor."}},faq={{q="Vem är Sarilus Foulborne?",a="Sarilus Foulborne är en odöd magiker som flydde till The Barrens och slog sig ner på toppen av Dreadmist Peak. Han använder magisk frammaning för att förslava vattenelementarer, vilket väcker vreden hos Sentinels i närliggande Ashenvale.",al={"sarilus foulborne","vem är mage summoner","foulbornes historia"}},{q="Var ligger Dreadmist Peak?",a="Dreadmist Peak är ett framträdande, klippigt berg i norra The Barrens, strax söder om gränsen till Ashenvale. Sarilus Foulborne väntar på dess högsta utsiktsplats.",al={"var ligger dreadmist peak","dreadmist peaks läge","hur hittar man dreadmist peak"}},{q="Varför vill Sentinel Velene Starstrike se Sarilus död?",a="Sarilus har vanhelgat och fördärvat vattenelementarer nära gränsen till Ashenvale. Velene finner hans fräckhet outhärdlig och vill sätta stopp för hans onaturliga besvärjelser och visa att fiender inte kan håna Sentinels från andra sidan gränsen.",al={"varför döda sarilus","velene starstrikes motiv"}},{q="Vad är Light of Elune som belöning?",a="Light of Elune är en sällsynt förbrukningsflaska välsignad med gudomligt månljus. Om du dricker den i ett kritiskt läge blir du helt immun mot all skada och alla besvärjelser under en kort stund, vilket räddar dig från en annars säker död.",al={"light of elune-dryck","light of elune-historia"}},{q="Vilket uppdrag kommer före detta?",a="Det här uppdraget följer direkt efter 'Elemental Bracers'. Där samlar äventyrare in hela armband från de spådomskunniga vattenelementarerna kring Mystral Lake i Ashenvale för att hjälpa Velene ta reda på vem som manipulerar dem.",al={"förutsättning för mage summoner","uppdraget före mage summoner"}},{q="Varför är det farligt för alliansspelare att gå in i The Barrens?",a="The Barrens är Horde:s suveräna territorium och hem för taurener och orcher. Allianssoldater och äventyrare som går in i området riskerar att bli upptäckta av Horde-patruller och rivaliserande kämpar.",al={"farliga barrens","uppdrag i hordens territorium"}}},fx={b17c8b5b={q="Varför vill Sentinel Velene Starstrike ha Sarilus Foulborne's Head?",a="Sentinel Velene Starstrike kräver Sarilus Foulbornes huvud som ett slutgiltigt bevis på hans död. Den Forsaken-magikern har fräckt vanhelgat Ashenvales vattenelementarvarelser och hånat Sentinels från sin plats på andra sidan gränsen. Om du för hans avhuggna huvud tillbaka till Silverwind Refuge står det bortom allt tvivel att hans högmod har fått ett slut, och hans motbjudande leende försvinner för alltid.",al={"sarilus foulbornes huvud","varför ta med sarilus huvud","sarilus huvuds syfte"}},bcfc7529={q="Varför skickar Sentinel Velene Starstrike dig i stället för att gå själv?",a="Sarilus Foulborne har sökt skydd på toppen av Dreadmist Peak, djupt inne i The Barrens. Eftersom det torra landet tillhör Horde skulle en officiell militärstyrka med Night Elf Sentinels riskera att utlösa en öppen gränskonflikt med Hordes vaksamma garnisoner. En skicklig äventyrare som färdas ensam kan passera gränsen obemärkt, döda nekromantikern och återvända innan fienden hinner ordna ett försvar.",al={"varför skicka mig mot magikern som kallade fram varelserna","varför dödar inte velene sarilus","varför behöver sentinel velene mig"}}},fp="13,266,21.416.0,24.422.0,17.314.1,25.206.0,32.146.0,54.233.0,45.195.0,29.180.0,59.164.0"}
P.entries["quest:102"] = {n="Patrolling Westfall",s="Gnollflockar strövar över Westfalls grässlätter och hotar dem som fortfarande bor där. Captain Danuvin kallar på frivilliga från Sentinel Hill för att jaga dem, eftersom han fruktar att de samarbetar med tjuvarna i The Deadmines.",h="Gnollflockar strövar över Westfalls grässlätter och hotar dem som fortfarande bor där.",kw={"danuvin","the deadmines","gnoller","tassar","folkets milis","sentinel hill","stormwind","westfall"},ang={["faction:Alliance"]="För Alliansen står Westfalls kämpande landsbygdsbefolkning i konflikt med aristokratin i Stormwind Keep, som har vänt dem ryggen.",["race:Human"]="Som människa visar det hur bräcklig kungarikets återhämtning efter de senaste krigen fortfarande är när du ser gnoller ta över Westfalls gyllene fält."},sec={{t="Övergivna av kronan",b="Sentinel Hill är Westfalls främsta försvar och hålls av lokala frivilliga snarare än kungliga trupper. Stormwind skickar inga soldater för att skydda de yttre jordbruken, så folket bildade People's Militia. Captain Danuvin, som en gång var jordbrukare i Westfall, leder dem och vägrar överge sitt hemland. Milisen är beroende av resande som passerar och hjälper till att hålla dess försvarslinje mot farorna som samlas över slätterna."},{t="Grässlätternas asätare",b="Gnoller hotar nu flyktingarna och inkräktarna som kämpar för att överleva i Westfall. Danuvins spejare tror att flockarna samarbetar med banditer med bas i The Deadmines. Han skickar ut jägare för att samla in gnolltassar, i hopp om att hejda flockarnas växande patruller och bryta allt samarbete mellan bestarna och laglösa."}},faq={{q="Vem är Captain Danuvin?",a="Captain Danuvin leder frivilliga försvarare vid Sentinel Hill. Han var en gång jordbrukare i Westfall och tog ledningen när Stormwind drog tillbaka sitt stöd. Han vägrar överge dem som är kvar.",al={"captain danuvin","vem är danuvin","uppdragsgivare sentinel hill"}},{q="Varför strider People's Militia mot gnoller i stället för Stormwinds soldater?",a="Stormwinds adelsråd har i stort sett ignorerat Westfalls svåra situation och lämnat regionen utan kungliga soldater. Jordbrukare och arbetare som fördrivits från sina hem bildade People's Militia för att försvara sin mark mot banditer och vilda bestar.",al={"varför ingen stormwind-armé","var finns stormwinds vakter","varför milis"}},{q="Är gnollerna i Westfall organiserade?",a="Gnoller är vanligtvis kaotiska asätare, men Captain Danuvin ser tecken på att Westfalls flockar samordnar sig med tjuvar med bas i The Deadmines. De kan vakta brottslingarnas utkanter.",al={"samarbetar gnoller med defias","gnollallians","tjuvar och gnoller i deadmines"}},{q="Varför ber Captain Danuvin om gnolltassar?",a="Captain Danuvin ber om gnolltassar som bevis på att bestarna har dödats och drivits bort från grässlätterna.",al={"varför gnolltassar","tassbelöning","bevis på dödade gnoller"}},{q="Var brukar man hitta gnollerna?",a="Gnollernas jaktlag och läger ligger utspridda över Westfalls centrala och södra slätter. De strövar över öppna fält kring övergivna gårdar och nära sluttningarna.",al={"gnollernas platser","var hittar man gnoller i westfall"}},{q="Vad händer när gnollhotet drivs tillbaka?",a="People's Militia hoppas att en minskning av gnollernas och de laglösas styrkor låter folket återta slätterna och återställa det skafferi som en gång födde kungariket.",al={"vad händer sedan i westfall","milisens mål","stormwinds kornbod"}}},fx={["939494a1"]={q="Varför vill Captain Danuvin att du patrullerar Westfall?",a="Captain Danuvin vägrar överge sitt hemland. Stormwinds krona har vänt Westfall ryggen och lämnat de kvarvarande bönderna och invånarna utsatta för laglöshet. Danuvin och People's Militia är fast beslutna att återta regionen och återställa den till den bördiga kornbod den en gång var, men de kan inte säkra slätterna medan gnollerna härjar fritt och trakasserar lokalbefolkningen.",al={"varför patrullera westfall","danuvins motiv","varför döda gnollerna i westfall"}},["91e73c26"]={q="Varför finns gnollerna i Westfall?",a="Gnollerna som stryker omkring på gräsmarkerna verkar samarbeta med tjuvarna som befäst sig i The Deadmines. De utnyttjar att rikets militär har dragit sig tillbaka, terroriserar de lokala gårdarna och samarbetar med banditerna för att hålla Sentinel Hill och resten av befolkningen belägrade och splittrade.",al={"vilka är gnollerna","varför är gnollerna här","gnollerna i westfall och the deadmines"}}},fp="19,191,22.427.0,32.307.0,23.192.0,74.225.0,37.188.0,44.110.0,37.158.0,50.159.0"}
P.entries["quest:1020"] = {n="Orendil's Cure",s="Orendil's Cure är ett brådskande leveransuppdrag som örtläkaren Orendil Broadleaf ger åt alliansens resenärer. Efter att ha blandat ett läkemedel av sällsynta växter skickar Orendil budbäraren i ilfart längs skogsvägarna till Astranaar för att rädda ett döende Night Elf-barn.",h="Orendil's Cure är ett brådskande leveransuppdrag som örtläkaren Orendil Broadleaf ger åt alliansens resenärer.",kw={"ashenvale","astranaar","bathran's hair","kur","orendil broadleaf","pelturas whitemoon","relara"},ang={["class:Priest"]="Örter ger Relara tillfällig fysisk lindring, men den kvardröjande sjukdomen kräver snart Elunes heliga ingripande och månriter.",["profession:Herbalism"]="Leveransen visar den avgörande skillnaden mellan rå botanik och läkekonst på slagfältet och hur skördade Ashenvale-örter som Bathran's Hair kan vara skillnaden mellan liv och död för ett barn.",["race:NightElf"]="För Kaldorei innebär skyddet av Astranaar att skydda dess unga. Att hjälpa Pelturas och Relara berör själva kärnan i Night Elf-samhällets överlevnad i en omstridd skog."},sec={{t="En fars förtvivlan",b="I Astranaars centrala bosättning vakar Pelturas Whitemoon över sin dotter Relara medan hon tynar bort av en svår och gåtfull sjukdom. När den lokala kunskapen inte räcker till sökte Pelturas hjälp i Ashenvales vilda skog och vände sig till avlägsna örtläkares visdom innan hoppet helt rann honom ur händerna."},{t="En kapplöpning genom skogen",b="Efter att ha skaffat de nödvändiga beståndsdelarna, särskilt Bathran's Hair, brygger Orendil Broadleaf en särskild dryck som kan hejda sjukdomen. Orendil anförtror den sköra kuren åt en förbipasserande äventyrare och visar vägen söderut och österut längs skogens upptrampade huvudväg, så att flaskan hinner fram innan det är för sent."},{t="En skör fristad",b="Orendils dryck ger Relara välbehövlig lindring, men örtmedicinen är ingen permanent lösning på den övernaturliga ondska som gnager på hennes själ. Leveransen av drycken köper dyrbar tid och inleder ett större sökande bland forntida Kaldorei-ruiner efter helgade reliker välsignade av Elune, som kan fullborda hennes räddning."}},faq={{q="Vem är sjuk i Astranaar?",a="Relara Whitemoon, Pelturas Whitemoons unga dotter, ligger sängbunden i Astranaar. Hennes tillstånd är kritiskt, och hennes far är desperat efter ett läkemedel som kan hejda försämringen.",al={"vem är sjuk","vem behöver kuren","sjukt barn i astranaar"}},{q="Vem bryggde Orendil's Cure?",a="Orendil Broadleaf, en skicklig Night Elf-örtläkare stationerad i norra Ashenvale, beredde blandningen efter att ha fått växtmaterial som samlats in från Bathran's Haunt.",al={"vem gjorde kuren","orendil broadleaf","varifrån kom kuren"}},{q="Var finns Pelturas Whitemoon?",a="Pelturas Whitemoon bor i Astranaar, alliansens främsta stad längs huvudvägen i centrala Ashenvale. Du hittar honom vid sin dotters sjukbädd i en av skogens bostäder.",al={"pelturas plats","var finns pelturas","hitta pelturas i astranaar"}},{q="Botar Orendil's Cure Relara helt?",a="Nej. Örtmedicinen stabiliserar Relaras tillstånd för stunden och ger hennes far nytt hopp, men sjukdomen kräver ett djupare andligt ingripande. Därför ger sig resenärer ut för att söka efter Elune's Tear.",al={"är relara botad","fungerar kuren","kurens resultat"}},{q="Vilka ingredienser användes för att skapa kuren?",a="Huvudingrediensen var Bathran's Hair, en sällsynt och kraftfull växt som samlats från den förbannade marken vid Bathran's Haunt norr om Maestra's Post.",al={"kurens ingredienser","vad består kuren av","bathrans hair"}},{q="Varför bryggde inte Astranaars lokala läkare kuren själva?",a="Relaras åkomma stod emot Astranaars vanliga läkemedel, så Pelturas vände sig till Orendil Broadleafs särskilda botaniska kunskap. Orendil vet hur man hanterar de kraftfulla växter som finns i norra Ashenvale.",al={"varför orendil","varför astranaars läkare misslyckades","varför broadleaf"}}},fx={["49e0bc34"]={q="Varför vill Orendil Broadleaf att detta blir gjort?",a="Orendil Broadleaf är en skicklig örtavlare som vet att tiden håller på att rinna ut för Relara, Pelturas Whitemoons unga barn. Han har lyckats bereda en blandning av den sällsynta växten Bathran's Hair och vill att läkemedlet omedelbart förs till Astranaar för att hejda barnets dödliga åkomma och rädda hennes liv.",al={"varför skickar orendil läkemedlet","orendil broadleafs motiv","varför hjälpa relara"}}},fp="14,149,18.206.0,27.238.0,17.230.1,25.154.0,26.142.0,36.177.0,43.171.1,47.118.0,62.199.0"}
P.entries["quest:1021"] = {n="Vile Satyr! Dryads in Danger!",s="Vile Satyr! Dryads in Danger! är ett brådskande Alliance-uppdrag i Ashenvale, som dryaden Illiyana ger. I desperat behov av hjälp ber hon resande leta efter sina försvunna systrar, som begav sig in i Xavians korrumperade ruiner för att återta en stulen helig relik.",h="Vile Satyr!",kw={"anilia","ashenvale","branch of cenarius","cenarius","dryad","illiyana","satyr","xavian"},ang={["class:Druid"]="Druider har ett djupt släktskap med Cenarius barn och har svurit att rena den demoniska korrumpering som sprider sig från satyrernas fästen, som Xavian.",["faction:Alliance"]="När du hjälper Illiyana stärker du Alliansens band till Ashenvales mystiska invånare medan hoten i området växer.",["race:NightElf"]="Dryaderna är Cenarius heliga döttrar, så deras nöd och vanhelgandet av de forntida alvtemplens ruiner i Xavian är en fråga om personlig heder och andlig plikt."},sec={{t="En desperat syster",b="När dryaden Illiyana vilar i Ashenvale överväldigas hon av oro. En grupp av hennes dryadsystar gav sig av till skogens korrumperade norra delar på ett farligt uppdrag för att återta Branch of Cenarius, en helig relik som stulits av de vidriga satyrerna. De lovade att snart komma tillbaka, men två dagar har gått utan ett ljud. Därför vädjar Illiyana till Alliance-resande som passerar att hitta dem innan det är för sent."},{t="Xavians ruiner",b="Dryaderna styrde färden mot Xavian, ett forntida tempelkomplex för nattalver i nordost, som länge legat under skuggan av Burning Legions kvarvarande korrumpering. Xavian vimlar av satyrer besmittade av felmagi och är en synnerligen farlig jaktmark. Om du beger dig djupt in i ruinerna hittar du Anilia, ledaren för dryadernas expedition. Hon är svårt sårad och nära döden efter att ha drabbats av ruinernas demoniska invånares brutala vrede."}},faq={{q="Vem är Illiyana?",a="Illiyana är en dryad som lever i Ashenvales skogar. Orolig för sina systrars öde skickar hon resande till Xavians ruiner för att leta efter den försvunna gruppen.",al={"illiyana","vem ger uppdraget vile satyr! dryads in danger!","uppdragsgivare"}},{q="Vad är Branch of Cenarius?",a="Branch of Cenarius är en helig relik som betyder mycket för dryader och nattalver. Satyrer i norra Ashenvale stal den, vilket fick Anilia och hennes systrar att ge sig ut på ett farligt uppdrag för att hämta den i Xavian.",al={"branch of cenarius","vilken relik letade de efter","dryadrelik"}},{q="Vad är Xavian?",a="Xavian är ruinerna av ett forntida tempel för nattalver i östra Ashenvale. Platsen har tagits över av demoniska satyrer och genomsyras av felkorrumpering och fientlighet mot naturens beskyddare.",al={"xavian","xavians ruiner","var finns dryaderna"}},{q="Vem är Anilia?",a="Anilia är dryaden som ledde sökgruppen för att återta Branch of Cenarius från satyrerna. Illiyana ber resande att hitta henne i Xavian.",al={"anilia","försvunnen dryadledare","var finns anilia"}},{q="Varför är dryaderna i konflikt med satyrerna?",a="Dryader är halvguden Cenarius döttrar och har vigt sig åt att bevara naturen och skogens balans. Satyrer är forntida nattalver som förvridits av demonisk felmagi och aktivt fördärvar vildmarken och vanhelgar heliga lundar.",al={"varför avskyr dryader satyrer","krig mellan dryader och satyrer","satyrernas korrumpering"}},{q="Vilket uppdrag följer efter detta?",a="När du hittar Anilia är sökandet avslutat, och det leder vidare till ”The Branch of Cenarius”, där arbetet med att återta den stulna reliken fortsätter.",al={"nästa uppdrag","uppdragskedjan dryads in danger","efter vile satyr"}}},fx={a04fd548={q="Varför behöver Illiyana hjälp att hitta sina systrar?",a="Illiyana är förskräckt för sina systrars skull. Anilia ledde en grupp dryader nordost till de fördärvade ruinerna i Xavian för att återta en helig relik, Branch of Cenarius, från satyrerna. De lovade att snart komma tillbaka, men två dagar har gått utan ett livstecken. Illiyana fruktar att de har överfallits eller övermannats av de vidriga varelser som lurar i ruinerna. Hon behöver snabbt någon som vågar sig in i Xavian, letar reda på dem och ser om någon har överlevt.",al={"varför skickar illiyana dig","illiyanas motiv","varför hitta anilia"}}},fp="29,163,18.358.0,19.312.1,16.152.0,31.200.0,15.150.0,14.142.1,46.222.0,28.132.1"}
P.entries["quest:1022"] = {n="The Howling Vale",s="Det här uppdraget får du av Sentinel Melyria Frostshadow vid The Shrine of Aessina och det leder Alliansens äventyrare till The Howling Vale nära gränsen till Felwood. Den förfallna helgedomen Mel'Thandris har tagits över av vilda vargmän som kallas worgen. Genom att studera den heliga Tome of Mel'Thandris hoppas undersökarna förstå varför dessa märkliga varelser har dykt upp i Ashenvale.",h="Det här uppdraget får du av Sentinel Melyria Frostshadow vid The Shrine of Aessina och det leder Alliansens...",kw={"ashenvale","felwood","the howling vale","mel'thandris","melyria frostshadow","scythe of elune","terrowulf","tome of mel'thandris","velinde starsong","worgen"},ang={["class:Priest"]="Präster kommer att finna sökandet efter Priestess Velinde Starsong en allvarsam berättelse om hängivenhet till Elune.",["faction:Alliance"]="Undersökningen i The Howling Vale markerar början på Alliansens sökande efter ursprunget till de skräckinjagande worgenbestar som strövar omkring i både norra Kalimdor och Eastern Kingdoms.",["race:NightElf"]="Vanhelgandet av Mel'Thandris helgedom och de tragiska synerna av Priestess Velinde Starsong träffar kärnan i nattalvernas heliga plikt att skydda Ashenvale mot märkliga förbannelser."},sec={{t="En kuslig närvaro",b="Medan nattalvernas väktare lägger stora resurser på att hålla stånd mot den demoniska korruptionen som väller ut ur Felwood, har ett nytt hot i tysthet slagit sig ner i Ashenvales norra kullar. Den förfallna helgedomen Mel'Thandris, gömd bortom en grottgång nära gränsen till Felwood, har fallit i händerna på våldsamma vargmän vars hemska ylanden ekar genom trädkronorna. Området kallas nu The Howling Vale, och Sentinel Melyria Frostshadow befarar att denna bestialiska plåga kan förebåda ännu en katastrof för skogsriket."},{t="Den levande krönikan",b="För att förstå var dessa bestar kommer ifrån hänvisar Melyria sökarna till Tome of Mel'Thandris, som ligger inne i den övertagna helgedomen. Boken är långt ifrån en vanlig text; dess blad välsignades av Mel'Thandris själv för att på övernaturlig väg återspegla och fånga betydelsefulla händelser. När den öppnas bland de fientliga worgen frammanar artefakten en spektral syn av Priestess Velinde Starsong, som avslöjar den ödesdigra åkallelsen av en mystisk relik vid namn Scythe of Elune."}},faq={{q="Var ligger The Howling Vale?",a="The Howling Vale ligger i norra centrala Ashenvale, strax sydväst om gränsen till Felwood. En grottgång mynnar ut i den gömda dalen och den förfallna helgedomen Mel'Thandris.",al={"platsen för howling vale","hur man tar sig till howling vale","var ligger helgedomen mel'thandris"}},{q="Vilka är vargmännen i dalen?",a="Dessa vilda vargmän är worgen, närmare bestämt medlemmar av Terrowulf-flocken. De är onaturliga, våldsamma tvåbenta bestar som plötsligt dök upp i Kalimdor och terroriserade ruinerna nära gränsen till Felwood.",al={"vargmän i ashenvale","vilka är monstren i howling vale","terrowulf-worgen"}},{q="Vad är Tome of Mel'Thandris?",a="Tome of Mel'Thandris är en förtrollad relik som ligger bland helgedomens ruiner. I stället för att vara skriven med bläck som en vanlig bok välsignades dess blad av Mel'Thandris för att bevara och visa syner av avgörande historiska händelser för dem som studerar den.",al={"tome of melthandris","vad gör boken","mel'thandris bok"}},{q="Vem var Velinde Starsong?",a="Velinde Starsong var en nattalvprästinna som förknippades med kampen mot demoner nära Felwood. Tome of Mel'Thandris kan ge ledtrådar till hennes historia.",al={"velinde starsong","prästinnan velinde","vem är anden i boken"}},{q="Vem ger det här uppdraget?",a="Sentinel Melyria Frostshadow ger uppdraget från The Shrine of Aessina i Ashenvale. Hon oroar sig djupt över demoniska intrång från Felwood och worgenens oförklarliga uppdykande i närheten.",al={"vem startar howling vale","uppdragsgivare i howling vale","melyria frostshadow"}},{q="Varför bryr sig Sentinel Melyria om helgedomen?",a="Väktarna i Ashenvale står som en sköld mot korruptionen från Felwood. När mystiska vargmän våldsamt tog över en forntida, helig plats för nattalver precis vid gränsen behövde väktarna ta reda på om det rörde sig om en demonisk plan eller en helt ny fara.",al={"varför undersöka howling vale","forest song-väktare"}}},fp="16,146,19.335.0,20.319.1,34.164.0,34.196.0,33.171.0,25.151.1,21.171.0,48.220.0"}
P.entries["quest:1023"] = {n="Raene's Cleansing",s="Uppdraget fortsätter den tragiska sökningen efter Teronis, en Night Elf-väktare som skickades till Lake Falathim. När hans kvarlevor hittas vid stranden går uppdraget ut på att återfinna hans forskningsjournal och hämta den Glowing Gem som de lokala murlocerna bär på, innan de dystra nyheterna förs tillbaka till Astranaar.",h="Uppdraget fortsätter den tragiska sökningen efter Teronis, en Night Elf-väktare som skickades till Lake...",kw={"ashenvale","astranaar","glowing gem","lake falathim","murloc","raene's cleansing","sentinels","teronis"},ang={["faction:Alliance"]="När du säkrar Astranaars norra infarter och hjälper Raene Wolfrunner stärker du Alliansens band till de Sentinels som håller Ashenvale.",["race:NightElf"]="En annan Sentinels död vid Lake Falathim visar den växande faran som hotar Kalimdors forntida, heliga lundar."},sec={{t="En fallen spejare",b="Äventyrare som skickats till Lake Falathim av Raene Wolfrunner upptäcker Teronis död vid vattnet. Uppdraget blir ingen räddningsaktion, utan i stället ett sökande efter hans tillhörigheter och ledtrådar. Bland dem finns en oskadd journal som beskriver hans uppdrag och vad han fann om de märkliga störningarna i Ashenvale."},{t="Den glödande ädelstenen",b="Teronis hade spårat en sällsynt, lysande sten till sjön, men den hamnade hos de aggressiva murlocer som hemsöker det grunda vattnet. För att föra den avlidne spejarens ursprungliga uppdrag vidare måste både Teronis' Journal och den bortrövade stenen återtas."},{t="Sorg i Astranaar",b="Återkomsten till Astranaar väcker sorg hos Raene Wolfrunner, som måste ordna en patrull för att hämta sin fallne kamrats kropp. Men skogen hotas av fördärv, så Raene kan inte sörja länge. Hon ber dig ta över Teronis' uppdrag och slutföra det han dog med att försöka: att återskapa staven som han hoppades skulle hejda furbolgernas angrepp."}},faq={{q="Vem var Teronis?",a="Teronis var en Night Elf-spejare som Raene Wolfrunner skickade ut från Astranaar. Han skulle undersöka vattnen i Lake Falathim och säkra en mystisk ädelsten, men den fientliga faunan i området övermannade och dödade honom innan han hann fullgöra sitt uppdrag.",al={"teronis","vem är teronis","teronis historia"}},{q="Var hittar man Glowing Gem?",a="Glowing Gem bärs av murlocer som lever vid stränderna och i vattnen kring Lake Falathim i nordvästra Ashenvale, nära platsen där Teronis' Corpse hittades.",al={"var finns glowing gem","glowing gem plats","hitta glowing gem"}},{q="Varför är Raene Wolfrunner så fokuserad på det här uppdraget?",a="Teronis var en gammal vän till Raene och trodde att staven han sökte efter kunde hejda furbolgernas angrepp på hennes folk. Furbolgerna i Ashenvale fortsätter att plundra, så Raene ser hans oavslutade uppdrag som en viktig prioritet trots att han miste livet.",al={"varför raene's cleansing","raene wolfrunner motiv"}},{q="Vad händer med Teronis' kropp efter uppdraget?",a="Raene Wolfrunner lovar att skicka en avdelning Sentinels från Astranaar för att hämta Teronis' kvarlevor, så att han kan sörjas och få en traditionell Night Elf-begravning.",al={"teronis corpses öde","vad händer med teronis"}},{q="Vad används Teronis' Journal till?",a="Journalen dokumenterar Teronis' undersökning av den mänsklige magikern Dartol, som använde druidmagi i ett försök att bli vän med och kontrollera furbolgerna. Den innehåller också hans anteckningar om hur man återfinner delarna av staven som Dartol skapade.",al={"teronis journal","vad är journalen"}},{q="Fortsätter uppdragskedjan när man lämnar in uppdraget?",a="Ja. När du återlämnar ädelstenen och journalen till Raene Wolfrunner ber hon dig fortsätta Teronis' arbete. Det leder vidare till sökandet efter de återstående delarna av Dartols stav.",al={"uppdragets fortsättning","nästa uppdrag efter teronis"}}},fx={a4b5e1af={q="Varför håller murlocerna vid Lake Falathim i ädelstenen?",a="De vidriga fenmurlocerna som hemsöker Lake Falathims stränder och vatten letar efter allt som skimrar eller har kraft, och som sköljs in på deras område. Efter Teronis död vid sjökanten snappade de vilda varelserna snabbt åt sig den strålande stenen och vaktar den svartsjukt i sin klunga.",al={"varför har murlocer ädelstenen","murlocer lake falathim","lake falathim-murlocer"}},["699dfe26"]={q="Varför är det viktigt att hitta Teronis' Journal och ädelstenen?",a="Teronis dog innan han hann slutföra det viktiga uppdrag Astranaar hade anförtrott honom. När du återfinner hans oskadda journal och hämtar Glowing Gem från vattnen i närheten ser du till att hans offer inte var förgäves. Då kan Raene Wolfrunner förstå och fortsätta hans reningsuppdrag.",al={"varför hitta teronis journal","varför återta glowing gem","teronis uppdragsmotiv"}},["9d747809"]={q="Vad är Glowing Gem?",a="Glowing Gem är en förtrollad sten som Teronis spårade till Lake Falathim innan han dog. Raene Wolfrunner behöver den för sitt reningsarbete, men sjöns aggressiva murlocs har kommit över den strålande reliken. Den måste återtas för att Teronis heliga uppdrag ska kunna fortsätta.",al={"vad är glowing gem","glowing gems bakgrund","varför glowing gem"}}},fp="17,257,14.251.0,15.182.0,18.281.1,16.183.0,31.121.0,48.213.0,47.156.0,29.202.0,51.146.0"}
P.entries["quest:1024"] = {n="Raene's Cleansing",s="Det här steget i utredningen av korruptionen i Ashenvale leder Alliansens äventyrare djupt in i de heliga lundarna öster om Iris Lake. Du får en återfunnen Glowing Gem och måste rådfråga dryaden Shael'dryn om hur Dartols forntida stav kan återställas.",h="Det här steget i utredningen av korruptionen i Ashenvale leder Alliansens äventyrare djupt in i de heliga...",kw={"ashenvale","dartols stav","glowing gem","iris lake","månbrunn","raene wolfrunner","raenes rening","shael'dryn","teronis"},ang={["class:Druid"]="Att hjälpa dryaden Shael'dryn ligger helt i linje med Cenarions plikt att läka de brutna banden mellan naturen och Kaldorei-magin.",["faction:Alliance"]="Att stärka Astranaars norra försvarslinje och säkra forntida artefakter bidrar till Alliansens krigsinsats mot växande hot i regionen.",["race:NightElf"]="När staven återställs fortsätter Teronis oavslutade utredning av problemen bland Ashenvales furbolger."},sec={{t="En ledtråd i Teronis anteckningar",b="Efter vaktposten Teronis tragiska död granskar Raene Wolfrunner fältanteckningarna han lämnade efter sig. Hans efterforskningar tyder på att utredningen av Ashenvales oroliga furbolger kan kräva en forntida artefakt: en stav som för länge sedan tillverkades av en Night Elf vid namn Dartol. Med bara en Glowing Gem i handen erkänner Raene att hennes taktiska expertis som jägare inte räcker till för att tyda förlorade arkaniska och naturliga mysterier."},{t="På jakt efter Cenarius döttrar",b="I stället för att gissa sig till de återstående delarna av Dartols stav leder Raene resenärer nordost mot Iris Lake. Intill en fridfull månbrunn bor Shael'dryn, en dryad vars naturliga samhörighet med skogen ger henne djup insikt i forntida reliker. Genom att överlämna ädelstenen till henne hoppas äventyrarna hitta de saknade delarna och lära sig hur staven kan smidas om."}},faq={{q="Vem var Teronis?",a="Teronis var en Night Elf-spejare som Astranaar skickade för att undersöka den onda korruption som spreds genom Ashenvale. Han dödades under sitt uppdrag, men den återfunna dagboken innehöll den avgörande ledtråden: att återställa Dartols stav kunde hjälpa landet.",al={"teronis","teronis anteckningar","vem är teronis"}},{q="Vad är Dartols stav?",a="Dartols stav är en forntida magisk artefakt som Raene Wolfrunner hoppas ska hjälpa henne att utreda Ashenvales furbolger. Den återfunna Glowing Gem är en av delarna som behövs för att återställa den.",al={"dartols stav","vad är staven"}},{q="Var hittar jag Shael'dryn?",a="Shael'dryn bor vid en avskild månbrunn nordost om Astranaar, inbäddad bland kullarna strax öster om Iris Lake. Den säkraste vägen är att följa vägen österut och svänga norrut innan du når de farliga trakterna nära Raynewood Retreat.",al={"var finns shael'dryn","shael'dryns plats","hitta dryaden"}},{q="Vad är Glowing Gem?",a="Glowing Gem är en viktig del av Dartols stav, återfunnen i ruinerna efter Teronis ödesdigra utredning. Den genljuder av stark magi och Shael'dryn behöver den för att spåra upp stavens övriga delar.",al={"glowing gem","vad ska ädelstenen användas till","teronis ädelsten"}},{q="Varför skickar Raene Wolfrunner dig till en dryad?",a="Som jägare och ledare för Astranaars vaktposter fokuserar Raene på militärt försvar. Kunskap om forntida reliktillverkning och naturens återställande hör till dryadernas andliga område, Cenarius döttrar.",al={"varför träffa en dryad","raene wolfrunner dryad","varför shael'dryn"}},{q="Varför är skogen runt Iris Lake i fara?",a="Korruption och oro sprider sig bland Ashenvales djurliv och furbolgstammar. Raene hoppas att en återställd stav ska hjälpa henne att få veta mer om furbolgernas svåra situation.",al={"korruption i ashenvale","varför är ashenvale korrumperat","faran vid iris lake"}}},fx={["3ee5b81a"]={q="Varför behöver Raene att du tar ädelstenen till Shael'dryn?",a="Som jägmästare och ledare stationerad i Astranaar har Raene Wolfrunner fullt upp med att samordna försvaret av Ashenvale mot växande demoniska hot och hot från andra grupper. Hon kan inte lämna sin post för att forska i obskyr magi eller resa till avlägsna månbrunnar. Eftersom du hämtade Teronis dagbok och ädelstenen från murlocerna litar hon på att du slutför den fallne spejarens arbete.",al={"varför skicka mig till shael'dryn","varför går inte raene själv","varför jag i raene's cleansing"}}},fp="17,186,25.339.0,33.282.0,16.217.0,21.184.0,28.193.0,24.154.0,46.190.0,45.159.0"}
P.entries["quest:1025"] = {n="An Aggressive Defense",s="An Aggressive Defense är ett Alliance-uppdrag som ges av Sentinel Raene Wolfrunner i Astranaar. Furbolgkorruptionen härjar längs Ashenvales centrala vägar, och Night Elf tvingas till en aktiv utrensning av den vansinniga Foulweald-stammen.",h="An Aggressive Defense är ett Alliance-uppdrag som ges av Sentinel Raene Wolfrunner i Astranaar.",kw={"ashenvale","astranaar","falfarren","foulweald","furbolg","raene wolfrunner","sentinels"},ang={["class:Druid"]="Druiderna ser Foulwealds vansinne som en plågsam påminnelse om den demoniska smitta som drabbar Kalimdors heliga vildmarker.",["faction:Alliance"]="När Foulweald röjs undan skyddas livsviktiga försörjnings- och färdvägar för Alliance som förbinder Astranaar med utposter i östra Ashenvale.",["race:NightElf"]="För kaldorei är det en sorglig nödvändighet att döda Foulweald. De tvingas rikta sina vapen mot forna skogsfränder som helt har förlorat förståndet till korruptionen."},sec={{t="Hot mot landsvägen",b="Vägen österut från Astranaar mot Falfarren River är en livsviktig förbindelse genom Ashenvale, men den har blivit ytterst farlig. Furbolger som drivits till vansinne av demonisk korruption har börjat överfalla resenärer direkt från huvudleden. I stället för att bara bemanna barrikader och vänta på nästa bakhåll skickar Sentinel Raene Wolfrunner ut dugliga äventyrare för att slå ut Foulweald-lägren strax söder om landsvägen."},{t="En bitter historia",b="Att fälla Foulwealds furbolger är en tragisk börda för Night Elf. Björnfolket var sedan urminnes tider nära vänner och allierade till kaldorei och delade deras vördnad för naturen och de vilda gudarna. Men den kvardröjande smittan från Burning Legions invasion krossade förståndet hos många stammar och förvandlade fredliga grannar till blodtörstiga rövare vars våld hotar oskyldiga resenärer."}},faq={{q="Vem ger uppdraget och var finns personen?",a="Uppdraget ges av Raene Wolfrunner, en Sentinel-befälhavare stationerad i Astranaar, den främsta Night Elf-bosättningen i centrala Ashenvale.",al={"uppdragsgivare","vem ger an aggressive defense","var finns raene wolfrunner"}},{q="Varför är furbolgerna i Ashenvale fientliga?",a="Foulweald-stammen, liksom flera andra furbolgklaner i Kalimdor, föll offer för den demoniska smitta som Burning Legion lämnade efter sig under det tredje kriget. Deras sinnen förvrängdes och de blev våldsamma, vilket drev dem till att slakta resenärer och angripa forna allierade.",al={"varför är furbolger vansinniga","foulweald fientliga","furbolgkorruption"}},{q="Var finns Foulweald-lägren?",a="Deras läger ligger söder om huvudvägen österut från Astranaar, väster om Falfarren River.",al={"var finns foulweald","var hittar man foulweald","var finns furbolgerna"}},{q="Har furbolgerna alltid varit Night Elf-folkets fiender?",a="Nej. I tusentals år levde furbolgerna och Night Elf-folket sida vid sida i harmoni. Det var först när demonisk korruption svepte genom Ashenvale och Felwood som stammar som Foulweald förlorade förståndet och blev fientliga.",al={"furbolgernas night elf-lore","var furbolgerna goda","kaldorei och furbolger"}},{q="Har uppdraget samband med andra händelser i Astranaar?",a="Ja. Raene Wolfrunner ger uppdraget som ett tillfälligt försvarsslag samtidigt som hon skickar hjältar för att undersöka korrumperade månkällor och bidra till att rena skogen.",al={"krav för uppdraget","raenes koppling till reningen"}},{q="Vilka furbolger måste elimineras?",a="Raene kräver att en Foulweald Den Watcher, två Ursas, tio Totemics och tolv Warriors dödas för att slå sönder deras befälsstruktur och skingra hotet nära vägen.",al={"uppdragsmål","vem ska jag döda","foulweald-mål"}}},fx={bc4e30a1={q="Varför vill Raene Wolfrunner att Foulweald-furbolgerna ska decimeras?",a="Förvridna Foulweald-furbolger har slagit läger söder om vägen som leder österut mot Falfarren River. Skogens besudlade tillstånd har gjort dem galna och våldsamma, och de ger sig direkt på resande och oskyldiga vägfarare. Raene behöver minska deras aggressiva antal för att skydda vägen och lätta trycket på Astranaars hårt ansatta försvarare.",al={"varför döda foulweald","raene wolfrunners motiv","varför aggressivt försvar"}},bea6b71d={q="Vilka är Foulweald-furbolgerna som du skickas att bekämpa?",a="Foulweald är en lokal furbolgstam som bor i Ashenvale och vars sinnen dukat under för de mörka, fördärvande energier som sipprar genom skogen. De var en gång tillbakadragna grannar till nattalverna, men deras galenskap visar sig nu som blodtörstigt rovdjursbeteende. De ligger i bakhåll för resande längs landsvägen öster om Astranaar.",al={"vilka är foulweald-furbolgerna","vad är foulweald","vilka är målen"}}},fp="21,160,21.289.0,16.315.0,48.117.0,42.164.0,36.96.0,52.172.0,53.141.0,42.144.0"}
P.entries["quest:1026"] = {n="Raene's Cleansing",s="Det här uppdraget är ett avgörande steg i återställandet av Dartol's Rod of Transformation, en uråldrig Night Elf-relik som Raene Wolfrunner söker efter. Vägledda av Shael'dryn vid hennes månsjö måste äventyrare bege sig norrut mot Felwoods fördärvade gräns för att hitta ett järnskaft låst i en gömd kista. Uppdraget har en tragisk underton och tvingar Alliansen att möta korrumperade uråldringar som vaktar nyckeln.",h="Det här uppdraget är ett avgörande steg i återställandet av Dartol's Rod of Transformation, en uråldrig Night...",kw={"ashenvale","crazed ancient","dartol's rod","felwood","iron shaft","månsjö","raenes rening","shael'dryn","withered ancient","wooden key"},ang={["class:Druid"]="Att se de uråldringar som Felwoods framryckande fördärv driver till vansinne är en dyster påminnelse om The Emerald Dreams kamp för att läka den sårade världen ovan jord.",["faction:Alliance"]="Att återuppbygga Dartols relik är avgörande för att säkra vägnätet i norra Ashenvale mot det växande hotet från korrumperade furbolgar och demoniska styrkor.",["race:NightElf"]="Det är en plågsam plikt att göra slut på Crazed Ancients, eftersom dessa levande träd en gång var älskade följeslagare och skogens väktare innan den demoniska farsoten förgiftade deras andar."},sec={{t="En skärva nära fördärvet",b="För att följa ledtrådarna och laga Dartol's Rod skickar Raene sökandet vidare till Shael'dryn, en kunnig väktare som vakar över en fridfull månsjö djupt inne i Ashenvale. Shael'dryn vet var stavens järnskaft finns, men för att hämta det måste man möta den krypande korrumpering som hotar de norra skogarna. Delen ligger låst i en gammal kista undangömd i en stilla glänta nära gränsen till Felwood."},{t="De fallna väktarna",b="För att nå kistan krävs en tränyckel, men den har hamnat i händerna på skogens förvridna beskyddare. Längs bergsvägen norrut mot Felwood vandrar treanter som kallas Crazed och Withered Ancients i plågor. Korrumperingen som sipprar söderut från de demoniska ödemarkerna har krossat deras naturliga harmoni och förvandlat vildmarkens forna väktare till fientliga, plågade varelser som måste betvingas för att återta Dartols relik."}},faq={{q="Vem är Shael'dryn?",a="Shael'dryn är en dryad som är stationerad vid en avskild månsjö i Ashenvale, öster om Astranaar och söder om vägen till Felwood. Hon besitter djup kunskap om skogens historia och Dartols uråldriga hantverk och ger stillsamma råd till dem som försöker laga staven.",al={"shaeldryn","vem är månsjöns väktare","shael'dryns bakgrund"}},{q="Varför är treanterna korrumperade?",a="Treanterna lever längs de norra åsarna som gränsar till Felwood. Det utbredda demoniska fördärvet från Tredje kriget sipprar fortfarande söderut in i Ashenvale, förvrider träden, driver de uråldriga väktarna till vansinne och förvränger deras naturliga band till landet.",al={"korrumperade treanter","varför är treanter galna","crazed ancients bakgrund"}},{q="Vad är Dartol's Rod?",a="Dartol's Rod är en förtrollad relik skapad av Dartol, en ond trollkarl som nu är död. När staven har satts ihop helt och renats bär den på stark förvandlingsmagi som kan förklä bäraren till en furbolg, vilket gör den avgörande för Raenes planer att undersöka de lokala stammarna.",al={"dartols stav","förvandlingsstav","vad gör staven"}},{q="Var finns den gömda kistan?",a="Den slitna kistan med järnskaftet står i en liten, stilla glänta strax väster om bergsvägen som leder norrut från Ashenvale mot gränsen till Felwood.",al={"sliten kista plats","var finns järnskaftet","var finns kistan"}},{q="Varför sörjer Shael'dryn treanterna?",a="Treanter är tidlösa vårdare av Kaldoreis skogar och vördas som naturens heliga andar. Det plågar Shael'dryn djupt att se dem falla för vansinne och korrumpering utan något känt botemedel, eftersom det är en sorgens handling att göra slut på deras lidande, inte en illvillig sådan.",al={"shael'dryn och treanterna","varför är shael'dryn ledsen"}},{q="Hur passar uppdraget in i den större reningskedjan?",a="Här samlas de fysiska delarna av Dartols trasiga stav. När järnskaftet och de andra delarna har samlats in riktas arbetet mot att rena stavens kvarvarande magiska kraft.",al={"raenes reningskedja","raenes uppdragskedja"}}},fx={["348d2e5e"]={q="Vad är Iron Shaft?",a="Iron Shaft är en viktig del av Dartol's Rod, en forntida relik vars magi låter bäraren anta en furbolgs skepnad. Stavens delar skingrades, och detta metallstycke låstes in i en gömd kista nära gränsen till Felwood.",al={"vad är iron shaft","iron shaft dartol","iron shaft raene's cleansing"}},["410ea010"]={q="Vad ska Wooden Key användas till?",a="Wooden Key öppnar den slitna, gömda kistan nära gränsen till Felwood, där en del av Dartol's Rod ligger. Nyckeln anförtroddes för länge sedan åt gläntans väktare och innehas fortfarande av de forntida treanterna, som sedan dess fallit för galenskap och pest.",al={"vad används wooden key till","wooden keys syfte","varför behövs wooden key"}},["8a6f94e5"]={q="Varför måste du strida mot treanterna om nyckeln?",a="De vissna och vansinniga forntida varelserna i nordöst, nära gränsen till Felwood, var en gång ädla skogsväktare, men demoniskt fördärv som sipprar in från norr har krossat deras sinnen. Shael'dryn sörjer deras fall, men eftersom deras natur förvridits bortom all sans kan nyckeln de vaktar bara återtas med våld.",al={"varför döda treanterna","varför är de vansinniga forntida fientliga","varför anfalla vissna forntida varelser"}}},fp="17,209,26.307.0,20.323.0,18.218.0,30.203.0,21.197.1,34.147.0,38.225.0,54.175.0"}
P.entries["quest:1027"] = {n="Raene's Cleansing",s="Det här uppdraget inleder sökandet efter den sista delen som behövs för att återställa Dartol's Rod, en forntida relik knuten till Ashenvales rening. Shael'dryn visar resande vägen till den fallna druidhelgedomen Dor'Danil för att hitta den saknade järnknoppen.",h="Det här uppdraget inleder sökandet efter den sista delen som behövs för att återställa Dartol's Rod, en...",kw={"ashenvale","dartol's rod","dor'danil","iron pommel","månbrunn","raenes rening","shael'dryn"},ang={["class:Druid"]="Ett besök på den vanhelgade marken i Dor'Danil påminner på allvar om de förluster som Cenarion Circle och kaldoreiernas druider har lidit i Ashenvale.",["faction:Alliance"]="Det är livsviktigt att skydda Ashenvale från korrumpering för att Alliansen ska behålla sitt grepp om norra Kalimdor, särskilt när hordens styrkor rycker fram från Splintertree.",["race:NightElf"]="Att återfinna Dartols arvegods hedrar både de fallna väktarna i Dor'Danil och försvaret av de forntida kaldoreiska länderna."},sec={{t="Ruinerna av Dor'Danil",b="Den sista delen av Dartol's Rod – en järnknopp – anförtroddes åt nattalvernas druider som bodde i The Dor'Danil Barrow Den. Tragiskt nog drabbades helgedomen av en katastrof och dess väktare dödades. När druiderna var döda och deras tillflykt översvämmad gick relikens exakta gömställe förlorat. Asätare och kringströvande slem tog sedan hand om allt som fanns kvar i ruinerna öster om den södra vägen."},{t="Att återupprätta Dartols arv",b="Dartol var en ond trollkarl som nu är död, men staven han skapade har förvandlande krafter. Raene Wolfrunner och Shael'dryn försöker sätta ihop artefakten igen i hopp om att den kan hjälpa till att hejda furbolgarnas angrepp på Ashenvales nattalver. Att säkra järnknoppen är det sista som krävs innan Shael'dryn kan försöka laga den trasiga staven vid månbrunnen."}},faq={{q="Vad är järnknoppen?",a="Järnknoppen är den avslutande delen av Dartol's Rod. Utan den kan reliken inte smidas om eller användas för att rena Ashenvale.",al={"iron pommel","sista stavdelen","vad är en knopp"}},{q="Vad hände med druiderna i Dor'Danil?",a="Druiderna som bodde i The Dor'Danil Barrow Den dödades nyligen när deras helgedom föll, och tillflykten lämnades åt lurande slem och bestar. Shael'dryn tycker att deras tragiska öde är smärtsamt att tala om.",al={"druiderna i dordanil","vem dödade druiderna","dor danil"}},{q="Var ligger Dor'Danil?",a="Dor'Danil ligger i södra Ashenvale, öster om huvudvägen som leder söderut mot gränsen till The Barrens och söder om Splintertree Post.",al={"var ligger dordanil","dor danils läge"}},{q="Vem är Shael'dryn?",a="Shael'dryn är en dryad som vårdar en helig månbrunn i Ashenvale. Hon hjälper Raene Wolfrunner att spåra upp de utspridda resterna av Dartol's Rod och vägleder hjältar när de ska laga den.",al={"shaeldryn","vem är shaeldryn"}},{q="Varför har slemmen svalt järnknoppen?",a="Efter att gravhögen föll invaderades området av geléaktigt slem som slukade bortkastade reliker, kistor och lik. På så vis svalde det av misstag järnknoppen tillsammans med annat bråte.",al={"slem och kista","järnknopp och slem","varför har slemmen den"}},{q="Vad händer när man hittar järnknoppen?",a="Om du återlämnar järnknoppen till Shael'dryn kan hon börja laga staven, så att den äntligen kan användas för att hjälpa Raene Wolfrunner att rena skogen.",al={"nästa steg","vad gör shaeldryn"}}},fx={["414ae6aa"]={q="Varför vill Shael'dryn att detta ska göras?",a="Shael'dryn hjälper Raene Wolfrunners försök att rena Ashenvale från fördärv. Att återta den sista delen av Dartol's Rod, Iron Pommel, är avgörande. När alla delarna återförenas kan Shael'dryn återskapa den forntida artefakten så att den återfår sin fulla kraft.",al={"varför hjälpa shael'dryn","shael'dryns motiv","varför hitta stavdelen"}}},fp="17,175,22.315.0,26.335.0,24.127.0,41.185.0,27.117.0,18.163.0,37.178.0,38.136.0"}
P.entries["quest:1028"] = {n="Raene's Cleansing",s="Det här steget i reningen av Ashenvale går ut på att ta den återuppbyggda Rod of Dartol till en avskild bergshelgedom. Den heliga källan ligger gömd bland bergskammarna sydost om Shael'dryns tillhåll och rymmer den vilande magi som behövs för att förtrolla reliken på nytt.",h="Det här steget i reningen av Ashenvale går ut på att ta den återuppbyggda Rod of Dartol till en avskild...",kw={"ashenvale","bassäng","dartol's rod","gömd helgedom","månkälla","raene's cleansing","återuppbyggd stav","shael'dryn"},ang={["class:Druid"]="Det subtila gensvar som väcks i helgedomen visar hur djupt nattalvernas forntida hantverk var förenat med naturens otämjda krafter.",["faction:Alliance"]="Att återställa reliken är ett viktigt steg mot att hjälpa Raene Wolfrunner att skydda Astranaar och läka de fördärvade markerna i norra Kalimdor.",["race:NightElf"]="Ashenvales gömda bergshelgedomar är stilla, bestående fristäder som dina förfäder vävde in i vildmarken innan invasionerna i modern tid."},sec={{t="En väg upp i höjderna",b="När Dartol's Rods krossade delar har satts samman visar dryaden Shael'dryn resenärer bort från sin månkällas och in i de otämjda sluttningarna åt sydost. Ashenvales forntida helgedomar placerades ofta medvetet högt uppe bland bergsklipporna, långt från vägen och skyddade av täta skogskronor. För att nå den stilla helgedomen måste du ta dig fram över obanad mark längs klippväggarna och följa slingrande stigar som främst Sentinels och skogseremiter känner till."},{t="Återställningen av Dartol's Rod",b="Själva helgedomen ligger i en stilla glänta omgiven av frodig skog. Även när den slumrar sjunger stenen av den vilande skyddsmagi som nattalverna från forna tider har ingjutit i den. När den återuppbyggda staven placeras i helgedomens stenbassäng vaknar platsens slumrande kraft. Den fyller gläntan med ett mjukt gensvar och genomsyrar Dartols skapelse med en ren förtrollning, så att den äntligen kan rena landet."}},faq={{q="Var ligger den gömda helgedomen?",a="Helgedomen ligger gömd i bergen sydost om Shael'dryns månkällare. I stället för att följa huvudvägarna måste du ta dig längs de klippiga bergssidorna och leta efter en slingrande stig som leder upp bland bergskammarna.",al={"helgedomens plats","var ligger helgedomen","hitta helgedomen","stigen till den gömda helgedomen"}},{q="Vem var Dartol?",a="Dartol var en avliden ond trollkarl som skapade staven. Raene hoppas att dess magi ska hjälpa till att undersöka furbolgernas attacker i Ashenvale.",al={"vem är dartol","dartols bakgrund","stavens skapare"}},{q="Varför måste Dartol's Rod placeras i helgedomen?",a="Shael'dryn kunde återuppbygga den trasiga staven rent fysiskt, men dess uråldriga förtrollningar hade tömts på kraft. Den gömda helgedomen är en orörd källa till naturmagi som kan väcka stavens kraft på nytt.",al={"varför ladda upp staven","stavens syfte","vad gör helgedomen"}},{q="Vem är Shael'dryn?",a="Shael'dryn är en dryad som bor intill en stilla månkälla i östra Ashenvale. Hon hjälper Raene Wolfrunner genom att undersöka reliker och riter som kan rena den fördärvade vildmarken.",al={"shael'dryn","uppdragsgivare","prästinna vid månkällan"}},{q="Vad händer när staven har laddats upp?",a="När helgedomen har fyllt staven med kraft är den redo att återlämnas till Shael'dryn och användas i Raenes undersökning av furbolgerna i Ashenvale.",al={"vad händer sedan","efter helgedomen","nästa steg"}},{q="Är helgedomen bevakad?",a="Själva helgedomen är en fridfull tillflyktsort, men vilddjur och fördärvade furbolgstammar stryker omkring i bergen och skogarna runt omkring och gör klättringen farlig.",al={"finns det fiender vid helgedomen","faror vid helgedomen"}}},fx={c5f164a1={q="Varför vill Shael'dryn att Dartol's Rod ska laddas upp igen?",a="Shael'dryn vill återställa Dartol's Rod så att reningen av Ashenvale kan fortsätta. Att återskapa de trasiga delarna var bara första steget. Utan att bada staven i den forntida magin vid den gömda bergshelgedomen förblir den en kraftlös relik som inte kan låsa upp sin vilande förvandlingskraft.",al={"varför ladda upp dartol's rod","shael'dryns motiv","varför vill shael'dryn få detta gjort"}},da3545ca={q="Varför skickar Shael'dryn dig till den gömda helgedomen i stället för att gå själv?",a="Shael'dryn är bunden till månbrunnen vid Iris Lake, där hon vakar över dess heliga vatten och hjälper Astranaars försvarare. Du har redan visat ditt mod genom att återta Dartol's Rods utspridda delar i Ashenvale. Därför litar hon på att du tar dig fram längs de otämjda bergsstigarna och hittar den bortglömda helgedomen.",al={"varför går inte shael'dryn själv","varför skicka mig till helgedomen","varför jag åt shael'dryn"}}},fp="17,178,23.335.0,22.303.0,35.167.0,15.140.0,54.162.0,18.173.0,40.132.0,22.151.0"}
P.entries["quest:1029"] = {n="Raene's Cleansing",s="Det här steget i den långvariga utredningen i Ashenvale innebär att Dartol's Rod of Transformation återställs helt. Med det färdigställda föremålet i din vård, anförtrott av dryaden Shael'dryn, återvänder du till Raene Wolfrunner i Astranaar för att rapportera framgången och hedra minnet av den fallne spejaren Teronis.",h="Det här steget i den långvariga utredningen i Ashenvale innebär att Dartol's Rod of Transformation återställs...",kw={"ashenvale","astranaar","dartol's rod","raene wolfrunner","raene's cleansing","shael'dryn","teronis"},ang={["faction:Alliance"]="Astranaar är Alliansens fäste i Ashenvale. När du hjälper Raene Wolfrunner stärker du din ställning direkt bland de tillbakadragna sentinelerna.",["race:NightElf"]="Teronis arv ger Astranaar ett avslut och visar att fallna fränder inte glöms bort, trots de växande hoten mot Kalimdors heliga lundar."},sec={{t="Staven återställd",b="Efter att ha genomsökt Ashenvales fördärvade trakter efter beståndsdelar och forntida ädelstensfragment har reliken Dartol's Rod of Transformation äntligen smitts om. Dryaden Shael'dryn anförtrodde dig den nära Iris Lake, där dess magiska krafter renades och förnyades. När arbetet är klart skickar hon dig tillbaka genom skogsstigarna till Astranaar, så att du kan överlämna föremålet till Raene Wolfrunner."},{t="Till Teronis minne",b="Allt började med en expedition under Teronis ledning. Han var en mångårig vän till Raene och sökte efter Dartol's stav i hopp om att hejda furbolgernas attacker mot sitt folk. Teronis hittades död på ön i Lake Falathim, nedgjord av murlocer som hade tagit ädelstenen han sökte, innan han hann slutföra sitt uppdrag. När du återlämnar den återställda staven till Raene Wolfrunner blir det en bitterljuv seger som ser till att hans farliga uppoffring inte var förgäves."}},faq={{q="Vad är Dartol's Rod of Transformation?",a="Det är den magiska stav som skapades av Dartol, en avliden ond trollkarl. När den har återställts kan den hjälpa Raene att utreda furbolgernas attacker i Ashenvale.",al={"dartols stav","vad gör staven"}},{q="Vem var Teronis?",a="Teronis var en ung nattalvssentinel som Raene Wolfrunner gett i uppdrag att hitta beståndsdelar av forntida magi i Ashenvale. Han hittades död på ön i Lake Falathim, nedgjord av murlocer som hade tagit ädelstenen han sökte. Därmed överlämnades slutförandet av hans viktiga uppdrag till förbipasserande resenärer från Alliansen.",al={"vem är teronis","teronis död"}},{q="Vem är Raene Wolfrunner?",a="Raene Wolfrunner är en erfaren befälhavare bland nattalvssentinelerna, stationerad mitt i Astranaar. Hon leder försvaret av centrala Ashenvale mot invaderande demonisk smitta, fientliga satyrer och fördärv bland traktens bestar.",al={"raene","raene wolfrunner"}},{q="Vem är Shael'dryn?",a="Shael'dryn är en dryad som lever stillsamt nära månkällan öster om Iris Lake. Hennes djupa kunskap om skogen och dess forntida reliker gör att hon kan rena fördärvade reliker och återställa uråldriga kraftföremål.",al={"shaeldryn","iris lake prästinna"}},{q="Var utspelar sig uppdraget?",a="Det här ärendet tar dig från Iris Lakes stillsamma stränder i centrala Ashenvale västerut längs huvudstigarna till Astranaar, områdets främsta nav för Alliansen.",al={"uppdragsplats","vart ska jag gå"}},{q="Vad händer när staven överlämnats till Raene?",a="Raene uttrycker stor lättnad och stolthet över att Teronis sista uppdrag lyckades. Men reningen av Ashenvale är långt ifrån över, och hon söker genast sätt att använda stavens kraft mot skogens ihållande fördärv.",al={"nästa uppdrag","fortsättning på raenes rening"}}},fx={f5799a7d={q="Varför vill Shael'dryn att du tar staven till Raene?",a="Nu när Dartol's Rod of Transformation äntligen återställts vet Shael'dryn att hennes del i förberedelserna är klar. Raene Wolfrunner leder väktarna i Astranaar och gav ursprungligen Teronis i uppdrag att undersöka det hemska fördärv som plågar Ashenvale. Shael'dryn skickar dig tillbaka till Raene, så att nattalvernas ledare kan använda den färdiga reliken och avgöra hur Teronis oavslutade uppdrag bäst ska fortsätta.",al={"varför ta staven till raene","shael'dryns motiv","varför träffa raene wolfrunner"}}},fp="17,191,16.304.0,16.358.1,39.170.0,16.257.0,24.203.0,18.188.0,33.133.0,47.188.1"}
P.entries["quest:103"] = {n="Keeper of the Flame",s="Vid Westfall Lighthouse håller Captain Grayson vakt över kusten. Den vålnadslika sjömannen söker olja så att fyren kan fortsätta lysa efter att murlocs dödat dess levande fyrvaktare, så att skepp kan passera reven säkert.",h="Vid Westfall Lighthouse håller Captain Grayson vakt över kusten.",kw={"fyr","captain grayson","oljeflaska","great sea","skördemonstren","old murk-eye","westfall lighthouse"},ang={["faction:Alliance"]="Fyren i Westfall hjälper till att hindra handelsfartyg och örlogsfartyg på väg till Stormwind Harbor från att gå på grund längs kungarikets sönderfallande kust.",["profession:Engineering"]="Harvest Watchers som strövar omkring på Westfalls gårdar bär på flyktiga maskinv ätskor som kan användas som bränsle i en lykta."},sec={{t="En vålnads plikt",b="Westfall Lighthouse står på en klippig holme utanför zonens sydvästra kust, där dess ljus en gång vägledde sjömän genom Great Seas grunda vatten. Den uppgiften tog slut när Old Murk-Eye ledde ett murlocangrepp och dödade fyrvaktaren och hans familj. Captain Grayson, en sjöman som dog i vattnen vid klipporna, vakar nu över tornet som ett spöke. Döden gjorde honom oförmögen att stoppa massakern, men han tänker inte låta fyren slockna."},{t="Fyren får bränsle",b="Ingen levande fyrvaktare finns kvar som kan sköta lågan, så Captain Grayson behöver ett ovanligt bränsle. De listiga Harvest Watchers som strövar omkring på Westfalls övergivna jordbruk bär på flaskor med maskinolja i sina rostiga kroppar. Grayson skickar dig i land för att hämta oljan från dessa trasiga konstruktioner. Med den kan fyren fortsätta lysa och vägleda andra kaptener förbi reven."}},faq={{q="Vem är Captain Grayson?",a="Captain Grayson är vålnaden efter en sjöman som förliste och dog vid Westfalls farliga kust. Han vakar över Westfall Lighthouse för att hjälpa levande sjömän att undvika samma öde.",al={"captain grayson","fyrspöke","vem är spöket vid westfall lighthouse"}},{q="Vad hände med de ursprungliga fyrvaktarna?",a="Old Murk-Eye ledde murlocangreppet som dödade fyrvaktaren och hans familj. Som spöke såg Captain Grayson hjälplöst på när de massakrerades.",al={"vad hände med fyrvaktaren","vem dödade fyrvaktaren","fyrvaktarens familj död"}},{q="Varifrån kommer oljan till fyrens låga?",a="Oljan kommer från de mekaniska Harvest Watchers som strövar omkring på Westfalls övergivna gårdar och fält.",al={"var hittar man olja","olja från skördemonster","oljeflaska"}},{q="Varför bryr sig Grayson om att hålla fyren tänd?",a="Grayson vill att fyren ska vägleda sjömän över Great Sea och förbi kustens klippor. Han dog vid de reven och vakar nu över fyren.",al={"varför tända facklan","graysons motiv","fyrens syfte"}},{q="Vem är Old Murk-Eye?",a="Old Murk-Eye är en ökänd murloc som stryker längs Westfalls kust och leder angrepp mot bosättningar vid stranden. Hans plundrare dödade fyrvaktaren och hans familj.",al={"old murk-eye","murk eye","murlocledare i westfall"}},{q="Var ligger Westfall Lighthouse?",a="Westfall Lighthouse står på en klippig holme utanför Westfalls sydvästra kust. Du kan nå den genom att simma genom det grunda kustvattnet.",al={"fyrens plats","var ligger westfall lighthouse","hitta fyren"}}},fx={["44c879dd"]={q="Varför är Harvest Monsters källan till fyrens olja?",a="De mekaniska Harvest Monsters som strövar omkring på Westfalls övergivna åkrar drivs av dunkar med tjock maskinolja. Fyrvaktarens familj är död och de vanliga leveransvägarna har brutits. Därför måste Captain Grayson förlita sig på bränsle som kan bärgas från dessa förrymda automater för att hålla fyrens signalljus brinnande.",al={"harvest monsters olja","varför harvest-golemers olja","harvest monsters mål"}},cbe3424a={q="Varför behöver Captain Grayson din hjälp i stället för att samla in oljan själv?",a="Captain Grayson är en rastlös vålnad som är bunden till området närmast Westfall Lighthouse. Hans ande kan inte ta sig inåt landet för att själv jaga de felande Harvest Monsters, så han måste förlita sig på äventyrare på genomresa som kan bege sig ut på åkrarna och samla in bränslet som behövs för att hålla fyren igång.",al={"varför behöver grayson mig","varför kan inte grayson hämta olja","varför jag åt grayson"}}},fp="19,185,15.419.0,18.348.0,23.190.0,49.131.0,54.98.0,51.150.0,20.161.0,41.145.0"}
P.entries["quest:1030"] = {n="Raene's Cleansing",s="Det här avgörande skedet i Raene Wolfrunners uppdrag kräver att du använder Dartol's Rod of Transformation, som nyligen återställts, för att förklä en främling och ta kontakt med en okorrumperad furbolg. Sydost om Mystral Lake ger en utstött vid namn Krolg en sällsynt inblick i de överlevande furbolgernas djupa bitterhet mot Night Elf.",h="Det här avgörande skedet i Raene Wolfrunners uppdrag kräver att du använder Dartol's Rod of Transformation...",kw={"ashenvale","dartol's rod of transformation","fel moss","furbolg","krolg","mystral lake","raene wolfrunner","raenes rening"},ang={["class:Druid"]="Druider som försöker återställa skogens balans möter furbolgernas råa tragedi. De stod en gång naturen nära som allierade, men lider nu av fruktansvärt vansinne från kvardröjande demonisk smuts.",["faction:Alliance"]="Astranaars överlevnad hänger på att hoten längs gränsvägarna avslöjas. Därför är detta hemliga möte avgörande för att säkra östra Ashenvale.",["race:NightElf"]="Krolgs ord påminner allvarligt om att många av Ashenvales ursprungliga invånare inte ser Kaldorei som välvilliga väktare, utan som de vårdslösa upphovsmännen till landets återkommande undergång."},sec={{t="En päls- och klobeklädnad",b="När Dartol's Rod of Transformation har återställts misstänker Raene Wolfrunner att den avlidne Night Elf ville förklä sig för att kunna närma sig furbolgerna utan fara. Skogarna i Ashenvale har blivit farliga, och vansinnet som sprider sig bland stammarna gör direkt diplomati omöjlig. Med hjälp av den magiska reliken antar en äventyrare en furbolgs utseende i hopp om att ta sig förbi deras instinktiva revirilska och hitta någon som vill tala."},{t="Den landsförvisades bitterhet",b="Sydost om Mystral Lake finns Krolg, en isolerad furbolg som har lyckats undgå Fel Moss korrumperande inverkan. I tron att han talar med en ren medlem av sitt eget folk berättar Krolg öppet om sin landsförvisning och djupa sorg. Men han ser inte Night Elf som allierade eller beskyddare. I stället hyser han stor bitterhet mot dem och skyller öppet på Night Elf-högmod och forntida misslyckanden för den demoniska smitta som härjar bland hans folk."}},faq={{q="Vad gör Dartol's Rod of Transformation?",a="Dartol's Rod of Transformation förändrar tillfälligt bärarens utseende till en furbolgs. Förklädnaden låter en äventyrare röra sig bland okorrumperade furbolger utan att utlösa en omedelbar våldsam attack.",al={"vad gör staven","dartols förvandlingsstav","furbolgförklädnad med stav"}},{q="Vem är Krolg?",a="Krolg är en okorrumperad furbolg som lever i landsförvisning sydost om Mystral Lake. Han har undgått Fel Moss, som infekterat hans folk, och lever ensam på andra sidan en bäck kantad av facklor. Han sörjer sin stams förlust och hyser samtidigt ett djupt agg mot Night Elf-folket.",al={"vem är krolg","okorrumperad furbolg vid mystral lake","furbolg sydost om mystral lake"}},{q="Varför anfaller Krolg om du inte använder staven?",a="Krolg är skräckslagen och misstror främlingar djupt, särskilt Night Elf, som han skyller på för sitt folks undergång. Utan illusionen som får dig att se ut som en okorrumperad furbolg betraktar han dig som en inkräktare och försvarar sitt läger våldsamt.",al={"varför anfaller krolg","krolg aggressiv","varför använda staven på krolg"}},{q="Varför skyller Krolg på Night Elf för korrumperingen?",a="Krolg ser skogens demoniska korrumpering, som orsakats av Legion-invasionerna och historisk magisk inblandning, som en direkt följd av Night Elf-folkets högmod. I hans ögon drog de forntida Kaldorei olycka över Kalimdor och lämnade de ursprungliga stammarna att lida följderna.",al={"varför hatar krolg night elf","furbolger skyller på night elf","krolgs hat mot night elf"}},{q="Var hittar du Krolg?",a="Han finns sydost om Mystral Lake i Ashenvale. Följ en slingrande jordstig markerad med brinnande facklor. Den leder ned över en liten bäck till hans ensliga läger.",al={"var finns krolg","krolgs plats","hitta okorrumperad furbolg"}},{q="Vad är Fel Moss, och hur påverkade det furbolgerna?",a="Fel Moss är en demonisk växtlighet som sprider sig genom Ashenvale och låter demonisk smitta tränga in i jorden och floran. De lokala furbolgstammarna föll offer för dess inflytande, vilket drev dem in i ett tillstånd av ursinnigt, våldsamt vansinne och splittrade deras samhälle.",al={"vad är fel moss","fel moss och furbolger","varför blev furbolgerna vansinniga"}}},fx={b9c958d0={q="Varför vill Raene Wolfrunner att du ska hitta en ofördärvad furbolg?",a="Raene hoppas att den återställda staven låter dig närma dig en ofördärvad furbolg och få veta mer om hans stams svåra situation. Hon skickar dig mot länderna sydöst om Mystral Lake för att fortsätta undersökningen.",al={"varför hitta en ofördärvad furbolg","raene wolfrunners motiv","varför behöver raene detta"}}},fp="17,199,23.378.0,22.305.1,44.166.0,13.220.0,47.193.0,56.201.0,25.152.0,52.178.0"}
P.entries["quest:1031"] = {n="The Branch of Cenarius",s="Efter en desperat vädjan från den döende dryaden Anilia får en äventyrare i uppdrag att återta en helig relik som stulits av den usle satyren Geltharis. Att återta Branch of Cenarius innebär att konfrontera de demonbundna fördärvarna i östra Ashenvale och återlämna den dyrbara grenen till dryaden Illiyana.",h="Efter en desperat vädjan från den döende dryaden Anilia får en äventyrare i uppdrag att återta en helig relik...",kw={"anilia","ashenvales dryader","branch of cenarius","geltharis","illiyana","night run","satyr"},ang={["class:Druid"]="Cenarius lärde de första dödliga druiderna, vilket gör hans reliker djupt heliga. Att återta hans gren från en demonbesudlad satyr är en andlig plikt.",["faction:Alliance"]="Ashenvales dryader förlitar sig på hjälp från Alliansen för att slå tillbaka demoniska hot i Ashenvales otämjda östra delar.",["race:NightElf"]="Cenarius döttrar är älskade allierade till Kaldorei. Hämnas Anilia och rensa era förfäders skogar från satyravskummet som vanhelgar dem."},sec={{t="En döendes begäran",b="Alliansresenärer skickas till östra Ashenvales fördärvade trakter för att söka efter försvunna dryader och finner Anilia på livets yttersta rand. Med sina sista andetag pekar Cenarius sårade dotter mot satyrruinerna i norr. Flämtande nämner hon satyren som tagit den, Geltharis, och ber med sina sinande krafter att Branch of Cenarius ska återtas innan hon ger efter för sina sår."},{t="Fördärv i ruinerna",b="Tjuven Geltharis är en usel satyr som håller till bland de uråldriga alvruinerna i Xavian. För satyren är uråldriga reliker knutna till halvguden Cenarius dyrbara troféer, redo att skändas och hånas demoniskt. Att besegra Geltharis och slita grenen ur hans klor är inte bara en rättvis handling för Anilia, utan också ett försvar mot den spridande smitta som den brinnande legionens uråldriga tjänare sprider bland Ashenvales heliga växter."},{t="Sorg bland dryaderna",b="När grenen återlämnas till dryaden Illiyana får sökandet ett bitterljuvt slut. Den heliga reliken räddas från demonisk förvanskning, men beskedet om Anilias död blir ett hårt slag för hennes överlevande fränder. Ashenvales dryader, som en gång fritt lekte under de uråldriga grenarna, tvingas möta krigets hårda verklighet och det annalkande fördärvet."}},faq={{q="Vad är Branch of Cenarius?",a="Det är en helig naturrelik knuten till skogsherren Cenarius, högt älskad av hans dryaddöttrar. Satyrierna hade tagit den, och Anilia blev dödligt sårad när hon ledde sina systrar för att återta den. Med sitt sista andetag namngav hon Geltharis som den som har den.",al={"branch of cenarius-relik","vad är grenen","cenarius gren"}},{q="Vem dödade Anilia?",a="Anilia blev dödligt sårad i de satyrkontrollerade ruinerna i Xavian när hon försökte återta Branch of Cenarius. Med sitt sista andetag namngav hon satyren Geltharis som den som hade tagit den.",al={"anilias mördare","vem angrep anilia","vem dödade dryaden"}},{q="Var finns Geltharis?",a="Geltharis kan hittas lurande under stenvalven och bland de fördärvade byggnaderna i Xavianruinerna, norr om platsen där Anilia låg döende.",al={"geltharis plats","hitta geltharis","var dödar man geltharis"}},{q="Vart ska jag ta Branch of Cenarius när den har återtagits?",a="Du måste ta den återtagna grenen till dryaden Illiyana, som väntar vid The Shrine of Aessina i Ashenvale.",al={"lämna in branch of cenarius","illiyanias plats","vem får grenen"}},{q="Varför vill satyrierna ha Cenarius artefakter?",a="Satyrier är uråldriga nattalver som förvandlats genom demoniska pakter och hyser ett djupt hat mot naturen och halvguden Cenarius. Att fördärva eller stjäla heliga reliker tjänar både deras demoniska herrar och deras agg mot sina forna fränder.",al={"satyrernas motiv","varför stjäla cenarius gren","varför tog geltharis den"}},{q="Vad var Anilia för Illiyana?",a="De var nära dryadvänner och systrar i anden, som i oräkneliga dagar hade sprungit och lekt fritt i Ashenvales vildmarker innan det växande hotet från fördärvet tog Anilias liv.",al={"anilia och illiyana","är dryaderna systrar"}}},fx={["4863107a"]={q="Varför vill Anilia att Branch of Cenarius ska återtas?",a="Med sitt sista andetag önskar Anilia bara att hennes fars heliga relik inte ska förbli i de vidriga satyrernas händer. Hon anförtror dig att återta den, så att Branch of Cenarius kan återlämnas tryggt till hennes dryadsystrar i stället för att skändas.",al={"anilias motiv","varför återta grenen","anilias sista önskan"}},["9fd6df2e"]={q="Vem är Geltharis och varför skickas du efter honom?",a="Geltharis är satyren som överföll Anilia och stal Branch of Cenarius. Han håller till bland de forntida ruinerna i norr och har tagit den heliga reliken från den döende dryaden.",al={"vem är geltharis","varför döda geltharis","geltharis historia"}},["59d5db2f"]={q="Varför behöver Anilia att du hämtar grenen?",a="Anilia kan inte själv hämta artefakten eftersom hennes sår är dödliga. När hon drar dig intill sig för att viska sina sista ord tar hon sitt sista andetag. Du är den enda på plats och kan därför hämnas henne och uppfylla hennes sista önskan.",al={"varför jag för branch of cenarius","varför behöver anilia hjälp"}}},fp="22,154,15.265.0,23.325.0,23.245.1,31.279.0,18.177.0,27.69.0,60.76.0,44.203.0,27.187.0"}
P.entries["quest:1032"] = {n="Satyr Slaying!",s="Dryaden Illiyana sörjer sin syster Anilia och söker hämnd på satyrerna som lurar i Ashenvale. Hon ber Alliansens hjältar att tunna ut de korrumperade varelserna och återvända med deras horn som bevis på att de har besegrats.",h="Dryaden Illiyana sörjer sin syster Anilia och söker hämnd på satyrerna som lurar i Ashenvale.",kw={"anilia","ashenvale","dryad","illiyana","satyr","satyr horns","satyrjakt"},ang={["class:Druid"]="Att hämnas en fallen dryad och skära av hornen på demoniska satyrer går direkt till angrepp mot den korrumpering som förgiftar Cenarius favoritvildmark.",["faction:Alliance"]="Om satyrerna blir färre får Alliansens styrkor i Ashenvale en tryggare skog, trots de vilda hot som omger dem.",["race:NightElf"]="Satyrerna är en kvarvarande, skamlig påminnelse om hur Highborne en gång sjönk ner i ondskans tjänst. När du hjälper Illiyana renar du landet från denna arvsbörda."},sec={{t="En dryads sorg",b="Dryader är vanligtvis lekfulla och fridfulla skogsandar, djupt knutna till naturen och svåra för dödliga att få syn på. När Anilia brutalt dödas bryts denna frid för Illiyana, som bor vid The Shrine of Aessina. Sorgen får henne att lämna sin sorglösa natur bakom sig, och hon vänder sig till Alliansens resenärer för att slå ner de demoniska odjur som bär skulden."},{t="Det korrumperade släktet",b="Satyrer är en mörk, förvriden gren av de forna Night Elves förfäder, oåterkalleligt besudlade av demonisk energi under De uråldrigas krig. Dessa avskyvärda tjänare till Burning Legion lurar i vanhelgade lundar runt om i Ashenvale och jagar aktivt skogens invånare. Deras horn blir inte bara ett bevis på hämnden, utan utdelar också ett direkt slag mot den onda närvaro som breder ut sig i östra Ashenvale."}},faq={{q="Vem är Illiyana?",a="Illiyana är en dryad som bor vid The Shrine of Aessina i Ashenvale. Hon är känd för sitt milda sinnelag och sörjer sin syster Anilias tragiska död. De lokala satyrerna dödade Anilia.",al={"illiyana-bakgrund","vem ger uppdraget","forest song-dryad"}},{q="Vem var Anilia?",a="Anilia var en dryad och Illiyanas älskade syster. De lekte genom Ashenvales uråldriga trädkronor i evigheter, tills satyrerna som strök omkring i trakten överföll och dödade Anilia.",al={"anilia","illiyanas syster","vem dog"}},{q="Varför ber Illiyana om satyrhorn?",a="Satyrhornen är ett obestridligt, konkret bevis på att de korrumperade odjur som mördade Anilia har dödats, så att hennes systers ande kan få frid.",al={"varför satyrhorn","satyrhorn som bevis"}},{q="Vad är satyrer?",a="Satyrer är forna Night Elves som förbannades och förvandlades av Burning Legions demoniska krafter under De uråldrigas krig. De håller till i korrumperade enklaver och försöker sprida besmittelse och förgöra skogens naturliga andar.",al={"satyrernas bakgrund","vad är satyrerna i ashenvale"}},{q="Var ligger Forest Song?",a="Forest Song är en uråldrig, nästan övergiven ruin efter Night Elves, längst österut i Ashenvale och nära gränsen till Azshara. Illiyana bor inte där; hon väntar vid The Shrine of Aessina.",al={"forest songs plats","var ligger forest song"}},{q="Har detta samband med andra jakter?",a="Illiyana tar fortfarande emot satyrhorn även efter att hennes syster har hämnats. Det visar att Ashenvales försvarare fortsätter sitt försök att rensa Ashenvale från satyrhotet.",al={"uppdrag med satyrhorn","uppföljningsuppdrag","upprepningsbart satyruppdrag"}}},fx={f313c3da={q="Varför vill Illiyana att satyrerna dödas?",a="Illiyana sörjer sin syster Anilia, som tillfångatogs och dödades av de vidriga satyrerna som lurar i Ashenvale. Förlusten av hennes älskade barndomsvän har krossat henne, och hon söker tröst i hämnden. Att döda varelserna som bär ansvaret och se deras avhuggna horn ger henne en dyster känsla av frid och hedrar hennes fallna systers minne.",al={"varför döda satyrer","illiyanas motiv","varför vill illiyana ha hämnd"}},["45b4e644"]={q="Varför finns satyrerna i Ashenvale?",a="Satyrer är förvridna nattalver som föll för demoniskt fördärv under De forntida kriget och förbannades till bestlika odjur i den brinnande legionens tjänst. Fickor av dessa odödliga fasor dröjer sig kvar i Ashenvales mörka, fördärvade vrår, som Xavian och Night Run. De smider ständigt planer på att hemsöka de heliga skogarna och slakta alla kaldorei de överrumplar.",al={"varför är satyrerna här","satyrer i ashenvale","vad gör satyrerna här"}}},fp="14,193,15.309.0,17.331.0,16.147.0,15.141.0,38.145.0,16.196.0,21.173.0,37.142.0"}
P.entries["quest:1033"] = {n="Elune's Tear",s="Pelturas Whitemoons unga dotter Relara är fortfarande drabbad av en hemsk och obeveklig sjukdom. Inte ens örtmedicinerna från de norra ruinerna hjälper. I sin desperation efter ett starkare botemedel skickar Pelturas en äventyrare till Iris Lake för att hämta Elune's Tear, en helig mineral som Night Elf vördar för dess kraft att rena allt fördärv.",h="Pelturas Whitemoons unga dotter Relara är fortfarande drabbad av en hemsk och obeveklig sjukdom.",kw={"ashenvale","astranaar","botemedel","elune","elune's tear","iris lake","orendil broadleaf","pelturas whitemoon","relara","vattenelementaler"},ang={["class:Druid"]="Druider förstår både den känsliga balansen i Ashenvales vatten och förekomsten av nyckfulla vattenelementaler som vaktar det orörda hjärtat av Iris Lake.",["class:Priest"]="Präster som viger sig åt Elune känner igen det djupa andliga beroendet av heliga reliker i kampen mot mörka, onaturliga farsoter när bönen ensam behöver en fysisk katalysator.",["faction:Alliance"]="Att hjälpa Astranaars försvarare med personliga kriser stärker Alliansens sammanhållning i Ashenvale medan farorna i regionen växer.",["race:NightElf"]="För kaldorei visar bruket av heliga stenar uppkallade efter Mångudinnan deras absoluta tro på att Elunes nåd kan rena sår som vanliga botemedel inte rår på."},sec={{t="En fars växande oro",b="Relara Whitemoon ligger sängbunden i Astranaar och tynar bort av en våldsam sjukdom med okänt ursprung. Pelturas hade satt sitt hopp till en alkemisk brygd som apotekaren Orendil Broadleaf tillredde av Bathran's Hair. Brygden lyckades hejda sjukdomens snabba förlopp, men renade inte hennes kropp helt. När han inser att vanlig läkande magi och vilda örter inte räcker till vänder sig Pelturas till sitt folks uråldriga traditioner och ber om hjälp att få tag på botemedel fyllda av gudomligt renande ljus."},{t="Stenen från Iris Lake",b="Innan de skildes åt berättade Orendil om mörkare försiktighetsåtgärder för Pelturas och nämnde legendariska botemedel ifall örtblandningen inte skulle räcka. Främst bland dem står Elune's Tear, en lysande, helig sten som bara finns på en ö i Iris Lake, öster om Astranaar. Stenen anses bära Mångudinnans välsignelse och sägs kunna rena levande kött från djupt rotat fördärv. Att hämta den är ingen stillsam pilgrimsfärd, för oroliga vattenelementaler patrullerar sjöns grunda vatten och stränder och vaktar dess orörda hjärta med våldsam beslutsamhet."},{t="Ett mått av hopp",b="När stenen förs säkert tillbaka till Astranaar tänker Pelturas låta den dra i en läkande buljong som han ska ge sin sjuka dotter. Men även när han uttrycker sin desperata tacksamhet tyder det långlivade fördärvet på att prövningen kan kräva ännu mer sällsynta ingredienser innan barnets liv verkligen är utom fara."}},faq={{q="Vad är Elune's Tear?",a="Elune's Tear är en sällsynt, invigd sten som upptäckts på den centrala ön i Iris Lake i Ashenvale. Enligt Night Elf-lärdomar har mineralen kraftfulla renande och läkande egenskaper och kan tvätta bort svåra gifter och kvarvarande fördärv.",al={"vad är elune's tear","elune's tear föremål","stenen från iris lake"}},{q="Varför misslyckades Orendils tidigare botemedel?",a="Brygden som Orendil Broadleaf tillredde av växten Bathran's Hair bromsade sjukdomens förlopp, men kunde inte övervinna den våldsamma sjukdom som drabbat Relara. Hennes far Pelturas insåg att vanliga örtmediciner inte räckte, och började därför söka efter botemedel välsignade av andliga krafter.",al={"varför misslyckades orendils botemedel","fungerade orendils botemedel","är relara fortfarande sjuk"}},{q="Var ligger Iris Lake?",a="Iris Lake ligger öster om Astranaar i Ashenvale. Resenärer kan ta sig dit genom att följa huvudvägen österut från staden och sedan följa en grusväg norrut längs en bäck som rinner ner i sjöbäckenet.",al={"var ligger iris lake","iris lakes läge","hur hittar man iris lake"}},{q="Vilka faror lurar kring Iris Lake?",a="Iris Lakes vatten och centrala ö bebos av revirhävdande vattenelementaler. Den som försöker nå ön för att hämta stenen måste ta sig förbi dessa fientliga naturandar.",al={"fiender vid iris lake","vad anfaller vid iris lake"}},{q="Hur tänker Pelturas använda stenen?",a="Pelturas tänker låta Elune's Tear dra i en läkande gryta och förlitar sig på den heliga mineralens omtalade renande egenskaper för att dra ut det mörka gissel som förtär hans dotter Relara.",al={"hur använder man elune's tear","elune's tear gryta"}},{q="Vem är Relara Whitemoon?",a="Relara är den unga Night Elf-dottern till Pelturas Whitemoon och bor i Astranaar. Hon har drabbats av ett allvarligt, onaturligt fördärv som hotar hennes liv.",al={"vem är relara","pelturas dotter"}}},fx={["58c1c268"]={q="Varför vill Pelturas Whitemoon att detta ska göras?",a="Pelturas är desperat och vill rädda sin sjuka dotter Relara. Orendil Broadleafs första botemedel lyckades bara bromsa det lömska fördärv som härjar i hennes kropp, inte driva ut det. Tiden håller på att rinna ut, och Pelturas sätter sitt hopp till Elune's Tears legendariska läkande krafter för att rena sjukdomen innan den tar hennes liv.",al={"varför vill pelturas ha elune's tear","pelturas motiv","varför hjälpa pelturas"}}},fp="12,266,24.374.0,22.345.0,17.181.1,21.161.0,37.169.0,27.152.0,35.154.0,40.139.0,24.172.0"}
P.entries["quest:1034"] = {n="The Ruins of Stardust",s="Pelturas Whitemoons desperata försök att bota sin dotter Relara fortsätter i Astranaar. Den heliga stenen Elune's Tear stillade hennes fruktansvärda mardrömmar, men en våldsam feber plågar henne fortfarande. Med vägledning från Orendil Broadleafs botaniska kunskaper beger sig äventyrare söderut för att samla svalkande, självlysande stoft som lagt sig bland uråldriga Night Elf-stenar.",h="Pelturas Whitemoons desperata försök att bota sin dotter Relara fortsätter i Astranaar.",kw={"ashenvale","astranaar","bota","elune","feber","orendil","pelturas","omslag","relara","stjärnstoft"},ang={["class:Druid"]="För att samla det lindrande stjärnstoftet måste man hantera de upprörda vattenandarna i de översvämmade ruinerna, en tydlig påminnelse om Ashenvales bräckliga ekologiska balans.",["class:Priest"]="Elunes nåd lindrade Relaras mardrömmar, men den fysiska kroppen behöver ofta jordiska kurer vid sidan av gudomlig bön för att livet ska kunna bevaras.",["profession:Herbalism"]="Insamlingen av skimrande pulver från snåren visar vilken specialkunskap som krävs för att identifiera sällsynta botaniska fenomen i Ashenvales fuktiga mikroklimat.",["race:NightElf"]="Ruinerna söder om Astranaar är lämningar efter den uråldriga kaldoreicivilisationen och påminner Night Elfs om att magin som dröjer kvar i stenarna fortfarande kan användas för att hela."},sec={{t="En fars kvarvarande förtvivlan",b="Pelturas Whitemoon har tillbringat sömnlösa nätter vid sin dotter Relaras bädd och sett en elakartad sjukdom härja i henne. En Elune's Tear gav tillfällig lindring från de plågsamma drömmar som hemsökte hennes tankar, men sjukdomen sitter fortfarande djupt. Hennes kropp skakas av en intensiv feber som vanliga läkemedel inte har lyckats dämpa. När templets helare nått gränsen för sin förmåga vänder sig Pelturas åter till uråldriga, naturpräglade kurer för att rädda sin dotters liv."},{t="Stoftets skimmer",b="På den äldre örtakunnige Orendil Broadleafs inrådan riktar Pelturas blicken mot The Ruins of Stardust, söder om Astranaar på andra sidan floden. De fallna marmorpelarna och valvbågarna i denna uråldriga kaldoreihelgedom hyser ett märkligt fenomen: ett frostigt, skimrande ämne som lägger sig över växtligheten i trakten. Denna pulverformiga kondens, i folkmun kallad stjärnstoft, har naturligt svalkande egenskaper som är starka nog att dra ut onormal hetta. Pelturas tänker mala det insamlade stoftet till ett läkande omslag och hoppas att dess rogivande kyla äntligen ska bryta Relaras brännande feber."},{t="Rovdjur i vattnet",b="Det är farligt att samla det frostiga stoftet, eftersom väktare och vilda djur håller till bland de översvämmade, sjunkna stenarna. Vattenelementarer, fördärvade eller upprörda av förändringar i Ashenvales balans, väller fram runt de sjunkna torgen där buskarna växer som tätast. Samlarna måste vada ut i de till synes stilla vattnen och vara beredda på plötsliga bakhåll från de grumliga djupen. De söker igenom de skimrande buskarna efter tillräckligt med rent stoft innan de skyndar tillbaka till Astranaar."}},faq={{q="Varför behöver Pelturas stjärnstoft?",a="Pelturas Whitemoons dotter Relara håller på att dö av en svår magisk eller fördärvad feber i Astranaar. Elune's Tear lindrade hennes mörka mardrömmar, men febern rasar fortfarande okontrollerat. Den äldre örtakunnige Orendil berättade att det frostiga stoft som samlas i The Ruins of Stardust har starkt svalkande egenskaper och kan blandas till ett lindrande omslag.",al={"varför stjärnstoft","syftet med the ruins of stardust","botemedel mot relaras feber"}},{q="Var ligger The Ruins of Stardust?",a="The Ruins of Stardust ligger rakt söder om Astranaar i centrala Ashenvale, runt en liten sjö och omgivna av uråldriga, igenvuxna kaldoreistenbyggnader.",al={"the ruins of stardusts plats","var ligger the ruins of stardust","hitta ruinerna med stjärnstoft"}},{q="Vad är stjärnstoft i det här sammanhanget?",a="Pelturas hoppas kunna använda det svalkande, frostiga stoftet från växtligheten vid sjön i ett omslag som sänker hans dotters feber.",al={"vad är stjärnstoft","stjärnstoftets natur","stjärnstoftets historia"}},{q="Botar stjärnstoftet Relara helt?",a="Pelturas hoppas att ett omslag av stjärnstoft ska sänka Relaras feber. Om det återställer all hennes styrka får man veta efter behandlingen.",al={"botar stjärnstoft relara","relara botad","räddas flickan"}},{q="Vilka hot finns vid The Ruins of Stardust?",a="De översvämmade ruinerna är hem åt aggressiva vattenelementarer som lurar under ytan och försvarar de stilla vattnen. De utgör en fara för alla som vadar genom det grunda vattnet för att undersöka de skimrande buskarna.",al={"fiender i the ruins of stardust","vad anfaller vid the ruins of stardust"}},{q="Vem är Orendil?",a="Orendil Broadleaf är en kunnig Night Elf-örtakunnig som bor i norra Ashenvale nära Maestra's Post. Han har studerat traktens unika växter i århundraden och ger Pelturas råd om sällsynta botaniska behandlingar när templets vanliga kurer inte räcker till.",al={"vem berättade för pelturas om stjärnstoft","orendil broadleaf"}}},fp="21,230,28.372.0,21.410.0,22.390.0,32.231.0,40.130.0,33.145.0,41.130.1,48.178.0,15.227.0"}
P.entries["quest:1035"] = {n="Fallen Sky Lake",s="\"Fallen Sky Lake\" är den känslomässiga höjdpunkten i Pelturas Whitemoons uppdragskedja för att rädda sin döende dotter Relara i Astranaar. Hennes feber har gått ner, men hon är fortfarande farligt svag och behöver en himmelsk månsten för att återfå sin livskraft. Du måste färdas till Fallen Sky Lakes otämjda vatten och ta en av de månstenar som en fördärvad Shadethicket Oracle samlat på sig.",h="\"Fallen Sky Lake\" är den känslomässiga höjdpunkten i Pelturas Whitemoons uppdragskedja för att rädda sin...",kw={"ashenvale","astranaar","fallen moonstone","fallen sky lake","pelturas whitemoon","relara","shadethicket oracle"},ang={["class:Druid"]="När du rensar ut de fientliga Shadethicket-träskbestarna ser du den tragiska oenighet som sprider sig bland Ashenvales naturliga väktare. Att återställa balansen kräver ett tungt hjärta.",["class:Priest"]="De fallna månstenarna eftersöks för sin gudomliga energi. De är ett påtagligt uttryck för mångudinnan Elunes läkande nåd, som kanaliseras för att rädda ett döende barn.",["faction:Alliance"]="Genom att hjälpa Pelturas Whitemoon visar Alliansen sitt engagemang för att försvara Astranaars invånare mot den krypande fördärvning som tar över Ashenvale.",["race:NightElf"]="För kaldorei är det en helig gemensam plikt att skydda Astranaars unga. Att hämta heliga månstenar knutna till Elunes välsignelser är både en barmhärtig och vördnadsfull handling."},sec={{t="En dotters sista andetag",b="Pelturas Whitemoon har i plågsamma dagar sett sin unga dotter Relara närma sig döden. Kraftfulla läkemedel bryggda av Bathran's Hair och stjärnstoft hjälpte till att få ner hennes höga feber, men prövningen har lämnat hennes kropp utmärglad och bräcklig. Tiden är knapp. Pelturas fruktar att hon bara har några få andetag kvar innan hennes ande försvinner i natten för gott, om inte övernaturliga krafter ingriper."},{t="Den fallna månstenen",b="För att ge flickan ny kraft vänder sig Pelturas till månstenarnas magi. Dessa himmelska skärvor föll en gång fritt i vattnen vid Fallen Sky Lake, sydost om Astranaar. Nattalverna brukade samla dem för deras läkande egenskaper, men nu har aggressiva elementarvarelser eller fördärvad bark tagit dem i besittning. Att samla dem kräver därför klinga och besvärjelser, inte fridfull skörd."},{t="Shadethickets domän",b="Nattalverna förlorade den enkla vägen till sjön när Shadethickets träskbestar slog sig ner där och tog över den omgivande vildmarken. Deras ledare, Shadethicket Oracle, samlar alla fallna månstenar på en avskild holme mitt i vattnet. För att återta en enda relik måste du möta och döda oraklet innan Relara förlorar sina sista krafter. Pelturas krossar den återfunna månstenen i te. Relara dricker det och återfår sin styrka."}},faq={{q="Varför behöver Relara en månsten när febern redan har gått ner?",a="Den intensiva febern tömde Relaras livskraft så svårt att vanlig vila inte kan återställa henne. Hennes far Pelturas tror att endast den rena läkande kraften i en fallen månsten kan återställa hennes uttömda ande innan hon dukar under av utmattning.",al={"varför månsten","relara fortfarande sjuk","relara feber borta"}},{q="Var ligger Fallen Sky Lake?",a="Fallen Sky Lake ligger i östra centrala Ashenvale, sydost om Astranaar. Sjön behärskas av uråldriga, fientliga träskbestar och har en liten ö i mitten.",al={"var ligger fallen sky lake","sjöns läge","shadethicket vid sjön"}},{q="Vem har den fallna månstenen?",a="Månstenen innehas av Shadethicket Oracle, ledaren för de fientliga träskbestar som lever vid sjön. Oraklet håller till på en ö mitt i Fallen Sky Lake.",al={"vem släpper månstenen","shadethicket oracles läge","var får man månsten"}},{q="Vad händer efter det här uppdraget?",a="Det här är det sista ärendet i Pelturas jakt på ett botemedel. Han behöver en fallen månsten för att återställa Relaras styrka. Hennes öde avslöjas när stenen levereras.",al={"finns det ett uppföljningsuppdrag","vad händer sedan","fortsättning på uppdraget"}},{q="Varför samlar Shadethickets på månstenarna?",a="När vilda djur och träskbestar i Ashenvale blev allt mer oberäkneliga och fördärvade började Shadethickets våldsamt driva bort främlingar. Deras orakel samlade systematiskt månrelikerna och vaktade dem, så att nattalverna i Astranaar inte kunde få tag i dem.",al={"varför tar träden stenarna","oraklet samlar månstenar"}},{q="Vilka tidigare uppdrag leder fram till det här?",a="Kedjan börjar med Bathran's Hair, följt av Orendil's Cure, Elune's Tear och The Ruins of Stardust. I varje steg samlar du sällsynta ingredienser för att behandla Relaras allt sämre tillstånd.",al={"uppdrag före fallen sky lake","förutsättningar för uppdraget","vad kommer före"}}},fx={fb73f711={q="Vad används Fallen Moonstone till?",a="Månstenarna som fallit runt Fallen Sky Lake bär på läkande magi knuten till natthimlen. Relaras svåra feber har gått över, men hennes kropp är fortfarande kritiskt svag. Pelturas tror inte att vanlig vila kan rädda henne. Bara den koncentrerade mystiska kraften i en månsten kan återställa hennes förlorade livskraft innan hennes styrka helt tar slut.",al={"fallen moonstone användning","vad gör månstenen","varför fallen moonstone"}}},fp="15,266,27.309.0,20.316.0,23.397.1,60.211.0,33.157.0,29.155.0,30.169.1,50.233.0,42.179.0"}
P.entries["quest:1037"] = {n="Velinde Starsong",s="Det här uppdraget knyter en kuslig undersökning i Ashenvale till den militära hierarkin i Darnassus. Efter att ha avslöjat oroande händelser med koppling till den försvunna befälhavaren Velinde Starsong skickas äventyrarna över havet för att rådfråga Sentinel-ledningen om hennes gåtfulla öde.",h="Det här uppdraget knyter en kuslig undersökning i Ashenvale till den militära hierarkin i Darnassus.",kw={"ashenvale","darnassus","felwood","melyria frostshadow","sentinels","thyn'tel bladeweaver","velinde starsong","warrior's terrace"},ang={["class:Priest"]="Prästinnor vigda åt Elune kommer särskilt att intressera sig för hur en trosfrände kämpade när hon försökte hejda den demoniska flodvåg som vällde fram från Felwood.",["faction:Alliance"]="Uppdraget visar hur strikta de militära protokollen är i Darnassus, där Sentinel-befälhavare håller uppgifter om känsliga försvinnanden på slagfältet åtskilda och strikt begränsade.",["race:NightElf"]="För nattalvernas försvarare handlar det om att avslöja vad som hände en respekterad befälhavare och prästinna, vilket berör det bräckliga läget i norra Kalimdor efter det tredje kriget."},sec={{t="En föregångare försvinner",b="Sentinel Melyria Frostshadow håller vakt i Ashenvale, men hon var inte den första att bära det ansvaret. Före henne tjänstgjorde Velinde Starsong, en prästinna med uppgift att hejda den demoniska korruption som sipprade söderut från Felwood. De första rapporterna tydde på att Starsong hade faran under kontroll, men hennes försvarskampanj föll gradvis samman. Sedan försvann hon plötsligt och utan förvarning eller formell avlösning, och lämnade efter sig ett oavslutat krig och obesvarade frågor."},{t="Terrassens hemligheter",b="Melyria vill inte låta gåtan förbli olöst efter att ha upptäckt oroande spår i skogen, så hon hänvisar sökare till huvudstaden Darnassus. Högt uppe på Warrior's Terrace övervakar Sentinel-befälhavaren Thyn'tel Bladeweaver truppernas utplacering. Starsongs plötsliga avfärd viskas det om i leden, men de exakta omständigheterna hålls hemliga av det högsta befälet. Det krävs uppriktig övertalning innan några djupare arkiv öppnas."}},faq={{q="Vem var Velinde Starsong?",a="Velinde Starsong var en alvprästinna och befälhavare för de Sentinels som var stationerade i Ashenvale. Hon fick i uppdrag att hålla den norra gränsen mot de demoniska fasor som trängde fram ur Felwood, innan hon mystiskt försvann från tjänsten.",al={"velinde starsong historia","vem är velinde","prästinnan velinde"}},{q="Varför frågar Sentinel Melyria om henne nu?",a="Sentinel Melyria Frostshadow tog Velindes plats efter hennes oförklarliga försvinnande. Efter upptäckterna med koppling till The Howling Vale inser Melyria att det som hände hennes föregångare fortfarande kan hota Ashenvales säkerhet.",al={"varför utreda velinde","melyrias skäl för uppdraget"}},{q="Vart måste jag gå för att slutföra uppdraget?",a="Du måste resa från Ashenvale till nattalvernas huvudstad Darnassus, högst upp på Teldrassil. Befälhavaren Thyn'tel Bladeweaver finns på Warrior's Terrace.",al={"var lämnar man in velinde starsong","thyn'tel bladeweavers plats"}},{q="Varför är befälhavare Bladeweaver ovillig att prata?",a="Det är allmänt känt bland Sentinels att Velinde försvann, men omständigheterna och de hemligstämplade detaljerna kring hennes sista uppdrag är känsliga militära angelägenheter. Ledningen delar inte lättvindigt sådan information med utomstående.",al={"varför hemligt","varför vill thyn'tel inte prata"}},{q="Vilken koppling har Velinde till Felwood?",a="Velinde ledde Sentinels frontlinjeinsatser för att hejda den demoniska korruptionen som trängde fram från Felwood. Hennes första försök att hejda den verkade lyckas, men kampanjen började till sist gå om intet strax innan hon försvann.",al={"velinde felwood","vad hände i felwood"}},{q="Vilket uppdrag leder direkt hit?",a="Det här uppdraget följer efter ”The Howling Vale”, där äventyrarna undersöker de märkliga och fientliga händelser som bubblar upp djupt inne i Ashenvales skogar.",al={"förutsättning för velinde starsong","föregående uppdrag"}}},fx={["8a014bde"]={q="Varför skickar Sentinel Melyria dig till Darnassus i stället för att själv åka dit?",a="Sentinel Melyria Frostshadow placerades i Ashenvale för att ta över Velinde Starsongs övergivna uppgifter och hejda de växande hoten från Felwood. Den norra gränsen är ständigt instabil, så hon kan inte lämna sin utpost och själv göra den långa resan tillbaka till Darnassus. En äventyrare kan resa fritt och söka upp Commander Thyn'tel Bladeweaver utan att lämna Ashenvales försvar underbemannat.",al={"varför skicka mig","varför åker melyria inte","varför kan melyria inte åka själv"}}},fp="16,210,22.393.0,22.318.1,25.191.0,45.166.0,45.122.0,47.172.0,45.159.0,40.108.0"}
P.entries["quest:1038"] = {n="Velinde's Effects",s="Velinde's Effects är en alliansutredning i Darnassus som söker svar på vad som hände Sentinel Velinde Starsong. På uppdrag av Thyn'tel Bladeweaver hämtar äventyrare Velindes personliga dagbok ur en kista i Sentinels kvarter för att få veta varför den vördnadsfulla prästinnan försvann.",h="Velinde's Effects är en alliansutredning i Darnassus som söker svar på vad som hände Sentinel Velinde...",kw={"bladeweaver","logement","darnassus","dagbok","mel'thandris","sentinels","starsong","thyn'tel","tradesmen's terrace","velinde"},ang={["class:Priest"]="Velinde var en vördad prästinna vars hängivenhet till heliga plikter ger Elunes övriga anhängare bråttom att ta reda på vad som fick henne på avvägar.",["faction:Alliance"]="När man utreder högt uppsatta nattalvsbefäl blir de kvardröjande hoten över Kalimdor tydliga. Den unga alliansledningen i Darnassus har svårt att hålla dem i schack.",["race:NightElf"]="Velinde Starsong står för de tysta uppoffringar som görs av The Sisterhood of Elune och Sentinels. Hennes plötsliga försvinnande oroar därför hennes folk i Darnassus djupt."},sec={{t="En betrodd Sentinel",b="Prästinnan Velinde Starsong vann stort förtroende bland nattalverna genom sin långa och hängivna tjänst. När hon i tysthet försvann från sina plikter antog Sentinels att hon hade rest av personliga skäl och väntade sig att hon skulle återvända. Först när utomstående hittar ledtrådar med koppling till Tome of Mel'Thandris tillåter Sentinel-ledningen en undersökning av hennes personliga tillhörigheter."},{t="Kistan i logementet",b="Thyn'tel Bladeweaver är stationerad på Warrior's Terrace i Darnassus och ger dig nyckeln till Velindes låsta kista, som förvaras i Sentinels logement på Tradesmen's Terrace. I kistan ligger Velindes personliga dagbok, med detaljer om hennes uppdrag och innersta tankar. I stället för att lugna Sentinels antyder dagboken mörka, hemlighetsfulla händelser som fick henne att ensam ge sig av från Teldrassil."}},faq={{q="Vem är Velinde Starsong?",a="Velinde Starsong är en högt aktad nattalvprästinna och Sentinel-befälhavare. Hennes hängivna tjänst gav henne stor respekt bland hennes likar innan hon plötsligt försvann på ett ouppklarat uppdrag.",al={"velinde starsongs bakgrund","vem är velinde","velindes bakgrund"}},{q="Var finns Velindes kista?",a="Kistan förvaras i Sentinels logement på övervåningen i en byggnad på Darnassus Tradesmen's Terrace. Du når den genom att gå över den upphöjda bron från den närliggande butiken för postrustningar.",al={"var finns velindes kista","var finns velinde's effects","sentinels logement i darnassus"}},{q="Varför letade inte Sentinels efter henne tidigare?",a="Velinde hade ett oklanderligt rykte, så hennes befälhavare trodde att hon hade giltiga, personliga skäl att resa och antog att hon skulle återvända när hennes ärende var avslutat.",al={"varför ignorerade sentinels velinde","varför anmäldes inte velinde försvunnen"}},{q="Vad hittar man i dagboken?",a="Hennes dagbok visar att hennes frånvaro var långt mer oroande än en vanlig ledighet. Thyn'tel Bladeweaver söker därför genast hjälp utifrån för att spåra hennes resväg.",al={"innehållet i velindes dagbok","vad skrev velinde"}},{q="Hur var Velinde kopplad till Tome of Mel'Thandris?",a="Den uråldriga alvtexten innehöll hänvisningar till hennes tidigare efterforskningar och aktiviteter. Det blev den första drivkraften som fick forskare och äventyrare att undersöka var hon befann sig.",al={"tome of mel'thandris och velinde","varför tome of mel'thandris"}},{q="Vart leder utredningen efter att man hittat hennes tillhörigheter?",a="Ledtrådarna i dagboken leder utredarna mot The Barrens, där de följer Velindes spår söderut mot Kalimdors knutpunkter för resor och hamnar.",al={"vart efter velinde's effects","nästa uppdrag efter velinde's effects"}}},fx={c0fc6707={q="Varför vill Thyn'tel Bladeweaver att Velindes tillhörigheter genomsöks?",a="Sentinels trodde länge att Velinde Starsong på eget bevåg hade lämnat Darnassus och skulle återvända när tiden var inne. De litade på hennes hängivna tjänst. Men det du upptäckte i Tome of Mel'Thandris tyder på att hennes försvinnande kan vara betydligt mer komplicerat. Bladeweaver ger dig tillgång till hennes personliga kista i hopp om att Velindes tjänstejournal ska ge avgörande ledtrådar om hennes plötsliga avfärd och var hon befinner sig nu.",al={"varför vill thyn'tel detta","thyn'tel bladeweavers motiv","varför söka igenom velindes tillhörigheter"}}},fp="17,239,18.366.0,26.383.1,24.177.0,33.192.0,48.170.0,38.150.0,54.178.0,60.118.1"}
P.entries["quest:1039"] = {n="The Barrens Port",s="The Barrens Port är ett Alliance-uppdrag som ges av Thyn'tel Bladeweaver i Darnassus som en del av utredningen av Velinde Starsongs försvinnande. Sentinels tror att Velinde tog ett skepp över Great Sea till Eastern Kingdoms och skickar dig genom farligt Horde-territorium till den goblindrivna hamnen Ratchet för att granska Wharfmaster Dizzywigs liggare.",h="The Barrens Port är ett Alliance-uppdrag som ges av Thyn'tel Bladeweaver i Darnassus som en del av...",kw={"ashenvale","ratchet","scythe of elune","steamwheedle cartel","the barrens","thyn'tel bladeweaver","velinde starsong","wharfmaster dizzywig"},ang={["faction:Alliance"]="När Alliance-spejare färdas genom hjärtat av Kalimdor utsätts de för täta Horde-patruller i The Barrens. De måste vara försiktiga innan de når den neutrala fristaden vid goblinernas kajer.",["race:NightElf"]="Velinde Starsong är en högt aktad Sentinel. Hennes förlust tynger ledarskapet i Darnassus, och att följa hennes desperata färd är en fråga om kaldoreisk plikt."},sec={{t="På spåren efter prästinnan",b="Efter att ha undersökt Velinde Starsongs personliga tillhörigheter upptäckte Sentinels ledtrådar som tydde på att hon sökte passage över havet mot Eastern Kingdoms. Ratchet är den enda fungerande hamnen i The Barrens, och därmed den enda vägen för en resenär från norra Kalimdor att ordna transport söderut eller österut utan att segla direkt från Night Elf-territorium. Thyn'tel Bladeweaver skickar dig söderut för att leta efter spår av Velindes namn i hamnmästarens fraktliggare."},{t="En farlig färd",b="För att ta sig till Ratchet måste en Alliance-agent våga sig genom hjärtat av Horde-kontrollerade länder. Söder om Ashenvale kryllar The Mor'shan Rampart och The Barrens torra savanner av orcher till häst och Tauren-patruller. Själva staden Ratchet styrs av det neutrala Steamwheedle Cartel och erbjuder en trygg hamn under goblinernas lagar, där handel går före fraktionsrivalitet och Wharfmaster Dizzywig noggrant håller reda på varje passagerare och lastlåda som passerar kajerna."}},faq={{q="Varför skickar Sentinels mig till The Barrens?",a="Ratchet är den främsta neutrala handelshamnen i centrala Kalimdor. Eftersom Velinde Starsong försvann när hon sökte passage mot Eastern Kingdoms drar Night Elves slutsatsen att hon troligen bokade en säker resa utomlands på ett goblinhandelsfartyg, snarare än att använda officiella militära kanaler.",al={"varför åka till ratchet","varför uppdraget the barrens port"}},{q="Vem är Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig är goblinen som ansvarar för avgångar till havs och lastregister vid kajerna i Ratchet. På uppdrag av Steamwheedle Cartel för han utförliga liggare över varje fartyg, passagerare och last som seglar in i eller ut ur hamnen.",al={"vem är dizzywig","ratchets hamnmästare"}},{q="Varför är en Alliance-medlem trygg i Ratchet?",a="Ratchet drivs av det neutrala Steamwheedle Cartel, inte av Horde. Goblinerna sätter handel och vinst framför fraktionstvister. Deras slagskämpar upprätthåller därför freden och låter Alliance-resenärer uträtta sina ärenden ostörda, så länge de inte drar vapen inne i bosättningen.",al={"är ratchet säkert för alliance","attackerar vakterna mig i ratchet"}},{q="Vad händer när jag hittar Wharfmaster Dizzywig?",a="När Dizzywig har granskat sina fraktlistor bekräftar han att Velinde avreste med ett fartyg på väg till Eastern Kingdoms. Han skickar dig vidare till Booty Bay i Stranglethorn Vale för att följa hennes spår på andra sidan Great Sea.",al={"vad händer efter the barrens port","fortsättning på velindes uppdrag"}},{q="Hur tar sig en Alliance-resenär säkert till Ratchet?",a="Alliance-resenärer färdas vanligtvis söderut från Ashenvale förbi Silverwing Grove och rundar den hårt bevakade Mor'shan Rampart genom att ta sig genom kullarna strax öster om huvudvägen. Väl i The Barrens leder stigarna mot östkusten direkt till kajerna i Ratchet.",al={"säkraste vägen till ratchet för alliance","hur tar man sig till ratchet som alliance"}},{q="Vem är Velinde Starsong?",a="Velinde Starsong var en Night Elf-prästinna och Melyria Frostshadows föregångare i Ashenvale, med uppdraget att rena skogen från demoner. Hennes arbete gick långsamt tillbaka tills hon plötsligt försvann, och hennes spår verkar nu leda över havet.",al={"vem är velinde","velinde starsongs historia"}}},fx={["1c038d53"]={q="Varför behöver Thyn'tel Bladeweaver mig i stället för att skicka en Sentinel till Ratchet?",a="The Barrens kontrolleras helt av Horde, och beväpnade Night Elf-sentinels som marscherar söderut från Ashenvale skulle genast utlösa en blodig strid. Ratchets neutrala hamn välkomnar fredliga resenärer, men en officiell Kaldorei-militär närvaro skulle störa den sköra vapenvilan och väcka starka misstankar. En ensam äventyrare kan obemärkt ta sig förbi Horde-gränserna och hantera gobliner utan att starta ett öppet krig.",al={"varför skicka mig","varför inte skicka en sentinel","varför jag till hamnen i the barrens"}}},fp="16,223,22.365.0,20.349.0,46.267.0,28.204.0,48.236.0,48.197.1,51.240.0,24.225.0"}
P.entries["quest:104"] = {n="The Coastal Menace",s="Captain Graysons vålnad vakar över Westfalls klippiga kust, där hans skepp förliste mot klipporna. Han skyller på Old Murk-Eye för att ha drivit fyrvaktarens familj från sin post och senare dödat dem i ett nytt angrepp. Nu uppmanar han resande att jaga murlockhövdingen och skipa rättvisa vid kusten.",h="Captain Graysons vålnad vakar över Westfalls klippiga kust, där hans skepp förliste mot klipporna.",kw={"captain grayson","kustens plåga","great sea","murloc","old murk-eye","scale of old murk-eye","westfall","westfall lighthouse"},ang={["faction:Alliance"]="Westfalls kustvatten trafikeras av viktiga handelsfartyg på väg till Stormwind. Att driva bort ledare som Old Murk-Eye bidrar till att hålla de sydliga sjölederna fria från sabotage.",["race:Human"]="Som människa ser du mordet på fyrvaktarens familj som ett mörkt kapitel i Westfalls förlust av trygghet. Deras död ger dig ytterligare ett skäl att hämnas dina medborgare."},sec={{t="En fyr i mörkret",b="Westfall Lighthouse vägledde en gång skepp genom de sydliga kusternas förrädiska grund. Captain Graysons skepp gick på klipporna i mörkret efter att murlocerna skrämt bort fyrvaktarens familj från sin post. Familjen återvände och tände fyren igen, men tryggheten varade inte länge. Ett listigt och hänsynslöst rovdjur lurade fortfarande längs kusten."},{t="Kustens plåga",b="Old Murk-Eye samlade kustens mindre begåvade murlocer och ledde dem mot fyren. I det andra angreppet dödades fyrvaktarens familj medan Captain Grayson såg på, hjälplös. Nu kräver den spöklika kaptenen Murk-Eyes död och en fjällflaga som bevis, i hopp om att ge de döda frid och skydda sjöfarare på Great Sea."}},faq={{q="Vem är Old Murk-Eye?",a="Old Murk-Eye är en listig murloc-hövding som stryker omkring längs Westfalls sydkust. Han samlar andra murlocer och leder dem i angrepp mot mänskliga bosättningar längs stranden.",al={"murk-eye","murk eye","vem är murk eye","vem är kustens plåga"}},{q="Varför vill Captain Grayson att Old Murk-Eye ska dö?",a="Captain Grayson vill att Old Murk-Eye ska dö eftersom murlocer skrämde bort fyrvaktarens familj från sin post, så att kusten låg mörk när Graysons skepp gick på klipporna. Senare såg Grayson Murk-Eye leda ett andra angrepp som dödade fyrvaktaren och hans familj när de hade återvänt.",al={"graysons agg","varför döda murk eye","graysons bakgrund"}},{q="Var finns Old Murk-Eye?",a="Old Murk-Eye stryker omkring på Westfalls öppna stränder och i det grunda vattnet, nära Westfall Lighthouse och närliggande murlocläger.",al={"murk-eyes plats","var finns murk eye","hitta murk eye"}},{q="Vilket bevis ber Grayson om?",a="Captain Grayson ber om en fjällflaga från Old Murk-Eye som bevis på att hövdingen är död.",al={"dödsbevis","murk-eyes fjällflaga","lämna in uppdrag"}},{q="Vem var Captain Grayson i livet?",a="Captain Grayson var en sjökapten vars skepp gick på klipporna nedanför Westfall Lighthouse. Hans ande dröjer kvar vid kusten och söker hämnd på murlocer och tryggare vatten för förbipasserande fartyg.",al={"captain grayson","spöke vid fyren","fyrspöke"}},{q="Vad hände med fyrvaktarens familj?",a="Fyrvaktarens familj flydde först efter att Old Murk-Eye hade plågat fyrtornet. De återvände för att tända lyktan, men Murk-Eye ledde ett andra angrepp som dödade hela familjen.",al={"fyrvaktarens familj","vem bodde vid fyren","massaker vid fyren"}}},fx={["871c093a"]={q="Varför behöver Captain Grayson att du dödar Old Murk-Eye?",a="Captain Grayson är ett spöke, bundet till den klippiga kust där hans skepp krossades mot grundet. Han är kroppslös och maktlös, och kan varken hämnas på murlocernas ledare för vaktarens familjs död eller skipa rättvisa längs kusten. Dessutom saknar Westfall en organiserad militär eller vaktstyrka längs de sydvästra stränderna, så uppgiften faller helt på kringresande äventyrare.",al={"varför kan grayson inte döda murk-eye","varför behöver grayson mig","varför behöver grayson hjälp"}}},fp="18,331,20.302.0,24.344.0,20.161.0,48.264.0,32.116.0,32.89.0,32.205.0,48.181.0"}
P.entries["quest:1040"] = {n="Passage to Booty Bay",s="Det här uppdraget följer spåren efter den försvunna Sentinel Velinde Starsong över Stora havet till Booty Bays laglösa fristad. Efter att hamnmästare Dizzywig grävt fram skeppsloggar måste alliansresenärer resa från Ratchet till Eastern Kingdoms för att söka efter en goblin som kör karavaner och heter Ruzzgot.",h="Det här uppdraget följer spåren efter den försvunna Sentinel Velinde Starsong över Stora havet till Booty...",kw={"black osprey","booty bay","caravaneer ruzzgot","passage till booty bay","ratchet","scythe of elune","velinde starsong","hamnmästare dizzywig"},ang={["faction:Alliance"]="Att ta sig fram i neutralt goblinområde som Ratchet och Booty Bay kräver tålamod och diplomati. Alliansresenärer måste hantera legosoldater och kartellens byråkrater.",["race:NightElf"]="Att hitta Velinde Starsong är ett brådskande uppdrag för kaldorei, eftersom hennes försvinnande med Scythe of Elune lämnat efter sig ett seglivat och farligt mysterium i Ashenvales skogar."},sec={{t="Ett spår över havet",b="Sökandet efter nattalven Sentinel Velinde Starsong leder bort från Ashenvales välbekanta trädkronor och ut på havets handelsleder. I den livliga goblinhamnen Ratchet gräver hamnmästare Dizzywig till slut fram gamla frakthandlingar som bekräftar att Velinde bokat passage ombord på ett fartyg vid namn Black Osprey, med kurs direkt mot piratnästet Booty Bay i Stranglethorn Vale."},{t="Vägen till Booty Bay",b="För att nå Booty Bay måste du gå ombord på den neutrala goblinfärjan som går över havet mellan Ratchet och den södra spetsen av Eastern Kingdoms. Vid ankomsten leder spåret vidare till Caravaneer Ruzzgot, en goblin som sköter transporter och som Dizzywig rekommenderade för Velinde när hon frågade om farliga resor landvägen genom den södra vildmarken."}},faq={{q="Vem är Velinde Starsong?",a="Velinde Starsong var en nattalvprästinna som ledde arbetet i Ashenvale för att hålla den demoniska närvaron i Felwood tillbaka. Hennes ansträngningar ebbade långsamt ut tills hon försvann, och nu följer Sentinels hennes resa över havet.",al={"velinde","vem är velinde","velinde starsong berättelse"}},{q="Varför reste Velinde till Booty Bay?",a="Booty Bay är den främsta hamnen som förbinder centrala Kalimdor med södra Eastern Kingdoms. Velinde behövde ta sig över Stora havet, och Black Osprey från Ratchet erbjöd en direktresa mot människornas och dvärgarnas riken, där hon frågade om resor landvägen.",al={"varför booty bay","velinde booty bay","varför reste hon till booty bay"}},{q="Vem är hamnmästare Dizzywig?",a="Hamnmästare Dizzywig sköter skeppsdockorna i Ratchet åt Steamwheedle Cartel. Han är känd för sitt otåliga sätt och förvaltar hamnens loggböcker och passagerarlistor för alla fartyg som reser mellan Kalimdor och Eastern Kingdoms.",al={"dizzywig","vem är dizzywig","hamnmästare"}},{q="Vem är Caravaneer Ruzzgot?",a="Caravaneer Ruzzgot är en goblin som kör lastdjur och har sin bas i Booty Bay, där han samordnar försörjningskaravaner och transporter landvägen genom Stranglethorn Vales farliga djungler och vidare därifrån.",al={"ruzzgot","caravaneer ruzzgot","vem är ruzzgot"}},{q="Vilket fartyg tog Velinde?",a="Enligt hamnmästare Dizzywigs skeppsregister bokade Velinde Starsong passage ombord på Black Osprey, som genomförde resan från Ratchet över Stora havet till Booty Bay.",al={"velindes fartyg","vilken båt tog velinde","black osprey"}},{q="Hur tar jag mig från Ratchet till Booty Bay?",a="Steamwheedle Cartel driver en passagerarfärja direkt från den södra kajen i Ratchet över Stora havet. Färjan lägger till i pirathamnen Booty Bay på den södra spetsen av Stranglethorn Vale.",al={"ta sig till booty bay","hur tar man sig till booty bay","båt till booty bay"}}},fx={["416fbc17"]={q="Varför vill Wharfmaster Dizzywig att du ska åka till Booty Bay?",a="Han har inget personligt intresse av Velinde Starsong eller hennes öde. Han vill bara få ut dig från sitt kontor. Dizzywig håller Ratchets livliga hamn igång, och att leta i gamla fraktjournaler efter en passagerare från förr är redan mer vänlighet än en goblinhamnmästare brukar bjuda på gratis. När han bekräftat att hon seglade med Black Osprey och nämnt karavaner längs landsvägen, hänvisar han dig till Caravaneer Ruzzgot på andra sidan havet i Booty Bay. Då slutar du störa honom, så att han kan återgå till arbetet.",al={"dizzywigs motiv","varför skickar dizzywig dig","varför booty bay för dizzywig"}}},fp="20,166,22.298.0,21.299.0,24.201.0,36.195.0,28.210.0,26.176.0,27.172.0,42.164.0"}
P.entries["quest:1041"] = {n="The Caravan Road",s="Karavanvägen är ett Alliance-uppdrag som följer spåren efter den försvunna Night Elf-prästinnan Velinde Starsong. Med ledtrådar från Booty Bay går spåret norrut från Stranglethorn Vales farliga djungler till den skuggiga staden Darkshire.",h="Karavanvägen är ett Alliance-uppdrag som följer spåren efter den försvunna Night Elf-prästinnan Velinde...",kw={"booty bay","caravaneer ruzzgot","clerk daltry","darkshire","duskwood","stranglethorn vale","karavanvägen","velinde starsong"},ang={["faction:Alliance"]="Att föra nyheter mellan de neutrala goblinhamnarna och avlägsna Alliance-utposter som Darkshire stärker banden i en värld söndrad av de senaste krigen.",["race:NightElf"]="Velinde Starsong är en aktad Sentinel-prästinna till Elune. Hennes hemlighetsfulla agerande i Eastern Kingdoms väcker stor oro bland hennes folk i Kalimdor."},sec={{t="En prästinna i djungeln",b="När äventyrare följer Velinde Starsongs spår genom världen färdas de från Ashenvales skogar ända till den sydliga hamnen Booty Bay. Där minns Caravaneer Ruzzgot en ovanlig passagerare: en Night Elf-prästinna som reste med hans dammiga handelskaravan. Sådana ensamma resor är ovanliga för hennes folk, och därför minns köpmännen särskilt hennes färd genom Stranglethorn Vales laglösa djungel."},{t="Norrut till Darkshire",b="Enligt Ruzzgot skildes han och Velinde åt under färden norrut genom djungeln, då prästinnan fortsatte mot Duskwood. Hennes spår leder direkt till den hårt ansatta staden Darkshire, där stadens handlingar sköts noggrant av Clerk Daltry. I en tid präglad av övernaturliga hot antecknar Daltry varje okänd resenär som kommer till staden. Hans liggare är därför nästa viktiga ledtråd till Velindes öde."}},faq={{q="Vem är Velinde Starsong?",a="Velinde Starsong är en Night Elf-prästinna till Elune som lämnade sitt hemland i Kalimdor under mystiska omständigheter. Hennes försvinnande ledde till ett omfattande sökande över kontinenterna, från Ashenvale genom Eastern Kingdoms.",al={"velinde","vem är velinde","vem letar vi efter"}},{q="Varför reste Velinde med en karavan?",a="Velinde reste ensam eller utan sällskap genom goblinernas områden. I Booty Bay anlitade hon Caravaneer Ruzzgots handelskaravan för den farliga färden norrut genom Stranglethorn Vale.",al={"varför karavan","velinde karavan","ruzzgots karavan"}},{q="Vem är Clerk Daltry?",a="Clerk Daltry är stadsskrivare och arkivarie i Darkshire i Duskwood. Med tanke på de utbredda hoten och märkliga händelserna i regionen håller han noggrann uppsikt över främlingar och besökare som kommer till staden.",al={"clerk daltry","daltry darkshire","vem är daltry"}},{q="Vart leder uppdragskedjan efter Darkshire?",a="Efter att ha rådfrågat Clerk Daltrys kommunala handlingar hänvisar han resenärer till Jonathan Carevin. Därmed inleds uppdraget 'The Carevin Family', som avslöjar mer om Velindes vistelse i Duskwood.",al={"nästa uppdrag","what comes next","efter darkshire"}},{q="Varför är det farligt att resa från Booty Bay till Darkshire?",a="Stranglethorn Vale kryllar av rovdjur, fientliga trollstammar och Bloodsail Buccaneers, som är mycket farligare än Duskwoods lokala djurliv. För att ta sig norrut måste man hålla sig nära huvudvägen.",al={"djungelns faror","stranglethorn nivå","farliga stranglethorn"}},{q="Var började undersökningen?",a="Sökandet började i Ashenvale, där Night Elf-utredare noterade att Velinde gett sig av utan förklaring med en mäktig artefakt. Ledtrådarna pekade mot ett skepp på väg mot de södra haven.",al={"startpunkt","var började uppdragskedjan","start i ashenvale"}}},fx={a495199a={q="Varför hjälper Caravaneer Ruzzgot dig att hitta Velinde?",a="Caravaneer Ruzzgot missbedömde dig till en början, men efter att du bevisat vad du går för delar han gärna med sig av det han vet. En Night Elf-prästinna som reste med hans råbarkade sjöfarare var ovanlig nog för att fastna i minnet. Han skildes från Velinde Starsong på vägen norrut och har inget att förlora på att hänvisa dig till Darkshire och dess arkivarie.",al={"ruzzgots motiv","varför hjälper ruzzgot","varför hjälpa till att hitta velinde"}}},fp="16,191,25.308.0,18.307.0,24.238.0,41.162.0,20.155.0,49.170.1,55.178.0,35.186.0"}
P.entries["quest:1042"] = {n="The Carevin Family",s="The Carevin Family är ett kort alliansuppdrag där du utreder ett mysterium som knyter Velinde Starsong till Duskwoods monsterjägare. På Clerk Daltrys vägledning söker du den försvunna prästinnan hos Jonathan Carevin, överhuvudet för en familj som jagar odjur och fiender.",h="The Carevin Family är ett kort alliansuppdrag där du utreder ett mysterium som knyter Velinde Starsong till...",kw={"calor","carevin","clerk daltry","darkshire","duskwood","jonathan carevin","velinde starsong","vargmän","worgen"},ang={["class:Hunter"]="Carevin-familjen är en kärv grupp monsterjägare med rötter i staden, specialiserad på att rensa bort onaturliga fiender och förbannade rovdjur.",["faction:Alliance"]="Den här delen av utredningen visar hur isolerade och vaksamma alliansens bosättningar i Duskwood måste vara för att klara sig i de fördärvade skogarna.",["race:NightElf"]="Att hitta mänskliga monsterjägare med avhuggna huvuden från varelser knutna till Velinde Starsong är en oroande ledtråd för nattalver som följer prästinnans ödesdigra färd."},sec={{t="Spår av klor och skuggor",b="Sökandet efter Velinde Starsong leder bort från Kalimdors uråldriga skogar och djupt in i Duskwoods hemsökta dunkel. När du kommer till Darkshire hittar stadsskrivaren Clerk Daltry ingen officiell anteckning om att en alvprästinna någonsin bott i staden. Men när du nämner de vilda vargmännen i Ashenvale spetsar han öronen, för odjur som stämmer med beskrivningen har nyligen börjat terrorisera skogarna omkring."},{t="Nattens jägare",b="Det är Carevin-familjen, inte stadsvakterna, som tar hand om sådana onaturliga fasor. De är kända i trakten som skoningslösa jägare på demoner, odöda och andra vidunder. Deras spårare Calor släpade nyligen en makaber rad avhuggna vargmanshuvuden genom Darkshires gator. Clerk Daltry hänvisar främlingar till Jonathan Carevin, familjens stränge överhuvud, för att få veta vad familjen känner till om dessa våldsamma worgen."},{t="Ett kyligt mottagande",b="Att närma sig Carevin-familjens överhuvud är ingen vardaglig visit. Duskwoods obevekliga fasor tär på Jonathan Carevin, och han bemöter varje objuden främling som frågar om worgen med stor misstänksamhet. Innan han berättar vad hans jägare upptäckt om odjuren kräver han att få veta vem du är och varför du söker efter sådant som bäst lämnas begravt i mörkret."}},faq={{q="Vem är Jonathan Carevin?",a="Jonathan Carevin är överhuvud för Carevin-familjen i Darkshire. Han leder en familj som är känd i den här fördärvade trakten som erfarna jägare, specialiserade på att spåra upp och döda demoner, odöda och monstruösa odjur.",al={"jonathan carevin","vem är carevin","carevin-familjens överhuvud"}},{q="Varför hänvisar Clerk Daltry dig till Carevin-familjen?",a="Clerk Daltry har ingen uppgift om den försvunna nattalven Velinde Starsong, men känner igen beskrivningen av vargmännen du nämner. Carevin-familjens spårare Calor tog nyligen med sig avhuggna delar av dessa varelser till Darkshire, så familjen är stadens främsta experter på monstren.",al={"varför träffa carevin","clerk daltry carevin","varför gå till jonathan"}},{q="Vem är Calor?",a="Calor är jägare och spårare med koppling till Carevin-familjen i Darkshire. Han gjorde nyligen ett makabert intryck på staden när han tågade in med en rad avhuggna worgenhuvuden och visade att vargmännen är aktiva i närheten.",al={"calor","vem är calor","carevin-jägaren calor"}},{q="Hur knyter uppdraget samman Ashenvale och Duskwood?",a="Uppdragskedjan börjar i Ashenvale, där Velinde Starsong försvinner och worgen dyker upp på ett mystiskt sätt. Följer du karavanens rutt leder den från Kalimdor över havet till Duskwood, där samma monstruösa vargbest har visat sig.",al={"koppling till velinde starsong","varför duskwood","ashenvale till darkshire"}},{q="Varför är Jonathan Carevin så misstänksam mot främlingar?",a="Duskwood är fullständigt översvämmat av skuggor, odöda och ondskefulla krafter, vilket gör de överlevande invånarna djupt paranoida. När en okänd äventyrare plötsligt dyker upp och frågar om livsfarliga worgen misstänker Jonathan ont uppsåt tills främlingen bevisar motsatsen.",al={"varför är carevin fientlig","carevins misstänksamhet"}},{q="Vilka monster är Carevin-familjen specialiserad på att bekämpa?",a="Carevin-familjen ägnar sig åt att utrota monstruösa hot, främst demoner, odöda och bisarra, avvikande odjur som worgen som hemsöker Duskwood.",al={"carevin-monster","vad jagar carevin-familjen"}}},fp="18,165,28.308.0,20.402.0,16.314.1,24.182.0,55.263.0,13.195.0,50.228.0,51.219.0,53.126.0"}
P.entries["quest:1043"] = {n="The Scythe of Elune",s="The Scythe of Elune är en alliansundersökning som knyter samman en forntida Night Elf-relik i Kalimdor med den plötsliga worgeninvasion som plågar Duskwood. Jonathan Carevin skickar ut äventyrare från Darkshire för att utforska Roland's Dooms hemsökta djup och ta reda på vad som förde dessa glupska bestar till Eastern Kingdoms.",h="The Scythe of Elune är en alliansundersökning som knyter samman en forntida Night Elf-relik i Kalimdor med...",kw={"calor","darkshire","duskwood","jonathan carevin","nightbane","roland's doom","the scythe of elune","velinde starsong","worgen"},ang={["class:Druid"]="De vilda och otämjda worgen som The Scythe of Elune släppte lös är en allvarlig varning till druider om krafter som inte går att kontrollera.",["faction:Alliance"]="När mysteriet bakom Nightbane-worgen nystas upp får Darkshire och alliansen sina första verkliga svar om fasorna som hemsöker södra Duskwood.",["race:NightElf"]="När prästinnan Velinde Starsongs sista viloplats hittas uppenbaras det fruktansvärda priset för att The Scythe of Elune hamnade utom Systraskapets uppsikt."},sec={{t="En jakt i mörkret",b="Efter att ha spårat den gåtfulla prästinnan Velinde Starsong genom Kalimdor och talat med familjen Carevin i Darkshire finner resenärerna en gemensam sak med Jonathan Carevin. Nightbane-worgen har intagit södra Duskwood, drivit bort gruvarbetare och hotar det lilla som finns kvar av samhället. Carevin förstår inte fullt ut bestarnas övernaturliga ursprung, men inser värdet av någon som är villig att rensa ut dem. Han hänvisar därför sökarna till Roland's Doom, gruvan där odjuren först sågs."},{t="Spöken från Roland's Doom",b="Djupare inne i Roland's Doom, bland flockar av våldsamma Nightbane, finns en orörd jordhög. När jorden rubbas visar sig ett kvarvarande spöke av Velinde Starsong själv. Den spöklika uppenbarelsen bekräftar att nattalvprästinnan tog sig in i denna eländiga grotta med The Scythe of Elune, men mötte ett tragiskt och mystiskt slut under Duskwoods jord. Hennes spöke sörjer att worgen hon släppte lös nu härjar fritt och att lieen hon fick av sin gudinna är förlorad."}},faq={{q="Var letar jag efter spår av The Scythe of Elune?",a="Ta dig in i Roland's Doom, en övergiven gruva i sydöstra Duskwood. Kämpa dig igenom Nightbane-worgen till en orörd jordhög inne i gångarna.",al={"var finns lien","the scythe of elune plats","grottan roland's doom"}},{q="Vem är Jonathan Carevin?",a="Jonathan Carevin tillhör familjen Carevin, som bor i Darkshire. När försvararna mot ondskan blir allt färre delar han gärna information med utomstående som vill minska antalet farliga worgen.",al={"jonathan carevin","carevin darkshire"}},{q="Vad hände med Velinde Starsong i gruvan?",a="Långt inne i Roland's Doom finns svaret på Velindes öde och var The Scythe of Elune befinner sig, begravt under en orörd jordhög. När du undersöker den får du veta vad som hänt, och kan ta berättelsen tillbaka till Jonathan Carevin.",al={"velinde starsongs öde","vad hände med velinde"}},{q="Vad är The Scythe of Elune?",a="The Scythe of Elune är en helig Night Elf-artefakt som prästinnan Velinde Starsong fick. Sentinels tror att gudinnan Elune skänkte den till henne som en gåva.",al={"vad är lien","the scythe of elune bakgrund"}},{q="Varför dök worgen upp i Duskwood?",a="Enligt Jonathan Carevin dök worgen upp från ingenstans. De hittades först i gruvan Roland's Doom i söder. Om du söker efter spår av The Scythe of Elune där får du reda på varför.",al={"varför worgen i duskwood","duskwoods worgenursprung"}},{q="Vem är Calor?",a="Calor är en bundsförvant till familjen Carevin i Darkshire. Efter dina upptäckter i Roland's Doom ger Jonathan honom order att helt inrikta sig på att hejda worgenhotet.",al={"npc calor","vem är calor"}}},fx={["48e90786"]={q="Varför vill Jonathan Carevin att det här ska göras?",a="Duskwood är omringat av monster, och worgen är bland de dödligaste rovdjuren som stryker genom de mörka skogarna. Jonathan Carevin kanske inte helt förstår varför du söker efter Scythe of Elune, men han ser en möjlighet. Om din jakt driver bort bestarna som hemsöker Roland's Doom och avslöjar hur de kom dit, hjälper det försvaret av Darkshire. Night Watch har knappa resurser, så all information och varje rensning av den vilda flocken bidrar direkt till att skydda de överlevande stadsborna.",al={"varför hjälper carevin","jonathan carevins motiv","varför vill carevin ha scythe"}}},fp="19,238,18.479.0,23.406.1,40.150.0,24.171.0,46.185.1,28.159.0,38.181.1,13.172.1"}
P.entries["quest:1044"] = {n="Answered Questions",s="Answered Questions är ett Alliance-uppdrag som avslutar en undersökning över flera kontinenter om nattalvprästinnan Velinde Starsongs försvinnande. Efter att ha följt ledtrådar genom Kalimdor och Eastern Kingdoms återvänder en äventyrare till Darnassus för att lämna en slutrapport till Thyn'tel Bladeweaver.",h="Answered Questions är ett Alliance-uppdrag som avslutar en undersökning över flera kontinenter om...",kw={"answered questions","darnassus","duskwood","jonathan carevin","roland's doom","scythe of elune","thyn'tel bladeweaver","velinde starsong","worgen"},ang={["class:Priest"]="Elunes präster känner en stark andlig samhörighet med Velindes berättelse och ser både gudinnans gåvors kraft och faran i att försöka kuva okända bestar.",["faction:Alliance"]="Uppdraget lyfter fram de sköra banden över kontinenterna mellan nattalverna i Kalimdor och de hårt prövade mänskliga bosättningarna i Duskwood, som hanterar gemensamma, dunkla hot.",["race:NightElf"]="För nattalverna hjälper rapporten ledarskapet att följa spåret efter en försvunnen prästinna och en helig artefakt."},sec={{t="En tragisk sanning",b="Uppdragskedjan som följer Velinde Starsongs spår börjar i Ashenvale och sträcker sig över kontinenterna till Duskwoods hemsökta dungar och övergivna gruvor. Hennes spår avslöjar att Velinde, desperat att försvara Kalimdor mot demoniska krafter, använde Scythe of Elune och kallade fram de våldsamma worgen. Men hon förlorade kontrollen, vilket ledde till tragedi och hennes död djupt inne i gruvan Roland's Doom, medan Duskwood lämnades att hantera de monstruösa följderna."},{t="Återvänd till Darnassus",b="Efter att ha återfunnit Velinde's Journal och fått veta hur hennes liv slutade uppmanar Jonathan Carevin i Duskwood äventyraren att återvända till Teldrassil. I Darnassus tar Sentinel Thyn'tel Bladeweaver emot rapporten. Velinde var nära vän med översteprästinnan Tyrande Whisperwind, så nyheten om hennes öde blir ett tungt personligt och andligt slag för The Sisterhood of Elune."},{t="En försvunnen artefakt",b="Velindes öde är till sist klarlagt, men en större fara är fortfarande olöst: Scythe of Elune har försvunnit. Skäran gavs av gudinnan som en helig gåva och ett vapen, men har nu gått förlorad i vildmarken, långt från prästinnorna som vördar den. De vilda worgen som finns i Eastern Kingdoms utgör ett kvarstående, oförutsägbart hot som uppstått ur förlusten."}},faq={{q="Vad är uppdraget Answered Questions?",a="Answered Questions är ett Alliance-uppdrag som avslutar undersökningen av Velinde Starsong. Jonathan Carevin i Duskwood ger uppdraget, som ber spelaren att återvända till Darnassus och berätta för Thyn'tel Bladeweaver vad som hänt med Velinde och Scythe of Elune.",al={"uppdraget answered questions","answered questions classic","slutet på scythe of elune-uppdraget"}},{q="Vem var Velinde Starsong?",a="Velinde Starsong var en nattalvprästinna åt Elune och Sentinel Melyria Frostshadows föregångare i Ashenvale. Hon hade i uppdrag att hålla de demoniska krafterna i Felwood tillbaka. Hon fick Scythe of Elune, försvann sedan, och hennes spår ledde över havet till Duskwood.",al={"velinde starsong","vem är velinde","vad hände med velinde"}},{q="Var finns Scythe of Elune när uppdraget är slut?",a="Var Scythe of Elune befinner sig är centralt för undersökningen. Jonathan Carevin ber dig rapportera vad du har fått veta till Thyn'tel Bladeweaver i Darnassus.",al={"var finns scythe of elune","hittade vi skäran","scythe of elune plats"}},{q="Vilken koppling har Tyrande Whisperwind till Velinde?",a="Översteprästinnan Tyrande Whisperwind och Velinde Starsong var nära vänner innan Velinde försvann, vilket gjorde sökandet viktigt för nattalvernas ledarskap.",al={"tyrande och velinde","koppling till översteprästinnan"}},{q="Vem är Jonathan Carevin?",a="Jonathan Carevin är en mänsklig invånare i Duskwood som hjälper äventyraren att söka igenom de lokala gruvorna. Han lovar att hålla worgen i Duskwood i schack och skickar spelaren tillbaka till Kalimdor för att berätta för Velindes folk vad som hittats.",al={"jonathan carevin","vem ger answered questions"}},{q="Var finns Thyn'tel Bladeweaver?",a="Thyn'tel Bladeweaver är stationerad i Darnassus på ön Teldrassil. Hon tjänar nattalvernas ledarskap och övervakar sökandet efter försvunna väktare och prästinnor.",al={"var finns thyn'tel bladeweaver","thyn'tel bladeweavers plats","lämna in answered questions"}}},fx={["6f485fee"]={q="Varför skickar Jonathan Carevin dig tillbaka till Darnassus?",a="Jonathan Carevin inser att det som upptäcktes i gruvorna i Duskwood angår långt fler än Night Watch. Velinde Starsong tjänade nattalverna och gudinnan Elune, och Carevin anser att hennes öde och den oroande förlusten av Scythe of Elune är viktiga nyheter. De måste förmedlas direkt till hennes folk i Darnassus, inte begravas i gruvorna.",al={"varför vill jonathan carevin få detta gjort","jonathan carevins motiv","varför återvända till darnassus"}}},fp="18,296,14.461.1,19.372.1,18.380.1,37.259.1,25.269.1,54.168.1,48.163.1,24.241.0,38.171.0"}
P.entries["quest:1045"] = {n="Raene's Cleansing",s="Förklädda med Dartol's Rod of Transformation vinner äventyrarna Krolgs förtroende. Han är en okorrumperad furbolg nära Lake Mystral. Desillusionerad av både de arroganta nattalverna och den förruttnelse som fräter på hans eget folk ber Krolg dem döda den fördärvade hövdingen Ran Bloodtooth, så att furbolgerna kan hålla ordning bland de sina.",h="Förklädda med Dartol's Rod of Transformation vinner äventyrarna Krolgs förtroende.",kw={"ashenvale","bloodtooths vakt","korrumpering","dartols stav","furbolg","krolg","lake mystral","ran bloodtooth"},ang={["class:Druid"]="För druider som vigt sig åt att bevara Ashenvales balans står Ran Bloodtooth för de naturliga varelsernas tragiska fall, när de helt ger efter för demonisk korrumpering.",["faction:Alliance"]="Med hjälp av Dartols förtrollade stav agerar Alliansens kämpar som hemliga förmedlare för att kuva upproriska hövdingar långt bakom fiendens linjer.",["race:NightElf"]="Mötet med Krolg blir en obekväm spegel för nattalverna. Trots att de vaktat Ashenvale i tusentals år håller de lokala stammarna kaldoreis stolthet direkt ansvarig för den uråldriga Särningen och den kvardröjande smittan."},sec={{t="En bitter eremit",b="Nära Lake Mystrals vatten håller Krolg sig undan och vakar. Han är fördriven och trött, och hyser en djup bitterhet mot nattalverna. Han anklagar deras urgamla övermod för att ha fört fördärv över Kalimdor och väckt den mörka förruttnelse som härjar i Ashenvale. För att nå honom använder sökare Dartol's Rod of Transformation och rör sig oupptäckta bland furbolgerna. Men trots sitt bittra hat mot kaldorei söker Krolg varken meningslös slakt eller oskyldigas död."},{t="Hålla ordning bland de sina",b="Krolg tror att hans folk måste stå till svars för sina egna handlingar, i stället för att helt ge efter för den demoniska smitta som griper tag i stammarna. Den demoniska korrumperingen skapade inte deras brister, utan förstärkte bara deras värsta drifter. Ran Bloodtooth visar hur långt fallet gått. Han var redan hänsynslös och maktlysten före smittan, och tog villigt mörkret till sig. Nu utgör han ett existentiellt hot mot både alver och oskyldiga djur. Krolg vägrar låta sådan ondska tala för alla furbolger."},{t="Ett gemensamt ansvar",b="Krolg ber en främling, förklädd med Dartols magi, att fälla Ran Bloodtooth och hans elitvakter. Därmed skipas rättvisa utan att ytterligare inre stamstrider bryter ut. Rans död blir ett slag mot det växande vansinnet och förenar för en stund en bitter furbolg och en agent för Alliansen i en gemensam vilja att rena den heliga skogen."}},faq={{q="Varför hatar Krolg nattalverna?",a="Krolg ser nattalverna som arroganta väktare som genom historisk inblandning i farlig magi förde korrumpering över landet. Han håller dem ansvariga för Ashenvales korrumperade tillstånd och ursprungsstammarnas lidande.",al={"krolgs hat mot nattalver","varför hatar krolg alver","krolgs bakgrund"}},{q="Vem är Ran Bloodtooth?",a="Ran Bloodtooth är en korrumperad och maktlysten furbolghövding som slagit läger i bergen öster om Lake Mystral. De mörka krafter som förgiftar Ashenvale har drivit honom till vansinne, och hans våldslusta hotar alla skogens naturliga varelser.",al={"ran bloodtooths bakgrund","vem är bloodtooth","ran bloodtooth"}},{q="Varför vill Krolg att Ran Bloodtooth ska dö?",a="Trots att Krolg hyser agg mot nattalverna drar han en gräns vid urskillningslöst våld mot oskyldiga. Han anser att furbolgerna måste hålla ordning bland sina egna och att Rans korrumpering förvandlat honom till ett monster som hotar hela skogen.",al={"varför döda ran bloodtooth","krolgs motiv för bloodtooth"}},{q="Hur kan spelare i Alliansen tala med Krolg utan att bli anfallna?",a="Alliansens hjältar använder Dartol's Rod of Transformation, en förtrollad stav som de får under uppdragskedjan. Den låter dem anta en furbolgs skepnad och närma sig Krolg säkert.",al={"hur man talar med krolg","dartols stav och krolg","varför är krolg vänligt sinnad"}},{q="Var finns Ran Bloodtooth?",a="Ran Bloodtooth och hans vakter har ett läger längs bergen öster om Krolgs tillflyktsort nära Lake Mystral.",al={"ran bloodtooths plats","var finns ran bloodtooth","bloodtooth camp"}},{q="Hur hjälper det att döda Ran Bloodtooth till att rena Ashenvale?",a="När Ran Bloodtooth dödas försvinner en av de våldsammaste furbolgerna, stärkt av smittan, och ett hot mot alla skogens naturliga varelser. Som Krolg säger är skogen fortfarande korrumperad, men detta är ett litet steg mot att återställa dess forna glans.",al={"rensa ashvale med ran","varför ingår bloodtooth i raenes rening"}}},fp="17,259,15.361.0,18.424.0,13.319.1,36.169.0,22.228.0,40.198.0,63.164.0,32.101.0,55.227.0"}
P.entries["quest:1046"] = {n="Raene's Cleansing",s="Det här uppdraget avslutar sökandet efter vad som hände Teronis och arbetet med att hejda hotet från furbolgerna mot Ashenvale. Med Ran Bloodtooth's Skull från Krolg återvänder en äventyrare till Sentinel Raene Wolfrunner i Astranaar för att rapportera om den farofyllda resans slut.",h="Det här uppdraget avslutar sökandet efter vad som hände Teronis och arbetet med att hejda hotet från...",kw={"ashenvale","astranaar","dartol's rod","furbolg","krolg","raene wolfrunner","raenes rening","ran bloodtooth","teronis"},ang={["faction:Alliance"]="När du överlämnar Bloodtooths skalle befäster du Alliansens åtagande att försvara Astranaar och stå sida vid sida med Night Elf-väktarna.",["race:NightElf"]="För kaldorei hedrar ett slut på Ran Bloodtooths vrede fallna allierade som Teronis och bidrar till att återta heligheten i Ashenvales heliga lundar."},sec={{t="En bitter trofé",b="Efter att ha besegrat den våldsamma, korrumperade furbolg-hövdingen Ran Bloodtooth skickar Krolg mästaren tillbaka till Astranaar. Med Bloodtooths avhuggna skalle i handen återvänder du som bevis på att det vilda hotet i skogens djup har slagits ned med kraft."},{t="Till minne av Teronis",b="När Raene Wolfrunner tar emot skallen placerar hon den bredvid Dartol's Rod på en vördnadsvärd plats. Den dystra trofén hedrar minnet av Teronis, vars tragiska undersökning av hur de korrumperade furbolgerna kunde renas satte hela den desperata insatsen i rörelse."}},faq={{q="Vem är Ran Bloodtooth?",a="Ran Bloodtooth ansågs vara det våldsammaste korrumperade furbolg-hotet som terroriserade Ashenvales skogar. Hans nederlag undanröjer en farlig hövding som aktivt jagade skogens invånare.",al={"ran bloodtooth","bloodtooths skalle","vem var ran bloodtooth"}},{q="Varför vill Raene Wolfrunner ha skallen?",a="Raene Wolfrunner förvarar skallen bredvid Dartol's Rod som en symbol för seger och hågkomst. Den är ett obestridligt bevis på att Sentinel-styrkorna och deras allierade slog ned ett dödligt hot mot Ashenvale.",al={"varför skallen","wolfrunners skalle","vad gör raene med skallen"}},{q="Vem var Teronis?",a="Teronis var en Night Elf-utredare vars död tidigt i uppdragskedjan satte sökandet efter renande ädelstenar och Dartol's Rod i rörelse. När du slutför uppdraget fullföljer du hans oavslutade uppdrag.",al={"teronis","vem är teronis","teronis proud"}},{q="Var avslutas uppdraget?",a="Det slutförs i Astranaar, den främsta samlingsplatsen för Night Elf i Ashenvale, genom att tala med Sentinel Raene Wolfrunner.",al={"inlämningsplats","var är raene","raene wolfrunners plats"}},{q="Vem är Krolg?",a="Krolg är en allierad som ber dig ta Ran Bloodtooths avhuggna skalle tillbaka till Astranaar för att få erkännande och fira segern bland ditt eget folk.",al={"krolg","vem ger uppdraget","npc krolg"}},{q="Vad är Dartol's Rod?",a="Dartol's Rod är en kraftfull förtrollad relik som sattes samman under uppdragskedjan och har starka magiska band till furbolgernas natur och rening.",al={"dartol's rod","förvandlingens stav","furbolg-stav"}}},fx={d3b35236={q="Varför skickar Krolg dig till Astranaar?",a="Nu när Ran Bloodtooth, det största furbolghotet i Ashenvale, har dödats erkänner Krolg din triumf. Han är en okorrumperad furbolg som tror att du tillhör hans folk tack vare Dartol's Rod. Han ger dig Rans skalle och säger åt dig att återvända till din egen stam, visa upp trofén och njuta av segerns ära.",al={"varför vill krolg få detta gjort","krolgs motiv","varför skickar krolg skallen till astranaar"}}},fp="17,174,15.203.0,20.207.1,22.139.0,41.217.0,16.190.1,26.120.0,13.134.0,21.130.0"}
P.entries["quest:1052"] = {n="Down the Scarlet Path",s="Brother Anton säger att dina bedrifter mot de odöda i Desolace bara är en början, för farsotens verkliga fara finns i Lordaeron. Han ger dig ett rekommendationsbrev med sitt sigill till Raleigh the Devout i Southshore.",h="Brother Anton säger att dina bedrifter mot de odöda i Desolace bara är en början, för farsotens verkliga fara...",kw={"brother anton","ner den scharlakansröda stigen","hearthglen","rekommendationsbrev","lordaeron","raleigh the devout","scarlet monastery","southshore","tirisfal glades"},sec={{t="Korstogets fästen",b="Anton talar stolt om Scarlet Crusades renande bastioner i Lordaeron. Korståget gör anspråk på fästen hela vägen mellan Hearthglen och Tirisfal Glades. Anton säger att ditt arbete mot de odöda i Desolace har bevisat ditt värde, men farsotens verkliga fara finns i Lordaeron."},{t="Ett brev till Southshore",b="Anton skickar dig till Southshore, en stad i Eastern Kingdoms, för att leta efter en korsfarare vid namn Raleigh the Devout. Brevet bär Antons sigill, och Anton säger att det ska ge dig en eskort av Raleigh till en hedersplats i Scarlet Monastery."},{t="Raleighs reaktion",b="Raleigh bryter sigillet och läser brevet. Att höra att Anton fortfarande sprider ordet om Scarlet Crusade oroar Raleigh, som säger att något här är bortom vad du förstår."}},faq={{q="Vem skickar dig på den här resan?",a="Brother Anton ger dig ett förseglat rekommendationsbrev att ta med till Raleigh the Devout.",al={"vem ger ner den scharlakansröda stigen","uppdragsgivare ner den scharlakansröda stigen"}},{q="Vart skickas du?",a="Du beger dig till Southshore i Eastern Kingdoms för att hitta korsfararen Raleigh the Devout.",al={"vart ska man gå","var finns raleigh","ner den scharlakansröda stigen plats"}},{q="Vad säger Brother Anton att brevet ska göra?",a="Anton säger att när Raleigh får se hans förseglade brev kommer Raleigh att föra dig till en hedersplats i Scarlet Monastery.",al={"vad gör brevet","syftet med rekommendationsbrevet"}},{q="Vilket område gör Scarlet Crusade anspråk på i Lordaeron?",a="Brother Anton säger att Scarlet Crusade håller fästen som sträcker sig mellan Hearthglen och Tirisfal Glades, och han är stolt över dessa renande bastioner.",al={"scarlet crusades landområden","var finns scarlet crusades fästen"}}},fp="21,221,26.278.0,23.249.0,18.184.1,30.87.0,25.87.0,47.124.0,59.158.0"}
P.entries["quest:1054"] = {n="Culling the Threat",s="Culling the Threat är en defensiv alliansoperation som Raene Wolfrunner har gett i Astranaar. De nattalverna möter snabbt växande skaror av Thistlefur-furbolger direkt norrut och vill förekomma ett angrepp på bosättningen genom att döda deras krigsherre, Dal Bloodclaw. Det speglar den bistra verkligheten: forna skogsallierade måste nu rensas ut för att skydda kaldoreiernas hem.",h="Culling the Threat är en defensiv alliansoperation som Raene Wolfrunner har gett i Astranaar.",kw={"ashenvale","astranaar","culling the threat","dal bloodclaw","furbolg","raene wolfrunner","thistlefur"},ang={["class:Druid"]="Druider ser Thistlefur-stammens vansinne med djup sorg och bevittnar hur den kvardröjande smittan över Ashenvale driver ädla furbolger till blodtörstiga bestar.",["faction:Alliance"]="Att hålla Astranaar är avgörande för Alliansens försörjningslinjer och kommunikation genom centrala Kalimdor, så varje hot norr om staden kräver omedelbar taktisk prioritet.",["race:NightElf"]="För kaldoreierna är det en tragisk nödvändighet att slå ner furbolgerna. De sörjer att forna allierade har fördärvats, samtidigt som de tar till brutala åtgärder för att skydda Astranaar från undergång."},sec={{t="Ett hotande hot i norr",b="Astranaar ligger i hjärtat av Ashenvale och omges ständigt av faror. Direkt norr om bosättningen bor Thistlefur-furbolgerna. De var en gång fredliga invånare i den uråldriga skogen, men har fallit i vansinne och aggression, liksom många av sina fränder. Sentinel-spejare såg deras antal växa under de senaste månaderna och fruktade att ett samordnat angrepp mot själva Astranaar bara var en tidsfråga."},{t="Slå till mot hövdingen",b="I stället för att vänta på att Thistlefur-horden ska svämma över Astranaars anspråkslösa palissader ger Raene Wolfrunner resande i uppdrag att gå till anfall. Målet är Dal Bloodclaw, hövdingen vars ledarskap samlar och stärker The Den. Genom att hugga av stammens huvud och föra Dals skalle tillbaka till Astranaar hoppas Sentinels bryta furbolgernas samordning och vinna dyrbar tid åt den hårt prövade staden."}},faq={{q="Vem ger uppdraget Culling the Threat?",a="Raene Wolfrunner, en Sentinel-befälhavare stationerad i nattalvernas stad Astranaar i Ashenvale, erbjuder uppdraget.",al={"uppdragsgivare","vem ger uppdraget culling the threat","var hämtar jag culling the threat"}},{q="Varför vill Astranaar att Dal Bloodclaw ska dö?",a="Dal Bloodclaw leder Thistlefur-stammen direkt norr om Astranaar. Eftersom deras antal växer snabbt fruktar Wolfrunner att Bloodclaw ska leda en direkt räd mot staden om hans ledarskap inte undanröjs.",al={"varför döda dal bloodclaw","dal bloodclaw-lore","varför angripa thistlefur"}},{q="Varför är Thistlefur-furbolgerna fientliga mot nattalverna?",a="Furbolger och nattalver var historiskt sett allierade, men demoniska och fördärvande krafter i Ashenvale har drivit många stammar, däribland Thistlefur, in i våldsamt vansinne och territoriell paranoia.",al={"varför anfaller furbolger","fördärvade furbolger i ashenvale","thistlefur-lore"}},{q="Var finns Dal Bloodclaw?",a="Dal Bloodclaw håller till i Thistlefur Village och dess närliggande gravhögar, direkt norr om Astranaar i Ashenvale.",al={"dal bloodclaws plats","var finns dal bloodclaw"}},{q="Löser det furbolghotet för gott att döda Dal Bloodclaw?",a="Nej. Raene Wolfrunner säger att när Dal Bloodclaw dödas dämpas deras aggression bara för en tid. Så länge fördärvet håller Ashenvale i sitt grepp förblir furbolgerna en ständig fara.",al={"är thistlefur besegrat","räddade vi astranaar"}},{q="Vilket bevis på Dal Bloodclaws död krävs?",a="Du måste ta med dig Dal Bloodclaw's Skull och lämna den direkt till Raene Wolfrunner i Astranaar.",al={"vad ska jag ta med till raene","inlämningsföremål för culling the threat"}}},fx={d8b26d15={q="Vem är Dal Bloodclaw?",a="Dal Bloodclaw är hövding över Thistlefur-furbolgarna, som bor i sin by strax norr om Astranaar. Under hans ledning har de korrumperade furbolgarna snabbt blivit fler de senaste månaderna. De hotar att ta över de omgivande skogarna och inleda ett fullskaligt angrepp på nattalvernas bosättning.",al={"vem är dal bloodclaw","vem är furbolg-hövdingen","dal bloodclaws bakgrund"}},["05594dd8"]={q="Varför behöver Raene Wolfrunner en äventyrare i stället för Astranaars sentinels?",a="Sentinels i Astranaar är hårt ansatta när de försvarar själva staden mot hot som närmar sig från alla håll. Raene Wolfrunner måste stanna kvar och samordna det lokala försvaret. Därför passar dugliga resenärer bäst för att smyga in på Thistlefurs område och slå ut deras ledare innan ett angrepp hinner inledas.",al={"varför skicka mig","varför skickar raene inte vakter","varför anfaller inte astranaars sentinels"}}},fp="18,162,28.371.0,22.333.0,39.91.0,43.199.0,59.194.0,33.104.0,64.175.0,48.82.0"}
P.entries["quest:1055"] = {n="Raene's Cleansing",s="Det här uppdraget markerar att Rod of Transformation är färdig vid den gömda helgedomen i Ashenvale. När den heliga artefakten är sammansatt måste den genast återlämnas till dryaden Shael'dryn vid hennes månbrunnshelgedom.",h="Det här uppdraget markerar att Rod of Transformation är färdig vid den gömda helgedomen i Ashenvale.",kw={"ashenvale","astranaar","elune","gömd helgedom","månbrunn","raene's cleansing","rod of transformation","shael'dryn"},ang={["class:Priest"]="När du hjälper Shael'dryn återställer du en magisk relik som behövs för Raenes utredning i Ashenvale.",["faction:Alliance"]="Det är avgörande för Alliansens ställning i norra Kalimdor att säkra Ashenvale. Då skyddas Astranaar mot skoningslösa angrepp från korruptionen i området och fientliga styrkor.",["race:NightElf"]="Att återställa staven hjälper Raene att utreda furbolgernas angrepp, som hotar Astranaar och de omgivande skogsdungarna."},sec={{t="En återställd relik",b="Det mödosamma arbetet med att sätta samman Rod of Transformation når en stillsam vändpunkt vid den avskilda helgedomen, gömd djupt i Ashenvales vildmark. Skaftet, knoppen och Glowing Gem har fogats samman, och den återuppbyggda staven har förtrollats på nytt vid den gömda helgedomen. Dess magi är återställd. Artefakten är redo att återlämnas till Shael'dryn så att Raene kan utreda furbolgernas angrepp."},{t="Återvänd till Shael'dryn",b="När staven är färdig måste du snabbt återvända till Shael'dryn med den och beskedet. Dryaden väntar vid skogens stilla månbrunn och har väglett varje steg i arbetet med att återställa den. När du visar henne den sammansatta staven bekräftar det att dess magi är återställd. Det gör också att Sentinels försvarare kan ta nästa avgörande steg för att skydda sitt belägrade hemland."}},faq={{q="Vad är syftet med det här steget i uppdraget?",a="Nu när du har satt samman Rod of Transformation vid den gömda helgedomen behöver du bara ta den färdiga staven tillbaka till dryaden Shael'dryn, som väntar vid månbrunnen i norra Ashenvale.",al={"vad ska göras i raene's cleansing 7","vad är det här uppdraget","uppdragets mål"}},{q="Vem är Shael'dryn?",a="Shael'dryn är en dryad som vakar över en helig månbrunn i Ashenvale. Hon arbetar för att rena den uråldriga skogen från en korruption som sprider sig och skickar betrodda allierade för att samla reliker, rena delar och återställa heliga artefakter.",al={"shaeldryn","vem är shael'dryn","prästinna vid månbrunn"}},{q="Var finns Shael'dryn?",a="Shael'dryn håller till vid en stilla månbrunn i norra Ashenvale, öster om huvudvägen mellan Astranaar och Felwood. Hon är omgiven av det rofyllda vatten hon vakar över.",al={"shael'dryns plats","var finns shaeldryn","var finns månbrunnen"}},{q="Vad är Rod of Transformation?",a="Staven är Dartols magiska skapelse. Dess återställda kraft ska hjälpa Raene att utreda furbolgerna. Vilken form den ger upptäcks senare.",al={"vad är rod of transformation","rod of transformations historia","staven"}},{q="Varför är det så viktigt för Astranaar att staven sätts samman?",a="Raene Wolfrunner hoppas att staven ska låta en utredare närma sig furbolgerna och ta reda på mer om angreppen som hotar Astranaar.",al={"varför raene's cleansing","varför bryr sig astranaar","raenes betydelse"}},{q="Avslutar staven kedjan av rening?",a="Nej. Shael'dryn ber dig sedan återvända till Raene Wolfrunner i Astranaar och berätta att staven är färdig.",al={"är det här det sista uppdraget","slutar raene's cleansing här","slutet på kedjan"}}},fp="17,204,16.231.0,20.247.0,47.140.0,18.221.0,28.149.0,34.163.0,52.133.0,48.105.0"}
P.entries["quest:1057"] = {n="Reclaiming the Charred Vale",s="Reclaiming the Charred Vale är ett alliansuppdrag som erbjuds av Keeper Albagorm på toppen av Stonetalon Peak. Äventyrare får i uppdrag att decimera de aggressiva Bloodfury-harpierna som håller till i den förstörda dalen The Charred Vale, så att druider och väktare kan börja läka det svedda landskapet.",h="Reclaiming the Charred Vale är ett alliansuppdrag som erbjuds av Keeper Albagorm på toppen av Stonetalon Peak.",kw={"bloodfury","the charred vale","harpier","keeper albagorm","reclaiming the charred vale","stonetalon","stonetalon peak"},ang={["class:Druid"]="Som Cenarion Circles förvaltare och naturens harmonis försvarare hjälper druiderna Keepers direkt med att rensa bort fördärvade bon, så att magisk återbeskogning kan inledas.",["faction:Alliance"]="Att säkra de höga passen och de södra dalarna skyddar de utsatta Night Elf-bosättningarna och helgedomarna kring Stonetalon Peak från rovdjurshot.",["race:NightElf"]="Night Elves vördar Stonetalon Mountains vilda skogar. Att rensa bort de vidriga harpierna från heliga dungar som vanhelgats av främmande maskiner är ett akut kall."},sec={{t="Den sårade dalen",b="Söder om Stonetalon Peak ligger The Charred Vale, en gång en frodig alpin oas, nu reducerad till aska och pyrande ruiner. Förödelsen började när en mekaniserad skogsavverknings- och gruvarmé svepte genom de heliga bergsklipporna, fällde träden och gav näring åt okontrollerade bränder. För väktarna kring Stonetalon är det ett outhärdligt sår i vildmarken att se urgammal skog falla offer för industriell girighet."},{t="Harpiernas hot",b="Mekaniska bränder satte landskapet i lågor, men en opportunistisk invasion slog rot i askan. De grymma Bloodfury-harpierna svärmade in över de rökiga lågländerna, byggde bon och överföll aggressivt alla som närmade sig dalen. Keeper Albagorm och hans allierade kan inte ens beträda marken för att så förnyelsens frön, eftersom Bloodfury-harpierna våldsamt vägrar alla utomstående passage."},{t="Röj väg för förnyelsen",b="Innan någon verklig återställning kan börja måste Bloodfury-stammens boplatser slås sönder. Albagorm ger erfarna allianskrigare i uppdrag att tränga djupt in bland dem och dräpa jägare, bakhållskrigare och roguefeathers. Att decimera deras rovlystna flockar är det viktiga första steget mot att återta det som tillhör naturen och ge skogsandarna utrymme att andas igen."}},faq={{q="Vad är The Charred Vale?",a="The Charred Vale är en dal inbäddad i den sydvästra delen av Stonetalon Mountains. En gång var den en frodig, grönskande skog, men eld slukade den och brände den ända ner till berggrunden när industriella skogsavverkare exploaterade landet utan hämningar.",al={"lore om the charred vale","vad hände med the charred vale","varför brann the charred vale"}},{q="Vem är Keeper Albagorm?",a="Keeper Albagorm är en skogsväktare och naturvårdare som bor vid alliansens bosättning på Stonetalon Peak. Som naturens och skogsandarnas beskyddare ägnar han sig åt att hejda förödelsen i bergen och driva tillbaka inkräktande bestar.",al={"keeper albagorm","vem ger reclaiming the charred vale","lore om albagorm"}},{q="Varför bor harpier i The Charred Vale?",a="Bloodfury-harpierna är aggressiva, opportunistiska asätare som trivs i störda och fördärvade områden. När elden jämnade dalen med marken flyttade flocken in för att härska över den öde sänkan och anfalla alla som försökte ta sig in.",al={"bloodfury-harpier","varför harpier här","bloodfury-harpier i stonetalon"}},{q="Vem satte eld på The Charred Vale från början?",a="Keeper Albagorm pekar ut en girig mekaniserad armé av industrialister som slet upp kullarna som de skyldiga. Okontrollerade skogsmaskiner och explosiv expansion orsakade förödande bränder som slukade skogen.",al={"vem brände the charred vale","mekaniserad armé industrialister","venture company the charred vale"}},{q="Vad måste göras när harpierna har decimerats?",a="Att rensa bort harpierna säkrar bara området. När Bloodfury-harpiernas antal har minskats riktar Keeper Albagorm in sig på att plantera frön och kanalisera läkande magi för att locka nytt liv ur den svedda jorden.",al={"nästa uppdrag the charred vale","reclaiming the charred vale del 2","vad händer härnäst"}},{q="Är uppdraget tillgängligt för äventyrare i Horde?",a="Nej. Keeper Albagorm utgår från alliansens utpost på toppen av Stonetalon Peak, så just detta uppdrag att rensa bort Bloodfury-harpierna är begränsat till alliansens hjältar.",al={"kan horde göra det här uppdraget","horde reclaiming the charred vale"}}},fx={d7987d6f={q="Varför vill Keeper Albagorm att Bloodfuries ska utrotas?",a="Som skogslundens väktare och skogsandarnas beskyddare vill Albagorm läka och återställa The Charred Vales sargade, brända landskap till den frodiga fristad det en gång var. Men de aggressiva Bloodfury-harpiorna som svärmar över ruinerna blockerar all tillgång och hindrar aktivt Cenarion Circle från att inleda sina heliga riter för förnyelse och återväxt.",al={"varför rensa the charred vale","keeper albagorms motiv","varför döda harpiorna i the charred vale"}}},fp="27,213,18.340.0,16.330.0,28.321.0,25.207.0,23.215.0,43.169.0,52.191.0,45.152.1,45.139.0"}
P.entries["quest:1058"] = {n="Jin'Zil's Forest Magic",s="Vid Malaka'jins lilla utpost har Witch Doctor Jin'Zil fångat tre nattalviska spejare i grova järnburar. I stället för att avrätta dem direkt eller hålla dem som gisslan ber den excentriske trollen Hordens äventyrare att samla vildmarksingredienser från Stonetalon Peak för att blanda till en ohygglig dos ”skogsmagi”.",h="Vid Malaka'jins lilla utpost har Witch Doctor Jin'Zil fångat tre nattalviska spejare i grova järnburar.",kw={"courser eye","fey dragon","skogsmagi","jin'zil","malaka'jin","fångar","stonetalon","twilight runner","häxdoktor"},ang={["class:Druid"]="Att se heliga fey drakes, ståtliga courser-hästar och uråldrig skogssav skördas för att brygga ett dödligt gift är en mörk förvrängning av naturens balans.",["faction:Horde"]="Att säkra Malaka'jin innebär att kuva nattalvernas motstånd i hela bergskedjan, även med en tillbakadragen häxdoktors okonventionella metoder.",["race:NightElf"]="Den plågsamma avrättningen av nattalviska fångar med förvridna skogsmaterial är en av Hordens grymmare handlingar i Stonetalon.",["race:Troll"]="Jin'Zils makabra humor och praktiska bruk av voodooalkemi är typiska kännetecken för Darkspear-häxdoktorernas hantverk."},sec={{t="En besk brygd",b="I Malaka'jins ravin av röd klippa utövar Witch Doctor Jin'Zil sitt hantverk under Hordens vaksamma blick. När tre nattalviska fångar hamnar i hans klor avstår Jin'Zil från vanlig slakt och tillreder i stället en hånfull ritual särskilt riktad mot sina fångna skogsfiender. Han skickar resenärer norrut till de otämjda bergstopparna för att samla en mängd lokala delar: tjock trädsaft, morrhår från rovdjurslika twilight runners, en skimrande fey dragon-fjäll och mängder av ögon plockade ur skogens courser-hästar."},{t="En smak av hemmet",b="Bakom Jin'Zils lekfulla uppsyn döljer sig en grym trollhumor. Under förevändningen att få de fängslade alverna att ”känna sig som hemma” utan en skog att leka i bildar blandningen av magiska djur och koncentrerad sav ett dödligt, flyktigt gift. När den släpps ut i grottan kväver den stinkande brygden de fångna på fläcken. Medan deras kroppar dör upplöses alvernas förfädersandar till lysande irrbloss som svävar ut i bergen och lämnar de tomma burarna bakom sig."}},faq={{q="Vem är Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil är en Darkspear-troll som är stationerad vid Malaka'jin i södra Stonetalon Mountains. Han bidrar till Hordens krigsinsats mot nattalverna genom att utöva traditionell trollalkemi, voodoo och förhör.",al={"vem är jin'zil","witch doctor jin'zil","jin'zils historia"}},{q="Varför vill Jin'Zil ha så många courser-ögon?",a="Jin'Zil hävdar att man helt enkelt inte kan brygga kraftfull skogsmagi utan en stor mängd ögon. Trollens häxdoktorer använder ofta märkliga organiska ingredienser i sina brygder, men den absurda mängden speglar också hans excentriska och hämndlystna personlighet.",al={"varför courser-ögon","30 courser-ögon","varför så många ögon"}},{q="Vad händer med de instängda nattalverna när uppdraget är slutfört?",a="När Jin'Zil har fått ingredienserna släpper han ut det giftiga brygget i hela grottan. Blandningen förgiftar de tre fångarna dödligt och dödar dem, varefter deras andar frigörs som irrbloss som driver bort i vildmarken.",al={"vad händer med alverna","de instängda alvernas öde","jin'zils fångar"}},{q="Var hittar man alla ingredienser?",a="Courser-ögonen och Stonetalon Sap kan samlas kring Mirkfallon Lake och i de norra högländerna. Morrhåren från twilight runners och det sällsynta Fey Dragon Scale finns längre norrut nära Stonetalon Peak, där bergets magiska bestar strövar.",al={"var hittar man ingredienser till skogsmagi","var finns stonetalon sap","var finns fey dragon scale"}},{q="Varför strider Horden mot nattalverna i Stonetalon?",a="Hordens skogsavverkning i grannlandet Ashenvale har väckt hårt motstånd från Sentinels, och nattalverna håller fortfarande Stonetalon Peak och dess heliga lundar ovanför Hordens utposter som Malaka'jin.",al={"varför strida mot nattalver i stonetalon","konflikten mellan horden och nattalverna i stonetalon","kriget i stonetalon"}},{q="Varför förvandlas de döende alverna till irrbloss?",a="Irrbloss är andar från avlidna nattalver som fortfarande är starkt bundna till naturen. När de dör antar deras själar denna lysande, trädliknande form i stället för att dröja kvar som vanliga spöken eller skuggor.",al={"varför blir alver irrbloss","alviska irrbloss i grottan","irrblossens historia"}}},fx={["58b555cd"]={q="Varför vill Witch Doctor Jin'Zil att det här ska göras?",a="Witch Doctor Jin'Zil har fångat tre nattalvssentinels och låst in dem i burar i sin grotta i Malaka'jin. I stället för att bara avrätta dem vill han koka ihop en elak brygd som hånfullt kallas \"skogsmagi\". Genom att blanda kraftfulla, råa essenser från deras älskade vildmark tänker han skapa ett dödligt gift som vänder skogens egna gåvor mot fångarna.",al={"varför skogsmagi från jin'zil","varför skapa skogsmagi","jin'zils motiv"}},["840e6ff0"]={q="Vad ska Stonetalon Sap användas till?",a="Den tjocka kådan, som utvinns ur regionens levande träd och saftbestar, fungerar som en trögflytande och klibbig bas för Jin'Zils brygd. Den binder samman de andra skogsämnena och förankrar hans giftiga blandning i bergens råa essens.",al={"stonetalon sap användning","varför samla kåda","vad ska kådan användas till"}},["70cbdf3f"]={q="Vad ska Fey Dragon Scale användas till?",a="Fey dragons är mystiska varelser som är djupt förbundna med Stonetalon Peaks smaragdgröna kraft och Kaldorei. Jin'Zil behöver en fjällbit för att fylla sin brygd med deras medfödda magiska skydd och vilda energier, och förvrida den till ett dödligt gift särskilt anpassat för att skada nattalver.",al={"fey dragon scale användning","varför behövs fey dragon scale","vad ska fey dragon scale användas till"}},a0fa7c69={q="Vad ska Twilight Whisker användas till?",a="De här morrhåren tas från Twilight-löpare som smyger omkring i skogarna. De tillför blandningen den vilda, rovdjurslika instinkten hos Stonetalon Mountains inhemska rovdjur och gör brygden till ett aggressivt gift.",al={"twilight whisker användning","varför twilight whiskers","vad ska twilight whiskers användas till"}}},fp="22,192,13.425.0,15.455.1,28.193.0,43.203.0,62.159.1,35.219.0,52.192.0,39.175.0"}
P.entries["quest:1059"] = {n="Reclaiming the Charred Vale",s="Reclaiming the Charred Vale är ett budbäraruppdrag från Keeper Albagorm i Stonetalon Peak. Efter att tillfälligt ha hejdat de lokala harpyorna skickar Albagorm en alliansresenär långt söderut till Feralas för att värva hjälp från druiden Falfindel Waywarder.",h="Reclaiming the Charred Vale är ett budbäraruppdrag från Keeper Albagorm i Stonetalon Peak.",kw={"bloodfury-harpyor","the charred vale","falfindel waywarder","feralas","thalanaar","keeper albagorm","stonetalon peak","thousand needles"},ang={["class:Druid"]="Uppdraget lyfter fram cenariernas plikt att sträcka sig bortom de lokala garnisonerna och kalla fram naturandar för att läka marker som förstörts av onaturlig ödeläggelse.",["faction:Alliance"]="Alliansens fäste i Stonetalon Peak är beroende av förbindelser mellan utposter vid gränsen, genom Kalimdors vidsträckta och omstridda områden."},sec={{t="Dalens ärr",b="The Charred Vale i södra Stonetalon Mountains är fortfarande en askfylld påminnelse om katastrofal förödelse. Alliansstyrkor under Keeper Albagorm har slagit tillbaka mot de härjande Bloodfury-harpyor som häckar i ruinerna, men att driva bort dem är bara en tillfällig lösning. Albagorm inser att våld inte ensamt kan läka den sargade jorden innan harpyorna samlar sig och återtar sin dominans."},{t="En vädjan söderut",b="För att återställa de förkolnade markerna för gott behöver lundens väktare mystisk hjälp som de själva saknar. Albagorm skickar en kurir långt söderut, förbi saltöknarna och ravinerna i Thousand Needles, till Thalanaar vid gränsen till Feralas. Där väntar Falfindel Waywarder, en nattalvlig druid som sägs besitta den sällsynta förmågan att kalla fram uråldriga skogsandar som kan återuppliva den döda jorden."}},faq={{q="Vem är Keeper Albagorm?",a="Keeper Albagorm är en lundväktare stationerad i Stonetalon Peak. Där leder han Alliansens försök att rena och återställa det fördärvade Charred Vale.",al={"vem är albagorm","keeper albagorm"}},{q="Var finns Falfindel Waywarder?",a="Falfindel Waywarder är stationerad i Thalanaar, vid den västra gränsen där Thousand Needles övergår i Feralas frodiga vildmark.",al={"var finns falfindel","falfindel waywarders plats","hitta waywarder"}},{q="Varför skicka bud efter en druid ända till Feralas?",a="Keeper Albagorm anser att Falfindel är särskilt lämpad att åkalla mäktiga, uråldriga skogsandar som kan vända den djupa ekologiska förödelsen i Charred Vale.",al={"varför åka till feralas","varför falfindel"}},{q="Vilket hot finns i Charred Vale?",a="Dalen översvämmas av fientliga Bloodfury-harpyor, eldvarelser och vilddjur som frodades efter att landet bränts.",al={"fiender i charred vale","vad anfaller dalen"}},{q="Kräver det här uppdraget strid?",a="Nej. Den andra delen av Reclaiming the Charred Vale är en ren färd över land. Du ska leverera Albagorms meddelande genom centrala och södra Kalimdor.",al={"är uppdraget svårt","strid i charred vale-uppdraget"}},{q="Hur tar man sig från Stonetalon till Thousand Needles?",a="Resenärer måste ta sig österut från Stonetalon Mountains till The Barrens, färdas söderut längs Gold Road, åka nerför The Great Lift till Thousand Needles och fortsätta västerut mot Feralas.",al={"hur tar man sig till thousand needles","resväg till feralas"}}},fx={edca7440={q="Varför vill Keeper Albagorm att det här ska göras?",a="Du har fällt många av Bloodfury-harpiorna, men Keeper Albagorm vet att de snart samlar sig igen och återtar greppet om The Charred Vale om inget varaktigt görs. Marken ligger fortfarande i ruiner och är sårbar, och att bara utrota bestar kan inte läka den brända jorden. Han behöver snabbt de mäktiga skogsandar som bara en druid som Falfindel Waywarder kan kalla fram, så att livet återvänder till dalen innan harpiorna samlar sig och omintetgör dina framsteg.",al={"keeper albagorms motiv","varför skicka efter falfindel","varför återta the charred vale"}}},fp="27,175,21.370.0,19.344.0,23.139.0,37.96.0,44.129.0,40.116.0,31.89.0,50.169.0"}
P.entries["quest:106"] = {n="Young Lovers",s="Young Lovers är ett uppdrag i Elwynn Forest om den förbjudna kärleken mellan Maybell Maclure och Tommy Joe Stonefield. Deras familjer är bittra rivaler, så Maybell ber en äventyrare i hemlighet lämna ett innerligt kärleksbrev till Tommy Joe vid flodstranden.",h="Young Lovers är ett uppdrag i Elwynn Forest om den förbjudna kärleken mellan Maybell Maclure och Tommy Joe...",kw={"elwynn forest","fejd","kärleksbrev","the maclure vineyards","maybell maclure","the stonefield farm","tommy joe stonefield","young lovers"},ang={["faction:Alliance"]="Alliansens äventyrare som färdas genom Elwynn Forest får ofta bära meddelanden mellan de rivaliserande familjerna Stonefield och Maclure. De upptäcker att lokala hjärtesorger består även när faror hotar hela kungariket.",["race:Human"]="För människor som känner Elwynn Forest är det gamla agget mellan familjerna Stonefield och Maclure en välkänd lokal fejd. Därför är romansen mellan Maybell och Tommy Joe en känslig grannskandal."},sec={{t="En förbjuden romans",b="I Elwynn Forests lantliga landskap splittrar en bitter fejd två grannfamiljer som driver gårdar: familjerna Stonefield och Maclure. Trots fiendskapen mellan familjerna har unga Maybell Maclure förälskat sig djupt i Tommy Joe Stonefield. Hon kan inte besöka honom öppet utan att väcka familjens vrede, så Maybell ber resande att i hemlighet föra brev över gränsen mellan de rivaliserande gårdarna."},{t="Möte vid floden",b="För att hålla sin kärlek hemlig för vaksamma släktingar tillbringar Tommy Joe Stonefield sina dagar vid den stilla flodstranden strax väster om The Stonefield Farm. När han får Maybell's Love Letter känner han en enorm lättnad och längtar efter henne igen. Saknaden blir outhärdlig, och det leder till fler hemliga försök att föra de unga älskande samman trots fejden."}},faq={{q="Vem ger uppdraget Young Lovers?",a="Maybell Maclure ger uppdraget vid The Maclure Vineyards i Elwynn Forest. Hon är djupt förälskad i Tommy Joe Stonefield, men deras familjer är bittra rivaler och hindrar dem från att träffas öppet.",al={"vem ger young lovers","vem inleder young lovers","uppdragsgivare för young lovers"}},{q="Var hittar man Tommy Joe Stonefield?",a="Tommy Joe Stonefield står vid flodstranden strax väster om The Stonefield Farm, som ligger rakt väster om The Maclure Vineyards i Elwynn Forest. Han väntar där, utom synhåll för sin vaksamma familj.",al={"var finns tommy joe stonefield","hitta tommy joe","tommy joes plats"}},{q="Varför hålls Maybell och Tommy Joe åtskilda?",a="Familjerna Stonefield och Maclure är bittra fiender och bär på ett gammalt agg mot varandra. På grund av den djupt rotade fiendskapen låter ingen av familjerna sina barn umgås, så det unga paret tvingas kommunicera genom hemliga brev.",al={"varför är familjerna osams","fejden mellan stonefield och maclure","varför kan maybell och tommy joe inte träffas"}},{q="Vilket föremål ska du leverera under uppdraget?",a="Du ska lämna Maybell's Love Letter direkt till Tommy Joe Stonefield vid floden. Brevet förmedlar hennes starka kärlek och försäkrar Tommy Joe om hennes hängivenhet trots fejden mellan deras familjer.",al={"vad är maybells brev","vad lämnar man under young lovers","kärleksbrev i elwynn"}},{q="Hur reagerar Tommy Joe på brevet?",a="När Tommy Joe får Maybells brev blir han överlycklig och säger att Maybell är ljuset i hans trista liv. När han läser hennes ord blir saknaden outhärdlig, och han börjar söka ett sätt för dem att träffas.",al={"hur reagerar tommy joe","tommy joes svar","vad händer när man lämnar brevet"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig i södra Elwynn Forest, mellan The Maclure Vineyards och floden som gränsar till The Stonefield Farm. Det är en stillsam lantlig del av människornas kungarike, där små familjekonflikter skapar oro.",al={"var utspelar sig young lovers","young lovers område","the stonefield farms plats"}}},fp="12,138,19.252.0,24.243.0,33.165.0,40.161.0,41.162.0,43.130.0,39.166.0,33.194.0"}
P.entries["quest:1060"] = {n="Letter to Jin'Zil",s="Letter to Jin'Zil är ett Horde-leveransuppdrag som anförtros åt äventyrare som har dödat Serena Bloodfeather i norra The Barrens. Orcen och skurken Darsok Swiftdagger skickar dig över gränsen till de karga klipporna i Stonetalon Mountains för att berätta för hans gamla vän, Witch Doctor Jin'Zil, att harpyornas matriark har dött.",h="Letter to Jin'Zil är ett Horde-leveransuppdrag som anförtros åt äventyrare som har dödat Serena Bloodfeather...",kw={"bloodfury","darsok swiftdagger","harpyor","letter to jin'zil","malaka'jin","serena bloodfeather","stonetalon mountains","witch doctor jin'zil"},ang={["faction:Horde"]="När du levererar brevet går Hordes krigare från att lugna handelsvägarna i The Barrens till att etablera fästen i de omstridda Stonetalon Mountains.",["race:Troll"]="Jin'Zils grotta i Malaka'jin är en viktig andlig och taktisk utpost för Darkspear Trolls som vill säkra bergspassen."},sec={{t="Ett budskap till bergen",b="När harpyhotet kring norra The Barrens systematiskt undanröjs avslöjar Darsok Swiftdagger att de bevingade plundrarna aldrig hörde hemma i buskmarkerna. Witchwing- och Bloodfeather-flockarna kom från de karga bergsryggarna i Stonetalon Mountains i nordväst. Darsok imponerades av din skicklighet när du dödade Serena Bloodfeather och skickar dig till de farliga bergstopparna med nyheten om hennes död till sin gamla bekant, Witch Doctor Jin'Zil, som bor i trollbosättningen Malaka'jin."},{t="Ekon från Bloodfury Claws",b="När du når Jin'Zil i hans skuggiga grotta får du veta mer om ett äldre kapitel i Hordes historia. När trollhäxdoktorn hör att Serena Bloodfeather har fallit minns han den tidigare kampanjen då skuggjägaren Rokhan och den kringvandrande bestmästaren Rexxar dödade Serenas äldre syster, Bloodfeather. Serenas utplåning ger en känsla av slutgiltighet åt den långvariga fejden mellan Hordes gränsposter och Kalimdors blodtörstiga harpyor."}},faq={{q="Vem ger uppdraget Letter to Jin'Zil?",a="Darsok Swiftdagger ger uppdraget vid The Crossroads i The Barrens. Han erbjuder det först när du har slutfört jakten på Serena Bloodfeather.",al={"uppdragsgivare","var får man uppdraget","vem startar letter to jin'zil"}},{q="Var hittar jag Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil bor i en grotta vid Malaka'jin, ett läger för Darkspear Trolls strax utanför huvudvägen från The Barrens in i Stonetalon Mountains.",al={"var finns jin'zil","jin'zils plats","malaka'jins plats"}},{q="Varför skickar Darsok dig till Stonetalon Mountains?",a="Darsok vill berätta för sin gamla vän Jin'Zil att harpyhotet är undanröjt efter Serena Bloodfeathers död. Samtidigt vill han leda en skicklig äventyrare mot de större utmaningar som väntar Horden i Stonetalon-bergen.",al={"varför åka till stonetalon","varför darsok skickar brevet"}},{q="Vilken tidigare syster till Serena syftar Jin'Zil på?",a="Jin'Zil nämner Bloodfeather, en äldre harpy som terroriserade Kalimdor för många år sedan. Hon dödades av skuggjägaren Rokhan och halvorchen Rexxar när de reste tillsammans med den grundande Horden.",al={"serenas äldre syster","rokhan och rexxar harpy","bloodfury"}},{q="Är det här uppdraget del av en större kedja?",a="Ja. Det avslutar kedjan av harpyjakter i norra The Barrens, efter Harpy Raiders, Harpy Lieutenants och Serena Bloodfeather, och leder samtidigt vidare till Stonetalon Mountains.",al={"uppdragskedja","förkunskaper","vad leder hit"}},{q="Vilken fraktion kan ta sig an uppgiften?",a="Det här är uteslutande ett Horde-uppdrag, eftersom både Darsok Swiftdagger och Witch Doctor Jin'Zil tjänar Hordes gränsområden.",al={"är det bara för horden","kan alliansen göra uppdraget"}}},fx={a93c7265={q="Varför behöver Darsok att du levererar brevet till Jin'Zil?",a="Darsok Swiftdagger är fortfarande stationerad vid The Crossroads och håller vakt över norra The Barrens. Han har sett dig framgångsrikt rensa ut witchwing-harpiorna och döda deras ledare Serena Bloodfeather. Därför ser han dig som en beprövad och duglig budbärare som klarar den farliga resan in i Stonetalon Mountains. Nyheten om Serenas fall ger dig också en god anledning att utforska områden bortom de torra slätterna.",al={"varför skicka mig med brevet till jin'zil","varför kan darsok inte leverera brevet","varför jag med brevet till jin'zil"}}},fp="17,198,28.423.0,29.339.1,38.124.0,38.147.0,49.214.0,55.201.0,37.167.0,37.114.0"}
P.entries["quest:1061"] = {n="The Spirits of Stonetalon",s="Oro råder bland Stonetalon Mountains andar, och Zor Lonetree skickar Hordens mästare västerut för att ta reda på varför. Från Orgrimmar reser de förbi The Crossroads och rapporterar direkt till Seereth Stonebreak nära Greatwood Vale.",h="Oro råder bland Stonetalon Mountains andar, och Zor Lonetree skickar Hordens mästare västerut för att ta reda...",kw={"the crossroads","avskogning","greatwood vale","seereth stonebreak","stonetalon mountains","visdomens dal","venture company","zor lonetree"},ang={["class:Shaman"]="Som schaman hör du elementen vädja om att du ska hela bandet mellan jorden och allt levande.",["faction:Horde"]="Som medlem av Horden hjälper du till att hålla färdvägarna mellan Stonetalon Mountains och The Barrens fria från laglösa handelssyndikat.",["race:Tauren"]="Som tauren har du en kulturell plikt att lugna jorden och försvara heliga skogar mot goblinernas skogsavverkning."},sec={{t="Ett rop från väster",b="I Grommash Hold lyssnar Zor Lonetree till naturen och känner en djup oro från Stonetalon Mountains. De elementära andarna på dess klippiga toppar är rasande när skogsavverkningen tränger in i deras skogar. Hordens schamaner hör oron och fruktar att förödelsen i de västra högländerna ska rubba Kalimdors andliga balans."},{t="Industriell skogsavverkning",b="Venture Company, ett skrupelfritt goblinsyndikat, avverkar timmer i Greatwood Vale. Dess kommersiella arbetslag använder aggressiva maskiner, sågar och råstyrka för att skövla den uråldriga skogen i stället för att avverka hållbart. Horden skickade Seereth Stonebreak, en ung schaman, för att hålla uppsikt över skogen från gränslandet och samla försvarare mot skövlarna."}},faq={{q="Vem ger uppdraget och var finns personen?",a="Zor Lonetree, en orkrådgivare, erbjuder detta i Grommash Hold i Orgrimmar.",al={"uppdragsgivare","var får man uppdraget","zor lonetrees plats"}},{q="Var hittar jag Seereth Stonebreak?",a="Seereth Stonebreak väntar i Stonetalon Mountains, längs stigen nära Greatwood Vale, strax efter den östra ingången från norra The Barrens.",al={"seereths plats","var finns seereth stonebreak","lägret i stonetalon"}},{q="Varför är andarna i Stonetalon arga?",a="Goblinerna i Venture Company kalhugger bergsskogarna och provocerar landets elementära väktare.",al={"varför är andarna arga","oro i stonetalon","arga andar"}},{q="Hur tar jag mig till Stonetalon Mountains från Orgrimmar?",a="Res söderut från Orgrimmar genom The Barrens till The Crossroads, följ sedan vägen västerut genom det klippiga passet in i Stonetalon Mountains.",al={"vägen till stonetalon","hur tar man sig till stonetalon","resväg till stonetalon"}},{q="Vad händer efter att jag talat med Seereth?",a="Vid sitt läger ger Seereth Stonebreak dig Goblin Invaders och skickar dig till Greatwood Vale för att göra dig av med skogsarbetarna och sätta stopp för deras verksamhet.",al={"nästa uppdrag","uppföljning","vad händer efter the spirits of stonetalon"}},{q="Varför ingriper Horde mot avskogningen i Stonetalon?",a="Tauren- och orkschamaner vördar de elementära andarna. Goblinernas vårdslösa skogsavverkning skadar landets andliga harmoni och hotar gränsen mot The Barrens.",al={"varför bryr sig horde","taurenernas intresse för stonetalon"}}},fx={["4d15c2b8"]={q="Varför vill Zor Lonetree att det här ska göras?",a="Zor Lonetree lyssnar till naturen och har hört landets desperata rop. Goblinernas okontrollerade skövling och bränning av skogen i Stonetalon Mountains har gjort elementarandarna djupt upprörda. För att läka landet och bevara balansen svarar han på Seereth Stonebreaks brådskande begäran om förstärkning. Han skickar dugliga äventyrare till bergen innan förödelsen sprider sig ytterligare.",al={"varför skickar zor dig","zor lonetrees motiv","varför zor lonetree och andarna i stonetalon"}}},fp="25,214,19.326.0,24.353.0,49.72.0,36.147.0,40.107.0,55.135.0,44.142.0,59.153.0"}
P.entries["quest:1062"] = {n="Goblin Invaders",s="Goblin Invaders är ett uppdrag för Horden som Seereth Stonebreak ger vid gränsen mellan The Barrens och Stonetalon Mountains. Det skickar Hordens krigare till Windshear Crag för att gå till direkt angrepp mot Venture Companys skogshuggare, som ödelägger områdets urgamla skogar.",h="Goblin Invaders är ett uppdrag för Horden som Seereth Stonebreak ger vid gränsen mellan The Barrens och...",kw={"goblin","greatwood vale","skogshuggare","seereth stonebreak","andar","stonetalon mountains","venture company","windshear crag"},ang={["class:Druid"]="Den tanklösa förstörelsen av levande dungar och slakten av urgamla träd i Windshear Crag är ett direkt brott mot den naturliga ordning som druiderna svurit att försvara.",["class:Shaman"]="Schamaner känner starkt hur de lokala elementarerna och naturandarna ropar. Röken och förödelsen från goblinernas maskiner har drivit dem till blint raseri.",["faction:Horde"]="Genom att hejda Venture Company säkras gränslandet mellan The Barrens och de högre passen, så att fientliga handelssyndikat inte kan befästa sin ställning i centrala Kalimdor.",["race:Tauren"]="Skändningen av Stonetalon skogar och jordandarnas plågor gör konfrontationen med Venture Company till en brådskande plikt för varje tauren som vördar Jordmodern."},sec={{t="En skog i vånda",b="Venture Company har trängt djupt in i Stonetalon Mountains och skurit breda stråk av förödelse genom klippor och dalar. Deras avverkning skövlar sluttningarnas träd och sätter eld på snårskogen, vilket lämnar efter sig glödande sår. För tauren och deras allierade är detta inte bara en anskrämlig gruv- och timmerverksamhet; urandarna som är bundna till Stonetalon ylar i plågor. Seereth Stonebreak, som är stationerad längs bergsgränsen, ser att dessa andar har blivit blinda av plåga och raseri under goblinernas skoningslösa angrepp."},{t="Våldets språk",b="Vädjan om förnuft eller diplomati betyder ingenting för Venture Companys hänsynslösa chefer och anställda, vars enda mål är rå vinst. Seereth inser detta och beordrar resenärer att ta sig förbi Greatwood Vale och rakt in i Windshear Crag för att röja undan femton skogshuggare. Genom att möta företagsgirighet med väpnat våld försöker Horden stoppa skogsskövlingen och vinna tid åt taurenäldste att lugna landets upprörda andar."}},faq={{q="Vem är Seereth Stonebreak?",a="Seereth Stonebreak är en orkschaman som är stationerad nära den södra gränsen mellan The Barrens och Stonetalon Mountains. Hon håller uppsikt över fientliga fraktioners intrång och arbetar för att skydda områdets andliga balans.",al={"seereth stonebreak","uppdragsgivare","vem ger goblin invaders"}},{q="Varför avverkar goblinerna skogen i Stonetalon Mountains?",a="Venture Company är ett skrupelfritt företag som drivs av vinstintresse. De ser Stonetalon täta urgamla skogar och mineralrika kullar enbart som råvaror att skörda, bearbeta och sälja till högstbjudande, helt likgiltiga inför den natur- och andeförödelse som lämnas efter dem.",al={"varför avverkar venture company","venture companys motiv i stonetalon","varför fälla träd"}},{q="Var ligger Windshear Crag?",a="Windshear Crag ligger i den centrala delen av Stonetalon Mountains. För att ta dig dit från gränsen mot The Barrens färdas du nordväst längs bergsvägen genom Greatwood Vale, tills den frodigt gröna skogen övergår i Venture Companys mekaniska skogshuggarläger och kalhuggna kullar.",al={"windshear crags läge","var finns skogshuggarna","var hittar man venture companys skogshuggare"}},{q="Hur reagerar andarna på Venture Companys närvaro?",a="Enligt Seereth Stonebreak drivs landets andar nästan till vansinne av raseri och smärta från den hänsynslösa avverkningen och bränningen av skogarna. Deras lidande rubbar naturens balans och utgör ett andligt hot mot hela området.",al={"stonetalon-andarna arga","stonetalon-andarnas reaktion"}},{q="Vad händer efter att Venture Companys skogshuggare röjts undan?",a="Att göra sig av med skogshuggarna är bara det första slaget mot verksamheten. Därefter riktar Seereth Hordens uppmärksamhet mot att montera ned företagets mekaniserade infrastruktur, samtidigt som hon rekommenderar att kämpen söker vägledning hos taurenäldste för att hjälpa till att lugna de sårade andarna.",al={"efter goblin invaders","nästa uppdrag efter skogshuggarna"}},{q="Varför bryr sig Horden om skogsavverkningen i Stonetalon?",a="Stonetalon Mountains har djup kulturell och andlig betydelse för tauren, medan Horden som helhet ser Venture Companys otyglade aggression och stöld av naturresurser som ett hot mot deras territoriella inflytande och andliga harmoni.",al={"hordens intresse för stonetalon","varför slåss horden mot venture company"}}},fx={c7723727={q="Varför vill Seereth Stonebreak att Venture Companys skogshuggare dödas?",a="Venture Company kalhugger hänsynslöst stora områden i Stonetalon Mountains och sätter dem i brand. Deras vårdslösa förstörelse har drivit de lokala naturandarna till vansinne av plågsam smärta och vrede. Seereth vill att skogshuggarna slås ner för att hejda den obevekliga plundringen och visa att Horden inte tolererar skändningen av dessa heliga marker.",al={"seereth stonebreaks motiv","varför döda skogshuggarna","varför bryr sig seereth om gobliner"}},["4d329e4c"]={q="Vilka är Venture Co. Loggers?",a="Venture Co. Loggers är lejda arbetare och tekniker som arbetar för det ökända goblinsyndikatet. De drivs enbart av vinst och har trängt förbi Greatwood Vale in i Windshear Crag, där de kalhugger urgamla skogar och använder tunga maskiner utan minsta hänsyn till marken eller dess inhemska andars vrede.",al={"vilka är skogshuggarna","venture co loggers","venture companys arbetare"}}},fp="15,184,17.502.0,21.347.0,26.213.0,53.244.0,32.233.0,59.201.0,55.216.1,52.237.0"}
P.entries["quest:1063"] = {n="The Elder Crone",s="The Elder Crone är en kallelse från Horde som leder äventyrare från Stonetalon Mountains sargade klippor till Thunder Bluffs höga platå. För att få andlig vägledning och blidka Stonetalon Mountains rasande elementandar skickar Seereth Stonebreak sändebud till den inflytelserika taurenäldsten Magatha Grimtotem på Elder Rise.",h="The Elder Crone är en kallelse från Horde som leder äventyrare från Stonetalon Mountains sargade klippor till...",kw={"elder crone","elder rise","grimtotem","magatha","seereth stonebreak","andar","stonetalon","tauren","thunder bluff"},ang={["class:Shaman"]="Shamanerna förstår allvaret i Stonetalon Mountains elementuppror. Att rådfråga en äldre som Magatha på Elder Rise visar hur djup den andliga kris som utspelar sig bland Kalimdors bergstoppar är.",["faction:Horde"]="Det här ärendet visar de pragmatiska band som håller Horde samman och kopplar en kris i Stonetalon direkt till Thunder Bluffs ledarskaps höga salar.",["race:Tauren"]="För taurenvandrare är ett besök hos Magatha en påminnelse om den sköra balansen mellan Cairnes enade stammar och den reserverade, djupt traditionsbundna Grimtotem-fraktionen som bor i hjärtat av Thunder Bluff."},sec={{t="Rop från Stonetalon",b="I Stonetalon Mountains klippiga terräng har goblinernas skogsskövling och gruvdrift gjort de lokala elementandarna ursinniga. Seereth Stonebreak inser att rå styrka inte kan stilla landets andliga vånda och drar slutsatsen att de äldre shamanernas visdom behövs. Seereth känner till få stamledare vid namn, men vet att Magatha Grimtotem är en äldre som sägs ha djupa kunskaper och en auktoritativ närvaro."},{t="Möte på Elder Rise",b="Magatha håller hov på höjderna av Elder Rise i Thunder Bluff, där shamanistiska och andliga angelägenheter samlas. Grimtotem-stammen har ett osäkert och ofta konfrontativt förhållande till Cairne Bloodhoofs ledarskap, men Magatha erkänns som en mäktig äldre vars råd väger tungt i hela Horde. Äventyrarna vet inte att deras försök att föra Stonetalon Mountains bekymmer till henne kommer att leda dem mot betydligt mörkare lösningar."},{t="En pragmatisk allians",b="När Magatha får höra om elementkaoset vänder hon sig inte enbart till taurenernas traditionella ritualer. I stället hänvisar hon ärendet till de Forsaken-al kemister som bor i staden. Hennes vilja att blanda in Hordes nyaste och mest cyniska allierade i Kalimdors andliga angelägenheter visar hennes slughet och okonventionella sätt att utöva makt och lösa problem."}},faq={{q="Vem skickar mig för att hitta Magatha?",a="Seereth Stonebreak, som befinner sig i Stonetalon Mountains, ger dig uppdraget efter att du har bekämpat Venture Companys goblininkräktare som härjar i bergsskogarna.",al={"uppdragsgivare","vem startar uppdraget","seereth stonebreak"}},{q="Var finns Magatha Grimtotem?",a="Magatha Grimtotem bor i Thunder Bluff på Elder Rise, den nordöstra klippan som är förbunden med den centrala platån genom träbroar.",al={"magathas plats","var finns magatha","elder rise"}},{q="Varför ber Seereth en taurenäldste om hjälp?",a="Goblinernas destruktiva industriverksamhet i Stonetalon Mountains har stört områdets andar djupt. Seereth inser att militär styrka inte räcker för att läka landet och att det krävs verklig andlig vägledning för att lugna de upprörda elementen.",al={"varför elder crone","varför rådfråga magatha"}},{q="Vem är Magatha Grimtotem?",a="Magatha är Grimtotem-stammens matriark och äldre. Hennes stam är känd för att vara våldsamt aggressiv och skeptisk till den enade Horde, men Magatha har ett framstående politiskt och andligt inflytande på toppen av Thunder Bluff.",al={"elder crone-lore","vem är elder crone","magathas bakgrund"}},{q="Vad händer efter att jag har talat med Magatha?",a="Magatha lyssnar på din rapport om nödläget i Stonetalon Mountains och skickar dig genast till den Forsaken-sändebudet Apothecary Zamah i The Pools of Vision under Spirit Rise, för uppdraget Forsaken Aid.",al={"vad händer sedan","uppföljning av uppdrag"}},{q="Varför heter uppdraget ”The Elder Crone”?",a="Titeln syftar direkt på Magatha Grimtotem själv. Både inom hennes egen klan och bland taurener i stort är hon vida känd som The Elder Crone, tack vare sin höga ålder, sin mäktiga shamanistiska kunskap och sin auktoritet som matriark.",al={"varför crone","titeln elder crone"}}},fx={["9e600b44"]={q="Varför skickar Seereth Stonebreak en äventyrare till Thunder Bluff i stället för att själv åka dit?",a="Seereth Stonebreak är kvar i Stonetalon Mountains för att leda det omedelbara försvaret av marken och återställa den andligen efter Venture Companys skogsavverkning. Som orc-schaman bunden till gränslandet kan hon inte överge sin post för den långa färden genom The Barrens till Thunder Bluff. Hon förlitar sig på Hordens resande hjältar för att på hennes vägnar föra nyheter om faran i Stonetalon direkt till taurenäldste.",al={"varför skicka mig","varför kan inte seereth åka","varför behöver seereth spelaren"}}},fp="15,238,19.344.0,22.368.0,20.314.1,29.136.0,35.129.0,47.153.0,25.222.0,41.148.1,43.174.0"}
P.entries["quest:1064"] = {n="Forsaken Aid",s="Magatha Grimtotem sänder en äventyrare djupt in i The Pools of Vision i Thunder Bluff för att rådfråga den fördärvade andebuden Apothecary Zamah om de vanställda andarna i Stonetalon Mountains. Genom att framställa de Fördömda som experter på att hantera sjukdom använder den gamla matriarken krisen i Stonetalon för att främja ett närmare samarbete mellan tauren och deras kontroversiella odöda allierade.",h="Magatha Grimtotem sänder en äventyrare djupt in i The Pools of Vision i Thunder Bluff för att rådfråga den...",kw={"apothecary zamah","hjälp från de fördömda","magatha grimtotem","the pools of vision","orm-budbärare","spirit rise","stonetalon mountains","thunder bluff"},ang={["faction:Horde"]="Uppdraget visar det känsliga nätverk av allianser som binder samman Kalimdor och Lordaeron efter det tredje kriget.",["race:Tauren"]="Traditionella tauren vänder sig till druidism och Jordmodern för att hela landet. Magathas envishet att vända sig till odöda alkemister visar hennes okonventionella sätt att sköta stammens diplomati.",["race:Undead"]="För de Fördömda är alkemisk hjälp till tauren ett viktigt tillfälle att visa sitt värde och vinna förtroende inom en annars misstänksam Horde."},sec={{t="Ett pragmatiskt partnerskap",b="Äldrematriarken Magatha Grimtotem, en av de främsta förespråkarna för alliansen mellan tauren och de Fördömda, betraktar de odöda utifrån deras praktiska nytta. När rapporter om de korrumperade elementandar och det lidande landet i Stonetalon Mountains når Thunder Bluff ser Magatha en naturlig användning för de Fördömdas kunskaper. Hon hävdar att man måste förstå sjukdomen för att kunna bota den och styr resenärer bort från traditionella druidiska botemedel, rakt i händerna på Royal Apothecary Society."},{t="Under Spirit Rise",b="Undangömd i den grottliknande The Pools of Vision under Spirit Rise företräder Apothecary Zamah Undercitys intressen på Kalimdor. Grottan är en helig tillflyktsort för tauren-schamaner, präster och siare, men den Fördömdas närvaro där markerar en subtil politisk förskjutning. Magatha skickar en orm-budbärare i förväg för att varna Zamah och upprättar därmed en direkt förbindelse mellan Grimtotem-matriarken och de Fördömdas alkemiska forskare."}},faq={{q="Varför rådfrågar Magatha Grimtotem de Fördömda om Stonetalon?",a="Magatha hävdar att de Fördömda har ingående kunskaper om farsoter och sjukdomar och därför är särskilt lämpade att diagnostisera och behandla sjukdomen som plågar landet i Stonetalon Mountains.",al={"varför hjälp från de fördömda","magatha och de odöda","varför fråga de fördömda"}},{q="Var finns Apothecary Zamah?",a="Hon bor inne i The Pools of Vision, en underjordisk grotta under Spirit Rise på den nordvästra klippan i Thunder Bluff. Dit kommer man via en grottgång nära bassängen på platån ovanför.",al={"apothecary zamahs plats","var finns zamah","ingången till the pools of vision"}},{q="Vad händer när du tar emot uppdraget från Magatha?",a="När du tar emot uppdraget tillkallar Magatha en orm-budbärare som slingrar sig och flyger genom Thunder Bluff, direkt mot Apothecary Zamah för att meddela att du är på väg.",al={"orm-budbärare","magathas orm"}},{q="Vad tycker de Fördömda om att hjälpa tauren i Stonetalon?",a="Apothecary Zamah uttrycker medkänsla med de plågade andarna i Stonetalon trots att hon själv är odöd. Hon säger att de Fördömda gärna erbjuder sin hjälp och stärker banden till Horde.",al={"de fördömdas motiv i stonetalon","varför zamah hjälper till"}},{q="Vilken uppdragskedja följer efter samtalet med Zamah?",a="Efter mötet med Zamah fördjupas undersökningen av de Fördömdas alkemi. Den leder så småningom till ”Journey to Tarren Mill” i Eastern Kingdoms, där du ska rådfråga apotekare med högre rang.",al={"what comes next","nästa uppdrag efter forsaken aid"}},{q="Varför finns de Fördömda i den heliga The Pools of Vision?",a="I The Pools of Vision håller olika Horde-lärda, magiker och siare till. Apothecary Zamah arbetar där som officiell emissarie och forskare, med sina kontroversiella experiment undangömda från de stora stråken.",al={"varför finns odöda i the pools of vision","odöda vid spirit rise"}}},fx={["5f2f83c5"]={q="Varför skickar Magatha dig i stället för att själv rådfråga Apothecary Zamah?",a="Som Elder Crone i Grimtotem-stammen och framstående ledare på Elder Rise förlitar sig Magatha Grimtotem på självständiga äventyrare för känsliga ärenden på plats runt om i Thunder Bluff. Att skicka en duglig budbärare prövar inte bara din pålitlighet i stammens angelägenheter, utan skapar också direktkontakt mellan en aktiv agent för Horden och Apothecary Zamah nedanför Spirit Rise.",al={"varför jag i forsaken aid","varför skickar magatha en äventyrare till zamah","varför behöver magatha mig"}}},fp="12,217,23.367.0,23.363.0,66.134.0,36.187.0,52.160.0,64.152.0,50.184.0,65.199.0"}
P.entries["quest:1065"] = {n="Journey to Tarren Mill",s="För att driva bort Venture Company från Stonetalon Mountains utan onödigt blodspillan söker Apothecary Zamah i Thunder Bluff en okonventionell lösning och skickar ett sändebud över havet till Lordaeron. Uppdraget leder Horde-resenärer till Tarren Mill i Hillsbrad Foothills, där Royal Apothecary Society har ett illavarslande laboratorium under Apothecary Lydon.",h="För att driva bort Venture Company från Stonetalon Mountains utan onödigt blodspillan söker Apothecary Zamah...",kw={"apothecary lydon","apothecary zamah","hillsbrad","journey to tarren mill","stonetalon","tarren mill","thunder bluff","undercity","venture company"},ang={["faction:Horde"]="Förbindelsen mellan Thunder Bluff och Tarren Mill blir en tidig prövning som knyter unga Horde-försvarare till den större alliansen mellan kontinenterna.",["race:Tauren"]="Skändningen av Stonetalon går tauren djupt in på livet, men att ta emot kemiska lösningar från Forsaken visar vilka obekväma kompromisser som krävs för att skydda heliga marker.",["race:Undead"]="Resan visar hur långt Royal Apothecary Societys räckvidd sträcker sig och hur Undercitys kemiska kunnande förs över havet för att hjälpa avlägsna Horde-allierade."},sec={{t="En vädjan över Stora havet",b="I Thunder Bluff företräder Apothecary Zamah den bräckliga alliansen mellan de nybildade Forsaken och Jordmoderns barn. När tauren finner sina heliga marker i Stonetalon Mountains skändade av Venture Companys hänsynslösa skogsavverkning och gruvdrift räcker de vanliga metoderna inte till. Zamah föreslår en annan taktik: ett okonventionellt kemiskt avskräckningsmedel framtaget av hennes kollegor i Royal Apothecary Society. I stället för att inleda ett fullskaligt utnötningskrig vänder hon sig till specialiserade alkemiska brygder som framställs på andra sidan Stora havet."},{t="Vägen till Hillsbrad",b="Resan kräver att du korsar kontinenter och leder äventyrare från Kalimdor ombord på zeppelinare mot Ruins of Lordaeron och Undercity. Från Tirisfal Glades pesthärjade ängar går leden söderut genom Silverpine Forests skuggiga skogar, innan den öppnar sig mot det omstridda Hillsbrad Foothills. Där, nära mänskliga gårdar och ruiner, ligger Tarren Mill, en före detta mänsklig by som nu är befäst som Forsakens norra fäste och utpost för Royal Apothecary Societys forskning."},{t="Apothecary Lydons hantverk",b="Apothecary Lydon verkar från Tarren Mill och ägnar sig åt flyktig kemi och biologiska ämnen, ofta genom att testa tvivelaktiga blandningar på levande försökspersoner. När Lydon får Zamahs brev med Venture Company-dilemmat blir hen entusiastisk. Royal Apothecary Society tar varje tillfälle att fälttesta sina blandningar i nya miljöer, och Lydon slösar ingen tid på att förbereda mörka reagenser för att ta itu med goblininvasionen."}},faq={{q="Varför skickar Apothecary Zamah mig hela vägen till Tarren Mill?",a="Apothecary Zamah behöver en specialblandning för att få bort Venture Company från Stonetalon Mountains utan öppet krig. Hennes kollega i Royal Apothecary Society, Apothecary Lydon, är specialist på de alkemiska ämnen som behövs och verkar från Tarren Mill i Lordaeron.",al={"varför åka till tarren mill","varför skicka mig till lydon","syftet med resan till tarren mill"}},{q="Var ligger Tarren Mill?",a="Tarren Mill ligger i den norra delen av Hillsbrad Foothills på kontinenten Lordaeron. För att ta dig dit från Kalimdor tar du zeppelinaren från Durotar till Undercity i Tirisfal Glades. Res sedan söderut genom Silverpine Forest och österut in i Hillsbrad.",al={"var ligger tarren mill","tarren mills läge","hur tar jag mig till tarren mill"}},{q="Vilka är Apothecary Zamah och Apothecary Lydon?",a="Båda är medlemmar i Forsakens Royal Apothecary Society. Zamah tjänstgör som sändebud vid The Pools of Vision i Thunder Bluff, där hon studerar den lokala floran och hjälper tauren. Lydon utför mer hänsynslösa alkemiska experiment och pestexperiment i Tarren Mill.",al={"vem är zamah","vem är lydon","vilka är apotekarna"}},{q="Varför hjälper Forsaken till mot Venture Company i Stonetalon?",a="Forsaken anslöt sig till Horde främst för att överleva och av praktiska skäl, och förlitade sig mycket på taurenfolkets stöd för att få en plats i fraktionen. Genom att hjälpa tauren mot Venture Company stärker Forsaken den politiska alliansen och får en plats att testa sin alkemi på.",al={"varför bryr sig forsaken om stonetalon","odöda hjälper tauren i stonetalon"}},{q="Vad är Royal Apothecary Society?",a="Royal Apothecary Society är en orden av Forsaken-alkemister och forskare med bas under Ruins of Lordaeron i Undercity. Under ledning av Lady Sylvanas Windrunners direktiv utvecklar de ständigt nya elixir, gifter och peststammar för att försvara Forsaken och utplåna deras fiender.",al={"vad är royal apothecary society","forsaken-apotekarnas historia"}},{q="Vad händer efter att jag lämnat brevet till Lydon?",a="När Apothecary Lydon får Zamahs begäran börjar hen genast formulera en lösning. För att skapa en lämplig blandning behöver resenärer samla in flaskor med oskyldigt blod från Syndicates skuggmagiker i Durnholde Keep.",al={"nästa uppdrag efter journey to tarren mill","vad behöver lydon"}}},fx={f7a71381={q="Varför behöver Apothecary Zamah en äventyrare som kan leverera brevet?",a="Apothecary Zamah är stationerad vid The Pools of Vision under Thunder Bluff som sändebud för Royal Apothecary Society. Hennes arbete kräver att hon håller sig bland de misstänksamma tauren och sköter sina pågående alkemiska sysslor i Kalimdor. Det är mycket mer praktiskt att skicka en oberoende kurir över havet till Tarren Mill än att överge sin känsliga diplomatiska post och forskningspost.",al={"varför skicka mig","varför kan inte zamah åka","varför behöver zamah mig"}}},fp="22,221,27.408.0,21.368.0,24.347.1,61.246.0,29.214.0,46.256.0,68.252.0,37.277.0,48.201.1"}
P.entries["quest:1066"] = {n="Blood of Innocents",s="Blood of Innocents är ett uppdrag åt Apothecary Lydon i Tarren Mill, där du samlar in mörka alkemiska ingredienser. För att kuva Venture Company, som tränger in i Stonetalon Mountains, använder Royal Apothecary Society mörka ämnen från traktens banditer.",h="Blood of Innocents är ett uppdrag åt Apothecary Lydon i Tarren Mill, där du samlar in mörka alkemiska...",kw={"apothecary lydon","blood of innocents","durnholde keep","skuggmagiker","stonetalon mountains","syndicate","tarren mill","venture company"},ang={["faction:Horde"]="Uppdraget visar de band mellan kontinenterna som håller ihop Horden. De mörka alkemiska konsterna hos Lordaerons Forsaken används för att skydda territorier i Kalimdor.",["race:Tauren"]="Tauren kan tycka att insamlingen av oskyldigas blod är djupt oroande, men det övergripande målet är att sätta stopp för Venture Companys miljöförstörelse i Kalimdor.",["race:Undead"]="För Forsaken får moraliska betänkligheter stå tillbaka för effektiviteten. Lydons beräknande tillvägagångssätt visar hur Royal Apothecary Society använder kall logik för att lösa de levande allierades problem."},sec={{t="En kemisk lösning",b="Horden möter ständigt motstånd i Stonetalon Mountains, där det rovlystna Venture Company skövlar vildmarken utan hänsyn till marken eller dess invånare. I stället för att skicka arméer för att hejda deras yxor föreslår Apothecary Lydon en alkemisk lösning. Hans plan går ut på att brygga ett förlamande, lugnande medel som dämpar legosoldaternas aggressivitet och gör dem svaga och fogliga."},{t="Stulet från de onda",b="Att brygga en sådan lömsk blandning kräver ett ytterst sällsynt och moraliskt tvivelaktigt ämne: oskyldigas blod. I stället för att tvinga Hordens agenter att själva döda oskyldiga utnyttjar Lydon de lokala Syndicates brott. De fallna adelsmännen och mördarna som hemsöker Durnholde Keep anlitar skumma skuggmagiker som samlar in oskyldigas blod till sina egna vanheliga ritualer. Därför är de ett lämpligt mål för alkemisk insamling."}},faq={{q="Varför behöver Apothecary Lydon oskyldigas blod?",a="Apothecary Lydon behöver det som en viktig ingrediens i en experimentell blandning. Han tänker brygga ett försvagande gift som berövar Venture Company i Stonetalon Mountains dess våldsamma drivkraft och gör The Defilers kuvade och lätta att hantera.",al={"vad används oskyldigas blod till","varför oskyldigas blod","lydons bloduppdrag"}},{q="Vem har flaskorna med oskyldigas blod?",a="Flaskorna bärs av Syndicates skuggmagiker. De här skumma magikerna håller till bland ruinerna av Durnholde Keep, sydost om Tarren Mill, där de samlar blod till sina egna skändliga besvärjelser.",al={"vem släpper blodet","var får man tag på oskyldigas blod","plats för oskyldigas blod"}},{q="Varför handlar ett uppdrag i Hillsbrad om Stonetalon Mountains?",a="Hordens ledare i Kalimdor bad Royal Apothecary Society i Eastern Kingdoms om vetenskaplig hjälp. Konflikten mot Venture Company utspelar sig i Stonetalon, men specialister som Apothecary Lydon i Tarren Mill behärskar den mörka konsten som krävs för att brygga särskilda biologiska botemedel.",al={"kopplingen till stonetalon","varför tarren mill och stonetalon"}},{q="Vad är Syndicate?",a="Syndicate är en organisation av före detta adelsmän från det fallna människoriket Alterac, som blivit stråtrövare, lönnmördare och mördare. Desperata att återta sina förlorade landområden drar de sig inte för utpressning, svart magi och att ge sig på alla som färdas genom Hillsbrad och Alterac.",al={"vilka är syndicate","syndicates bakgrund"}},{q="Var ligger Durnholde Keep?",a="Durnholde Keep ligger sydost om Tarren Mill i Hillsbrad Foothills. Det var en gång en ökänd människofästning och ett interneringsläger för orcher, men ligger nu delvis i ruiner och fungerar som ett viktigt fäste för Syndicate.",al={"hitta durnholde keep","var ligger durnholde"}},{q="Mördar Horden oskyldiga för att få tag på det här blodet?",a="Nej. Royal Apothecary Society drar sig sällan för obehagliga metoder, men Lydon ber uttryckligen agenterna samla in blod som Syndicates skuggmagiker redan tagit från sina egna offer.",al={"dödade horden oskyldiga","källa till oskyldigas blod"}}},fx={b5439bfd={q="Vad ska Vial of Innocent Blood användas till?",a="Apothecary Lydon behöver flaskorna med oskyldigt blod för att brygga en specialblandning åt Royal Apothecary Society. I stället för att döda direkt är hans planerade gift utformat för att kuva det aggressiva Venture Company i Stonetalon Mountains, beröva dem viljan att slåss och göra dem fogliga.",al={"vad används vial of innocent blood till","vad gör oskyldigt blod","syftet med oskyldigt blod"}}},fp="18,221,19.322.0,22.367.0,46.230.0,36.172.0,60.247.0,22.243.0,32.185.0,49.163.0"}
P.entries["quest:1067"] = {n="Return to Thunder Bluff",s="Det här uppdraget går ut på att föra ett kraftfullt kemiskt ämne från Tarren Mill över havet till Thunder Bluff. Apothecary Lydon har framställt ämnet, och där väntar Apothecary Zamah för att konstruera en spridningsanordning mot Venture Company. Det är ett avgörande steg i Royal Apothecary Societys hemliga forskning under deras tauren-värdars eget tak.",h="Det här uppdraget går ut på att föra ett kraftfullt kemiskt ämne från Tarren Mill över havet till Thunder...",kw={"apothecary lydon","apothecary zamah","lydon's toxin","the pools of vision","return to thunder bluff","royal apothecary society","tarren mill","toxic fogger","venture company"},ang={["faction:Horde"]="Forsaken-alkemisternas samarbete hjälper till att skydda Hordes intressen genom att rikta in sig på Venture Companys destruktiva verksamhet.",["race:Tauren"]="Magatha Grimtotem och de äldste välkomnade Forsaken till Thunder Bluff i hopp om att de skulle finna upprättelse eller bot, men apotekarna under Spirit Rise ägnar sin tid åt att utveckla smittsamma biologiska vapen.",["race:Undead"]="Det här uppdraget visar hur långt Royal Apothecary Societys verksamhetsnätverk sträcker sig, med forskning samordnad mellan fronten i Lordaeron och forskningsposter på Kalimdor."},sec={{t="En leverans över havet",b="Efter att ha säkrat de flyktiga ingredienserna han bad om i Hillsbrad Foothills lyckas Apothecary Lydon framställa sin giftiga brygd. Lydon är överlycklig över att få testa sitt biologiska hantverk på levande försökspersoner, men det råa giftet saknar en effektiv spridningsmetod. För att få största möjliga effekt måste flaskan föras över Stora havet till Mulgore, där Apothecary Zamah väntar på den."},{t="Zamahs anordning",b="Zamah håller till på den skuggiga nedre nivån under Spirit Rise i Thunder Bluff och arbetar som ambassadör och forskare för Royal Apothecary Society. När hon får Lydons blandning börjar hon omvandla vätskan till ett aerosolmedel och tillverkar en trycksatt anordning som kallas Toxic Fogger. Hennes yttersta mål är att släppa lös det biologiska vapnet direkt mot de inkräktande goblinerna i Venture Company."}},faq={{q="Varför ska giftet föras till Thunder Bluff?",a="Apothecary Lydon skapade det råa flytande giftet, men det behöver ett särskilt spridningssystem för att få största möjliga effekt över ett stort område. Apothecary Zamah har de tekniska kunskaper som krävs för att omvandla formeln till en aerosolapparat som kallas Toxic Fogger.",al={"varför thunder bluff","vad gör zamah med giftet","hur lydons gift används"}},{q="Vem är målet för den här blandningen?",a="Giftet är särskilt framtaget för att användas mot Venture Company, det hänsynslösa gruvsyndikatet av gobliner som härjar i Stonetalon Mountains och områdena däromkring.",al={"vem blir förgiftad","målet för lydons gift","vem strider vi mot"}},{q="Var finns Apothecary Zamah?",a="Apothecary Zamah finns i The Pools of Vision, ett nätverk av grottor gömt under Spirit Rise i Thunder Bluff.",al={"hitta zamah","var finns apothecary zamah","zamahs plats"}},{q="Varför arbetar apotekare från Undercity i en taurenstad?",a="Tauren gav Forsaken asyl och stödde deras inträde i Horde, till stor del i hopp om att hjälpa dem hitta ett botemedel mot sin åkomma. Apothecary Zamah är utsänd av Royal Apothecary Society, men hennes arbete handlar oftare om pest och biologiska vapen än om läkande.",al={"forsaken i thunder bluff","varför finns odöda i thunder bluff","apotekare i mulgore"}},{q="Vad händer när giftet lämnas in?",a="När Zamah tagit emot flaskan bygger hon Toxic Fogger på plats. Sedan skickar hon dig för att placera aerosolmaskinen direkt vid en anläggning som tillhör Venture Company i Stonetalon Mountains.",al={"nästa uppdrag","vad händer efter return to thunder bluff","fogger-uppdrag"}},{q="Vem skapade den ursprungliga formeln?",a="Giftet framställdes av Apothecary Lydon, en forskare för Royal Apothecary Society stationerad i Tarren Mill i Hillsbrad Foothills.",al={"vem gjorde giftet","vem är lydon","apothecary lydons bakgrund"}}},fx={["4bd277bc"]={q="Varför vill Apothecary Lydon att det här ska göras?",a="Apothecary Lydon längtar efter att få se sina blandningar användas i praktiken ute på fältet. Giftet ska ta udden av Venture Companys våldsamhet och göra dem svaga och fogliga, men det kan inte användas effektivt på egen hand. Om det skickas tillbaka till Apothecary Zamah i Thunder Bluff kan hon skapa en lämplig leveransmetod som maximerar effekten, med gynnsamma, kanske till och med smittsamma, resultat.",al={"varför vill lydon detta","lydons motiv","apothecary lydons skäl"}}},fp="23,164,27.269.0,17.259.1,59.153.0,37.129.0,34.81.0,56.239.0,40.146.1,33.88.0"}
P.entries["quest:1068"] = {n="Shredding Machines",s="Shredding Machines är ett Horde-uppdrag där äventyrare ska jaga två specialbyggda skogshuggarmekar från Venture Company i Windshear Crag. Under schamanen Seereth Stonebreaks ledning slår spelarna mot den mekaniska skogsskövling som plågar Stonetalon Mountains ursprungsandar.",h="Shredding Machines är ett Horde-uppdrag där äventyrare ska jaga två specialbyggda skogshuggarmekar från...",kw={"skogsavverkning","seereth stonebreak","skogshuggare","shredding machines","stonetalon mountains","venture company","windshear crag","xt:4","xt:9"},ang={["class:Shaman"]="Seereth betonar den djupa samklangen mellan andlig magi och naturen och påminner schamaner om att den elementära balansen kräver att de försvarar andarna som bor i landet.",["faction:Horde"]="När Horden etablerar fästen över Kalimdor är det avgörande att tygla Venture Companys oreglerade girighet för att bevara landet och säkra trygga färder genom Stonetalon Mountains.",["profession:Engineering"]="Skogshuggarmekarna i XT-serien visar upp avancerad goblinsk skogshuggardesign, där hydrauliska sågar kombineras med ångdrift.",["race:Tauren"]="De själlösa goblinmaskinernas skändning av Stonetalon Mountains uråldriga skogar går rakt emot taurenfolkets vördnad för Jordmodern."},sec={{t="En vision av skogsskövling",b="Orkschamanen Seereth Stonebreak står vid den dammiga gränsen mellan The Barrens och Stonetalon Mountains och lyssnar noga till den osynliga världen. Mycket av Stonetalon Mountains andliga röst dränks av kaos, men en vision nådde henne med fasansfull tydlighet: människolika maskiner som rusade genom uråldriga skogar i onaturlig hastighet. Dessa goblinbyggda skogshuggare, märkta XT:4 och XT:9, slaktar skogarna i Windshear Crag och sänder vågor av förtvivlan genom naturandarna i trakten."},{t="Tysta sågarna",b="För att hejda förödelsen beger sig Hordens hjältar djupt in i Windshear Crag, nordväst om Greatwood Vale, där Venture Company bedriver sin verksamhet. Genom att spåra upp och förstöra just dessa skogshuggare tillfogas bergens kommersiella skogsskövling ett hårt slag. När XT:4 och XT:9 fälls tystnar de sårade trädandarnas omedelbara rop, men Seereth varnar för att långt värre grymheter väntar landet om Venture Company inte lämnar Stonetalon helt."}},faq={{q="Vem är Seereth Stonebreak?",a="Seereth Stonebreak är en ork-schaman stationerad vid den södra gränsen av Stonetalon Mountains, nära The Barrens. Hon är lyhörd för landets elementära och andliga krafter och förmedlar de plågade skogsandarnas protester mot Venture Companys snabba expansion.",al={"vem är seereth","uppdragsgivaren seereth","seereth stonebreaks historia"}},{q="Vad är XT:4 och XT:9?",a="XT:4 och XT:9 är specialbyggda skogshuggare med beteckningar som Venture Company använder i Windshear Crag. De drivs av ångmaskiner och styrs av gobliner. Dessa mekaniska gångare fäller uråldriga träd mycket snabbare än manuella arbetare någonsin skulle kunna.",al={"vad är skogshuggarna","xt4 och xt9","mål för skogshuggarna"}},{q="Var ligger Windshear Crag?",a="Windshear Crag ligger i den norra delen av Stonetalon Mountains, nordväst om Greatwood Vale. Venture Company har omvandlat området till ett enormt industriellt skogshuggningsområde.",al={"windshear crags plats","var hittar jag skogshuggarna","var finns maskinerna"}},{q="Varför bryr sig en schaman om träd och druidsk magi?",a="Som Seereth förklarar har schamanens samverkan med andar nära band till druidisk naturmagi. Skadorna på levande skogar ekar in i andevärlden, så lyhörda schamaner kan höra slaktade trädandar jämra sig tillsammans med elementär oro.",al={"varför bryr sig schamaner om träd","kopplingen mellan schamaner och druider","naturandar och schamaner"}},{q="Vem äger och använder skogshuggarna?",a="Skogshuggarna tillhör Venture Company, ett skrupelfritt kommersiellt konglomerat som styrs av gobliner och är ökänt i hela Azeroth för att hänsynslöst utvinna värdefulla naturresurser utan hänsyn till det lokala ekosystemet eller dess ursprungliga invånare.",al={"vem byggde xt4","vem använder skogshuggarna","venture companys skogshuggare"}},{q="Driver förstörelsen av XT:4 och XT:9 bort Venture Company?",a="Nej. Förstörelsen av dessa flaggskeppsmaskiner lugnar de gråtande trädandarna och sinkar den lokala skogsavverkningen, men Venture Company behåller ett omfattande industriellt fotfäste i Windshear Crag. Vildmarkens försvarare måste fortsätta göra motstånd.",al={"lämnar venture company området","efter shredding machines","uppdragets utfall"}}},fx={["0171bd6f"]={q="Varför vill Seereth Stonebreak att XT:4 och XT:9 förstörs?",a="Som schaman med band till andevärlden hör Seereth de plågsamma ropen från Stonetalon, vars mark har sargats. Schamanens andlighet och naturens balans hör samman, och därför kan hon uppfatta trädandarna när de jämrar sig medan Venture Company härjar genom bergen. I en tydlig andlig syn såg hon just dessa två mekaniska fasor fälla urgamla träd i onaturlig takt. För henne är det livsviktigt att förvalta andevärlden genom att förstöra dem. Om maskinerna fortsätter sin hejdlösa slakt av skogen kanske markens sår aldrig läker.",al={"varför döda shredders","seereth stonebreaks motiv","varför förstöra xt4 och xt9"}}},fp="18,161,25.496.0,18.426.0,26.269.0,23.219.0,24.181.0,53.261.0,38.234.0,61.235.0"}
P.entries["quest:1069"] = {n="Deepmoss Spider Eggs",s="Mebok Mizzyrix ser en chans att sälja Deepmoss Spider Eggs till Booty Bay. Omeletter med spindelägg har blivit en fluga där, och han skickar resenärer till Stonetalon Mountains för att samla färska kullar till handeln över havet.",h="Mebok Mizzyrix ser en chans att sälja Deepmoss Spider Eggs till Booty Bay.",kw={"booty bay","deepmoss","dizzywig","mebok mizzyrix","omelett","ratchet","sishir canyon","spindelägg","windshear crag"},ang={["faction:Alliance"]="Som Alliance-spejare på resa mellan The Barrens och nattalvernas enklaver i Stonetalon kan du utnyttja goblinernas neutralitet i Ratchet för att tjäna pengar till resan.",["faction:Horde"]="Som Horde-resenär på väg genom The Barrens mot Stonetalon kan du tjäna snabba pengar i Ratchet för att finansiera kampen mot de lokala harpyorna och skogshuggarna från Venture Company.",["profession:Cooking"]="Som kock kan du se hur gäster i hamnstäder gör märklig och djärv mat, som deepmoss spider eggs, till statusmarkörer."},sec={{t="En smak för lyx",b="Booty Bays välbärgade gäster och excentriska pirater har fått smak för omeletter med spindelägg, vilket driver efterfrågan på sällsynta ingredienser över Great Sea. Köpmannen Mebok Mizzyrix från Ratchet ser en chans att tjäna en förmögenhet genom att förse den södra hamnen. Det finns inga sådana spindlar i Eastern Kingdoms, så Mebok söker efter äggen i Kalimdors vildmarker."},{t="Bon i bergen",b="Deepmoss spider eggs finns i Stonetalon Mountains, där Venture Company har huggit ner skog. Du kan hitta kullar under träden som ännu står kvar vid Windshear Crag, eller längre in i de nätövertäckta djupen av Sishir Canyon. Att samla dem innebär att möta giftiga bett och täta angrepp. Även vana asätare kan ha svårt att tåla svärmarna."},{t="The Steamer Clam Express",b="Färska ägg måste över havet innan de blir dåliga eller kläcks. Mebok samarbetar med Wharfmaster Dizzywig i Ratchet för att boka frakt på handelsfartyg från gobliner med kurs mot hamnen i Stranglethorn Vale. När äggen har packats i lådor tjänar Mebok en nätt vinst på handeln med exklusiv mat över haven."}},faq={{q="Varför vill Mebok Mizzyrix ha spindelägg?",a="Booty Bay har fått smak för omeletter med spindelägg, men saknar en lokal tillgång på äggen. Mebok Mizzyrix ser en chans för goblinhandlare från Ratchet att göra vinst genom att förse hamnen.",al={"varför spindelägg","mebok spindelägg","vad används äggen till"}},{q="Var finns deepmoss-spindlarnas ägg?",a="Deepmoss spider eggs finns i Stonetalon Mountains, nordväst om The Barrens. Samla dem under de kvarvarande träden vid Windshear Crag eller längre in i Sishir Canyon.",al={"var finns deepmoss-ägg","äggplatser","platser med spindelägg i stonetalon"}},{q="Varför varnar Mebok för Sishir Canyon?",a="Sishir Canyon rymmer enorma spindelsvärmar, täta spindelnät och delvis uppätna byten. Mebok varnar alla med känslig mage för att samla ägg under träden vid Windshear Crag i stället.",al={"varning för sishir canyon","känslig mage sishir"}},{q="Vem fraktar äggen när de har samlats in?",a="Mebok samarbetar med Wharfmaster Dizzywig vid Ratchets hamn för att skicka äggen med handelsfartyg över havet till Booty Bay.",al={"vem fraktar äggen","hamnmästarens frakt","dizzywigs ägg"}},{q="Äts äggen råa eller tillagade?",a="Äggen blir till omeletter, en excentrisk lyxrätt för välbärgade gäster och äventyrare som besöker tavernorna i Booty Bay.",al={"hur äts spindelägg","spindelomeletter"}},{q="Kan spelare från båda fraktionerna utföra uppdraget?",a="Ja. Ratchet är en öppen hamn som drivs av Steamwheedle Cartel, och Mebok Mizzyrix erbjuder arbetet till både Alliance- och Horde-resenärer.",al={"är uppdraget neutralt","horde eller alliance spindelägg"}}},fp="20,221,18.351.0,22.355.0,24.294.0,41.188.0,44.178.0,42.194.0,34.121.0,33.126.0,48.133.0"}
P.entries["quest:107"] = {n="Note to William",s="\"Note to William\" är ett ärende för Gramma Stonefield i södra Elwynn Forest, där två hemliga älskande från rivaliserande familjer behöver hjälp. Genom att lämna Mildreds meddelande till apotekaren William Pestle i Goldshire söker äventyrare en alkemisk lösning som kan förena unga Maybell och Tommy Joe.",h="\"Note to William\" är ett ärende för Gramma Stonefield i södra Elwynn Forest, där två hemliga älskande från...",kw={"elwynn forest","goldshire","gramma stonefield","lion's pride inn","maybell maclure","mildred stonefield","brev till william","tommy joe stonefield","william pestle"},ang={["faction:Alliance"]="Alliansens äventyrare som färdas genom Elwynn Forest hjälper ofta lokala jordbrukarfamiljer med personliga kriser när vakterna enbart fokuserar på militära hot.",["race:Human"]="Den pågående fejden mellan familjerna Stonefield och Maclure splittrar mänskliga grannar i Elwynn och får medkännande äldre att förlita sig på diskreta budbärare."},sec={{t="Kärlek i Elwynn",b="Familjerna Stonefield och Maclure har bott grannar i södra Elwynn Forest i åratal, men deras bittra fejd har gjort normala relationer omöjliga. Mitt i konflikten står unga Tommy Joe Stonefield och Maybell Maclure, vars kärlek måste hållas fullständigt hemlig. Medan deras föräldrar hyser outtröttligt agg hyser Gramma Mildred Stonefield medlidande med de unga älskande och söker en okonventionell lösning som kan förena dem."},{t="En vädjan till Goldshire",b="Eftersom hon tror att vanliga övertalningsförsök aldrig kommer att påverka de stridande familjerna skickar Gramma Stonefield en budbärare norrut till Lion's Pride Inn i Goldshire. I meddelandet söker hon upp William Pestle, en erfaren alkemist och apotekare som Mildred har känt i många år. När William tar emot brevet blir han berörd av Maybell och Tommy Joes svåra situation och beslutar sig för att använda sina alkemikunskaper för deras skull."}},faq={{q="Vem är William Pestle?",a="William Pestle är en alkemist och apotekare som bor på Lion's Pride Inn i Goldshire. Han är en gammal bekant till Gramma Mildred Stonefield och är känd för att blanda örtmediciner och särskilda drycker.",al={"vem är william pestle","william pestle goldshire","alkemist i goldshire"}},{q="Vem skickade brevet till William?",a="Gramma Mildred Stonefield, överhuvudet för familjen på The Stonefield Farm, skrev brevet. Hon känner sympati för den förbjudna kärleken mellan Maybell Maclure och Tommy Joe Stonefield och hoppas att William Pestle kan hitta en lösning som hjälper dem.",al={"vem skickade brevet","gramma stonefields brev","mildred stonefield"}},{q="Varför kan Maybell och Tommy Joe inte vara öppet tillsammans?",a="Maybell Maclure och Tommy Joe Stonefield är djupt förälskade, men deras familjer är inbegripna i en bitter och långvarig rivalitet. Gramma Stonefield tror att William Pestle kanske känner till en dryck eller en plan som kan låta de två älskande vara tillsammans trots familjernas fiendskap.",al={"varför hjälpa maybell och tommy joe","uppdrag om unga älskande i elwynn","fejden mellan stonefield och maclure"}},{q="Var hittar man William Pestle?",a="William Pestle finns på Lion's Pride Inn, den centrala tavernan och samlingsplatsen i staden Goldshire i Elwynn Forest.",al={"var finns william pestle","pestles plats","alkemist på lion's pride inn"}},{q="Vad heter Gramma Stonefield egentligen?",a="Hennes förnamn är Mildred, vilket William Pestle avslöjar när han säger att han inte har sett Mildred på flera år efter att ha fått hennes brev.",al={"vad heter gramma stonefield i förnamn","gramma stonefields namn"}},{q="Hur reagerar William Pestle på brevet?",a="När William har läst Mildreds brev säger han att han inte har sett Mildred på flera år och undrar vad hon har att säga, eftersom hon hoppas att hans alkemi kan hjälpa de olycksdrabbade älskande.",al={"vad gör william med brevet","william pestles reaktion"}}},fp="15,295,22.448.0,22.423.0,22.217.0,29.228.0,59.270.0,34.148.0,38.138.0,42.195.0"}
P.entries["quest:1070"] = {n="On Guard in Stonetalon",s="On Guard in Stonetalon är ett alliansuppdrag som leder äventyrare söderut från Ashenvale till de karga Stonetalon Mountains. Sentinel Thenysil skickar resenärer för att undersöka hur det går för hennes spejarkamrat Kaela Shadowspear, som skickades till bergsklyftorna tillsammans med en gnommagiker för att hålla uppsikt över Venture Companys industriella intrång.",h="On Guard in Stonetalon är ett alliansuppdrag som leder äventyrare söderut från Ashenvale till de karga...",kw={"ashenvale","kaela shadowspear","on guard in stonetalon","sentinel thenysil","stonetalon mountains","venture company","windshear crag"},ang={["faction:Alliance"]="Det här uppdraget markerar alliansens utvidgning av gränsskyddet söderut och knyter samman försvarsposter i Ashenvale med isolerade spejarplatser i Stonetalon Mountains.",["race:Gnome"]="Sentinels ser med stor skepsis på gnomisk magi och gnomiska uppfinningar och betraktar en gnommagiker i Kalimdors vildmark som ett besynnerligt och oförutsägbart inslag.",["race:NightElf"]="Uppdraget visar på motsättningarna mellan traditionella nattalvssentinels och deras allierade från Eastern Kingdoms magiska och mekaniska sedvänjor, särskilt gnomernas."},sec={{t="En spejare skickas söderut",b="Sentinel Thenysil är stationerad i Astranaar och håller noga uppsikt över hoten som närmar sig den uråldriga skogen. Hon är djupt oroad för sin vän Kaela Shadowspear och ber förbipasserande allianshjältar att leta reda på henne. Sentinel Wolfrunner skickade Kaela till Stonetalon Mountains för att undersöka den växande oron i höjderna, men kontakten har tystnat och Thenysil oroar sig för hennes säkerhet."},{t="Oroande sällskap i bergsklyftorna",b="Thenysils oro ökar av att Kaelas tilldelade följeslagare är en gnommagiker som alliansledningen skickat med henne. Även om nattalverna av strategiska skäl har anslutit sig till Grand Alliance är många Sentinels djupt skeptiska till magiker och uppfinningsrika gnomer i orörd vildmark. När du hittar Kaela på klipporna ovanför Windshear Crag ser du en utpost som vakar över den omfattande miljöförstörelse som Venture Company orsakat."}},faq={{q="Vem ger uppdraget?",a="Uppdraget erbjuds av Sentinel Thenysil, en nattalvssentinel stationerad i Astranaar i Ashenvale.",al={"uppdragsgivare","var börjar uppdraget","vem startar on guard in stonetalon"}},{q="Var hittar jag Kaela Shadowspear?",a="Kaela Shadowspear håller till högt uppe på en klippig ås med utsikt över dalöppningen mot Windshear Crag i Stonetalon Mountains.",al={"kaelas plats","hitta kaela","kaela shadowspears plats"}},{q="Varför oroar sig Sentinel Thenysil för Kaela?",a="Kaela skickades för att undersöka farliga fientliga intrång i Stonetalon och har inte hört av sig. Dessutom är Thenysil misstänksam eftersom alliansen parade ihop Kaela med en gnommagiker, något hon ser som ett förebud om problem.",al={"varför oroa sig","thenysils oro"}},{q="Vilka hot finns i Stonetalon Mountains?",a="Venture Company härjar i bergen. Det är en hänsynslös gruv- och skogsbrukskartell av gobliner som skövlar vildmarken. Aggressiva inhemska bestar och rivaliserande hordstyrkor tränger också in från söder.",al={"fiender i stonetalon","vem finns i stonetalon"}},{q="Vem är Tara?",a="Tara är Sentinel Thenysils förnamn. När du träffar Kaela kallar hon kärleksfullt sin gamla vän för Tara och uttrycker stolthet över att hon samordnar spejare och äventyrare.",al={"vem är tara","tara nämns"}},{q="Vad händer när jag hittar Kaela Shadowspear?",a="När du når Kaela är resan avklarad, och därefter kan du hjälpa henne och hennes gnompartner att hålla uppsikt över hoten som tränger in vid Windshear Crag.",al={"nästa uppdrag","what comes next"}}},fx={["96da069b"]={q="Varför behöver Sentinel Thenysil en äventyrare som kan hitta Kaela?",a="Sentinel Thenysil är i tjänst i Ashenvale och kan inte bara överge sin post för att rida in i grannländerna. När hon ser en kapabel resenär som verkar längta efter äventyr tar hon chansen att rekrytera en självständig spejare som kan ta sig över gränsen till Stonetalon utan att störa de lokala Sentinel-styrkornas försvar.",al={"varför skicka mig","varför åker inte thenysil","varför en äventyrare"}}},fp="22,207,18.334.0,32.341.0,21.75.0,35.125.0,45.204.0,52.184.0,12.164.0,45.145.0"}
P.entries["quest:1071"] = {n="A Gnome's Respite",s="A Gnome's Respite är ett alliansuppdrag som erbjuds av den excentriske uppfinnaren Gaxim Rustfizzle i Stonetalon Mountains. Venture Company har snabbt byggt ut sin industri i Windshear Crag, och Gaxim har fått nog. Han anlitar äventyrare för att slå ut deras skogshuggare och skogsröjare, så att han får tid att uppfinna nya avskräckande anordningar.",h="A Gnome's Respite är ett alliansuppdrag som erbjuds av den excentriske uppfinnaren Gaxim Rustfizzle i...",kw={"skogsröjare","sprängämne","gaxim rustfizzle","gnom","skogshuggare","stonetalon","venture co","windshear crag"},ang={["profession:Engineering"]="Ingenjörer lär uppskatta Gaxims filosofi om att mekanik och kemi kan lösa miljökriser, liksom hans förkärlek för kraftigt sprängämne.",["race:Gnome"]="Gaxims uppdrag står för klassisk gnomisk ambition: att lösa uråldriga, filosofiska konflikter mellan natur och civilisation med överlägsen uppfinningsrikedom och lite kraftigt sprängämne.",["race:NightElf"]="Kaldorei-väktare ser ofta på gnomiska maskiner med stor misstänksamhet. Men Venture Companys obevekliga framfart gör att varje effektivt motmedel är välkommet i Stonetalon."},sec={{t="En splittrad allians",b="Gaxim Rustfizzle företräder Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Han är stationerad bland Stonetalon Mountains uråldriga dungar. Hans uppdrag är att bevisa för de naturdyrkande Night Elf att moderna gnomiska uppfinningar, som förenar magi, kemiska brygder och mekanik, kan skydda deras hotade marker. Men Venture Companys obevekliga framfart har knappt lämnat honom tid att bygga prototyper av sina försvarsanordningar."},{t="Vinna tid i Windshear Crag",b="För att hejda framfarten skickar Gaxim äventyrare rakt in i den rykande verksamheten i Windshear Crag. Genom att ge sig på Venture Co. Loggers och Deforesters vid fronten ger resenärerna Gaxim tid att ordna sin verkstad och utforma nästa försvarslinje: strategiska, kontrollerade sprängningar med kraftigt sprängämne."}},faq={{q="Vem är Gaxim Rustfizzle?",a="Gaxim Rustfizzle är en magiker och uppfinnare av rasen gnom i alliansen. Han håller till i Stonetalon Mountains. Han tjänstgör som agent för Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences och försöker hjälpa Night Elf att stå emot industriella inkräktare.",al={"gaxim","vem är gaxim rustfizzle","uppdragsgivaren gaxim"}},{q="Varför försöker en gnom skydda Night Elf-skogar?",a="Gaxim anser att det är hans plikt att bevisa för de skeptiska Night Elf att avancerad gnomisk vetenskap, särskilt arkanologi, alkemi och ingenjörskonst, kan samexistera med naturen och aktivt försvara vildmarken mot okontrollerad industriell exploatering.",al={"varför gnom i stonetalon","varför hjälpa night elf","gnomer och ekologi"}},{q="Vilka är Venture Company i Windshear Crag?",a="Venture Company är ett hänsynslöst handelsförbund som styrs av gobliner och rovdriftsbryter samt kalhugger Windshear Crag. De drivs enbart av vinst och har översvämmat dalen med skogshuggare, skogsröjare och tunga skogsmaskiner.",al={"venture co i stonetalon","vilka är venture co","gobliner i windshear crag"}},{q="Var finns skogshuggarna och skogsröjarna?",a="De arbetar över hela Windshear Crag, det kraftigt industrialiserade bäckenet direkt öster om Gaxims plats längs huvudvägen i Stonetalon Mountains.",al={"var finns skogshuggarna","var hittar man skogsröjarna","windshear crags läge"}},{q="Vad tänker Gaxim göra när han får tid att tänka?",a="När goblin-arbetarna drivits tillbaka tänker Gaxim fylla på sitt lager av kraftigt sprängämne. Han ska spränga utvalda delar av berget för att driva bort och skrämma Venture Company från dungarna.",al={"gaxims plan","fortsättning på gnomens andrum","sprängämnesplan"}},{q="Vad är Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="Det är ett gnomiskt akademiskt sällskap som utforskar hur magisk besvärjelsekonst, kemiska blandningar och mekanisk ingenjörskonst kan förenas för att lösa praktiska problem i Azeroth.",al={"gnomiskt sällskap","arkanologiskt sällskap","vad är enlightened assembly"}}},fx={["8136de5d"]={q="Varför vill Gaxim Rustfizzle att Venture Company decimeras?",a="Gaxim Rustfizzle känner att det är hans plikt som medlem av Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences att bevisa att gnomisk uppfinningsrikedom kan skydda nattalvernas heliga skogar. Venture Companys obevekligt snabba skogsskövling håller honom ständigt överhopad med arbete, så han får ingen andrum att utforma, organisera och sätta ihop de uppfinningsrika apparater och sprängämnen han behöver för att vända stridslyckan.",al={"varför döda skogshuggarna","gaxims motiv","varför decimera venture co"}},["7aed6e2a"]={q="Varför behöver Gaxim Rustfizzle dig till att slåss mot goblinerna?",a="Gaxim är uppfinnare och forskare, inte en enmansarmé, och han arbetar utan större militärt stöd från Alliansen i Stonetalon. Mellan att hålla lägret säkert och försöka utarbeta nya ritningar kan han helt enkelt inte ensam slå tillbaka Venture Companys ständigt svärmande skogshuggare. Han förlitar sig på kapabla äventyrare som du för att tunna ut deras led, så att han kan fokusera på att bygga sina motmedel.",al={"varför jag åt gaxim","varför behöver gaxim hjälp","varför skicka en äventyrare"}}},fp="17,173,19.392.0,29.243.0,24.232.0,51.219.0,46.193.0,47.163.0,54.192.0,81.228.0"}
P.entries["quest:1072"] = {n="An Old Colleague",s="An Old Colleague är ett Alliance-uppdrag som ges av gnomingenjören Gaxim Rustfizzle i Stonetalon Mountains. Gaxim vill bygga en ovanligt kraftfull apparat och skickar en äventyrare över havet till Ironforge för att hitta en gammal bekant som kan framställa en farlig explosiv blandning. När ärendet är avklarat öppnas vägen till den flyktiga kemiska föreningen Nitromirglyceronium.",h="An Old Colleague är ett Alliance-uppdrag som ges av gnomingenjören Gaxim Rustfizzle i Stonetalon Mountains.",kw={"sprängämnen","gaxim rustfizzle","ironforge","lomac gearstrip","ng-5","nitromirglyceronium","stonetalon","tinker town"},ang={["faction:Alliance"]="Uppdraget skickar Alliance-äventyrare på en resa över en hel kontinent, från de krigshärjade klipporna i Kalimdor till tryggheten i Ironforge.",["profession:Engineering"]="Ingenjörer lär uppskatta Gaxims och Lomacs outtröttliga jakt på maximal eldkraft, trots de farliga och krångliga förberedelserna.",["race:Gnome"]="Ett typiskt gnomiskt projekt med akademiska kontakter på långt håll, excentriska rivaliteter och farligt instabila explosiva föreningar."},sec={{t="Ett flyktigt recept",b="Under sin tid bland topparna i Stonetalon Mountains får Gaxim Rustfizzle en idé till sitt hittills mest ambitiösa ingenjörsprojekt. En mekanism av den storleken kräver specialbränsle, långt kraftfullare än vanligt krut eller råolja. Gaxim behöver specifikt Nitromirglyceronium, även betecknat NG-5, en explosiv blandning så kraftig att den garanterar förödande resultat om allt går enligt plan."},{t="Kontakter i Tinker Town",b="Att framställa NG-5 är ingen enkel uppgift, och Gaxim känner bara till en person med tillräcklig kunskap för att förädla det: en gammal bekant vid namn Lomac Gearstrip. Lomac bor långt österut i gnomenklaven Tinker Town, djupt inne i bergsfästet Ironforge. Kuriren får i uppdrag att göra den långa resan, men möts av Lomacs omedelbara misstänksamhet och paranoida frågor."}},faq={{q="Vem ger uppdraget An Old Colleague?",a="Uppdraget ges av Gaxim Rustfizzle, en gnomingenjör stationerad i Stonetalon Mountains.",al={"uppdragsgivare","vem ger uppdraget an old colleague","gaxims uppdrag"}},{q="Var hittar jag Lomac Gearstrip?",a="Lomac Gearstrip finns i Tinker Town, gnomenklaven i den östra delen av dvärgarnas stad Ironforge.",al={"var finns lomac","lomac gearstrips plats","lomac i ironforge"}},{q="Vad är Nitromirglyceronium?",a="Nitromirglyceronium, även kallat NG-5, är ett extremt flyktigt kemiskt sprängämne som har framställts av Lomac Gearstrip och som Gaxim Rustfizzle vill ha till sina kraftfulla apparater.",al={"vad är ng-5","nitromirglyceronium","ng 5"}},{q="Varför skickar Gaxim mig hela vägen till Ironforge?",a="Gaxim hävdar att Lomac Gearstrip är den enda som kan framställa den specialiserade NG-5-förening som behövs för att driva hans experimentella apparat.",al={"varför resa till ironforge","varför lomac","varför gå till tinker town"}},{q="Vad händer när jag har hittat Lomac Gearstrip?",a="När du har bekräftat Gaxims ärende för den misstänksamma Lomac ger han dig uppdraget Ineptitude + Chemicals = Fun, där du ska samla de farliga reagenser som krävs för att blanda satsen.",al={"nästa uppdrag","vad kommer efter an old colleague","fortsättningsuppdrag"}},{q="Vilken fraktion kan utföra uppdraget?",a="Det här är ett uppdrag enbart för Alliance. Det börjar hos en gnom i Stonetalon som står på Alliances sida och slutar i Alliances huvudstad Ironforge.",al={"är det här bara för alliance","horde-version","kan horde göra det här"}}},fx={bce9e2b8={q="Varför behöver Gaxim Rustfizzle dig i stället för att själv åka till Ironforge?",a="Gaxim Rustfizzle är upptagen i Stonetalon Mountains med att rekognosera och förbereda den taktiska placeringen av sina experimentella apparater. Eftersom det krävs en lång resa över havet tillbaka till Tinker Town i Ironforge för att tillverka det högklassiga sprängämnet Nitromirglyceronium, förlitar han sig på en kapabel resenär som kan sköta ärendet medan han stannar på plats och gör operationen redo.",al={"varför behöver gaxim mig","varför skicka en äventyrare till ironforge","varför kan inte gaxim åka till lomac"}}},fp="16,264,17.308.0,22.284.0,37.87.0,33.89.0,28.156.0,48.128.0,43.148.0,38.150.0"}
P.entries["quest:1073"] = {n="Ineptitude + Chemicals = Fun",s="För att hitta ett sprängämne mot Venture Company i Stonetalon Mountains skickas alliansäventyrare över havet till Ironforge. Där går den excentriske gnomen Lomac Gearstrip med på att brygga sin flyktiga uppfinning Nitromirglyceronium, om du hämtar de nödvändiga alkemiska ingredienserna.",h="För att hitta ett sprängämne mot Venture Company i Stonetalon Mountains skickas alliansäventyrare över havet...",kw={"elixir av mindre styrka","gaxim rustfizzle","ironforge","lomac gearstrip","manadryck","nitromirglyceronium","stonetalon","venture company"},ang={["faction:Alliance"]="Den långa färden från Stonetalon till Ironforge visar hur krävande det är att försörja avlägsna alliansutposter utspridda över fientliga Kalimdor.",["profession:Engineering"]="När vanligt sprängkrut inte biter på Venture Companys stål ger kombinationen av esoterisk alkemi och ingenjörskonst långt mer katastrofala resultat.",["race:Gnome"]="Lomac personifierar den tygellösa, galna sidan av gnomisk uppfinningsrikedom. Han prioriterar kemisk verkan och teoretisk användning framför säkerhet och diplomatisk försiktighet."},sec={{t="En flyktig lösning",b="Gaxim Rustfizzle, som håller till högt uppe i Stonetalon Mountains klippiga pass, behövde kraftiga sprängämnen till den mest avancerade anordning han hittills konstruerat mot Venture Company. Därför vände han sig till en excentrisk före detta kollega i Ironforge, Lomac Gearstrip. Lomac har uppfunnit Nitromirglyceronium, ett ämne så instabilt och destruktivt att han tycker det är hysteriskt roligt att någon använder det, oavsett vem som sprängs i bitar."},{t="Drycker till fyrverkerierna",b="Lomac längtar efter att få se goblinernas maskiner, och kanske äventyraren, sprängas i bitar. Men i hans verkstad i Ironforge är lagret av den färdiga blandningen helt slut. Innan han brygger en ny sats Nitromirglyceronium kräver Lomac vanliga alkemiska brygder: mindre manadrycker och elixir av mindre styrka. I hans ögon fyller det dubbla syften att låta en äventyrare samla ingredienserna: han får råvarorna som behövs för reaktionen och ser om äventyraren åtminstone har en gnutta respekt för alkemins hantverk."}},faq={{q="Vem är Lomac Gearstrip?",a="Lomac Gearstrip är en excentrisk gnomisk alkemist och uppfinnare i Ironforge, dvärgarnas huvudstad. Han är en gammal kollega till Gaxim Rustfizzle och upphovsmannen till Nitromirglyceronium, en ovanligt flyktig explosiv blandning.",al={"lomac gearstrip","vem är lomac","gnom i ironforge"}},{q="Varför vill Lomac ha drycker i stället för vanliga ingenjörsdelar?",a="Lomac använder alkemi tillsammans med sina mekaniska kunskaper för att skapa kraftfulla, flyktiga reaktioner. Den magiska energin i mindre manadrycker och de stabiliserande kroppsvätskor som förstärks av elixir av mindre styrka fungerar som grundingredienser i hans särskilda Nitromirglyceroniumblandning.",al={"varför drycker","alkemiska ingredienser","varför manadrycker"}},{q="Varför skicka en äventyrare ända till Ironforge?",a="Gaxim Rustfizzle är isolerad i Stonetalon Mountains vildmark och saknar tillgång till tunga industri- och kemiverkstäder. Lomac Gearstrip i Ironforge är den enda han litar på, eller fruktar tillräckligt, för att ha ett sprängämne kraftfullt nog för hans mest avancerade anordning.",al={"varför ironforge","varför resa så långt","gaxim till ironforge"}},{q="Vad är Nitromirglyceronium?",a="Nitromirglyceronium är Lomac Gearstrips egen explosiva kemiska brygd. Den är ökänd för sin flyktighet, och Lomac kallar den sitt främsta verk.",al={"nitromirglyceronium","vad är sprängämnet","gnomisk bombvätska"}},{q="Bryr sig Lomac om Venture Company eller skogen?",a="Inte det minsta. Lomac skrattar öppet åt tanken på att använda kraftiga sprängämnen för att rädda träd. Hans enda intresse av att lämna ifrån sig blandningen är den kaotiska möjligheten att se antingen gobliner eller kuriren sprängas i bitar.",al={"bryr sig lomac om naturen","lomacs motiv"}},{q="Måste du vara alkemist för att klara uppgiften?",a="Nej. Lomac talar visserligen om att pröva din alkemi, men han godtar lika gärna ingredienser som du fått genom handel, från köpmän eller av andra hantverkare, så länge han får brygderna som receptet kräver.",al={"behövs alkemi","alkemi krävs"}}},fx={["04ca68af"]={q="Varför vill Lomac Gearstrip att det här ska göras?",a="Lomac bryr sig föga om Venture Company, Stonetalon-skogarnas öde eller sin gamla bekant Gaxim Rustfizzle. Det som roar honom är rent kaos och explosiv potential. Han går med på att brygga sitt flyktiga Nitromirglyceronium bara för det skruvade nöjet att se antingen dig eller goblinerna sprängas i småbitar, förutsatt att du skaffar reagenserna som behövs för att fylla på hans lager.",al={"lomac gearstrips motiv","varför hjälpa lomac","varför tillverka nitromirglyceronium"}},["23e9865b"]={q="Vad ska Minor Mana Potion användas till?",a="Minor Mana Potions är viktiga flytande reagenser i Lomacs instabila blandning. Tillsammans med styrkeelixiren fungerar deras magiska energi som en nödvändig katalysator för att framställa en ny sats Nitromirglyceronium, hans flyktiga och stolta alkemiuppfinning.",al={"vad används minor mana potion till","varför minor mana potion","mana potion nitromirglyceronium"}},["2bdc95b5"]={q="Vad ska Elixir of Minor Fortitude användas till?",a="Lomac behöver Elixirs of Minor Fortitude som viktiga beståndsdelar när han brygger Nitromirglyceronium. I hans egendomliga kemiska recept ingår den stärkande blandningen i den reaktiva grundmassa som behövs för att skapa den explosiva föreningen.",al={"vad används elixir of minor fortitude till","varför elixir of minor fortitude","styrkeelixir nitromirglyceronium"}},ba2add0a={q="Varför behöver Lomac dig till att hämta dryckerna i stället för att skaffa dem själv?",a="Lomac har helt slut på förråd och känner ingen brådska att hjälpa dig eller Gaxim på egen bekostnad. Genom att låta dig hämta eller brygga ingredienserna själv tvingar han dig att visa prov på påhittighet och alkemisk skicklighet innan han anförtror dig sin dyrbara och farliga skapelse.",al={"varför behöver lomac mig","varför måste jag hämta dryckerna","varför kan inte lomac hämta sina egna drycker"}}},fp="28,218,19.403.0,24.373.0,23.195.0,66.256.0,57.258.0,28.133.0,57.191.0,53.181.0"}
P.entries["quest:1074"] = {n="Ineptitude + Chemicals = Fun",s="Det här ärendet för en behållare med flyktigt NG-5 från uppfinnaren Lomac Gearstrip till Gaxim Rustfizzle i Stonetalon Mountains. Gaxim behöver den instabila kemikalien för att skapa en kraftfull tändare till flera vagnar lastade med dynamit. Explosionen blir en avgörande avledningsmanöver för Alliansens operationer i de omstridda bergen.",h="Det här ärendet för en behållare med flyktigt NG-5 från uppfinnaren Lomac Gearstrip till Gaxim Rustfizzle i...",kw={"dynamit","ingenjörskonst","gaxim rustfizzle","gnom","lomac gearstrip","ng-5","nitromirglyceronium","stonetalon"},ang={["faction:Alliance"]="Stonetalon är en omstridd gränsbygd. En enorm explosion ger Alliansens agenter det andrum de så desperat behöver.",["profession:Engineering"]="För att hantera NG-5 krävs förståelse för flyktig kemi och stadiga händer, så att det inte detonerar i förtid.",["race:Gnome"]="Bara gnomisk ambition skulle betrakta vagnar med högexplosiva ämnen, antända med Nitromirglyceronium, som en rimlig avledningsmanöver."},sec={{t="En flyktig leverans",b="Gnomisk ingenjörskonst balanserar ofta genialitet på katastrofens knivsegg, och Nitromirglyceronium, eller NG-5, är inget undantag. Lomac Gearstrip överlämnar den instabila blandningen med en sträng varning: hantera den ytterst varsamt, annars riskerar du att spränga dig själv i bitar på vägen tillbaka till Gaxim Rustfizzle."},{t="Ett recept på avledning",b="När Gaxim Rustfizzle får behållaren oskadd avslöjar han omfattningen av sitt verk. NG-5 är den nödvändiga katalysatorn för att spränga hela vagnar fulla med dynamit. Genom att iscensätta en kolossal explosion hoppas Gaxim skapa kaos och vilseleda fiender i Stonetalon medan Alliansen driver sina regionala mål."}},faq={{q="Vad är NG-5?",a="NG-5, en förkortning av Nitromirglyceronium, är en mycket flyktig kemisk förening som Lomac Gearstrip har blandat till. Den fungerar som en obestridlig tändkatalysator för tung ammunition.",al={"vad är nitromirglyceronium","ng-5","vad gav lomac mig"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim Rustfizzle är en gnomisk magiker stationerad i Stonetalon Mountains. Han samordnar Alliansens sprängningsinsatser och taktiska avledningsmanövrar mot regionala hot.",al={"gaxim","vem är gaxim rustfizzle"}},{q="Vem är Lomac Gearstrip?",a="Lomac Gearstrip är ingenjör och medarbetare till Gaxim Rustfizzle. Han tillverkar den farliga blandningen NG-5 och anförtro den åt pålitliga kurirer.",al={"lomac","vem är lomac gearstrip"}},{q="Varför behöver Gaxim så stor sprängkraft?",a="Gaxim har ordnat flera vagnar lastade med dynamit. NG-5 ger den tillförlitliga, kraftiga gnista som krävs för att detonera dem allihop samtidigt och skapa en överväldigande avledningsmanöver.",al={"varför vagnar med dynamit","gaxims plan","varför explosionen"}},{q="Är kemikalien farlig att transportera?",a="Lomac varnar uttryckligen för att NG-5 är instabilt och riskerar att detonera katastrofalt av misstag om det hanteras fel. En stadig kurir kan dock leverera det säkert till Gaxim.",al={"exploderar ng-5","är ng-5 säkert"}},{q="Var sker leveransen?",a="Leveransen avslutas vid Gaxim Rustfizzles postering i de karga bergspassen i Stonetalon Mountains.",al={"var finns gaxim","stonetalon plats"}}},fx={cbbf8960={q="Varför ger Lomac Gearstrip dig NG-5?",a="Lomac uppfyller en begäran från sin medarbetare Gaxim Rustfizzle och tillhandahåller det flyktiga Nitromirglyceronium som han blivit ombedd om. Han ställer inga frågor om detaljerna. Om du verkligen är Gaxims allierade skickar han med en hälsning, och om du är en bedragare låter han gärna sprängämnet spränga dig i bitar.",al={"varför hjälper lomac","lomac gearstrips motiv","varför ge ng5"}}},fp="28,226,19.239.0,24.277.1,13.141.0,24.150.0,23.136.0,44.126.0,39.113.0,36.87.0"}
P.entries["quest:1075"] = {n="A Scroll from Mauren",s="Gaxim Rustfizzle behöver arcansk hjälp för att utlösa sina NG-5-sprängämnen på avstånd. Han skickar dig till Collin Mauren i Stormwind, där gnomisk uppfinningsrikedom möter mänsklig arkan konst.",h="Gaxim Rustfizzle behöver arcansk hjälp för att utlösa sina NG-5-sprängämnen på avstånd.",kw={"collin mauren","devils in westfall","sprängämnen","gaxim rustfizzle","mage quarter","ng-5","fjärrutlösare","stormwind"},ang={["class:Mage"]="Som magiker vet du att Kirin Tor och Stormwinds arkanutövare samarbetar med ingenjörer. De använder evokation och transmutation för att lösa mekaniska problem.",["faction:Alliance"]="Som medlem i Alliansen ser du gnomiska uppfinnare arbeta med de mänskliga magiker som studerar i Stormwinds Mage Quarter.",["profession:Engineering"]="Som ingenjör vet du att flyktigt svartkrut och arkana katalysatorer kan lösa problem som fjärrantändning.",["race:Gnome"]="Som gnom tvekar du aldrig att förena teknik och trolldom när det kan ge en mer katastrofal explosion på bekvämt avstånd."},sec={{t="En gnista över avstånd",b="Gaxim Rustfizzle söker ett säkrare sätt att utlösa sina NG-5-sprängämnen. Mekaniska stubiner kan inte ge honom den fjärrutlösare han vill ha: en knapp ska antända laddningarna medan han själv håller sig på säkert avstånd. Han vänder sig till arkan magi för att överbrygga avståndet."},{t="Kontakten i Mage Quarter",b="Gaxim skickar dig till Collin Mauren i Stormwinds Mage Quarter för den nödvändiga besvärjelsen. Mauren är en mänsklig besvärjare vars praktiska kunskaper om det arkana kan hjälpa till att binda en explosiv antändning till ett kommando på avstånd. Hans arbete inleder besvärjelsen som Gaxim behöver för sitt farliga projekt."}},faq={{q="Vem skickar mig till Collin Mauren?",a="Gaxim Rustfizzle skickar dig till Collin Mauren. Han behöver en arkan formel från sin mänskliga bekant för att färdigställa en fjärrutlösare.",al={"uppdragsgivare","vem ger en scroll from mauren","gaxims uppdrag"}},{q="Var hittar jag Collin Mauren?",a="Collin Mauren finns i Mage Quarter i Stormwind City. Leta efter honom bland områdets instruktörer, lärlingar och arkanforskare vid tornen och butikerna.",al={"collin maurens plats","var finns collin mauren","hitta mauren"}},{q="Varför behöver Gaxim en besvärjelse till en sprängladdning?",a="Gaxim vill utlösa sina NG-5-sprängämnen med en knapp på säkert avstånd. Han söker Maurens arkana kunskaper för en omedelbar fjärrutlösare, eftersom mekaniska metoder kan vara otympliga eller opålitliga på långa avstånd.",al={"varför magi till bomber","historien bakom fjärrutlösning","varför träffa en magiker"}},{q="Vad är NG-5?",a="NG-5, eller Nitromirglyceronium, är ett flyktigt sprängämne som bryggts av Gaxims gamla kollega Lomac Gearstrip i Ironforge. Gaxim behöver ett fjärrutlösningssystem så att den som utlöser sprängämnet kan hålla sig långt utanför sprängradien.",al={"ng-5","vad är ng5","gaxims sprängämne"}},{q="Vad händer efter att jag talat med Collin Mauren?",a="När Collin Mauren har övervägt begäran om en besvärjelse för fjärrutlösning ber han dig hjälpa honom i Westfall i Devils in Westfall.",al={"nästa uppdrag","vad följer efter a scroll from mauren","uppföljning till collin mauren"}},{q="Är Collin Mauren en gnom eller en människa?",a="Collin Mauren är en mänsklig magiker. Gaxim säger att Mauren bör vara lätt att känna igen bland folkmassorna i Stormwind eftersom han är människa.",al={"collin maurens folk","vilket folk tillhör mauren","är mauren människa"}}},fp="20,141,24.202.0,27.215.0,30.129.0,33.162.0,52.219.0,17.222.0,50.132.0,36.114.0"}
P.entries["quest:1076"] = {n="Devils in Westfall",s="Dust devils strövar omkring i Westfall, och Collin Mauren behöver deras rester till en besvärjelse. Magikern i Mage Quarter hjälper Gaxim Rustfizzle med ett ovanligt experiment. Arbetet kräver en meddelanderulle, och stoftet innehåller det Mauren behöver för att förtrolla den.",h="Dust devils strövar omkring i Westfall, och Collin Mauren behöver deras rester till en besvärjelse.",kw={"collin mauren","dust devil","dust devil debris","gaxim rustfizzle","mage quarter","meddelandebesvärjelse","rulle","stormwind","westfall"},ang={["class:Mage"]="Som magiker ser du hur förtrollning kan utnyttja vild elementarresonans för att binda en komplicerad kommunikationsbesvärjelse i en rulle.",["faction:Alliance"]="Som resande i Alliansen färdas du från Stormwinds torn till Westfalls vanskötta fält, där kungarikets gränsland ligger i ruiner.",["profession:Engineering"]="Som ingenjör ser du hur Gaxim Rustfizzles arbete använder magisk rullskrift för att lösa ett kommunikationsproblem."},sec={{t="Komponenter till en budrulle",b="Collin Mauren förbereder en meddelanderulle åt Gaxim Rustfizzle. Magikern hjälper uppfinnaren med ett ovanligt projekt, men besvärjelsen kräver mer än bläck och pergament. Dust devils strövar omkring i Westfall med elementarmagi virvlande inom sig. Deras rester ger det flyktiga medium Mauren behöver för att binda Gaxims besvärjelse till pergamentet."},{t="Elementarödemarken",b="Westfall var en gång Stormwinds bördiga kornbod. Torka, banditdåd och vanvård har gjort fälten torra och vildvuxna. Dust devils strövar omkring där och hotar resande och ensamma nybyggare. Deras rester innehåller den koncentrerade elementarkraft Mauren behöver för att fullborda förtrollningen."}},faq={{q="Vem är Collin Mauren?",a="Collin Mauren är en mänsklig magiker i Stormwinds Mage Quarter. Han arbetar med stadens besvärjare och hjälper ibland forskare utifrån, som Gaxim Rustfizzle, att förbereda förtrollade rullar och magiska komponenter.",al={"collin mauren","vem är uppdragsgivaren","magiker i stormwind"}},{q="Varför behöver Collin Mauren stoft från dust devils?",a="Collin Mauren behöver stoft från dust devils för att förtrolla en meddelanderulle åt Gaxim Rustfizzle. Resterna innehåller elementarkraft som hjälper till att binda besvärjelsen till pergamentet.",al={"varför stoft från dust devils","vad används stoft från dust devils till","varför resa till westfall"}},{q="Var hittar man dust devils?",a="Dust devils strövar omkring på Westfalls torra slätter och karga fält, särskilt på de dammiga sträckorna mellan de vanskötta gårdarna söder om vägen till Sentinel Hill.",al={"plats för dust devils","var finns dust devils","dust devils i westfall"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim Rustfizzle är en ambitiös uppfinnare av gnomer som arbetar med esoteriska ingenjörsprojekt. Collin Mauren hjälper honom att förbereda förtrollade rullar för hans experiment.",al={"gaxim","gaxim rustfizzle","vem är gaxim"}},{q="Vad händer när man lämnar stoftet till Mauren?",a="Med stoftet färdigställer Collin Mauren meddelanderullen och ber dig ta den till Gaxim Rustfizzle, så att uppfinnaren kan fortsätta sina experiment.",al={"uppdragsbelöning","what comes next","efter devils in westfall"}},{q="Är dust devils magiska eller naturliga varelser?",a="Dust devils är mindre luftelementarer som visar sig som levande virvelvindar av sand och grus. De trivs i Westfalls torra och ostadiga landskap.",al={"är dust devils elementarer","dust devil-lore"}}},fx={b0d4cd5a={q="Vad används Dust Devil Debris till?",a="Collin Mauren behöver resterna från en dust devil som en viktig reagens för att förtrolla en särskild skriftrulle. Gaxim Rustfizzle behöver en besvärjelse för att skicka meddelanden i sina egendomliga experiment, och det elementära materialet från virvelvarelsen gör att Mauren kan överföra den magiska förtrollningen till pergamentet.",al={"vad används dust devil debris till","vad är resterna till","varför dust devil debris"}},["9b2ec5a3"]={q="Vad är dust devils för varelser som du jagar?",a="Dust devils är kaotiska luftelementarer som strövar omkring på Westfalls karga slätter och jordbruksmarker. De rörs upp av de turbulenta vindarna och den vilda magin i regionen. Dessa små virvelvindar går till attack mot alla resenärer som korsar deras väg och utgör därför en dödlig fara för både lokala bönder och vandrare.",al={"vad är dust devils","vad jagar dust devils","vilka är dust devils"}}},fp="18,250,24.333.0,20.278.0,21.211.0,46.163.0,28.150.0,24.160.0,49.152.0,45.139.0"}
P.entries["quest:1077"] = {n="Special Delivery for Gaxim",s="Special Delivery for Gaxim är den återgående sträckan av ett allianskuriruppdrag mellan Stormwind City och Kalimdors vildmarker. Collin Mauren tillhandahåller en specialiserad Scroll of Messaging som ska återföras till gnomuppfinnaren Gaxim Rustfizzle i Stonetalon Mountains. Rullen innehåller den magiska komponent som behövs för att bygga en fjärrstyrd sprängladdning mot den lokala avskogningen.",h="Special Delivery for Gaxim är den återgående sträckan av ett allianskuriruppdrag mellan Stormwind City och...",kw={"collin mauren","gaxim rustfizzle","ng-5","fjärrutlöst sprängladdning","scroll of messaging","stonetalon","venture company"},ang={["class:Mage"]="Collin Maurens hantverk visar hur skickliga uppfinnare kan omvandla enkla pergamentförtrollningar till fungerande magiska reläer.",["faction:Alliance"]="Uppdraget visar de logistiska förbindelserna mellan Stormwind, människornas huvudstad, och avlägsna alliansutposter som kämpar mot industriell exploatering på Kalimdor.",["profession:Engineering"]="Gaxims plan visar den egendomliga kombinationen av gnomisk ingenjörskonst och magi, där flyktiga NG-5-sprängämnen paras ihop med magiska utlösare."},sec={{t="Magiska leveranser",b="Gaxim Rustfizzles försök att sabotera Venture Companys destruktiva verksamhet kräver okonventionella lösningar. Efter att ha kokat ihop en explosiv blandning kallad NG-5 upptäckte uppfinnaren att han saknade ett tillförlitligt sätt att fjärrutlösa den. I stället för att använda primitiva stubiner sökte Gaxim hjälp på andra sidan Stora havet och kontaktade Collin Mauren i Mage Quarter i Stormwind för att få en förtrollad Scroll of Messaging."},{t="En avlägsen avledning",b="När Gaxim får rullen avslöjar han hela omfattningen av sin excentriska ingenjörsplan. Det förtrollade pergamentet är inte bara till för att skicka ord över långa avstånd; dess kommunikationsmagi kan i stället kopplas direkt till den instabila NG-5-blandningen. Genom att magiskt utlösa sprängningen på avstånd tänker Gaxim skapa en förödande avledning som låter agenter smyga in i Venture Companys område utan att upptäckas."}},faq={{q="Vad används Scroll of Messaging till?",a="Scroll of Messaging utformades ursprungligen som ett magiskt redskap för att förmedla meddelanden, men Gaxim Rustfizzle kombinerar den med sin flyktiga NG-5-blandning. Meddelandemagin fungerar som en fjärrutlösare och gör att han kan detonera sprängladdningar på säkert avstånd.",al={"varför scroll of messaging","vad gör rullen","syftet med scroll of messaging"}},{q="Vem är Collin Mauren?",a="Collin Mauren är en alliansmagiker i Mage Quarter i Stormwind City. Han hjälper äventyrare med magiska ärenden och tillverkar den förtrollade rulle som Gaxim behöver för sin plan i Stonetalon.",al={"collin maurens historia","vem är collin"}},{q="Varför saboterar Gaxim Rustfizzle Venture Company?",a="Venture Company kalhugger skoningslöst Stonetalon Mountains orörda skogar. Gaxim vill bromsa avskogningen genom att skapa kaos, slå ut deras verksamhet och stjäla deras egna ingenjörsplaner och korrespondens.",al={"varför angripa venture company","gaxims motiv","venture company i stonetalon"}},{q="Vart tar leveransen äventyraren?",a="Leveransen tar kuriren över havet från Stormwind City tillbaka till allianslägret bland klipporna i Stonetalon Mountains på Kalimdor.",al={"leveransens destination","var finns gaxim","var ligger stonetalon"}},{q="Vad händer efter att rullen har levererats?",a="Med både rullen och NG-5 till hands förbereder Gaxim en fjärrutlöst sprängladdning som ska skapa en avledning och röja vägen för en agent att infiltrera verksamheten vid Windshear Crag och hämta timmerbrev och ritningar.",al={"nästa uppdrag","vad händer efter leveransen","avledning mot venture company"}}},fx={["89640f85"]={q="Varför vill Collin Mauren att det här ska göras?",a="Collin Mauren hjälper Gaxim Rustfizzle som en vän och kollega inom arkana konster. Medan Collin tryggt bedriver sina magiska studier i Stormwind är han nyfiken på Gaxims djärva plan mot Venture Company i Kalimdor och bidrar gärna med den nödvändiga besvärjelsen. Han ser fram emot att höra allt om äventyret när det är över.",al={"collin maurens motiv","varför hjälper collin gaxim","varför skickar collin mauren skriftrullen"}}},fp="26,213,17.367.0,20.305.1,41.184.0,21.157.0,55.232.0,45.132.0,43.198.1"}
P.entries["quest:1078"] = {n="Retrieval for Mauren",s="Retrieval for Mauren är ett uppdrag från Collin Mauren i Mage Quarter i Stormwind. Efter att ha hört berättelser om resenärer som beger sig djupt in i Kalimdor anlitar trollkarlen äventyrare från Alliansen för att samla kristalliserade fjäll från basilisker i The Charred Vale i Stonetalon. Mauren vill mala dessa sällsynta exemplar till pulver som ingredienser i sin personliga magi.",h="Retrieval for Mauren är ett uppdrag från Collin Mauren i Mage Quarter i Stormwind.",kw={"basiliskfjäll","the charred vale","collin mauren","kristalliserade fjäll","mage quarter","retrieval for mauren","stonetalon mountains","stormwind"},ang={["class:Mage"]="Att skaffa esoteriska ingredienser åt andra magiker hör till den arkanistiska forskningen och visar hur exotiska magiska varelser bidrar till utvecklingen av nya besvärjelser.",["faction:Alliance"]="Uppdraget visar hur Alliansens närvaro i Stormwind upprätthåller aktiva intressen och försörjningslinjer djupt in i Kalimdors vilda områden."},sec={{t="En magikers märkliga ingredienser",b="Collin Mauren, en trollkarl som bor i Mage Quarter i Stormwind City, håller örat nära samtalen bland kringvandrande äventyrare. Han har hört att avlägsna Stonetalon Mountains i Kalimdor har blivit ett växande resmål för resenärer som söker vilda wyverner, ostyriga elementaler eller lukrativa affärer och sammandrabbningar med Venture Company. Mauren söker varken rikedom eller ära, utan intresserar sig för de sällsynta naturunder som sägs finnas i regionens kargaste trakter."},{t="Dalens glasartade bestar",b="Djupt inne i Stonetalon ligger The Charred Vale, en askfylld trakt som lämnats sargad av Venture Companys förödelse. Enligt Maurens studier hyste bäckenet en gång en säregen ras basilisker. När deras fjäll samlas in och mals till ett fint pulver blir de en kraftfull katalysator för specialiserade besvärjelser som han har utvecklat. Eftersom han inte vet om varelserna överlevde dalens hårda förvandling förlitar sig Mauren på oförvägna upptäcktsresande som kan samla in en ny omgång kristalliserade fjäll och bekräfta att rasen finns kvar."}},faq={{q="Vem är Collin Mauren?",a="Collin Mauren är en magiutövare som finns i Mage Quarter i Stormwind. Han studerar esoterisk magi och förlitar sig ofta på äventyrliga resenärer för att skaffa sällsynta magiska ingredienser från avlägsna länder.",al={"collin mauren","vem ger retrieval for mauren","mauren stormwind"}},{q="Varför behöver Collin Mauren basiliskfjäll?",a="Mauren mal de kristalliserade fjällen till ett fint pulver och använder deras unika mineralsammansättning som katalyserande ingrediens i egna besvärjelser som han har utarbetat.",al={"varför fjäll","vad används fjäll till","användning av kristalliserade fjäll"}},{q="Var ligger The Charred Vale?",a="The Charred Vale är ett förstört, sotigt bäcken i den sydvästra delen av Stonetalon Mountains på kontinenten Kalimdor.",al={"var ligger charred vale","hitta charred vale","charred vale plats"}},{q="Varför är The Charred Vale förkolnad?",a="The Charred Vale ödelades av Venture Companys gobliner. Deras förstörelse gjorde dalens andar ursinniga och släppte lös elementaler, så marken svartnade och pyrde och fylldes av tåliga, förvridna bestar.",al={"vad hände med charred vale","brand i charred vale","förstörelsen av charred vale"}},{q="Vilka varelser släpper fjällen som behövs för uppdraget?",a="Fjällen samlas in från olika basilisker som strövar omkring i The Charred Vales pyrande ödemarker i Stonetalon Mountains.",al={"vilka basilisker","vem släpper kristalliserade fjäll","varelser som släpper fjäll"}},{q="Varför skicka en äventyrare ända över havet för det här?",a="De särskilda kristallina egenskaper som Mauren behöver finns bara hos basiliskerna som hör hemma i The Charred Vale. Eftersom färden över Stora havet är farofylld anlitar Mauren erfarna resenärer som redan är på väg till Kalimdor.",al={"varför kalimdor","varför stonetalon för fjäll"}}},fx={ae0c8dc0={q="Varför vill Collin Mauren ha basiliskfjällen?",a="Collin Mauren är en uppfinningsrik magiker som bor i Stormwind och skapar egna besvärjelser. Han upptäckte att kristalliserade fjäll från basilisker i The Charred Vale i Stonetalon, när de malts till fint pulver, fungerar utmärkt som magisk reagens. Eftersom han stannar i staden och ägnar sig åt magiska studier förlitar han sig på resande äventyrare för att fylla på sitt sällsynta förråd.",al={"collin maurens motiv","varför vill mauren ha fjäll","varför samla fjäll åt mauren"}},c10c105c={q="Vilka varelser jagar du i The Charred Vale?",a="Du skickas in i de förkolnade djupen av The Charred Vale för att spåra upp de basilisker som lever bland askan och de elementära ruinerna. Mauren minns deras unika, kristallbelagda hudar från tidigare rapporter, men är osäker på om de tåliga bestarna överlevde dalens katastrofala brand.",al={"vilka basilisker finns i charred vale","vem slåss jag mot åt mauren","mål för basiliskjakt i stonetalon"}}},fp="20,187,25.399.0,29.451.0,21.127.0,44.105.0,34.85.0,32.210.0,52.83.0,59.180.0"}
P.entries["quest:1079"] = {n="Covert Ops - Alpha",s="Covert Ops - Alpha är ett alliansuppdrag för infiltration, lett av gnommekanikern Gaxim Rustfizzle i Stonetalon Mountains. Från bergstopparna ska agenter tränga in i Venture Companys sågverk i Windshear Crag och hämta företagets tekniska ritningar. Med ritningarna kan Alliansen avslöja svagheter i goblinernas maskiner och ta till sig deras avverkningsteknik.",h="Covert Ops - Alpha är ett alliansuppdrag för infiltration, lett av gnommekanikern Gaxim Rustfizzle i...",kw={"alpha","covert ops","cragpool lake","ingenjörsritningar","gaxim rustfizzle","sågverk","stonetalon","venture company","windshear crag"},ang={["faction:Alliance"]="Genom att säkra fästen och hejda industriell utvinning i Kalimdor kan Alliansen behålla ett taktiskt övertag mot rivaliserande makter som tränger in i omstridda vildmarker.",["profession:Engineering"]="De återfunna ritningarna avslöjar Venture Companys robusta mekanismer med hög förbränning och ger värdefulla tekniska insikter i industriella motorer.",["race:Gnome"]="För en gnommekaniker är goblinritningar det finaste bytet. De ger en sällsynt chans att håna goblinernas konstruktionsmissar och stjäla deras mest lönsamma mekaniska knep.",["race:NightElf"]="Venture Companys avskogning i Windshear Crag skadar Stonetalon Mountains uråldriga skogar, så sabotage av företagets avverkningsutrustning är högsta prioritet för kaldorei."},sec={{t="Sabotage och spioneri",b="Från Windshear Crag bedriver Gaxim Rustfizzle en långvarig hemlig kampanj för att störa Venture Companys aggressiva avverkning. Goblinernas skogshuggare fäller urskogens träd söder om Cragpool Lake, men Gaxim inser att hänsynlös förstörelse inte räcker för att stoppa verksamheten. Plan Alpha prioriterar därför underrättelseinhämtning framför att bara spränga industrimaskiner. Agenterna måste smyga förbi goblinernas skogshuggare och förmän för att lägga beslag på sågverkets viktigaste tekniska ritningar."},{t="Baklängeskonstruktion",b="Gnomenes intresse för Venture Company handlar om mer än nattalvernas natur. Ritningarna visar hur goblinernas kraftiga skogshuggare, mekaniska sågar och motoriserade transporter fungerar. Genom att studera dem kan Alliansens ingenjörer hitta avgörande konstruktionsbrister och slå ut framtida verksamhet. Samtidigt kan de låna förfinade goblindesigner till sina egna mekaniska projekt i Ironforge."}},faq={{q="Vad är huvudmålet med Covert Ops - Alpha?",a="Huvudmålet är att hämta Venture Companys ingenjörsritningar från sågverket i Windshear Crag, söder om Cragpool Lake. Sprängämnen ingår i den övergripande hemliga insatsen, men uppdraget lyckas endast om ritningarna säkras.",al={"vad är covert ops alpha","alphauppdragets mål","vad vill gaxim ha"}},{q="Vem ger uppdraget Covert Ops - Alpha?",a="Uppdraget ges av Gaxim Rustfizzle, en gnommekaniker i Alliansen som är stationerad i Stonetalon Mountains och leder hemliga sabotageinsatser mot goblinernas industri.",al={"vem startar covert ops alpha","gaxim rustfizzle uppdrag","vem ger covert ops-uppdraget"}},{q="Var finns ingenjörsritningarna?",a="Venture Companys ingenjörsritningar finns inne i det aktiva sågverket i Windshear Crag, strax söder om Cragpool Lake och bakom tungt bevakade goblinernas avverkningslinjer.",al={"var finns venture companys ritningar","ingenjörsritningarnas plats","ritningar i sågverket i windshear crag"}},{q="Varför vill Gaxim Rustfizzle ha Venture Companys ritningar?",a="Gaxim vill studera svagheterna i goblinernas skogsmaskiner. När Alliansen hittar deras mekaniska brister kan den sabotera framtida maskiner effektivare och samtidigt ta till sig praktiska goblindesigner för sina egna apparater.",al={"varför stjäla venture companys ritningar","vad ska gaxim göra med ritningarna","orsaken till covert ops alpha"}},{q="Är ren förstörelse uppdragets mål?",a="Nej. Gaxim påminner agenterna uttryckligen om att uppdraget inte lyckas genom att orsaka så stor förstörelse som möjligt, utan genom att hämta ritningarna oskadda från sågverket.",al={"ska jag spränga sågverket","ska jag förstöra maskinerna","fokuserar uppdraget på förstörelse"}},{q="Varför bekämpar Alliansen Venture Company här?",a="Venture Company plundrar Stonetalon på naturresurser genom okontrollerad avskogning och industriföroreningar. Alliansens agenter ingriper för att försvaga företagets industriella närvaro och bevara strategiskt territorium i Kalimdor.",al={"varför bekämpa venture company i stonetalon","konflikten mellan alliansen och venture company","avverkningskriget i stonetalon"}}},fx={f4c6420b={q="Vad ska Venture Co. Engineering Plans användas till?",a="De här detaljerade ritningarna visar de inre mekanismerna och utformningen hos Venture Companys tunga skogsmaskiner i Windshear Crag. Genom att återta dem hoppas Gaxim Rustfizzle kunna hitta kritiska konstruktionsfel och sabotera framtida verksamhet, samtidigt som han stjäl deras bästa idéer för att förbättra Alliansens ingenjörskonst.",al={"användning av venture co engineering plans","vad är ritningarna till","syftet med ingenjörsritningarna"}}},fp="18,184,22.296.0,19.330.0,47.212.0,39.113.0,40.146.0,58.196.0,46.113.0,54.159.0"}
P.entries["quest:1080"] = {n="Covert Ops - Beta",s="Covert Ops - Beta är ett Alliance-uppdrag som organiseras av gnomingenjören Gaxim Rustfizzle i Stonetalon Mountains. Efter tidigare sabotage mot det framryckande Venture Company skickar operationen en agent djupt in i Windshear Mine för att iscensätta explosiva avledningsmanövrar och hämta viktiga verksamhetsbrev. Underrättelserna hjälper både gnomernas nyfikenhet och de regionala Night Elf-sentinellernas försvar av sitt territorium.",h="Covert Ops - Beta är ett Alliance-uppdrag som organiseras av gnomingenjören Gaxim Rustfizzle i Stonetalon...",kw={"covert ops - beta","gaxim rustfizzle","sentineller","stonetalon mountains","venture co.","venture co. letters","windshear crag","windshear mine"},ang={["faction:Alliance"]="När gnomisk teknik samordnas med Night Elves territoriella försvar stärks Alliances bräckliga närvaro i centrala Kalimdor.",["profession:Engineering"]="Uppdraget kretsar kring Gaxims specialanpassade Covert Ops Pack och visar hur fiffiga pyrotekniska avledningar kan uppnå mål som råstyrka ensam inte klarar.",["race:Gnome"]="Gaxim Rustfizzles blandning av högavkastande sprängämnen, noggrann planering och hemlig infiltration är typisk gnomisk uppfinningsrikedom i praktisk militär användning.",["race:NightElf"]="Venture Company skövlar de urgamla skogarna; genom att stödja Gaxims hemliga operationer ser du till att befälhavarna bland Sentinellerna får underrättelserna de behöver för att skydda bergen."},sec={{t="Sabotage i djupet",b="Efter de första angreppen mot Venture Companys kalhuggning i Windshear Crag utformar Gaxim Rustfizzle en uppföljande operation riktad direkt mot deras logistiska nav. Plan Beta följer samma grundprincip som föregångaren: skapa en explosiv, kaotisk avledning som skingrar goblinoperatörer och legosoldater, medan en agent smiter igenom förvirringen och söker efter skriftlig korrespondens i gruvorna."},{t="Ögon på Windshear Mine",b="Windshear Mine ligger längst österut i klippområdet och fungerar som företagets regionala underjordiska bas. Goblinerna gräver genom berg och avverkar timmer och för noggranna liggare och meddelanden om sina försörjningslinjer och ledningens direktiv. Genom att smyga in, placera Gaxims specialanpassade sprängladdningar och beslagta Venture Co. Letters kan agenterna slå ut företagets säkerhet och samtidigt avslöja dess större ambitioner i Kalimdor."},{t="Ett pragmatiskt samarbete",b="Gaxim tar sig an uppdraget med typisk gnomisk förtjusning i pyroteknik och fiffiga manicker, men uppdraget har allvarliga strategiska följder för Night Elves. Sentinellerna i Stonetalon, ledda av befälhavare som Kaela Shadowspear, kämpar hårt mot både Horde och hänsynslösa industriella exploatörer. Underrättelserna från gruvan hjälper Sentinellerna direkt att förutse och förhindra skändningen av deras heliga skogsmarker."}},faq={{q="Vad är målet med Covert Ops - Beta?",a="Målet är att infiltrera Windshear Mine i östra Windshear Crag, iscensätta explosiva avledningsmanövrar med Gaxim Rustfizzles laddning och stjäla Venture Co. Letters, som beskriver deras regionala verksamhet.",al={"målet med covert ops beta","vad gör jag i covert ops beta","plan beta mål"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim Rustfizzle är en gnomingenjör stationerad i Stonetalon Mountains. Han använder sin mekaniska expertis och sina explosiva uppfinningar för att hjälpa Night Elf-sentinellerna bekämpa skogsavverkningen och gruvdriften som tränger in i bergen.",al={"gaxim rustfizzle","vem ger covert ops beta"}},{q="Var ligger Windshear Mine?",a="Windshear Mine är uthuggen i bergen vid den östra änden av Windshear Crag, djupt inne i Venture Companys vidsträckta kalhuggna skogsområde.",al={"windshear mine plats","var ligger gruvan"}},{q="Varför vill Gaxim ha Venture Co. Letters?",a="Breven innehåller viktiga underrättelser om Venture Companys försörjningsrutter, ledningens direktiv och verksamhetsplaner. Att återta dem hjälper Alliance och Sentinellerna att förutse företagets nästa drag och störa dess exploatering av skogen.",al={"varför stjäla brev","vad är venture co letters"}},{q="Hur hjälper uppdraget Night Elves?",a="Night Elf-sentinellerna har inte tillräckligt många soldater för att bevaka varje del av Stonetalon mot industriell skändning. Gaxims sprängsabotage fördröjer avverkningen, medan den återtagna korrespondensen ger befälhavare som Kaela användbara underrättelser om fienderna.",al={"varför bryr sig night elves","sentineller covert ops"}},{q="Vad var Plan Alpha?",a="Plan Alpha var Gaxims föregående hemliga operation: en explosiv avledning vid Venture Companys sågverk söder om Cragpool Lake, medan en agent stal företagets ingenjörsritningar. Plan Beta upprepar samma taktik vid Windshear Mine.",al={"plan alpha","covert ops alpha","föregående uppdrag"}}},fx={c7fb3974={q="Vad ska Venture Co. Letters användas till?",a="Dokumenten innehåller viktiga meddelanden och planer från Venture Companys ledning inne i Windshear Mine. Genom att beslagta dem hoppas Gaxim Rustfizzle och de lokala nattalvernas väktare avslöja The Defilers verksamhet, störa deras hänsynslösa avverkning och gruvdrift i Stonetalon och ge Kaelas försvarare ett viktigt taktiskt övertag.",al={"användning av venture co letters","varför venture co letters","vad är breven"}},["2e3cb5f9"]={q="Vilka infiltrerar du i Windshear Mine?",a="Du slår till mot Venture Company, ett skrupelfritt handelskartell som drivs av gobliner och är ökänt för hänsynslös exploatering av naturresurser. De har befäst sig i Windshear Crag, gräver upp jorden, skövlar de heliga skogarna och struntar i nattalvernas markanspråk. Hela området har förvandlats till ett industriellt sår i landskapet.",al={"fiender i windshear mine","vem finns i windshear crag","venture company i stonetalon"}}},fp="17,237,22.309.0,22.407.0,23.342.0,38.193.0,24.187.0,32.102.0,44.203.0,46.193.0,20.238.0"}
P.entries["quest:1081"] = {n="Reception from Tyrande",s="Reception from Tyrande är ett Alliance-uppdrag som skickar äventyrare från de hårt ansatta sluttningarna i Stonetalon Mountains direkt till nattalvernas huvudstad Darnassus. Efter att ha hjälpt Sentinels att säkra sitt utsatta fäste i Stonetalon mot Venture Company skickas du av Sentinel Thenysil i Astranaar för att få ett formellt erkännande av självaste överprästinnan Tyrande Whisperwind i Temple of the Moon.",h="Reception from Tyrande är ett Alliance-uppdrag som skickar äventyrare från de hårt ansatta sluttningarna i...",kw={"darnassus","kaldorei","reception from tyrande","sentinel thenysil","stonetalon mountains","teldrassil","temple of the moon","tyrande whisperwind"},ang={["faction:Alliance"]="Ett möte med Tyrande Whisperwind blir en betydelsefull länk mellan Kalimdors nattalver och den övriga Alliance, och gör skärmytslingar i vildmarken till erkänd tjänst för Darnassus.",["race:NightElf"]="Att rapportera till överprästinnan Tyrande Whisperwind i Temple of the Moon är en stolt hemkomst och visar din hängivenhet till försvaret av urgamla förfädersmarker."},sec={{t="Ett fäste i Stonetalon",b="Nattalvernas utposter, utspridda över Stonetalon Mountains, utsätts för hårt tryck, särskilt från Venture Company som ödelägger landet. Sentinel Thenysil samordnar arbetet från Astranaar, men det krävs enorm uthållighet för att hålla dessa avlägsna baser vid liv. Det är livsviktigt att säkra försörjningslinjer och underrättelser för att upprätthålla Alliance närvaro i Kalimdors inre, så hjälp utifrån betyder oerhört mycket för de Sentinels som är stationerade där."},{t="Möte med överprästinnan",b="Eftersom din hjälp aktivt har stärkt Sentinels grepp om regionen, skickar Sentinel Thenysil dig tillbaka till Teldrassil. I Temple of the Moon i Darnassus tar överprästinnan Tyrande Whisperwind emot dig personligen. Tyrande erkänner dina växande bedrifter runtom i Kalimdor och välkomnar dig inte bara som en kringvandrande legosoldat, utan som en allierad mästare som strider sida vid sida med kaldorei."}},faq={{q="Var börjar det här uppdraget?",a="Uppdraget börjar hos Sentinel Thenysil i Astranaar i Ashenvale, direkt efter att du har slutfört ”Update for Sentinel Thenysil”.",al={"var får jag reception from tyrande","uppdragsgivare","var finns sentinel thenysil"}},{q="Var hittar jag Tyrande Whisperwind?",a="Tyrande Whisperwind finns i Temple of the Moon, i det centrala distriktet i nattalvernas huvudstad Darnassus på Teldrassil.",al={"var finns tyrande","hitta tyrande","var finns temple of the moon"}},{q="Varför vill Tyrande träffa mig?",a="Dina insatser i Stonetalon har hjälpt till att bevara kaldoreis fäste i det omstridda bergsterritoriet. Sentinel Thenysil tycker att dina insatser för nattalverna förtjänar en personlig uppskattning från deras andliga och militära ledare.",al={"varför vill tyrande prata","syftet med mötet"}},{q="Vilket strategiskt värde har Stonetalon Mountains?",a="Stonetalon utgör en karg buffert mellan Ashenvale och Kalimdors södra slätter. När Hordes styrkor tränger fram från The Barrens är det avgörande för nattalverna att hålla utposterna här, så att de kan övervaka fiendens rörelser och skydda heliga marker.",al={"varför bry sig om stonetalon","stonetalon-lore"}},{q="Blir andra Alliance-folk också erkända här?",a="Ja. Alla Alliance-äventyrare som hjälper Sentinel Thenysil kan göra resan till Darnassus. Det symboliserar det växande ömsesidiga försvaret mellan nattalverna och den övriga Alliance.",al={"kan andra än nattalver göra detta","är det här för människor"}},{q="Finns det ett uppföljningsuppdrag efter mötet med Tyrande?",a="Mötet avslutar budbärar- och understödsuppdragen för Sentinel Thenysil i Stonetalon. Det ger en formell avslutning och en möjlighet att söka vidare order i Darnassus.",al={"what comes next","nästa uppdrag i kedjan"}}},fx={e0e9e6b4={q="Varför skickar Sentinel Thenysil dig till Darnassus?",a="Sentinel Thenysil anser att dina insatser har lagt grunden för att säkra nattalvernas fotfäste i det hårt prövade Stonetalon Mountains. Hon ser hur du har stått emot övergreppen i bergen och vill att nattalvernas ledare, översteprästinnan Tyrande Whisperwind, personligen ska visa sin uppskattning och tacksamhet.",al={"varför skickar thenysil mig","thenysils skäl att skicka mig till tyrande","varför gå till tyrande"}}},fp="22,235,24.328.0,32.308.0,28.113.0,37.96.0,32.208.0,56.190.0,44.162.0,49.130.0"}
P.entries["quest:1082"] = {n="Update for Sentinel Thenysil",s="Det här ärendet för med sig lugnande besked från Stonetalon Mountains klippor till nattalvernas utpost Astranaar. Efter att ha hjälpt Kaela Shadowspear och Gaxim Rustfizzle att hejda Venture Companys framryckning får du i uppdrag att försäkra Sentinel Thenysil om att deras utpost står stadigt.",h="Det här ärendet för med sig lugnande besked från Stonetalon Mountains klippor till nattalvernas utpost...",kw={"ashenvale","astranaar","gaxim rustfizzle","kaela shadowspear","sentinel thenysil","stonetalon","rapport till sentinel thenysil","venture co"},ang={["faction:Alliance"]="Kommunikation mellan utposterna vid Stonetalon Mountains gräns och Ashenvales fästen hjälper till att säkra Alliances närvaro i centrala Kalimdor.",["race:Gnome"]="Till och med Sentinel Thenysil erkänner motvilligt att det är en lättnad att Gaxim Rustfizzle är oskadd. Det visar att gnomisk uppfinningsrikedom kan vinna respekt även bland traditionalistiska alver.",["race:NightElf"]="Beskedet om att Kaela överlevt försäkrar Sentinels om att deras grepp om Kalimdors gränsland inte har brutits av industrins intrång."},sec={{t="Ett bud från topparna",b="Stonetalon Mountains branta pass är en avlägsen och utsatt gränsmark för nattalverna. Venture Companys skogsskövling äter sig in i klipporna och förorenar vattendragen. Utposten, bemannad av Kaela Shadowspear och gnommekanikern Gaxim Rustfizzle, är ständigt hotad. När de omedelbara farorna från Venture Company har avvärjts är det viktigt att hålla befälet informerat. Kaela skickar dig nordost över gränsen tillbaka till Ashenvale för att bekräfta att de har klarat sig."},{t="Lättnad i Astranaar",b="I Astranaars skogsklädda fristad håller Sentinel Tara Thenysil uppsikt över Ashenvales inre vägar och oroar sig samtidigt för spejare som skickats till mer ogästvänliga trakter. Beskedet att både Kaela och hennes excentriska tekniska partner lever och aktivt återställer landet ger ett sällsynt glädjebesked. Det visar att samarbete med allierade från Alliance kan hejda den ekologiska förstörelsen, trots minskande styrkor och fiender på flera fronter."}},faq={{q="Vem är Sentinel Thenysil?",a="Tara Thenysil är en officer bland nattalvernas Sentinels, stationerad i Astranaar, Ashenvales främsta nav för Alliance. Hon håller koll på spejare och patruller som skickats ut i vildmarken och närliggande områden.",al={"sentinel thenysil","tara thenysil","thenysil astranaar"}},{q="Varför är Kaela Shadowspear i Stonetalon Mountains?",a="Kaela Shadowspear skickades till Stonetalon Mountains för att övervaka och bekämpa Venture Companys miljöförstörande exploatering. Tillsammans med gnommen Gaxim Rustfizzle saboterar hon goblinernas maskiner och återställer landet.",al={"kaela shadowspear","kaelas uppdrag","varför är kaela i stonetalon"}},{q="Vem är Gaxim?",a="Gaxim Rustfizzle är en gnomingenjör från Alliance, stationerad tillsammans med Kaela Shadowspear i Stonetalon Mountains. Hans bullriga yrke går kanske inte ihop med alvernas traditionella värderingar, men hans tekniska kunskaper är avgörande för att slå ut goblinernas skogsmaskiner.",al={"gaxim","gaxim rustfizzle","gnommen med kaela"}},{q="Var hittar jag Sentinel Thenysil?",a="Sentinel Thenysil är stationerad i Astranaar, vid huvudvägen genom centrala Ashenvale, nordost om stigen som leder ner från Stonetalon Mountains.",al={"var är thenysil","thenysils plats","var ligger astranaar"}},{q="Vad händer efter att jag rapporterat till Sentinel Thenysil?",a="När du rapporterar framgångarna i Stonetalon Mountains till Sentinel Thenysil öppnas fler möjligheter inom nattalvernas militär, och du får kontakt med befäl på högre nivå i Darnassus.",al={"nästa uppdrag efter thenysil","vart går jag härnäst","hälsning från tyrande"}},{q="Varför är Venture Company ett hot i Stonetalon Mountains?",a="Venture Company kalhugger skoningslöst heliga lundar, driver väldiga skogsmaskiner och förgiftar vattendragen i Stonetalon Mountains. Det hotar direkt den naturliga balansen som nattalverna skyddar.",al={"venture co stonetalon","varför slåss man mot venture co"}}},fx={be49c188={q="Varför vill Kaela Shadowspear att du levererar den här rapporten?",a="Kaela och Gaxim arbetar djupt inne i det omstridda Stonetalon Mountains för att stoppa Venture Companys miljöförstörelse, och har blivit avskurna. Kaela behöver få ett meddelande till Astranaar så att väktarnas ledning vet att deras uppdrag fortfarande pågår och går framåt, i stället för att ha gått förlorat i vildmarken eller under goblinernas maskiner.",al={"varför skicka rapport till thenysil","kaela shadowspears motiv","varför rapportera till astranaar"}},["9e9209a2"]={q="Varför skickar Kaela dig i stället för att gå själv?",a="Kaela och Gaxim kan inte lämna sin post. Venture Companys skogsskövling och gruvdrift utgör ett omedelbart hot mot klippan och de omgivande bergen. Om de gav sig av nu skulle de överge marken som ni nyss kämpade hårt för att säkra, så de förlitar sig på en duglig resenär som du för att föra meddelandet norrut.",al={"varför skicka ingen väktare","varför kan kaela inte rapportera tillbaka","varför behöver kaela mig"}}},fp="28,214,25.367.0,19.364.0,25.204.0,49.203.0,13.201.0,34.124.0,55.178.0,50.173.0"}
P.entries["quest:1083"] = {n="Enraged Spirits",s="Enraged Spirits är ett alliansuppdrag som Kaela Shadowspear ger i Stonetalon Mountains. Efter att Venture Company ödelade The Charred Vale med eld och tunga maskiner bröt rasande eldelementaler sig fria och översvämmade den sargade sänkan. Alliansens hjältar ombeds kuva dessa kringströvande andar av eld och sten, så att det sårade landet en dag kan läka under Elunes nåd.",h="Enraged Spirits är ett alliansuppdrag som Kaela Shadowspear ger i Stonetalon Mountains.",kw={"the charred vale","elune","enraged spirits","eldelementaler","kaela shadowspear","smoldering embers","stonetalon mountains","venture company"},ang={["class:Druid"]="Druider ser de härjande eldelementalerna som en katastrofal rubbning av naturens jämvikt, som kräver aktiva ingripanden innan liv kan återvända till jorden.",["class:Shaman"]="Schamaner förstår att elementalerna reagerar direkt och plågsamt på dödligas hänsynslösa exploatering av jorden genom gruvdrift och skogsavverkning.",["faction:Alliance"]="Alliansen arbetar genom nattalvssentineller i Stonetalon för att begränsa kaoset som goblinkartellerna orsakat och återställa säkerheten på bergspassen.",["race:NightElf"]="För nattalverna är förödelsen i The Charred Vale ett hjärtskärande sår i Kalimdors heliga vildmarker, som orsakats av ohämmad industriell girighet."},sec={{t="En tragedi i aska",b="The Charred Vale var en gång en lummig fristad i Stonetalon, men Venture Companys hänsynslösa girighet förvandlade platsen till en askgrå ödemark. För att fälla träd och utvinna landets resurser använde trollen brandbomber och tunga maskiner som satte hela trädkronorna i brand. Deras destruktiva ingrepp förstörde inte bara träden, utan rubbade också den sköra elementbalansen under marken."},{t="Frigjord vrede",b="Trollens expedition gick inte som planerat. Eldsvådan och de djupa utgrävningarna väckte uråldriga slumrande andar av eld, sten och vrede ur djupet. De rasande elementalerna vände sig genast mot inkräktarna, drev tillbaka Venture Company och gjorde anspråk på den rykande kratern. Kaela Shadowspear sörjer att naturen inte kan börja återhämta sig förrän dessa kaotiska elementaler har röjts undan."}},faq={{q="Vem ger uppdraget Enraged Spirits?",a="Kaela Shadowspear, en nattalvssentinell stationerad i Stonetalon Mountains, ger uppdraget till alliansäventyrare som vill hjälpa landet.",al={"uppdragsgivare","var får man enraged spirits","vem startar enraged spirits"}},{q="Varför härjar eldelementalerna i The Charred Vale?",a="Venture Company kalhögg och brände skogen med destruktiva maskiner. Deras invasiva industrimetoder rubbade jorden och släppte lös slumrande andar av eld, sten och vrede som snabbt översvämmade området.",al={"varför finns elementaler här","vad orsakade eldelementalerna","eldandar i the charred vale"}},{q="Vad hände med Venture Company i The Charred Vale?",a="Trollen satte skogen i brand, men deras vårdslöshet släppte lös elementaler som var långt farligare än de hade räknat med. De rasande eldvarelserna övermannade deras verksamhet och lämnade förstörda läger och brinnande spillror efter sig.",al={"venture companys öde","dog troll i the charred vale","venture company i the charred vale"}},{q="Vad är Smoldering Embers?",a="Smoldering Embers är brinnande rester som samlas in från förstörda eldelementaler i The Charred Vale och förs tillbaka till Kaela Shadowspear som ett fysiskt bevis på att deras kaotiska antal har minskat.",al={"smoldering embers bakgrund","vad används glöden till","glöd från enraged spirits"}},{q="Kan The Charred Vale någonsin återhämta sig?",a="Kaela Shadowspear tror att landet inte kan känna Elunes välsignelse eller återhämta sig så länge fientliga elementaler strövar omkring bland askan. Att avlägsna dessa härjande andar är första steget mot en framtida läkning.",al={"kommer the charred vale att läka","läka the charred vale","kan sänkan räddas"}},{q="Var ligger The Charred Vale?",a="The Charred Vale ligger i den sydvästra delen av Stonetalon Mountains och kännetecknas av svartbränd jord, förkolnat timmer och kringströvande elementalandar.",al={"the charred vales plats","hitta the charred vale","var finns elementalerna"}}},fx={db30736e={q="Varför vill Kaela Shadowspear att de ursinniga andarna ska röjas undan?",a="Förödelsen i The Charred Vale krossar Kaela Shadowspears hjärta. Den hänsynslösa skändningen släppte lös våldsamma brinnande andar av eld, sten och raseri över landet. Som nattalv tror hon att den sargade jorden inte kan få Elunes nåd eller börja läka så länge dessa kaotiska elementkrafter strövar fritt. Att röja undan dem är första steget mot att återställa friden i den sårade dalen.",al={"varför röja undan andarna","kaela shadowspears motiv","varför vill kaela att detta görs"}},["3905caa9"]={q="Vilka varelser strider du mot i The Charred Vale?",a="Du jagar de brinnande andarna, elementaler födda ur eld, smält sten och ursinnigt raseri, som nu hemsöker The Charred Vales förkolnade ödemark. De väcktes och hetsades upp när Venture Company satte skogarna i brand och slet sönder jorden med maskiner. Nu väller dessa fientliga varelser fram över ruinerna och anfaller alla som vågar närma sig.",al={"elementaler i charred vale","vad är de brinnande andarna","vem slåss jag mot bland de ursinniga andarna"}}},fp="15,277,18.334.0,14.285.0,36.135.0,58.190.0,57.200.0,27.185.0,34.166.0,34.132.0"}
P.entries["quest:1084"] = {n="Wounded Ancients",s="Wounded Ancients är ett alliansuppdrag som Kaela Shadowspear ger i Stonetalon Mountains. Kaela misstänker att goblinernas ammunition gjorde skogsväktarna galna och skickar äventyrare att hämta splitter från de korrumperade träantarna, så att gnomingenjören Gaxim Rustfizzle kan analysera förgiftningen.",h="Wounded Ancients är ett alliansuppdrag som Kaela Shadowspear ger i Stonetalon Mountains.",kw={"corroded shrapnel","korruption","gaxim rustfizzle","kaela shadowspear","stonetalon","träantar","venture company","wounded ancients"},ang={["class:Druid"]="Träantarna är naturens levande puls. Att dra ut den främmande metall som förgiftar deras kroppar är en bister nödvändighet när man bekämpar Venture Companys förstörelse.",["profession:Engineering"]="Den korroderade metallen från träantarna visar hur destruktiv och hafsig Venture Companys ammunition är jämfört med gnomernas förfinade hantverk.",["race:Gnome"]="Gaxim Rustfizzles analytiska blick visar hur mekaniskt hantverk kan användas för att förstå och diagnostisera miljöbrott som begås av ansvarslösa ingenjörer.",["race:NightElf"]="Att se uråldriga skogsförsvarare ruttna och förvridas av goblinernas industri är en skymf mot varje kaldorei som värnar om Kalimdors vildmarker."},sec={{t="Fördärvade väktare",b="De skogsklädda dungarna i Stonetalon vaktades länge av väldiga träantar, milda men våldsamma väktare som var knutna till landets hälsa. När Venture Company flyttade in med motorsågar, sprängämnen och dagbrott svarade naturen. Träantarna drev framgångsrikt bort inkräktarna från delar av dalen, men segern hade ett lömskt pris. Försvararna återgick inte till sitt fredliga väktarskap. I stället blev de fientliga, vansinniga skal."},{t="Gnomisk undersökning",b="Kaela Shadowspear, en alliansspejare stationerad i bergen, tror inte att träantarnas förfall beror på någon naturlig sjukdom. Gnomingenjören Gaxim Rustfizzle misstänker att boven finns i den kemiska och mekaniska arsenalen som goblinerna använde under sin kaotiska reträtt. Genom att bända loss korroderat splitter ur de sårade träbestarna hoppas Gaxim kunna avgöra om Venture Companys ammunition aktivt förgiftar Stonetalon Mountains uråldriga beskyddare."}},faq={{q="Vem erbjuder uppdraget Wounded Ancients?",a="Kaela Shadowspear ger uppdraget. Hon är en alliansagent som bevakar den tilltagande konflikten och de ekologiska skadorna i Stonetalon Mountains.",al={"uppdragsgivare för wounded ancients","vem ger wounded ancients","kaela shadowspear uppdrag"}},{q="Varför är träantarna korrumperade?",a="Gaxim Rustfizzle misstänker att giftig ammunition och beväpning från Venture Company fastnade i träantarna under goblinernas kaotiska reträtt och långsamt förgiftade och drev skogsväktarna till vansinne.",al={"varför är träantar galna","korrumperade träantar i stonetalon","orsaken till träantarnas korruption"}},{q="Vilket föremål måste hämtas till uppdraget?",a="Du måste hämta en bit Corroded Shrapnel, som sitter fast i barken och köttet på de sårade träantarna som vandrar i området.",al={"föremål i wounded ancients","corroded shrapnel uppdrag"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim är en gnomingenjör med band till Alliansen som hjälper Kaela Shadowspear. Han använder sina mekaniska kunskaper för att undersöka Venture Companys teknik och ta reda på hur deras vapen korrumperar naturligt liv.",al={"gaxim","gnom i stonetalon","gaxim rustfizzles roll"}},{q="Vad gör Venture Company i Stonetalon?",a="Venture Company är ett hänsynslöst gobliniskt skogs- och gruvsyndikat som invaderade Stonetalon för att kalhugga heliga skogar och plundra mineralfyndigheter utan hänsyn till den lokala balansen.",al={"venture company i stonetalon","varför är gobliner i stonetalon"}},{q="Blir träantarna friska av att man samlar in splitter?",a="Nej. Splitterbiten är enbart ett analysprov som Gaxim ska undersöka för att fastställa giftets natur och ursprung. Den botar inte de korrumperade väktarna direkt.",al={"kan träantar botas","återhämtar sig träantar"}}},fx={["6c6333aa"]={q="Varför vill Kaela Shadowspear ha Corroded Shrapnel?",a="Kaela är djupt bekymrad över den förvridning som drabbar The Charred Vales beskyddare. Efter att Venture Company drevs tillbaka lämnades de uråldriga treanterna våldsamma och vansinniga. Hon lovade Gaxim Rustfizzle att skaffa ett prov av goblinernas ammunition som sitter i de sårade uråldriga väktarna. Hon hoppas att gnomen kan undersöka det och bekräfta om inkräktarnas grymma vapen verkligen förgiftar landets försvarare.",al={"kaela shadowspears motiv","varför hjälpa treanterna i stonetalon","varför vill kaela ha splitter"}},["4feb3a85"]={q="Vad är Corroded Shrapnel?",a="Corroded Shrapnel består av taggiga metallfragment som Venture Company avfyrade mot treanterna under sin reträtt. Gaxim Rustfizzle misstänker att giftiga eller explosiva rester på järnet fick de uråldriga väktarna att tragiskt sjunka ner i vansinne. Kaela behöver få provet tillbaka så att Gaxim kan undersöka dess kemiska sammansättning och hitta en väg framåt.",al={"vad är corroded shrapnel","corroded shrapnel i stonetalon","splitterlore"}},["2aa0bc4f"]={q="Varför skickas du mot de sårade treanterna?",a="De sårade treanterna var en gång fredliga väktare av The Charred Vale, innan Venture Companys avverkning och krigföring ödelade dalen. Under reträtten träffade goblinerna försvararna med vidriga vapen och lämnade dem sargade, vansinniga och fientliga mot alla som närmar sig. För att få loss splitter som fastnat i deras bark måste du möta dessa plågsamt förvridna varelser.",al={"varför döda sårade treanter","vilka är de sårade uråldriga väktarna","treanter i charred vale"}}},fp="16,240,19.381.0,21.398.0,38.138.0,30.184.0,42.115.0,24.186.0,53.184.0,46.150.0"}
P.entries["quest:1085"] = {n="On Guard in Stonetalon",s="On Guard in Stonetalon leder Alliansens resenärer från Kaela Shadowspear till Gaxim Rustfizzle vid deras läger nära Windshear Crag. När Venture Company härjar och skövlar förenas ett osannolikt par – en försiktig Night Elf-vaktpost och en excentrisk gnomuppfinnare – för att skydda bergspasset.",h="On Guard in Stonetalon leder Alliansens resenärer från Kaela Shadowspear till Gaxim Rustfizzle vid deras...",kw={"ingenjörskonst","gaxim rustfizzle","gnom","kaela shadowspear","night elf","stonetalon","stonetalon peak","venture company"},ang={["faction:Alliance"]="Det här samarbetet visar Alliansens bredare anda i praktiken, när kunskaper från Eastern Kingdoms förenas med Kalimdors Sentinels för att hejda gemensamma hot längs gränsen.",["profession:Engineering"]="Gaxims uppdrag visar hur användbar ingenjörskonst är för spaning i frontlinjen och för att försvara ekosystem. Kugghjul kan tjäna naturvården när de riktas mot hänsynslös exploatering.",["race:Gnome"]="Gaxim Rustfizzle representerar stolt gnomisk uppfinningsrikedom i Kalimdor och visar genom sin närvaro att vetenskap, ingenjörskonst och magi kan övervinna utmaningar där uråldriga traditioner inte räcker till.",["race:NightElf"]="För kaldoreiska vaktposter krävs det att man sväljer en hel del stolthet för att lita på en gnomisk uppfinnare som förespråkar att ingenjörskonst förenas med magi. Det visar hur förödande Venture Companys skogsavverkning har blivit."},sec={{t="En osannolik allians",b="Night Elves och gnomer har sällan mycket gemensamt, särskilt när det gäller teknik och naturen. Men i klipporna i Stonetalon Mountains överbryggar nöden kulturklyftan. När den rovgiriga Venture Company skövlar vildmarken och fäller uråldriga träd har vaktposten Kaela Shadowspear insett att ren krigisk styrka inte räcker för att hejda den industrialiserade plundringen. Att välkomna gnomisk uppfinningsrikedom till helig kaldoreisk mark visar hur kritiskt läget har blivit."},{t="Gnomisk filosofi",b="Gaxim Rustfizzle förkroppsligar den excentriska pragmatism som utmärker Alliansens mindre allierade. Night Elf-samhället vände sig som bekant bort från magiskt överflöd för årtusenden sedan, men Gaxim anser att de blir sårbara om de avstår från magi och teknisk innovation. Genom att förena alkemi och ingenjörskonst med en gnutta arkandisciplin vill Gaxim övertyga sina kaldoreiska värdar om att praktisk vetenskap kan skydda naturen lika effektivt som båge och glaive."}},faq={{q="Varför arbetar en Night Elf och en gnom tillsammans här?",a="Venture Companys hänsynslösa skogsskövling och resursutvinning i Stonetalon är så omfattande att Kaela Shadowspear har tagit emot hjälp utifrån. Gaxim bidrar med ingenjörskunskaper och alkemisk expertis som Night Elves vanligtvis saknar, och erbjuder tekniskt stöd för att motverka moderna industrimaskiner.",al={"varför är gaxim med kaela","kaela och gaxim","allians mellan gnom och night elf"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim är en äventyrlig gnomisk ingenjör och uppfinnare, stationerad i ett läger nära Windshear Crag. Han anser bestämt att Night Elves strikta aversion mot arkan magi gör dem underlägsna. Han vill bevisa att ingenjörskonst, alkemi och kontrollerad magi tillsammans kan lösa även de värsta hoten.",al={"gaxim rustfizzle bakgrund","vem är gaxim","gnom vid stonetalon peak"}},{q="Vem är Kaela Shadowspear?",a="Kaela Shadowspear är en Night Elf-vaktpost med uppgift att hålla vakt och försvara Stonetalon Mountains. Hon är en regional befälhavare som samordnar motståndet mot Venture Company.",al={"kaela shadowspear","vem är kaela"}},{q="Vilket hot utgör Venture Company i Stonetalon?",a="Venture Company är ett skrupelfritt handelssyndikat som fäller heliga skogar, driver destruktiva borriggar och förorenar orörda marker i Stonetalon för att snabbt göra vinst.",al={"venture company i stonetalon","varför bekämpa venture company"}},{q="Vem är Tara, som Kaela nämner?",a="Tara är Sentinel Tara Thenysil, Kaelas vän i Astranaar som skickade dig för att se till henne. Kaela är stolt över att Tara klarar sig så bra bland Sentinels att hon kan skicka ut äventyrare på ärenden.",al={"tara i stonetalon","skicka tillbaka dig till tara"}},{q="Vart leder uppdraget härnäst?",a="Efter att du talat med Gaxim Rustfizzle erbjuder han ”A Gnome's Respite” och ber dig hjälpa till att hålla Venture Companys skogshuggare tillbaka i Windshear Crag, så att han får tid att planera sina nästa uppfinningar.",al={"uppdrag efter on guard in stonetalon","nästa uppdrag efter gaxim"}}},fx={["6de32c22"]={q="Varför vill Kaela Shadowspear att du ska tala med Gaxim?",a="Venture Company har ödelagt stora delar av Stonetalon, och Kaela har nästan inte haft tid till annat än att försöka hejda deras förstörelse. I desperat behov av hjälp har hon lagt nattalvernas traditionella motvilja åt sidan och allierat sig med gnomeingenjören Gaxim Rustfizzle. För att göra effektivt motstånd och skydda bergen behöver hon att du samordnar dig direkt med Gaxim och bidrar till deras gemensamma insatser.",al={"varför tala med gaxim","kaela shadowspears motiv","varför skickar kaela dig till gaxim"}}},fp="22,271,20.405.0,18.360.0,54.285.0,24.273.0,25.184.0,56.189.0,32.188.0,31.187.0"}
P.entries["quest:1086"] = {n="The Flying Machine Airport",s="På uppdrag av Apothecary Zamah från Thunder Bluff jagar hordens äventyrare upp en gömd landningsplats för Venture Company ovanför Stonetalon Mountains. Med en alkemisk Toxic Fogger måste agenterna ta sig in i hjärtat av goblinernas skogsavverkning för att gasa deras flygknutpunkt. Uppdraget slår direkt mot kartellens kommunikationer och visar samtidigt Royal Apothecary Societys hänsynslösa metoder.",h="På uppdrag av Apothecary Zamah från Thunder Bluff jagar hordens äventyrare upp en gömd landningsplats för...",kw={"flyghamn","apothecary zamah","helikopterplatta","cragpool lake","flygmaskin","stonetalon","thunder bluff","toxic fogger","venture company"},ang={["faction:Horde"]="För att säkra Stonetalon måste Venture Company stängas ute från hjälp utifrån, och ett angrepp mot deras lufttransporter är ett viktigt logistiskt slag.",["profession:Engineering"]="Goblinernas helikopterplatta visar den grova, funktionella ingenjörskonst som driver Venture Companys snabba transporter över oländiga bergskedjor.",["race:Tauren"]="Ditt folk avskyr Venture Companys förstörelse av Stonetalon, men användningen av kemiska gifter på inrådan av en Forsaken-apotekare prövar balansen mellan vördnad för jordmodern och hård pragmatism på slagfältet.",["race:Undead"]="För Forsaken är det vardagsmat att sätta in Toxic Fogger i Stonetalon. Det visar Kalimdor att Undercitys alkemiska snille kan lösa problem som råstyrka inte rår på."},sec={{t="En tyst leverans",b="Medan taurerna försöker skydda Stonetalon från avskogning och skövlande maskiner för fram Forsaken en helt annan filosofi. Apothecary Zamah gör i ordning Apothecary Lydons gift för att störa Venture Companys logistik. I stället för att angripa fotsoldater eller skogshuggare direkt siktar hon in sig på kartellens länk till omvärlden: en omtalad helikopterplatta som används för att frakta lätt last och meddelanden mellan Stonetalon och avlägsna företagskontor."},{t="Cragpools flyghamn",b="Högt uppe i Cragpool Lake-området, söder om det stora vattenhjulet, ligger Venture Companys helikopterplatta, ovanför sotet och det fällda timret. Den är liten och avsedd för lätta flygmaskiner snarare än massiva zeppelinare. Om Toxic Fogger utlöses direkt på plattan kvävs varje pilot, kurir eller mekaniker som arbetar där i giftig ånga innan de hinner varna sina befälhavare."},{t="De Forsakens pragmatism",b="När Apothecary Zamah får höra om bombningen ber hon inte om ursäkt för att ha använt kemisk krigföring mot goblinerna. Enligt henne förtjänar Venture Company mycket värre för vad de gör med landet. Än viktigare är att hon ger Horden en grundläggande lärdom ur Undercitys doktrin: tveka aldrig inför mörka vägar om de leder till slutlig seger."}},faq={{q="Var ligger flygmaskinernas flyghamn?",a="Venture Companys helikopterplatta ligger i Cragpool Lake-regionen i Stonetalon Mountains. Du hittar den upphöjda träplattformen söder om det enorma industriella vattenhjulet, med utsikt över sjöns södra krök.",al={"var ligger flyghamnen","helikopterplattans plats","venture companys landningsplats","venture co landningsplatta"}},{q="Varför vill Apothecary Zamah förgifta platsen?",a="Zamah vill skära av Venture Companys kommunikationer och lätta försörjningslinjer mellan Stonetalon och deras avlägsna högkvarter. Genom att förgifta helikopterplattan hoppas hon slå ut goblinernas flygbesättningar och kanske låta giftet följa med tillbaka till deras företagsledare.",al={"varför bomba flyghamnen","varför använda toxic fogger","zamahs motiv"}},{q="Vem är Apothecary Zamah?",a="Apothecary Zamah är ett sändebud för Royal Apothecary Society, stationerad i The Pools of Vision under Thunder Bluff. Hon studerar Kalimdors flora och fauna samtidigt som hon utvecklar alkemiska vapen åt Forsaken och Horden.",al={"zamahs identitet","vem är zamah","odöda i thunder bluff"}},{q="Varför använder Horden kemiska vapen här?",a="Forsaken strider med pragmatisk hänsynslöshet. Deras taurenallierade föredrar andlig läkedom och att försvara jorden direkt, men Zamah anser att Venture Companys destruktiva girighet motiverar skoningslösa metoder. Hon lär ut att segern väger tyngre än sentimental återhållsamhet.",al={"horden använder pest","varför förgifta gobliner","är det här pest"}},{q="Vilken sorts luftfarkoster använder Venture Company här?",a="Plattformen är dimensionerad för små goblinska flygmaskiner och gyrokoptrar, inte fullstora zeppelinare. Dessa smidiga farkoster låter kartellen snabbt ta sig förbi Stonetalon Mountains oländiga bergspass och transportera viktiga meddelanden och varor.",al={"venture companys helikoptrar","vilken flygmaskin","goblinska luftfarkoster i stonetalon"}},{q="Vad händer när dimspridaren sätts ut?",a="När du släpper ut dimspridaren högst upp på plattformen flyr du innan ångorna hinner ta dig. Zamah ser utsläppet som en framgång och räknar med att giftet kommer att störa goblinernas logistik allvarligt.",al={"dimsprejarens följder","efter att dimsprejaren placerats"}}},fx={ee15b44c={q="Vilka angriper du på flygplatsen, och varför är de där?",a="Du angriper Venture Company, ett hänsynslöst goblinkartell som dagbrottsbryter och kalhugger Stonetalon Mountains för vinnings skull. De driver en hemlig flyghamn för att transportera meddelanden och lätt last till sitt avlägsna högkvarter. Genom att slå till mot landningsplatsen med Apothecary Zamahs giftsprej vill Horden strypa deras försörjningsled och sprida giftet direkt till deras ledning.",al={"mål för venture company på flygplatsen","vem angriper vi i stonetalon","varför är venture company här"}}},fp="26,206,17.417.0,19.336.0,19.270.1,44.199.0,50.244.0,24.225.0,45.270.0,56.198.0,42.176.1"}
P.entries["quest:1087"] = {n="Cenarius' Legacy",s="Cenarius' Legacy är ett Horde-uppdrag som Braelyn Firehand delar ut nära Sun Rock Retreat i Stonetalon Mountains. Den blodälviska magikern är frustrerad över de naturliga skydd som Night Elf och Cenarius barn upprätthåller och vill minska deras antal vid Stonetalon Peak för att återställa magins obehindrade flöde. För Horde innebär ett angrepp på Cenarion-försvararna också att Alliansens närvaro i regionen försvagas.",h="Cenarius' Legacy är ett Horde-uppdrag som Braelyn Firehand delar ut nära Sun Rock Retreat i Stonetalon...",kw={"braelyn firehand","cenarion botanist","cenarius' legacy","daughter of cenarius","jaedenar","ordanus","son of cenarius","stonetalon peak","sun rock retreat"},ang={["class:Druid"]="För tauren-druider är det obekvämt och djupt splittrande att slakta Cenarius avkomma och botaniker från Cenarion Circle. Det blottlägger den tragiska friktionen mellan lojalitet mot fraktionen och naturens heliga vägar.",["class:Mage"]="Braelyns klagomål klingar sant för arkanmagiker som känner igen friktionen mellan kaldoreis uråldriga skydd och leyenergiernas fria flöde, även om hennes obetänksamma iver gränsar till besatthet.",["faction:Horde"]="Stonetalon Peak är den största bastionen för Alliansens och kaldoreis styrka i bergskedjan. Att rensa ut försvararna är avgörande för att skydda Sun Rock Retreat och Greatwood Vale."},sec={{t="Hämmade strömmar",b="Braelyn Firehand bor bland kullarna nära Sun Rock Retreat och kokar av frustration över Stonetalon naturliga miljö. Enligt henne undertrycker och kväver druiderna i Cenarion Circle och halvguden Cenarius avkomma aktivt landets magiska strömmar. Hon beskriver kraftkanaliseringen här som att hämta vatten med en läckande hink och längtar efter att avlägsna deras naturliga försvar, så att rå magisk energi åter kan välla fram obehindrat."},{t="Ett angrepp mot Stonetalon Peak",b="För att försvaga detta grönskande strypgrepp skickar Braelyn Horde-mästare norrut till Stonetalon Peak. Där patrullerar Cenarion Botanists tillsammans med de stolta Sons and Daughters of Cenarius bland de uråldriga kaldorei-lundarna och tempelområdena. När dessa väktare fälls fyller det två syften: det monterar ner skydden som dämpar Braelyns trolldom och utdelar ett blodigt slag mot Night Elf-enklaven som hotar Hordes fotfäste i bergen."},{t="Band till Shadow Council",b="Braelyn framställer sin klagan som en fråga om magisk bekvämlighet, men hennes verkliga lojalitet finns i mörkare hörn. Hon längtar efter att återvända till Jaedenar, Shadow Councils fördärvade fäste dolt i Felwood norrut, men säger att hennes osedde mästare förbjuder henne att återvända innan arbetet i Stonetalon är klart. Horde hjälper henne av territoriella skäl och är ofta ovetande om den olycksbådande kult som drar i trådarna."}},faq={{q="Vem är Braelyn Firehand?",a="Braelyn Firehand är en blodälvisk magiker som slagit läger bland klipporna nära Sun Rock Retreat. Hon tar emot Hordes hjälp med att rensa ut Night Elf i Stonetalon, men tjänar en dold mästare med bas i Jaedenar i Felwood.",al={"braelyn firehands bakgrund","vem ger uppdraget","braelyn"}},{q="Varför vill Braelyn döda Cenarius barn?",a="Hon hävdar att den druidiska magi som utövas av kaldorei-botanikerna och Cenarius avkomma aktivt hämmar flödet av rå arkan kraft genom bergen. Om de röjs undan försvagas lundens skydd, så att magin kan flöda fritt i hennes händer.",al={"varför döda sons of cenarius","varför hata cenarion botanists","varför hatar braelyn dem"}},{q="Var finns målen?",a="Sons of Cenarius, Daughters of Cenarius och Cenarion Botanists finns samlade långt norrut vid Stonetalon Peak, där de vaktar de förfädersruiner, lundar och månbrunnar som Night Elf upprätthåller.",al={"var finns sons of cenarius","stonetalon peak fiendeplatser","var hittar man cenarion botanists"}},{q="Vad är Jaedenar, som Braelyn nämner?",a="Jaedenar är ett djupt kanjon- och grottkomplex i Felwood, kraftigt fördärvat av Burning Legion och nu Shadow Councils centrala operationsbas i Kalimdor.",al={"vad är jaedenar","braelyns mästare jaedenar","kopplingen till jaedenar"}},{q="Varför är Horde villigt att hjälpa Braelyn angripa Cenarion-försvararna?",a="Night Elf vid Stonetalon Peak står direkt på Alliansens sida och motarbetar Hordes expansion i Stonetalon Mountains. Att försvaga deras lund säkrar regionen åt Horde, oavsett Braelyns personliga motiv.",al={"varför dödar horde cenarion circle","hordes konflikt vid stonetalon peak"}},{q="Vad händer efter att du slutfört Cenarius' Legacy?",a="Braelyns nästa uppdrag riktar in sig på Ordanus, en lundväktare vid Raynewood Retreat i Ashenvale. Han finns uppe i det stora trädet där.",al={"uppdraget efter cenarius legacy","vad kommer härnäst i kedjan","ordanus uppdragskedja"}}},fx={["9bca5a54"]={q="Vem skickar Braelyn dig för att döda i Cenarius' Legacy?",a="Braelyn skickar dig mot Cenarius söner och döttrar samt de cenarioniska botaniker som är stationerade på toppen av Stonetalon Peak. Dessa väktare, dryader och nattalver tar hand om den heliga lunden och arbetar outtröttligt för att odla marken och skydda området från den kaotiska, brinnande arkana magi som Braelyn vill utnyttja.",al={"mål i cenarius' legacy","vem dödar man i cenarius' legacy","vilka är cenarius söner och döttrar"}}},fp="16,331,16.387.0,27.401.0,26.293.1,24.152.1,52.229.0,30.193.0,41.162.0,67.219.0,47.134.1"}
P.entries["quest:1088"] = {n="Ordanus",s="Braelyn Firehand vid Sunrock Retreat använder sin arkana syn för att spåra upp Keeper Ordanus, en av Cenarius äldsta söner som flydde från Stonetalon Peak. Hon anser att hans folk har vanhelgat forntida Highborne-ruiner och skickar hordens mästare över gränsen till Ashenvale för att ta hans huvud.",h="Braelyn Firehand vid Sunrock Retreat använder sin arkana syn för att spåra upp Keeper Ordanus, en av Cenarius...",kw={"ashenvale","braelyn firehand","cenarius","highborne","ordanus","raynewood retreat","stonetalon","sunrock retreat"},ang={["class:Druid"]="Hordens druider ställs inför ett dystert dilemma i detta uppdrag: de tar livet av en av Cenarius egna söner för att fullfölja en blodalvs urgamla fejd.",["class:Mage"]="Braelyn Firehand står för Highbornes obevekliga arkanaprägel och hävdar arkan överlägsenhet över Cenarions naturfilosofi.",["faction:Horde"]="Att fälla en av Cenarius äldsta söner försvagar nattalvernas auktoritet längs gränsen mellan Ashenvale och Stonetalon och hjälper Horden att utöka sitt inflytande i omstridda skogsmarker."},sec={{t="En jakt driven av gamla oförrätter",b="Braelyn Firehand kom till Stonetalon Mountains på order av sin mästare för att återta de heliga ruinerna av Azsharas forntida tempel. Hon fann att nattalverna redan hade tagit toppen i besittning och behandlade hennes Highborne-förfäders reliker som vildmark som skulle hållas i schack. Hennes främsta mål, Keeper Ordanus, flydde innan hon hann tränga in honom i ett hörn och tog sig över gränsen till Ashenvale. Med sin arkanasyn skådade Braelyn hans gömställe högt uppe i en tillflykt av trä vid Raynewood Retreat och värvade Horden för att fullfölja jakten."},{t="Skogsgudens ättling",b="Ordanus räknas till Cenarius äldsta söner och har djupa band till Kalimdors vilda magier. Nattalvernas väktare flyttade honom från Stonetalon Peak till Raynewood Retreat för att skydda honom från de arkanakrafter som tränger in bland heliga dungar. Keepern försvaras av lojala Cenarion Vindicators och tillkallade skogstreants, och står både för skogshalvgudens uråldriga auktoritet och utgör ett levande hinder för Braelyns hämnd."},{t="Highborne-hämnd",b="För Braelyn Firehand är det personligt att ta Ordanus huvud, inte bara en taktisk handling. Hon berättar öppet att hon kände honom för århundraden sedan och minns hur Cenarius avkomma såg ner på Highborne och deras mästerskap i arkana konster. Att skilja hans huvud från kroppen blir en hämnd för gamla oförrätter och röjer väg för hennes mästares större planer i Kalimdors vildmark."}},faq={{q="Vem är Keeper Ordanus?",a="Ordanus är en lundväktare och en av halvguden Cenarius äldsta söner. Han var först stationerad nära Stonetalon Peak, men flydde till Ashenvale för att undkomma Highborne-hämnden.",al={"ordanus historia","vem är ordanus","vem är keeper ordanus"}},{q="Var finns Keeper Ordanus?",a="Ordanus håller till högst upp i en väldig, ihålig trädstruktur vid Raynewood Retreat, längs vägen genom centrala Ashenvale.",al={"ordanus plats","var finns ordanus","raynewood retreat-träd"}},{q="Varför vill Braelyn Firehand döda Ordanus?",a="Braelyn ser nattalvernas närvaro i Stonetalon som en vanhelgning av forntida Highborne-tempelruiner. Hon hyser också ett långvarigt personligt hat mot Ordanus och minns honom som arrogant och nedlåtande mot hennes folk i forna tider.",al={"varför döda ordanus","braelyns oförrätt","varför vill braelyn åt ordanus"}},{q="Vem är Braelyn Firehands mästare?",a="Braelyn berättar att hon tjänar en mästare som skickade henne till toppen av Stonetalon för att återta Azsharas forntida tempelruiner, men håller mästarens exakta identitet hemlig.",al={"braelyns mästare","vem skickade braelyn"}},{q="Hur hänger konflikten ihop med hordens närvaro i Stonetalon?",a="Hordens styrkor vid Sunrock Retreat drabbar ofta samman med nattalvernas väktare och Cenarion-försvarare om territorium och resurser i Stonetalon och Ashenvale. Därför gynnar Braelyns angrepp på en Cenarion-ledare båda parter.",al={"varför hjälper horden braelyn","hordens motiv i stonetalon"}},{q="Vad händer när Ordanus har dödats?",a="När Ordanus är död belönar Braelyn mästaren och skickar dem vidare mot The Den, där de får ta itu med fler hot bland Stonetalon-topparna.",al={"vad händer efter ordanus","uppdrag efter ordanus","the den härnäst"}}},fx={ec9312c1={q="Vad ska Ordanus' Head användas till?",a="Braelyn Firehand kräver huvudet från väktaren Ordanus som ett slutgiltigt bevis på hans död och för att stilla en gammal oförrätt. Braelyn kände Ordanus för länge sedan och avskyr hans arrogans och hans tro på att hans folk stod över till och med högalverna. Att ta med hans avhuggna huvud bekräftar inte bara att nattalvernas försvar i Ashenvale har fått ett allvarligt slag, utan förödmjukar också Cenarius son precis som Braelyn tänkt sig.",al={"varför ordanus' head","syftet med ordanus' head","vad gör braelyn med ordanus' head"}}},fp="7,269,32.483.0,27.413.0,19.333.1,22.175.0,34.130.0,44.209.0,33.138.0,67.222.0,36.119.1"}
P.entries["quest:1089"] = {n="The Den",s="The Den är kulmen på Hordens infiltrationskampanj mot nattalvdruiderna som håller stånd på Stonetalon Peak. Under ledning av blodalvsagenten Braelyn Firehand tar sig mästare ner i The Talon Dens underjordiska gravkamrar för att forcera ett säkerhetssystem i flera led och lägga beslag på druidernas gömda reliker.",h="The Den är kulmen på Hordens infiltrationskampanj mot nattalvdruiderna som håller stånd på Stonetalon Peak.",kw={"barrow key","braelyn firehand","cenarius' legacy","claw key","gatekeeper's key","ordanus","sleepers' key","stonetalon peak","talon den","talon den hoard"},ang={["class:Druid"]="Hordens taurendruider ställs här inför en bitter ironi. De använder nycklar, utformade efter traditionell gravarkitektur och uppkallade efter Sleepers, Claws och Barrows, mot sina egna Cenarion-väktare.",["class:Rogue"]="Att ta sig genom gravens dunkla hallar och stjäla nycklar från gömda lyktor och fackelhållare kräver skicklig infiltration och list.",["faction:Horde"]="Räden mot The Talon Den bryter nattalvernas försvar på Stonetalon Peak, säkrar bergspassen och ger Horden mäktiga magiska reliker.",["race:NightElf"]="Skändningen av The Talon Den är ett mörkt övergrepp mot heliga gravar. Cenarion-väktarnas forntida sömn störs och deras reliker, låsta bakom skydd, plundras."},sec={{t="Underjordiska hemligheter",b="The Talon Den ligger högt uppe på Stonetalon Mountains och tjänar som underjordiskt fäste för nattalvdruider. Gravhallarna är uthuggna djupt i levande sten och ska skydda väktare i meditation och hålla heliga skatter undan nyfikna blickar. Braelyn Firehand känner till det strategiska och magiska värdet av det som finns där inne. Hon förhör en tillfångatagen druid för att få fram hemligheterna bakom försvaret."},{t="Lås i flera led",b="För att skydda sina mäktigaste reliker byggde druiderna en sinnrik mekanism i stället för att lita på en enda dörr. Vid ingången till gravkamrarna ligger Gatekeeper's Key gömd i en anspråkslös lykta. Den första nyckeln öppnar tre utspridda gömmor längre in i komplexet. Där finns Sleepers' Key, Claw Key och Barrow Key. Först när alla tre uthuggna stenar vrids i den centrala skattkammaren löses druidernas sigill upp och de forntida föremålen hamnar i Hordens händer."}},faq={{q="Vad är The Talon Den?",a="The Talon Den är ett underjordiskt gravkomplex för nattalver, uthugget i höjderna vid Stonetalon Peak. Det är både en meditationsplats för vilande druider och ett säkert förvar för deras heliga reliker.",al={"var ligger talon den","vad är the den","gravgrottan i stonetalon"}},{q="Vem beordrar infiltrationen av The Talon Den?",a="Braelyn Firehand, en Sin'dorei-agent som samarbetar med Horden i Stonetalon Mountains, planerar räden. Efter att ha fått fram viktiga upplysningar från en stackars tillfångatagen druid leder hon Hordens agenter förbi helgedomens skydd och låter dem plundra skattkammaren.",al={"vem ger uppdraget till the den","braelyn firehands syfte","vem skickade mig till the den"}},{q="Hur fungerar nycklarna i The Den?",a="En Gatekeeper's Key finns gömd i en lykta nära ingången. Den öppnar tre utspridda gömmor i gravkomplexet, där Sleepers' Key, Claw Key och Barrow Key finns. När nycklarna sätts in tillsammans i den uthuggna stenskattkammaren skingras skyddet.",al={"hur öppnar man talon den hoard","vad används gatekeeper's key till","tre nycklar i stonetalon"}},{q="Varför är druiderna på Stonetalon Peak måltavlor?",a="Braelyn Firehand vill återställa områdets magiflöde och anklagar druiderna på Stonetalon Peak och Cenarius söner för att blockera det. Hon låter döda dem och deras ledare Keeper Ordanus, som hon säger sig ha känt en gång, och skickar sedan dig för att länsa The Den på dess mäktiga föremål.",al={"varför anfalla druiderna i stonetalon","varför dödar horden ordanus","varför plundra the den"}},{q="Vad finns i The Talon Den Hoard?",a="Skattkammaren innehåller mäktiga reliker och skatter som nattalvdruiderna har samlat på sig. Föremålen förvarades säkert bakom skydd i flera led, tills Braelyn tvingade fram säkerhetssekvensen.",al={"bakgrund om bytet i talon den hoard","vad finns i skattkammaren","vad gömde druiderna"}},{q="Vad hände precis före det här uppdraget?",a="Innan de bryter sig in i The Den får Hordens äventyrare i uppdrag att undersöka nattalvernas närvaro i Cenarius' Legacy och mörda Keeper Ordanus för att splittra försvararnas ledning.",al={"uppdragskedjan för the den","vad leder fram till the den","förkunskaper för the den"}}},fx={["6ca48c55"]={q="Vad används Barrow Key till?",a="Barrow Key är den tredje delen i den sinnrika säkerhetsanordning som Stonetalon-druiderna utformade. Den är gömd i ett förråd med facklor bland djupa rötter och gravhögar, och fungerar tillsammans med nycklarna Claw och Sleepers för att häva skyddsförtrollningarna kring skattkistan.",al={"användning av barrow key","syftet med barrow key","vad öppnar barrow key"}},["48aeb852"]={q="Varför vill Braelyn Firehand att skatten plundras?",a="Braelyn Firehand vill återställa magiflödet kring Stonetalon Peak och anklagar druiderna och Cenarius söner för att blockera det. När väktaren Ordanus hade dödats och en av druiderna hade avslöjat hemligheterna bakom The Dens skyddsmagi skickar hon dig för att länsa The Talon Den på de mäktiga föremål som göms där.",al={"braelyns motiv","varför plundra the den","varför stjäla från the talon den"}},["6c65008b"]={q="Vad ska Sleepers' Key användas till?",a="Sleepers' Key är en av tre nycklar som nattalvdruiderna gömde för att skydda sina mest värdefulla reliker. Den ligger undangömd i ett gömställe djupt inne i The Talon Den. Tillsammans med de andra nycklarna måste den sättas in i det uråldriga låset av sten för att öppna The Talon Den Hoard.",al={"användning av sleepers' key","syftet med sleepers' key","vad öppnar sleepers' key"}},["1086853e"]={q="Vad ska Claw Key användas till?",a="Claw Key är en av de tre nycklar som Stonetalon-druiderna gömde runt The Den. Den förvaras i ett fack som liknar en fackla och som bara Gatekeeper's Key kan öppna. Den är den andra delen av det tredelade låset som säkrar den centrala skatten i The Talon Den.",al={"användning av claw key","syftet med claw key","vad öppnar claw key"}}},fp="7,212,20.321.0,17.349.1,22.151.0,45.230.0,36.236.0,53.288.0,35.182.0,38.185.0"}
P.entries["quest:109"] = {n="Report to Gryan Stoutmantle",s="Westfall behöver stridsvana, och Report to Gryan Stoutmantle skickar dig att svara på kallelsen. Kronan överlåter de yttre jordbruksmarkerna åt sitt öde, så lokala försvarare samlas under Gryan Stoutmantle vid Sentinel Hill.",h="Westfall behöver stridsvana, och Report to Gryan Stoutmantle skickar dig att svara på kallelsen.",kw={"defias","elwynn","gryan stoutmantle","marshal dughan","people's militia","sentinel hill","stormwind","westfall"},ang={["class:Warrior"]="Som krigare bidrar du med den erfarna disciplin som Gryan Stoutmantle värdesätter, vilket gör dig till en viktig stridskämpe för den underlägsna People's Militia.",["faction:Alliance"]="Som medlem av Alliansen ser du hur vanliga invånare bildar miliser för att överleva medan det kungliga hovet käbblar om politik i Stormwind.",["race:Human"]="Som människa i riket ser du klyftan mellan Stormwind Citys trygga marmorgator och de hårda, försummade jordbruksmarkerna bortom dem."},sec={{t="En vädjan över floden",b="Westfall kallar på skickliga stridskämpar från andra sidan floden. Rövare, gnoller och fientliga skördegolemer driver jordbruksmarkerna mot kaos. Eftersom inga kungliga bataljoner kommer till undsättning måste lokala frivilliga försvara riket."},{t="Sentinel Hill och milisen",b="Vägen leder dig till Gryan Stoutmantle i stentornet på toppen av Sentinel Hill. Han leder People's Militia, en styrka av bönder, pensionerade veteraner och legosoldater som bildades efter kungamaktens passivitet. Jordbruksmarkerna står inför ett bittert gerillakrig mot laglösheten."}},faq={{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en erfaren stridskämpe som leder People's Militia. Han organiserar Westfalls försvar från tornet på toppen av Sentinel Hill och samlar stridskämpar för att skydda bönderna från banditer och bestar.",al={"gryan stoutmantle","vem är stoutmantle","ledare för sentinel hill"}},{q="Varför behövs People's Militia?",a="People's Militia behövs eftersom Stormwinds armé har riktat sin uppmärksamhet mot huvudstaden och lämnat Westfall utan större stöd från kronan. Invånarna bildade milisen för att försvara sig mot banditer, förvildade skördeautomater och härjande Riverpaw-gnoller.",al={"varför behövs milisen","varför skickar stormwind ingen armé","varför är westfall övergivet"}},{q="Var ligger Sentinel Hill?",a="Sentinel Hill ligger nära mitten av Westfall, längs huvudvägen. Dess stadiga stenvakttorn och befästa läger är samlingsplatser för People's Militia.",al={"hitta sentinel hill","sentinel hills läge","var hittar man stoutmantle"}},{q="Vem skickar äventyrare på det här uppdraget?",a="Marshal Dughan i Goldshire, gränsvakter som Guard Thomas och Deputy Rainer samt fördrivna bönder som Farmer Furlbrow och Farmer Saldean hänvisar dugliga stridskämpar till Gryan.",al={"vem ger uppdraget","uppdragsgivare","vem ger uppdraget report to gryan"}},{q="Vad händer när du rapporterar till Gryan?",a="När du rapporterar till Stoutmantle tar han din stridsförmåga i bruk för People's Militia. Dina första uppdrag riktas mot Defias-rövarna och gnollerna som hotar Westfall.",al={"vad händer sedan","stoutmantles fortsättning","milisens uppdragskedja"}},{q="Är Westfall fortfarande formellt en del av Alliansen?",a="Ja. Westfall är fortfarande alliansområde under Stormwindrikets nominella myndighet. Kronans garnison försummar provinsen, så beväpnade invånare får försvara den.",al={"tillhör westfall alliansen","äger stormwind westfall"}}},fx={a1beb42d={q="Varför ombeds du rapportera till Gryan Stoutmantle?",a="Stormwind riktar sin militära uppmärksamhet inåt och har i stort sett övergett Westfall åt banditer och asätare. De som håller stånd där är hårt pressade. Gryan Stoutmantle och hans People's Militia behöver desperat erfarna kämpar för att försvara det som återstår av jordbruken. De som skickar dig från Elwynn inser att din stridsförmåga går till spillo när du patrullerar fridfulla fruktodlingar medan grannlandet Westfall sjunker allt djupare ner i kaos.",al={"varför rapportera till stoutmantle","varför westfall","varför dughan westfall stoutmantle"}},e97846b7={q="Varför behöver Gryan Stoutmantle oberoende äventyrare i stället för Stormwinds vakter?",a="Stormwinds monarki har vägrat skicka förstärkningar ur den reguljära armén till Westfall och lämnat provinsen åt sitt öde. De lokala vakterna och milisen kan inte hantera den enorma mängden banditer, gnoller och laglösa som tar över gårdarna. Gryan Stoutmantle måste förlita sig på dugliga resande legosoldater och äventyrare som du, som har visat verklig stridsvana och är villiga att ta till vapen för deras sak.",al={"varför jag i westfall","varför äventyrare i stället för armén","varför people's militia behöver hjälp"}}},fp="27,94,23.204.0,29.234.0,25.210.0,35.272.0,31.162.0,41.179.0,38.176.0,51.175.0"}
P.entries["quest:1090"] = {n="Gerenzo's Orders",s="Vid Venture Companys utgrävning i Stonetalon Mountains smider den avsatte trollet Piznik planer på att avslöja sin nye chef, Gerenzo. Genom att skydda Piznik från patruller medan han bryter en märklig guldgrön malm hjälper äventyrare till att avslöja de lönsamma hemligheterna bakom företagets aggressiva utgrävning.",h="Vid Venture Companys utgrävning i Stonetalon Mountains smider den avsatte trollet Piznik planer på att...",kw={"gerenzo","guldgrön malm","mystisk malm","piznik","stonetalon mountains","venture company","windshear crag","ziz fizziks"},ang={["faction:Horde"]="Venture Companys hänsynslösa, invasiva gruvdrift ödelägger Stonetalon Mountains naturlandskap. Därför är alla försök att övervaka, störa eller utnyttja verksamheten till nytta för Hordens styrkor i närheten.",["profession:Mining"]="Den märkliga guldgröna malm som Venture Companys gruvarbetare har hittat i Stonetalon liknar inte vanliga järn- eller tennådror. Den väcker nyfikenheten hos alla prospektörer som intresserar sig för sällsynta mineraler."},sec={{t="Förräderi i Crag",b="Venture Companys enorma verksamhet i Stonetalon bygger på skoningslös konkurrens, där befordringar vinns genom hänsynslöshet snarare än lojalitet. Piznik hade en gång näst högsta positionen vid utgrävningen, tills Gerenzo tog makten, avsatte arbetsledaren Ziz Fizziks och degraderade Piznik till att svinga en hacka i jorden. I stället för att ge sig av stannade Piznik kvar som informatör på Zizs uppdrag. Han bevakar varje steg Gerenzo tar och väntar på rätt tillfälle att slå tillbaka mot sin förrädiske nye arbetsledare."},{t="Den guldgröna ådern",b="Ger enzos plötsliga maktövertagande drivs av en besatthet av en mystisk guldgrön malm som löper genom klipporna i Stonetalon. Gerenzo tror att mineralet har ett extraordinärt kommersiellt värde och har beordrat gruvarbetarna att bryta enorma mängder. Piznik misstänker att Ziz Fizziks mystiske nye uppdragsgivare betalar bra för information om verksamheten. Därför riskerar han att bli upptäckt när han gräver fram ett orört prov, samtidigt som han förlitar sig på en bundsförvant som håller aggressiva grävare, skadedjur och arbetsledare borta från honom."}},faq={{q="Vem är Piznik?",a="Piznik är en trollarbetare vid verksamheten i Windshear Crag i Stonetalon Mountains. Under Ziz Fizziks var han en gång den näst viktigaste chefen vid utgrävningen, men efter att Gerenzo tagit kontrollen degraderades Piznik till enkelt gruvarbete.",al={"piznik","vem är trollgruvarbetaren","piznik stonetalon"}},{q="Varför bryter Piznik malm i hemlighet?",a="Piznik samlar i hemlighet ett prov av ett märkligt guldgrönt mineral som Gerenzo har beordrat att bryta i enorma mängder. Hans tidigare chef, Ziz Fizziks, har lovat att hans nye uppdragsgivare betalar bra för information om den värdefulla verksamhet Gerenzo bedriver.",al={"varför bryta malm","mystisk malm","guldgrön malm"}},{q="Vem är Gerenzo?",a="Gerenzo är den hänsynslöse arbetsledaren för Venture Company som tog kontroll över utgrävningen i Stonetalon genom att avskeda Ziz Fizziks. Han styrde genast om företagets resurser till att aggressivt bryta en okänd, värdefull guldgrön malm som finns i hela klippområdet.",al={"gerenzo","vem är gerenzo","gerenzo venture company"}},{q="Vem arbetar Ziz Fizziks för nu?",a="Efter att Gerenzo avskedat honom slöt Ziz Fizziks en allians med nya uppdragsgivare som vill övervaka Venture Companys verksamhet i regionen. Han betalar agenter och informatörer som Piznik för att sabotera för Gerenzo och ta reda på vad Venture Company gräver fram.",al={"zizs nye chef","vem anställde ziz","zizs arbetsgivare"}},{q="Vad anfaller Piznik medan han gräver?",a="Venture Companys arbetare anfaller under utgrävningen, däribland Windshear Tunnel Rats, Windshear Vermin, grävare, geomantiker, stenhuggare och arbetsledare.",al={"piznik överfall","vem anfaller piznik","windshears patruller"}},{q="Vad händer när provet har brutits?",a="När Piznik har lyckats bryta malmprovet ger han det till sin beskyddare, som ska överlämna det direkt till Ziz Fizziks. Han hoppas att provet ger dem det övertag de behöver för att omintetgöra Ger enzos storslagna planer.",al={"vart ska malmen föras","vad ska man göra med provet"}}},fx={["0d43f256"]={q="Varför behöver Piznik din hjälp i stället för att bryta malmen själv?",a="Piznik bevakas av Venture Company-arbetare vid utgrävningsplatsen. Han behöver en bundsförvant som håller patrullerna borta medan han tar ut ett malmprov åt Ziz Fizziks.",al={"varför behöver piznik mig","varför hjälpa piznik","varför kan piznik inte bryta malm ensam"}}},fp="16,206,30.422.0,30.447.0,14.186.0,39.225.0,15.218.0,34.233.0,34.150.0,38.172.0"}
P.entries["quest:1091"] = {n="Kaela's Update",s="Kaela's Update är en alliansrapport från Stonetalon Mountains med avlyssnad korrespondens mellan operatörer vid fronten. Gnommagikern Gaxim Rustfizzle skickar tillbaka äventyraren till Kaela Shadowspear med beslagtagna brev från Venture Company. Underrättelserna hjälper Night Elf Sentinels att följa kartellens destruktiva expansion över helig mark.",h="Kaela's Update är en alliansrapport från Stonetalon Mountains med avlyssnad korrespondens mellan operatörer...",kw={"gaxim rustfizzle","kaela shadowspear","kaela's update","brev","sentinels","stonetalon peak","venture company"},ang={["faction:Alliance"]="Överlämningen av avlyssnad korrespondens från Venture Company stärker alliansens bräckliga fäste i Stonetalon mot företagens plundring.",["race:Gnome"]="Gaxim Rustfizzle företräder stolt gnomernas arkana uppfinningsrikedom och ser till att hans Night Elf-allierade inser hur oumbärlig gnomernas magi är.",["race:NightElf"]="Varje underrättelse om Venture Company hjälper Sentinels att skydda Kalimdors sargade vildmark från industriell skövling."},sec={{t="En budbärare i bergen",b="Efter att ha hjälpt gnommagikern Gaxim Rustfizzle att avslöja Venture Companys rörelser sammanställer han återfunna brev som beskriver kartellens verksamhet. Gaxim är mån om att få erkännande och skickar spelaren direkt tillbaka till Kaela Shadowspear, Night Elf-officeren som samordnar Sentinelstyrkorna nära Windshear Crag. Han ser till att påminna budbäraren om att nämna hur hans magiska skicklighet gjorde utredningen framgångsrik."},{t="Eyes of the Sentinels",b="Sentinels i Stonetalon Mountains håller uppsikt över klipporna med växande oro. Medan Hordes styrkor kämpar om de lägre stigarna utgör Venture Companys kalhuggning och gruvdrift ett omedelbart ekologiskt och taktiskt hot. Breven som Gaxim återfann ger Kaela värdefull insyn i kartellens interna kommunikation och stärker alliansens försvarsplanering längs bergsryggarna."}},faq={{q="Vem är Kaela Shadowspear?",a="Kaela Shadowspear är en Night Elf-officer i Sentinelstyrkorna, allierad med alliansen och stationerad i ett läger nära Windshear Crag. Hon leder spanings- och försvarsinsatser mot både den framryckande Horden och de destruktiva gruvföretagen i bergen.",al={"kaela shadowspear","vem är kaela","kaela i stonetalon"}},{q="Vem är Gaxim Rustfizzle?",a="Gaxim Rustfizzle är en energisk gnommagiker med bas i Stonetalon Mountains. Han använder sina arkana färdigheter för att undersöka och störa Venture Companys verksamhet och samarbetar nära med de lokala Night Elf Sentinels.",al={"gaxim","gaxim rustfizzle","gnommagiker i stonetalon"}},{q="Vad står det i Venture Companys brev?",a="Breven innehåller intern korrespondens från Venture Company som avlyssnats under operationer mot företagets läger. De ger Kaela Shadowspear och Sentinels viktig information om kartellens lokala logistik, utgrävningar och resursutvinning.",al={"brev från venture company","vad står det i breven","brev till kaela"}},{q="Varför oroar sig Sentinels för Venture Company?",a="Venture Company kalhugger heliga skogar och ärrar jorden med vårdslösa gruvmaskiner. För Sentinels är denna skoningslösa industrialisering ett angrepp på naturen och ett direkt hot mot Stonetalon Mountains helgd.",al={"varför bry sig om gobliner","sentinels och venture company","venture company i stonetalon"}},{q="Var börjar och slutar uppdraget?",a="Uppdraget börjar hos Gaxim Rustfizzle längs bergsstigarna och avslutas hos Kaela Shadowspear i hennes läger nära Windshear Crag.",al={"uppdragsplats","lämna in kaela's update","var finns kaela"}},{q="Leder uppdraget till fler undersökningar?",a="När breven lämnas över hålls Sentinels informerade om kartellens verksamhet, så att Kaela kan planera fler militära insatser och spaningsuppdrag i hela Stonetalon Mountains.",al={"nästa uppdrag","vad händer efter kaela's update","uppföljningsuppdrag"}}},fx={["94a820b1"]={q="Varför vill Gaxim Rustfizzle att du levererar breven?",a="Gaxim vill se till att nattalvernas Sentinels får veta om Venture Companys planer, men han är lika angelägen om att ta åt sig äran för framgången. Han uppmanar dig att säga till Kaela Shadowspear att uppdraget lyckades tack vare hans magiska experiment.",al={"varför leverera breven","gaxim rustfizzles motiv","varför skicka brev till kaela"}}},fp="14,178,28.365.0,21.267.0,25.179.0,24.174.0,39.230.0,58.173.0,36.126.0,47.176.0"}
P.entries["quest:1092"] = {n="Gerenzo's Orders",s="Efter att ha slagit tillbaka utgrävningsplatsens patruller och säkrat ett prov av den märkliga malm som Gerenzo beordrade att bryta, skickar Piznik iväg äventyrare med provet till sin kontakt, Ziz Fizziks. Leveransen avslutar en riskfylld företagsintrig djupt inne i Venture Companys verksamhet vid Windshear Crag.",h="Efter att ha slagit tillbaka utgrävningsplatsens patruller och säkrat ett prov av den märkliga malm som...",kw={"gerenzo's orders","piznik","stonetalon","undermine","unidentified ore","venture company","windshear crag","ziz fizziks"},ang={["profession:Engineering"]="Gobliningenjörer i Undermine betalar bra för obearbetade, exotiska malmer som kan driva instabila nya mekanismer och prototyper.",["profession:Mining"]="Unidentified Ore, som brutits på Gerenzos order, visar att Venture Companys avskogningsverksamhet vid Windshear Crag också inriktar sig på att genomsöka bergen efter okända rikedomar under jord."},sec={{t="En biljett ut",b="Efter att hans täckmantel röjts under striden vid utgrävningsplatsen vet Piznik att hans tid bland Venture Companys besättning vid Windshear Crag är över. Företagsledningen i Undermine ser inte med blida ögon på sabotage inifrån, så den nervöse goblinen planerar sin flykt. Innan han smiter iväg för att söka en ny arbetsgivare anförtror han Unidentified Ore, som brutits på Gerenzos order, åt en utomstående. På så sätt kan det värdefulla provet levereras säkert utan att väcka misstankar mot honom."},{t="Företagshemligheter",b="Målet för malmen är Ziz Fizziks, som har upprättat en hemlig utpost vid Windshear Crags västra kant. Ziz inser mineralets strategiska värde och tänker skicka det söderut till ingenjörerna i Undermine, samtidigt som han i hemlighet lägger beslag på en värdefull del för egen vinning. Denna själviska pragmatism visar hur skoningslösa handels- och ingenjörstvister pyr under Stonetalon Mountains toppar."}},faq={{q="Varför måste Piznik fly från Windshear Crag?",a="Piznik ertappades av platsens förmän när han i hemlighet bröt ett malmprov åt Ziz, och hans täckmantel som informatör röjdes. Han vet att Venture Companys högsta ledning kommer att slå till snabbt när den får höra om händelsen, så han måste smita iväg och hitta ett nytt jobb.",al={"varför lämnar piznik","piznik på flykt","varför är piznik rädd"}},{q="Vem är Ziz Fizziks?",a="Ziz Fizziks är en goblinagent som slagit läger på Windshear Crags västra bergsrygg. Han placerade Piznik hos Venture Company för att stjäla företagshemligheter och sällsynta mineralprov.",al={"vem är ziz","ziz fizziks roll","var finns ziz"}},{q="Vad är Unidentified Ore?",a="Det är ett prov av den mystiska guldgröna malm som Chief Engineer Gerenzo beordrade att bryta i stora mängder. Ziz Fizziks tänker skicka det till forskare och ingenjörer i Undermine för att analysera dess industriella användningsområden.",al={"unidentified ore bakgrund","vad är malmen","gerenzos malm"}},{q="Var hittar man Ziz Fizziks?",a="Ziz Fizziks gömmer sig i ett litet läger vid den västra kanten, med utsikt över Windshear Crag i Stonetalon Mountains.",al={"ziz fizziks plats","hitta ziz","var lämnar man in gerenzo's orders"}},{q="Vad händer med malmen när Ziz får den?",a="Ziz planerar att skicka större delen av malmprovet till ingenjörerna i Undermine för att vinna pengar och anseende, medan han behåller en liten flisa åt sig själv utan att arbetsgivarna får veta det.",al={"vad gör ziz med malmen","behåller ziz malmen"}},{q="Är Piznik lojal mot Venture Company?",a="Piznik arbetade för Venture Company bara så länge det gynnade Ziz. Han är inte lojal mot syndikatet och fruktar aktivt vedergällning från dess ledning.",al={"pizniks fraktion","är piznik med i venture company","vem arbetar piznik för"}}},fx={["692a35ea"]={q="Varför låter Piznik dig leverera malmen i stället för att ta den själv?",a="Piznik kan inte ge sig av genast, eftersom han behöver tid för att dölja sina spår och städa upp röran innan han smiter från Venture Company. Eftersom nyheten om händelsen snart når hans överordnade anförtror han dig Unidentified Ore, så att den snabbt och säkert når Ziz Fizziks.",al={"varför skickar piznik mig","varför kan inte piznik leverera malmen","varför jag åt piznik"}}},fp="16,193,12.397.0,21.313.1,44.228.0,19.176.0,29.210.0,31.112.0,45.114.0,39.146.0"}
P.entries["quest:1093"] = {n="Super Reaper 6000",s="Super Reaper 6000 är ett uppdrag från den missnöjde goblinmekanikern Ziz Fizziks i Windshear Crag i Stonetalon Mountains. För att vinna sin nya chef Sputtervalves gunst anlitar Ziz äventyrare som ska infiltrera Venture Companys lokala skogsavverkning och stjäla ritningarna till en väldig skogsmaskin, konstruerad av hans rival, gnomen Gerenzo Wrenchwhistle.",h="Super Reaper 6000 är ett uppdrag från den missnöjde goblinmekanikern Ziz Fizziks i Windshear Crag i...",kw={"ritningar","gerenzo wrenchwhistle","sputtervalve","stonetalon mountains","super reaper 6000","venture company","windshear crag","ziz fizziks"},ang={["profession:Engineering"]="Uppdraget lyfter fram den eviga rivaliteten mellan goblinernas pragmatism, som är explosiv, snabb och rå, och gnomernas ingenjörskonst, som värdesätter överkonstruerad komplexitet och precision.",["race:Gnome"]="Ziz kan knappt tro att ett goblinsyndikat skulle lita på en gnom att bygga deras främsta maskin. Ändå blir han helt förbryllad av gnomens tekniska genialitet.",["race:NightElf"]="Super Reaper 6000 står för de dödligas totala hänsynslöshet mot naturen: den kalhugger gamla träd i Stonetalon för att mätta industrins vinsthunger."},sec={{t="Industrispionage i Windshear Crag",b="Venture Trading Company har ristat ett industriellt sår rakt in i hjärtat av Stonetalon Mountains och skövlar skoningslöst skogen i Windshear Crag. Men under smogen och de snurrande sågbladen pågår en småaktig företagsrivalitet. Ziz Fizziks, en gobliningenjör som nyligen sparkats ut ur Venture Company, har fått anställning hos Sputtervalve. Ziz vill befästa sin position och visa sitt värde, så han försöker komma över Venture Companys mest åtråvärda mekaniska tillgång: ritningarna till deras enorma, automatiserade timmermaskin, Super Reaper 6000."},{t="Goblins mot gnomisk ingenjörskonst",b="En del av Zizs bittra förbittring bottnar i stolthet. Venture Company, ett syndikat som på papperet domineras av goblins, bröt traditionen genom att sätta en gnom, Gerenzo Wrenchwhistle, att leda det lokala ingenjörsarbetet. När ritningarna slitits ur händerna på Venture Companys maskinoperatörer blir Ziz frustrerad: den gnomiska ritkonstens överdrivet invecklade och perfektionistiska filosofi är nästan helt obegriplig för en gobliningenjör som är van vid råstyrka, billiga delar och oberäknelig förbränning."}},faq={{q="Vem är Ziz Fizziks?",a="Ziz Fizziks är en gobliningenjör som bor i Stonetalon Mountains. Venture Company sparkade honom nyligen, men Sputtervalve, en inflytelserik medarbetare i området, rekryterade honom snabbt. Nu vill han hämnas på sina före detta arbetsgivare.",al={"ziz fizziks","vem ger uppdraget","ziz"}},{q="Vad är Super Reaper 6000?",a="Super Reaper 6000 är en väldig mekanisk skogsmaskin som Gerenzo Wrenchwhistle konstruerat för Venture Companys skogsavverkning i Windshear Crag.",al={"super reaper 6000","vad är super reaper","vad är det här för maskin"}},{q="Vem konstruerade Super Reaper 6000?",a="Den konstruerades av Gerenzo Wrenchwhistle, en gnommekaniker som Venture Company anställde. Det förolämpar gobliningenjörerna som tidigare ledde platsen djupt.",al={"vem gjorde super reaper","vem byggde maskinen","gerenzo wrenchwhistle"}},{q="Varför vill Sputtervalve ha ritningarna?",a="Sputtervalve vill få tillgång till den avancerade teknik för storskalig skogsavverkning som Venture Company utvecklat, och Ziz Fizziks vill gärna förse honom med den för att visa sin nya arbetsgivare vad han går för.",al={"varför stjäla ritningarna","sputtervalves ritningar"}},{q="Var finns ritningarna?",a="Ritningarna bärs av Venture Companys maskinoperatörer, som övervakar avverkningsmaskinerna i Windshear Crag.",al={"var hittar jag ritningarna","vem släpper ritningarna"}},{q="Varför har Ziz svårt att läsa ritningarna när han väl fått tag på dem?",a="Gobliners och gnomers ingenjörsfilosofier är ökända för att vara oförenliga. Ziz tycker att Gerenzo Wrenchwhistles noggranna och intrikata diagram är förvirrande och omöjliga att tyda vid en snabb blick.",al={"varför kan ziz inte läsa ritningarna","gnomritningar goblin"}}},fx={["1ca65bff"]={q="Varför vill Ziz Fizziks att det här blir gjort?",a="Ziz blev nyligen utsparkad ur Venture Company, men Sputtervalve anställde honom strax därefter. Genom att säkra ritningarna till Venture Companys enorma nya skogsmaskin hoppas Ziz visa sin lojalitet mot sin nya arbetsgivare och få Sputtervalve att äntligen ta till vara på hans tekniska geni.",al={"varför vill ziz ha ritningarna","ziz fizziks motiv","varför hjälpa sputtervalve"}},f1f026be={q="Vad används ritningarna till Super Reaper 6000 för?",a="Ritningarna beskriver hur Super Reaper 6000 är konstruerad och fungerar. Det är en enorm skogsmaskin byggd för Venture Companys avverkning. Sputtervalve vill stjäla dem för att förstå tekniken, och Ziz behöver studera dem för att uppfylla avtalet.",al={"vad används ritningarna till","syftet med ritningarna till super reaper 6000","varför stjäla ritningarna"}},c62989dc={q="Varför kan inte Ziz Fizziks stjäla ritningarna själv?",a="Ziz är persona non grata vid Venture Companys avverkningsområde. Deras chefsingenjör, en gnom vid namn Gerenzo Wrenchwhistle, har beordrat att han ska dödas så fort han syns. Om han själv gick in i lägret skulle han avrättas omedelbart, så en skicklig äventyrare är hans enda realistiska möjlighet att stjäla ritningarna.",al={"varför stjäl inte ziz dem","varför behöver ziz mig","varför kan inte ziz åka"}},["6f0e6bcb"]={q="Vem bär på ritningarna till Super Reaper?",a="Venture Companys operatörer som övervakar avverkningen bär på ritningarna. Arbetarna sköter maskinerna och leder kalhuggningen kring Cragpool Lake under Gerenzo Wrenchwhistles ledning. De håller planerna nära till hands för att sköta och underhålla skördarna.",al={"vem har ritningarna","vem ska jag slåss mot för ritningarna","vem bär planerna för super reaper"}}},fp="17,192,38.356.0,31.418.1,19.186.0,30.136.0,35.176.0,42.147.0,31.116.0,60.185.1"}
P.entries["quest:1094"] = {n="Further Instructions",s="Further Instructions är ett leveransuppdrag som knyter Stonetalon Mountains kaotiska skogsavverkning till handelsnavet Ratchet. Den missnöjde uppfinnaren Ziz Fizziks skickar en kurir med stulna ritningar och interna dokument till sin motsvarighet Sputtervalve, i hopp om att göra företagsspionage till personlig vinning.",h="Further Instructions är ett leveransuppdrag som knyter Stonetalon Mountains kaotiska skogsavverkning till...",kw={"the barrens","further instructions","ratchet","sputtervalve","stonetalon","super reaper 6000","venture company","ziz fizziks"},ang={["faction:Horde"]="Att frakta stulna ritningar från Venture Company till Ratchet bidrar till de pyrande handelskrigen, som motverkar farlig industriell expansion nära hordens territorier.",["profession:Engineering"]="Kuvertet visar goblinernas industri i sitt esse: hänsynslöst företagsspionage, patentstöld och baklängeskonstruktion av komplicerade timmerskördare."},sec={{t="Företagsspionage",b="När Ziz Fizziks blev utsparkad från Venture Companys skogsavverkning vid Windshear Crag gick han inte tomhänt därifrån. Bitter över avskedet lade Fizziks beslag på en samling känsliga dokument, interna handböcker och tekniska ritningar, där de åtråvärda ritningarna till den experimentella Super Reaper 6000 ingick. Desperat efter att hitta en köpare eller bundsförvant som kunde utnyttja informationen förseglade han hemligheterna i ett kuvert adresserat till Ratchet."},{t="Förbindelsen till Ratchet",b="Mottagaren av de stulna dokumenten är Sputtervalve, en ingenjör stationerad i den neutrala hamnen Ratchet i The Barrens. Sputtervalve hyser föga personlig tillgivenhet eller tillit till Fizziks, men rivaliteten med Venture Company gör erbjudandet omöjligt att tacka nej till. Gobliner med band till Steamwheedle letar ständigt efter sätt att minska sin hänsynslösa konkurrents inflytande, samtidigt som de gärna baklängeskonstruerar alla överlägsna mekaniska innovationer de stöter på."}},faq={{q="Vad finns i Sealed Envelope?",a="Kuvertet innehåller interna dokument från Venture Company, tekniska handböcker och ritningar till Super Reaper 6000, som Ziz Fizziks stal när han blev avsatt från deras skogsavverkning.",al={"kuvertets innehåll","vad skickar fizziks","stulna dokument"}},{q="Vem är Sputtervalve?",a="Sputtervalve är en gobliningenjör som bor i Ratchet i The Barrens. Även om han inte litar fullt ut på Ziz Fizziks är han ivrig att försvaga Venture Company och undersöka deras mekaniska framsteg.",al={"sputtervalves identitet","vem är mottagaren","ingenjör i ratchet"}},{q="Varför arbetar Ziz Fizziks mot Venture Company?",a="Fizziks blev skamlöst utsparkad ur Venture Companys led i Stonetalon. Av ren illvilja och med hämnd i sikte började han läcka deras företagshemligheter till rivaler.",al={"varför förrådde fizziks venture company","fizziks motiv"}},{q="Var hittar man Sputtervalve?",a="Sputtervalve är stationerad i den neutrala hamnstaden Ratchet, vid The Barrens östra kust.",al={"var finns sputtervalve","sputtervalves plats","hitta sputtervalve"}},{q="Litar Sputtervalve på Ziz Fizziks?",a="Nej, Sputtervalve medger öppet att han inte litar på Fizziks, men värdet av de tekniska handböckerna och ritningarna väger tyngre än hans misstänksamhet mot kuriren.",al={"litar sputtervalve på fizziks","relationen mellan fizziks och sputtervalve"}},{q="Vad är Super Reaper 6000?",a="Det är en avancerad industriell flismaskin som Venture Company utvecklat för att röja skog och bearbeta timmer snabbt, vilket gör ritningarna mycket eftertraktade.",al={"super reaper 6000","vad är maskinen","venture companys reaper"}}},fx={["98641ea6"]={q="Varför behöver Ziz Fizziks en äventyrare som levererar kuvertet?",a="Ziz Fizziks gömmer sig i Stonetalon Mountains efter att ha kastats ut ur Venture Company. Han har förlorat sin ställning och omges av fientliga före detta kollegor och farorna i Crag. Därför kan han inte själv resa säkert över Kalimdor till Ratchet. Om han anförtror de känsliga ritningarna och stulna dokumenten åt en duglig resenär når informationen Sputtervalve utan att han riskerar livet.",al={"varför jag i further instructions","varför behöver ziz mig","varför kan inte ziz leverera kuvertet"}}},fp="20,133,19.389.0,22.353.0,35.186.0,20.151.0,55.137.0,32.84.0,36.134.0,30.166.0"}
P.entries["quest:1095"] = {n="Further Instructions",s="Further Instructions markerar en upptrappning i goblinernas företagspolitik och beordrar mordet på en olydig gnomisk ingenjör som Mogul Razdunk anlitat. Sputtervalve förmedlar direktiv från högt upp i Undermine och beordrar Ziz Fizziks att röja Gerenzo Wrenchwhistle ur vägen i Stonetalon Mountains.",h="Further Instructions markerar en upptrappning i goblinernas företagspolitik och beordrar mordet på en olydig...",kw={"further instructions","gerenzo wrenchwhistle","gnomeregan","razdunk","riddlevox","sputtervalve","stonetalon","undermine","venture company","ziz fizziks"},ang={["profession:Engineering"]="Den skoningslösa rivaliteten mellan gnomisk och goblinisk ingenjörskonst får här bokstavligen en ny innebörd: från debatter om designpatent till rena företagsmord.",["race:Gnome"]="Goblinagenterna nämner att Gerenzo tidigare var senior ingenjör i Gnomeregan och att hans hemliga experiment exploderade katastrofalt i ansiktet på ingenjörerna."},sec={{t="Företagets ogillande",b="Venture Company drivs av hänsynslös vinstjakt, men när de anlitar utomstående kan det skapa hårda interna motsättningar. När Mogul Razdunk tog in gnomingenjören Gerenzo nådde ryktet Undermine och väckte irritation bland de styrande Trade Princes. Director Riddlevox instruerade Sputtervalve att ingripa och hantera situationen diskret. Sputtervalve drar slutsatsen att ordern kommer från de högsta handelsmyndigheterna och lämnar över grovjobbet till den operative som är närmast platsen: Ziz Fizziks."},{t="Dun Moroghs hemligheter",b="När Ziz Fizziks får mordordern tar han ivrigt på sig uppdraget. Gobliningenjörer hyser ett naturligt förakt för sina gnomiska rivaler, men Gerenzos förflutna gör honom till en särskilt oberäknelig person. Innan han började arbeta för Venture Company var Gerenzo chefsingenjör i Gnomeregan och deltog i ett topphemligt projekt som Undermines spioner aldrig lyckades avslöja helt. Projektet ska ha slutat i en katastrof och bokstavligen exploderat i ansiktet på ingenjörerna. Nu säljer Gerenzo sin farliga expertis till Venture Company i Kalimdor."}},faq={{q="Vem är Sputtervalve?",a="Sputtervalve är en goblinagent som arbetar under Director Riddlevox. Han agerar på direktiv från Undermine, samordnar fältoperationer och förmedlar kontrakt till agenter på plats som Ziz Fizziks.",al={"sputtervalve","vem ger uppdraget","uppdragsgivare sputtervalve"}},{q="Varför bryr sig Trade Princes om Gerenzo?",a="Trade Princes i Undermine ogillar starkt att Mogul Razdunk umgås med gnomiska ingenjörer utifrån. Att anlita uppmärksammade icke-goblins hotar goblinernas industriella dominans internt och lockar till sig oönskad granskning.",al={"varför bryr sig trade princes","undermines vrede","gerenzo och trade princes"}},{q="Vilket hemligt projekt arbetade Gerenzo med?",a="Gerenzo var chefsingenjör i Gnomeregan och arbetade med ett hemligstämplat projekt som goblinernas spioner aldrig lyckades komma åt. Vad han än byggde ska ha slutat i en katastrofal olycka och bokstavligen exploderat i ansiktet på de inblandade ingenjörerna.",al={"gerenzos hemliga projekt","explosion i gnomeregan","gerenzos förflutna"}},{q="Var befinner sig Ziz Fizziks?",a="Ziz Fizziks är stationerad i Stonetalon Mountains. Han håller uppsikt över Venture Companys lokala avverkning och gruvdrift samtidigt som han utför företagets kontrakt.",al={"ziz fizziks plats","var är ziz","var ska ordern lämnas"}},{q="Varför är Ziz Fizziks ivrig att döda Gerenzo?",a="Utöver goblinernas yrkesmässiga hat mot gnomer ser Fizziks Gerenzo som en farlig rival vars misslyckade experiment i Dun Morogh gör honom till ett hot mot alla i närheten.",al={"varför hatar ziz gerenzo","fizziks reaktion","varför döda gerenzo"}},{q="Vem är Mogul Razdunk?",a="Mogul Razdunk är verkställande direktör för Venture Company. Hans beslut att anställa Gerenzo trotsade direkt den rådande handelsetiketten i Undermine och fick Trade Princes att kräva att Gerenzo skulle röjas ur vägen.",al={"mogul razdunk","vem är razdunk","chefen för venture company"}}},fx={["36e39e8c"]={q="Varför vill Sputtervalve att det här blir gjort?",a="Sputtervalve fick direktiv direkt från Director Riddlevox, som i sin tur utsätts för påtryckningar från Undermines handelsprinsar. Mogul Razdunks beslut att anställa gnomen Gerenzo Wrenchwhistle har skandaliserat goblinernas ledarskap. För att skydda sin egen ställning och uppfylla sina överordnades krav måste Sputtervalve se till att Gerenzo elimineras. Han ser ordern till Ziz Fizziks som ett perfekt sätt att genomföra Undermines vilja och samtidigt pröva Fizziks förmåga.",al={"varför skicka ordern","sputtervalves motiv","varför döda gerenzo"}}},fp="20,174,21.408.0,21.483.1,20.152.0,44.189.0,40.190.0,29.149.0,41.159.0,21.164.0"}
P.entries["quest:1096"] = {n="Gerenzo Wrenchwhistle",s="Den här belöningen går ut på att äventyrare ska döda Gerenzo Wrenchwhistle, en förrymd gnomisk arbetsledare högt ovanför Cragpool Lake i Stonetalon Mountains. Gerenzo har förstärkt sin förruttnande kropp ordentligt med kugghjul, urverk och konstgjorda lemmar. Gobliningengören Ziz Fizziks vill ha hans mekaniska arm som obestridligt bevis på hans död, så att Ziz kan få den eftertraktade befordran från sina överordnade.",h="Den här belöningen går ut på att äventyrare ska döda Gerenzo Wrenchwhistle, en förrymd gnomisk arbetsledare...",kw={"cragpool lake","cyborg","gerenzo","mekanisk arm","sputtervalve","stonetalon","wrenchwhistle","ziz fizziks"},ang={["faction:Horde"]="Att bistå goblinkontraktörer i Stonetalon hjälper till att säkra värdefulla resurser och territorium, samtidigt som farliga ingenjörer på rymmen störs i bergsklyftorna.",["profession:Engineering"]="Den fasansfulla konstruktionen av Gerenzos mekaniska arm visar en oroande ytterlighet inom gnomisk bionisk ingenjörskonst och står i skarp kontrast till goblinernas praktiska konstruktioner.",["race:Gnome"]="Gerenzo är en excentrisk och makaber avvikelse från gnomisk uppfinningsrikedom, och har valt radikal självförstärkning för att bevara sin sviktande kropp."},sec={{t="Ett monstruöst hybridväsen",b="Gerenzo Wrenchwhistle är ökänd även bland erfarna finmekaniker för sina fasansfulla kroppsförändringar. Enligt dem som har sett honom verkar hans naturliga kropp vara på väg att ruttna bort, övertäckt av inympade kugghjul, järnplåt och surrande mekaniska proteser. Gnomens position nära det enorma vattenhjulet högt ovanför Cragpool Lake låter honom övervaka arbetet med mekanisk precision och en oroande likgiltighet inför sin dödliga kropp."},{t="Goblinernas ambitioner",b="Ziz Fizziks, en goblin som arbetar för Sputtervalve, ser Gerenzos fall som sin gyllene biljett bort från Stonetalon, en avkrok. Ziz saknar den fysiska styrkan att kämpa sig uppför klipporna eller besegra den förstärkta arbetsledaren själv, så han anlitar en äventyrare för att döda Gerenzo och hämta hans mekaniska arm. Med den trofén hoppas Ziz kunna visa sitt värde och få en förflyttning till det ansedda Tinkers' Union-verkstaden i Gadgetzan eller Undermine."},{t="Olika synsätt",b="Återhämtningen av Gerenzos mekaniska arm visar den djupa ideologiska klyftan mellan gobliners och gnomers ingenjörstraditioner. Gerenzo tog det extrema gnomiska steget att amputera sviktande kroppsvävnad för att kunna bygga in avancerade proteser, något gobliner finner obegripligt. Som Ziz påpekar skulle sann goblinuppfinningsrikedom inte kassera en biologisk lem – den skulle helt enkelt montera en explosiv tredje arm bredvid de andra två."}},faq={{q="Vem är Gerenzo Wrenchwhistle?",a="Gerenzo Wrenchwhistle är en gnomisk arbetsledare på rymmen i Stonetalon Mountains. Han är ökänd för att ersätta delar av sin förruttnande kropp och sina lemmar med mekaniska proteser och kugghjul, medan han övervakar industriarbetet högt ovanför Cragpool Lake.",al={"gerenzo","vem är gerenzo","gerenzos bakgrund"}},{q="Var hittar man Gerenzo Wrenchwhistle?",a="Gerenzo befinner sig nordost om Ziz Fizziks, högt ovanför Cragpool Lake, nära ett stort industriellt vattenhjul.",al={"gerenzos plats","hitta gerenzo","var finns gerenzo"}},{q="Varför vill Ziz Fizziks ha Gerenzo död?",a="Ziz Fizziks handlar på order från Sputtervalve. Om Gerenzo dödas visar det att Ziz är kompetent, och han hoppas att det ska ge honom en förflyttning till en större verkstad inom Tinkers' Union i Gadgetzan eller Undermine.",al={"varför döda gerenzo","ziz motiv","ziz fizziks mål"}},{q="Vilket bevis behöver Ziz?",a="Ziz behöver Gerenzos inympade mekaniska arm som konkret, obestridligt bevis på att den cyborgförvandlade arbetsledaren har tagits ur bruk för gott.",al={"vilket bevis","gerenzos bevis","uppdragsföremål"}},{q="Varför är Gerenzo delvis mekanisk?",a="Gerenzos organiska kropp verkade ruttna bort, så han ympade fast kugghjul, järnplåtar och mekaniska lemmar direkt på kroppen för att hålla sig vid liv och förstärka sig.",al={"varför är gerenzo en cyborg","gerenzo robot","gerenzos kropp"}},{q="Vem är Sputtervalve?",a="Sputtervalve är en framstående goblinförman som övervakar verksamheten och styr underhuggare som Ziz Fizziks från en annan plats i Kalimdor.",al={"sputtervalve","vem är sputtervalve"}}},fx={["94dcbf90"]={q="Varför behöver Ziz Fizziks din hjälp med Gerenzo?",a="Ziz Fizziks är ingenjör, inte frontsoldat. Gerenzo Wrenchwhistle har barrikaderat sig högt ovanför Cragpool Lake, omgiven av Venture Companys avverkning och maskiner. Ziz medger att han inte har en chans att kämpa sig igenom den fientliga avverkningsplatsen på egen hand, än mindre besegra den kraftigt förstärkta gnomen högst uppe på anläggningen. Han behöver en duglig äventyrare som kan ta sig igenom försvaret och slutföra jobbet.",al={"varför jag åt gerenzo","varför dödar inte ziz gerenzo","varför anlita en äventyrare"}}},fp="21,308,18.294.0,16.341.0,21.287.0,29.201.0,41.98.0,39.179.0,28.72.0,33.131.0,20.127.0"}
P.entries["quest:1097"] = {n="Elmore's Task",s="Smith Argus skickar dig från Goldshire till Stormwind för att hjälpa Grimand Elmore. Den dvärgska vapensmeden behöver hjälp med en leverans till sina släktingar i Khaz Modan, och Argus litar på att du klarar resan.",h="Smith Argus skickar dig från Goldshire till Stormwind för att hjälpa Grimand Elmore.",kw={"smed","leverans","dwarven district","elmore","goldshire","grimand elmore","smith argus","stormwind"},ang={["faction:Alliance"]="Som resenär i Alliansen hjälper du till att bevara stark handel och tillit mellan Stormwind och dvärgklanerna i Khaz Modan.",["profession:Blacksmithing"]="Som smed ser du två smeder förenade av sitt hantverk: Smith Argus i Goldshire och Grimand Elmore i Stormwind.",["race:Dwarf"]="Som dvärg kanske du känner igen hur människornas smeder hedrar Ironforges hantverk och hjälper till att skicka förnödenheter norrut till bergen."},sec={{t="Ett ord från smedjan",b="I Goldshire håller smeden Smith Argus utkik efter resenärer han kan anförtro arbete som går utöver att rensa ut vargar och kobolder. Grimand Elmore, en skicklig dvärgsk vapensmed i Stormwind, har bett om hjälp med en leverans till sina släktingar i Khaz Modan. Argus anser att du klarar resan och skickar dig mot stadsportarna för att svara på Elmores uppmaning."},{t="Band som förenar",b="Stormwind och Ironforge är beroende av öppen handel och god vilja för att försörja och hålla samman båda rikena. Argus säger att Elwynn Forest behöver försvarare, men att hålla löften till dvärgarna också är viktigt. I nordöstra Stormwind leder Dwarven District dig till Elmores verkstad, där en resa bortom skogen börjar."}},faq={{q="Vem startar uppdraget Elmore's Task?",a="Smith Argus, smeden i Goldshire, skickar dig för att hjälpa Grimand Elmore.",al={"var får jag elmore's task","vem ger elmore's task","uppdragsgivare för elmore's task"}},{q="Var hittar man Grimand Elmore?",a="Grimand Elmore arbetar i en vapenbutik i nordöstra Dwarven District i Stormwind.",al={"grimand elmore plats","var finns grimand elmore","hitta elmore i stormwind"}},{q="Vad är syftet med uppdraget?",a="Argus skickar dig till Elmore, som behöver en pålitlig kurir för att föra en leverans norrut till sitt hemland. Resan tar dig bortom Elwynn och genom Alliansens områden.",al={"varför skickas jag till elmore","syftet med elmore's task","vad vill elmore"}},{q="Vilket uppdrag följer efter Elmore's Task?",a="När du talar med Grimand Elmore är ärendet klart och Stormpike's Delivery blir tillgängligt. Där ska du föra hans försändelse norrut till Loch Modan.",al={"nästa uppdrag efter elmore's task","uppföljning till elmore's task","vad kommer efter elmore's task"}},{q="Varför bryr sig Smith Argus om dvärgarnas leveranser?",a="Argus säger att starka handelsband med dvärgarna i Khaz Modan hjälper till att skydda Stormwind och hålla varuflödet igång, även när Elwynn behöver försvarare.",al={"varför hjälper argus dvärgarna","smith argus band till dvärgarna"}},{q="Måste du vara smed för att ta det här uppdraget?",a="Nej. Alla resenärer i Alliansen som är redo att bege sig till Stormwind kan ta leveransen, oavsett om de kan smida eller inte.",al={"är elmore's task bara för smeder","krävs smide för elmore's task"}}},fx={["4799d1e0"]={q="Varför skickar Smith Argus dig i stället för att själv ge sig av?",a="Smith Argus är bunden till sin smedja i Goldshire, där han håller Elwynn Forests försvarare och resenärer beväpnade och deras utrustning i skick. Han skulle gärna ta emot mer hjälp på plats, men inser att du är en tålig resenär som klarar färden mellan Elwynn Forest och Stormwind. Genom att rekommendera en äventyrare kan han bistå sin dvärgiske motsvarighet utan att överge sitt viktiga smidesarbete i Goldshire.",al={"varför skicka mig på elmores uppdrag","varför levererar inte argus det","varför smith argus skickar mig"}}},fp="13,201,21.237.0,18.297.0,35.75.0,34.83.0,33.161.0,33.138.0,51.140.0,50.114.0"}
P.entries["quest:1098"] = {n="Deathstalkers in Shadowfang",s="High Executor Hadrec skickar Horde-äventyrare till Shadowfang Keep för att hitta två saknade spaningsagenter, Deathstalker Adamant och Deathstalker Vincent. Forsakens armé förlitar sig på deras insamlade underrättelser för att samordna ett anfall mot Archmage Arugal och hans worgenflockar. När fästningen intas avslöjas spionagets bistra verklighet bakom fiendens linjer.",h="High Executor Hadrec skickar Horde-äventyrare till Shadowfang Keep för att hitta två saknade spaningsagenter...",kw={"adamant","arugal","deathstalkers in shadowfang","hadrec","the sepulcher","shadowfang keep","silverpine","vincent"},ang={["class:Rogue"]="Deathstalkers försvinnande visar riskerna med spaning bakom befästa fiendelinjer.",["faction:Horde"]="High Executor Hadrec förlitar sig på Horde-hjältar för att stödja Forsakens operationer när vanliga trupper inte kan ta sig in i Arugals förbannade fästning.",["race:Undead"]="För Forsaken är det avgörande att återta Silverpine från Arugals bestar för att säkra Lordaeron. De saknade spejarna visar hur farlig kampen är."},sec={{t="In i worgenhålan",b="Silverpine Forest är fortfarande omstritt område, där Archmage Arugals vilda worgen håller den höga borgen Shadowfang Keep. För att bryta belägringen vid sina södra gränser organiserade Forsakens befäl vid The Sepulcher en underrättelseoperation. High Executor Hadrec skickade två erfarna Deathstalkers, Adamant och Vincent, för att infiltrera fästningen och kartlägga dess försvar. När flera dagar gick utan livstecken blev Hadrec desperat efter deras fältrapporter och gav dugliga Horde-hjältar i uppdrag att ta sig in i borgen, rädda agenterna och rädda uppdraget."},{t="En bitter upptäckt",b="När äventyrarna kämpat sig genom de nedre murarna upptäcker de det höga priset för infiltrationen. Deathstalker Adamant överlever fångenskapen och hjälper till att låsa upp gårdsportarna, men Vincent mötte ett brutalt slut. Hans sönderslagna kropp ligger orörlig inne i borgen, och hans personliga underrättelser har gått förlorade i de mörka salarna. Bara en liten prydnad återstår, hårt knuten i hans kalla fingrar, ett stilla vittnesbörd om en spion som gav sitt liv för Dark Ladys erövring."}},faq={{q="Varför skickades Deathstalkers till Shadowfang Keep?",a="High Executor Hadrec beordrade infiltrationen för att samla in viktiga taktiska underrättelser om Archmage Arugals styrkor och befästningar innan Forsaken-trupper sattes in i ett fullskaligt anfall mot Shadowfang Keep.",al={"varför skicka spioner till shadowfang","syftet med hadrecs uppdrag","deathstalkers mål i shadowfang"}},{q="Vilka är Deathstalker Adamant och Deathstalker Vincent?",a="De är elitsoldater från Forsaken som tillhör Deathstalkers, Undercitys gren för spionage och lönnmord. Som förtruppsspejare fick de i uppdrag att kartlägga Shadowfang Keep och hålla uppsikt över worgenförsvaret.",al={"vilka är adamant och vincent","adamant och vincent i berättelsen"}},{q="Vad hände med Deathstalker Vincent?",a="Vincent har inte rapporterat tillbaka från Shadowfang Keep. Hadrec behöver någon som tar sig in i fästningen och tar reda på vad som hänt honom.",al={"dog vincent","var är vincent","vincents öde"}},{q="Vilken roll har Deathstalker Adamant inne i borgen?",a="Adamant är en av de saknade Deathstalkers som skickades för att samla underrättelser inne i Shadowfang Keep. Hans situation blir känd under sökandet.",al={"vad gör adamant","deathstalker adamants roll"}},{q="Var börjar det här uppdraget?",a="Uppdraget ges av High Executor Hadrec, Forsakens befälhavare vid The Sepulcher i Silverpine Forest.",al={"var får man deathstalkers in shadowfang","uppdragsgivare för deathstalkers in shadowfang"}},{q="Varför vill Forsakens ledning rensa Shadowfang Keep?",a="Archmage Arugal släpper lös våldsamma worgenflockar över Silverpine Forest från sitt näste i Shadowfang Keep. De hotar ständigt Forsakens besittningar, försörjningslinjer och hela Lordaerons säkerhet.",al={"varför anfalla shadowfang","forsakens konflikt med arugal"}}},fx={["7d643f75"]={q="Varför behöver High Executor Hadrec dig för att hitta Deathstalkers?",a="High Executor Hadrec förbereder ett stort Forsaken-anfall mot Shadowfang Keep, men hela strategin hänger på viktig underrättelse. Han skickade Deathstalkers Adamant och Vincent i förväg för att spana på fästningen, men flera dagar har gått utan ett livstecken. Utan deras spaning om fiendens styrka och försvar skulle ett direkt angrepp innebära att marschera rakt in i slakten.",al={"varför vill hadrec få det här gjort","hadrecs motiv kring shadowfang","varför leta efter deathstalkers"}},cc510862={q="Varför skickar High Executor Hadrec dig i stället för sina egna trupper?",a="The Sepulchers stående styrkor är hårt pressade med att hålla linjen genom Silverpine, och att skicka en armé för att infiltrera Shadowfang utan underrättelser vore att bjuda in till katastrof. Hadrec behöver en uppfinningsrik och duglig äventyrare som kan smita förbi fästningens yttre försvar, hitta hans försvunna elitspanare och ge dem den hjälp de behöver för att rädda uppdraget.",al={"varför skicka mig till shadowfang","varför inte använda deathstalkers eller vakterna","varför jag åt hadrec"}}},fp="27,264,19.433.0,18.378.1,47.192.0,42.225.0,38.129.1,57.139.1,30.138.0,62.182.0"}
P.entries["quest:1099"] = {n="Goblins Win!",s="I Thousand Needles lönar sig en Goblin Race Ticket när goblinerna går segrande ur loppet. En prisbox går tillbaka till den som hade den vinnande biljetthalvan.",h="I Thousand Needles lönar sig en Goblin Race Ticket när goblinerna går segrande ur loppet.",kw={"goblin","goblinprisbox","tävlingsbiljett","thousand needles"},sec={{t="Goblin Ticket",b="Goblin Race Ticket är biljetthalvan som räknas när goblinerna vinner. Behåll den, så får du en goblinprisbox när resultatet är klart. Gnomernas biljett har ett eget resultat för loppets andra sida."}},faq={{q="Vad är Goblin Race Ticket?",a="Det är biljetten för goblinernas sida av loppet i Thousand Needles. Den spelar roll när goblinerna vinner.",al={"tävlingsbiljett","vad är goblin race ticket"}},{q="Vad får du när goblinerna vinner?",a="En goblinprisbox går till den som har Goblin Race Ticket när goblinerna går segrande ur loppet.",al={"goblinprisbox","goblinernas vinstpris"}},{q="Vad händer om gnomerna vinner i stället?",a="Då är gnomernas biljett den som spelar roll. Dess resultat kallas Gnomes Win!, motsvarigheten till detta.",al={"gnomerna vinner","gnome race ticket"}}},fp="12,140,17.212.0,31.102.0,37.97.0,39.109.0"}
P.entries["quest:11"] = {n="Riverpaw Gnoll Bounty",s="Riverpaw Gnoll Bounty är ett officiellt kontrakt som Deputy Rainer utfärdat vid Westbrook Garrison för att minska antalet gnoller som tränger in och hotar Elwynn Forests västra gränser. Stormwind Army erbjuder en belöning för målade armbindlar som tas från Riverpaw-flockarna som hemsöker skogarna och vattendragen.",h="Riverpaw Gnoll Bounty är ett officiellt kontrakt som Deputy Rainer utfärdat vid Westbrook Garrison för att...",kw={"belöning","deputy rainer","elwynn","gnoll","painted gnoll armband","riverpaw","stone cairn lake","westbrook garrison"},ang={["faction:Alliance"]="När du tar dig an gränsbelöningar stärker du ditt anseende hos Stormwind Army och säkrar viktiga handelsvägar genom kungarikets hjärta.",["race:Human"]="För rikets människor är jakten på Riverpaws ett konkret sätt att skydda Elwynns gränser och stödja de överbelastade kungliga vakterna."},sec={{t="Ett hot vid gränsen",b="Westbrook Garrison bevakar de viktiga gränsområdena mellan Elwynn Forest och Westfall. Men garnisonens utarmade styrkor gör att utposten har svårt att hejda en aggressiv tillströmning av Riverpaw-gnoller. Dessa vildsinta varelser har slagit läger strax söder om vakttornet och längre österut längs Stone Cairn Lakes stränder. De tränger så nära att de hotar fredliga resenärer och lokala gårdar."},{t="Ordningens pris",b="Deputy Rainer kan inte avvara reguljärt infanteri för att genomsöka skogarna och sätter därför en belöning på plundrarna. För att bekräfta dödsfallen kräver Rainer bevis på seger: målade gnollarmbindlar som tagits från de dödade bestarna. Genom att anlita kringvandrande äventyrare och rekryter för att minska flockens antal hoppas garnisonen hejda Riverpaw-flockarnas framryckning innan de översvämmar de västra gränstrakterna."}},faq={{q="Var finns Riverpaw-gnoller i Elwynn Forest?",a="Riverpaw-gnoller samlas främst i två områden i Elwynn: i de täta skogarna strax söder om Westbrook Garrison, nära flodstränderna, och längre österut runt Stone Cairn Lake.",al={"gnollernas platser","var finns gnollerna","riverpaws platser"}},{q="Varför ber garnisonen äventyrare om hjälp med gnollerna?",a="Westbrook Garrison har för få soldater och utsätts för påtryckningar längs Elwynns gränser. Eftersom det finns för få vakter för att både patrullera gränsen och genomföra offensiva räder vänder sig Deputy Rainer till självständiga hjältar för att jaga gnollerna.",al={"varför deputy rainer behöver hjälp","varför garnisonen anlitar legosoldater"}},{q="Vilka bevis kräver Deputy Rainer?",a="Deputy Rainer kräver åtta Painted Gnoll Armbands som fysiskt bevis på att de invaderande bestarna har dödats.",al={"belöningsbevis","vad ska samlas in åt rainer"}},{q="Vilka är Riverpaw-gnollerna?",a="Riverpaws är en ökänd, våldsam stam av hyenaliknande humanoider som hemsöker floddalar och gränsområden i människornas länder. De plundrar ofta bosättningar, resenärer och jordbruk för att få mat och byte.",al={"vilka är riverpaw-gnollerna","riverpaw-stammens bakgrund"}},{q="Har det här uppdraget något samband med andra hot i Elwynn?",a="Riverpaw Gnoll Bounty avslutar den korta larmkedjan vid Westbrook Garrison, men Deputy Rainer och Westbrook Garrison håller också uppsikt över andra laglösa i området, som den ökände banditen Hogger.",al={"fortsättning på uppdraget","vad händer efter riverpaw-belöningen"}},{q="Vem betalar belöningen för gnollerna?",a="Belöningen är officiellt sanktionerad och finansierad av Stormwind Army, som ger lokala garnisoner rätt att belöna och ersätta dem som hjälper till att pacificera kungarikets territorier.",al={"vem finansierar belöningen","belöningens källa"}}},fx={["139c22ee"]={q="Varför vill Deputy Rainer att gnollerna ska rensas ut?",a="Deputy Rainer ser Riverpaw-gnollerna som råbarkade inkräktare som inte har någon plats vid Elwynns gränser. Stora flockar har slagit sig ner söder om vakttornet och österut nära Stone Cairn Lake, där de hotar Westbrook Garrisons försvarslinje och nybyggarna i trakten. Rainer vill rensa ut dem och stoppa deras framryckande plåga innan utposten blir helt översvämmad.",al={"varför rensa ut gnoller","deputy rainers motiv","varför vill rainer att riverpaw dödas"}}},fp="21,221,22.282.0,18.283.0,52.155.0,60.182.0,38.94.0,28.185.0,55.172.0,37.144.0"}
P.entries["quest:110"] = {n="Insect Part Analysis",s="När Scrimshank är försvunnen börjar Senior Surveyor Fizzledowser gå igenom mätutrustningen och ordna Scrimshanks personliga tillhörigheter. Du ombeds besöka Alchemist Pestlezugg i Gadgetzan angående insektsdelarna.",h="När Scrimshank är försvunnen börjar Senior Surveyor Fizzledowser gå igenom mätutrustningen och ordna...",kw={"fizzledowser","gadgetzan","analys av insektsdelar","pestlezugg","scrimshank","tanaris"},sec={{t="En avstämning i Gadgetzan",b="Fizzledowser tänker ägna lite tid åt Scrimshanks mätutrustning och personliga tillhörigheter, och anar att insekterna kommer att kräva fler offer. Du ombeds besöka Alchemist Pestlezugg i Gadgetzan och ta reda på om insektsdelarna som mätarna skickade har bearbetats. Om de är klara vill Fizzledowser att du tar med dem tillbaka."},{t="Vad Pestlezugg upptäckte",b="Pestlezugg har resultaten, och de är oroande. Den första misstanken, att en yttre kraft styr insekterna, tros vara riktig. Det innebär en mycket mäktig, okänd kraft, och den är illvillig. Insekterna har förvandlats till rena förödare, och Pestlezugg har aldrig sett något liknande."}},faq={{q="Vem skickar dig för att rådfråga Alchemist Pestlezugg?",a="Senior Surveyor Fizzledowser, som går igenom Scrimshanks utrustning och ordnar Scrimshanks tillhörigheter.",al={"uppdragsgivare","vem startar analys av insektsdelar","fizzledowsers plats"}},{q="Var finns Alchemist Pestlezugg?",a="I Gadgetzan, där du ska fråga om insektsdelarna.",al={"var finns pestlezugg","pestlezzugs plats","pestlezzugs stad"}},{q="Vad hände direkt före det här steget?",a="Det följer på The Scrimshank Redemption.",al={"förutsättningsuppdrag","vilket uppdrag kommer först","föregående steg"}},{q="Vad skickas du för att ta reda på?",a="Om Pestlezugg har gått igenom insektsdelarna som mätarna skickade. Om de är klara ska de tas med till Fizzledowser.",al={"vad har pestlezugg"}}},fp="20,225,23.354.0,21.311.1,46.111.0,38.63.0,36.37.0,30.141.0"}
P.entries["quest:1100"] = {n="Lonebrow's Journal",s="Lonebrow's Journal är ett Alliance-uppdrag som börjar när du hittar en väderbiten bok i handen på en död dvärg vid foten av The Great Lift i Thousand Needles. Anteckningarna beskriver hans sista resa och ber upphittaren att föra boken västerut till en Night Elf-druid vid gränsen till Feralas.",h="Lonebrow's Journal är ett Alliance-uppdrag som börjar när du hittar en väderbiten bok i handen på en död...",kw={"falfindel","feralas","the great lift","henrig","dagbok","lonebrow","razorfen kraul","thalanaar","thousand needles","waywarder"},ang={["class:Druid"]="Falfindel Waywarder i Thalanaar håller uppsikt över onaturliga förändringar i det lokala ekosystemet. Därför är Lonebrows anteckningar om quilboarerna i Razorfen av direkt intresse för Cenarion Circle.",["faction:Alliance"]="Det finns få utposter mellan Theramore och Thalanaar. Genom att återfinna Lonebrows dagbok ser du till att viktig information når Alliance-allierade innan den går förlorad i kanjonen.",["race:Dwarf"]="Henrig Lonebrows död är en sorgsen påminnelse om farorna som möter dvärgiska upptäcktsresande långt från Ironforge, i Kalimdors vilda utkanter."},sec={{t="En fallen upptäcktsresande",b="Nära foten av The Great Lift, den väldiga mekaniska hissen som förbinder The Barrens med kanjonens botten i Thousand Needles, ligger Henrig Lonebrows kropp. I handen håller han en personlig dagbok som beskriver hans resor genom detta karga område. Hans lik ligger kvar i en fientlig öken, där centaurer och tauren dominerar, och är en dyster varning om hur skoningslös kanjonen kan vara mot ensamma resenärer."},{t="En döendes önskan",b="När du läser Henrigs dagbok får du veta vilken väg han tänkte ta och vad hans sista önskan var. Upptäcktsresanden ville inte låta sina fynd förfalla i kanjonen, utan hoppades att hans anteckningar skulle nå vänliga händer. Följ vägen rakt västerut genom Thousand Needles, bort från de torra ravinerna och mot Thalanaar, Night Elf-utposten som bevakar gränsen till Feralas. Där väntar druiden Falfindel Waywarder på nyheter om resenären."},{t="Krauls hemlighet",b="När Falfindel Waywarder går igenom Lonebrows anteckningar knyts upptäcktsresandens öde till ett större hot i södra Kalimdor. Henrigs iakttagelser pekar mot de törnsnåra gångarna i Razorfen Kraul, längre norrut, och avslöjar att en farlig häxa leder de quilboar som bor där."}},faq={{q="Var hittar jag Henrig Lonebrows kropp?",a="Hans kropp ligger vid foten av The Great Lift i Thousand Needles. Från den västra hissrampens nedre ände går du ungefär sju meter framåt mot en låg klipphylla. Där ligger hans lik med dagboken i handen.",al={"henrig lonebrows plats","var finns lonebrows dagbok","lonebrows kropp","hitta lonebrow"}},{q="Vem ska jag lämna dagboken till?",a="Lämna dagboken till Falfindel Waywarder, en Night Elf-druid som finns i Thalanaar. Thalanaar ligger längs huvudvägen västerut, precis vid gränsen mellan Thousand Needles och Feralas.",al={"vem får lonebrows dagbok","var lämnar man in lonebrow","lämna in lonebrow","falfindels plats"}},{q="Vem var Henrig Lonebrow?",a="Henrig Lonebrow var en dvärg på resa genom centrala Kalimdor. Han dog nära foten av The Great Lift och lämnade efter sig en väderbiten dagbok med iakttagelser om de omgivande länderna och quilboarernas farliga rörelser.",al={"vem är henrig lonebrow","lonebrows bakgrund","vem är lonebrow"}},{q="Vad leder uppdraget vidare till?",a="När du lämnar dagboken till Falfindel Waywarder låser du upp uppdraget 'The Crone of the Kraul', som leder Alliance-äventyrare in i grottan Razorfen Kraul.",al={"uppföljning till lonebrow","uppdrag efter lonebrows dagbok","lonebrows uppdragskedja"}},{q="Kan Horde-spelare plocka upp dagboken?",a="Nej. Dagboken och den efterföljande uppdragskedjan är endast för Alliance-spelare och leder direkt till Alliance-gränsposten i Thalanaar.",al={"är lonebrows dagbok bara för alliance","kan horde göra lonebrows dagbok","horde lonebrow"}},{q="Varför var Lonebrow på väg mot Thalanaar?",a="Thalanaar är den närmaste Alliance-utposten i området och fungerar som en fristad mellan Thousand Needles och Feralas vildmarker. Lonebrow tänkte dela sina iakttagelser om trakten med Night Elf-folket där.",al={"varför thalanaar","varför skicka boken till druiden","lonebrows syfte"}}},fx={["0173d93a"]={q="Varför ber journalen att föras till Thalanaar?",a="Henrig Lonebrow visste att hans resa skulle sluta i tragedi under The Great Lift. På de slitna sidorna skrev han sin sista önskan: att hans upptäckter skulle nå Falfindel Waywarder vid gränsposten i Thalanaar. När du ser till att journalen levereras bevarar du viktiga underrättelser eller upptäckter som kostade dvärgen livet, så att de inte går förlorade i Thousand Needles sand.",al={"varför leverera journalen","journalens syfte","henrig lonebrows motiv med journalen"}}},fp="18,299,17.419.0,15.417.0,20.301.1,39.222.0,32.194.0,24.240.0,29.168.1,38.140.0,42.221.0"}
P.entries["quest:1101"] = {n="The Crone of the Kraul",s="The Crone of the Kraul är ett alliansuppdrag som erbjuds av Falfindel Waywarder vid Thalanaar, på gränsen mellan Feralas och Thousand Needles. Efter att ha läst den återfunna dagboken efter den fallne dvärgen Henrig Lonebrow skickar Falfindel äventyrare för att infiltrera Razorfen Kraul och döda quilboar-häxan Charlga Razorflank.",h="The Crone of the Kraul är ett alliansuppdrag som erbjuds av Falfindel Waywarder vid Thalanaar, på gränsen...",kw={"agamaggan","charlga razorflank","häxa","falfindel waywarder","lonebrow","medaljong","razorfen kraul","thalanaar"},ang={["class:Druid"]="Druiderna håller Agamaggan högt som en vördad naturens Ancient och vill rena den mörka fläck som förvrider hans törnbeklädda arv.",["faction:Alliance"]="Det här uppdraget är alliansens främsta insats mot quilboarhotet i södra Barrens, med utgångspunkt från utposten Thalanaar.",["race:Dwarf"]="Att hämnas upptäcktsresanden Henrig Lonebrow ger dvärgarna ett personligt skäl att storma quilboarernas fäste.",["race:NightElf"]="Nattalverna ser med bestörtning på skändningen av Agamaggans viloplats och känner igen vildsvins-ancienten som en fallen allierad från War of the Ancients."},sec={{t="En vädjan vid gränsen",b="Vid den avskilda nattalvsutposten Thalanaar sörjer Falfindel Waywarder druiden Heralath och dvärgen Henrig Lonebrow. Lonebrow, en resande från Explorers' League som tillfångatogs av quilboar, flydde från Razorfen Kraul men dog på vägen och lämnade efter sig en sliten dagbok som beskriver det växande hotet där inne. Falfindel inser att det inte finns tid att skicka en budbärare till Darnassus efter militära förstärkningar och vänder sig därför till förbipasserande äventyrare för att slå direkt mot de taggiga hålornas hjärta."},{t="Anfallet mot hövdingen",b="Expeditionens mål är Charlga Razorflank, en uråldrig geomantiker och hänsynslös matriark som har enat de splittrade Razorfen-quilboar under sitt järnhårda styre. Från Kraulens djup samlar hon en taggbeväpnad armé som hotar grannländerna. Äventyrarna måste kämpa sig igenom täta taggsnår, murar och svärmar av fanatiska quilboar-krigare för att ringa in Charlga och ta hennes medaljong från hennes livlösa kropp som bevis på hennes fall."},{t="En djupare fördärvelse",b="Charlgas död dämpar det omedelbara quilboarhotet, men hennes nederlag väcker djupare oro hos nattalverna. Kraul består av levande törnen som spirade där vildsvins-ancienten Agamaggan föll under War of the Ancients. När medaljongen återlämnas påpekar Falfindel att Charlgas neutralisering låter nattalvernas lärda studera områdets fördärvelse närmare, men han anar att förrädiska krafter kan ligga bakom den plötsliga farsot som sprider sig över Agamaggans heliga kvarlevor."}},faq={{q="Vem ger uppdraget The Crone of the Kraul?",a="Uppdraget ges av Falfindel Waywarder, en nattalv stationerad vid Thalanaar. Thalanaar är en alliansutpost på det höga bergspasset mellan Feralas och Thousand Needles.",al={"uppdragsgivare crone of the kraul","var får jag crone of the kraul","falfindel waywarder uppdrag"}},{q="Vilket förhandsuppdrag måste slutföras innan det här uppdraget kan påbörjas?",a="Du måste först slutföra uppdraget Lonebrow's Journal. Det går ut på att hämta Henrig Lonebrows dagbok från hans kvarlevor nära The Great Lift i Thousand Needles och lämna den till Falfindel i Thalanaar.",al={"förhandskrav crone of the kraul","låsa upp crone of the kraul","lonebrows dagbok förhandskrav"}},{q="Vem är Charlga Razorflank?",a="Charlga Razorflank är Razorfen-quilboarernas högsta häxa och matriark. Hon är en mäktig geomantiker som har enat de stridande stammarna i Razorfen Kraul och riktar deras aggression mot grannområdena.",al={"vem är häxan","charlga bakgrund","charlga razorflank"}},{q="Var finns Charlga Razorflank?",a="Hon finns längst in i Razorfen Kraul, i Barrens sydligaste hörn nära The Great Lift. Hon väntar på ett altare djupt inne i grottan.",al={"var finns charlga","charlgas plats","var finns häxan i rfk"}},{q="Varför behöver Falfindel äventyrare i stället för att kalla på Darnassus armé?",a="Thalanaar är en avlägsen gränsutpost långt från norra Kalimdor. Charlga samlar aktivt sina styrkor, så det skulle ta för lång tid att skicka bud till Darnassus och invänta en armé för att avvärja det växande hotet.",al={"varför inte kalla på darnassus","varför anlita äventyrare"}},{q="Vilket bevis på häxans död kräver Falfindel?",a="Falfindel kräver Razorflank's Medallion, en amulett som Charlga själv bär och som utgör ett obestridligt bevis på att häxan har dödats.",al={"vilket föremål faller","föremål som bevisar döden","razorflank medaljong"}}},fx={["8858b532"]={q="Varför vill Falfindel Waywarder att Charlga Razorflank dödas?",a="Falfindel Waywarder tänker inte låta Heralaths och Henrig Lonebrows uppoffringar vara förgäves. Charlga Razorflank samlar aktivt en farlig styrka djupt inne i Razorfen Kraul och hotar alla omgivande marker. Om hon elimineras stoppas det växande quilboarhotet, och nattalverna i Thalanaar kan tryggt undersöka hur de forntida Agamaggans heliga viloplatser blev vanhelgade.",al={"varför döda charlga razorflank","falfindels motiv","varför crone of the kraul"}}},fp="22,214,20.491.0,22.400.0,19.467.1,43.167.0,63.187.0,26.219.0,38.171.0,74.210.0,54.102.0"}
P.entries["quest:1103"] = {n="Call of Water",s="Det här uppdraget ger schamaner en ny chans att klara sina andliga prövningar längs Silverpine Forests kust. Om en schamans andeblick bleknar innan hen hinner tala med den renade vattenmanifestationen, finns Tiev Mordune där för att återuppta kontakten. Med ännu en Water Sapta kan den sökande bevittna ritualen på nytt och fullborda sin kontakt.",h="Det här uppdraget ger schamaner en ny chans att klara sina andliga prövningar längs Silverpine Forests kust.",kw={"call of water","islen waterseer","minor manifestation of water","schaman","silverpine forest","tiev mordune","water sapta"},ang={["class:Shaman"]="Den här riten visar kamratskap mellan schamaner som vandrar den mödosamma vägen för att förtjäna sin Water Totem. Ingen novis ska lämnas strandsatt när transen börjar blekna.",["faction:Horde"]="Hordens schamantraditioner bygger i hög grad på ömsesidig hjälp och respekt för naturandar, även i Lordaerons hemsökta länder."},sec={{t="En hjälpande hand i dimman",b="Vägen till att bemästra vatten kräver noggrann känsla för andlig timing. Schamaner dricker en kraftfull brygd som kallas Water Sapta för att uppfatta andarna kring elementhelgedomarna. Om brygdens magi avtar innan schamanen talar med Minor Manifestation of Water, stängs hen ute från andevärlden och kan inte fullborda sin prövning. Som tur är dröjer Tiev Mordune, en schamanbroder, kvar på Silverpine Forests dimhöljda stränder för att hjälpa dem vars syner tog slut för tidigt."},{t="Ritualen på nytt",b="Tiev Mordune har redan besegrat den fördärvade vattenanden utanför kusten och väntar med resterna han samlat från ritualen. Han behöver ett bevis på att du är redo: en ny Water Sapta från Islen Waterseer i The Barrens. När han fått brygden kastar Tiev sina insamlade armskydd och vattendroppar i helgedomens offereld. Då frammanar han den rena manifestationen på nytt, så att hans schamanbroder kan tala med den och befästa sitt band till elementet."}},faq={{q="Vem är Tiev Mordune?",a="Tiev Mordune är en schaman från Horden som är stationerad vid Silverpine Forests kust. Han har slutfört striden mot det lokala fördärvade elementväsendet och stannar kvar vid stranden för att hjälpa andra noviser som förlorar sin andesyn innan de hinner fullborda sin kontakt.",al={"tiev mordune","vem är tiev","tiev silverpine"}},{q="Varför behöver jag en Water Sapta för det här uppdraget?",a="En Water Sapta låter schamanens sinne passera tröskeln till andevärlden. Tiev behöver en ny brygd från Islen Waterseer för att försäkra sig om att du kan se elementväsendet när han frammanar det igen.",al={"varför behövs sapta","water sapta tiev","var får man tag på sapta"}},{q="Vad händer om jag missade att tala med vattenanden?",a="Om andebrygden slutar verka eller Minor Manifestation of Water försvinner innan du hinner tala med den, kan du inte slutföra prövningen på egen hand. Tiev Mordune ingriper och tänder offerelden på nytt med sina egna insamlade troféer, så att du kan tala med anden.",al={"missade vattenanden","misslyckades med vattenmanifestationen","manifestationen försvann"}},{q="Var äger ritualen rum?",a="Prövningen äger rum längs västra kusten av Silverpine Forest, nära en elementhelgedom som vetter mot Great Sea.",al={"var finns vattenhelgedomen","vattenhelgedomen i silverpine"}},{q="Vem skickade schamanerna på den här pilgrimsfärden?",a="Islen Waterseer, en tauren-schaman som bor vid en fiskestuga på The Barrens östkust, vägleder noviser genom deras Call of Water-prövningar och brygger de saptor som behövs.",al={"vem gav call of water","islen waterstrider"}},{q="Vad är Minor Manifestation of Water?",a="Det är en renad elementande som frammanas vid helgedomen efter att fördärvet som förgiftade de lokala vattnen har renats bort. Att tala med den markerar att den här delen av schamanens elementprövningar är avklarad.",al={"vad är vattenanden","mindre manifestation"}}},fx={["890785ae"]={q="Varför hjälper Tiev Mordune andra schamaner här?",a="Tiev Mordune är en schamanbroder som redan har besegrat den korrumperade vattenanden och förberett sina offergåvor. Han har sett andra pilgrimer gå miste om sin chans när andevärlden försvunnit alltför snabbt. Därför valde han att skjuta upp sin egen ritual för att hjälpa alla bröder och systrar som snubblar under prövningen. Genom att erbjuda sina ritualföremål och kunskap om sapta-magi ser han till att ingen värdig schaman lämnas efter på vägen mot förståelse.",al={"varför hjälper tiev","tiev mordunes motiv","varför väntar tiev"}}},fp="13,224,26.319.0,19.379.0,20.219.0,43.160.0,54.232.0,34.104.0,36.172.0,41.216.0"}
P.entries["quest:1104"] = {n="Salt Flat Venom",s="Ute på Shimmering Flats bländande saltslätt letar gnomingenjören Fizzle Brassbolts efter ovanliga ingredienser för att trimma upp sin raketbil. Övertygad om att den intensiva salthalten i de lokala skorpionernas gift ger ett extremt hett bränsle, ber han förbipasserande äventyrare att trotsa de stickande bestarna.",h="Ute på Shimmering Flats bländande saltslätt letar gnomingenjören Fizzle Brassbolts efter ovanliga...",kw={"fizzle brassbolts","bränsle","mirage raceway","raketbil","salty scorpid venom","the shimmering flats","thousand needles"},ang={["profession:Engineering"]="Att använda organiska gifter som behandlats med katalysatorer, till exempel skipper-otomrar, visar på de kreativa och riskfyllda experiment som är vanliga inom tävlingsinriktad fordonsutveckling.",["race:Gnome"]="Fizzle står för klassisk gnomisk ambition: obevekligt skruvande, tveksam kemikaliesäkerhet, borttappade anteckningar och en ständig lust att överglänsa goblinernas mekaniker."},sec={{t="Ett flyktigt recept",b="Mirage Raceway är en ändlös kamp om teknisk överlägsenhet i hög fart mellan gnomisk precision och goblinernas djärvhet. För Fizzle Brassbolts räcker vanliga kolväten och urverksdelar helt enkelt inte för att köra om konkurrenterna. Han föreställer sig en specialblandning som brinner mycket hetare än vanliga drivmedel och driver deras raketbilar över den uttorkade saltsjön i blixtrande fart."},{t="Saltgift från saltslätten",b="Fizzles genombrott bygger på det farliga djurlivet som hör hemma på Shimmering Flats. De lokala skorpionerna har utvecklats för att överleva i ett torrt, saltbemängt ödeland, vilket har gett dem ett ovanligt salthaltigt gift. Fizzle fruktar inte dess dödliga giftighet, utan ser det som en rå kemisk laddning. När det har kokats, renats och behandlats med exotiska katalysatorer tror han att det salta giftet ger den explosiva förbränning som krävs för att lämna goblinernas depåpersonal bakom sig."}},faq={{q="Varför vill Fizzle Brassbolts ha skorpiongift?",a="Fizzle uppfinner ett nytt bränsle till raketbilar som brinner extremt hett. Han tror att den ovanligt höga salthalten i giftet från skorpionerna som hör hemma på Shimmering Flats är den avgörande kemiska beståndsdelen i hans explosiva blandning.",al={"varför skorpiongift","vad används giftet till","fizzles bränslerecept"}},{q="Var hittar man skorpionerna som behövs?",a="Skorpioner strövar över hela Shimmering Flats öppna vidder och jagar särskilt på de västra saltslätterna och i ökensanden bort från den centrala racerbanan.",al={"skorpionernas plats","var finns skorpioner","fiender med saltslättsgift"}},{q="Vad ska Fizzle göra med giftet när det har samlats in?",a="Fizzle tänker koka ner giftet, behandla det med en skipper-otomer och blanda det med en nega-katalysator för att framställa sitt högoktaniga raketbränsle, om han bara kan hitta sina borttappade anteckningar.",al={"hur blir gift till bränsle","bränsleprocessen"}},{q="Kan både Alliansen och Horden hjälpa Fizzle?",a="Ja. Mirage Raceway drivs under en neutral vapenvila mellan gnomerna och goblinerna, så äventyrare från båda fraktionerna kan hjälpa depåpersonalen utan politisk inblandning.",al={"är uppdraget neutralt","horden eller alliansen"}},{q="Varför tävlar gnomer och gobliner i Thousand Needles?",a="Shimmering Flats erbjuder en vidsträckt, helt plan och obehindrad bädd av hårt packat salt, vilket gör platsen idealisk för att testa experimentella raketbilar och dragracers i hög fart.",al={"varför racerbanan här","varför mirage raceway"}},{q="Får bilen verkligen bränslet att flyga?",a="Fizzle hävdar entusiastiskt att bilen kommer att ”flyga”, men gnomiska raketfordon på saltslätten är konstruerade för att susa fram precis ovanför marken i svindlande fart. Katastrofala luftfärder och krascher är ändå alltid möjliga.",al={"flyger bilen","resultatet av fizzles raketbil"}}},fp="15,323,17.404.0,30.473.0,46.240.0,42.163.0,50.202.0,55.183.0,54.185.0,40.223.0"}
P.entries["quest:1105"] = {n="Hardened Shells",s="Vid Mirage Raceway i The Shimmering Flats oroar sig gnomuppfinnaren Wizzle Brassbolts för att hans brors starka nya raketbränsle ska lösa upp deras racerbil inifrån. För att förhindra en katastrof på saltslätten ber Wizzle förbipasserande att samla härdade skal från traktens sköldpaddor, så att han kan tillverka en oförstörbar bränsletank.",h="Vid Mirage Raceway i The Shimmering Flats oroar sig gnomuppfinnaren Wizzle Brassbolts för att hans brors...",kw={"härdade skal","mirage raceway","raketbil","the shimmering flats","thousand needles","sköldpadda","wizzle brassbolts"},ang={["profession:Engineering"]="Att använda organiska pansarplattor för att förvara flyktiga ämnen är oortodoxt och visar hur gnomuppfinnare förlitar sig på excentriska försök och misstag när de är pressade.",["race:Gnome"]="Här möts broderlig uppfinningsrikedom och vårdslös vetenskaplig ambition. Det fångar gnomernas drivkraft att överträffa goblinernas rivaler, oavsett vilka praktiska hinder som står i vägen."},sec={{t="Flyktiga innovationer",b="I den bländande hettan i The Shimmering Flats driver rivaliteten mellan gnomernas och goblinernas ingenjörer deras mekaniska ambitioner till vårdslösa ytterligheter. Wizzle Brassbolts och hans bror tänker dominera Mirage Raceway med sin specialbyggda raketbil. Men hans brors experimentella bränsleblandning verkar vara alldeles för kraftfull. Wizzle befarar att den frätande blandningen ska smälta rakt igenom fordonets vanliga chassi och tankar och letar febrilt efter en behållare som klarar färden."},{t="Ökenhårda lösningar",b="I stället för att förlita sig på förädlade metaller som kanske löses upp av kemisk påfrestning vänder sig Wizzle till saltslättens naturliga anpassningar. Sköldpaddorna som hör hemma i Thousand Needles har skal som står emot hårda element och mekaniskt slitage ovanligt väl. Genom att samla in dessa härdade skal hoppas Wizzle kunna tillverka specialtankar som tål blandningen utan att spränga raketbilen i bitar."}},faq={{q="Varför behöver Wizzle sköldpaddsskal i stället för metall?",a="Hans bror brygger ett experimentellt raketbränsle som är så frätande att det kan lösa upp metall. Wizzle tror att traktens sköldpaddors naturliga, extremt hårda skal står emot kemiskt slitage bättre än vanliga tankar.",al={"varför sköldpaddsskal","bränsletanksskal","bränsletankens skal"}},{q="Vem är Wizzle Brassbolts?",a="Wizzle är en gnomingenjör stationerad vid Mirage Raceway i The Shimmering Flats. Tillsammans med sin bror bygger och finjusterar han deras snabba raketbil för att köra ifrån goblinernas konkurrenter.",al={"wizzle","vem är wizzle"}},{q="Var finns sköldpaddorna?",a="Sköldpaddorna strövar fritt över den vidsträckta saltslätten i The Shimmering Flats. Särskilt många solar sig nära det gamla skeppsvraket i den nordöstra delen.",al={"sköldpaddornas plats","var finns sköldpaddorna","var får man tag på härdade skal"}},{q="Är detta ett uppdrag för Alliansen eller Horden?",a="Det är helt neutralt. Mirage Raceway verkar utanför fraktionskrigen och fokuserar på ingenjörstävlingar, så både Alliansens och Hordens äventyrare kan hjälpa Wizzle.",al={"är hardened shells neutralt","alliansen eller horden"}},{q="Vad händer när skalen har levererats?",a="Wizzle börjar ivrigt tillverka förstärkta bränsletankar av dem, men inser snart att skalen är så tåliga att han troligen förstör en hel verktygslåda när han formar dem.",al={"wizzles resultat med skalen","vad gör wizzle med skalen"}},{q="Varför är ett haveri i bränsletanken så bekymmersamt på saltslätten?",a="Raketbilar kör i skräckinjagande hastigheter över saltet. Wizzle befarar att hans brors nya bränsle kan fräta sig rakt igenom bilens chassi, så han vill förstärka bränsletankarna innan det händer.",al={"raketbilens faror","varför oroa sig för bränslet"}}},fx={["201b3417"]={q="Varför vill Wizzle Brassbolts att det här görs?",a="Wizzles bror konstruerar ett extremt instabilt nytt bränsle till deras raketbil på Mirage Raceway. Wizzle beundrar sin brors genialitet, men är livrädd för att blandningen är så frätande att den smälter rakt igenom bilens nuvarande chassi under testerna. För att förhindra en katastrof på saltslätten måste Wizzle tillverka tåligare ersättningstankar innan hans bror blir klar med blandningen.",al={"wizzles motiv","varför hjälpa wizzle","varför vill wizzle ha skal"}},["5a3ddfa8"]={q="Vad är sköldpaddorna på The Shimmering Flats?",a="Sparkleshell-sköldpaddor vandrar över The Shimmering Flats solstekta vidder. Under generationer i den hårda, torra sänkan har deras skal blivit ovanligt tåliga och slitstarka. De håller sig för det mesta för sig själva bland saltskorpan, vilket gör dem till ett idealiskt, hållbart naturmaterial för gnomiska uppfinnare i desperat behov av värmetålig beklädnad som inte reagerar med andra ämnen.",al={"sköldpaddor på saltslätten","sköldpaddor på the shimmering flats","varför finns det sköldpaddor här"}}},fp="15,330,20.523.0,24.429.0,54.225.0,25.202.0,33.172.0,35.179.0,43.182.1,53.208.0"}
P.entries["quest:1106"] = {n="Martek the Exiled",s="Fizzle Brassbolts bygger en ny motor till sin bil, men kan inte tillverka kolvar som är tillräckligt hårda för att tåla påfrestningen. Han skickar dig med ett brev till den skicklige smeden Martek the Exiled, långt bort i ett läger i Badlands.",h="Fizzle Brassbolts bygger en ny motor till sin bil, men kan inte tillverka kolvar som är tillräckligt hårda...",kw={"badlands","fizzle brassbolts","gath'ilzogg","martek the exiled","mirage raceway","kolvar","thousand needles"},sec={{t="Ett brev till smeden",b="Efter Salt Flat Venom berättar Fizzle vid Mirage Raceway att den nya motorn ska göra bilen så snabb att den kan flyga. Alla hans försök har misslyckats eftersom han inte kan tillverka kolvar som är tillräckligt hårda för den stora belastningen. Han känner en person som kanske vet hur: Martek the Exiled, en skicklig smed som kan mer om metall än någon annan. Martek är långt borta i Badlands, där han slagit läger med en goblin, och du tar med Fizzles brev till honom."},{t="Vid lägret",b="Martek är inte vänlig när du hittar lägret. Martek frågar om du har kommit med en yxa tillverkad åt Gath'Ilzogg eller för att återupprätta Duchess Pamays heder, och säger att om du vill slåss kan ni lika gärna börja nu."},{t="Marteks svar",b="När Martek får veta att Fizzle har skickat dig förändras allt. Martek säger att Fizzle och hans bror är bland de få som inte vill se honom död, och går med på att hjälpa till med kolvar som klarar vilken belastning Fizzle än planerar. Den nya bilen låter, enligt Martek, som en vulkan på hjul."}},faq={{q="Varför behöver Fizzle Brassbolts hjälp av Martek?",a="Fizzles nya motor ska göra bilen snabb nog att flyga, men alla försök har misslyckats eftersom han inte kan tillverka kolvar som är tillräckligt hårda för belastningen. Martek är en skicklig smed som kan mer om metall än någon annan.",al={"varför besöka martek","fizzle brassbolts problem med kolvarna","varför martek the exiled"}},{q="Var finns Martek the Exiled?",a="I Badlands, i ett läger där en goblin också håller till.",al={"var finns martek","martek the exiled plats","hur hittar man martek"}},{q="Vad hände före den här resan?",a="Salt Flat Venom kommer före den här resan i uppdragskedjan. Indurium följer efter.",al={"förkunskapskrav för martek the exiled","vilket uppdrag kommer före martek the exiled"}}},fp="17,218,22.435.0,11.220.1,14.277.1,46.209.0,35.58.0,30.73.0"}
P.entries["quest:1107"] = {n="Encrusted Tail Fins",s="Wizzle Brassbolts vid Mirage Raceway fruktar att raketbilen är så snabb att friktionen sliter sönder den. För att skydda den behöver han stjärtfenor från Saltscale-murlocerna vid The Vile Reef, utanför Stranglethorn Vales kust.",h="Wizzle Brassbolts vid Mirage Raceway fruktar att raketbilen är så snabb att friktionen sliter sönder den.",kw={"encrusted tail fins","mirage raceway","raketbil","saltscale-murlocer","the shimmering flats","stranglethorn vale","the vile reef","wizzle brassbolts"},sec={{t="En beläggning till bilen",b="Wizzle kallar raketbilen det snabbaste som finns på The Shimmering Flats och oroar sig för att friktionen ska slita sönder den. De rörliga delarna behöver täckas med en komposit som är hård men inte spröd och som står emot saltskorrosion, annars kommer slätterna att äta upp bilen. Den viktigaste ingrediensen är stjärtfenorna från Saltscale-murlocerna, som lever vid The Vile Reef, utanför Stranglethorn Vales kust. Du ombeds att hämta tio stycken åt Wizzle."},{t="Den färdiga kompositen",b="Wizzle mal dina fenor till pulver och blandar dem med några andra ingredienser. Den färdiga kompositen bör skydda bilen från dess egen hastighet. Wizzle tillägger att skyddet bara håller så länge bilen inte kör in i något."}},faq={{q="Varför behöver Wizzle Brassbolts de belagda stjärtfenorna?",a="Raketbilen är så snabb att Wizzle fruktar att friktionen ska slita sönder den. Fenorna är en viktig ingrediens i en komposit som täcker bilens rörliga delar, gör dem hårda men inte spröda och står emot saltskorrosion.",al={"varför stjärtfenor","wizzles användning av stjärtfenor","varför murlocfenor"}},{q="Var finns Saltscale-murlocerna?",a="Vid The Vile Reef, utanför Stranglethorn Vales kust, nästan rakt västerut från Grom'gol Base Camp.",al={"var ligger vile reef","var finns saltscale-murlocerna","var hittar man belagda fenor"}},{q="Vad gjorde Wizzle innan det här?",a="Hardened Shells kommer före det i uppdragskedjan.",al={"vilket uppdrag kommer först","wizzles föregående uppdrag i kedjan","förkunskapskrav för encrusted tail fins"}},{q="Vem är Wizzle Brassbolts?",a="Wizzle Brassbolts håller till vid Mirage Raceway, oroar sig för raketbilen och är den som ber dig hämta fenorna.",al={"vem är wizzle","vem ger encrusted tail fins"}}},fp="19,221,21.428.0,22.227.1,52.206.0,41.99.0,33.45.0,25.113.0"}
P.entries["quest:1108"] = {n="Indurium",s="Martek the Exiled säger att Badlands rymmer en rikedom av metall för den som vågar hämta den. Indurium sägs tåla hetta och påfrestningar, och Martek vill ha prover för att testa om det kan fungera till Fizzles racerbil. Stonevault-troggar i Badlands bär på flagor av metallen.",h="Martek the Exiled säger att Badlands rymmer en rikedom av metall för den som vågar hämta den.",kw={"agmond's end","badlands","fizzle brassbolts","indurium","induriumflagor","martek the exiled","mirage raceway","stonevault-troggar","uldaman"},sec={{t="En metall värd att testa",b="Martek the Exiled berättar att han inte håller till i Badlands bara för att slippa sällskap. Regionen rymmer indurium, en metall som sägs tåla hetta och påfrestningar, och den kanske passar till Fizzles bil. Martek vill ha prover att testa och har smedjan varm och redo."},{t="Flagor från troggarna",b="Den egentliga malmen finns djupt inne i Uldaman, men Stonevault-troggar i Badlands bär ibland på flagor av den. Martek ber dig hämta tio. Troggarna som har sådana strövar längs den sydöstra sluttningen av en klippig kulle vid Agmond's End, strax söder om Valley of Fangs."},{t="Provet i smedjan",b="Martek tar flagorna till smedjan och höjer värmen stegvis. De håller, och Martek svär vid Orgrim att detta indurium tål enorm hetta. Testet lyckas, och Martek kallar metallen fantastiskt material."}},faq={{q="Vem skickar dig för att hämta indurium?",a="Martek the Exiled, ute i centrala Badlands, ber om proverna. Uppdragskedjan som leder till honom börjar hos Fizzle Brassbolts vid Mirage Raceway i Thousand Needles.",al={"vem ger induriumuppdraget","var hittar man indurium"}},{q="Varför behöver Martek indurium?",a="Martek tror att denna metall, som sägs tåla hetta och påfrestningar, kan fungera till Fizzles bil. Han vill ha prover att testa i smedjan.",al={"vad används indurium till","varför indurium"}},{q="Var hittar man induriumflagor?",a="Stonevault-troggar i Badlands bär ibland på dem, längs den sydöstra sluttningen av en klippig kulle vid Agmond's End, strax söder om Valley of Fangs.",al={"var finns induriumflagor","hur får man flagor","vem släpper induriumflagor"}},{q="Varifrån kommer den egentliga induriummalmen?",a="Martek säger att den egentliga malmen finns djupt inne i Uldaman.",al={"var finns induriummalm","var bryter man indurium"}},{q="Vad kommer före det här?",a="Det följer på Martek the Exiled, det första steget i kedjan, som börjar hos Fizzle Brassbolts vid Mirage Raceway.",al={"föregående induriumuppdrag","hur startar man induriumuppdraget"}},{q="Vad händer efter att flagorna har lämnats in?",a="Kedjan fortsätter med News for Fizzle.",al={"nästa uppdrag efter indurium","vad händer sedan"}}},fp="8,292,21.251.0,22.245.0,14.220.1,33.170.0,30.135.0,39.151.0,39.44.0,23.118.0,42.41.0"}
P.entries["quest:111"] = {n="Speak with Gramma",s="Tommy Joe Stonefield söker hjälp hos sin farmor Gramma Stonefield för att träffa Maybell Maclure. Familjernas bittra fejd håller de unga älskande isär, och Tommy Joe hoppas att hans farmor kan hitta ett sätt för dem att ses.",h="Tommy Joe Stonefield söker hjälp hos sin farmor Gramma Stonefield för att träffa Maybell Maclure.",kw={"elwynn forest","gramma stonefield","the maclure vineyards","maybell maclure","tala med gramma","the stonefield farm","tommy joe stonefield","unga älskande"},ang={["faction:Alliance"]="Medan Stormwind står inför oroligheter från Defias och bestangrepp kan du få medla i gräl mellan grannbönder.",["race:Human"]="Som människa i Elwynn ser du hur djupt lokala agg sitter i Stormwinds hjärtland, även mitt bland större oroligheter i riket."},sec={{t="En fejd och förbjuden kärlek",b="Tommy Joe Stonefield och Maybell Maclure håller sin romans hemlig för sina familjer, som ligger i fejd. Stonefields och Maclures har kämpat om sina gårdar i åratal, vilket gjort deras grannhem till fientlig mark. Tommy Joe vill träffa Maybell utan att framkalla våld mellan deras släkter, så han ber sin farmor om hjälp."},{t="Farmors list",b="Gramma Stonefield håller sig inomhus, men hon känner till fejden väl. Hon förstår att familjerna inte kan försonas på riktigt så länge agg består. Ändå tänker hon inte låta deras groll krossa ung kärlek. I stället för att mana till försiktighet börjar Gramma leta efter små möjligheter att föra Tommy Joe och Maybell samman."}},faq={{q="Varför vill Tommy Joe att jag ska tala med hans farmor?",a="Tommy Joe älskar Maybell Maclure, men familjernas fejd hindrar dem från att träffas. Han hoppas att hans farmor kan ordna hemliga möten utan att väcka uppståndelse.",al={"varför gramma","tommy joe och farmor","syftet med att tala med farmor"}},{q="Var hittar jag Gramma Stonefield?",a="Gramma Stonefield håller till i Stonefields stora bondgård, söder om Goldshire och öster om flodstranden där Tommy Joe gömmer sig.",al={"gramma stonefields plats","var är gramma","hitta gramma stonefield"}},{q="Vad handlar fejden mellan Stonefields och Maclures om?",a="De två närliggande bondfamiljerna hyser ett långvarigt personligt agg och en territoriell konflikt. De anklagar varandra för stöld och tävlar om skördarna, medan misstron håller båda hushållen nära våld. Deras barn måste hålla all kontakt hemlig.",al={"fejden mellan stonefield och maclure","varför slåss de","familjefejd i elwynn"}},{q="Motsätter sig Gramma Stonefield Tommy Joes förhållande?",a="Nej. Gramma vet att fejden gör en varaktig framtid svår, men hon bryr sig om de unga älskande och är villig att hitta på sätt för dem att träffas.",al={"är gramma emot maybell","stödjer gramma de älskande"}},{q="Vad händer efter att jag talat med Gramma?",a="Gramma börjar smida en plan för att i hemlighet föra Tommy Joe och Maybell samman. Hon skickar dig för att hämta det hon behöver till en osynlighetsdryck, så att de kan ta sig förbi sina vaksamma familjer.",al={"vad händer efter tala med gramma","fortsättning på gramma-uppdraget"}},{q="Vem är Maybell Maclure?",a="Maybell Maclure är dotter till rivalfamiljen och bor på andra sidan vägen från Stonefields. Hon träffar Tommy Joe Stonefield i hemlighet.",al={"vem är maybell","maybell maclure"}}},fx={ba5df8a9={q="Varför behöver Tommy Joe en främling som kan prata med hans farmor?",a="Tommy Joe gömmer sig vid flodstranden nära The Stonefield Farm för att i hemlighet träffa Maybell Maclure. Om han själv återvänder till familjens bondgård riskerar han att väcka uppmärksamhet kring sin förbjudna kärlek, särskilt när spänningarna mellan de två rivaliserande familjerna är så höga. Som förbipasserande resenär kan du närma dig Gramma Stonefield i tysthet utan att väcka resten av hushållet.",al={"varför jag, tommy joe","varför skicka spelaren till gramma","varför kan tommy inte prata med gramma"}}},fp="17,177,25.220.0,16.219.0,52.156.0,37.129.0,58.231.0,55.133.0,38.176.1,23.144.0"}
P.entries["quest:1110"] = {n="Rocket Car Parts",s="Rocket Car Parts är ett ärende åt den opportunistiske dvärgköpmannen Kravel Koalbeard på Shimmering Flats bländande saltöken. I stället för att låta vrakdelarna från våldsamma krascher i hög fart gå till spillo betalar Koalbeard vandrare för att genomsöka ökensanden och samla in havererade mekanismer som han säljer vidare direkt till de rivaliserande depåteamen av gnomer och gastar.",h="Rocket Car Parts är ett ärende åt den opportunistiske dvärgköpmannen Kravel Koalbeard på Shimmering Flats...",kw={"krascher","gnom","gast","kravel koalbeard","mirage raceway","rocket car parts","bärgning","skrot","the shimmering flats","thousand needles"},ang={["profession:Engineering"]="När du söker igenom saltöknen ser du den vårdslösa uppfinningsrikedomen hos rivaliserande gastiska och gnomiska konstruktioner. Instabila raketmotorer och improviserade chassin slutar ofta i spektakulära haverier.",["race:Dwarf"]="Många dvärgar från Ironforge söker sig till tävlingsbanan för mekanisk innovation eller utgrävning. Kravel Koalbeard visar i stället upp en utpräglat girig sida och intresserar sig enbart för pengarna som skrothanteringen ger.",["race:Gnome"]="Att samla in delarna visar hur obevekligt gnomiska ingenjörer försöker överträffa sina gastiska konkurrenter på den öppna banan, även när försöken ibland slutar i katastrof."},sec={{t="Vrakdelar på saltöknens vidder",b="Shimmering Flats är en testbana för den hårda tekniska rivaliteten mellan gastar och gnomiska ingenjörer. Experimentella raketbilar i hög fart drabbas regelbundet av katastrofala fel, så att förvridna kugghjul, cylindrar och vassa metallstycken sprids över den vidsträckta vita öknen. Medan depåteamen bara fokuserar på att bygga och trimma nästa maskin har ökensanden i tysthet blivit en skrotgård för experimentell ingenjörskonst."},{t="Koalbeards skrotverksamhet",b="I stället för att tävla direkt på banan insåg dvärgentreprenören Kravel Koalbeard att det fanns pengar att tjäna som mellanhand vid Mirage Raceway. Gnomiska och gastiska mekaniker förbrukar delar i rasande takt och är ständigt i behov av reservmekanismer att slänga på sina fordon. Koalbeard anställer resenärer för att samla ihop trettio buntar med krossat skrot. På så sätt gör han haverier till nya varor och tjänar prydligt på förarnas olycka."}},faq={{q="Vem är Kravel Koalbeard?",a="Kravel Koalbeard är en slug dvärgköpman som håller till vid Mirage Raceway på Shimmering Flats. Han driver olika affärsprojekt kring banan, främst med fokus på skrotinsamling, ströjobb och att göra gnomernas och gastarnas rivalitet till personlig vinst.",al={"kravel koalbeard","vem delar ut rocket car parts","dvärg vid tävlingsbanan"}},{q="Varför ligger det så många raketbildelar på marken?",a="Mirage Raceway är en aktiv test- och tävlingsbana där gastiska och gnomiska ingenjörer pressar experimentella raketfordon till farliga gränser. Våldsamma krascher och plötsliga explosioner inträffar regelbundet över saltöknen och slungar konstruktionsdelar, kugghjul och cylindrar över vidderna.",al={"varför finns bildelar i öknen","vrakdelar på shimmering flats","trasiga raketbilar"}},{q="Vad gör Kravel med de havererade delarna?",a="Koalbeard rensar upp det insamlade skrotet och säljer det direkt tillbaka till de gnomiska och gastiska tävlingslagen. Teamen förbrukar ständigt material och köper gärna tillbaka alla mojänger och metallbitar som de kan bulta fast på sina nästa prototyper.",al={"vad vill kravel ha delarna till","varför samla bildelar"}},{q="Var finns delarna?",a="Delarna ligger utspridda över de öppna ökenvidderna på Shimmering Flats, runt det centrala tävlingslägret. De ser ut som övergivna högar av mekaniskt skrot, förvridna kugghjul, cylindrar och tillplattade metallplåtar.",al={"var hittar man raketbildelar","delarnas platser","bildelar på shimmering flats"}},{q="Hänger det här uppdraget ihop med andra sysslor kring banan?",a="Ja. Att leta skrot på saltöknen passar bra ihop med att jaga det lokala djurlivet åt andra av banans besökare. Det kan innebära att samla gift från skorpiddjurens gaddar, ta sköldar från sköldpaddor och minska antalet lokala gamar och basilisks när du färdas över de vidsträckta saltöknarna.",al={"uppdrag vid tävlingsbanan","jaktuppdrag på shimmering flats","uppdrag med raketbildelar"}},{q="Vad händer med förarna som råkar ut för de här krascherna?",a="Raketbilstävlingar är ökända för att vara dödliga. När Koalbeard går igenom det bärgade skrotet lägger han obekymrat märke till ett avskuret öra som krossats mellan metallplåtar. Det visar den bistra verkligheten: många piloter överlever inte provkörningar i hög fart.",al={"överlever förare krascher","krossat öra","pilotdödsfall vid tävlingsbanan"}}},fx={["16d6be49"]={q="Vad används raketbilsdelarna till?",a="De är förvridet skrot — kugghjul, cylindrar och metallbitar som slungats ut vid våldsamma kollisioner på saltslätten. I stället för att låta dem rosta i saltlaken samlar Kravel Koalbeard in dem och säljer dem direkt tillbaka till de desperata gnomiska och goblina depåteamen. Båda sidorna vill desperat bygga upp sina krossade racerbilar och överlista sina rivaler, så de köper gärna tillbaka metallskrot att svetsa fast på nästa vårdslösa skapelse.",al={"vad raketbilsdelar används till","vad ska raketbilsdelar användas till","varför samla raketbilsdelar"}}},fp="16,378,24.464.0,30.467.0,24.272.0,63.294.0,43.255.0,30.225.0,56.256.0,53.243.0"}
P.entries["quest:1111"] = {n="Wharfmaster Dizzywig",s="Kravel Koalbeard, en dvärg vid Mirage Raceway, ser till att folk får det de behöver. Gnomerna där väntar på delar som kom till Ratchet för en vecka sedan, och Kravel kan inte åka dit själv. Han skickar dig till Ratchet med sin beställning av delar till Wharfmaster Dizzywig.",h="Kravel Koalbeard, en dvärg vid Mirage Raceway, ser till att folk får det de behöver.",kw={"kravel koalbeard","mirage raceway","beställning av delar","ratchet","thousand needles","wharfmaster dizzywig"},sec={{t="Ärenden åt Kravel",b="Kravel Koalbeard ser till att folk får det de behöver. Gnomerna vid Mirage Raceway väntar på en sändning delar som kom till Ratchet för en vecka sedan, och Kravel kan inte göra resan själv. Han ber dig uträtta ärendet och lovar fler jobb med goda vinstmöjligheter om du gör det."},{t="Ratchets hamn",b="Ratchet ligger i The Barrens. Goblinen Wharfmaster Dizzywig är den du ska träffa, och Kravel säger att Dizzywig förmodligen är vid hamnen. Du tar med dig Kravel's Parts Order dit."}},faq={{q="Vem skickar dig till Wharfmaster Dizzywig?",a="Kravel Koalbeard, en dvärg vid Mirage Raceway i Thousand Needles, ger dig sin beställning av delar och skickar dig till Ratchet.",al={"vem ger wharfmaster dizzywig","kravel koalbeard uppdrag"}},{q="Var hittar man Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig är en goblin, och Kravel tror att Dizzywig finns vid hamnen i Ratchet i The Barrens.",al={"dizzywigs plats","var är dizzywig","var hittar man dizzywig"}},{q="Vad är syftet med Kravels beställning?",a="Gnomerna vid Mirage Raceway väntar på delar som kom till Ratchet för en vecka sedan. Kravel kan inte åka dit själv, så han ber dig ta med hans beställning till hamnen där.",al={"vad är delarna till","varför åka till ratchet"}},{q="Vad händer efter Wharfmaster Dizzywig?",a="Nästa steg i kedjan är Parts for Kravel.",al={"nästa uppdrag efter dizzywig","what comes next"}}},fp="20,272,18.302.0,20.173.0,38.120.0,40.109.0,38.166.0,38.47.0"}
P.entries["quest:1112"] = {n="Parts for Kravel",s="Efter att ha lämnat Kravel Koalbeards reservdelsbeställning till Wharfmaster Dizzywig bär du nu Kravels paket tillbaka till honom på Mirage Raceway i The Shimmering Flats. Dizzywig skickar med ett meddelande: om Kravel vill ha fler specialbeställningar måste han betala sin skuld.",h="Efter att ha lämnat Kravel Koalbeards reservdelsbeställning till Wharfmaster Dizzywig bär du nu Kravels paket...",kw={"kravel koalbeard","mirage raceway","reservdelar till kravel","the shimmering flats","thousand needles","wharfmaster dizzywig"},sec={{t="Ett paket och en skuld",b="Wharfmaster Dizzywig ger dig ett paket till Kravel Koalbeard, som väntar på Mirage Raceway i The Shimmering Flats i Thousand Needles. Dizzywig ber dig att framföra en varning: om Kravel hoppas på fler specialbeställningar måste han först betala vad han är skyldig."},{t="Kravel tar emot dig",b="Kravel är glad att paketet har kommit och säger att det fortfarande måste nå fram till gnomerna. Men först ställer han ner lådan, tar ut en liten sak och stoppar den i fickan."}},faq={{q="Vem ger dig paketet till Kravel?",a="Wharfmaster Dizzywig i Ratchet ger dig paketet och ber dig ta det tillbaka till Kravel Koalbeard.",al={"vem startar reservdelar till kravel","varifrån kommer reservdelarna","uppdragsgivare för reservdelar till kravel"}},{q="Var väntar Kravel Koalbeard på leveransen?",a="Kravel är på Mirage Raceway i The Shimmering Flats i Thousand Needles.",al={"kravel koalbeards plats","var är kravel","var lämnar man in reservdelar till kravel"}},{q="Vilket meddelande vill Dizzywig att du framför tillsammans med reservdelarna?",a="Dizzywig ber dig säga att om Kravel vill ha fler specialbeställningar måste han betala sin skuld.",al={"vad säger dizzywig","dizzywigs meddelande till kravel","kravels skuld"}},{q="Vad hände före den här leveransen?",a="Det här följer på steget där du bar Kravels reservdelsbeställning till Wharfmaster Dizzywig i Ratchet.",al={"förutsättning för reservdelar till kravel","föregående uppdrag reservdelar till kravel"}}},fp="16,266,19.266.0,16.173.1,37.104.0,47.76.0,62.96.0,31.99.0"}
P.entries["quest:1114"] = {n="Delivery to the Gnomes",s="Kravel Koalbeard har nu det han behöver och vill att Delicate Car Parts ska levereras till Fizzle Brassbolts i The Shimmering Flats, som har väntat länge på dem. Kravel erkänner att han tog bort en liten del från Fizzles beställning och föreslår att du inte nämner det.",h="Kravel Koalbeard har nu det han behöver och vill att Delicate Car Parts ska levereras till Fizzle Brassbolts...",kw={"delicate car parts","leverans till gnomerna","fizzle brassbolts","hydrospärrhakar","kravel koalbeard","mirage raceway","repeterbultar","the shimmering flats","thousand needles"},sec={{t="En del saknas",b="Kravel Koalbeard berättar att delarna är till Fizzle Brassbolts, som har väntat länge. Kravel erkänner att han tog ut en liten del ur Fizzles beställning, men är säker på att ingen kommer att sakna den. Han kallar delen liten och värdelös, råder dig att inte ta upp saken och ber dig lita på honom."},{t="Fizzles dom",b="Fizzle Brassbolts tar glatt emot paketet: hans hydrospärrhakar och repeterbultar har äntligen kommit, och de duger gott."}},faq={{q="Vem skickar delarna till Fizzle Brassbolts?",a="Kravel Koalbeard vid Mirage Raceway. Han ber dig ta delarna vidare till Fizzle Brassbolts.",al={"vem ger leveransen till gnomerna","uppdragsgivare för leveransen till gnomerna","vem skickar delarna"}},{q="Vad tog Kravel Koalbeard ur paketet?",a="Kravel säger att han tog bort en liten del ur Fizzles beställning. Han kallar den liten och värdelös och vill helst att du inte nämner det för Fizzle.",al={"vad tog kravel","vad saknas bland delarna","kravel stal delar"}},{q="Vart ska leveransen?",a="Till Fizzle Brassbolts i The Shimmering Flats, samma saltslätt som Mirage Raceway, där Kravel Koalbeard finns.",al={"leveransen till gnomerna plats","var finns fizzle brassbolts","leverans till the shimmering flats"}},{q="Vad hände före den här leveransen?",a="Det här följer på Parts for Kravel, där du tog med Kravels paket från Ratchet tillbaka till honom.",al={"tidigare uppdrag före leveransen till gnomerna","vad leder till leveransen till gnomerna"}}},fp="22,263,16.299.0,16.130.1,41.96.0,48.150.0,28.119.0,31.94.0"}
P.entries["quest:1115"] = {n="The Rumormonger",s="Efter att ha gjort en tjänst åt gnomerna vill Kravel Koalbeard nu göra goblinerna en gentjänst. Han har hört att Nazz Steamboil, goblinernas racerpilot, en gång använde ett annat namn och undrar om det är en hemlighet värd pengar. Han skickar dig till Krazek i Booty Bay, som borde veta.",h="Efter att ha gjort en tjänst åt gnomerna vill Kravel Koalbeard nu göra goblinerna en gentjänst.",kw={"booty bay","kravel koalbeard","krazek","mirage raceway","nazz steamboil","salty sailor tavern","the shimmering flats","stranglethorn vale","thousand needles"},sec={{t="Ett namn värt att fråga om",b="Kravel Koalbeard säger att goblinerna står näst på tur att få en gentjänst. Han har hört att Nazz Steamboil, goblinernas racerpilot, en gång använde ett annat namn. Kravel undrar varför det ändrades, om det döljer en hemlighet och om Nazz vill hålla den hemlig. Den som känner till sanningen, säger Kravel, är Krazek, längst nere på Stranglethorns södra spets i Booty Bay. Användbar information kan ge en slant. Leta efter Krazek på Salty Sailor Tavern."},{t="Krazeks svar",b="Krazek känner till Nazz Steamboil som racerpilot ute på The Shimmering Flats. Krazek säger att det kanske går att ta reda på något, men varnar för att det varken blir enkelt, snabbt eller billigt."}},faq={{q="Vem skickar dig till Krazek?",a="Kravel Koalbeard, en dvärg vid Mirage Raceway ute på The Shimmering Flats, skickar dig.",al={"vem ger rumormonger","uppdragsgivare för rumormonger","vem startar uppdraget"}},{q="Varför är Kravel intresserad av Nazz Steamboil?",a="Kravel har hört att goblinernas racerpilot inte alltid använde det namnet. Han undrar om det är en hemlighet och om Nazz värderar den tillräckligt högt för att den ska kunna ge pengar.",al={"varför nazz steamboil","kravels motiv med nazz","vad är ryktet"}},{q="Var hittar man Krazek?",a="Krazek finns på Salty Sailor Tavern i Booty Bay, längst nere på Stranglethorns södra spets.",al={"krazeks plats","var finns krazek","hur hittar man krazek"}},{q="Vad kommer före det här?",a="Det följer efter Delivery to the Gnomes, tjänsten som gjordes åt gnomerna.",al={"förkunskapskrav för rumormonger","föregående uppdrag för rumormonger","vilket uppdrag kommer först"}}},fp="15,277,25.442.0,15.174.1,24.88.0,43.162.0,26.88.0,23.67.0"}
P.entries["quest:1116"] = {n="Dream Dust in the Swamp",s="Krazek i Booty Bay säger att det är en stor tjänst att få veta mer om Nazz. Medan Krazek kontaktar sina källor ska du hämta tio korn Dream Dust från drakungar i Swamp of Sorrows till Krazeks snusdosa. Kom tillbaka med dem, så ger Krazek dig informationen du söker.",h="Krazek i Booty Bay säger att det är en stor tjänst att få veta mer om Nazz.",kw={"booty bay","dream dust","kravel koalbeard","krazek","mirage raceway","nazz","swamp of sorrows","drakungar"},sec={{t="En tjänst för en tjänst",b="Krazek säger att det är en stor tjänst att få veta mer om Nazz, och att du redan har färdats långt från The Shimmering Flats för den. Medan Krazek kontaktar sina källor ber han dig hämta något. Valet faller på tio korn Dream Dust från drakungar i Swamp of Sorrows, som Krazek gärna vill ha till en snusdosa. När du återvänder med dem får du informationen."},{t="Där dammet finns",b="De gröna drakarna i Swamp of Sorrows bär på Dream Dust. Både unga drakungar och drömmande drakungar har det, och båda lever i träskets sydvästra hörn."}},faq={{q="Vem ber om Dream Dust?",a="Krazek i Booty Bay ber om det i utbyte mot informationen om Nazz.",al={"vem ger uppdraget om dream dust","vem skickar mig till swamp of sorrows","uppdragsgivare för dream dust"}},{q="Varför vill Krazek ha Dream Dust?",a="Krazek säger att han vill ha dammet till en snusdosa och ber dig hämta det medan han kontaktar sina källor om Nazz.",al={"vad används dream dust till","varför krazek vill ha damm","dream dust till snus"}},{q="Var finns Dream Dust?",a="Det hämtas från drakungar i Swamp of Sorrows, till exempel unga drakungar och drömmande drakungar, i träskets sydvästra hörn.",al={"var hittar man dream dust","var finns dream dust i swamp of sorrows","dream dust plats"}},{q="Hur hänger detta ihop med Kravel Koalbeard?",a="Kravel Koalbeard från Mirage Raceway skickade dig till Krazek för att fråga om goblinföraren Nazz Steamboil, och du kom från The Shimmering Flats för att få svaret.",al={"varför är jag i booty bay","hur hänger det ihop med kravel","kopplingen till the shimmering flats"}},{q="Vad händer härnäst?",a="Nästa steg är Rumors for Kravel.",al={"vad händer efter dream dust in the swamp","nästa uppdrag efter dream dust","rumors for kravel härnäst"}}},fp="23,287,19.398.0,23.162.0,33.76.0,32.102.0,30.132.0,47.164.0,16.35.0"}
P.entries["quest:1117"] = {n="Rumors for Kravel",s="Krazek har hittat det du letade efter. Efter att ha bett om tjänster, dragit många slutsatser och gett bort en sällsynt flaska alviskt vin skrev Krazek ett brev om Nazz Steamboil. Det är för farligt för Krazek att använda, så du tar det till Kravel Koalbeard ute på The Shimmering Flats. Du ombeds att inte berätta var det kommer ifrån.",h="Krazek har hittat det du letade efter.",kw={"booty bay","goblinrykten","kravel koalbeard","krazek","mirage raceway","nazz steamboil","rumors for kravel","the shimmering flats","thousand needles"},sec={{t="Ett brev från Krazek",b="Krazek berättar vad efterforskningen kostade: några tjänster utnyttjades, en sällsynt flaska alviskt vin gavs bort och många slutsatser drogs. Resultatet är ett brev med några mycket intressanta uppgifter om Nazz Steamboil. Krazek anser att det är för farligt att använda och låter dig göra vad du vill med det, så länge ingen får veta var det kommer ifrån. Det ska tillbaka till Kravel Koalbeard ute på The Shimmering Flats."},{t="Kravels dom",b="Kravel tycker att brevet är mycket intressant. Han funderar på om han kanske borde buga för goblinpiloten nästa gång de ses och räknar med att Nazz betalar en mindre förmögenhet för att hålla hemligheten begravd."}},faq={{q="Var börjar det här?",a="Krazek ger dig brevet i Booty Bay när du har hämtat Dream Dust.",al={"vem ger rykten till kravel","start på rumors for kravel","var hämtar jag ryktena"}},{q="Vem ska brevet lämnas till?",a="Till Kravel Koalbeard vid Mirage Raceway ute på The Shimmering Flats i Thousand Needles.",al={"var lämnar jag in rumors for kravel","vem får goblinryktena","var finns kravel koalbeard"}},{q="Vem handlar Krazeks upptäckter om?",a="Nazz Steamboil, goblinernas racerförare. Krazek skrev ner några mycket intressanta uppgifter om Nazz i brevet.",al={"vem är nazz steamboil","vad handlar ryktet om","vem handlar ryktena om"}},{q="Hur fick Krazek fram informationen?",a="Krazek utnyttjade några tjänster, drog många slutsatser och gav bort en sällsynt flaska alviskt vin.",al={"hur fick krazek informationen","krazeks tjänster"}},{q="Vad händer härnäst?",a="Nästa steg i kedjan är The Next Step.",al={"nästa uppdrag efter rumors for kravel","fortsättning på rumors for kravel"}}},fp="17,326,20.418.0,16.192.1,22.73.0,37.91.0,40.110.0,39.97.0,16.48.0"}
P.entries["quest:1118"] = {n="Back to Booty Bay",s="Kravel Koalbeard litar på att du får jobbet gjort och håller tyst om det. Han har en ny plan, riskabel men med löfte om en rejäl hacka åt er båda. Du tar hans brev till Crank Fizzlebub i Booty Bay. Det här följer på Rumors for Kravel.",h="Kravel Koalbeard litar på att du får jobbet gjort och håller tyst om det.",kw={"booty bay","crank fizzlebub","kravel koalbeard","kravel's scheme","mirage raceway","salty sailor tavern","the shimmering flats","thousand needles"},sec={{t="Ett brev till Booty Bay",b="Kravel Koalbeard, dvärgen vid Mirage Raceway, säger att han litar på att du både slutför ett jobb och håller tyst om det. Hans nya plan är riskabel, men om den lyckas kan ni båda tjäna en rejäl hacka. Han ber om ursäkt för att han skickar dig tillbaka till Booty Bay, dit hans förra jobb tog dig, och ber dig leta upp Crank Fizzlebub där och överlämna ett brev. Om Crank behöver hjälp vill Kravel att du gör ditt bästa, och säger att mödan kommer att löna sig."},{t="Crank läser planen",b="Crank Fizzlebub läser brevet och förstår att Kravel har en stor plan på gång. Crank gillar Kravels ondskefulla sinne. Planen kommer att kräva något kraftfullt som förvirrar folk, och Crank undrar om blandningen som Zanzil ger sina zombier kan komma till användning."}},faq={{q="Var börjar och slutar resan?",a="Den börjar hos Kravel Koalbeard vid Mirage Raceway i Thousand Needles. Du tar hans brev till Crank Fizzlebub, som finns på Salty Sailor Tavern i Booty Bay, i Stranglethorn Vale.",al={"vart ska jag gå","vem ger uppdraget tillbaka till booty bay","var finns crank fizzlebub"}},{q="Vad hände före det här?",a="Det följer på Rumors for Kravel, det tidigare steget som tog dig till Booty Bay.",al={"förkunskaper","föregående uppdrag","vilket uppdrag kommer först"}},{q="Vad är Kravel's Scheme?",a="Det är brevet du tar till Crank Fizzlebub. Kravel kallar sin plan riskabel och säger att ni två kan tjäna en rejäl hacka om den lyckas.",al={"vad är kravel's scheme","kravels planbrev"}},{q="Vad ska du göra om Crank Fizzlebub behöver hjälp?",a="Kravel ber dig göra ditt bästa för att hjälpa honom och säger att mödan kommer att löna sig.",al={"hjälpa crank","behöver crank hjälp"}},{q="Vad kommer efter det här?",a="Kedjan fortsätter med Zanzil's Mixture and a Fool's Stout.",al={"nästa uppdrag","vad följer efter tillbaka till booty bay"}}},fp="17,233,22.462.0,22.254.1,38.193.0,22.74.0,24.142.0,49.80.0,22.61.0"}
P.entries["quest:1119"] = {n="Zanzil's Mixture and a Fool's Stout",s="Crank Fizzlebub har upptäckt att Zanzil's Mixture, blandad i stout, blir en stark dryck som kallas Fool's Stout. Han tror att den är precis vad Kravel behöver. Du tar den till Kravel Koalbeard vid Mirage Raceway på The Shimmering Flats, och det snabbt, eftersom den inte håller sig färsk.",h="Crank Fizzlebub har upptäckt att Zanzil's Mixture, blandad i stout, blir en stark dryck som kallas Fool's...",kw={"booty bay","fizzlebub","kravel","blandning","racerbana","the shimmering flats","stout","zanzil"},sec={{t="En sup åt Kravel",b="Crank Fizzlebub har upptäckt att Zanzil's Mixture, blandad i stout, ger en stark dryck: Fool's Stout. Crank tror att den är precis vad Kravel behöver och vill höra hur den fungerar. Du tar den tillbaka till Kravel Koalbeard vid Mirage Raceway på The Shimmering Flats."},{t="Låt den inte stå",b="Crank varnar dig för att behålla stouten länge. Blandningen har en märklig effekt på stoutens jäst och får den att arbeta för fullt, så drycken håller sig inte färsk för evigt."}},faq={{q="Vem skickar dig med leveransen?",a="Crank Fizzlebub i Booty Bay ger dig Fool's Stout att bära med dig.",al={"vem inleder zanzil's mixture och fool's stout","uppdragsgivare"}},{q="Vem tar emot Fool's Stout?",a="Kravel Koalbeard vid Mirage Raceway på The Shimmering Flats i Thousand Needles.",al={"vem får stouten","var lämnar jag in den","kravels plats"}},{q="Varför måste drycken levereras snabbt?",a="Blandningen får jästen att arbeta hårt, och stout som står för länge blir dålig.",al={"blir fool's stout dålig","varför är det bråttom","jäsningseffekt"}},{q="Vad hände före detta?",a="Det följer på Back to Booty Bay och Zanzil's Secret.",al={"förutsättningsuppdrag","föregående steg"}},{q="Vad händer när stouten har levererats?",a="Kedjan fortsätter med Fool's Stout, Get the Gnomes Drunk och Get the Goblins Drunk.",al={"nästa uppdrag","vad händer sedan"}}},fp="35,279,21.273.0,17.178.0,31.65.0,30.84.0,48.77.0,22.49.0,38.86.0"}
P.entries["quest:112"] = {n="Collecting Kelp",s="I Goldshire söker Maybell Maclure ett sätt att besöka Tommy Joe Stonefield utan att bli sedd. William Pestle behöver sällsynt crystal kelp för att brygga en Invisibility Liquor åt henne.",h="I Goldshire söker Maybell Maclure ett sätt att besöka Tommy Joe Stonefield utan att bli sedd.",kw={"samla kelp","crystal kelp","crystal lake","goldshire","invisibility liquor","maybell maclure","murloc","tommy joe stonefield","william pestle"},ang={["faction:Alliance"]="För Alliansen bidrar röjningen av murloclägren kring Crystal Lake åt Pestle till att dämpa hotet nära Goldshires östra väg.",["profession:Herbalism"]="För dig som samlare är crystal kelp ett märkligt fynd: en havsväxt som tas ur sötvattensmurlocs påsar, inte från mark eller havsbotten."},sec={{t="Ett botemedel mot förbjuden kärlek",b="Fejden mellan familjerna Stonefield och Maclure hindrar Maybell Maclure och Tommy Joe Stonefield från att träffas öppet. Maybell vill träffa sin älskade utan att provocera fram en väpnad sammandrabbning mellan deras släkter, så hon söker ett sätt att ta sig osedd genom dalen. William Pestle, örtkännare och apotekare på Lion's Pride Inn i Goldshire, planerar att brygga en Invisibility Liquor. De sällsynta ingredienser han behöver finns inte i värdshusets skåp."},{t="Asätarna vid Crystal Lake",b="Crystal kelp är katalysatorn William Pestle behöver till sin brygd. Bladen växer vanligtvis långt ute i saltvattenhaven, men stamlevande murlocs har burit förråd inåt land till sina primitiva läger längs Crystal Lake, strax öster om Goldshire. Deras märkliga instinkter har fått dem att släpa de marina växterna till sötvattensstranden. Du måste få tag på tillräckligt många blad från murlocs innan du återvänder till Goldshire med dem."}},faq={{q="Varför behöver William Pestle crystal kelp?",a="William Pestle behöver crystal kelp för att brygga en Invisibility Liquor åt Maybell Maclure. Drycken ska hjälpa henne att lämna familjens vingård osedd och besöka Tommy Joe Stonefield.",al={"varför crystal kelp","vad används kelp till","ingredienser åt william pestle"}},{q="Varför finns havstång vid sötvattensjön Crystal Lake?",a="Crystal kelp växer i havet, men stamlevande murlocs kring Crystal Lake samlar upp bladen och bär dem inåt land. De samlar kelpen i läger vid sjön, vilket gör lägren till den enda lokala källan nära Goldshire.",al={"varför kelp vid crystal lake","kelp i sötvatten","murlocs och kelpens historia"}},{q="Vilka är Maybell Maclure och Tommy Joe Stonefield?",a="Maybell Maclure och Tommy Joe Stonefield är unga älskande från rivaliserande jordbrukarfamiljer i södra Elwynn Forest. Deras familjer avskyr varandra, så paret måste förlita sig på hemlighetsmakeri och alkemi för att träffas.",al={"vem är maybell","vem är tommy joe","fejden mellan maclure och stonefield"}},{q="Var ligger Crystal Lake?",a="Crystal Lake ligger strax öster om Goldshire i centrala Elwynn Forest. Fientliga murlocs hemsöker dess vatten och stränder.",al={"var ligger crystal lake","crystal lakes läge","hitta crystal lake"}},{q="Vad händer när kelpen har samlats in?",a="När du har lämnat över fyra blad crystal kelp destillerar William Pestle dem till en Invisibility Liquor. Sedan ber han dig ta den till Maybell Maclure så att hon kan smita iväg osedd.",al={"nästa uppdrag efter kelpen","vad tillverkar pestle"}},{q="Vem är William Pestle?",a="William Pestle är apotekare och amatöralkemist på Lion's Pride Inn i Goldshire. Han hjälper ortsbor med huskurer, märkliga drycker och diskreta tjänster.",al={"vem är william pestle","pestle i goldshire"}}},fx={ff0f7883={q="Varför vill William Pestle hjälpa Maybell och Tommy Joe?",a="William Pestle är Goldshires lokala apotekare och alkemist, och han är villig att använda sina kunskaper för att hjälpa de unga älskande. Maybell Maclure och Tommy Joe Stonefield befinner sig på varsin sida av familjernas bittra, långvariga fejd. En hemlig osynlighetsdryck ger Maybell ett listigt sätt att smita undan familjens vakande blickar på The Maclure Vineyards utan att förvärra fejden mellan släkterna.",al={"varför hjälpa maybell","william pestles motiv","varför bryr sig william"}},cc419076={q="Varför har murlocar samlats vid Crystal Lake?",a="Murlocar har smugit sig inåt land från kusterna och slagit läger vid sötvattensområden i Elwynn Forest, som Crystal Lake och Stonecairn Lake. Stormwinds militär är upptagen med att försvara andra gränser, så dessa aggressiva groddjur har blivit djärvare, tränger sig på lokala bosättningar och samlar in material — bland annat havstång som de bär med sig inåt land.",al={"varför finns murlocar vid crystal lake","murlocar vid crystal lake","murlocar i elwynn"}}},fp="15,148,27.431.0,30.406.0,42.183.0,53.191.0,49.206.0,30.112.0,39.178.0,22.170.0"}
P.entries["quest:1120"] = {n="Get the Gnomes Drunk",s="Kravel Koalbeard vill att Fool's Stout testas på ett depålag vid Mirage Raceway. Om du väljer gnomerna tar du ölet till Gnome Pit Boss. Ölet blir dåligt så småningom, så Kravel säger åt dig att inte vänta för länge.",h="Kravel Koalbeard vill att Fool's Stout testas på ett depålag vid Mirage Raceway.",kw={"fool's stout","gnome pit boss","kravel koalbeard","mirage raceway","thousand needles","zanzil"},sec={{t="Ett test på depålagen",b="Kravel Koalbeard behöver få Fool's Stout testat på ett av depålagen. Du kan prova det på gnomerna: han ger dig ölet och skickar dig med det till Gnome Pit Boss, som finns i närheten vid Mirage Raceway. Om du väljer gnomerna gynnas goblinerna i tävlingarna. Kravel varnar dig för att dröja, eftersom ölet blir dåligt så småningom."},{t="En liten drink före loppet",b="Gnome Pit Boss blir glad över gåvan och kallar den omtänksam. Det är inte klokt att dricka när ett lopp snart ska börja, medger Pit Boss, men laget kan nog ta lite. Det kan ju inte vara så starkt."}},faq={{q="Vem ber dig leverera ölet?",a="Kravel Koalbeard, dvärgen vid Mirage Raceway i Thousand Needles, ger dig ölet.",al={"vem ger uppdraget få gnomerna fulla","uppdragsgivare få gnomerna fulla","kravel koalbeard uppdrag"}},{q="Vem ska få Fool's Stout?",a="Gnome Pit Boss, som finns i närheten vid Mirage Raceway.",al={"vart ska jag ta ölet","vem får fool's stout","gnome pit boss plats"}},{q="Vad händer om det dröjer för länge innan du levererar ölet?",a="Ölet blir dåligt så småningom, så Kravel säger åt dig att inte vänta för länge.",al={"blir fool's stout dåligt","tidsgräns för ölet","fool's stout blir dåligt"}},{q="Kan du välja att rikta in dig på goblinerna i stället?",a="Ja. Kravel låter dig välja vilket depålag som ska testa ölet, och det andra alternativet är Get the Goblins Drunk.",al={"valet få goblinerna fulla","kan jag få goblinerna fulla i stället","gnomer eller gobliner vid kapplöpningsbanan"}},{q="Vad kommer före det här?",a="Det följer efter Zanzil's Mixture och a Fool's Stout.",al={"föregående uppdrag","förutsättning för get the gnomes drunk"}},{q="Vad händer efter att ölet har levererats?",a="Uppdragskedjan fortsätter med Report Back to Fizzlebub.",al={"nästa uppdrag","vad kommer efter get the gnomes drunk"}}},fp="20,222,23.338.0,30.214.1,34.91.0,45.59.0,55.75.0,45.108.0,23.47.0,40.50.0"}
P.entries["quest:1121"] = {n="Get the Goblins Drunk",s="Kravel Koalbeard vill att Fool's Stout testas på ett depålag vid Mirage Raceway. Om du väljer goblinerna tar du ölet till Goblin Pit Boss. Ölet blir dåligt till slut, så Kravel säger att du inte ska vänta för länge.",h="Kravel Koalbeard vill att Fool's Stout testas på ett depålag vid Mirage Raceway.",kw={"fool's stout","gnom","goblin","goblin pit boss","kravel koalbeard","mirage raceway","thousand needles"},sec={{t="Ett test på depålagen",b="Kravel Koalbeard behöver få Fool's Stout testad på ett av depålagen. Du kan testa det på goblinerna: han ger dig ölet och skickar dig till Goblin Pit Boss, som finns i närheten vid Mirage Raceway. Om du väljer goblinerna gynnas gnomerna i loppen. Kravel varnar dig för att dröja, eftersom ölet blir dåligt till slut."},{t="Lite skadar inte",b="Goblin Pit Boss ser att det bjuds på sprit och har inget emot att ta sig en liten slurk."}},faq={{q="Vem erbjuder det här?",a="Kravel Koalbeard, dvärgen vid Mirage Raceway i Thousand Needles.",al={"uppdragsgivare","vem ger uppdraget get the goblins drunk","kravel koalbeard"}},{q="Vart ska ölet tas?",a="Till Goblin Pit Boss, som finns i närheten vid Mirage Raceway.",al={"vart ölet ska tas","goblin pit boss plats"}},{q="Vad händer om du väntar för länge?",a="Ölet blir dåligt till slut, så Kravel säger att du inte ska vänta för länge.",al={"blir ölet dåligt","hur länge håller fool's stout","ölet blir dåligt"}},{q="Vad är alternativet?",a="Kravel låter dig välja vilket depålag som ska testa ölet. Det andra valet är Get the Gnomes Drunk, med gnomernas lag.",al={"valet get the gnomes drunk","gnomer eller gobliner vid racerbana"}},{q="Vad kommer före det här?",a="Det följer efter Zanzil's Mixture och Fool's Stout.",al={"föregående uppdrag","förutsättning för get the goblins drunk"}},{q="Vad händer efter att ölet har levererats?",a="Kedjan fortsätter med Report Back to Fizzlebub.",al={"nästa uppdrag","vad kommer efter get the goblins drunk"}}},fp="21,224,23.340.0,19.74.1,16.70.0,30.60.0,34.75.0,32.119.0,23.47.0,40.50.0"}
P.entries["quest:1122"] = {n="Report Back to Fizzlebub",s="Kravel Koalbeard säger att Fool's Stout fungerade utmärkt. Han har satsat pengar på nästa lopp och hoppas att depåteamet du gjorde berusat kvaddade sin egen bil. Du tar med dig en lapp om det lyckade testet till Crank Fizzlebub i Booty Bay. Detta följer efter att du valde vilket depåteam du skulle göra berusat.",h="Kravel Koalbeard säger att Fool's Stout fungerade utmärkt.",kw={"booty bay","crank fizzlebub","fool's stout","kravel koalbeard","mirage raceway","the shimmering flats","thousand needles"},sec={{t="En lapp till Crank",b="Kravel Koalbeard säger att Fool's Stout fungerade utmärkt. Han har satsat pengar på nästa lopp och hoppas att depåteamet du gjorde berusat kvaddade sin egen bil. Ett jobb återstår: ta med en lapp om det lyckade testet till Crank Fizzlebub i Booty Bay, som gärna vill höra om det. Kravel hoppas också att det går att få tag på mer av drycken inför framtida lopp."},{t="Cranks svar",b="Crank Fizzlebub läser lappen, kallar testet lyckat och gläds åt nyheten. Om du någon gång vill ha mer av drycken säger Crank att du bara ska fråga, så får du samla in mer Zanzil's Mixture."}},faq={{q="Vem ger uppdraget?",a="Kravel Koalbeard, dvärgen vid Mirage Raceway på The Shimmering Flats i Thousand Needles, ger dig lappen.",al={"uppdragsgivare","vem ger rapporten till fizzlebub"}},{q="Var finns Crank Fizzlebub?",a="I Booty Bay.",al={"fizzlebubs plats","var finns crank fizzlebub","plats för inlämning"}},{q="Vad kommer före det här?",a="Det följer efter Get the Gnomes Drunk eller, om du valde det andra teamet, Get the Goblins Drunk.",al={"förutsättningar","föregående uppdrag"}},{q="Vad vill Kravel Koalbeard att Fizzlebub ska få veta?",a="Att testet lyckades.",al={"vad innehåller rapporten","rapportens innehåll"}}},fp="24,268,16.332.0,14.201.1,16.114.0,33.13.0,23.87.0,50.28.0"}
P.entries["quest:1127"] = {n="Fool's Stout",s="Crank Fizzlebub i Booty Bay brygger omgångar av Fool's Stout åt resenärer som vill återvända till kapplöpningsbanan i The Shimmering Flats. För att brygga en ny sats behöver han tolv flaskor Zanzil's Mixture.",h="Crank Fizzlebub i Booty Bay brygger omgångar av Fool's Stout åt resenärer som vill återvända till...",kw={"booty bay","crank fizzlebub","fools stout","kapplöpningsbana","stranglethorn vale","zanzils mixture"},sec={{t="En andra sats",b="För resenärer vars första förråd av Fool's Stout har dunstat innan de når gnomen vid kapplöpningsbanan erbjuder Crank Fizzlebub sig att brygga en ersättning. Goblinen Crank Fizzlebub i Booty Bay behöver tolv flaskor Zanzil's Mixture för att återigen tillreda den starka drycken. Han ersätter alla som hämtar ingredienserna och erbjuder lite extra för att hålla affären diskret."}},faq={{q="Vem erbjuder sig att brygga Fool's Stout?",a="Crank Fizzlebub, som finns i Booty Bay i södra Stranglethorn Vale, brygger ölet.",al={"vem ger fools stout","uppdragsgivare för fools stout","crank fizzlebub"}},{q="Vilka ingredienser behöver Crank Fizzlebub?",a="Han behöver tolv flaskor Zanzil's Mixture för att brygga en ny sats av ölet.",al={"vilka föremål behövs till fools stout","ingredienser till fools stout","krav på zanzils mixture"}},{q="Varför skulle någon behöva ännu en sats Fool's Stout?",a="Brygden dunstar efter två timmar, så resenärer som missar den tidsfristen måste samla färska ingredienser för en ersättningssats.",al={"varför behövs mer fools stout","fools stout har dunstat","hur länge varar fools stout"}},{q="Vart är brygden tänkt att ta vägen?",a="Brygden är avsedd för gnomen vid kapplöpningsbanan.",al={"vart ska fools stout","vem dricker fools stout","fools stouts destination"}}},fp="12,198,14.393.0,32.91.0,43.81.0,53.125.0,33.48.0"}
P.entries["quest:113"] = {n="Insect Part Analysis",s="Alchemist Pestlezugg har färdigställt rapporten om insektsdelarna och säger att Senior Surveyor Fizzledowser måste se den genast. Hotet riktar sig mot Tanaris och Gadgetzan och, om det inte hejdas, hela södra Kalimdor.",h="Alchemist Pestlezugg har färdigställt rapporten om insektsdelarna och säger att Senior Surveyor Fizzledowser...",kw={"fizzledowser","gadgetzan","gadgetzan water company","insektsanalys","pestlezugg","rapport","tanaris"},sec={{t="En allvarlig varning",b="Pestlezugg insisterar på att Senior Surveyor Fizzledowser måste se rapporten genast, och att alla som kan läsa också måste få se den. Hotet är allvarligt och farligt för Tanaris och Gadgetzan och, om det inte hejdas, för hela södra Kalimdor. Det kan till och med nå hela Azeroth, eftersom det inte visat några tecken på att avta. Du ombeds att ta rapporten till Fizzledowser i Gadgetzan och låta göra en kopia som du fritt kan dela med dina egna. Alla måste känna till hotet."},{t="En fråga om pengar",b="Fizzledowser tackar dig för leveransen och för ditt hårda arbete åt Gadgetzan Water Company. Fizzledowser gillar inte tanken på att lämna ut företagets värdefulla information till alla, eftersom folk normalt skulle betala bra för den. Men Fizzledowser har känt Pestlezugg länge, och om Pestlezugg rekommenderar att alla får veta, så får det bli så. En kopia görs åt dig."}},faq={{q="Vem skickar rapporten och vem tar emot den?",a="Alchemist Pestlezugg ger dig rapporten och skickar dig med den till Senior Surveyor Fizzledowser i Gadgetzan.",al={"vem ger insect part analysis","vem lämnar jag in insect part analysis till","var ska rapporten lämnas"}},{q="Varför är Alchemist Pestlezugg så oroad?",a="Pestlezugg kallar det ett allvarligt och farligt hot mot Tanaris och Gadgetzan och, om det inte hejdas, mot hela södra Kalimdor och kanske hela Azeroth. Det finns inga tecken på att hotet avtar.",al={"pestlezuggs varning","vad står i insektsrapporten","varför är insekthotet allvarligt"}},{q="Varför behöver du en kopia av rapporten?",a="Pestlezugg vill att alla ska känna till hotet, så Fizzledowser ska göra en kopia som du fritt kan sprida bland dina egna.",al={"varför kopiera rapporten","fizzledowsers rapportkopia","varför dela rapporten"}},{q="Vad händer direkt före den här leveransen?",a="Den följer på ett tidigare steg som också heter Insect Part Analysis.",al={"föregående uppdrag","vilket uppdrag kommer före detta"}}},fp="20,212,15.495.0,16.367.1,41.109.0,39.185.0,37.145.0,41.59.0"}
P.entries["quest:1130"] = {n="Melor Sends Word",s="Melor Sends Word är en kallelse som Jorn Skyseer överlämnar i The Barrens på uppdrag av den berömde jägaren Melor Stonehoof. Äventyrare på väg uppåt som visat sin styrka runtom i Kalimdor skickas till Hunter's Rise i Thunder Bluff för att prövas betydligt hårdare.",h="Melor Sends Word är en kallelse som Jorn Skyseer överlämnar i The Barrens på uppdrag av den berömde jägaren...",kw={"the barrens","camp taurajo","hunter's rise","jorn skyseer","melor sends word","melor stonehoof","steelsnap","thunder bluff"},ang={["class:Hunter"]="Melor Stonehoof förkroppsligar taurenfolkets bestkonst och kräver precision, tålamod och fullständig respekt för farliga byten.",["faction:Horde"]="Camp Taurajo och Thunder Bluff förlitar sig på skickliga fältagenter som håller farliga rovdjur borta från Hordes försörjningsleder och utposter.",["race:Tauren"]="Bland tauren är svaret på Melors kallelse en traditionell övergångsrit som visar att man blivit vuxen och vunnit anseende. Den bevisar ens mästerskap i jakten och bringar ära åt Hunter's Rise."},sec={{t="En kallelse till Thunder Bluff",b="Ord sprids snabbt över slätterna. När en äventyrare får erfarenhet i The Barrens och trakterna däromkring lägger framstående jägare märke till dem som visar verklig begåvning. Jorn Skyseer håller uppsikt över vadställena och lägren och tjänar som utsänd för de äldste på Hunter's Rise. Han söker upp lovande jägare och krigare för att meddela dem att Melor Stonehoof, en vördad mentor bland tauren, har stakat ut en särskild väg åt dem."},{t="Jaktens väg",b="När den sökande klättrar upp till Hunter's Rise i Thunder Bluff möter hen Melor själv. Den äldre jägaren ger inga lovord, utan frågar om äventyraren har mod nog att ge sig ut i farlig, avlägsen vildmark. Om du antar kallelsen får du tillträde till prövningsmarker långt bortom Mulgore och ställs mot kontinentens allra grymmaste rovdjur."}},faq={{q="Vem är Melor Stonehoof?",a="Melor Stonehoof är en erfaren taurenjägare stationerad på Hunter's Rise i Thunder Bluff. Han prövar Horde-jägare och krigare på frammarsch och skickar värdiga kandidater runtom i Kalimdor för att spåra och jaga ökända bestar.",al={"melor","vem är melor","melor stonehoof historia"}},{q="Vem överlämnar kallelsen?",a="Jorn Skyseer, en taurenbestämjare bosatt i Camp Taurajo i The Barrens, förmedlar budskapet. Han håller uppsikt över resande och skickar dem som visat mod till Thunder Bluff för att tala direkt med Melor.",al={"vem inleder uppdraget","jorn skyseer","vem kallade på mig"}},{q="Var hittar jag Melor Stonehoof?",a="Melor finns på Hunter's Rise, den södra platån i Thunder Bluff som är tillägnad taurenjägare, spårare och bestämjare.",al={"var finns melor","var är melor","hunters rise thunder bluff"}},{q="Vilken väg har Melor planerat för mig?",a="Melor prövar din uthållighet och dina jaktinstinkter genom att skicka dig på krävande spårningsexpeditioner. Den första jakten går genom Thousand Needles, där du ska fälla den grymma hyenatyrannen Steelsnap.",al={"vad vill melor","nästa uppdrag efter melor sends word","melors uppdragskedja"}},{q="Varför rekryterar Melor äventyrare från The Barrens?",a="Den som överlever de skoningslösa rovdjuren, quilboarerna och kentaurerna i The Barrens visar sig ha de instinkter som krävs för elitjakter. Melor söker personer som kan spåra svårfunna och dödliga byten i okända trakter.",al={"varför jag","varför bryr sig melor"}},{q="Är den här prövningen bara för jägare?",a="Utmaningen kommer från Hunter's Rise och prövar en spårares egenskaper, men Melor utmanar alla äventyrare i Horde som visat styrka och uppfinningsrikedom i vildmarken.",al={"är det här ett jägaruppdrag","kan andra klasser göra det här"}}},fx={["2189d60f"]={q="Varför skickar Jorn Skyseer dig till Melor Stonehoof?",a="Jorn Skyseer fungerar som budbärare och mentor i The Barrens och håller utkik efter dugliga äventyrare som visar sin styrka. Han har bevittnat dina bedrifter över slätterna och förstår att du har vuxit ifrån de lokala uppgifterna. Därför hänvisar han dig till Hunter Rise i Thunder Bluff, där Melor Stonehoof förbereder värdiga jägare för mycket större prövningar runtom i Kalimdor.",al={"varför jorn skickar ett meddelande","varför vill jorn att jag träffar melor","jorn skyseers motiv"}},e1bd22c0={q="Varför väljer Jorn Skyseer just dig?",a="De äldste har hört talas om dina bedrifter i The Barrens. Melor Stonehoof kallar inte på vanliga spejare eller stadsvakter. Han söker beprövade vandrare som visat den skicklighet och uthållighet som krävs för att spåra upp de våldsammaste bestarna i fjärran länder. Jorn väljer ut dig eftersom ditt rykte visar att du är redo för Melors uppdrag.",al={"varför jag, melor skickar bud","varför valde jorn skyseer mig","varför kallar melor på mig"}}},fp="16,196,26.267.0,20.266.0,23.211.0,26.190.0,33.116.0,35.172.0,52.186.0,36.165.0"}
P.entries["quest:1131"] = {n="Steelsnap",s="Steelsnap är ett jaktuppdrag från Melor Stonehoof på Hunter Rise i Thunder Bluff. Jakten frångår taurenfolkets traditionella skäl att döda och går ut på att förgöra en våldsam hyena vars flock terroriserar djurlivet i Thousand Needles.",h="Steelsnap är ett jaktuppdrag från Melor Stonehoof på Hunter Rise i Thunder Bluff.",kw={"camp e'thok","jordmodern","hunter rise","hyena","melor stonehoof","steelsnap","thousand needles","thunder bluff"},ang={["class:Hunter"]="Att fälla Steelsnap sätter spårarens förmåga på prov. Du måste skilja ut en vild alfaledare ur flocken bland följeslagare som strövar omkring på kanjonbottnen.",["faction:Horde"]="En säkrare väg genom Thousand Needles skyddar viktiga försörjningsleder och resenärer som färdas från The Barrens mot The Shimmering Flats.",["race:Tauren"]="För Shu'halo är det en andlig fråga att ta ett djurs liv. Jakten på Steelsnap lär dig att gallra bort vilda inslag som orsakar meningslös grymhet och står utanför Jordmoderns nåd."},sec={{t="En jakt utanför välsignelsen",b="Taurenfolkets tradition säger att ett liv bara får tas av ett heligt eller praktiskt skäl: för att få mat, försvara sin heder eller vinna visdom från Jordmodern. Melor Stonehoof ser detta byte som ett undantag från regeln. Steelsnap betraktas som en styggelse mot den naturliga balansen, en brutal tyrann som sprider meningslöst våld och rädsla i stället för att upprätthålla livets kretslopp."},{t="Plågan i Needles",b="Steelsnap strövar omkring i kanjonerna i norra Thousand Needles och håller till söder om centaurernas läger vid Camp E'thok. Till skillnad från ensamma asätare får detta väldiga odjur våldsamma flockmedlemmar i släptåg och leder attacker som stör och decimerar de mer fridsamma djuren på kanjonens botten. När du dödar honom och hämtar hans revben renar du Needles från hans grymma inflytande."}},faq={{q="Varför vill Melor Stonehoof att Steelsnap ska dödas?",a="Melor Stonehoof ser Steelsnap som en avvikelse som står utanför Jordmoderns välsignelse. Till skillnad från jakter efter mat, heder eller naturlig balans är detta en reningshandling som ska stoppa ett tyranniskt rovdjur från att terrorisera fredliga djur.",al={"varför döda steelsnap","melor stonehoofs skäl","steelsnaps motiv"}},{q="Var finns Steelsnap?",a="Steelsnap strövar omkring på den dammiga kanjonbottnen i Thousand Needles, söder om centaurernas bosättning vid Camp E'thok i zonens nordvästra del.",al={"steelsnaps plats","var finns steelsnap","hitta steelsnap"}},{q="Vilket bevis ska du ta med tillbaka till Thunder Bluff?",a="Du måste ta Steelsnap's Rib från det dödade odjuret och visa upp den för Melor Stonehoof på Hunter Rise.",al={"steelsnaps trofé","steelsnaps mål","vad ska jag plundra"}},{q="Strider Steelsnap ensam?",a="Nej. Steelsnap färdas med andra hyenor som följer hans ledning, så det är farligt att möta honom och flera fiender samtidigt.",al={"är steelsnap ensam","steelsnaps flock","steelsnaps följeslagare"}},{q="Hur skiljer sig den här jakten från taurenfolkets traditionella jakter?",a="Taurenfolket jagar vanligtvis enbart för att få mat, vinna ära i strid eller få andlig insikt. Den här jakten är en förebyggande åtgärd för att avlägsna ett grymt odjur som stör landets naturliga harmoni.",al={"taurenfolkets jaktfilosofi","jordmodern och jakt","jaktens lärdom"}},{q="Var bor Melor Stonehoof?",a="Melor Stonehoof bor på Hunter Rise i Thunder Bluff, där han undervisar jägare och sätter erfarna spårare på prov.",al={"melor stonehoofs plats","var finns melor","melors koordinater"}}},fx={["1c130f9f"]={q="Vad är Steelsnap för ett slags best?",a="Steelsnap är en våldsam, tyrannisk hyena som stryker omkring på botten av ravinen i Thousand Needles. Till skillnad från vanliga vilddjur leder han en flock asätare i meningslöst blodbad, terroriserar fredligare varelser och rubbar naturens balans. Melor Stonehoof anser att han är en vidrig varelse som helt har förskjutits från Earthmothers välsignelse.",al={"vem är steelsnap","vad är steelsnap","hyenan steelsnap"}}},fp="9,163,27.268.0,26.275.0,47.233.0,29.85.0,49.73.0,27.56.0,56.146.0,33.110.0"}
P.entries["quest:1132"] = {n="Fiora Longears",s="Det här ärendet introducerar Alliansens äventyrare från Eastern Kingdoms för Kalimdors otämjda kontinent. På uppdrag av den entusiastiske rekryteraren Red Jack Flint i Menethil Harbor seglar resenärer över Great Sea för att möta hans högälvskontakt Fiora Longears på värdshuset i Theramore.",h="Det här ärendet introducerar Alliansens äventyrare från Eastern Kingdoms för Kalimdors otämjda kontinent.",kw={"theramore","båt","dustwallow marsh","fiora longears","kalimdor","menethil harbor","red jack flint","wetlands"},ang={["faction:Alliance"]="Den här resan utgör en förbindelse mellan Eastern Kingdoms och nattalvernas områden i Kalimdor och förenar Alliansens östra och västra gränstrakter.",["race:NightElf"]="Fiora Longears välkomnar officiellt östliga allierade som anländer till Theramore och förbereder dem för norra Kalimdors uråldriga vildmarker."},sec={{t="En kallelse västerut",b="För många människor, dvärgar och gnomer präglas Eastern Kingdoms av gamla konflikter och sargad mark. I den livliga hamnen Menethil Harbor ägnar sjömannen Red Jack Flint dagarna åt att uppmana äventyrslystna resenärer att gå ombord på ett fartyg över Great Sea. Flint beskriver Kalimdor som ett outforskad rike fyllt av rikedomar och möjligheter och hänvisar djärva vandrare till Theramore för att träffa sin medarbetare, en alv vid namn Fiora Longears."},{t="Framme i Theramore",b="Överfarten för resenärerna till Theramore, en allianshamn vid Dustwallow Marshs kust. Fiora Longears väntar på stadens värdshus och tar emot nyanlända som Flint har rekommenderat. Fiora litar på Flints människokännedom, välkomnar de nyanlända allianshjältarna och förbereder sig på att visa dem vägen inåt landet mot Ashenvales uråldriga skogar."}},faq={{q="Vem är Fiora Longears?",a="Fiora Longears är en högälva som är stationerad på värdshuset i Theramore i Dustwallow Marsh. Hon är Red Jack Flints välkomnande partner och kontakt och hälsar alliansresenärer från Eastern Kingdoms välkomna.",al={"fiora longears","vem är fiora"}},{q="Vem startar det här uppdraget?",a="Uppdraget erbjuds av Red Jack Flint, en energisk mänsklig sjöman i Menethil Harbor vid Wetlands kust.",al={"uppdragsgivare","var får man uppdraget fiora longears","vem ger uppdraget"}},{q="Hur tar jag mig till Fiora Longears från Menethil Harbor?",a="Gå ombord på passagerarfartyget som ligger förtöjt i Menethil Harbor. Det seglar västerut över Great Sea direkt till Theramore i Dustwallow Marsh.",al={"hur tar man sig till theramore","fartyg till theramore","båt från menethil"}},{q="Vad händer efter mötet med Fiora Longears?",a="När Fiora hälsar dig välkommen i Theramore berömmer hon Flints rekommendation och erbjuder nästa etapp på din resa. Hon skickar dig inåt landet till Astranaar i Ashenvale.",al={"what comes next","fortsättningsuppdrag","uppdraget resa till astranaar"}},{q="Vilken relation har Red Jack Flint och Fiora Longears?",a="Flint beskriver Fiora som sin partner på andra sidan havet. Medan Flint spanar efter äventyrslystna resenärer i Eastern Kingdoms tar Fiora emot dem i Kalimdor för att stödja Alliansens verksamhet och resor inåt landet.",al={"är flint och fiora partner","red jack flint och fioras koppling"}},{q="Varför rekryterar Alliansen resenärer till Kalimdor?",a="Kalimdor erbjuder Alliansen stora nya områden och resurser, liksom en front där nattalvernas allierade behöver hjälp att skydda sina förfäders marker mot hot som horden och demoniska rester.",al={"varför åka till kalimdor","varför theramore"}}},fx={["869cd7aa"]={q="Varför vill Red Jack Flint skicka dig till Kalimdor?",a="Red Jack Flint ser sig själv som en möjligheternas man, med uppgiften att inspirera lovande äventyrare i Menethil Harbor att korsa Stora havet. Själv är han bunden till hamnen och längtar efter sjöresor. Hans roll är att hitta hårdföra själar och hänvisa dem till sin högalviska partner, Fiora Longears, som hjälper nykomlingar att komma till rätta och delta i Alliansens växande insatser i Kalimdor.",al={"red jack flints motiv","varför skicka mig till fiora","varför vill jack flint att detta görs"}}},fp="14,298,18.431.0,20.337.0,22.211.0,22.125.0,51.136.0,42.156.0,67.199.0,53.213.0"}
P.entries["quest:1133"] = {n="Journey to Astranaar",s="Journey to Astranaar är ett introduktionsuppdrag för Alliansen som leder nykomlingar från Kalimdors kust till Ashenvales inre. På Theramore visar Fiora Longears vägen norrut till Shindrell Swiftfire i Astranaar. Uppdraget markerar äventyrarens första steg in i de växande konflikterna kring nattalvernas förfädersskog.",h="Journey to Astranaar är ett introduktionsuppdrag för Alliansen som leder nykomlingar från Kalimdors kust till...",kw={"ashenvale","astranaar","theramore","dustwallow marsh","fiora longears","journey to astranaar","menethil harbor","shindrell swiftfire"},ang={["faction:Alliance"]="Den här färden innebär att en rekryt från Alliansen skickas direkt från de relativt trygga hamnarna i Dustwallow Marsh till Ashenvales omstridda vildmark.",["race:Human"]="Direkt från fartyget från Menethil Harbor tar mänskliga resenärer sina första steg djupt in i Kalimdors inland och infriar Alliansens löfte att hjälpa nattalverna.",["race:NightElf"]="För nattalver är den här resan en återkomst till deras belägrade hemland, där de tillsammans med utländska allierade försvarar Ashenvales heliga grenar."},sec={{t="Från kusten in i skogen",b="Alliansens resenärer som anländer till Dustwallow Marsh med färjan från Menethil Harbor söker ofta efter en uppgift i norra Kalimdor. I Theramore skickar Fiora Longears dugliga personer längre inåt landet mot Astranaar, den främsta nattalvbosättningen i Ashenvale. Resan följer slingrande stigar under uråldriga, skuggiga trädkronor och leder rakt in i en skog som plågas av krig och oro."},{t="En outtalad rekommendation",b="Märkligt nog säger Fiora åt resenärerna att inte nämna hennes namn när de kommer till Astranaar, och förklarar rakt på sak att Shindrell Swiftfire inte känner henne. Hennes roll är helt enkelt att skicka nya alliansstyrkor dit de behövs som mest. När de anländer välkomnar Shindrell gärna alla försvarare som är redo att kämpa och medger att Ashenvale fortfarande är häpnadsväckande vackert, men inte längre den fridfulla tillflyktsort det en gång var."}},faq={{q="Var börjar uppdraget Journey to Astranaar?",a="Uppdraget ges av Fiora Longears i Theramore, vid kusten av Dustwallow Marsh. Hon erbjuder det till alliansresenärer från Eastern Kingdoms som vill hjälpa till i Kalimdor.",al={"vem ger journey to astranaar","starta journey to astranaar","var hämtar man journey to astranaar"}},{q="Vem ska jag prata med i Astranaar?",a="Du måste prata med Shindrell Swiftfire, en nattalv stationerad i Astranaar, Alliansens centrala stad i Ashenvale.",al={"var lämnar man in journey to astranaar","slut-npc för journey to astranaar","vem är shindrell swiftfire"}},{q="Varför säger Fiora att jag inte ska nämna hennes namn?",a="Fiora Longears säger uttryckligen åt äventyrarna att inte nämna vem som skickade dem, helt enkelt för att Shindrell inte känner henne personligen. Hon visar bara ivriga nykomlingar till en utpost som desperat behöver hjälp.",al={"varför inte nämna fiora","fiora longears koppling till shindrell"}},{q="Vad är syftet med uppdraget?",a="Det fungerar som en vägvisare som leder alliansfigurer från Dustwallow Marsh till Ashenvale och introducerar Astranaar som deras främsta bas i skogen.",al={"varför göra journey to astranaar","syftet med journey to astranaar i berättelsen"}},{q="Vilka problem pågår i Ashenvale?",a="Som Shindrell Swiftfire påpekar när du kommer fram är Ashenvale inte längre den fridfulla lund den en gång var. Skogen drabbas av intrång från horden, demonisk korruption som dröjer sig kvar sedan Tredje kriget och det lokala djurliv som oroas av de senaste konflikterna.",al={"varför behöver astranaar hjälp","ashenv ales problem i berättelsen"}},{q="Vilket uppdrag leder fram till Journey to Astranaar?",a="Det föregås direkt av ett kort introduktionsuppdrag med vägvisning, kallat 'Fiora Longears', som ber resenärer som ankommer till Dustwallow Marsh att prata med henne i Theramore.",al={"förutsättning för journey to astranaar","fiora longears uppdragskedja"}}},fx={["5f2da217"]={q="Varför skickar Fiora Longears dig till Astranaar?",a="Fiora ser nya Alliansresenärer anlända till Theramore och hänvisar dugliga äventyrare dit de behövs mest. Astranaar är den centrala nattalvsbosättningen i Ashenvale, en region som just nu präglas av växande faror och fientliga intrång. Hon hänvisar dig till Shindrell Swiftfire så att dina färdigheter genast kan bidra till Alliansens ansträngda försvar av den uråldriga skogen.",al={"varför skicka mig till astranaar","fiora longears motiv","varför skickar fiora dig"}},["432055d5"]={q="Varför ber Fiora dig att åka i stället för att åka själv?",a="Fiora stannar på Theramore Inn i Dustwallow Marsh och hänvisar villiga resenärer till Shindrell Swiftfire i Astranaar, där deras hjälp behövs.",al={"varför jag, resan till astranaar","varför åker inte fiora till astranaar","varför inte fiora"}}},fp="20,173,29.348.0,26.320.0,48.178.0,38.97.0,43.147.0,34.129.0,47.166.0,43.148.0"}
P.entries["quest:1134"] = {n="Pridewings of Stonetalon",s="Shindrell rapporterar ett obekräftat påstående: Sentinelstyrkorna i Astranaar oroar sig för hemliga Horde-attacker och vill lägga beslag på ett dödligt vapen innan det kan skada deras folk. Underrättelser från Theramore avslöjar att orciska lönnmördare samlar gift från wyvernerna i Stonetalon Mountains för hemliga räder. För att skydda den utsatta gränsen skickas Alliance-spejare söderut för att samla giftsäckarna först och beröva fienden dess dödliga gift.",h="Shindrell rapporterar ett obekräftat påstående: Sentinelstyrkorna i Astranaar oroar sig för hemliga...",kw={"lönnmördare","astranaar","mirkfallon lake","pridewings","shindrell swiftfire","stonetalon mountains","theramore","gift"},ang={["class:Druid"]="Druider sörjer ofta slöseriet med liv i naturen och beklagar att oskyldiga varelser måste dödas enbart för att deras gifter inte ska hamna hos krigshetsare.",["class:Rogue"]="Rogues kan uppskatta pridewing-giftets dödliga användbarhet och förstår precis hur förödande bestrykta klingor kan vara i hemliga bakhåll i vildmarken.",["faction:Alliance"]="Uppdraget visar det tysta underrättelsenätverk som knyter Jainas bosättning i Theramore till Sentinel-utposterna i Ashenvale i ett försök att hejda Hordes aggression.",["race:NightElf"]="Nattalverna kämpar med den bistra nödvändigheten att döda vilda pridewings och väger sitt andliga ansvar för naturen mot gränskrigets hårda verklighet."},sec={{t="En bräcklig vapenvila",b="Även om öppet krig inte har utropats mellan Alliance och Horde i norra Kalimdor är freden dem emellan skör. Sammandrabbningar bryter ut under den täta skogens lövverk, och tysta, förnekbara angrepp har ersatt stora arméer. Sentinelbefälhavarna i Astranaar håller ständig uppsikt över fiendens hemliga rörelser, medvetna om att lättja kan kosta dem deras fristad."},{t="Gift från klipporna",b="Shindrell rapporterar ett obekräftat påstående: Underrättelser från hemlighetsfulla kontakter i Theramore berättar om en ondskefull verksamhet i Stonetalon Mountains klippiga bergstrakter. Orciska förföljare har samlat gift från vilda pridewings kring Mirkfallon Lake och använder det kraftfulla biologiska giftet för att bestryka sina klingor inför dödliga bakhåll mot Alliance-styrkor. För att hejda hotet skickar Shindrell Swiftfire ut hjältar för att fälla bestarna och ta giftsäckarna innan Horde-agenter hinner samla in dem."},{t="En smärtsam plikt",b="Det tynger nattalverna att beordra att inhemska bestar ska dödas, eftersom de vördar Kalimdors vildmark djupt. Shindrell själv sörjer att oskyldiga varelser måste lida för ett krig de inte valt att delta i. Men i gränsförsvarets bistra kalkyl går det före att neka fienden dödliga vapen än att bevara ekosystemet."}},faq={{q="Vad är pridewings?",a="Pridewings är farliga, giftiga flygande bestar som är släkt med wyverner och bygger bo på höga klippor, särskilt kring Mirkfallon Lake i Stonetalon Mountains. Deras kraftiga gift gör dem till dödliga rovdjur och en eftertraktad resurs för giftblandare.",al={"vad är pridewings","pridewing-lore","pridewings i stonetalon"}},{q="Varför jagar Alliance dem?",a="Shindrell rapporterar ett obekräftat påstående: Alliance-underrättelser tyder på att Horde-lönnmördare aktivt samlar pridewing-gift för att bestryka vapen som används vid hemliga räder mot Alliance-ställningar. Genom att slakta bestarna och ta deras giftsäckar först berövar Alliance Horde detta dödliga gift.",al={"varför döda pridewings","uppdragets syfte","alliance och pridewing-gift"}},{q="Vem lämnade uppgifterna om de orciska lönnmördarna?",a="Varningen kom från dolda Alliance-informatörer i Theramore, som noga bevakar Horde-rörelser och försörjningsnätverk i Southern Barrens och Stonetalon Mountains.",al={"vem varnade alliance","spioninformation från theramore","källa till shindrells underrättelser"}},{q="Var ligger Mirkfallon Lake?",a="Mirkfallon Lake ligger i den norra delen av Stonetalon Mountains, strax söder om gränsstigen från Ashenvale.",al={"mirkfallon lakes läge","var finns pridewings","hitta pridewings"}},{q="Är Alliance och Horde i öppet krig i Ashenvale?",a="Officiellt upprätthåller de två fraktionerna en bräcklig fred och undviker att förklara öppet krig. I verkligheten blossar hemliga lönnmord, strider om resurser och gränskonflikter ständigt upp under skogens lövverk.",al={"är horde och alliance i krig","krigsläget i ashenvale","fredsavtal i ashenvale"}},{q="Hur känner Shindrell Swiftfire inför att döda bestarna?",a="Shindrell sörjer att hon måste beordra slakten av bestar som inte frivilligt gett sig in i konflikten. Men som befälhavare med ansvar för Astranaars försvar ser hon det som en tragisk nödvändighet för att hålla sitt folk tryggt.",al={"shindrells reaktion","druidisk skuld","nattalver dödar bestar"}}},fx={["9b2e4c3f"]={q="Vad ska Pridewing Venom Sac användas till?",a="Shindrell Swiftfire låter dig samla in giftsäckarna för att bevisa att bestarna har gallrats ut och för att neka Horden en dödlig tillgång. Obekräftade underrättelser från Theramore varnar för att orchiska lönnmördare samlar gift från pridewings vid Mirkfallon Lake och stryker det på sina vapen inför hemliga räder mot Alliansen. Om du själv samlar in säckarna ser du till att giftet aldrig når fiendens klingor.",al={"vad pridewing venom sac används till","varför samla giftsäckar","vad gör shindrell med giftsäckarna"}}},fp="24,265,15.321.0,21.378.0,14.278.0,20.227.0,33.234.0,54.153.0,33.105.0,52.159.0,59.203.0"}
P.entries["quest:1135"] = {n="Highperch Venom",s="Fiora Longears i Theramore skickar alliansens äventyrare västerut till ravinerna i Thousand Needles. Där häckar farliga wyverner högst uppe på Highperchs klippor, berömda för sitt exceptionellt kraftfulla gift.",h="Fiora Longears i Theramore skickar alliansens äventyrare västerut till ravinerna i Thousand Needles.",kw={"dustwallow marsh","fiora","highperch","longears","theramore","thousand needles","gift","wyvern"},ang={["class:Rogue"]="Skurkar förstår av naturen exotiska gifts mörka lockelse. Att skaffa rent, obearbetat wyverngift ger en nära inblick i Kalimdors dödligaste biologiska ämnen.",["faction:Alliance"]="När Alliansens äventyrare ger sig in i Thousand Needles hamnar de djupt bakom fiendens linjer, rakt under Hordens taureners och orchers vaksamma blickar.",["race:NightElf"]="För kaldorei visar det hur långt handelsintressen och jakten på märkliga ingredienser sträcker sig bortom Ashenvale och Darkshore, när jägare skickas djupt in i Thousand Needles torra ödemarker."},sec={{t="En lönsam expedition",b="När resande vilar i öhamnen Theramore kan de stöta på Fiora Longears. Orcher fångar och tämjer ofta wyverner som flygande riddjur, men Fiora pekar på en betydligt mer hemlig handel: varelsernas dödliga gift. Vissa köpare i Kalimdor värderar färska giftsäckar långt högre än själva bestarna. Därför rekryterar Fiora jägare som vågar färdas långt och klättra på osäkra höjder."},{t="Highperchs klippor",b="Bytet har sina bon väster om Dustwallow Marsh, bland de väldiga sandstensplatåerna i Thousand Needles. Wyvernerna vid den plats som kallas Highperch har ovanligt koncentrerat gift. För att nå bona måste du ta dig genom fientligt Hordeterritorium och uppför förrädisk terräng. Där måste jägarna döda wyverner och få ut giftsäckarna hela innan de bär bytet tillbaka till Theramore."}},faq={{q="Var hittar jag wyvernerna till det här uppdraget?",a="Wyvernerna håller till vid Highperch, en hög platå i västra delen av Thousand Needles, väster om Theramore.",al={"highperchs läge","var ligger highperch","wyvernernas läge"}},{q="Vem är Fiora Longears?",a="Fiora Longears är en kontakt för Alliansen som är stationerad i Theramore, utanför Dustwallow Marsh kust. Hon rekryterar djärva äventyrare för att skaffa sällsynta och värdefulla naturingredienser från olika delar av Kalimdor.",al={"fiora longears","vem ger uppdraget highperch venom"}},{q="Varför är wyverngift så värdefullt?",a="Wyverngift är mycket kraftfullt och eftertraktat i vissa undre kretsar, bland apotekare och i handelsnätverk. Horden värdesätter främst wyverner som flygande riddjur, men deras giftkörtlar betingar ett högt pris bland alkemister och giftblandare.",al={"varför wyverngift","användning av wyverngift"}},{q="Varför skickar ett uppdrag från Theramore mig så långt västerut?",a="Fiora är en företagsam handlare som söker exotiska exemplar som inte finns i träskmarkerna kring Theramore. I Highperch i Thousand Needles finns en särskild wyvernsort med koncentrerat gift som inte förekommer i Dustwallow Marsh.",al={"varför thousand needles","varför skicka till thousand needles"}},{q="Vad händer när jag lämnar tillbaka giftsäckarna?",a="Fiora granskar säckarna och konstaterar att de är sprängfyllda med gift. Hon påpekar att sådan kvalitet oftast bara kommer från unga wyverner eller fruktsamma honor och gratulerar dig till jakten.",al={"fioras reaktion","slutföra uppdraget highperch venom"}},{q="Är Highperch säkert för resande från Alliansen?",a="Nej. Det finns gott om Horde i Thousand Needles, med bosättningar som Freewind Post i närheten. När du klättrar upp på Highperch måste du hantera både vilda rovdjur och fientliga Hordespejare.",al={"är highperch farligt","alliansen i thousand needles"}}},fx={["9e43b6cb"]={q="Varför vill Fiora Longears att det här görs?",a="Fiora har näsa för lönsam handel och sällsynta reagenser. De flesta känner bara till wyverner som riddjur som Horden har tämjt, men hon vet att vissa kretsar betalar dyrt för kraftfullt gift. Genom att samla in säckarna från Highperch kan hon göra en rejäl vinst på dessa specialiserade marknader.",al={"varför vill fiora ha gift","fiora longears motiv","varför samla wyverngift"}},ef763353={q="Vad ska Highperch Venom Sac användas till?",a="Giftsäckarna innehåller det dödliga, kraftfulla giftet från vilda wyverner som bygger bo på höjderna i Thousand Needles. De är högt värderade av vissa alkemister, giftblandare och exotiska handelsmän, och de sprängfyllda säckarna betingar enorma priser på marknader för sällsynta och farliga bestar.",al={"vad highperch venom sac används till","vad giftsäckar används till","varför samla giftsäckar"}},f9186ab4={q="Vilka varelser bygger bo på Highperch?",a="Highperch är en väldig platå i Thousand Needles som fungerar som vild tillflyktsort för traktens wyverner. De är otämjda och starkt revirhävdande. Dessa bevingade rovdjur glidflyger över ökenravinerna och fäller byten med sina giftiga gaddar innan de släpar upp måltiderna till sina steniga bon.",al={"vad är wyvernerna på highperch","vem jagar man på highperch","vad lever på highperch"}}},fp="15,226,22.421.0,22.392.0,43.115.0,22.195.0,32.245.0,48.220.0,44.181.0,41.193.0"}
P.entries["quest:1137"] = {n="News for Fizzle",s="Martek the Exiled i Badlands har nyheter om indurium till Fizzle Brassbolts. Du tar med Marteks budskap tillbaka till The Shimmering Flats i Thousand Needles.",h="Martek the Exiled i Badlands har nyheter om indurium till Fizzle Brassbolts.",kw={"badlands","fizzle brassbolts","indurium","induriummalm","martek the exiled","mirage raceway","the shimmering flats","thousand needles","uldaman"},sec={{t="Marteks ord om indurium",b="Martek berättar att indurium står emot värme anmärkningsvärt väl och tror att det passar Fizzles kolvar. Flagor duger dock inte: Fizzle behöver riktig induriummalm, utgrävd ur djupen i Uldaman vid Badlands norra gräns, som Martek pekar ut som induriums verkliga källa. Martek ber dig hälsa och återge allt detta för Fizzle Brassbolts."},{t="Fizzle får höra nyheten",b="Fizzle Brassbolts vill gärna höra vad Martek sa och om Martek kan hjälpa till. När du berättar om dina resor i Badlands förklarar Fizzle att indurium är nyckeln."}},faq={{q="Var börjar och slutar den här resan?",a="Martek the Exiled i Badlands ger dig ett budskap, och du tar det till Fizzle Brassbolts vid Mirage Raceway på The Shimmering Flats i Thousand Needles.",al={"vem ger nyheter till fizzle","var lämnar man in nyheter till fizzle","martek till fizzle"}},{q="Vilka nyheter skickar Martek till Fizzle?",a="Martek säger att indurium står emot värme anmärkningsvärt väl och bör passa till Fizzles kolvar. Fizzle behöver riktig malm i stället för flagor, och den måste brytas ur djupen i Uldaman.",al={"vad säger martek","indurium-nyheter","marteks budskap"}},{q="Var kommer induriummalmen ifrån?",a="Martek säger att den grävs upp ur djupen i Uldaman, vid Badlands norra gräns, som Martek kallar induriums verkliga källa.",al={"var finns induriummalm","induriummalmens källa"}},{q="Var i berättelsen passar det här steget in?",a="Det följer efter Indurium, i kedjan som började när Fizzle Brassbolts skickade dig till Martek the Exiled.",al={"nyheter till fizzle-kedjan","föregående uppdrag nyheter till fizzle"}}},fp="15,157,25.365.0,21.173.1,38.159.0,37.184.0,34.137.0,42.98.0"}
P.entries["quest:1138"] = {n="Fruit of the Sea",s="Fruit of the Sea är ett Alliance-uppdrag som fiskaren Gubber Blump erbjuder på Auberdines bryggor. Gubber brinner för rätter med kräftdjur och ber resenärer söka längs Darkshores kust efter Fine Crab Chunks medan han sköter sina fiskelinor.",h="Fruit of the Sea är ett Alliance-uppdrag som fiskaren Gubber Blump erbjuder på Auberdines bryggor.",kw={"auberdine","darkshore","encrusted tide crawlers","fine crab chunks","fruit of the sea","gubber blump","reef crawlers"},ang={["faction:Alliance"]="Auberdine är en viktig landstigningsplats för Alliance-utforskare som anländer till Kalimdor och erbjuder små tjänster, som att hjälpa lokala fiskare att komma till rätta.",["profession:Cooking"]="Gubbers entusiastiska genomgång av krabbrecept kan inspirera alla kockar som vill få ut så mycket som möjligt av den lokala fångsten längs kusten.",["race:Dwarf"]="Att höra en främling i norra Kalimdor drömma om att laga en ”Ironforge surprise crab” är en fin påminnelse om hemmet för resande bergsklättrare från Khaz Modan."},sec={{t="En passion för kräftdjur",b="Gubber Blump fiskar från Auberdines långa träbryggor och hyser en närmast besatt kärlek till krabbkött. Han ser krabbor som havets verkliga skatt och drömmer om en ändlös samling recept, från ugnsbakade, grillade och kokta rätter till lokala specialiteter som whipper root crab och Ironforge surprise crab."},{t="Längs tidvattenpölarna",b="Eftersom Gubber inte kan slita sig från sitt fiskespö förlitar han sig på äventyrare som passerar för att samla ingredienser längs Darkshores dimhöljda stränder. Kusten myllrar av reef crawlers och encrusted tide crawlers som kilar omkring bland vågorna. De är en lättillgänglig, om än ibland nypglad, källa till kött för en blivande kustkock."}},faq={{q="Vem ger uppdraget Fruit of the Sea?",a="Uppdraget ges av Gubber Blump, en Alliance-fiskare som håller till på bryggorna i Auberdine i Darkshore.",al={"uppdragsgivare för fruit of the sea","vem ger fruit of the sea","gubber blump uppdrag"}},{q="Vilka varelser släpper Fine Crab Chunks?",a="Fine Crab Chunks fås från reef crawlers och encrusted tide crawlers som finns längs stränderna och i det grunda vattnet vid Darkshores kust.",al={"var får man fine crab chunks","vad släpper krabbchunks","vilka krabbor släpper fine crab chunks"}},{q="Varför samlar inte Gubber in krabbköttet själv?",a="Gubber är helt upptagen med att fiska från bryggorna i Auberdine och kan inte lämna sin lina för att jaga krabbor som kryper längs stranden.",al={"varför skaffar inte gubber egen krabba","varför behöver gubber hjälp"}},{q="Vilka rätter vill Gubber laga?",a="Gubber skryter om en enorm mängd tillagningssätt, bland annat krabb­sallad, soppa, gryta, pepparkrabba, citronkrabba, whipper root crab och ett regionalt recept som han kallar Ironforge surprise crab.",al={"gubbers krabbrecept","vilka recept nämner gubber","krabbrätter"}},{q="Anspelar Gubber Blumps tal på något?",a="Ja. Hans monolog där han räknar upp alla tänkbara sätt att tillaga krabba är en tydlig hyllning till Benjamin Buford ”Bubba” Blue från filmen Forrest Gump, som berömt höll ett liknande tal om räkor.",al={"gubber blumps popkulturreferens","forrest gump bubba-referens"}},{q="Var utspelar sig det här uppdraget?",a="Uppdraget börjar och avslutas i hamnbyn Auberdine, medan jakten sker längs Darkshores stränder i norra Kalimdor.",al={"var finns fruit of the sea","vilken zon finns fruit of the sea i"}}},fx={cf4b2535={q="Vad ska Fine Crab Chunks användas till?",a="Gubber Blump tänker använda dem i en oändlig mängd maträtter. För honom är krabbor havets frukt, perfekta att baka, grilla, koka, steka och blanda ner i soppor, grytor och sallader.",al={"vad fine crab chunks används till","varför fine crab chunks","vad gör gubber med krabbitarna"}},["82492fa1"]={q="Vad är krabborna längs Darkshores kust?",a="Reef crawlers och encrusted tide crawlers är inhemska kräftdjur som letar föda längs Darkshores långa, dimmiga kustlinjer och i de grunda tidvattenspoolerna. De är farliga för oförsiktiga strandvandrare, men deras kött uppskattas av fiskare och kockar som Gubber Blump, som lagar mustiga kustmåltider.",al={"vad är reef crawlers","encrusted tide crawlers i darkshore","krabbor i darkshore"}}},fp="16,137,25.231.0,21.253.0,37.80.0,41.107.0,48.99.0,37.134.0,47.150.0,33.115.0"}
P.entries["quest:114"] = {n="The Escape",s="Maybell Maclure väntar på ett sätt att smita undan sin familj och träffa Tommy Joe Stonefield. Du hämtar William Pestles Invisibility Liquor, bryggd av kristallkelp från trakten.",h="Maybell Maclure väntar på ett sätt att smita undan sin familj och träffa Tommy Joe Stonefield.",kw={"elwynn forest","invisibility liquor","the maclure vineyards","maybell maclure","the stonefield farm","the escape","tommy joe stonefield","william pestle"},ang={["faction:Alliance"]="Som Alliance-äventyrare med start i Elwynn Forest får du en lättsam paus från striderna mot Defias-banditer och gnoller när du hjälper Tommy Joe och Maybell. Lantliga agg lever kvar även nära Stormwind.",["race:Human"]="Som människa i Elwynn vet du att envisa familjegräl går djupt, och att små, hemliga hjälpsamma handlingar mellan grannar kan bidra till att bevara freden."},sec={{t="En brygd för äkta kärlek",b="Familjerna Maclure och Stonefield har varit osams i generationer, så det finns inget utrymme för uppvaktning. Gramma Stonefield vänder sig till William Pestle, en alkemist på Lion's Pride Inn i Goldshire. Med kristallkelp från sjöarna i närheten brygger Pestle Invisibility Liquor som är stark nog att dölja Maybells flykt från Maclures gård."},{t="Försvunnen i skogen",b="Maybell Maclure tar flaskan och smiter bland träden mot Tommy Joe. Hon plågas av skuldkänslor över att lura sin familj, men hennes hängivenhet väger tyngre än rädslan för att bli upptäckt. Hon dricker brygden och försvinner inför dina ögon, vilket ger henne några ögonblick med Tommy Joe utom synhåll för deras fientliga släktingar."}},faq={{q="Vem ger uppdraget The Escape?",a="William Pestle, apotekaren och alkemistassistenten på Goldshires Lion's Pride Inn, ger dig Invisibility Liquor när du har hämtat kristallkelp åt honom.",al={"uppdragsgivare the escape","vem startar the escape","var hämtar man the escape"}},{q="Vad används Invisibility Liquor till?",a="Invisibility Liquor gör Maybell Maclure osynlig tillräckligt länge för att lämna familjens gård och besöka Tommy Joe Stonefield utan att reta upp sina släktingar.",al={"varför invisibility liquor","vad gör drycken","invisibility liquor syfte"}},{q="Varför måste Maybell och Tommy Joe dölja sitt förhållande?",a="Familjerna Maclure och Stonefield är bittra rivaler, och deras djupa fiendskap förbjuder deras barn att öppet uppvakta varandra.",al={"varför gömmer de sig","stonefield maclure-fejden","varför kan maybell och tommy joe inte vara tillsammans"}},{q="Vad händer när du lämnar drycken till Maybell?",a="Maybell tackar dig, kluven mellan skuldkänslor och förväntan, och dricker sedan brygden. Hon försvinner inför dina ögon för att smita iväg mot Tommy Joe.",al={"vad händer i slutet","försvinner maybell","slutföra uppdraget the escape"}},{q="Vilket uppdrag leder direkt till The Escape?",a="The Escape följer på Collecting Kelp, där du samlar kristallkelp från murlocer vid Crystal Lake åt William Pestle, så att han kan brygga osynlighetsdrycken.",al={"förutsättning för the escape","uppdraget före the escape","vad leder fram till the escape"}},{q="Löser uppdraget konflikten mellan familjerna?",a="Nej. Drycken ger de älskande bara ett kort, hemligt möte. Fiendskapen mellan Gramma Stonefield och familjen Maclure förblir bitter och olöst.",al={"blir familjerna sams","är fejden över","tar fejden slut"}}},fx={["245b9158"]={q="Varför hjälper William Pestle Tommy Joe och Maybell?",a="William Pestle är apotekare och vill gärna hjälpa ung kärlek. Efter att Gramma Stonefield skickat honom en lapp och bett om ett sätt att kringgå den bittra fejden mellan familjerna Stonefield och Maclure gick William med på att brygga en sats Invisibility Liquor, så snart han fick tag på crystal kelp. Han har inget personligt att vinna, utöver att hjälpa de två olyckligt kära att träffas i hemlighet utan att utlösa ännu ett slagsmål mellan deras fientliga släkter.",al={"varför hjälper william","william pestles motiv","varför hjälpa maybell att fly"}},["53ceb805"]={q="Varför ber William Pestle dig leverera drycken i stället för att göra det själv?",a="William driver sin livliga butik i Lion's Pride Inn i Goldshire och kan inte så lätt lämna sitt arbete för att uträtta ärenden genom skogen. Än viktigare är att om han själv vandrade in på Maclure-familjens vingård med misstänkta alkemiska brygder skulle Maybells beskyddande släktingar genast bli misstänksamma. Du är en kringvandrande äventyrare som redan har agerat kurir mellan de älskande och samlat in ingredienserna, så du kan smyga obemärkt in på gården och överlämna drycken till henne.",al={"varför skickar william dig","varför levererar jag invisibility liquor","varför kan inte william leverera drycken"}}},fp="10,183,26.338.0,24.305.1,31.151.0,41.162.0,61.129.0,52.139.1,42.147.0,54.144.1"}
P.entries["quest:1140"] = {n="The Tower of Althalaxx",s="Det här uppdraget är det sjätte kapitlet i korståget mot kultisterna i Tower of Althalaxx, som leds av Delgren the Purifier från Maestra's Post. Delgren tyder orciska skrifter som återfanns hos kultens sändebud och avslöjar att häxmästaren Athrikus Narassin gömt två fångade Highborne-själsädelstenar i demoniska satyrfästen djupt inne i Ashenvale. Mästarna skickas till Night Run och Satyrnaar för att krossa kärlen, befria de plågade uråldriga andarna och slå ut Athrikus mörka kraftkälla.",h="Det här uppdraget är det sjätte kapitlet i korståget mot kultisterna i Tower of Althalaxx, som leds av...",kw={"althalaxx","ashenvale","athrikus","delgren","highborne","maestra's post","night run","satyrnaar","själsädelstenar"},ang={["class:Paladin"]="Delgren the Purifier visar en pragmatisk sida av den helige korsfararen: han använder sina fienders språk för att avslöja demonisk korruption och rena de plågade döda.",["class:Priest"]="När fängelsecirklarna krossas får plågade andar, som lidit i århundraden av demonisk tortyr, äntligen ro.",["race:NightElf"]="Att befria Highborne-förfäder från satyrernas vanhelgande är en högtidlig plikt som konfronterar ditt folks forntida och tragiska förflutna."},sec={{t="Att tyda klottret",b="Efter att ha fällt den orciska kuriren Ilkrud Magthrull får Delgren the Purifier nytta av sina omstridda studier av orcernas språk. Medan hans jämlikar inom Holy Light ofta hånade honom för att lära sig sina fienders språk, hjälper Delgrens pragmatiska insikt honom att nysta upp kultens hemliga handel. Anteckningarna avslöjar att Athrikus Narassin säkrat två kraftfulla själsädelstenar med uråldriga Highbornes väsen och gömt dem långt åt nordost, i de vanhelgade lundarna i Night Run och Satyrnaar."},{t="Oheliga allianser",b="Att Highborne-själsädelstenar finns i satyrläger avslöjar en vidrig sammansmältning mellan Athrikus mörka kabal och Burning Legions demoniska avkomma. Dessa uråldriga andar, bundna ovanför rituella fängelsecirklar, plågas utan uppehåll för att driva mörk magi. Att ge sig in bland satyrernas bloddränkta altaren innebär att möta både vild demonisk korruption och de dolda satyrernas lurande dolkar, svurna att vakta dessa magiska kanaler."},{t="Att försvaga Athrikus",b="När äventyrarna krossar de karmosinröda stenarna och befriar Highborne-själarna från deras plågor skänker de Athrikus kraftförråd ett förödande slag. Delgren noterar att Althalaxx-kultens ledare är kraftigt försvagad nu när dessa själsädelstenar förstörts. Dådet lämnar också den helige korsfararen illa till mods över nattalvernas tysta oro för satyrerna, och han beslutar sig för att uppmärksamma ledarna i Auberdine på den kvardröjande demoniska smittan."}},faq={{q="Varför kan Delgren läsa orciska?",a="Delgren tog initiativ till att studera orcernas språk, trots att andra i hans heliga orden hånade honom. Han anser att förståelse för en fiendes språk är avgörande för att få taktiska insikter, vilket direkt låter honom översätta de återfunna anteckningarna från Ilkrud Magthrull.",al={"delgren läser orciska","hur kan delgren orciska","delgrens översättning"}},{q="Vad är själsädelstenarna, och varför har satyrerna dem?",a="Själsädelstenarna är karmosinröda fokusstenar som binder Highborne-alvernas uråldriga andar ovanför rituella fängelsecirklar. Athrikus Narassin förhandlade till sig dem eller placerade dem i satyrhelgedomar som Night Run och Satyrnaar, där han drar kraft ur andarnas lidande för att stärka kultens magi.",al={"althalaxx själsädelstenar","varför har satyrer ädelstenarna","fångade highborne-själar"}},{q="Var ligger Night Run och Satyrnaar?",a="Båda platserna är demoniska satyrfästen bland de skogsklädda höjderna i nordöstra Ashenvale, öster om Maestra's Post.",al={"var ligger night run","var ligger satyrnaar","satyrernas lägerplatser"}},{q="Varför är nattalverna ovilliga att prata om satyrerna?",a="Delgren märker att hans alvvärdar undviker att prata om satyrerna eftersom varelserna en gång själva var nattalver. Satyrerna förvandlades till bockbenta vidunder under det uråldriga De äldstes krig, efter att ha fallit för demonisk korruption. Därför är de än i dag en källa till sorg och skam för Kaldorei.",al={"varför hemlighetsfulla om satyrer","nattalvernas koppling till satyrer","satyrernas alviska historia"}},{q="Hur hjälper det att befria själarna till att stoppa Tower of Althalaxx-kulten?",a="Athrikus Narassin förlitar sig i hög grad på den stulna andliga energi som finns i Highborne-själsädelstenarna. När de svävande ädelstenarna krossas och de fångade spökena släpps fria, berövas hans ritualer sin kraft och han blir sårbar för ett direkt angrepp mot tornet.",al={"varför krossa själsädelstenarna","athrikus kraftkälla","försvaga athrikus"}},{q="Vem är Elissa som Delgren nämner att han ska tala med?",a="Elissa Starbreeze är en framstående nattalvssentinel stationerad i Auberdine, där hon samordnar det lokala försvaret i Darkshore. Delgren planerar att rådgöra med henne om den djupt rotade satyrinvasionen som hotar norra Kalimdor.",al={"elissa auberdine","vem är elissa","delgren elissa"}}},fx={["866ee2a4"]={q="Vem skickas du för att bekämpa så att Highborne-själarna blir fria?",a="Du skickas djupt in i de fördärvade ruinerna av Night Run och Satyrnaar för att bekämpa satyrerna som håller själsädelstenarna. Dessa demoniska tjänare åt Burning Legion har slutit sig samman med Athrikus Narassin och hans mörka kult. De håller de forntida Highborne-själarna fångna i svävande röda ädelstenar ovanför sina mörka fångkretsar.",al={"vem slåss du mot","vem vaktar själsädelstenarna","satyrer i night run och satyrnaar"}},["706f1be3"]={q="Varför skickar Delgren the Purifier dig i stället för att gå själv?",a="Delgren the Purifier är stationerad vid Maestra's Post, där han samordnar försvaret och underrättelsearbetet mot kultister och demoniska intrång över gränsen. Att infiltrera befästa satyrfästen som Night Run och Satyrnaar kräver en erfaren äventyrare som kan smyga förbi fiendens linjer och krossa ädelstenarna utan att dra bort en hel garnison från utposten.",al={"varför behöver delgren mig","varför kan delgren inte gå själv","varför skicka en äventyrare"}}},fp="22,403,27.448.0,16.373.1,18.420.1,41.231.0,54.271.0,42.115.0,59.276.0,67.231.0,48.215.0"}
P.entries["quest:1141"] = {n="The Family and the Fishing Pole",s="Gubber Blump, en dvärg som bor vid Auberdines bryggor, behöver hjälp med att fånga Darkshores inhemska groupers. Fientliga murlocs stryker längs kusten och har lamslagit stadens små fiskebåtar. Gubber är strandsatt och erbjuder ett arvegods i form av ett fiskespö till den som vill kasta ut sin lina.",h="Gubber Blump, en dvärg som bor vid Auberdines bryggor, behöver hjälp med att fånga Darkshores inhemska...",kw={"auberdine","blump family fishing pole","darkshore grouper","fiske","graun blump","gubber blump","murloc","veiled sea"},ang={["faction:Alliance"]="Auberdine är en viktig hamn för Alliansen på Kalimdor, där fastlandets folk och Night Elves samarbetar dagligen mot hot från kusten, som murlocs.",["profession:Cooking"]="Darkshore Grouper är en stadig och näringsrik fångst längs norra Kalimdors kust och en basingrediens i måltider vid gränslägrets lägereldar.",["race:Dwarf"]="Att träffa en annan dvärg som brinner för fiske i stället för smide under jord eller bryggning är en udda påminnelse om att ditt folk ägnar sig åt många olika saker."},sec={{t="En dvärg långt från Ironforge",b="Gubber Blump är mycket stolt över sin släkt och säger att namnet Blump länge har varit synonymt med konsten att meta. Night elves bor i större delen av Auberdine, men dvärgar och gnomer har slagit sig ner vid bryggorna och den livliga hamnen. I stället för att gräva i sten tillbringar Gubber dagarna med att blicka ut över Veiled Seas dimmiga vatten, ivrig att dra upp traktens fångst."},{t="Murlocinvasioner och Darkshore Grouper",b="Darkshore Grouper är en uppskattad kustfisk, användbar i matlagning och berömt livlig på kroken. Vanligtvis skulle lokala fiskare ro små båtar ut på djupare vatten för att fånga dem. Men de aggressiva murlocernas ankomst till kusten har stoppat all civil båttrafik. Gubber fruktar att varelserna äter upp alla lokala fiskbestånd och rekryterar därför resenärer som kan meta från stranden."},{t="Blump-arvet",b="Som belöning till dem som kommer med en rejäl fångst ger Gubber bort ett Blump Family Fishing Pole. Enligt honom kan alla som lyckas dra upp ett gäng livliga groupers mäta sig med sin släkts legendariska fiskare, däribland den skäggiga och starkt luktande kusinen Graun Blump. För en dvärg med hans excentriska smak är det yttersta tecknet på respekt att lämna ifrån sig ett familjespö."}},faq={{q="Vem är Gubber Blump?",a="Gubber Blump är en dvärgfiskare vid bryggorna i Auberdine i Darkshore. Han kommer från en stolt fiskarsläkt, lär ut grundläggande fisketekniker och för vidare familjens signaturspön till lovande fiskare.",al={"vem är gubber","gubber blump historia","dvärgfiskare i auberdine"}},{q="Varför ger sig inga båtar ut från Auberdine för att fiska?",a="Fientliga murlocs har tagit över stora delar av Darkshores kust. Deras aggressiva närvaro gör det alldeles för farligt att sjösätta små privata fiskebåtar, så de lokala fiskarna hålls kvar vid bryggorna och i de grunda vattnen.",al={"varför inga båtar","fiskebåtar i darkshore","båtproblem i auberdine"}},{q="Vad är en Darkshore Grouper?",a="Det är en inhemsk saltvattenfisk som finns utanför Darkshores dimmiga kust. Fiskare uppskattar grouper både för utmaningen i att fånga en och för att den passar i många mustiga kustrecept.",al={"darkshore grouper","grouper i darkshore"}},{q="Vem är Graun Blump?",a="Graun är Gubber Blumps kusin. Enligt Gubber har hon helskägg, luktar ganska starkt och hör till de främsta fiskare deras släkt någonsin har fått fram.",al={"graun blump","gubbers kusin"}},{q="Varför finns det dvärgar i en Night Elf-stad som Auberdine?",a="Efter Tredje kriget och Alliansens bildande reste dvärgar från Ironforge och gnomer över havet till Kalimdor för att handla, skapa sjöförbindelser och hjälpa sina nya Night Elf-allierade med hamninfrastruktur.",al={"varför dvärgar i auberdine","dvärgar i darkshore"}},{q="Vad är Blump Family Fishing Pole?",a="Det är ett tåligt fiskespö som Blump-klanen har tillverkat och använt. Gubber ger dessa värdefulla spön till resenärer som visar prov på verklig fiskeskicklighet i Darkshores vatten.",al={"blumps fiskespö","blump-familjens spö","gubbers belöningsspö"}}},fx={["27b30f0f"]={q="Varför vill Gubber Blump ha Darkshore Grouper?",a="Gubber kommer från en stolt släkt av dvärgfiskare och älskar verkligen hantverket. Vanligtvis seglar han ut på bukten för att fånga Darkshore Grouper, men de aggressiva murlocernas ankomst har stoppat all båttrafik. Gubber oroar sig för att murlocerna frossar i det lokala fiskbeståndet. Han vill därför gärna få tag på grouper och se ännu en lovande fiskare föra goda fisketraditioner vidare.",al={"gubber blumps motiv","varför vill gubber ha fisk","varför fånga grouper"}},["60ad423d"]={q="Vad används Darkshore Grouper till?",a="Darkshore Grouper är goda att äta och kan tillagas på flera olika lokala sätt. Gubber medger att de passar till många läckra rätter, men själv bryr han sig mycket mer om spänningen i att få napp och dra in fisken än om att äta den.",al={"vad används darkshore grouper till","användning av darkshore grouper","syftet med grouper"}}},fp="31,209,26.299.0,41.356.0,16.289.0,20.210.0,50.162.0,28.156.0,19.155.0,57.221.0,38.170.0"}
P.entries["quest:1142"] = {n="Mortality Wanes",s="Djupt inne bland de fientliga törnena i Razorfen Kraul viskar en döende Night Elf vid namn Heralath Fallowbrook sin sista bön till förbipasserande Alliance-äventyrare. Berövad sin styrka och sitt liv ber han bara att hans hustrus stulna kärlekspant återfinns och förs hem till Darnassus tillsammans med beskedet om hans död.",h="Djupt inne bland de fientliga törnena i Razorfen Kraul viskar en döende Night Elf vid namn Heralath...",kw={"darnassus","falfindel","heralath fallowbrook","lonebrow","dödligheten avtar","kärlekspant","razorfen kraul","treshala fallowbrook"},ang={["faction:Alliance"]="För Alliance-mästare som beger sig in i hjärtat av det Horde-dominerade The Barrens är det en allvarsam hedersplikt att föra Heralaths sista minne hem till Darnassus.",["race:Dwarf"]="Heralaths döende ord hedrar dvärgen Lonebrows mod. Han riskerade livet för att föra en brådskande varning bort från quilboar-fästet.",["race:NightElf"]="Night Elves känner ett djupt personligt styng när en av deras egna dör ensam och bortglömd bland de barbariska tistlarna i södra The Barrens."},sec={{t="Ett sista andetag bland törnena",b="Razorfen Kraul är ett farligt fäste som översvämmats av vilda quilboar och mörk magi, långt från Alliance territorium. Bland dessa förrädiska snår ligger Heralath Fallowbrook, dödligt sårad och snabbt döende. Med sina sista krafter lyckas han bara få fram några osammanhängande viskningar och berättar att en modig dvärg vid namn Lonebrow skickades i förväg för att varna Falfindel. Heralath vet dock att han aldrig kommer att lämna Kraul vid liv."},{t="Kärlekspantet",b="Innan han ger vika för sina sår håller Heralath fast vid en sista önskan: att få tillbaka en symbol för sitt äktenskap. Ett hängsmycke som symboliserar hans eviga band till hustrun Treshala slets från honom av en av hålans vidriga angripare. Han ber varje resenär som stannar vid hans sida att återfinna hängsmycket och bära det hela vägen över Kalimdor till Darnassus, så att Treshala får veta sanningen om hans ensamma död i stället för att vänta förgäves."},{t="Sorg i Darnassus",b="När Treshala Fallowbrook får det återfunna arvegodset i Darnassus blir hon förkrossad över bekräftelsen på sin makes död. Ställd inför världens hårda grymhet lovar hon att Heralaths arbete inte ska gå under med honom. Ensam kvar att sörja tar hon på sig tyngden av hans arv samtidigt som hon kämpar med sin plötsliga sorg."}},faq={{q="Vem är Heralath Fallowbrook?",a="Heralath Fallowbrook är en Night Elf i Alliance som hittas dödligt sårad i Razorfen Kraul. Han är snabbt på väg att dö av sina skador och anförtror förbipasserande äventyrare uppgiften att återfinna sin hustrus stulna kärlekspant och föra beskedet om hans död till Darnassus.",al={"heralath fallowbrook","vem är heralath","döende elf razorfen"}},{q="Var finns Heralath Fallowbrook?",a="Heralath finns inne i Razorfen Kraul, quilboar-fästet fullt av törnen i södra delen av The Barrens.",al={"heralaths plats","var finns heralath","var hittar man heralath"}},{q="Vem var Lonebrow?",a="Lonebrow är en modig dvärg som Heralath nämner i sina sista stunder. Tydligen skickades Lonebrow på ett brådskande uppdrag ut ur snåren för att varna Falfindel om farorna som växer i Kraul.",al={"dvärgen lonebrow","vem är lonebrow","lonebrows varning"}},{q="Vem är Treshala Fallowbrook?",a="Treshala är Heralaths hustru och bor i Night Elf-huvudstaden Darnassus. Hon tar emot det återfunna hängsmycket och måste bära beskedet om sin makes tragiska död.",al={"treshala fallowbrook","vem är treshala","heralaths hustru"}},{q="Vad är kärlekspantet?",a="Kärlekspantet är ett kärt minne som symboliserar äktenskapet mellan Heralath och Treshala Fallowbrook. Det stals från Heralath av quilboar-angriparna i Razorfen Kraul innan han dog.",al={"treshalas hängsmycke","vad är hängsmycket","kärlekspant"}},{q="Hur reagerar Treshala på beskedet?",a="Treshala är förkrossad av tragedin och sörjer världens grymhet. Trots sin djupa sorg beslutar hon att Heralaths arbete måste fortsätta genom henne och ber att få sörja ensam.",al={"treshalas reaktion","vad händer när man lämnar över hängsmycket"}}},fx={aa8861aa={q="Varför vill Heralath Fallowbrook att det här blir gjort?",a="Heralath vet att han håller på att dö djupt inne bland de fientliga törnena i Razorfen Kraul. Hans sista önskan i livet gäller inte hans egen överlevnad. Han vill att hans älskade hustru Treshala får veta vad som hänt honom och får det dyrbara förlovningshänget som quilboar stal från honom innan han drar sitt sista andetag.",al={"varför hjälpa heralath","heralath fallowbrooks motiv","varför skicka hänget"}},["170253dc"]={q="Varför kan Heralath Fallowbrook inte hämta hänget själv?",a="Heralath är dödligt sårad och försvagas snabbt, helt hjälplös bland Krauls våldsamma quilboar. Han har knappt styrka nog att viska sin sista vädjan och kan inte försvara sig mot angriparna eller på egen hand överleva färden hem till Darnassus.",al={"varför behöver heralath mig","varför kan inte heralath göra det","varför jag för mortality wanes"}}},fp="15,171,28.357.0,22.286.0,18.245.1,28.236.0,38.110.0,17.165.0,28.133.0,31.179.0,36.168.1"}
P.entries["quest:1143"] = {n="The Tower of Althalaxx",s="Det här uppdraget går ut på att anfalla Athrikus Narassin, den uråldriga mörkertrollkarlen som håller till högst upp i Tower of Althalaxx. Under Balthule Shadowstrikes ledning måste en agent för Alliansen tränga in i den förstörda borgen och döda kultens ledare. Att undanröja Athrikus blir ett förödande slag mot den demoniska dyrkan som fördärvar norra Darkshore.",h="Det här uppdraget går ut på att anfalla Athrikus Narassin, den uråldriga mörkertrollkarlen som håller till...",kw={"althalaxx","athrikus","balthule","darkshore","demonisk","narassin","shadowstrike","häxmästare"},ang={["class:Warlock"]="Athrikus utövar mäktig demonisk magi från toppen av Althalaxx och visar på ett dödligt sätt hur tygellös dyrkan av ondskefull magi drar till sig livsfarlig uppmärksamhet.",["faction:Alliance"]="Det är livsviktigt att skydda norra Darkshore från demoniska kulter för att säkra Alliansens färdvägar mellan Auberdine och länderna bortom.",["race:NightElf"]="Mötet med Athrikus Narassin påminner bittert om den arkana och demoniska korruption som en gång ödelade nattalvernas civilisation."},sec={{t="Stormningen av toppen",b="Tower of Althalaxx reser sig bland ruinerna på norra Darkshores höjder och har blivit ett vidrigt centrum för demoniska åkallanden. Balthule Shadowstrike, som bevakar ruinen från en plats i närheten, inser att det är bråttom att agera. Högst upp i tornet finns Athrikus Narassin, en uråldrig och mäktig nattalvisk häxmästare som styr de mörka ritualerna under det sönderslagna stentaket."},{t="Ett avgörande slag",b="Athrikus omger sig med lojala häxmästare och mörk magi som är långt dödligare än kultisterna som patrullerar sluttningarna nedanför. För att fälla kultens ledare måste du ta dig igenom hans innersta krets och säkra hans avhuggna huvud som bevis. Balthule påpekar att de demoniska krafterna kanske försöker samla sig på nytt en dag, men Athrikus död berövar kulten dess ledande intellekt och ger Darkshore ett välbehövligt andrum."}},faq={{q="Vem är Athrikus Narassin?",a="Athrikus Narassin är en uråldrig nattalvisk häxmästare som leder kultisterna vid Tower of Althalaxx. Han styr de mörka åkallandena och demoniska riterna som har tagit över ruinerna i norra Darkshore.",al={"athrikus","vem är athrikus","ledare för althalaxx"}},{q="Var hittar du Athrikus Narassin?",a="Athrikus håller till allra högst upp i Tower of Althalaxx, där han vaktas av en grupp erfarna häxmästare och åkallade tjänare.",al={"var finns athrikus","athrikus plats","toppen av althalaxx"}},{q="Vem ger uppdraget?",a="Balthule Shadowstrike, en spejare för Alliansen som slagit läger nära foten av Tower of Althalaxx, ger dig uppdraget att döda Athrikus.",al={"uppdragsgivare","balthule","balthule shadowstrike"}},{q="Vem är Delgren som nämns i uppdraget?",a="Delgren the Purifier är en allierad i Alliansen som är stationerad i närheten. Han skickade dig för att samordna med Balthule och utplåna den demoniska kulten.",al={"delgren","delgren the purifier"}},{q="Vad händer när Athrikus besegrats?",a="Balthule bekräftar att Athrikus död blir ett hårt slag mot de demoniska aktiviteterna i området, men varnar för att de mörka krafterna så småningom kommer att samla sig igen.",al={"efter athrikus","slutet på tower of althalaxx"}},{q="Varför är Tower of Althalaxx farligt för Darkshore?",a="Kultisterna och häxmästarna i tornet utövar ondskefull magi och åkallar demoner i nattalvernas länder. De hotar vildmarken och bosättningarna i närheten.",al={"varför rensa tornet","hotet från althalaxx"}}},fx={["95b2d6f7"]={q="Varför vill Balthule Shadowstrike att Athrikus Narassin dödas?",a="Balthule Shadowstrike vet att Athrikus Narassin leder kabalen av kultister och häxmästare som ockuperar det förfallna Tower of Althalaxx. Genom att slå direkt mot Athrikus högst uppe i tornet hoppas Balthule kunna krossa deras ledarskap och driva tillbaka de demoniska styrkorna som tränger in över norra Darkshore, innan deras fördärvade riter sprider sig vidare.",al={"varför döda athrikus","balthules motiv","varför gav balthule uppdraget"}},["6015f725"]={q="Vad ska Athrikus Narassin's Head användas till?",a="Athrikus Narassin's Head är ett obestridligt bevis på att den forntida häxmästaren verkligen har dödats. När du för tillbaka huvudet till Balthule Shadowstrike kan han och hans allierade vara säkra på att tornets mörke herre inte längre kan leda sina anhängare eller kalla fram demoniska styrkor till Darkshore.",al={"användning av athrikus narassin's head","varför ta med athrikus huvud","athrikus huvud som uppdragsföremål"}},["9e544083"]={q="Varför skickar Balthule dig för att möta Athrikus i stället för att gå själv?",a="Athrikus håller till allra högst upp i tornet, omgiven av sina farligaste häxmästare. Balthule överväger att invänta förstärkningar från Delgren the Purifier, men Delgren litade fullständigt på din bevisade stridsförmåga när han skickade dit dig från början. Du är deras bästa chans att slå till snabbt innan kultisterna hinner förstärka sina styrkor.",al={"varför jag åt balthule","varför slåss inte balthule mot athrikus","varför skicka mig ensam"}}},fp="22,209,20.302.0,17.346.1,25.180.0,37.116.0,21.115.0,38.115.0,40.140.1,53.148.0"}
P.entries["quest:1147"] = {n="The Swarm Grows",s="Moktar Krin i Ironstone Camp säger att Belgrom vill driva tillbaka silithiderna till djupen de kröp upp ur. Moktars egen halvdöda krigarskara klarar inte av det, så Moktar ber dig ta dig an silithiderna vid utgrävningen i söder.",h="Moktar Krin i Ironstone Camp säger att Belgrom vill driva tillbaka silithiderna till djupen de kröp upp ur.",kw={"belgrom","explorers' league","ironstone camp","moktar krin","the rustmaul dig site","the shimmering flats","silithider","thousand needles"},sec={{t="En halvdöd krigarskara",b="Efter The Swarm Grows (2) säger Moktar Krin att Belgrom ser silithiderna som ett hot och vill driva tillbaka dem till de djup de kom ifrån. Moktar har redan dödat dvärgarna som Explorers' League skickade, och hans krigarskara är nu i för dåligt skick för att strida igen. Han klarar inte av det utan hjälp. Utgrävningen ligger i söder, och Moktar räknar inte med att det finns fler dvärgar där. Silithiderna som ska dödas är sökare, kupdrönare och inkräktare. Moktars krigarskara kan inte ge sig av förrän det är gjort."},{t="Moktars tack",b="Moktar skämtar om att galla som täcker dig faktiskt gör dig snyggare, trots att du stinker av den. Moktar varnar dig för att hålla dig borta från kodoerna och säger att lukten ensam bevisar att du gjort din del mot silithiderna."}},faq={{q="Var finns silithidernas angrepp?",a="Vid The Rustmaul Dig Site, söder om Ironstone Camp.",al={"silithidernas plats","var finns insekterna","var ligger utgrävningen"}},{q="Varför kan Moktar Krins krigarskara inte själva ta hand om insekterna?",a="Moktars krigarskara är halvdöd efter att ha dödat dvärgarna som Explorers' League skickade. I det skicket kan den inte ge sig in i ännu ett slag.",al={"varför hjälpa moktar","varför är krigarskaran skadad","krigarskarans skick"}},{q="Vem vill driva tillbaka silithiderna?",a="Belgrom ser silithiderna som ett hot och vill driva tillbaka dem till djupen de kröp upp ur.",al={"vem vill döda silithiderna","belgroms order om silithiderna"}},{q="Vilka sorters silithider måste besegras?",a="Silithid Searchers, Silithid Hive Drones och Silithid Invaders, fem av varje.",al={"vilka silithider ska dödas","silithidmål"}},{q="Finns det fortfarande dvärgar vid utgrävningen?",a="Moktar säger att det inte borde finnas fler dvärgar att ta hand om där.",al={"finns det dvärgar vid rustmaul","explorers' league vid utgrävningen"}}},fp="15,230,21.486.0,15.216.1,42.50.0,60.141.0,35.107.0,40.77.0,40.63.0"}
P.entries["quest:1148"] = {n="Parts of the Swarm",s="När du vänder på ett sprucket silithidskal i Thousand Needles ser du att plattorna är så tätt sammanvävda att det är anmärkningsvärt starkt. Varelsen verkar kraftfull och högt utvecklad. Korran vid The Crossroads skulle nog vilja studera fler.",h="När du vänder på ett sprucket silithidskal i Thousand Needles ser du att plattorna är så tätt sammanvävda att...",kw={"skal","crossroads","field of giants","hjärta","korran","silithid","klor","thousand needles"},ang={["faction:Horde"]="Det här är ett ärende för Horden: proverna ska lämnas till Korran vid The Crossroads."},sec={{t="Ett märkligt skal",b="När du undersöker det närmare ser du att kitinet är vävt så tätt att du aldrig sett något liknande. Resten av kroppen vittnar om samma stora styrka och avancerade utveckling. Du tänker att Korran vid The Crossroads gärna skulle undersöka fler av dessa varelser för att lära sig mer om deras natur och ursprung. Proverna som behövs är ett silithidhjärta, fem silithidklor och tre intakta silithidskal."},{t="Prover åt Korran",b="Korran är nöjd och säger att dessa prover, tillsammans med äggen som hittats i Field of Giants, är en bra början på att förstå vad det är för slags varelser insekterna är och vad de söker."}},faq={{q="Vem vill ha dessa silithiddelar?",a="Korran vid The Crossroads, som gärna vill studera fler av dessa varelser.",al={"vem är korran","lämna in delar av svärmen","vem studerar silithiderna"}},{q="Var börjar det här?",a="Det börjar när du undersöker ett sprucket silithidskal i Thousand Needles.",al={"hur börjar man delar av svärmen","sprucket silithidskal som början","var hittar man skalet"}},{q="Vilka prover vill Korran ha?",a="Ett silithidhjärta, fem silithidklor och tre intakta silithidskal.",al={"vilka föremål behövs","lista över silithiddelar","vad ska jag samla in"}},{q="Varför vill Korran studera silithider?",a="Genom att studera fler kan man kanske förstå varelsernas natur och ursprung.",al={"varför studera silithider","vad lär sig korran"}}},fp="18,256,18.418.0,20.200.1,31.74.0,22.75.0,32.77.0,40.66.0"}
P.entries["quest:1149"] = {n="Test of Faith",s="Tronsprovet är en andlig rit som eremiten Dorn Plainstalker leder högt ovanför botten av Thousand Needles ravin. Det utmanar Hordens äventyrare att bevisa sin beslutsamhet genom att kliva från en ranglig träplanka ut i den öppna avgrunden nedanför.",h="Tronsprovet är en andlig rit som eremiten Dorn Plainstalker leder högt ovanför botten av Thousand Needles...",kw={"dorn plainstalker","horden","trosprånget","plankor","uthållighetsprovet","trons prov","thousand needles"},ang={["class:Priest"]="Präster som ägnar dagarna åt att stärka sin tro på högre makter utmanas att omsätta sina teoretiska övertygelser i konkret handling.",["faction:Horde"]="Prövningarna speglar de grundläggande värderingar som håller ihop den spirande Horden i Kalimdor: absolut övertygelse, motståndskraft i fientliga miljöer och orubblig vilja.",["race:Tauren"]="För Shu'halo är övergångsriter på Kalimdors heliga platser en uråldrig tradition, och Dorns prövning kräver en påtaglig demonstration av tillit till det osedda."},sec={{t="Ett mått på själen",b="Dorn Plainstalker bor på en avskild utsiktsplats med vy över Thousand Needles spiror, som vinden format, och begrundar de delar som utgör en levande varelse: sinne, kropp och själ. I stället för att förlita sig på enkla stamtraditioner anordnar Dorn egna prövningar för att mäta vad en äventyrare verkligen bär inom sig. Han menar att övertygelse kan ta många former, men att den viktigaste egenskapen helt enkelt är styrkan att tro så starkt på något att man riskerar livet för det."},{t="Språnget ut i tomheten",b="Prövningen är bedrägligt enkel. Förflyttad till den branta toppen av en av de väldiga stenpelarna ställer sig den prövade på väderbitna träplankor som svävar över tomma intet. För att klara prövningen måste man övervinna sin självbevarelsedrift och kliva ut i avgrunden utan någon konkret garanti för att överleva. De som hoppar får sitt fall hejdat av mystiska eller andliga krafter och förs tillbaka i säkerhet. De har visat att deras själ är härdad nog att möta framtida prövningar som ingen kan förutse."}},faq={{q="Vem är Dorn Plainstalker?",a="Dorn Plainstalker är en tauren-eremit som bor i ett avlägset läger vid klippkanten ovanför Thousand Needles. Han tjänar som andlig prövare och söker upp Hordens äventyrare för att testa de olika delarna av deras dödliga väsen: tro, uthållighet och styrka.",al={"dorn plainstalkers historia","vem ger trons prov","uppdragsgivare i thousand needles"}},{q="Dör jag om jag hoppar från plankan?",a="Nej. Fallet från stenpelaren ser helt klart dödligt ut, men prövningen är en handling av tillit. När du kliver från träplankorna fångar en magisk skyddsförtrollning dig mitt i fallet och teleporterar dig direkt tillbaka till Dorn Plainstalkers grotta, oskadd.",al={"dör jag om jag hoppar","kan fallskada döda mig i trons prov","är trons prov farligt"}},{q="Vad händer efter att jag klarat trons prov?",a="Att bevisa din tro är bara den första riten i Dorns serie av prövningar. När din själ bedöms vara mottaglig utmanar Dorn genast din fysiska uthållighet i uthållighetsprovet.",al={"vad kommer efter trons prov","trons prov uppdragskedja","dorn plainstalkers nästa uppdrag"}},{q="Varför säger Dorn att ett misslyckande innebär att inse Nederlandets väldighet?",a="Det är Dorns dystra filosofiska påminnelse om dödligheten. Enligt honom riskerar de som saknar den inre elden att helhjärtat anta utmaningen att förlora livet – och själen – i den oändliga tomheten bortom de levandes värld.",al={"betydelsen av nederlandets väldighet","dorn plainstalkers citat om nederlandet"}},{q="Kan äventyrare från Alliansen göra det här provet?",a="Nej. Dorn Plainstalker erbjuder bara sin visdom och andliga vägledning till hjältar som står på Hordens sida och färdas genom södra Kalimdors farliga raviner.",al={"är trons prov bara för horden","kan alliansen göra trons prov"}},{q="Var äger trons prov rum?",a="Prövningen börjar vid Dorns läger i ravinväggarna i Thousand Needles. Därifrån leder magin till den svindlande klippavsatsen på en avlägsen stenpelare som skjuter ut över ravinens botten.",al={"platsen för trons prov","var finns plankan i thousand needles"}}},fx={f9bf32d9={q="Varför prövar Dorn Plainstalker din tro?",a="Dorn Plainstalker tror att varje varelse formas av anden, kroppen och sinnet. Vissa egenskaper formas av kulturella traditioner, medan andra bara kan upptäckas djupt inom dig. Genom att ställa dessa prövningar vill Dorn mäta din inre styrka och förbereda din ande på svårigheter. Han kräver att du blint kastar dig ut i kanjonvindarna för att bevisa att du har tro och tillit utan någon garanti för att överleva. Då vet han att ditt sinne är öppet för de större utmaningarna som väntar.",al={"varför vill dorn ha det gjort","dorn plainstalkers motiv","varför prövning med troshopp"}}},fp="13,255,23.490.0,22.488.1,25.251.0,35.246.1,45.190.1,69.219.0,40.159.0,40.181.0"}
P.entries["quest:115"] = {n="Shadow Magic",s="Shadow Magic är ett desperat uppdrag från Marshal Marris för att störa de mörka konster som stärker Blackrocks invasion av Redridge. Blackrocks skuggmagiker har fört med sig demonbesmittade midnattsklot till slagfältet och använder mörka krafter som vapen mot Lakeshires hårt ansatta försvarare. Det är avgörande att säkra och förstöra dessa förbannade reliker för att hålla stadens försvarslinje.",h="Shadow Magic är ett desperat uppdrag från Marshal Marris för att störa de mörka konster som stärker...",kw={"blackrock-orcher","demonbesmittad","lakeshire","marshal marris","midnattsklot","redridge","skuggmagi","skuggmagiker"},ang={["class:Paladin"]="Att konfrontera skuggmagiker och säkra demonbesmittade reliker fullgör direkt den heliga plikten att rena den dödligas värld från demonisk förvanskning.",["class:Warlock"]="Midnattskloten visar att Blackrockklanens felrötter består och ger häxmästare en inblick i den råa demoniska kanalisering som orckiska trollkarlar brukar.",["faction:Alliance"]="Lakeshire står på randen till att bli överkört, med nästan inga förstärkningar från Stormwind. Att beröva Blackrockklanen deras mörka artilleri är avgörande för regionens överlevnad."},sec={{t="En ondskefull arsenal",b="Råstyrka har alltid varit Blackrockklanens kännetecken, men deras senaste intrång i Redridge Mountains innebär ett långt lömskare hot. Inkräktarna har förstärkt sina led med skuggmagiker som brukar mörka krafter. De förlitar sig inte enbart på trolldom, utan kanaliserar sina fel- och skuggkrafter genom demonbesmittade artefakter som kallas midnattsklot. Artefakterna har tillfogat den lokala stadsmilisen fruktansvärda förluster och tippat ett redan desperat krig ännu mer till inkräktarnas fördel."},{t="Bänd bort besmittelsen",b="Marshal Marris, som samordnar Lakeshires pressade försvar från stadens centrum, förstår att vanligt stål inte lätt kan besegra mörka reliker. Om Blackrock-orcherna får behålla sina midnattsklot riskerar Redridges östra gränser att falla helt. Genom att beordra äventyrare att döda skuggmagikerna och ta kloten vill Marris inte använda denna farliga magi, utan få de demoniska relikerna förstörda."}},faq={{q="Vad är midnattsklot?",a="Midnattsklot är demonbesmittade kanaler som bärs av Blackrocks skuggmagiker. De fokuserar mörk magi för att utdela förödande slag mot Redridges dödliga försvarare.",al={"midnattsklot","vad är ett midnattsklot","vad gör midnattsklot"}},{q="Varför vill Marshal Marris ha kloten?",a="Marshal Marris vill få bort kloten helt från slagfältet för att försvaga Blackrocks skuggmagikers offensiva kraft. Han tänker se till att de demoniska relikerna tas om hand på ett säkert sätt och förstörs.",al={"varför samla midnattsklot","marris klot","marris plan för kloten"}},{q="Vilka är Blackrocks skuggmagiker?",a="De är trollkarlar bland Blackrock-orcherna som utövar skuggmagi och felbesudlad magi. De bistår klanens råstyrkekrigare med magiskt artilleri och förbannelser.",al={"blackrocks skuggmagiker","vem använder skuggmagi","blackrocks trollkarlar"}},{q="Var hittar man skuggmagikerna?",a="Blackrocks skuggmagiker finns i läger och befästa ställningar tillhörande Blackrockklanen runtom i nordöstra Redridge Mountains.",al={"var finns skuggmagiker","skuggmagikerns plats","blackrocks skuggmagikerläger"}},{q="Kommer Lakeshire att studera eller använda kloten?",a="Nej. Marshal Marris anser att de är farliga och demonbesmittade, och säger bestämt att världen vore bättre utan dem. Hans tydliga mål är att de förstörs omedelbart.",al={"kommer lakeshire att använda kloten","kan alliansen använda kloten","är kloten användbara"}},{q="Varför förekommer demonisk magi i Redridge?",a="Blackrockklanen har länge umgåtts med mörka och felvarelser, ända sedan Gamla horden. Deras trollkarlar fortsätter att använda demoniska reliker och skuggmagi för att stärka sina erövringar.",al={"varför demoner i redridge","blackrocks demoniska besmittelse","fel i redridge"}}},fx={["809c126b"]={q="Varför behöver Marshal Marris en äventyrare i stället för sina egna vakter?",a="Lakeshires garnison är hårt pressad. Stormwind håller inne med förstärkningar, så Marshal Marris kan knappt samla tillräckligt många soldater för att försvara stadsbron och hålla vägarna fria från gnoller och orkernas spaningspatruller. För att infiltrera fiendens fästen och fälla Blackrock-skuggmagikerna krävs en självständig äventyrare som kan slå till bakom fiendens linjer, där stadsvakterna inte kan avvaras.",al={"varför jag för shadow magic","varför behöver marris mig","varför skickar de inte lakeshires vakter"}}},fp="12,253,18.351.0,20.340.0,23.158.0,40.183.0,36.161.0,34.106.0,37.152.0,43.184.0"}
P.entries["quest:1150"] = {n="Test of Endurance",s="Test of Endurance är den andra riten i en serie andliga prövningar som leds av Dorn Plainstalker i Thousand Needles. Efter att redan ha visat prov på mod i anden får hordens äventyrare i uppdrag att tänja sin fysiska uthållighet till det yttersta genom att infiltrera Roguefeather Den och locka fram den skoningslösa harpyledern Grenka Bloodscreech.",h="Test of Endurance är den andra riten i en serie andliga prövningar som leds av Dorn Plainstalker i Thousand...",kw={"dorn plainstalker","freewind post","grenka bloodscreech","roguefeather den","screeching canyon","test of endurance","thousand needles","the weathered nook"},ang={["faction:Horde"]="Dorn erbjuder dessa utmaningar till alla hordens raser. Han anser att unga krigare från varje stam måste härdas mot umbäranden innan de möter Kalimdors faror.",["race:Tauren"]="För taurenresenärer speglar Dorn Plainstalkers prövningar traditionella övergångsriter. De prövar om den invigdes fysiska uthållighet motsvarar Jordmoderns andliga vägledning."},sec={{t="Kroppen sätts på prov",b="Dorn Plainstalker, som bor i The Weathered Nook, tar på sig att härda unga krigare innan de ger sig ut i den större och hårdare världen. Den första riten visade att en resenär hade orubblig tro och nerver av stål. Den här prövningen sätter den fysiska styrkan på prov. Enligt Dorns filosofi kräver verklig beredskap harmoni mellan andlig hängivenhet, mental disciplin och den rena uthållighet som krävs för att överleva långvarig brutalitet."},{t="In i Roguefeather Den",b="Den utvalda platsen för prövningen är Roguefeather Den, en förrädisk grotta i Screeching Canyon väster om Freewind Post. Grottan kryllar av fientliga harpyor och utgör en stor fara för ensamma vandrare. För att klara prövningen måste utmanarna kämpa sig djupt in i det underjordiska nästet, sabotera harpyornas samlade förråd och uthärda flockens våldsamma motangrepp tills matriarken Grenka Bloodscreech själv ger sig in i striden."}},faq={{q="Vem ger Test of Endurance?",a="Uppdraget ges av Dorn Plainstalker, en äldre tauren som håller till vid The Weathered Nook på ravinens klippor i Thousand Needles.",al={"uppdragsgivare test of endurance","vem inleder test of endurance","dorn plainstalker uppdrag"}},{q="Var ligger Roguefeather Den?",a="Roguefeather Den ligger högt uppe längs Thousand Needles södra ravinväggar, väster om Freewind Post. Resenärer måste följa en slingrande stig upp genom Screeching Canyon för att nå rampen till grottans ingång.",al={"roguefeather den plats","var ligger harpygrottan","rampen i screeching canyon"}},{q="Hur framkallar man Grenka Bloodscreech?",a="Grenka Bloodscreech dyker upp när du har kämpat dig till de innersta kamrarna i Roguefeather Den och vandaliserat mat- och förrådsförrådet som harpyorna har samlat där. Då provocerar du henne att försvara sitt näste.",al={"framkalla grenka","hur får man grenka bloodscreech att dyka upp","hitta grenka"}},{q="Vad kommer efter Test of Endurance?",a="När du återlämnar Grenkas avhuggna klo till Dorn Plainstalker har du bevisat din fysiska uthållighet. Då skickar han dig vidare på nästa utmaning i sin serie: Test of Strength.",al={"nästa uppdrag efter endurance","vad följer efter test of endurance","dorn plainstalker nästa prövning"}},{q="Varför prövar Dorn äventyrare som inte är taurer?",a="Dorn anser att det är hans uppgift att vägleda alla unga i Horden, oavsett ras eller stam. Han ser oprövad stolthet som en dödsdom i den större världen och kräver att varje krigare visar sig redo till kropp, sinne och ande.",al={"varför hjälper dorn horden","dorn plainstalkers filosofi","taurenprövningar för andra raser"}},{q="Vilken prövning kom före den här?",a="Innan Dorn prövar kroppens uthållighet kräver han att utmanarna genomgår Test of Faith, ett farligt språng i hängivenhet som prövar om en äventyrares ande sviktar inför rädslan.",al={"föregående uppdrag","prövningen före endurance","första prövningen"}}},fx={["8999be4f"]={q="Varför vill Dorn Plainstalker att det här blir gjort?",a="Dorn Plainstalker ser det som sin heliga plikt att förbereda unga äventyrare på den vida världens dödliga faror. När han har sett till att din ande och tro är starka vill han pröva din kropp. Genom att tvinga dig att uthärda våg efter våg av rasande harpyor djupt inne på deras eget område ser han till att du har uthålligheten och beslutsamheten som krävs för att överleva utanför hemmets trygghet.",al={"varför prövar dorn uthållighet","dorn plainstalkers motiv","syftet med test of endurance"}},b2efd71b={q="Vad ska Grenka's Claw användas till?",a="Klon är ett obestridligt bevis på att du stod på dig mitt i Roguefeather Den, överlevde harpyornas ihållande angrepp och besegrade deras mäktiga matriark, Grenka Bloodscreech. Dorn behöver den för att bekräfta att din uthållighet höll under det skoningslösa anfallet, innan han ger dig nästa prövning.",al={"användning av grenkas claw","varför behöver jag grenkas claw","syftet med grenka claw"}},["28ecd26a"]={q="Vem är Grenka Bloodscreech?",a="Grenka Bloodscreech är en mäktig ledare bland Roguefeather-harpyorna som hemsöker kanjongrottorna väster om Freewind Post. Hon är våldsam och mycket revirhävdande och styr flockens inre fristad. När du stormar djupt in i Roguefeather Den och förstör deras förråd av proviant väcker hennes vrede henne från boet för att själv döda dig.",al={"vem är grenka","grenka bloodscreech i berättelsen","ledare för roguefeather-harpyorna"}}},fp="17,345,16.431.0,31.455.0,32.132.0,34.208.0,38.210.0,39.169.0,49.240.0,35.197.0"}
P.entries["quest:1151"] = {n="Test of Strength",s="Test of Strength är det tredje provet som taurenmystikern Dorn Plainstalker övervakar i Thousand Needles. För att bevisa sin fysiska styrka får Hordens mästare i uppdrag att jaga rätt på Rok'Alim the Pounder, en uråldrig, fritt strövande stenelementar, och återvända med rester av hans krossade kropp.",h="Test of Strength är det tredje provet som taurenmystikern Dorn Plainstalker övervakar i Thousand Needles.",kw={"dorn plainstalker","gamla gudar","stenelementar","rok'alim","test of strength","the pounder","thousand needles","the weathered nook"},ang={["class:Shaman"]="Schamaner känner igen Rok'Alim som mer än ett hinder: han är en farlig, obunden manifestation av jord vars vägran att ge vika stör den lokala andebalansen.",["faction:Horde"]="Den som fullföljer riterna vid The Weathered Nook vinner Thunder Bluffs äldstes respekt och stärker sitt rykte i hela Kalimdor.",["race:Tauren"]="För taurenpilgrimer är det ett traditionellt prov på harmoni och fysisk viljestyrka att möta en otämjd stenande och visa jägarens förmåga att uthärda och övervinna Jordmoderns hårdaste krafter."},sec={{t="De gamla gudarnas tidsålder",b="För länge sedan, under de gamla gudarnas välde, täckte urtidselementarer världens yta och tjänade sina mörka härskare. När dessa uråldriga väsen störtades och förseglades under jorden förlorade elementarandarna sin förankring i den här världen och försvann till stor del från den fysiska tillvaron, såvida de inte bands och kallades fram med modern magi. Några väsen var dock så envisa och kraftfulla att de kunde dröja kvar på Azeroth utan magiska förankringar. Rok'Alim the Pounder är en sådan relik som vandrar genom de torra ravinerna i Thousand Needles, ett levande eko från den urtidens tidsålder."},{t="Thousand Needles krossare",b="De lokala centaurklanerna gav Rok'Alim hans öknamn på grund av de öronbedövande, jordbävningsliknande dån som uppstår när hans stenknogar slår mot ravinens botten. Den som är dumdristig eller djärv nog att hamna i hans väg blir hamrad till stoft. Eftersom Rok'Alim står för rå, obändig fysisk massa låter Dorn Plainstalker de invigda bryta ner besten som ett direkt mått på deras krigaranda och kräver bitar av elementarens steniga hjärta som bevis på segern."}},faq={{q="Var börjar och slutar uppdraget?",a="Uppdraget erbjuds och slutförs hos Dorn Plainstalker, en taurenäldste som håller till vid The Weathered Nook, ett avskilt läger högt uppe bland Thousand Needles spiror.",al={"uppdragsgivare","var lämna in uppdraget","dorn plats"}},{q="Vad är Rok'Alim the Pounder?",a="Rok'Alim är en uråldrig stenelementar som har överlevt i Kalimdor sedan de gamla gudarnas tidsålder. Till skillnad från moderna, frammanade elementarer har han tillräcklig medfödd kraft för att förbli fysiskt närvarande på Azeroth helt på egen hand.",al={"vem är rokalim","vilken sorts fiende är rokalim","elementarlära"}},{q="Varför kallar centaurerna honom ”the Pounder”?",a="Centaurstammarna i ravinen kallade honom the Pounder på grund av de dånande, rullande chockvågor som hans stenknogar släpper lös när han krossar allt i sin väg.",al={"öknamnet the pounder","centaurernas namn på rokalim"}},{q="Var i ravinen kan man hitta Rok'Alim?",a="Rok'Alim strövar omkring i de nordvästra delarna av Thousand Needles och patrullerar vanligtvis den öppna marken söder om huvudvägen som skär genom ravinens botten.",al={"rokalims återkomstplats","var finns rokalim"}},{q="Vilken plats har uppdraget i hela provkedjan?",a="Test of Strength är det tredje provet i kedjan. Det följer efter Test of Faith och Test of Endurance och kommer direkt före det sista provet, Test of Lore.",al={"ordning i uppdragskedjan","what comes next","vad kommer före"}},{q="Varför kräver Dorn att en elementar dödas i stället för ett vilddjur eller en fiende?",a="Dorn väljer Rok'Alim eftersom elementaren är en ren manifestation av levande sten och obändig urkraft. Att besegra en sådan motståndare bevisar fysisk överlägsenhet över själva den råa, orubbliga jorden.",al={"varför döda en elementar","syftet med test of strength"}}},fx={d3b1c16f={q="Varför vill Dorn Plainstalker att det här blir gjort?",a="Dorn Plainstalker låter dig genomgå en forntida taurenrit för att bevisa din duglighet innan du går vidare till de sista prövningarna. Att möta ett vanligt odjur eller en soldat skulle inte sätta din styrka på prov på riktigt, så han kräver att du utmanar en uråldrig kvarleva av ursprunglig sten. Om du dödar Rok'Alim bevisar det att din inre och fysiska styrka kan övervinna till och med uråldriga elementarkrafter.",al={"dorn plainstalkers motiv","varför vill dorn döda rokalim","varför göra test of strength"}},["67dd1d0a"]={q="Vad ska Fragments of Rok'Alim användas till?",a="Fragmenten är ett obestridligt bevis på att du stod inför Rok'Alim the Pounder och krossade den uråldriga elementaren. Dorn Plainstalker behöver fysiska bevis på din seger för att erkänna att du har klarat Test of Strength och förtjänat att gå vidare till nästa prövning.",al={"användning av fragments of rokalim","vad används fragmenten till","varför samla rokalim-fragment"}}},fp="16,300,29.589.0,31.471.0,36.178.0,29.226.0,42.161.0,42.156.0,59.162.0,75.211.0"}
P.entries["quest:1152"] = {n="Test of Lore",s="Efter prövningar av tro, uthållighet och styrka i Thousand Needles skickar Dorn Plainstalker hordens kämpar norrut till Stonetalon Mountains. Där väntar en vis schaman vid namn Braug Dimspirit, redo att hålla kunskapens prov. Denna prövning flyttar fokus från fysisk beslutsamhet till förståelse för världens långa historia och utbredda lidande.",h="Efter prövningar av tro, uthållighet och styrka i Thousand Needles skickar Dorn Plainstalker hordens kämpar...",kw={"braug dimspirit","dorn plainstalker","stonetalon mountains","the talondeep path","kunskapens prov","thousand needles","the weathered nook","windshear crag"},ang={["class:Shaman"]="Braug Dimspirit står för en schamanistisk världsbild som tolkar landets lidande genom dödligas hänsynslösa handlingar, från goblinernas utsugning till alvernas uråldriga isolering.",["faction:Horde"]="Braugs prövning får hordens kämpar att öppet begrunda sina egna bundsförvanters rykte och påminner dem om att varken orcherna eller de Fördömda ensamma bär ansvaret för landets bekymmer.",["race:Tauren"]="Prövningarna förkroppsligar traditionell taurenfilosofi, där andlig harmoni och historisk förståelse värderas högre än rå blodtörst."},sec={{t="Från tro till kunskap",b="I Weathered Nooks skyddade tillflykt låter Dorn Plainstalker de som vill bli kämpar genomgå krävande prövningar av deras andliga övertygelse, fysiska uthållighet och stridsförmåga. Men rå styrka och blind tro räcker inte för att bli en sann kämpe för Horden. Dorn inser sina egna begränsningar som lärare och skickar dem som bevisat sig till Stonetalon Mountains, där en äldre schaman kan pröva deras förstånd och världskännedom."},{t="Vägen till Stonetalon",b="Resan går norrut över The Barrens torra buskmarker och in bland Stonetalon bergskammar. Högt uppe i bergen, nära ingången till The Talondeep Path, grottan som skär genom berget mot Ashenvale, ligger Braug Dimspirits eremitage. Han vakar över en hårt prövad gränstrakt där gobliners skogsavverkning skövlar skogarna och fientliga nattalver försvarar sina förfäders gränser med hårdhet."},{t="Ett vidare perspektiv",b="När du möter Braug blir provets verkliga syfte tydligt. I stället för att kräva blind stolthet över fraktionen reflekterar Braug över Azeroths tragiska tillstånd. Han konstaterar att nästan varje civilisation bär ansvar för landets svåra belägenhet, trots att orcherna och de Fördömda ständigt får skulden för krig och förfall. Gobliner fäller uråldriga träd, och nattalver misstror de yngre raserna djupt. Kunskapens prov kräver att en kämpe ser bortom omedelbara fiendskaper och förstår den sårade världens större historia."}},faq={{q="Vad är kunskapens prov?",a="Det är en lärorik prövning inom en större övergångsrit som utformats av taurenäldste. De som prövas måste visa att de inte bara har fysisk styrka och tro, utan också historisk medvetenhet och förståelse för Azeroths gemensamma förflutna.",al={"kunskapens prov betydelse","vad är det här för uppdrag"}},{q="Var hittar jag Braug Dimspirit?",a="Braug Dimspirit bor i Stonetalon Mountains, nära Windshear Crag och alldeles intill ingången till grottan The Talondeep Path, som förbinder Stonetalon med Ashenvale.",al={"braug dimspirit plats","var finns braug"}},{q="Varför skickar Dorn iväg dig?",a="Dorn leder prövningarna av tro, uthållighet och styrka i Thousand Needles, men medger att världens historia inte är hans område att undervisa i. Han hänvisar värdiga aspiranter till Braug, en schaman med den visdom som krävs för att pröva deras sinnen.",al={"varför stonetalon","varför skickar dorn iväg dig"}},{q="Vilka hot bör resenärer se upp för längs vägen?",a="Dorn varnar särskilt för att nattalver stryker omkring i gränstrakterna nära Ashenvale och Stonetalon och ser hordens närvaro som ett intrång. Området kring Windshear Crag är också fullt av riskfyllda goblinska skogsavverkningar.",al={"faror på vägen till braug","fara vid the talondeep path"}},{q="Hur ser Braug Dimspirit på världens konflikter?",a="Braug anser att alla dödliga raser bär skuld för världens lidande. Rivaler utmålar ofta orcherna och de Fördömda som onda, men han påpekar att goblinernas girighet och nattalvernas högmod har orsakat lika stor skada i Kalimdor och Lordaeron.",al={"braug dimspirits filosofi","vad tror braug"}},{q="Vad är The Talondeep Path?",a="The Talondeep Path är ett stort tunnelsystem i bergen som förbinder Windshear Crag i Stonetalon Mountains med Ashenvales uråldriga skogsbryn i söder.",al={"vad är the talondeep path","the talondeep path grotta"}}},fp="12,353,18.452.0,22.411.0,21.539.1,25.238.0,33.169.0,41.239.0,54.226.0,56.254.0,27.160.0"}
P.entries["quest:1153"] = {n="A New Ore Sample",s="Tatternack Steelforge söker ny malm i Thousand Needles för att stärka Hordens vapen. Smeden i Camp Taurajo skickar dig söderut för att hämta ett prov till undersökning.",h="Tatternack Steelforge söker ny malm i Thousand Needles för att stärka Hordens vapen.",kw={"camp taurajo","kobold","tatternack steelforge","thousand needles","thrall","unrefined ore sample","weapons of choice"},ang={["faction:Horde"]="I Camp Taurajo kan du bidra med material till överhövdingens militära förberedelser från Hordens södra bastion.",["profession:Blacksmithing"]="Som smed för Horden hjälper du till att säkra nya metallfyndigheter så att gränslandet kan försvaras mot hoten omkring det.",["profession:Mining"]="Som prospektör vet du värdet av råa, obearbetade malmådror som grävande varelser blottar i outforskade sydliga raviner."},sec={{t="En smeds ambition",b="Tatternack Steelforge arbetar som smed i Camp Taurajo, under direkt uppsikt från Orgrimmar. Han har redan levererat vapen tillverkade av lokala kentaurers utrustning, men vill fortfarande bevisa sitt hantverk för överhövding Thrall. Resande som passerade visade honom en märklig malmbit som tagits från en kobold söderut. När de vägrade sälja den tog Tatternack deras vägran som en förolämpning mot sitt hantverk och Horden."},{t="Färdas till Thousand Needles",b="Du lämnar de flacka slätterna i södra The Barrens bakom dig och beger dig till Thousand Needles höga, labyrintiska raviner. Koboldgrävare tunnlar genom dess klippor och stup. Hämta tillbaka obearbetade bitar direkt från dem, så kan Tatternack avgöra om råmalmen går att smida till vapen som kan bidra till Thralls krigsinsats."}},faq={{q="Vem är Tatternack Steelforge?",a="Tatternack Steelforge är en vapensmed av orcisk härkomst, stationerad i Camp Taurajo i södra The Barrens. Han tillverkar vapen för Hordens försvar av gränslandet och söker nya material för att imponera på överhövding Thrall.",al={"tatternack","smed i camp taurajo","vem är tatternack"}},{q="Varifrån kommer malmprovet?",a="Kobolder bär på obearbetad malm genom de vindlande ravinerna i Thousand Needles, söder om The Great Lift vid gränsen till The Barrens.",al={"var finns malmen","malmens plats","malm i thousand needles"}},{q="Varför är Tatternack arg på resenärerna?",a="Resande från söder visade Tatternack en märklig mineralbit som tagits från en dödad kobold, men vägrade sedan att sälja den. Han såg deras hamstring av livsviktiga material som en opatriotisk förolämpning mot överhövdingen och kallade dem fegisar.",al={"varför är tatternack arg","resenärernas malm","tatternack och resenärerna"}},{q="Vad ska Tatternack göra med malmen?",a="Tatternack planerar att analysera malmens metallurgiska egenskaper och testa dess styrka. Om den visar sig vara tillräckligt hållbar tänker han smida ett vapenprototyp och överlämna det direkt till överhövding Thrall i Orgrimmar.",al={"vad händer med malmen","varför vill han ha malm"}},{q="Vilket krav måste uppfyllas innan uppdraget?",a="Först slutför du Weapons of Choice genom att samla in särskilda vapen från de olika kentaurstammar som hotar Camp Taurajo, och bevisar därmed att lokala vapen kan användas på nytt.",al={"förkunskapsuppdrag","tidigare uppdrag","weapons of choice"}},{q="Varför bär kobolder i Thousand Needles den här malmen?",a="Kobolder gräver och bryter malm tvångsmässigt och tunnlar genom klippformationer och underjordiska malmådror. I Thousand Needles har deras grävande blottat ovanliga fyndigheter som invånare på ytan sällan har rört.",al={"koboldgruvdrift","kobolder i thousand needles"}}},fx={ecf3b4be={q="Varför behöver Tatternack att du hämtar malmprovet?",a="Tatternack är stationerad vid Camp Taurajo, där han sköter sin smedja och tillverkar vapen åt Horde på Warchiefens uttryckliga order. Han är bunden vid sitt arbete vid städet och förolämpad av kringresande legoknektar som vägrade dela med sig av sitt fynd. Därför vänder han sig till en äventyrare som redan har vunnit hans förtroende och visat sig duglig i strid.",al={"varför jag för a new ore sample","varför behöver tatternack mig","varför kan inte tatternack hämta malmen"}}},fp="16,172,18.414.0,29.315.0,29.199.0,37.130.0,49.228.0,37.212.0,53.173.0,54.194.0"}
P.entries["quest:1154"] = {n="Test of Lore",s="Test of Lore är en prövning som Braug Dimspirit har satt upp vid ingången till The Talondeep Path. Den prövar en äventyrare från Horde på skärpa snarare än fysisk uthållighet. För att klara den måste den sökande ta sig djupt in i de hemsökta gravkamrarna i Ashenvale, hämta en uråldrig bok om drakarnas historia och studera innehållet innan förhöret.",h="Test of Lore är en prövning som Braug Dimspirit har satt upp vid ingången till The Talondeep Path.",kw={"ashenvale","braug dimspirit","camp taurajo","deathwing","the dor'danil barrow den","dorn plainstalker","legacy of the aspects","the talondeep path","test of lore"},ang={["class:Druid"]="Den som tar sig in i The Dor'Danil Barrow Den får se tragedin med korrumperade och dödade nattalvfränder, som en gång sov i gemenskap med The Emerald Dream.",["faction:Horde"]="Prövningen speglar Hordes behov av krigare som kan förstå Kalimdors djupa historia och ta sig fram genom Ashenvales farliga alvruiner utan att gå under av okunskap."},sec={{t="En ny sorts prövning",b="Efter att ha visat sin fysiska uthållighet och orubbliga tro på Thousand Needles saltfält och platåer skickas kandidaterna i Dorn Plainstalkers serie av prövningar norrut till Braug Dimspirit i Stonetalon Mountains. Braug är stationerad nära mynningen av The Talondeep Path och avfärdar de tidigare utmaningarna som enkla fysiska övningar. För att verkligen tjäna Horde med ära behöver en äventyrare ett skarpt och disciplinerat intellekt, redo att förstå uråldriga historier i stället för att bara slå ner bestar."},{t="Dor'Danils skuggor",b="Braug uppmanar de sökande att ta sig genom The Talondeep Path till de skogklädda trakterna i södra Ashenvale. Där, gömd under trädkronorna söder om Splintertree Post, ligger The Dor'Danil Barrow Den. Den underjordiska helgedomen är en farlig ruin som hemsöks av fallna nattalvdruider och de våldsamma varelser som slaktade dem. På en stenpiedestal djupt nere i kamrarna ligger priset: Legacy of the Aspects, ett sällsynt manuskript som beskriver hur de stora drak aspekterna skapades och korrumperades i forntiden."},{t="Studera eller lida",b="Att säkra boken är bara halva Braugs prövning. Innan den sökande lämnar ifrån sig volymen måste hen lära sig innehållet utantill. Braug tar genast boken när den lämnas in och testar vad den sökande minns om de titanförstärkta beskyddarna och det katastrofala svek som gav upphov till Deathwing. Den som inte studerar eller gissar fel skickas plötsligt tvärs över Kalimdor till Camp Taurajo i södra Barrens och tvingas skamset vandra tillbaka till Stonetalon."}},faq={{q="Vem är Braug Dimspirit?",a="Braug Dimspirit är en äldre tauren-schaman som är stationerad nära ingången till The Talondeep Path i Stonetalon Mountains. Han är examinator efter Dorn Plainstalkers tidigare prövningar och testar om Hordes mästare har det intellekt och den kunskap som behövs för att komplettera deras råa stridsförmåga.",al={"braug dimspirit","vem ger test of lore","uppdragsgivare i stonetalon"}},{q="Var finns boken Legacy of the Aspects?",a="Boken finns i The Dor'Danil Barrow Den i södra Ashenvale, nästan rakt söder om Splintertree Post. Den ligger på en stenpiedestal på en central plattform djupt nere i gravkamrarna.",al={"var finns legacy of the aspects","var finns boken","bokens plats i dor'danil"}},{q="Vad lurar i The Dor'Danil Barrow Den?",a="Gravkammaren var en gång en helgedom för nattalvdruider, men en tragedi drabbade hålorna. Nu är den översvämmad av de döda druidernas rastlösa andar och de dödliga inkräktare som slaktade dem. Den utgör en livsfarlig labyrint för alla inkräktare.",al={"fiender i dor'danil","vem vaktar boken","gravkammare i ashenvale"}},{q="Varför låter Braug mig läsa boken innan jag lämnar in den?",a="Braug tar boken när du lämnar tillbaka den och testar vad du minns. Han förväntar sig att du studerar den i förväg, eftersom prövningen mäter kunskap snarare än bara förmågan att hämta ett föremål.",al={"varför läsa legacy of the aspects","förhör i test of lore","vad händer om jag svarar fel"}},{q="Hur passar uppdraget in i den större prövningsserien?",a="Den här prövningen följer Test of Faith, som Dorn Plainstalker inledde vid The Weathered Nook i Thousand Needles. Där Dorn prövade ditt mod och din överlevnadsförmåga mot dödliga odds bedömer Braug din kunskap om legender och historia.",al={"test of faith-uppdragskedjan","vad kommer före test of lore","dorn plainstalkers prövningar"}},{q="Vad handlar Legacy of the Aspects om?",a="Manuskriptet skildrar titanernas mytomspunna historia och hur de stärkte de fem stora drak aspekterna så att de kunde skydda Azeroth. Framför allt berättar det om Neltharion the Earth-Warders fall och hans förvandling till den monstruösa förgöraren som blev känd som Deathwing.",al={"historien i legacy of the aspects","bokens bakgrund","vad handlar boken om"}}},fx={["0efda427"]={q="Varför kräver Braug Dimspirit att jag hittar Legacy of the Aspects?",a="Braug Dimspirit prövar ditt sinne snarare än din styrka. Du har redan genomgått Dorn Plainstalkers fysiska prövningar och bedöms nu efter din intelligens, påhittighet och vilja att lära. Genom att skicka dig ensam in i farlig terräng för att hämta och ta till dig forntida kunskap avgör Braug om du har visdomen som krävs för att klara hela prövningsserien.",al={"varför prövar braug mig","varför legacy of the aspects","varför prövar braug dimspirit mig"}}},fp="12,326,21.528.0,24.518.0,15.477.1,23.306.0,48.223.0,39.236.0,58.180.1,54.232.0,56.260.0"}
P.entries["quest:1159"] = {n="Test of Lore",s="Det här steget i Test of Lore för Horde-äventyrare över Stora havet till Ruins of Lordaeron. Efter att ha löst Braug Dimspirits första gåta i Stonetalon Mountains ska du söka upp en före detta mänsklig lärd bland de Förfallna i Undercity.",h="Det här steget i Test of Lore för Horde-äventyrare över Stora havet till Ruins of Lordaeron.",kw={"apothecarium","braug dimspirit","dorn plainstalker","lordaeron","parqual fintallas","test of lore","thousand needles","undercity","the weathered nook"},ang={["faction:Horde"]="Det här uppdraget visar hur samarbetet mellan kontinenter binder samman den nybildade Horden och förenar tauren som söker visdom med Lordaraons dystra arkivarier.",["race:Tauren"]="För en taurenaspirant blir resan från Kalimdors öppna slätter och höga platåer till Undercitys giftiga, trånga kloaker en lika stor kulturell prövning som en historisk.",["race:Undead"]="Mötet med Parqual visar att de Förfallnas lärda, som han, trots förruttnelse och odödhet har bevarat det fallna kungariket Lordaraons omfattande akademiska traditioner och arkiv."},sec={{t="En lärd allians",b="När du har visat vad du går för och nystat upp historien om drakernas aspekter i Legacy of the Aspects erkänner Braug Dimspirit att hans kunskaper har sina gränser. I stället för att begränsa prövningen till Kalimdor visar Braug hur långt Hordes band sträcker sig genom att hänvisa dig till den odöda huvudstaden under Ruins of Lordaeron."},{t="Den skeptiske historikern",b="I Apothecariums fuktiga korridorer bor Parqual Fintallas. En gång var han en ansedd mänsklig krönikör i de nordliga kungarikena. Hans kunskapstörst överlevde Scourge och förvandlingen till en av de Förfallna. När en främling påstår sig ha klarat Thousand Needles andliga och fysiska prövningar vägrar Parqual tro att du är något annat än en lycksökande legosoldat, tills du själv bevisar ditt värde för honom."}},faq={{q="Varför skickar en taurenprövning mig hela vägen till Undercity?",a="Braug Dimspirit medger att verklig kunskap om historia sträcker sig längre än Kalimdors historia. Han skickar dig till Parqual Fintallas, en välkänd mänsklig lärd vars kunskaper överlevde Lordaraons fall och förvandlingen till odöd, för att pröva din förståelse av världens historia i stort.",al={"varför till undercity","varför lordaeron","braug skickar mig till odöda"}},{q="Var finns Parqual Fintallas egentligen?",a="Parqual Fintallas finns i Undercity, på den södra bron i Apothecarium-kvarteret.",al={"var finns parqual","parquals plats","hitta fintallas"}},{q="Vem var Parqual Fintallas när han levde?",a="När han levde var Parqual Fintallas en framstående mänsklig historiker i kungariket Lordaeron. Efter att ha fallit offer för Plague of Undeath och anslutit sig till Sylvanas Förfallna fortsatte han sina lärda studier och riktade sitt intellekt mot andra, mörkare frågor.",al={"parqual fintallas historia","vem är parqual","fintallas bakgrund"}},{q="Varför tror inte Parqual att Braug skickade mig?",a="Parqual är djupt skeptisk mot främlingar. Han tycker att det är otroligt att en vanlig äventyrare skulle kunna kasta sig från Thousand Needles spiror, besegra uråldriga elementarvarelser och hämta forntida reliker. Han antar i stället att du bara har snappat upp rykten på en krog.",al={"varför är parqual otrevlig","parquals reaktion","parqual tror mig inte"}},{q="Vilken större prövning ingår det här uppdraget i?",a="Det här uppdraget är mittpunkten i uppdragskedjan Test of Lore, som utvecklades ur prövningen Dorn Plainstalker inledde vid The Weathered Nook. Den bedömer om en aspirant har mer än stridsförmåga och mod: också det intellekt och den historiska medvetenhet som anstår en mästare i Horde.",al={"vilken uppdragskedja är det här","test of faith-uppdragskedjan","vad är test of lore"}},{q="Vad händer när jag har nått Parqual?",a="Innan Parqual behagar ställa sin egen historiska gåta kräver han att du utför ett ärende åt honom i Eastern Kingdoms. Där ska du visa att du verkligen är den dugliga hjälte som Braug säger att du är.",al={"vad händer efter parqual","nästa uppdrag efter undercity","efter samtalet med fintallas"}}},fx={["670eb265"]={q="Varför skickar Braug Dimspirit dig till Undercity?",a="Braug Dimspirit har prövat dina grundläggande kunskaper, men hans roll är bara att vägleda dig genom det första steget i Test of Lore. För att verkligen pröva din förståelse av världen inser han att nästa fråga kräver ett annat perspektiv än hans eget. Han skickar dig till Parqual Fintallas, en berömd historiker från Lordaeron som nu tillhör Forsaken, så att en lärd som söker en helt annan sorts upplysning kan bedöma din hängivenhet till historia och sanning.",al={"varför skickar braug iväg mig","braug dimspirits motiv","varför ska jag till undercity åt braug"}}},fp="12,263,20.359.0,23.461.0,57.270.0,43.120.0,34.266.0,42.255.0,40.295.0,39.206.0"}
P.entries["quest:116"] = {n="Dry Times",s="Dry Times är ett uppdrag från Barkeep Daniels i Lakeshire att fylla på värdshusets spritförråd under en pågående belägring. Blackrock-orkernas invasion har skurit av handelsvägarna, så Daniels förlitar sig på äventyrliga kurirer som hämtar specialdrycker från Stormwinds olika områden.",h="Dry Times är ett uppdrag från Barkeep Daniels i Lakeshire att fylla på värdshusets spritförråd under en...",kw={"barkeep daniels","dry times","grimbooze thunderbrew","lakeshire","merlot","moonshine","redridge","sweet rum","thunderbrew lager"},ang={["faction:Alliance"]="Det här ärendet visar hur den bristande säkerheten på vägarna i Redridge påverkar vardagslivet. Alliansens kurirer måste åter knyta samman avskurna handelsvägar mellan Stormwind, Elwynn, Westfall, Duskwood och Redridge.",["race:Dwarf"]="Även under en ork-invasion förlitar sig människornas värdshus på dvärgarnas bryggarkunskap. Kurirer skickas hela vägen till Westfall för att hämta Grimbooze Thunderbrews berömda lager."},sec={{t="En belägrad stad",b="Lakeshire ligger i frontlinjen för en aggressiv framryckning av Blackrock-klanens orcher, som kommer från Stonewatch Keep. De vanliga försörjningsvägarna är blockerade och vägarna osäkra. Stadens värdshusvärd, Barkeep Daniels, står inför en nära förestående kris med tomma tunnor. För att hålla modet uppe bland skrämda bybor och hårt prövade stadsvakter vänder han sig till resande utifrån, som kan ta sig förbi vägspärrarna och fylla på förråden."},{t="En storslagen färd genom kungariket",b="Att fylla på Daniels källare är ingen enkel leverans. Det kräver en ambitiös resa tvärs över hela kungariket Stormwind. En kurir måste hämta ett fat Merlot från själva huvudstaden, Sweet Rum från Lion's Pride Inn i Goldshire, stark Moonshine från dystra Darkshire i Duskwood och en särskild tunna Thunderbrew Lager, bryggd av Grimbooze Thunderbrew ute i Westfalls kullar."}},faq={{q="Varför börjar Lakeshire få slut på alkohol?",a="Blackrock-orkernas invasion av Redridge har helt stört den vanliga handeln och försörjningskaravanerna. Barkeep Daniels vanliga leveranser är kraftigt försenade. Hans värdshus riskerar att bli helt utan sprit, samtidigt som staden är hårt pressad av kriget.",al={"varför dry times","varför saknas sprit i lakeshire","barkeep daniels problem"}},{q="Var hittar jag alla drycker som Barkeep Daniels behöver?",a="Du måste samla in fyra föremål från olika delar av kungariket: Merlot från värdshusen i Stormwind City, Sweet Rum från Goldshire i Elwynn Forest, Moonshine från Darkshire i Duskwood och en tunna Thunderbrew Lager från Grimbooze Thunderbrew i Westfalls kullar.",al={"dry times dryckernas platser","var köpa merlot moonshine rum","var hitta drycker åt daniels"}},{q="Vem är Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew är en dvärgbryggare som bor i Westfalls kullar. Barkeep Daniels anser att hans Thunderbrew Lager är en viktig del av förrådet, men för att få tag på den måste du utföra ett separat ärende åt Grimbooze och ordna en ny tunna.",al={"grimboozes plats","var finns grimbooze thunderbrew","westfall thunderbrew"}},{q="Vem är Barkeep Daniels?",a="Daniels är värdshusvärden i Lakeshire. Han är desperat att hålla värdshuset välförsett och gästerna lugna medan hotet från Blackrock-orcherna närmar sig. Därför anlitar han resande för att själva hämta förnödenheter.",al={"barkeep daniels","värdshusvärd i lakeshire","vem ger dry times"}},{q="Varför behöver Daniels drycker från så många olika områden?",a="Daniels serverar en blandad skara flyktingar, lokala milismän och äventyrare på genomresa. Därför behöver han ett brett utbud, från dvärglager till fint huvudstadsvin och starka regionala drycker från Duskwood och Elwynn.",al={"varför så många drycker","varför besöka duskwood och westfall"}},{q="Vilken belöning ger Barkeep Daniels för att du gör resan?",a="Utöver att ersätta dina resekostnader med en påse mynt ger Daniels dig en handsydd mantel som hans fru har sytt, som tack för att du vågat dig ut på rikets omstridda vägar.",al={"dry times belöning","vad ger daniels"}}},fx={["266c2dd6"]={q="Varför behöver Barkeep Daniels din hjälp med att hämta drycker?",a="Daniels kan inte lämna sin värdshuskrog obevakad, särskilt inte när Lakeshire är spänt och gästerna desperat behöver en drink för att glömma sina bekymmer. Samtidigt är de lokala vakterna och stadsmilisen helt upptagna med att hålla tillbaka Blackrock-orkernas invasion som tränger ner från norr. Bara en kringresande äventyrare kan tryggt färdas längs rikets farliga vägar för att hämta förnödenheter.",al={"varför jag för dry times","varför behöver daniels en äventyrare","varför skicka mig efter drycker"}},["8f4cd8c5"]={q="Vad är Keg of Thunderbrew till för?",a="Tunnan innehåller starkt Thunderbrew Lager, bryggt av Grimbooze Thunderbrew ute i Westfalls kullar. Barkeep Daniels behöver det för att fylla på Lakeshires sinande källare och ge de skräckslagna stadsborna och hårt ansatta försvararna ett kraftigt dvärgbryggt öl som håller modet uppe mot Blackrock-hotet.",al={"keg of thunderbrew och dry times","varför keg of thunderbrew","vad är thunderbrew lager till för"}},["0ca5cd6a"]={q="Vad är Skin of Sweet Rum till för?",a="Den här Skin of Sweet Rum kommer direkt från Lion's Pride Inn i Goldshire. Daniels tar med den på sin akuta spritresa för att tillgodose gästernas smak för sötare drycker medan stadens vanliga försörjningsleder fortfarande är avskurna av orcherna.",al={"skin of sweet rum och dry times","varför sweet rum","vad är sweet rum till för"}},["41f763cb"]={q="Vad är Cask of Merlot till för?",a="Den här tunnan med fint rödvin kommer från Stormwind Citys hjärta och skänker en gnutta civiliserad bekvämlighet mitt i det dystra gränskriget. Daniels behöver den för att se till att tavernans källare inte sinar helt medan vägarna är belägrade.",al={"cask of merlot och dry times","varför cask of merlot","vad är merlot till för"}},["88b6ac2e"]={q="Vad är Bottle of Moonshine till för?",a="Den här flaskan med starkt, grovt Moonshine bryggs i den skuggiga byn Darkshire. Barkeep Daniels tar in den för gäster som behöver något exceptionellt starkt för att hålla nerverna i styr inför det ständiga invasionshotet.",al={"bottle of moonshine och dry times","varför bottle of moonshine","vad är moonshine till för"}}},fp="9,161,18.279.0,27.245.0,40.186.0,53.190.0,29.148.0,23.148.0,60.157.0,57.135.0"}
P.entries["quest:1166"] = {n="Overlord Mok'Morokk's Concern",s="Overlord Mok'Morokk från Stonemaul-klanen befinner sig i Brackenwall Village och vill ha tillbaka sitt grogg, sitt snus och sin kassaskrin. Han lämnade kvar dem i all hast vid klanens gamla hem och skickar dig söderut för att hitta dem.",h="Overlord Mok'Morokk från Stonemaul-klanen befinner sig i Brackenwall Village och vill ha tillbaka sitt grogg...",kw={"brackenwall","the den of flame","dustwallow","grogg","mok'morokk","rexxar","snus","stonemaul","kassaskrin"},sec={{t="Överlordens berättelse",b="Mok'Morokk säger att Rexxar gjorde honom till Stonemaul-klanens mäktiga ledare och att han håller sitt folk tryggt. Enligt honom kom stora drakar till det gamla hemmet och förde med sig eld, så han hittade ett nytt hem åt klanen här i Dustwallow."},{t="Kvarlämnade saker",b="Han lämnade det gamla hemmet så hastigt att han glömde sina ägodelar: sitt grogg, sitt snus och sitt kassaskrin. Han pekar ut vägen söderut, till Den of Flame och Stonemaul Ruins, och är säker på att de finns där. Han säger att han är för upptagen med att leda ogres för att gå dit själv."}},faq={{q="Vem är Overlord Mok'Morokk?",a="Overlord Mok'Morokk leder Stonemaul-klanen från Brackenwall Village. Enligt sin egen berättelse gjorde Rexxar honom till klanens mäktiga ledare.",al={"mok'morokk","ogreledare","vem är överlorden"}},{q="Vad hände med Stonemaul-klanens gamla hem?",a="Mok'Morokk säger att stora drakar kom och förde med sig eld till det gamla hemmet, så han hittade ett nytt hem åt klanen i Brackenwall Village.",al={"varför lämnade ogres platsen","stonemaul förstört","drakar anfaller ogres"}},{q="Vad vill Mok'Morokk ha tillbaka?",a="Han vill ha tillbaka sitt grogg, sitt snus och sitt kassaskrin, som han glömde när han hastigt lämnade det gamla hemmet.",al={"mok'morokks saker","vilka saker vill han ha","grogg snus kassaskrin"}},{q="Var finns Mok'Morokks ägodelar?",a="Han skickar dig söderut och är säker på att ägodelarna finns i Den of Flame och Stonemaul Ruins.",al={"var finns sakerna","sakernas platser","hitta grogg och snus"}},{q="Varför hämtar Mok'Morokk inte sina saker själv?",a="Han säger att han är för upptagen med att leda ogres för att gå och hämta dem.",al={"varför går inte mok'morokk själv","varför skickar han mig"}}},fp="29,205,20.226.0,18.248.0,27.132.0,47.122.0,31.101.0,34.94.0,48.60.0"}
P.entries["quest:1167"] = {n="The Tower of Althalaxx",s="Det här uppdraget markerar den spända pausen före konfrontationen med Athrikus Narassin vid Tower of Althalaxx. Delgren the Purifier skickar dig norrut för att åter möta spejaren Balthule Shadowstrike och samla information om de oberäkneliga, mörka händelser som skakar spiran.",h="Det här uppdraget markerar den spända pausen före konfrontationen med Athrikus Narassin vid Tower of...",kw={"althalaxx","athrikus","balthule","kultister","darkshore","delgren","torn"},ang={["class:Paladin"]="Delgrens genomtänkta tillvägagångssätt visar den disciplin som förväntas av ljusets krigare. Han föredrar vaksam spaning framför att rusa in i vanhelgade helgedomar.",["faction:Alliance"]="Samarbetet mellan Delgren och Balthule är ett praktiskt partnerskap i krigstid mellan mänskliga paladiner och nattalvsspejare, för att hålla norra Kalimdor säkert.",["race:NightElf"]="Balthule Shadowstrike försvarar sina förfäders land mot trolldom som påminner om de vårdslösa arkaniska överdrifter som ruinerade nattalvernas civilisation för tiotusen år sedan."},sec={{t="En spejares rapport",b="Efter att ha renat korrumperade reliker och nystat upp kultens grepp längs Darkshores gräns skickar Delgren the Purifier dig tillbaka norrut för att rådfråga sin vaktpostskamrat Balthule Shadowstrike. Innan ni går till direkt angrepp mot trollkarlen Athrikus inser Delgren att ni behöver färska spaningsuppgifter från slagfältet. Han litar på Balthules outtröttliga vakthållning från ruinerna med utsikt över tornet."},{t="Oro i spiran",b="När du når Balthules utkik berättar spejaren om en alarmerande upptrappning i det övre helgedomsrummet. Plötsliga blixtar av bländande ljus, plågsamma skrik som skär genom dimman och oberäkneliga blixtnedslag har börjat skaka det urgamla alvtornet våldsamt. De förebådar en instabil och farlig kulmen på Athrikus mörka verk."}},faq={{q="Varför skickar Delgren mig tillbaka till Balthule?",a="Delgren vet att det är vårdslöst att rusa blint in i Athrikus näste. Balthule har hållit ständig uppsikt över Tower of Althalaxx och är den ende som vet vad Athrikus och hans kultister har gjort på sistone.",al={"varför träffa balthule","prata med balthule","delgrens order"}},{q="Var finns Balthule Shadowstrike?",a="Balthule har ett observationsläger på kullarna strax väster om Tower of Althalaxx, med uppsikt över ruinerna i norra Darkshore.",al={"balthules plats","hitta balthule","var är balthule"}},{q="Vilka händelser vid tornet har Balthule nyligen bevittnat?",a="Balthule såg ett bländande ljussken bryta fram ur tornets översta kammare. Därefter hördes vedervärdiga skrik över kusten och oberäkneliga blixtar slog ner i marken.",al={"vad hände vid tornet","balthule skrik","ljussken vid tornet"}},{q="Vem är Athrikus?",a="Athrikus Narassin är den mörke trollkarl som leder kultisterna vid Tower of Althalaxx. Delgren och Balthule är fast beslutna att stoppa hans fasansfulla ritualer.",al={"vem är athrikus","athrikus narassin","tornets boss"}},{q="Är Delgren the Purifier en lokal nattalv?",a="Nej, Delgren är en mänsklig paladin och krigare av det heliga ljuset, stationerad vid gränsen mellan Darkshore och Ashenvale. Han samarbetar med nattalvernas spejare för att rensa ut demonisk korruption.",al={"vem är delgren","delgrens folkslag","är delgren en alv"}},{q="Vad är Tower of Althalaxx för slags ruin?",a="Det är en högborne eller urgammal nattalvsspira längs Darkshores klippiga nordkust. Den övergavs för länge sedan, innan fallna arkanister och demoniska kultister tog den i anspråk för förbjudna riter.",al={"althalaxx bakgrund","vad är tornet","tornets historia"}}},fx={cf915580={q="Varför vill Delgren the Purifier att det här ska göras?",a="Delgren the Purifier har vigt sig åt att utrota mörk, fördärvande magi och demoniskt inflytande. Kultristerna som ockuperar Tower of Althalaxx hotar Darkshores helighet med sina onda ritualer. Delgren vill att Athrikus stoppas innan magikern släpper lös de fasor han förbereder, men han vet att ett vårdslöst anfall kan bli dödligt utan kunskap om tornets senaste försvar.",al={"delgrens motiv","varför bryr sig delgren","delgrens syfte med tower of althalaxx"}}},fp="22,178,16.333.0,25.258.1,42.177.0,39.143.0,53.165.0,16.148.0,42.178.0,44.188.0"}
P.entries["quest:1168"] = {n="Army of the Black Dragon",s="I Brackenwall Village vill ogren Tharg hämnas på den svarta drakens armé. Tharg hyser agg mot Overlord Mok'Morokk, som bad og kan fly i stället för att slåss, och ber dig anfalla Firemane.",h="I Brackenwall Village vill ogren Tharg hämnas på den svarta drakens armé.",kw={"brackenwall","dustwallow","firemane","mok'morokk","rexxar","stonemaul","tharg"},sec={{t="En blodig oförrätt",b="Svarta drakar dödade många ogres, och Thargs hustru var en av dem. Mok'Morokk, som Rexxar utsåg till Overlord, sade åt de överlevande att fly, och så kom de till Brackenwall Village. Tharg säger att ogres är dåliga på att fly och borde slåss, och han tror att Mok'Morokk bara bryr sig om sig själv. Tharg säger också att Mok'Morokk ber alla ogres stanna kvar och hålla den här platsen trygg."},{t="Hem i söder",b="Tharg kallar Stonemaul Ruins sitt hem och trivs i söder. Brackenwall Village är inte hans hem. Han vill hämnas på den svarta drakens armé och få tillbaka sitt gamla hem, så han ber dig fälla Firemane Scouts och Firemane Ash Tails i dess led."}},faq={{q="Vem är Tharg?",a="Tharg är en ogre som bor i Brackenwall Village. Svarta drakar dödade hans hustru, och han vill hämnas och återvända till Stonemaul Ruins.",al={"tharg berättelse","vem är tharg","tharg dustwallow"}},{q="Varför ogillar Tharg Overlord Mok'Morokk?",a="Rexxar gjorde Mok'Morokk till Overlord, men Tharg säger att han bryr sig mer om makt än om ogres. När de svarta drakarna dödade många ogres sade Mok'Morokk åt resten att fly, och Tharg tycker att ogres borde slåss.",al={"varför hatar tharg mok morokk","mok'morokk fegis","tharg och mok morokk"}},{q="Vad hände med Thargs hustru?",a="Svarta drakar dödade henne tillsammans med många andra ogres. Det är roten till Thargs önskan om hämnd.",al={"thargs hustru","vad hände med thargs hustru","thargs hustru död"}},{q="Var ligger ogres gamla hem?",a="Tharg kallar Stonemaul Ruins sitt hem och trivs i söder. Han säger att Brackenwall Village inte är hans hem och att han vill återvända.",al={"stonemaul ogrehem","varifrån kom ogres","stonemaul ruins historia"}},{q="Vilka fiender ingår i den svarta drakens armé?",a="Tharg pekar ut Firemane, däribland Firemane Scouts och Firemane Ash Tails.",al={"firemane drakkin","vem ska dödas i den svarta drakens armé","firemane fiender"}}},fp="24,209,20.382.0,17.261.0,13.143.0,43.199.0,30.98.0,29.129.0,51.84.0"}
P.entries["quest:1169"] = {n="Identifying the Brood",s="I Brackenwall Village kallar Draz'Zilb Mok'Morokk en feg ynkrygg som vältrar sig i makt, och säger att Tharg brottas med sorg och hämndlystnad medan han kämpar om att leda klanen. Draz'Zilb tror att ingen annan bryr sig om att ta reda på vem som angrep det gamla hemmet, och ber dig om femton glödande tungor och femton glödande hjärtan.",h="I Brackenwall Village kallar Draz'Zilb Mok'Morokk en feg ynkrygg som vältrar sig i makt, och säger att Tharg...",kw={"svart drake","brackenwall village","draz'zilb","dustwallow marsh","mok'morokk","glödande hjärtan","glödande tungor","stonemaul","tharg"},sec={{t="En röst av förnuft",b="Draz'Zilb säger att Mok'Morokk vältrar sig i makt medan Tharg brottas med sorg och hämndlystnad, så enligt Draz'Zilb bryr sig ingen annan om vem som ligger bakom angreppet på det gamla hemmet. Draz'Zilb påpekar att du kanske hade väntat dig att en ogre skulle tala som en råskinn."},{t="Hjärtan och tungor",b="Draz'Zilb vill ha tungor och hjärtan från ungar och nykläckta drakar, femton av varje, för att spåra varifrån denna ondska kommer. Av de brända ungarna från den svarta drakarmén hoppas Draz'Zilb få veta vilket uselt odjur som släppte lös sina ungar i ogres hem. Om ogres lär känna fienden bättre kanske de kan förgöra dem för gott och återta Stonemaul Village från ruinerna. Att få Mok'Morokk att lämna detta träsk, tillägger Draz'Zilb, blir ett stort arbete i sig."}},faq={{q="Vem är Draz'Zilb?",a="Draz'Zilb är en ogre i Brackenwall Village som talar formellt i stället för som en råskinn, och vill ta reda på vem som ligger bakom attacken på klanens gamla hem.",al={"drazzilb","ogremagiker brackenwall","smart ogre"}},{q="Vad vill Draz'Zilb ha från ungarna och de nykläckta drakarna?",a="Draz'Zilb vill ha femton glödande tungor och femton glödande hjärtan. De ska hjälpa till att spåra vilket odjur som släppte lös sina ungar i det gamla hemmet.",al={"användning av glödande hjärtan","varför tungor och hjärtan","syftet med att identifiera ynglen"}},{q="Vad tycker Draz'Zilb om klanens ledare?",a="Draz'Zilb har föga respekt för Mok'Morokk och kallar den ogre för en feg ynkrygg som låter makten stiga honom åt huvudet. Om Tharg säger Draz'Zilb att han är uppslukad av sorg och hämndbegär.",al={"mokmorokk problem","tharg och mokmorokk","stonemauls ledare"}}},fp="21,323,17.284.0,18.461.0,17.171.0,56.145.0,48.186.0"}
P.entries["quest:117"] = {n="Thunderbrew",s="I Westfall samlar Grimbooze Thunderbrew ihop det han behöver till nästa brygd. Färsk humle hindrar ölet från att bli tjockt som gryta, och han delar med sig av fat till dem som hjälper till.",h="I Westfall samlar Grimbooze Thunderbrew ihop det han behöver till nästa brygd.",kw={"öl","bryggning","dvärg","grimbooze","humle","fat","lager","thunderbrew","westfall"},ang={["profession:Cooking"]="Som kock vet du hur korn, malt och humle måste balanseras, precis som ingredienserna i klassisk dvärgisk bryggning.",["race:Dwarf"]="Som dvärg är det välkommet att se en frände hålla Kharanos bryggtraditioner vid liv på Westfalls karga utmarker, särskilt när fat är inblandade."},sec={{t="En dvärgs passion i Westfall",b="Grimbooze Thunderbrew håller familjens bryggtradition vid liv långt från Dun Morogh. Även på Westfalls oroliga slätter insisterar han på rätt ingredienser: utan ordentlig humle kan hans nuvarande brygd bli tjock som gryta i stället för uppfriskande öl."},{t="Fatets konst",b="Grimbooze hyllar humle, korn, jäst och malt i glada rim. Med färsk humle avslutar han jäsningen på plats. De som förser honom med ingredienser får hela fat Thunderbrew Lager, en brygd känd för sin kraftiga smak."}},faq={{q="Vem är Grimbooze Thunderbrew?",a="Grimbooze Thunderbrew är en dvärgisk bryggare som strövar omkring i Westfall. Han för sin klans bryggtradition vidare var han än slår läger och talar och mässar på glada rim.",al={"grimbooze","vem är grimbooze","grimboozes historia"}},{q="Varför behöver Grimbooze humle?",a="Utan färsk humle kan Grimboozes senaste brygd smaka tjockt och tungt som gryta i stället för krispig lager. Humle ger brygden beska och balans.",al={"varför humle","grimbooze humle","vad används humle till"}},{q="Vad är Thunderbrew Lager?",a="Thunderbrew Lager är en stark dvärgisk dryck som bryggs av familjen Thunderbrew. Grimbooze delar ut den i hela fat, och den kraftiga smaken slår hårt mot gommen.",al={"thunderbrew-öl","fat thunderbrew","vad är thunderbrew"}},{q="Kan du ta med humle till Grimbooze mer än en gång?",a="Ja. Grimbooze tar gärna emot mer humle och erbjuder fler fat av sin brygd i utbyte.",al={"upprepningsbart uppdrag","kan thunderbrew upprepas","fler fat"}},{q="Var äger uppgiften rum?",a="Arbetet äger rum i Westfall, där Grimbooze slår läger och samlar förnödenheter bland jordbruken.",al={"thunderbrews plats","var finns grimbooze","uppdragsområde"}},{q="Är Grimbooze släkt med Thunderbrews i Dun Morogh?",a="Ja. Grimbooze delar efternamn och bryggaryrke med familjen Thunderbrew i Kharanos i Dun Morogh.",al={"thunderbrew distillery","grimboozes klan","familjen thunderbrew"}}},fp="11,173,29.178.0,18.203.0,29.155.0,29.150.0,26.150.0,44.77.0,32.97.0,55.106.0"}
P.entries["quest:1170"] = {n="The Brood of Onyxia",s="Draz'Zilb berättar att Onyxias yngel har invaderat Stonemaul Village och undrar varför Deathwings dotter skulle komma till dessa trakter. Du skickas för att underrätta Overlord Mok'Morokk i Brackenwall Village.",h="Draz'Zilb berättar att Onyxias yngel har invaderat Stonemaul Village och undrar varför Deathwings dotter...",kw={"brackenwall village","deathwing","draz'zilb","dustwallow marsh","mok'morokk","onyxia","stonemaul"},sec={{t="En oroande närvaro",b="Onyxias yngel invaderade Stonemaul Village, och Draz'Zilb tycker att det är oroande att Deathwings dotter skulle komma till dessa trakter. Draz'Zilb är säker på att Onyxia kom av mer än en belägring av några få ogres och vill att Overlord Mok'Morokk genast underrättas i Brackenwall Village, så att åtgärder kan vidtas."},{t="Besked i Brackenwall",b="Mok'Morokk tar inte emot nyheten väl. Overlord gillar inte drakar, trivs i Brackenwall Village och säger att det inte finns några drakar här."}},faq={{q="Vem skickar dig för att tala med Overlord Mok'Morokk?",a="Draz'Zilb skickar dig, efter att Onyxias yngel har invaderat Stonemaul Village.",al={"vem startar onyxias yngel","uppdragsgivare för onyxias yngel"}},{q="Var hittar du Overlord Mok'Morokk?",a="Du hittar Overlord Mok'Morokk i Brackenwall Village.",al={"mok'morokks plats","var finns mok'morokk","overlord mok'morokk dustwallow"}},{q="Varför oroar sig Draz'Zilb för Onyxias yngel?",a="Draz'Zilb undrar varför Deathwings dotter skulle komma till dessa trakter och är säker på att det var av mer än en belägring av en liten grupp ogres.",al={"varför bryr sig draz'zilb om drakar","draz'zilbs oro för onyxia"}}},fp="19,204,20.308.0,19.136.1,48.77.0,39.57.0,48.142.0"}
P.entries["quest:1171"] = {n="The Brood of Onyxia",s="Overlord Mok'Morokk vill inte höra talas om drakar. Han säger att det inte finns några svarta drakar här och skickar dig tillbaka till Draz'Zilb i Brackenwall Village med beskedet att ogres stannar.",h="Overlord Mok'Morokk vill inte höra talas om drakar.",kw={"brackenwall village","onyxias yngel","draz'zilb","dustwallow marsh","mok'morokk","rexxar"},sec={{t="Lämna mig i fred",b="Efter att Draz'Zilb skickat bud om Onyxias yngel vill Overlord Mok'Morokk bara bli lämnad i fred. Mok'Morokk säger att ogres stannar där de är, att det inte finns någon svart drake här, och ber dig gå och säga det till Draz'Zilb i Brackenwall Village."},{t="Vad Draz'Zilb säger",b="Draz'Zilb tar svaret illa och kallar Overlord en lat fegis. Mok'Morokk visade styrka medan Rexxar var deras ledare, säger Draz'Zilb, men efter att Rexxar gett sig av tog maktens frestelser över. Mok'Morokk kräver nu att ogres tjänar honom i stället för att leda dem, och Draz'Zilb säger att något måste göras."}},faq={{q="Varför vägrar Overlord Mok'Morokk att agera?",a="Mok'Morokk säger att det inte finns några svarta drakar här och vill bli lämnad i fred. Du får i uppdrag att meddela Draz'Zilb att ogres stannar.",al={"varför hjälper mok'morokk inte till","mok'morokks reaktion","varför finns inga svarta drakar"}},{q="Vad händer före detta i berättelsen?",a="Det här följer på The Brood of Onyxia, där Draz'Zilb skickade dig för att berätta om ynglet för Mok'Morokk.",al={"vad kommer före det här uppdraget","uppdragskedjans ordning"}},{q="Var utspelar sig det här?",a="Både Mok'Morokk och Draz'Zilb befinner sig i Brackenwall Village.",al={"var finns uppdraget","plats"}}},fp="19,191,14.249.0,19.322.1,43.136.0,40.103.0,27.57.0"}
P.entries["quest:1172"] = {n="The Brood of Onyxia",s="Draz'Zilb i Brackenwall Village vill inte att ännu en av Onyxias ungar ska kläckas. Du skickas för att hitta och förstöra den svarta drakens ägg nära Wyrmbog, längst söderut i träsket.",h="Draz'Zilb i Brackenwall Village vill inte att ännu en av Onyxias ungar ska kläckas.",kw={"brackenwall","onyxias kull","the dragonmurk","draz'zilb","mok'morokk","onyxia","stonemaul","wyrmbog"},sec={{t="Äggen i Wyrmbog",b="Onyxias kull har spridits ut över Dragonmurk. Draz'Zilb manar dig att skynda: Wyrmbog ligger i träskets södra del, och Draz'Zilb är säker på att draken har sitt näste där, med ägg utspridda omkring det. Så länge landet kring Stonemaul Village är en boplats för drakar kommer ogres aldrig att återta det, så du skickas för att spåra upp äggen och förstöra dem."},{t="En sista tjänst",b="När äggen har förstörts säger Draz'Zilb att det kommer att dröja innan Onyxia kan lägga fler, och tackar dig å Stonemaul Clans vägnar. Sedan ber Draz'Zilb om en tjänst till. Draz'Zilb anser att Mok'Morokk är olämplig att leda, och Tharg, som skulle bli en utmärkt ledare, hålls tillbaka av skador och ålder. Du ombeds driva bort Mok'Morokk med våld, så att en ny ledare kan föra klanen tillbaka till dess rätta hem i söder."}},faq={{q="Vem ger det här uppdraget?",a="Draz'Zilb i Brackenwall Village skickar ut dig mot Onyxias ägg.",al={"vem ger onyxias kull","uppdragsgivare onyxias kull","drazzilbs uppdrag"}},{q="Varför måste drakäggen förstöras?",a="Draz'Zilb vill inte att fler av Onyxias ungar ska kläckas. Så länge landet kring Stonemaul Village är en boplats för drakar kommer ogres aldrig att återta det.",al={"varför förstöra onyxias ägg","varför krossa ägg","drakägg stonemaul village"}},{q="Var finns äggen?",a="Runt Wyrmbog, i träskets södra del. Draz'Zilb är säker på att Onyxia har sitt näste där.",al={"var finns onyxias ägg","onyxias ägg plats","var ligger wyrmbog"}},{q="Var passar det här steget in i den större uppdragskedjan?",a="Det kommer efter att Mok'Morokk vägrade agera på nyheten om kullen, när du förde hans svar tillbaka till Draz'Zilb.",al={"onyxias kull uppdragskedja","föregående uppdrag onyxias kull","vad kommer före onyxias kull 3"}}},fp="19,188,23.384.0,16.428.1,21.71.0,38.159.0,27.96.0,46.113.0"}
P.entries["quest:1173"] = {n="Challenge Overlord Mok'Morokk",s="Overlord Mok'Morokk hånar din utmaning, lovar att krossa dig och ber dig säga till när du är redo att få stryk. Draz'Zilb i Brackenwall Village hade hoppats få se Mok'Morokk drivas ut ur byn.",h="Overlord Mok'Morokk hånar din utmaning, lovar att krossa dig och ber dig säga till när du är redo att få...",kw={"brackenwall village","utmana overlord mok'morokk","draz'zilb","dustwallow marsh","mok'morokk","stonemaul"},sec={{t="En utmaning till Overlord",b="Du kliver fram till Overlord Mok'Morokk, som skrattar åt ditt mod, lovar att krossa dig och säger åt dig att säga till när du är redo för stryk. Detta följer på The Brood of Onyxia. Draz'Zilb i Brackenwall Village väntar sig att få se Mok'Morokk jagas ut ur byn och undrar varför du skulle komma tillbaka bara för att prata."},{t="Besked till Draz'Zilb",b="När du har vunnit kampen säger Draz'Zilb att Mok'Morokk sprang iväg som en fegis och tackar dig för en stor tjänst. När Mok'Morokk är borta kan ogres utse en ny ledare som hjälper dem att återta sitt gamla hem för gott."}},faq={{q="Vem utmanar du?",a="Du utmanar Overlord Mok'Morokk i Brackenwall Village. Overlord svarar med ett skratt och skryter om att han ska krossa dig.",al={"vem ska jag slåss mot","utmaningens mål","vem är mok'morokk"}},{q="Vad kommer före den här utmaningen?",a="Den följer på The Brood of Onyxia.",al={"vilket uppdrag kommer före det här","förutsättningsuppdrag","föregående uppdrag"}},{q="Vem rapporterar du till efter kampen?",a="Draz'Zilb i Brackenwall Village är den du ska rapportera till.",al={"vem lämnar jag in det till","npc att lämna in till","vart efter att ha besegrat mok'morokk"}},{q="Vad förväntar sig Draz'Zilb av dig?",a="Draz'Zilb väntar sig att få se Mok'Morokk jagas ut ur byn och undrar varför du skulle komma tillbaka bara för att prata.",al={"varför slåss mot mok'morokk","varför utmana överherren","orsak till kampen"}}},fp="29,213,27.314.0,18.219.1,21.120.0,33.31.0,37.57.0,34.110.0"}
P.entries["quest:1174"] = {n="Gnomes Win!",s="I Thousand Needles ger en Gnome Race Ticket utdelning när gnomerna vinner. En prisask går till den som har den vinnande biljetthalvan.",h="I Thousand Needles ger en Gnome Race Ticket utdelning när gnomerna vinner.",kw={"gnome race ticket","prisask från gnomerna","gnomerna vinner","tävlingar","thousand needles"},sec={{t="Gnome Ticket",b="Gnome Race Ticket är biljetthalvan som gäller när gnomerna vinner. Behåll den, så får du en prisask från gnomerna när resultatet är klart. Goblinbiljetten har ett eget resultat för den andra sidan av loppet."}},faq={{q="Vad är Gnome Race Ticket?",a="Det är biljetten för gnomernas sida av loppet i Thousand Needles. Den gäller när gnomerna vinner.",al={"gnombiljett","vad är gnome race ticket","syftet med tävlingsbiljetten"}},{q="Vad får du när gnomerna vinner?",a="En prisask från gnomerna går till den som har Gnome Race Ticket när gnomerna vinner.",al={"prisask från gnomerna","pris när gnomerna vinner"}},{q="Vem kan delta i vadet?",a="Den tillhör ingen fraktion, så resande från Alliance och Horde har samma förutsättningar.",al={"kan horde slå vad","kan alliance slå vad","neutral biljett"}},{q="Vad händer om goblinerna vinner i stället?",a="Då är det goblinbiljetten som gäller. Dess resultat kallas Goblins Win!, motsvarigheten till det här resultatet.",al={"goblins win","goblin race ticket"}}},fp="11,138,16.210.0,30.100.0,36.94.0,32.87.0,40.111.0"}
P.entries["quest:1175"] = {n="A Bump in the Road",s="Trackmaster Zherin ser efter banan vid Mirage Raceway, och djuren ute på The Shimmering Flats har blivit så stora att deras antal måste hållas nere innan de vandrar ut på den. Du ombeds att gallra bland Saltstone Basilisks, Crystalhides och Gazers.",h="Trackmaster Zherin ser efter banan vid Mirage Raceway, och djuren ute på The Shimmering Flats har blivit så...",kw={"crystalhide","gazer","mirage raceway","red thunder","saltstone basilisk","the shimmering flats","tahonda ruins","trackmaster zherin","weazel's crater"},sec={{t="Håll banan fri",b="En basilisk kolliderade en gång med goblinernas racerbil Red Thunder, och efter olyckan tog Kronkrider med sig Zherin för att sköta banan. Zherin kan inte säga vad djuren ute på The Shimmering Flats äter för att bli så stora, bara att deras antal måste hållas nere, annars kan ett av dem irra ut på banan mitt under ett lopp. Det är illa nog att röja undan vrakdelar, och Zherin vill helst slippa plocka bort brända djurdelar också."}},faq={{q="Vem är Trackmaster Zherin?",a="Banmästaren vid Mirage Raceway på The Shimmering Flats, anställd av Kronkrider för att ta hand om banan.",al={"vem är zherin","trackmaster zherin","zherins bakgrund"}},{q="Varför jagas basiliskerna?",a="Bestarna ute på flaken har blivit stora, och om en irrar ut på banan under ett lopp kan det leda till en krasch, som när en basilisk kolliderade med goblinernas Red Thunder.",al={"varför döda basilisker","varför basilisker måste dö","basiliskproblem"}},{q="Vad är Red Thunder?",a="En racerbil som tillhör goblinerna och som förstördes i en kollision med en basilisk.",al={"red thunder","red thunder-krasch","goblinernas red thunder"}},{q="Var brukar basiliskerna finnas på flaken?",a="De strövar över hela The Shimmering Flats, men samlas tätare nära Weazel's Crater och bland Tahonda Ruins.",al={"basiliskernas platser","var finns basiliskerna","var hitta saltstone"}}},fp="18,266,23.435.0,26.109.0,35.167.0,24.73.0,51.114.0"}
P.entries["quest:1176"] = {n="Load Lightening",s="Pozzik, den ledande gobliningenjören vid Mirage Raceway, behöver material för att kapa några avgörande gram från chassit på sin raketbil. I stället för att enbart förlita sig på tung metallplåt tar goblinerna till vara på ihåliga ben från lokala ökensgamarskelett för att bygga starka men ultralätta styr- och chassidelar.",h="Pozzik, den ledande gobliningenjören vid Mirage Raceway, behöver material för att kapa några avgörande gram...",kw={"ben","lätta lasten","mirage raceway","pozzik","raketbil","the shimmering flats","thousand needles","gam"},ang={["profession:Engineering"]="Pozziks användning av ramar av fågelben visar prov på goblinernas typiska uppfinningsrikedom: funktionell, improviserad och förvånansvärt effektiv när det gäller att minska tjänstevikten.",["race:Gnome"]="Att se gobliner bokstavligen surra fast asätna fågelkadaver i mekaniska styranordningar lär skandalisera varje klassiskt skolad ingenjör från Tinker Town."},sec={{t="Varje uns räknas",b="Över Shimmering Flats bländande vita vidder avgörs rivaliteten mellan goblinernas och gnomernas ingenjörer med bråkdelar av en sekund. Rå motorkraft är värdelös om en förare tyngs ned av överflödig vikt. Medan gnomernas lag ägnar sig åt intrikata kugghjul och mässingsdetaljer söker goblinbesättningen under Pozzik en kompromisslöst praktisk effektivitet: de tar bort tunga järnramar och ersätter dem med lättare, ihåliga bärande delar där ramen tillåter det."},{t="Ökensamlande för fart",b="I stället för att frakta dyr, specialiserad komposit till Thousand Needles vänder sig Pozzik till de omgivande saltslätterna. Gamarna på saltslätterna är talrika, och deras skelett har formats av flykten så att de fått ihåliga, bikakeliknande kärnor med hög draghållfasthet och nästan ingen vikt. Genom att ersätta delar av racerns styranordning och mindre stag med bearbetade gamben hoppas Pozziks mekaniker hålla maskinerna så smidiga att de kan manövrera ifrån gnomerna utan att skaka sönder i toppfart."}},faq={{q="Varför vill Pozzik ha gamben till en racerbil?",a="Goblinernas ingenjörskonst bygger på uppfinningsrikedom och material som råkar finnas till hands. Gamben är ihåliga och naturligt lätta, vilket ger ett utmärkt förhållande mellan styrka och vikt när känsliga delar som styranordningar ska förstärkas utan att racern blir tyngre.",al={"syftet med gamben","varför ben","pozzik ben"}},{q="Vem är Pozzik?",a="Pozzik är ledande mekaniker för goblinernas racinglag och lagledare vid Mirage Raceway i Shimmering Flats. Han leder goblinernas depålag mot deras bittra rivaler, gnomerna.",al={"pozzik","pozzik historia","vem är gobliningenjören"}},{q="Var hittar man gamarna?",a="Asätarna och gamarna kretsar över Shimmering Flats öppna vidder, särskilt kring de väldiga skelettrester som ligger utspridda i saltslättens nordöstra delar.",al={"gamarnas plats","var hittar man ihåliga ben","asätare i shimmering flats"}},{q="Vad är Mirage Raceway?",a="Mirage Raceway är en neutral racingbana på den vidsträckta, torra saltsjön i Thousand Needles. Gobliner och gnomer tävlar där i farliga höghastighetslopp med experimentella raketbilar.",al={"racingbanans historia","vad är mirage raceway","banan i shimmering flats"}},{q="Gör gnomerna samma sak?",a="Gnomerna letar också efter sätt att effektivisera sina racers, men deras ingenjörstradition lutar åt precisionsurverk och komplexa metaller snarare än goblinernas skrapiga modifieringar med återvunnet material.",al={"gnomernas racers","gnomer mot gobliner","använder gnomer ben"}},{q="Hjälper det här Pozzik med hans större racingprojekt?",a="Ja. När du visar att du går att lita på genom att göra racern lättare vinner du Pozziks förtroende. Det leder till fler uppdrag kring rivaliteten på banan och officiellt stöd från gobliner ute på saltslätterna.",al={"fortsättning på uppdraget","what comes next","goblinernas stöd"}}},fx={a8fc0189={q="Varför är Pozzik så fokuserad på att lätta sin racer?",a="På Mirage Raceway är fart allt, och loppen avgörs ofta med en hårsmån. Pozzik tävlar direkt mot gnomisk ingenjörskonst, där varje onödigt kilo kan kosta honom segern på saltslätterna. Genom att skala bort varje överflödigt uns från chassit och styranordningen kan hans raketbil nå maximal acceleration utan att tumma på hållfastheten.",al={"pozziks motiv","varför lätta racern","varför behöver pozzik lätta delar"}},["8208273d"]={q="Varför finns det så många gamar i Shimmering Flats?",a="Shimmering Flats är en ogästvänlig, solstekt vidsträckt slätt, beströdd med resterna av enorma urtidsdjur och fallna vandrare. Saltmarkernas asätare trivs här. De kretsar ovanför och livnär sig på kadavren som det hårda ökenklimatet och slätternas våldsamma basilisker och skorpioner lämnar efter sig.",al={"varför gamar i shimmering flats","lore om gamar i saltslätterna","gamar i thousand needles"}}},fp="15,297,18.473.0,27.492.0,50.239.0,14.182.0,31.185.0,27.198.0,36.206.0,55.175.0"}
P.entries["quest:1177"] = {n="Hungry!",s="Mudcrush Durtfeet, en ogre i norra Dustwallow Marsh, är hungrig. Mud vill att du ska banka på de fiskiga Mirefin och komma tillbaka med deras huvuden, annars äter Mud upp dig i stället.",h="Mudcrush Durtfeet, en ogre i norra Dustwallow Marsh, är hungrig.",kw={"dustwallow marsh","fiskig","hungrig!","mirefin-huvuden","mudcrush durtfeet","ogre"},sec={{t="En hungrig ogre",b="Mudcrush Durtfeet är en stor ogre och säger det rent ut. Mud är hungrig och erbjuder en enkel byteshandel: banka på de fiskiga Mirefin och ta med deras huvuden som mat till Mud. Mätta Mud, annars äter Mud upp dig."}},faq={{q="Vem är Mudcrush Durtfeet?",a="Mudcrush Durtfeet är en stor ogre i norra Dustwallow Marsh som kallas Mud. Mud är hungrig och vill ha mat.",al={"mudcrush durtfeet","vem är mudcrush","ogre i dustwallow"}},{q="Vad vill Mudcrush Durtfeet äta?",a="Mud vill ha Mirefin-huvuden från de fiskiga Mirefin som du blir tillsagd att banka på.",al={"mat till mudcrush","vad vill ogren ha","mat till hungrig uppdragsgivare"}},{q="Vad händer om du vägrar mata honom?",a="Mud är tydlig: mata Mud, annars äter Mud upp dig.",al={"mudcrush hot","kommer mudcrush äta upp mig"}}},fp="7,167,13.184.0,25.107.0,40.82.0,39.49.0"}
P.entries["quest:1178"] = {n="Goblin Sponsorship",s="Pozzik i goblinernas racingteam väntar på en prototyp till bränsleregulatorn som Gazlowe lovade för några veckor sedan, men den har inte kommit. Gazlowe brukar vara mycket punktlig, så Pozzik ber dig åka till Ratchet och fråga vad som hänt, eftersom gnomerna håller på att komma ikapp teamet.",h="Pozzik i goblinernas racingteam väntar på en prototyp till bränsleregulatorn som Gazlowe lovade för några...",kw={"bränsleregulator","gazlowe","mirage raceway","pozzik","ratchet","the shimmering flats","tinkers union","undermine"},sec={{t="En utlovad del",b="Pozzik kallar racingteamet goblinernas stolthet och säger att många hjälper till på ett eller annat sätt. Gazlowe letar upp delar åt teamet från hela världen och kom till och med en gång för att arbeta på ett av deras fordon. För några veckor sedan sa Gazlowe att en ny prototyp till bränsleregulatorn skulle skickas, men inget har kommit, vilket är olikt honom. Eftersom gnomerna håller på att komma ikapp ber Pozzik dig åka till Ratchet och fråga Gazlowe om den."},{t="Om Pozzik",b="När Gazlowe får höra att Pozzik skickat dig säger han att Pozzik räknades till Undermine mest respekterade uppfinnare innan han drog sig tillbaka för att arbeta med racerbilarna. Det första Pozzik gjorde när han gick med i teamet var att konstruera racerbilarna med två motorer. Gazlowe medger att verksamheten kanske går sämre utan Pozzik i Tinkers' Union, men säger att inget slår racen."}},faq={{q="Varför behöver Pozzik att du åker till Ratchet?",a="Gazlowe sa för flera veckor sedan att han skulle skicka en prototyp till bränsleregulatorn, men den har inte kommit. Pozzik ber dig åka till Ratchet och fråga honom om den.",al={"varför ratchet","pozzi ks ärende","goblin sponsorship mål"}},{q="Vad gör Gazlowe för racingteamet?",a="Han letar upp delar åt teamet från hela världen och kom till och med en gång för att arbeta på ett av deras fordon.",al={"gazlowes medverkan","gazlowe sponsor för racet","är gazlowe sponsor"}},{q="Vad kommer före det här?",a="Det följer på Load Lightening, som också ges av Pozzik.",al={"förquest till goblin sponsorship","vilket uppdrag kommer före goblin sponsorship"}},{q="Varför har goblinteamet bråttom?",a="Pozzik säger att gnomerna håller på att komma ikapp dem.",al={"varför bränsleregulatorn är brådskande","gobliner mot gnomer i race"}}},fp="18,266,15.419.0,18.361.1,42.143.0,41.106.0,23.49.0,34.43.0"}
P.entries["quest:1179"] = {n="The Brassbolts Brothers",s="Pilot Longbeard i Ironforge behöver en kurir som kan leverera en låda med förstärkta hjälmar för belägringsmaskiner över havet till Kalimdor. Hans vänner, bröderna Brassbolt, testar snabba raketbilar i The Shimmering Flats och behöver omedelbart huvudskydd åt sina olycksdrabbade testförare.",h="Pilot Longbeard i Ironforge behöver en kurir som kan leverera en låda med förstärkta hjälmar för...",kw={"brassbolt","ironforge","mirage raceway","pilot longbeard","raketbil","the shimmering flats","thousand needles","wizzle brassbolts"},ang={["profession:Engineering"]="En typisk leverans av ingenjörsförnödenheter, där dvärgarnas hantverk med tung rustning möter gnomernas experiment med framdrivning i hög fart.",["race:Dwarf"]="Bara den robusta Siege Engine-rustningen från dvärgarna är tillräckligt tjock för att tåla en gnomisk raketbilskrasch i full fart ute på saltslätterna.",["race:Gnome"]="Bröderna Brassbolts jakt på ren hastighet visar gnomisk ambition när den är som tydligast: mekanisk innovation går före sådana småsaker som bromsar och förarnas livslängd."},sec={{t="En tjänst på långt håll",b="När dvärgflygaren Pilot Longbeard var stationerad bland sina flygmaskiner i Ironforge fick han en brådskande begäran från The Shimmering Flats i södra Kalimdor. Hans vänner, två påhittiga gnomer kända som bröderna Brassbolt, hade slagit sig ner på de vidsträckta saltslätterna för att tävla med experimentella maskiner. Longbeard är upptagen med militära uppgifter och flygtjänst, så han kan inte själv leverera förnödenheterna."},{t="Säkerhet i hög fart",b="Bröderna Brassbolts raketbil visade sig vara otroligt snabb, så snabb att deras testförare gång på gång kraschade över saltslätterna och fick svåra hjärnskakningar. Longbeard skaffar en låda med kraftiga Siege Engine-hjälmar från dvärgarna för att skydda deras huvuden. När lådan levereras får gnomerna det de behöver för att locka tillbaka motvilliga förare bakom ratten på sin oberäkneliga fartmaskin."}},faq={{q="Vem är Pilot Longbeard?",a="Pilot Longbeard är en dvärgflygare i Ironforge. Han känner bröderna Brassbolt och är deras leverantörskontakt i Eastern Kingdoms, där han skaffar fram kraftig dvärgutrustning som de inte lätt kan tillverka ute i fält.",al={"pilot longbeard","uppdragsgivare","vem ger det här uppdraget"}},{q="Vilka är bröderna Brassbolt?",a="Bröderna Brassbolt, däribland Wizzle Brassbolts, är ambitiösa gnomingenjörer som har etablerat sig vid Mirage Raceway i The Shimmering Flats. De tillbringar dagarna med att konstruera och trimma avancerade raketbilar för att köra ifrån sina goblinrivaler.",al={"bröderna brassbolt","wizzle brassbolts","gnombröder"}},{q="Var ligger The Shimmering Flats?",a="The Shimmering Flats är en vidsträckt, solstekt saltslätt i södra Kalimdor, bortom de höga kanjonpelarna i Thousand Needles. Den öppna ytan utan hinder gör platsen idealisk för att testa experimentella fordon i hög fart.",al={"var ligger the shimmering flats","vart ska leveransen","var ligger kapplöpningsbanan"}},{q="Varför behöver gnomerna Siege Engine-hjälmar?",a="Bröderna Brassbolts raketbil kommer upp i enorma hastigheter, men styrning och stabilitet lämnar mycket övrigt att önska. Förarkrascher och hjärnskakningar blev så vanliga att inga testförare ville sätta sig bakom ratten utan ordentligt huvudskydd från dvärgarna.",al={"varför hjälmar","krockhjälmar","raketbilskrascher"}},{q="Varför levererar inte Longbeard hjälmarna själv?",a="Pilot Longbeard är upptagen med sina militära skyldigheter och uppgifter i Ironforge. En lång resa över Great Sea till södra Kalimdor skulle innebära att han övergav sin post, så han förlitar sig på resande äventyrare för att frakta den tunga lådan.",al={"varför inte longbeard","longbeards uppgifter"}},{q="Kan spelare från Horde utföra uppdraget?",a="Nej. Uppdraget kommer från Pilot Longbeard i Alliansens huvudstad Ironforge och är endast tillgängligt för kurirer från Alliansen, även om Mirage Raceway välkomnar båda fraktionerna.",al={"är uppdraget endast för alliansen","horde-version","fraktion"}}},fp="23,296,21.426.0,23.411.0,23.242.0,32.258.0,30.242.0,44.260.0,43.238.0,37.181.0"}
P.entries["quest:118"] = {n="The Price of Shoes",s="Verner Osgood, smeden i Lakeshire, har använt allt sitt järn till att laga utrustning åt stadsvakten, som kämpar hårt. Nu när inget järn återstår till att sko traktens hästar skickar han ett bud genom Elwynn Forest för att be Smith Argus i Goldshire om hjälp.",h="Verner Osgood, smeden i Lakeshire, har använt allt sitt järn till att laga utrustning åt stadsvakten, som...",kw={"elwynn","goldshire","hästskor","järn","lakeshire","redridge","smith argus","verner osgood"},ang={["faction:Alliance"]="Att Lakeshire är beroende av Goldshire visar hur hårt rikets logistik är ansträngd under regentskapet i Stormwind.",["profession:Blacksmithing"]="Begäran visar de hårda materiella villkoren för smeder i gränslandet, där en hantverkare måste prioritera soldaternas överlevnad framför vanliga gårdar."},sec={{t="En gränsby pressad till bristningsgränsen",b="Lakeshire ligger mitt i skottlinjen för gnoller, orcher och murlocker, men Stormwind erbjuder knappt någon förstärkning. Den lokala garnisonen måste kämpa varje dag för att hålla staden från att falla, och striderna sliter snabbt på utrustningen. Verner Osgood tillbringar nästan varje vaken timme med att laga buckliga harnesk, räta ut slöa svärd och se till att stadsvakterna har järn på kroppen. Under tiden tömmer han sitt förråd av råmaterial."},{t="Försörjningsvägar till Elwynn",b="När en gränsbosättning får helt slut på järn stannar även vardagliga sysslor upp. Utan hästskor kan budbärare inte rida snabbt mellan stationerna, och dragdjur kan inte frakta förnödenheter längs Redridges steniga vägar. Verner måste svälja sin stolthet och vädja till hjärtlandet. Han skickar resande västerut längs vägen Three Corners till Goldshire, där Smith Argus fortfarande har god tillgång till rikets stora mineralförråd."}},faq={{q="Varför har Verner slut på järn?",a="Stadsvakterna i Lakeshire utsätts ständigt för angrepp från Redridges fientliga djurliv, gnoller och Blackrock-orcher. Verner har lagt allt sitt järnförråd på att laga deras sönderslagna rustningar och vapen, så inget återstår för civilbefolkningens behov.",al={"varför inget järn","verner slut på metall","järnbrist i lakeshire"}},{q="Vem är Smith Argus?",a="Smith Argus är Goldshires lokala smed i Elwynn Forest. Hans smedja ligger nära rikets livliga centrum, och där är det mycket lättare att få tag på tackjärn och förnödenheter än i gränsbyar som Lakeshire.",al={"argus i goldshire","vem är argus","smed i goldshire"}},{q="Varför får Lakeshire inga förnödenheter från Stormwind?",a="Stormwinds härskare har fastnat i politisk handlingsförlamning medan kung Varian Wrynn fortfarande är försvunnen. När adelsrådet håller inne med trupper och pengar lämnas gränsbyar som Lakeshire till stor del åt sig själva och får förlita sig på den regionala handel de kan få till stånd.",al={"varför ingen hjälp från stormwind","lakeshire ignoreras","stormwind försummar"}},{q="Varför är hästskor så viktiga i Redridge?",a="Redridges steniga och obarmhärtiga terräng sliter snabbt sönder hov på oskodda djur. Utan hästskor blir budhästar, förnödenhetsvagnar och patrullhästar halta, vilket skär av Lakeshire från resten av riket.",al={"varför behövs hästskor","varför hästskor är viktiga"}},{q="Vad händer när man når Smith Argus?",a="Argus tar emot Verners meddelande och ger dig en leverans hästskor att bära tillbaka till Lakeshire. Då öppnas fler uppgifter som hjälper dig att säkra den hårt ansatta bosättningen.",al={"nästa uppdrag","vad händer efter argus"}},{q="Var finns Smith Argus i Goldshire?",a="Du hittar honom vid den utomhussmedja där han arbetar, nära Lion's Pride Inn i Goldshire, strax intill huvudvägen genom Elwynn Forest.",al={"var finns argus","argus plats"}}},fx={["24418d93"]={q="Varför skickar Verner dig i stället för att själv gå eller skicka en vakt?",a="Verner är Lakeshires främste smed och kan inte lämna sin smedja när stadens försvar redan är hårt ansträngt. Redridge är belägrat av gnoller och orcher, så varje lokal vakt behövs på murarna och längs bron. När de lokala försörjningslederna är helt uttänjda får dugliga resande äventyrare som du ta sig hela vägen genom Elwynn Forest.",al={"varför skicka mig","varför går inte verner själv","varför inte skicka en vakt"}}},fp="18,180,32.368.0,22.325.0,26.194.0,19.149.0,48.244.0,43.186.0,40.123.0,42.114.0"}
P.entries["quest:1180"] = {n="Goblin Sponsorship",s="Gazlowe återgår till ärendet du kom hit för: bränsleregulatorn som utlovats till Pozzik har inte kommit fram till Ratchet. Revilgaz i Booty Bay sa att han skulle skicka den, men den kan ha kommit bort i hanteringen. Gazlowe skickar dig till Wharfmaster Lozgil där, som kan kontrollera fraktjournalerna.",h="Gazlowe återgår till ärendet du kom hit för: bränsleregulatorn som utlovats till Pozzik har inte kommit fram...",kw={"booty bay","bränsleregulator","gazlowe","goblin sponsorship","mirage raceway","pozzik","ratchet","revilgaz","wharfmaster lozgil"},sec={{t="En del som aldrig kom",b="Gazlowe medger att han lovade Pozzik en ny bränsleregulator, men att han fortfarande inte har fått den. Revilgaz i Booty Bay sa att han skulle skicka den, men den kan ha kommit bort i hanteringen. I så fall finns det inte mycket att göra, men du kan åtminstone ta reda på om den lämnade Booty Bay. Wharfmaster Lozgil, längst bort i den nordvästra änden av Booty Bays hamn, kan gå igenom fraktjournalerna."},{t="Hamnherrens journaler",b="Lozgil kontrollerar liggarna över försändelser till Ratchet. Den senaste var stövlar från Drizzlik, och i övrigt har det bara skickats byggmaterial och verktyg. Inga tävlingsdelar fanns med."}},faq={{q="Vilken del saknas?",a="Gazlowe lovade Pozzik en ny bränsleregulator, men Gazlowe har inte fått den ännu.",al={"del till pozzik","varför bränsleregulator","försändelse till pozzik"}},{q="Vem sa att de skulle skicka regulatorn till Ratchet?",a="Revilgaz i Booty Bay sa att han skulle se till att den skickades till Gazlowe i Ratchet.",al={"vem skickar delen","del från revilgaz","vem har bränsleregulatorn"}},{q="Vem för fraktjournalerna i Booty Bay?",a="Wharfmaster Lozgil, som kan gå igenom fraktjournalerna. Han finns längst bort i den nordvästra änden av Booty Bays hamn.",al={"fraktmästare i booty bay","vem är wharfmaster lozgil","var finns lozgil"}},{q="Var i kedjan passar det här steget in?",a="Det följer efter den första Goblin Sponsorship, där Pozzik skickade dig till Gazlowe, och nästa steg är Goblin Sponsorship (3).",al={"goblin sponsorship-kedjan","uppdragsförlopp","vad kommer före detta"}}},fp="18,290,22.386.0,25.183.1,21.82.0,50.79.0,44.117.0,38.122.0"}
P.entries["quest:1181"] = {n="Goblin Sponsorship",s="Wharfmaster Lozgil kan inte hjälpa dig mer med den saknade bränsleregulatorn och föreslår att du frågar Baron Revilgaz själv. Du hittar baronen på översta våningen i värdshuset på andra sidan hamnen i Booty Bay.",h="Wharfmaster Lozgil kan inte hjälpa dig mer med den saknade bränsleregulatorn och föreslår att du frågar Baron...",kw={"baron revilgaz","booty bay","bränsleregulator","goblin sponsorship","mirage raceway","ratchet","wharfmaster lozgil"},sec={{t="Fråga baronen",b="Wharfmaster Lozgil säger att han inte kan hjälpa dig mycket mer med att spåra den saknade försändelsen till Ratchet. Om du vill följa upp saken föreslår han att du går till baronen själv, eftersom ingen känner till Revilgaz affärer bättre än Revilgaz. Han väntar på översta våningen i värdshuset på andra sidan hamnen."},{t="Baronens svar",b="Baron Revilgaz vet vad du menar, men kan inte hjälpa dig. Några av hans män skickades för att hitta ritningarna till bränsleregulatorn, men de kom tillbaka tomhänta."}},faq={{q="Var hittar jag Baron Revilgaz?",a="På översta våningen i värdshuset på andra sidan hamnen i Booty Bay.",al={"baron revilgaz plats","var finns revilgaz","hitta revilgaz i booty bay"}},{q="Varför skickar Wharfmaster Lozgil dig till Revilgaz?",a="Lozgil kan inte hjälpa dig mycket mer och säger att ingen känner till Revilgaz affärer bättre än Revilgaz själv.",al={"varför prata med revilgaz","lozgil skickar till baronen","varför träffa baron revilgaz"}},{q="Vilken försändelse spårar man?",a="En ny bränsleregulator som skulle ha nått Ratchet, avsedd för goblinförarna på Mirage Raceway.",al={"vilken försändelse saknas","vad letar vi efter","saknat gods till ratchet"}},{q="Var passar det här steget in i kedjan?",a="Det följer på Goblin Sponsorship (2), ditt samtal med Wharfmaster Lozgil, och nästa steg är Goblin Sponsorship (4).",al={"vad hände före goblin sponsorship 3","goblin sponsorship kedjans framsteg"}}},fp="18,151,16.244.0,18.141.1,32.80.0,49.94.0,36.100.0,38.115.0"}
P.entries["quest:1182"] = {n="Goblin Sponsorship",s="Baron Revilgaz berättar att Venture Companys skördare vid Lake Nazferiti i norra Stranglethorn har en ny modell av bränsleregulator som Pozzik skulle kunna använda. Förman Cozzle har visat sig vara slugare än baronen väntade sig, så Revilgaz skickar dig för att hitta ritningarna.",h="Baron Revilgaz berättar att Venture Companys skördare vid Lake Nazferiti i norra Stranglethorn har en ny...",kw={"baron revilgaz","ritningar","förman cozzle","bränsleregulator","goblin sponsorship","lake nazferiti","mirage raceway","pozzik","venture company"},ang={["class:Rogue"]="En rogue kan dyrka upp låset på lådan med ritningarna utan att behöva förmannens nyckel."},sec={{t="Förmannens ritningar",b="Baron Revilgaz förklarar att Venture Companys skördare vid Lake Nazferiti, i norra Stranglethorn, har en ny modell av bränsleregulator. Pozzik skulle kunna dra nytta av den om han hade detaljerna, men Cozzle, förmannen där, är slugare än Revilgaz trodde. Du kanske har större tur. Revilgaz vet att ritningarna finns i Cozzles hus, nästan säkert inlåsta. Venture Company håller till kring Lake Nazferiti, i dalens nordöstra hörn. Nyckeln finns hos förman Cozzle i stugan högst upp i oljetornet, och lådan med ritningarna finns i det lilla huset nära tornets fot. Revilgaz medger att gnomlaget där ute är ganska bra och säger att laget behöver alla fördelar det kan få."},{t="En kopia åt baronen",b="Med ritningarna i handen vill Revilgaz ha en kopia till sina egna anteckningar. Sedan skickar han dig vidare till Pozzik, så att Pozzik inte tror att en av hans sponsorer har övergett honom."}},faq={{q="Varför vill Baron Revilgaz ha ritningar till en bränsleregulator?",a="Venture Companys skördare vid Lake Nazferiti har en ny modell av bränsleregulator, och Revilgaz tror att Pozzik skulle kunna dra nytta av den om han hade detaljerna.",al={"varför stjäla ritningar","varför bränsleregulator","revilgaz motiv"}},{q="Var finns ritningarna?",a="I en låda inne i ett litet hus vid oljetornets fot, vid Venture Companys bas vid Lake Nazferiti i norra Stranglethorn.",al={"var finns ritningarna","bränsleregulatorns ritningar plats","cozzles hus"}},{q="Vem har nyckeln?",a="Förman Cozzle har den och arbetar i stugan högst upp i oljetornet.",al={"cozzles nyckel","var är nyckeln","hur öppnar man kistan"}},{q="Var passar det här steget in i kedjan?",a="Det följer på Goblin Sponsorship (3), där Wharfmaster Lozgil skickade dig till baronen. Nästa steg är Goblin Sponsorship (5).",al={"vad kommer före detta","vilket uppdrag är nästa","goblin sponsorship kedja"}}},fp="18,259,24.743.0,20.166.1,55.159.0,30.135.0,18.69.0,38.126.0"}
P.entries["quest:1183"] = {n="Goblin Sponsorship",s="Baron Revilgaz har Fuel Regulator Blueprints redo och skickar dem till Pozzik på The Shimmering Flats. Han framför sina hälsningar och tillägger att Pozzik inte ska tveka att fråga om han någon gång behöver något.",h="Baron Revilgaz har Fuel Regulator Blueprints redo och skickar dem till Pozzik på The Shimmering Flats.",kw={"baron revilgaz","fuel regulator blueprints","goblin sponsorship","mirage raceway","pozzik","the shimmering flats","thousand needles"},sec={{t="Hälsningar till Pozzik",b="Baron Revilgaz säger att allt är klart. Du tar ritningarna till Pozzik ute på The Shimmering Flats, med baronens hälsningar och ett meddelande: om Pozzik någon gång behöver något ska han inte tveka att fråga. Revilgaz säger att han väntar på nyheter om att Pozzik slår banrekordet."},{t="Förbättra konstruktionen",b="Pozzik hade hoppats att regulatorn redan skulle vara monterad. Ändå ser han en chans att förbättra konstruktionen från grunden. Han planerar att skissa på förbättrade ritningar, bygga delen och få den installerad snart."}},faq={{q="Vem skickar dig med ritningarna?",a="Baron Revilgaz skickar dig från Booty Bay med sina hälsningar till Pozzik.",al={"vem ger goblin sponsorship 5","uppdragsgivare","revilgaz uppdrag"}},{q="Vem tar emot Fuel Regulator Blueprints?",a="Pozzik på The Shimmering Flats.",al={"var ska jag lämna ritningarna","vem får ritningarna","pozziks plats"}},{q="Vad hoppas Baron Revilgaz få höra?",a="Han säger att han väntar på nyheter om att Pozzik slår banrekordet.",al={"revilgaz motivation","baron revilgaz sponsor"}},{q="Vad föregår den här leveransen?",a="Den följer på Goblin Sponsorship (4), där du hämtade ritningarna åt Revilgaz. Nästa steg är The Eighteenth Pilot.",al={"föregående uppdrag","vad ledde fram till detta","goblin sponsorship uppdragskedja"}}},fp="18,200,18.282.0,20.207.1,34.69.0,43.32.0,38.72.0,32.123.0"}
P.entries["quest:1184"] = {n="Parts of the Swarm",s="Korran har ett meddelande till Belgrom Rockmaul i Orgrimmar. Du ska föra tillbaka beskedet att Moktar sköter sig väl ute i Thousand Needles och att Korrans studier går framåt.",h="Korran har ett meddelande till Belgrom Rockmaul i Orgrimmar.",kw={"belgrom rockmaul","korran","moktar","orgrimmar","parts of the swarm","rustmaul digsite","silithider","thousand needles"},sec={{t="Besked till Orgrimmar",b="Efter de spruckna ryggsköldar som togs från silithiderna vid Rustmaul Digsite skickar Korran dig tillbaka till Belgrom Rockmaul i Orgrimmar. Berätta för Belgrom att Moktar sköter hans uppdrag väl ute i Thousand Needles. Säg också att Korrans studier går framåt och att han hoppas få veta mer snart."},{t="Belgroms svar",b="Belgrom Rockmaul är tacksam för dina insatser och säger att hövdingen blir glad att höra hur ihärdig du har varit. Han lovar att nämna ditt namn och säger att Thrall ofta talar med honom och värdesätter hans åsikter. Om Korran har nyheter om silithiderna vill Belgrom höra dem, eftersom han anser att de utgör ett allvarligt hot."}},faq={{q="Vem skickar dig till Orgrimmar?",a="Korran, som har studerat silithiderna, ber dig föra tillbaka besked till Belgrom Rockmaul i Orgrimmar.",al={"uppdragsgivare","vem startar uppdraget","vem gav parts of the swarm"}},{q="Vem ska du lämna meddelandet till?",a="Belgrom Rockmaul i Orgrimmar.",al={"vem ska jag träffa","vart ska jag gå","belgrom rockmauls plats"}},{q="Vilket meddelande vill Korran att du framför?",a="Att Moktar sköter Belgroms uppdrag väl ute i Thousand Needles och att Korrans studier går framåt, med mer att lära snart.",al={"vad är meddelandet","korrans rapport"}},{q="Vilka varelser studerar Korran?",a="De är silithider. De spruckna ryggsköldarna som satte arbetet i gång kom från silithider vid Rustmaul Digsite i Thousand Needles.",al={"vilka är varelserna","varför studera svärmen"}}},fp="18,179,18.297.0,15.317.1,27.105.0,47.31.0,40.141.0,42.132.0"}
P.entries["quest:1186"] = {n="The Eighteenth Pilot",s="Pozzik kommer att ha fullt upp med att montera den nya bränsleregulatorn i racerbilarnas konstruktioner, men föreslår att du hjälper teamet vidare genom att tala med Razzeric på The Shimmering Flats. Razzeric är teamets pilot, den artonde i ordningen, och gillar att göra ändringar på racerbilarna.",h="Pozzik kommer att ha fullt upp med att montera den nya bränsleregulatorn i racerbilarnas konstruktioner, men...",kw={"goblin","pilot","pozzik","racerbana","razzeric","the shimmering flats","thousand needles"},sec={{t="Träffa piloten",b="Pozzik säger att bränsleregulatorn håller honom sysselsatt, men du kan hjälpa teamet ytterligare genom att tala med Razzeric på The Shimmering Flats. Razzeric är faktiskt teamets artonde pilot och gillar att göra egna små ändringar på racerbilarna. Pozzik tillägger att Razzeric är lite från vettet, så försök att inte verka alltför förvånad."},{t="En pilot minns",b="Razzeric vet att du har hjälpt Pozzik och säger att han en gång var som du, sprang runt i depån och hjälpte till med alla jobb som mekanikerna lät honom komma nära. Nu är han goblinernas raceteams främsta pilot."}},faq={{q="Vem är Razzeric?",a="Razzeric är en goblin och pilot för goblinernas raceteam på The Shimmering Flats. Pozzik kallar honom teamets artonde pilot.",al={"vem är den artonde piloten","razzerics bakgrund","goblinpilot"}},{q="Varför skickar Pozzik dig till Razzeric?",a="Pozzik har fullt upp med att integrera den nya bränsleregulatorn i racerbilarnas konstruktioner och föreslår att du hjälper teamet vidare genom att tala med Razzeric.",al={"varför tala med razzeric","pozzik artonde pilot"}},{q="Hurdan är Razzeric?",a="Pozzik säger att Razzeric gillar att göra egna små ändringar på racerbilarna och är lite från vettet.",al={"razzerics personlighet","är razzeric galen"}},{q="Vad hände före detta?",a="Det här följer på Goblin Sponsorship (5), där du levererade Fuel Regulator Blueprints till Pozzik.",al={"förutsättning för den artonde piloten","uppdragskedjan före razzeric"}}},fp="20,261,14.352.0,17.215.1,16.128.0,37.144.0,22.106.0,22.100.0"}
P.entries["quest:1187"] = {n="Razzeric's Tweaking",s="På Shimmering Flats gör Razzeric egna ändringar på racerbilarna när Pozzik är klar med dem. En seaforiumförstärkare som beställts från Shreev i Gadgetzan var ombord på ett zeppelin som Razzeric hört kraschade i Dustwallow Marsh, och Razzeric vill ha den tillbaka.",h="På Shimmering Flats gör Razzeric egna ändringar på racerbilarna när Pozzik är klar med dem.",kw={"dustwallow marsh","gadgetzan","gizmorium","pozzik","razzeric","seaforiumförstärkare","the shimmering flats","shreev","thousand needles"},sec={{t="Mer kräm",b="Razzeric medger att Pozzik är en skicklig mekaniker, men tycker att Pozzik är för försiktig med att lassa på eldkraft och bara hålla i sig. När Pozzik är klar med en racerbil ägnar Razzeric tid åt personliga ändringar: gör kontrollerna lösare, tar bort delar av ramen och ökar kraften. En seaforiumförstärkare beställdes från Shreev på Gizmorium i Gadgetzan, men zeppelinaren som fraktade den kraschade i Dustwallow Marsh, enligt Razzeric. Förstärkaren behövs tillbaka på Shimmering Flats, eftersom det vore en katastrof att dyka upp på banan utan den extra kraften."},{t="Fastspänd på racerbilen",b="Razzeric hyllar förstärkaren: hela femton pund seaforium. Fastspänd vid sidan av en racerbil borde den ta Razzeric genom banan i sådan fart att nissarna blir slagna två gånger om."}},faq={{q="Vem är Razzeric?",a="Razzeric är en racerförare på Shimmering Flats som gör egna ändringar på racerbilarna när Pozzik är klar med dem.",al={"razzeric","vem ger razzeric sina ändringar","razzeric shimmering flats"}},{q="Var kom förstärkaren ifrån?",a="Razzeric beställde den från Shreev på Gizmorium i Gadgetzan.",al={"var kom förstärkaren ifrån","vem tillverkade seaforiumförstärkaren","gizmorium i gadgetzan"}},{q="Var finns seaforiumförstärkaren nu?",a="Razzeric säger att zeppelinaren som fraktade den kraschade i Dustwallow Marsh.",al={"var finns seaforiumförstärkaren","förstärkarens plats","platsen för den störtade zeppelinaren"}},{q="Varför vill Razzeric ha förstärkaren?",a="Razzeric vill ha mer kraft än Pozzik är villig att lassa på, och tycker att det vore en katastrof att möta banan utan den extra kraften.",al={"varför vill han ha seaforium","varför seaforiumförstärkare"}},{q="Vad kom före det här steget?",a="The Eighteenth Pilot kom först.",al={"föregående uppdrag","förutsättning","vad leder till razzerics tweaking"}}},fp="19,263,10.560.0,21.199.1,16.113.0,32.57.0,35.67.0,35.133.0,27.32.0"}
P.entries["quest:1188"] = {n="Safety First",s="Razzeric har upptäckt att Shreev lämnade säkerhetsspärren på seaforiumförstärkaren. Den begränsar kraften Razzeric får ut av förstärkaren, och Razzeric hade bett att den skulle tas bort. Du skickas till Shreev i Gadgetzan, i Tanaris.",h="Razzeric har upptäckt att Shreev lämnade säkerhetsspärren på seaforiumförstärkaren.",kw={"gadgetzan gizmorium","razzeric","safety first","seaforiumförstärkare","the shimmering flats","shreev","tanaris"},sec={{t="En säkerhetsspärr ingen ville ha",b="Razzeric granskar seaforiumförstärkaren och upptäcker att säkerhetsspärren fortfarande är på. Den begränsar kraften förstärkaren kan ge, och Razzeric hade sagt till Shreev att den skulle vara av. Razzeric ger dig förstärkaren och skickar dig söder om The Shimmering Flats, ut i Tanaris öken, till Gadgetzan Gizmorium, så att Shreev kan ta bort spärren."},{t="Shreevs svar",b="Gizmorium erbjuder service för alla dina finmekaniska behov. När du lämnar över förstärkaren nekar Shreev till att ha satt dit någon säkerhetsspärr. Enligt Shreev består förstärkaren nästan helt av sprängämnet seaforium och har redan modifierats så att mer av laddningen levereras när den används. Shreev säger att Razzeric aldrig är nöjd om han inte drar det hela vägen till elva."}},faq={{q="Vem skickar dig till Gadgetzan?",a="Razzeric, goblinpiloten, skickar dig till Gadgetzan med sin seaforiumförstärkare.",al={"uppdragsgivare","vem startar safety first","razzerics uppdrag"}},{q="Varför är Razzeric missnöjd med förstärkaren?",a="Shreev lämnade säkerhetsspärren på. Den begränsar kraften Razzeric får ut av förstärkaren, och Razzeric hade bett att den skulle tas bort.",al={"varför klagar razzeric","problem med förstärkaren","vad är fel på förstärkaren"}},{q="Var finns Shreev?",a="Shreev finns i Gadgetzan, på Gizmorium, ute i Tanaris öken söder om The Shimmering Flats.",al={"shreevs plats","var finns shreev","gadgetzan gizmoriums plats"}},{q="Vilket föremål tar du med till Gadgetzan?",a="Du bär med dig Razzerics seaforiumförstärkare, som Razzeric ger dig att ta till Shreev.",al={"vilket föremål","förstärkarföremål","vad tar du med till shreev"}},{q="Vad händer efter den här leveransen?",a="Uppdragskedjan fortsätter med en andra del, som också heter Safety First.",al={"nästa uppdrag","vad följer efter safety first","fortsättning på safety first"}}},fp="12,220,22.321.0,15.350.1,27.78.0,41.123.0,26.98.0,40.84.0,31.65.0"}
P.entries["quest:1189"] = {n="Safety First",s="Shreev har gjort som Razzeric ville med seaforiumförstärkaren, och du tar den modifierade förstärkaren tillbaka till Razzeric på The Shimmering Flats. Shreevs varning: var försiktig när du utlöser den, för ett enda misstag kan göra Razzeric till en svedd fläck på banan. Det här följer den första Safety First.",h="Shreev har gjort som Razzeric ville med seaforiumförstärkaren, och du tar den modifierade förstärkaren...",kw={"gadgetzan","pozzik","razzeric","safety first","seaforiumförstärkare","the shimmering flats","shreev","thousand needles"},sec={{t="En varning från Shreev",b="Shreev räcker över den modifierade förstärkaren, utförd enligt Razzerics önskemål. Shreevs varning: Razzeric måste vara försiktig när han utlöser den. Ett enda misstag, så kommer han inte att rusa framåt; han blir en svedd fläck på banan. Shreev tillägger att det vore synd och undrar om den nittonde föraren hade varit något att ha."},{t="Sand under sitsen",b="Tillbaka på The Shimmering Flats muttrar Razzeric om Pozzik, som lastade en hink sand på racerbilen. Hur ska han kunna nå toppfart med sand under sitsen, undrar Razzeric."},{t="Förstärkaren återlämnad",b="Razzeric är nöjd med den modifierade förstärkaren. Han önskar att han kunde se gnomernas miner när han utlöser den, men räknar med att vara alldeles för upptagen med att sätta banrekord."}},faq={{q="Vem skickar tillbaka den modifierade förstärkaren till The Shimmering Flats?",a="Shreev slutför arbetet med seaforiumförstärkaren i Gadgetzan och ger den till dig att ta tillbaka till Razzeric på The Shimmering Flats.",al={"vem ger safety first två","shreev uppdragsgivare","vem modifierar förstärkaren"}},{q="Vad varnar Shreev för?",a="Shreev säger att Razzeric bör vara försiktig när han utlöser förstärkaren. Ett enda misstag, så kommer han inte att rusa framåt; han blir en svedd fläck på banan.",al={"är förstärkaren farlig","shreevs varning","risk med förstärkaren"}},{q="Varför är Razzeric upprörd över sitt fordon?",a="Pozzik lastade en hink sand på racerbilen, och Razzeric undrar hur han ska kunna nå toppfart med sand under sitsen.",al={"varför är razzeric arg","pozziks hink med sand","razzerics klagomål"}}},fp="12,302,21.329.0,19.188.0,20.176.1,49.133.0,28.149.0,40.119.0"}
P.entries["quest:119"] = {n="Return to Verner",s="Du bär femtio nyss smidda hästskor från Goldshire tillbaka till Lakeshire. Smith Argus har färdigställt beställningen, och Verner Osgood väntar på andra sidan gränsen i Redridge.",h="Du bär femtio nyss smidda hästskor från Goldshire tillbaka till Lakeshire.",kw={"crate of horseshoes","elwynn forest","goldshire","lakeshire","redridge","smith argus","priset på hästskor","verner osgood"},ang={["faction:Alliance"]="Som medlem av Alliansen hjälper du till att hålla avlägsna bosättningar som Lakeshire förbundna med kungarikets hjärta genom försörjningsleder mellan Elwynn Forest och Redridge.",["profession:Blacksmithing"]="Som smed vet du att gränsposteringarnas riddjur behöver jämn tillgång på hästskor när de lokala smedjorna är överbelastade av kriget."},sec={{t="Ett bud över gränsen",b="Smith Argus har smitt femtio hästskor åt Lakeshire, och du för dem österut från Goldshire. Redridge lider av brist på förnödenheter och gnollattacker. Järnskorna hjälper hästar och dragdjur att arbeta på de karga bergsvägarna."},{t="Lappen på lådan",b="Verner Osgood blir lättad när hästskorna kommer fram, men Smith Argus har fäst en räkning på lådan. Verner irriterar sig över att smeden i Goldshire förväntar sig betalning. Redridge står inför akuta faror, så det finns ont om tid att gräla om kostnaden."}},faq={{q="Var ska jag lämna Crate of Horseshoes?",a="Ta lådan till Verner Osgood i Lakeshire, i Redridge Mountains strax öster om bron och bryggorna vid sjön.",al={"var finns verner","plats för inlämning","vem får hästskorna"}},{q="Vem skickade den här leveransen tillbaka till Redridge?",a="Smith Argus, smeden utanför Lion's Pride Inn i Goldshire, skickar lådan när han har färdigställt hästskorna.",al={"vem gav uppdraget","smith argus","uppdragsgivare"}},{q="Varför blir Verner upprörd när han får lådan?",a="Smith Argus bifogade en räkning och kräver betalning för alla femtio hästskor, vilket irriterar Verner. Han hade tydligen hoppats på en kostnadsfri tjänst eller bättre villkor.",al={"varför är verner arg","argus lapp","verners reaktion"}},{q="Vilka uppdrag blir tillgängliga när leveransen är klar?",a="Efter leveransen erbjuder Verner arbete mot lokala hot: jaga Redridge-gnollarna i 'A Baying of Gnolls' och hämta 'Underbelly Scales'.",al={"nästa uppdrag","fortsättningsuppdrag","vad låses upp"}},{q="Varför behöver Lakeshire förnödenheter från Goldshire?",a="Gnoller och Blackrock-orcher belägrar Lakeshire och överbelastar de lokala hantverkarna. Staden behöver ofta vardagsvaror som hästskor i stora mängder från lugnare platser som Goldshire.",al={"varför hästskor från elwynn","varför importera hästskor","förnödenheter till redridge"}},{q="Följer Smith Argus med dig tillbaka till Redridge?",a="Nej. Smith Argus stannar vid sin smedja i Goldshire medan du bär lådan till Redridge.",al={"följer argus med","eskortera smeden argus"}}},fx={a0846e84={q="Varför vill Smith Argus att du levererar den här lådan till Verner?",a="Smith Argus uppfyller Verner Osgoods brådskande begäran om femtio hästskor, men inte av ren välvilja. Han har packat dem i en låda och bifogat en tydlig räkning för arbete och material. Genom att låta dig sköta leveransen får Redridge sina förnödenheter, samtidigt som Verner får veta att järnarbetet i Goldshire inte är gratis.",al={"varför skickar argus hästskor","smith argus motiv","varför hästskor till verner från argus"}},f67540ab={q="Varför ber Smith Argus dig bära hästskorna i stället för att leverera dem själv?",a="Argus är Goldshires lokala smed och måste hålla sig vid städet och smedjan för att utrusta resande och lokala vakter. Att släpa en tung låda med femtio järnhästskor genom Redridgepassen tar tid från arbetet och utsätter en ensam hantverkare för gnoller och banditer längs vägen. Du är en duglig äventyrare som redan är på väg österut.",al={"varför levererar inte argus skorna","varför jag i return to verner","varför skicka spelaren till lakeshire"}}},fp="16,156,27.247.0,21.257.0,40.115.0,40.118.0,47.154.0,51.142.0,57.178.0,48.86.0"}
P.entries["quest:1190"] = {n="Keeping Pace",s="Pozzik är säker på att bröderna Brassbolts har hittat ett nytt byggmaterial. Deras bilar går snabbare än tidigare, men ritningarna och övriga uppgifter från deras körningar är oförändrade. Rizzle Brassbolts har nästan hela tiden varit helt uppslukad av planerna för den här upptäckten, och Zamek kan skapa en avledning så att du kan stjäla dem. Detta följer på News for Fizzle.",h="Pozzik är säker på att bröderna Brassbolts har hittat ett nytt byggmaterial.",kw={"brassbolts","avledning","pozzik","racerbil","rizzle brassbolts","schematics","the shimmering flats","thousand needles","zamek"},sec={{t="Snabbare än siffrorna visar",b="Pozzik kan bara hitta en förklaring till att bröderna Brassbolts bilar har blivit så snabba: ett nytt byggmaterial. Deras ritningar och allt som samlats in från körningarna ser likadant ut som förut. Det enda man vet är att Rizzle Brassbolts nästan hela tiden varit helt uppslukad av planerna för den här upptäckten."},{t="En avledning från Zamek",b="Zamek kan skapa en avledning, och medan den varar stjäl du Rizzles planer. Pozzik på The Shimmering Flats vill ha dem."},{t="Den stulna skriftrullen",b="Planerna visar sig vara en skriftrulle med anteckningar och ritningar, hastigt nedklottrade, om hur man förädlar något råmaterial."}},faq={{q="Varför vill Pozzik ha Rizzles planer?",a="Bröderna Brassbolts bilar går snabbare, medan deras ritningar och uppgifter förblir desamma. Pozzik drar slutsatsen att de har hittat ett nytt byggmaterial och vill ha planerna som Rizzle varit så uppslukad av.",al={"pozziks motiv","varför stjäla brassbolts planer","orsaken till keeping pace"}},{q="Vem hjälper till att distrahera Rizzle Brassbolts?",a="Zamek kan skapa en avledning, så att du får chansen att stjäla Rizzles planer.",al={"vem skapar avledningen","zameks roll","hur distrahera rizzle"}},{q="Åt vem stjäls planerna?",a="Åt Pozzik, som befinner sig på The Shimmering Flats i Thousand Needles.",al={"var är keeping pace","keeping pace plats"}},{q="Vad kommer före det här steget?",a="Det följer på News for Fizzle.",al={"förutsättning för keeping pace","vilket uppdrag föregår keeping pace"}},{q="Vad följer efter att planerna säkrats?",a="Kedjan fortsätter med Rizzle's Schematics.",al={"vilket uppdrag kommer härnäst","efter keeping pace"}}},fp="12,355,27.304.0,22.126.0,17.108.1,36.196.0,37.76.0,29.63.0,28.27.0,38.45.0"}
P.entries["quest:1191"] = {n="Zamek's Distraction",s="Zamek kan skapa avledningen som Keeping Pace kräver. Det sker medan du håller på med det steget, och Keeping Pace kan inte slutföras utan den.",h="Zamek kan skapa avledningen som Keeping Pace kräver.",kw={"avledning","keeping pace","thousand needles","zamek"},sec={{t="En väl tajmad avledning",b="Medan du arbetar dig igenom Keeping Pace kan Zamek skapa en avledning. När det händer lämnar Rizzle sin hydda, och Indurium-planerna blir kvar."}},faq={{q="Vem ger Zamek's Distraction?",a="Zamek i Thousand Needles.",al={"vem startar zameks distraction","zamek uppdragsgivare","var får jag zameks distraction"}},{q="Hur hänger det ihop med Keeping Pace?",a="Det sker medan du håller på med Keeping Pace, och steget kan inte slutföras utan det.",al={"krävs detta för keeping pace","keeping pace zamek","koppling till keeping pace"}},{q="Vad gör avledningen?",a="Rizzle lämnar sin hydda, och hans planer blir kvar.",al={"vad händer när zamek distraherar","rizzle lämnar hyddan"}},{q="Kan äventyrare från både Alliance och Horde samarbeta med Zamek?",a="Ja. Zamek är neutral och öppen för båda fraktionerna.",al={"är zamek neutral","alliance eller horde zamek","vem kan göra zameks distraction"}}},fp="19,141,18.103.0,30.35.0,37.97.0,27.53.0,56.52.0"}
P.entries["quest:1192"] = {n="Indurium Ore",s="Pozzik tänker använda indurium i flera delar av racerbilarna, vilket kräver stora mängder råmalm. Malmen finns vid utgrävningen i Uldaman i Badlands, på andra sidan havet i Khaz Modan. Gnomerna håller redan på att skaffa egen malm, och Pozzik vill hålla jämna steg med dem.",h="Pozzik tänker använda indurium i flera delar av racerbilarna, vilket kräver stora mängder råmalm.",kw={"badlands","indurium","induriummalm","pozzik","racerbilar","thousand needles","uldaman"},sec={{t="Malm från Uldaman",b="Pozzik ber om fyra stycken rå induriummalm. Den finns vid utgrävningen i Uldaman i Badlands, på andra sidan havet i Khaz Modan. Gnomerna håller redan på att skaffa egen malm, så Pozzik vill också ha ett förråd. Detta följer på Rizzle's Schematics."}},faq={{q="Varför vill Pozzik ha induriummalm?",a="Han vill använda indurium i flera delar av racerbilarna, och det kräver stora mängder råmalm.",al={"vad används indurium till","varför induriummalm","pozziks syfte med indurium"}},{q="Var hittar man induriummalmen?",a="Vid utgrävningen i Uldaman i Badlands, på andra sidan havet i Khaz Modan.",al={"var hittar man induriummalm","induriums plats","var får jag tag på induriummalm"}},{q="Varför är det viktigt att få tag på malmen?",a="Gnomerna håller redan på att skaffa eget indurium, och Pozzik vill hålla jämna steg med dem.",al={"varför brådska med indurium","gnomrival med indurium"}},{q="Vad kom före det här?",a="Det följer på Rizzle's Schematics, som i sin tur följer på Keeping Pace.",al={"förutsättning för induriummalm","tidigare uppdrag i induriumkedjan"}}},fp="12,280,16.242.0,34.99.0,32.65.0,34.97.0,22.66.0"}
P.entries["quest:1194"] = {n="Rizzle's Schematics",s="Rizzles obevakade planer beskriver hur indurium malm förädlas. Klottren pekar ut dvärgarnas gruva i Uldaman, i Badlands, som malmens ursprung, och många av de andra anteckningarna handlar om värmetålighet. En klump råmalm ligger på planerna som pappersvikt, och du tar provet till Pozzik på The Shimmering Flats. Detta följer efter Keeping Pace.",h="Rizzles obevakade planer beskriver hur indurium malm förädlas.",kw={"badlands","indurium","pozzik","rizzle","ritningar","the shimmering flats","uldaman"},sec={{t="Anteckningar om indurium",b="Rizzles ritningar beskriver hur indurium malm förädlas. Rizzles klotter pekar ut dvärgarnas gruva i Uldaman, i Badlands, som malmens ursprung. Många av de andra anteckningarna handlar om hur väl den står emot värme. En klump rå induriummalm håller planerna på plats som pappersvikt, och det är det provet du tar till Pozzik."},{t="Pozziks utlåtande",b="Pozzik tycker att indurium är intressant. Om det står emot värme så bra som du säger, kan det förklara hur mycket tomtarna har förbättrats på sistone. Provet blir ovärderligt för tester, men Pozzik behöver mer för att det ska bli till någon verklig nytta."}},faq={{q="Varifrån får Rizzle sin induriummalm?",a="Rizzles klotter pekar ut dvärgarnas gruva i Uldaman, i Badlands.",al={"varifrån kommer indurium","induriummalmens ursprung","rizzle indurium plats"}},{q="Vad står det i Rizzles anteckningar om indurium?",a="Rizzles anteckningar beskriver hur malmen förädlas, och många av de andra anteckningarna handlar om dess värmetålighet.",al={"vad används indurium till","varför indurium","induriums egenskaper"}},{q="Vem får induriumprovet?",a="Du tar provet till Pozzik på The Shimmering Flats.",al={"vem ska jag lämna in det till","vem vill ha induriumprovet","lämna in till pozzik"}},{q="Varifrån kom det här provet?",a="En klump rå induriummalm höll Rizzles planer på plats som pappersvikt.",al={"var hittades provet","rizzles pappersvikt"}}},fp="19,356,17.329.0,16.242.1,39.71.0,42.110.0,33.55.0,32.76.0"}
P.entries["quest:1195"] = {n="The Sacred Flame",s="The Sacred Flame är ett uppdrag för Horden som Zangen Stonehoof inleder i Thunder Bluff. För att återfå en forntida relik som vaktas av Galak-centaurerna i Thousand Needles skickar Zangen äventyrare djupt in i Ashenvale för att hämta en helig månbrunnsflaska från traktens dryader.",h="The Sacred Flame är ett uppdrag för Horden som Zangen Stonehoof inleder i Thunder Bluff.",kw={"ashenvale","etched phial","falfarren river","galak-centaurer","laughing sisters","månbrunn","rau cliffrunner","raynewood retreat","the sacred flame","thousand needles","zangen stonehoof"},ang={["class:Druid"]="Tauren-druider ställs inför en besvärlig paradox under uppdraget: de dödar naturens döttrar, dryaderna, för att skörda helgat vatten till ett angrepp mot centaurernas elementarlågor.",["faction:Horde"]="Om du ställer till problem kring Raynewood Retreat riskerar spänningarna med Night Elf i Ashenvale att blossa upp, men centaurreliker från Thousand Needles stärker Hordens södra gränsland.",["race:Tauren"]="Centaurernas fientlighet har plågat taurenfolket i generationer. Att säkra en relik från deras folks ursprung ger Mulgore-stammarna värdefull kunskap och ett övertag mot deras bittraste fiender."},sec={{t="Centaurreliker och alvvatten",b="Galak-stammen av centaurer, som bor på botten av ravinen i Thousand Needles, skyddar svartsjukt en artefakt som går tillbaka till deras folks skapelse. För att bryta igenom deras försvar och släcka deras heliga lågor behöver Zangen Stonehoof vatten berört av månens gudomlighet, vilket riktar taurenfolkets blick norrut mot Ashenvales uråldriga skogar."},{t="Intrång i Ashenvale",b="Att få tag på rent månbrunnsvatten är inte enkelt. Ovälsignade kärl kan inte hålla den heliga vätskan utan att fördärva dess kraft, så Hordens sändebud måste jaga Laughing Sisters nära Raynewood Retreat för att få tag på en Etched Phial. När den väl är hämtad måste flaskan sänkas ner i en månbrunn längs Falfarren Rivers västra strand innan den förs tillbaka till Mulgore."}},faq={{q="Varför behöver Zangen Stonehoof månbrunnsvatten?",a="Vattnet är avsett för Zangens bundsförvant, Rau Cliffrunner, i Thousand Needles. Rau tänker använda månbrunnsvattnets starka magiska egenskaper för att släcka den heliga låga som vaktas av de fientliga Galak-centaurerna, så att Horden kan återta en forntida relik.",al={"varför månbrunnsvatten","månbrunnsvattnets syfte","varför hämta vatten från ashenvale"}},{q="Var finns den ingraverade flaskan?",a="Den ingraverade flaskan bärs av dryader som kallas Laughing Sisters. De strövar i skogarna kring Raynewood Retreat i centrala Ashenvale, strax intill vägen norrut som går västerut från Splintertree Post.",al={"var finns etched phial","hur får man etched phial","flaskans plats"}},{q="Vilken månbrunn ska användas för att fylla flaskan?",a="Månbrunnen finns nära Falfarren Rivers västra strand, söder om huvudvägen som går genom centrala Ashenvale.",al={"vilken månbrunn","månbrunnens plats","var fyller man flaskan"}},{q="Vilka är Galak-centaurerna?",a="Galak är en aggressiv centaurklan som lever i Thousand Needles dammiga vidder. De har en forntida relik från den tid då deras folk grundades, omgiven av en helig brasa som Zangen och Rau tänker släcka.",al={"galak-stammen","galak-centaurer","vilka är galak"}},{q="Vem tar emot den fyllda flaskan efter Zangen?",a="När Zangen har granskat den fyllda flaskan i Thunder Bluff ber han äventyraren resa söderut till Thousand Needles och överlämna kärlet direkt till Rau Cliffrunner, som har bett om det.",al={"vem är rau","vart förs vattnet härnäst","nästa steg efter zangen"}},{q="Varför döda dryader för deras flaskor?",a="Dryadernas kärl är särskilt tillverkade för att hålla rena, förtrollade vätskor utan att förorena dem. Vanliga flaskor kan inte transportera vatten som genomsyrats av de himmelska energierna från en Night Elf-månbrunn på ett säkert sätt.",al={"varför angripa dryader","varför laughing sisters","dryadernas kärl"}}},fx={["47d9b30a"]={q="Vad är Filled Etched Phial till för?",a="Flaskan innehåller heligt vatten från en nattalvers månbrunn i Ashenvale, i ett kärl taget från dryaderna. Zangen Stonehoofs bundsförvant Rau Cliffrunner i Thousand Needles behöver det välsignade vattnet för att släcka Galakcentaurernas heliga låga. Då kan Horde återta en uråldrig relik från centaurernas gryningstid.",al={"användning av filled etched phial","varför filled etched phial","vad gör flaskan"}},["9c32d271"]={q="Vilka är Laughing Sisters?",a="Laughing Sisters är dryader, halvguden Cenarius döttrar, som vaktar de förtrollade lundarna kring Raynewood Retreat i Ashenvale. De är djupt bundna till naturen och nattalverna, bor nära heliga platser och bär särskilda graverade flaskor som lämpar sig för rent månbrunnsvatten. Eftersom de är våldsamt fientliga mot främlingar och Horde måste du ta en flaska från dem med våld.",al={"varför döda dryader","vilka är dryaderna i raynewood","laughing sisters i ashenvale"}}},fp="16,159,31.331.0,24.262.0,46.228.0,36.191.0,48.112.0,26.212.0,43.147.0,33.190.0"}
P.entries["quest:1196"] = {n="The Sacred Flame",s="Efter en farofylld färd till en månskensbrunn i Ashenvale måste en flaska med heligt vatten föras söderut till Freewind Post. Taurenmystikern Rau Cliffrunner behöver denna månens essens för att bryta igenom en evig eld som skyddar en forntida centaurrelik i Thousand Needles.",h="Efter en farofylld färd till en månskensbrunn i Ashenvale måste en flaska med heligt vatten föras söderut...",kw={"centaurrelik","etched phial","freewind post","the great lift","rau cliffrunner","sacred flame","thousand needles","zangen stonehoof"},ang={["class:Druid"]="Rau Cliffrunner förlitar sig på sin djupa kunskap om Cenarion-blodslinjer för att förstå den magiska resonansen mellan dryader och centaurer.",["faction:Horde"]="När du levererar flaskan stärker du Freewind Post, Horde-folkets högt belägna utpost i Thousand Needles farliga kanjonpass.",["race:Tauren"]="Varje slag mot centaurerna skyddar Mulgore och ditt hemlands nyvunna gränser."},sec={{t="En lång färd söderut",b="Zangen Stonehoofs uppdrag kräver en snabb färd genom centrala Kalimdor. Med den etsade flaskan fylld till brädden med renat vatten från månskensbrunnen får du instruktioner om att korsa The Barrens solstekta vidder, ta dig nedför The Great Lift och nå bosättningen Freewind Post på den höga platån. Där väntar Rau Cliffrunner högt ovanför kanjonens botten och håller uppsikt över de fräcka centaurklanerna nedanför."},{t="Delat blod och forntida skydd",b="När Rau Cliffrunner tar emot flaskan förklarar han varför Night Elfs heliga vatten är avgörande för taurenfolkets operation mot centaurerna. Dryader och centaurer har gemensamma förfäder genom halvguden Cenarius, vars son Zaetar blev centaurernas far. Därför bär månskensbrunnarnas heliga vatten på en magisk resonans. Denna koppling gör vattnet till det enda som kan tränga igenom den skyddande eviga elden som omger en bevakad centaurartefakt."}},faq={{q="Var finns Rau Cliffrunner?",a="Rau Cliffrunner bor högst upp på Freewind Post i Thousand Needles. För att nå honom färdas du söderut genom The Barrens, tar dig nedför The Great Lift till kanjonen och följer sedan stigen åt sydost till hissen som är upphissad högt på den branta klippnålen.",al={"var finns rau","rau cliffrunners plats","hitta rau cliffrunner","lämna in vid freewind post"}},{q="Varför behöver Rau vatten från månskensbrunnen för att bekämpa centaurerna?",a="Centaurer och dryader har ett gemensamt ursprung i Cenarius avkomma. Därför har det helgade vattnet från en Night Elf-månskensbrunn den magiska samklang som krävs för att upplösa den eviga eld som skyddar centaurernas heliga relik.",al={"varför vatten från månskensbrunn","kopplingen mellan månskensbrunn och centaurer","förhållandet mellan dryader och centaurer"}},{q="Vem skickade mig med flaskan?",a="Zangen Stonehoof gav dig i uppdrag att transportera Filled Etched Phial efter att du hämtat vatten från den bevakade månskensbrunnen i Ashenvale.",al={"vem gav uppdraget","zangen stonehoof","vem gav uppdraget sacred flame 2"}},{q="Vad händer när jag har gett flaskan till Rau?",a="När Rau har bekräftat att vattnet är oskadat ger han dig i uppdrag att använda flaskans kraft direkt för att släcka elden och hämta centaurreliken från den närliggande kanjonen.",al={"nästa uppdrag","vad händer efter rau","sacred flame del 3"}},{q="Hur tar jag mig ned i Thousand Needles?",a="Följ huvudvägen söderut genom The Barrens tills du når klippkanten. Där hittar du The Great Lift, två trähissar som drivs med taurenfolkets taljor och tar resande ned till kanjonens botten.",al={"hur man tar sig till thousand needles","ta sig förbi klippkanten i the barrens","vägbeskrivning till the great lift"}},{q="Varför söker taurenfolket efter en centaurrelik?",a="Taurenfolket och centaurerna har utkämpat ett brutalt krig över hela Kalimdor i generationer. Genom att störa deras riter och ta deras heliga artefakter försvagas de krigiska klaner som håller till i kanjonen Thousand Needles.",al={"kriget mellan taurenfolket och centaurerna","varför ta centaurreliken"}}},fx={["070b3297"]={q="Varför vill Zangen Stonehoof att det här ska göras?",a="Zangen Stonehoof samordnar insatserna för att hjälpa Rau Cliffrunner och tauren i Thousand Needles. Genom att säkra det välsignade månbrunnsvattnet och se till att det når Freewind Post ger han Rau möjlighet att motverka den magiska låga som skyddar en viktig centaurrelik.",al={"varför skicka flaskan","zangens motiv","zangens syfte"}}},fp="16,180,20.320.0,30.328.1,33.221.0,51.181.0,27.119.0,43.145.1,40.191.0,43.215.0"}
P.entries["quest:1197"] = {n="The Sacred Flame",s="The Sacred Flame är det sista uppdraget i Rau Cliffrunners undersökning av Galak-centaurerna i Thousand Needles. Med välsignat vatten måste en Horde-äventyrare ta sig in i Splithoof Hold, släcka stammens vördade eldstad och hämta den uråldriga reliken Cloven Hoof.",h="The Sacred Flame är det sista uppdraget i Rau Cliffrunners undersökning av Galak-centaurerna i Thousand...",kw={"centaur","cloven hoof","freewind post","galak","rau cliffrunner","heliga lågan","splithoof crag","splithoof hold","thousand needles"},ang={["class:Shaman"]="Schamaner som hanterar Cloven Hoof känner lätt av den märkliga energin som strålar från talismanen. Det visar att centaurerna hämtar kraft från mystiska krafter långt bortom enkel råstyrka och vildsinthet.",["race:Tauren"]="För tauren innebär angreppet mot hjärtat av en centaurhåla och erövringen av deras heliga symbol både hämnd för generationer av räder och ett ovärderligt forskningsfynd för Freewind Post."},sec={{t="Slå mot härden",b="Norr om Freewind Post ligger Splithoof Crag, hjärtat av Galak-centaurernas område i Thousand Needles. Djupt inne i deras väldiga håla, Splithoof Hold, brinner en eld som centaurerna håller helig. Efter att ha fyllt en graverad ampull med renat vatten ger Rau Cliffrunner sina allierade i uppdrag att ta sig in i fästningen under jord, tillfälligt släcka lågan med vattnet och lägga beslag på bytet som vaktas där inne: en relik som kallas Cloven Hoof."},{t="Klövens hemligheter",b="Cloven Hoof är inte bara en krigsprydnad. Den utstrålar en märklig, kraftfull energi som genast fångar Rau Cliffrunners mystiska sinnen när den visas upp för honom. Tauren-lärda har länge kämpat mot de härjande centaurstammarna i Kalimdor, men reliker som denna antyder djupare, föga förstådda krafter som driver deras iver och stammarnas sammanhållning."}},faq={{q="Var finns den heliga lågan?",a="Lågan brinner längst in i Splithoof Hold, en grotta inne i centaurernas läger på Splithoof Crag, rakt norr om Freewind Post i Thousand Needles.",al={"splithoof hold plats","var finns den heliga lågan","låggrottan i thousand needles"}},{q="Vem ber dig släcka lågan?",a="Rau Cliffrunner, en äldste som håller till högt uppe på Freewind Post, ger dig uppdraget som avslutning på sin forskning om Galak-centaurerna.",al={"uppdragsgivare till the sacred flame","rau cliffrunners plats","vem ger uppdraget"}},{q="Hur släcker du lågan?",a="Du måste använda Filled Etched Phial som Rau Cliffrunner ger dig. Den innehåller vatten som samlats in tidigare i uppdragskedjan och används för att tillfälligt släcka eldstaden.",al={"hur får man cloven hoof","föremål för att släcka lågan","släcka den heliga lågan"}},{q="Vad är Cloven Hoof?",a="Cloven Hoof är en vördad stamrelik som Galak-centaurerna förvarar inne i lågan. Rau Cliffrunner känner en ovanlig magisk energi från den och hoppas att den ska avslöja hemligheter om centaurernas kultur och kraft.",al={"cloven hoofs bakgrund","centaurrelik","vad stal vi"}},{q="Varför vill tauren ha reliken?",a="Centaurstammarna har i generationer drivit bort tauren från deras förfäders jaktmarker. Genom att lägga beslag på ett heligt arvegods stör tauren Galak-stammens verksamhet och försöker förstå den mystiska eller andliga naturen bakom fiendernas vildsinthet.",al={"varför stjäla cloven hoof","taurenernas krig mot centaurerna"}},{q="Vilken centaurklan vaktar Splithoof Hold?",a="Splithoof Crag och grottfästet där styrs av Galak-stammen, den dominerande centaurklanen på botten av kanjonen Thousand Needles.",al={"centaurstam i thousand needles","galak-centaurer"}}},fp="16,178,19.363.0,19.272.1,34.135.0,32.127.0,29.133.0,24.191.0,34.237.0,41.133.0"}
P.entries["quest:1198"] = {n="In Search of Thaelrid",s="In Search of Thaelrid är ett rekognoseringsuppdrag för Alliansen, utsänt från Darnassus på Argent Dawns vägnar. Dawnwatcher Shaedlass ger äventyrare i uppdrag att ta sig in i de sjunkna ruinerna av Blackfathom Deeps och hitta en försvunnen spejare som försvann när han undersökte en farlig allians mellan naga och kultister. Uppdraget är ett tidigt möte med Argent Dawns räckvidd bortom dess vanliga bevakning i norr.",h="In Search of Thaelrid är ett rekognoseringsuppdrag för Alliansen, utsänt från Darnassus på Argent Dawns...",kw={"argent dawn","ashenvale","blackfathom deeps","darnassus","naga","shaedlass","thaelrid","twilight's hammer"},ang={["class:Paladin"]="Paladiner som tjänar Argent Dawn ser Thaelrids ensamma vakt som en högtidlig plikt att skydda världen från växande skuggor och korrumpering.",["faction:Alliance"]="Uppdraget ger Alliansens äventyrare en av sina tidigaste möjligheter att vinna Argent Dawns förtroende och tjäna orden.",["race:NightElf"]="Vanhelgandet av det uråldriga Elunes tempel i Blackfathom Deeps gör det brådskande att hjälpa Argent Dawn att återta nattalvernas heliga arv."},sec={{t="Ögon i Darnassus",b="Argent Dawn är mest känt för att hålla stånd mot Scourge i de pestdrabbade ruinerna av Ruins of Lordaeron, men dess vaksamhet sträcker sig över Kalimdor. Dawnwatcher Shaedlass, som är stationerad i Darnassus, samlar rykten och underrättelser om onaturliga hot som växer fram i världen. När oroande rapporter kom om att havslevande naga och domedagsfanatikerna i Twilight's Hammer hade slutit en pakt i de översvämmade salarna i Blackfathom Deeps vid Ashenvales kust insåg orden vilken katastrof som kunde följa."},{t="Den försvunna spejaren",b="För att bedöma om kustens rykten stämde skickade Shaedlass Argent Guard Thaelrid för att i hemlighet ta sig in i grottorna under jord. Veckor gick utan livstecken, och Dawnwatcher fick inget veta medan hans andra spejare var upptagna med skilda uppdrag. Rädd att Thaelrid antingen hade stupat i strid eller tillfångatagits av de mörka krafter som dväljs under vågorna ber han erfarna resenärer att våga sig in i Blackfathom Deeps och föra honom tillbaka levande."}},faq={{q="Varför är Argent Dawn intresserat av Blackfathom Deeps?",a="Argent Dawn bevakar alla hot mot Azeroths existens och hot om korrumpering, inte bara de odöda i Eastern Kingdoms. Risken att uråldriga naga samarbetar med fanatiska kultister från Twilight's Hammer i Kalimdor innebär en destabiliserande ondska som kräver deras uppmärksamhet.",al={"varför argent dawn här","argent dawn blackfathom","argent dawn naga"}},{q="Vem är Dawnwatcher Shaedlass?",a="Dawnwatcher Shaedlass är en agent för Argent Dawn, stationerad i nattalvernas huvudstad Darnassus. Hans främsta uppgift är att samla information, ta reda på var orden snarast behöver hjälpa till och skicka ut utredare för att bedöma regionala kriser.",al={"vem är shaedlass","uppdragsgivare shaedlass","dawnwatcher shaedlass roll"}},{q="Vem är Argent Guard Thaelrid?",a="Argent Guard Thaelrid är en agent för Argent Dawn som skickats för att rekognoscera Blackfathom Deeps. Hans uppdrag var att ta reda på kultisternas och naga-folkets verkliga styrka och avsikter i de dränkta grottorna.",al={"vem är thaelrid","thaelrids bakgrund","försvunna spejaren thaelrid"}},{q="Var finns Thaelrid?",a="Argent Guard Thaelrid har lyckats infiltrera djupen under jord i Blackfathom Deeps vid The Zoram Strand i Ashenvale, men han är fortfarande ensam långt inne i grottorna och väntar på förstärkning.",al={"thaelrids plats","var är thaelrid","hitta thaelrid i bfd"}},{q="Vad händer när man hittar Thaelrid?",a="När ni hittar honom avslöjar Thaelrid ritualens fulla, lömska natur i ruinerna och skickar genast äventyrarna mot ett anfall på kultens ledarskap i uppdraget Blackfathom Villainy.",al={"what comes next","fortsättning på thaelrids uppdrag","nästa uppdrag efter thaelrid"}},{q="Kan Horde-spelare ta det här uppdraget?",a="Uppdraget ges av Dawnwatcher Shaedlass i Darnassus och riktar sig till äventyrare i Alliansen. Äventyrare i Horde kan också ta det om de hittar fram till honom.",al={"horde in search of thaelrid","kan horde göra det här uppdraget","horde thaelrid"}}},fx={["4b9c6d96"]={q="Varför vill Dawnwatcher Shaedlass att du hittar Thaelrid?",a="Shaedlass samlar underrättelser åt Argent Dawn för att bevaka växande ondska i Kalimdor. För flera veckor sedan skickade han Argent Guard Thaelrid för att undersöka oroande rykten om en allians mellan naga och Twilight's Hammer i Blackfathom Deeps. Inget svar har kommit, och han fruktar det värsta. Han måste få veta hur det står till med spejaren och sanningen bakom den onda planen som växer fram längs Ashenvales kust.",al={"varför hitta thaelrid","shaedlass motiv","varför skicka till blackfathom deeps"}},["3832a285"]={q="Varför skickar Shaedlass en äventyrare i stället för sina egna spejare?",a="Argent Dawns närvaro i Darnassus är liten, och Shaedlass säger att alla hans andra spejare är fullt upptagna med sina egna brådskande uppdrag runtom i landet. Thaelrid är försvunnen och inga agenter finns att avvara, så han måste förlita sig på dugliga och villiga äventyrare som kan ta sig ner i de förrädiska djupen åt honom.",al={"varför jag i in search of thaelrid","varför inte skicka argent dawns spejare"}}},fp="21,195,17.375.0,17.337.0,55.207.0,29.200.0,29.182.0,28.165.0,36.143.1,36.148.0"}
P.entries["quest:1199"] = {n="Twilight Falls",s="Argent Guard Manados i Darnassus kallar alliansens hjältar till strid mot kultisterna i Twilight's Hammer, som samlats i Blackfathom Deeps. Den mörka kulten har allierat sig med ormlika naga för att ta över Night Elf-templet som sjunkit utanför Ashenvales kust. Genom att samla in hängen från fallna kultister slår äventyrarna mot deras lömska planer på att väcka uråldriga fasor.",h="Argent Guard Manados i Darnassus kallar alliansens hjältar till strid mot kultisterna i Twilight's Hammer...",kw={"argent dawn","argent guard manados","ashenvale","blackfathom deeps","darnassus","manados","naga","old gods","twilight falls","twilight pendant","twilight's hammer"},ang={["class:Paladin"]="Som förkämpar för det heliga ljuset och bundsförvanter till ordnar som Argent Dawn ser paladiner Twilight's Hammers fördärvade dyrkan av Old Gods som en styggelse som måste renas bort med rättfärdig kraft.",["class:Priest"]="Präster är särskilt lyhörda för hur templets en gång heliga månbrunn har förvridits och för de vansinnesframkallande, skuggiga viskningarna som driver kultisterna allt djupare in i vansinne.",["faction:Alliance"]="Twilight's Hammer utgör ett växande hot strax söder om Darkshore, vilket gör utrensningen av Blackfathom Deeps avgörande för att säkra norra Kalimdor.",["race:NightElf"]="När Old God-kultister och naga gradvis vanhelgar ett heligt tempel och en månbrunn, är det en direkt förolämpning mot Elune och Ashenvales förfäders land."},sec={{t="Ett vanhelgat tempel",b="Under de karga klipporna vid The Zoram Strand i Ashenvale ligger ruinerna av Blackfathom Deeps. Det var en gång ett heligt Night Elf-tempel tillägnat Elune och hem åt en mäktig månbrunn, men splittrades och sjönk ner i djupet under Sunderingen. I dag har det heliga vattnet blivit stinkande och motbjudande, och platsen översvämmas av blodtörstiga naga och fanatiska kultister som vördar krafter långt mörkare än havet."},{t="De gamla gudarnas viskningar",b="Twilight's Hammer är en apokalyptisk kult som ägnar sig åt de kaotiska Old Gods och vill återföra sina uråldriga härskare för att svepa in världen i vansinne och förödelse. Rapporter till Darnassus bekräftar att dessa galningar har slutit sig samman med nagorna som bor i Blackfathom Deeps. Djupt inne i de översvämmade salarna utför de hädiska ritualer och använder det sjunkna templets förgiftade vatten för att stärka sina mörka herrars återkomst."},{t="Argent Dawns vaksamhet",b="Argent Guard Manados är stationerad i Darnassus och företräder Argent Dawns vaksamhet mot alla plågor som hotar Azeroth. Orden inser att fördärvet i Blackfathom Deeps kan släppa lös fasor över alla civiliserade raser och erbjuder erkännande och hjälp åt hjältar som är villiga att ta sig ner i den översvämmade labyrinten, röja kultisterna ur vägen och rycka Twilight Pendants från deras halsar som bevis på deras fall."}},faq={{q="Vem är Argent Guard Manados?",a="Argent Guard Manados är ett sändebud för Argent Dawn, stationerad i Darnassus. Som ordens ögon och öron i Kalimdor håller han uppsikt över illvilliga kulter och mörka krafter som hotar riket och värvar äventyrare för att utrota dem.",al={"manados","vem ger twilight falls","argent guard manados plats"}},{q="Varför bryr sig Argent Dawn om Blackfathom Deeps?",a="Argent Dawn är främst känd för att bekämpa Scourge i Lordaeron, men dess uppdrag omfattar att konfrontera allt onaturligt ont som hotar hela tillvaron. Om dyrkan av Old Gods återuppstår och kultister allierar sig med naga i Kalimdor kan det leda till en global katastrof om det inte stoppas.",al={"varför argent dawn i darnassus","argent dawn blackfathom"}},{q="Vad är Twilight's Hammer?",a="Twilight's Hammer är en fanatisk domedagskult som dyrkar Old Gods, kaotiska och uråldriga väsen som för länge sedan fängslades under jorden. Kultisterna tror att de kan påskynda apokalypsen, då deras skuggiga härskare åter stiger upp för att stöpa om världen i skräck och vansinne.",al={"twilight hammer-kulten","vilka är twilight's hammer","twilight hammer"}},{q="Vad användes Twilight Pendants till?",a="Twilight Pendants är mörka talismaner som bärs av medlemmar i Twilight's Hammer. De symboliserar deras trohet till de kaotiska väsen de dyrkar, och Argent Dawn samlar in dem som verifierbara bevis på att en kultist har dödats och oskadliggjorts.",al={"twilight pendant-bakgrund","vad är twilight pendants"}},{q="Vad var Blackfathom Deeps från början?",a="Långt innan Blackfathom Deeps fördärvades var det ett storslaget Night Elf-tempel tillägnat mångudinnan Elune. Templet var känt för att hysa en oerhört kraftfull månbrunn, innan Sunderingen spräckte jorden och sänkte dess salar under havet.",al={"blackfathoms historia","bfd-templets historia","blackfathoms månbrunn"}},{q="Varför samarbetar Twilight's Hammer med nagorna?",a="Man känner inte till hela orsaken till deras förbund, men båda dras till den mörka kraft som rör sig i det sjunkna templet. I Blackfathom Deeps får kultisterna genom samarbetet ostörd tillgång till uråldriga kammare under vattnet, medan nagorna får nytta av kultens vidriga trolldom och offerriter.",al={"naga och kultisters allians","bfd:s naga-allians"}}},fp="14,246,17.326.0,24.330.0,28.363.0,28.170.0,57.231.0,30.242.0,41.210.0,38.170.0,52.245.0"}
P.entries["quest:12"] = {n="The People's Militia",s="Vid Sentinel Hill prövar Gryan Stoutmantle ditt mod för folkets milis. Stormwinds tron är upptagen på annat håll och dess armé är frånvarande, så lokala frivilliga försvarar Westfall mot Defias Brotherhood. Du börjar med att driva bort laglösa från de norra fälten och gruvorna.",h="Vid Sentinel Hill prövar Gryan Stoutmantle ditt mod för folkets milis.",kw={"defias-smugglare","defias-fällfångare","furlbrow","gryan stoutmantle","jangolode","the molsen farm","folkets milis","sentinel hill","westfall"},ang={["class:Paladin"]="Som paladin skyddar du de försvarslösa och skipar rättvisa åt laglösa som ger sig på de utsatta.",["faction:Alliance"]="Som äventyrare i Alliansen ser du splittringen i riket: Stormwinds adel håller sig bakom huvudstadens murar medan vanligt folk försvarar Westfall mot förödelse.",["race:Human"]="Som människa i riket ser du arbetarfamiljer och generationer av bönder lida under banditernas angrepp medan de kungliga myndigheterna blundar."},sec={{t="Fredens pris",b="Westfall försörjde en gång Stormwind med mat, men nu härjar laglösa, lösdrivare och tjuvar i regionen. Eftersom huvudstaden inte skickar några kungliga soldater för att patrullera landsbygden organiserade Gryan Stoutmantle folkets milis vid Sentinel Hill som en lokal försvarsstyrka. Han uppmanar till beslutsamma insatser för att återta Westfall. Alla som vill bära milisens märke måste visa att de kan strida och skydda oskyldiga nybyggare."},{t="Rensa spannmålsboden",b="Innan Stoutmantle litar på nya rekryter med mer omfattande uppdrag skickar han dem mot Defias-styrkor nära de norra gårdarna. Defias Trappers och Smugglers arbetar öppet nära Jangolode Mine, The Molsen Farm och Furlbrow's Pumpkin Farm, plundrar förråd och överfaller resande. Du kan störa deras födosök genom att driva bort dem och samtidigt visa Stoutmantles spejare att du har uthålligheten som krävs för en lång kamp mot brottsligheten."}},faq={{q="Vad är folkets milis?",a="Folkets milis är en frivillig armé som organiserats av Gryan Stoutmantle och har sitt högkvarter vid Sentinel Hill. Lokala bönder, veteraner och vanligt folk fyllde dess led för att försvara Westfall mot Defias Brotherhood, medan Stormwinds kungliga armé har vägrat eller misslyckats med att garnisonera regionen.",al={"folkets milis","vilka är milisen","vad är folkets milis"}},{q="Varför skickar Stormwind inte sin kungliga armé?",a="När kung Varian Wrynn försvann riktade Stormwinds adliga House of Nobles och rådets ledning rikets resurser åt andra håll. Avlägsna landsbygdsområden som Westfall får klara sig själva mot växande grupper av laglösa.",al={"var är armén","varför finns inga vakter i westfall","stormwinds garnison"}},{q="Var hittar jag Defias Trappers och Smugglers?",a="Defias Trappers och Smugglers håller till i hela norra Westfall, särskilt kring Furlbrow's Pumpkin Farm, The Molsen Farm och ingången till Jangolode Mine.",al={"var finns fällfångare","var finns smugglare","var finns fällfångarna"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en erfaren veteran som leder folkets milis vid Sentinel Hill. Han samlar frivilliga för att försvara Westfalls nybyggare, driva bort Defias Brotherhood och återställa ordningen på landsbygden.",al={"vem är stoutmantle","gryan stoutmantles bakgrund","milisens ledare"}},{q="Leder det här uppdraget till fler uppdrag för milisen?",a="Ja. Den här första prövningen leder till fler uppdrag för de frivilliga som klarar den. De tar sig an allt farligare grupper ur Defias Brotherhood på Westfalls slätter.",al={"är det här en uppdragskedja","nästa uppdrag","milisens utveckling"}},{q="Vad händer vid Furlbrow's Pumpkin Farm?",a="Defias Brotherhood drev bort familjen Furlbrow från deras gård och tog kontroll över deras jordbruksmark. Laglösa och asätare plundrar nu fälten och terroriserar de norra vägarna.",al={"furlbrows gård","vad hände med familjen furlbrow","pumpagården"}}},fx={b0313ac5={q="Varför vill Gryan Stoutmantle att det här ska göras?",a="Gryan Stoutmantle leder People's Militia med ett enda mål: att försvara Westfall och återta freden från det brottssyndikat som översvämmar jordbruksmarkerna. Grupper av Defiaslaglösa plundrar gårdar som The Molsen Farm och Furlbrow Farm. Genom att rensa bort deras fällställare och smugglare vill Gryan tränga tillbaka dem och pröva om du har viljan att kämpa för Westfalls folk.",al={"varför döda fällställare och smugglare","gryan stoutmantles motiv","syftet med uppdraget people's militia"}},["1cf2b131"]={q="Vilka är Defias Trappers och Smugglers?",a="De är Defias Brotherhoods meniga operatörer, ett hänsynslöst syndikat av tjuvar och laglösa som drivit bort bönderna från deras marker. Fällställarna och smugglarna håller till vid beslagtagna egendomar som The Molsen Farm och Jangolode Mine. De säkrar området och lagrar olagligt gods för att stödja Brotherhoods järngrepp om landsbygden.",al={"defias fällställare","defias smugglare","vilka är defias laglösa"}},b416da40={q="Varför behöver Gryan Stoutmantle dig för att bekämpa Defias?",a="People's Militia är en frivilligstyrka som pressats till bristningsgränsen och lämnats helt åt sitt öde av Stormwinds kungliga armé. Gryan kan inte riskera att skicka sina få återstående försvarare på skärmytslingar och därmed försvaga vakten vid Sentinel Hill. Han förlitar sig på dugliga frivilliga och legoknektar och ber dig bevisa ditt värde och engagemang innan han formellt välkomnar dig i milisens led.",al={"varför bekämpar inte milisen dem","varför jag, gryan","varför ta in utomstående"}}},fp="20,253,18.287.0,24.404.0,29.267.0,43.238.0,47.152.0,25.216.0,49.167.0,45.179.0"}
P.entries["quest:120"] = {n="Messenger to Stormwind",s="Magistrate Solomon i Lakeshire är desperat efter militär hjälp när gnoller och Blackrock-orcher omringar staden. Eftersom han inte kan avvara garnisonssoldater skickar han en äventyrare med ”The State of Lakeshire” direkt till General Marcus Jonathan i Stormwind City.",h="Magistrate Solomon i Lakeshire är desperat efter militär hjälp när gnoller och Blackrock-orcher omringar...",kw={"general marcus jonathan","lakeshire","magistrate solomon","bud till stormwind","redridge mountains","förstärkningar","stormwinds armé","the state of lakeshire"},ang={["class:Paladin"]="Att bära desperata människors vädjanden till ledare som lamslagits av hovpolitik prövar pliktkänsla, beskydd och viljan att handla rätt.",["faction:Alliance"]="Uppdraget blottlägger den växande spänningen mellan den välmående huvudstaden och de försummade gränsbygder som kämpar för sin överlevnad i rikets utkanter.",["race:Human"]="Redridge är Stormwinds historiska territorium. Att se andra människor överges på grund av byråkratiskt krångel svider för varje patriot i riket."},sec={{t="Ett rop över bergen",b="Lakeshire står på randen till sammanbrott. Gnollflockar strider om varje väg, Blackrock-orcher plundrar från norr och de lokala vakterna är hårt ansträngda. Magistrate Solomon har inte råd att skicka soldater på en ridtur som tar flera dagar till huvudstaden. Därför får en oberoende resenär ta med hans officiella vädjan om reguljära trupper till stadens portar."},{t="Byråkrati och High Seat",b="När äventyraren överlämnar magistratens rapport får hen möta General Marcus Jonathan, som leder Stormwinds försvar. Jonathan respekterar Solomons ledarskap och inser hur brådskande läget är, men arméns protokoll hindrar honom från att agera utan en kunglig order. Försvaret av Redridge måste vänta tills han har rådgjort formellt med den unge kungen Anduin och regentrådet."}},faq={{q="Varför behöver Magistrate Solomon en budbärare?",a="Lakeshire är ständigt belägrat av Blackrock-orcher och gnoller. Varje lokal vakt behövs för att försvara staden och hålla bron, så Solomon anförtror resande äventyrare sina brådskande vädjanden om hjälp.",al={"varför skicka mig","varför en budbärare","solomons budbärare"}},{q="Vad står det i rapporten ”The State of Lakeshire”?",a="Det är en officiell redogörelse för krisen som drabbar Redridge Mountains. Den beskriver hur fienden blir allt fler, vilka förluster som har skett och hur staden snart kommer att falla om reguljära soldater inte skickas från huvudstaden.",al={"lakeshires tillstånd","solomons rapport","vad står det i brevet"}},{q="Vem är General Marcus Jonathan?",a="General Marcus Jonathan leder Stormwind City Guard och är en högt uppsatt befälhavare inom Stormwind Army. Han håller uppsikt över stadsportarna och rapporterar direkt till Highlord Bolvar Fordragon och kronan.",al={"marcus jonathan","vem är generalen","stormwinds general"}},{q="Varför skickar inte General Jonathan soldater genast?",a="General Jonathan kan inte sätta in armén på eget bevåg. Han måste lägga fram Solomons rapport för kungen och regentrådet och få ett officiellt kungligt mandat innan några trupper kan marschera.",al={"varför inga trupper","var är förstärkningarna","jonathans svar"}},{q="Är vägen mellan Lakeshire och Stormwind säker?",a="Nej. Vägarna genom Redridge och in i Elwynn hemsöks av aggressiva gnollband och Defias-vägrövare, vilket gör resan farlig för ensamma budbärare.",al={"vägen till stormwind","säker resa","vägen genom redridge"}},{q="Skickar Stormwind till slut hjälp?",a="Politisk tröghet och oro i huvudstaden fördröjer en verklig militär insats. Lakeshire och dess magistrat får därför förlita sig nästan helt på legosoldater och frivilliga.",al={"kommer förstärkningarna","hjälp till lakeshire"}}},fx={["3f8e995f"]={q="Varför skickar Magistrate Solomon en äventyrare i stället för en stadsvakt?",a="Lakeshire är pressat till bristningsgränsen. Staden hotas ständigt av gnoller och Blackrock-orcher som rycker fram från de omgivande kullarna. Magistrate Solomon kan helt enkelt inte undvara en enda svuren försvarare eller stadsvakt från stridslinjerna utan att stadens försvar blir farligt försvagat. Genom att anförtro en livskraftig äventyrare att föra vädjan till Stormwind kan varje lokal vaktpost stanna kvar.",al={"varför skicka mig","varför levererar inte lakeshires vakter","varför en äventyrare som budbärare"}}},fp="22,279,26.301.0,29.331.0,45.192.0,43.203.0,31.201.0,54.183.0,49.148.0,35.173.1"}
P.entries["quest:1200"] = {n="Blackfathom Villainy",s="Blackfathom Villainy är ett uppdrag för Alliansen från Argent Guard Thaelrid, djupt inne i det förfallna, underjordiska templet Blackfathom Deeps. För att stoppa de fruktansvärda offren som göder en uråldrig skräck ska hjältarna döda kultledaren Twilight Lord Kelris och föra bevis tillbaka till Argent Dawn i Darnassus.",h="Blackfathom Villainy är ett uppdrag för Alliansen från Argent Guard Thaelrid, djupt inne i det förfallna...",kw={"aku'mai","argent dawn","blackfathom","darnassus","deeps","elune","kelris","moon well","selgorm","thaelrid","twilight's hammer"},ang={["class:Paladin"]="Att hörsamma Argent Dawns uppmaning att döda en kultist som offrar oskyldiga åt uråldriga fasor är själva definitionen av helig vedergällning.",["class:Priest"]="När Kelris stoppas upphör den hädiska vanhelgelsen av vigda vatten som en gång hölls heliga i vördnad för det gudomliga.",["faction:Alliance"]="Genom att hjälpa Argent Dawn mot Kelris bidrar Alliansen till att skydda Ashenvales utsatta gränser från förrädisk infiltration från kulten.",["race:NightElf"]="Att hämnas vanhelgandet av ett uråldrigt Elunetempel och rena dess förgiftade Moon Well slår direkt mot hjärtat av kaldorei-arvet."},sec={{t="En vanhelgad helgedom",b="Den översvämmade grotta som nu kallas Blackfathom Deeps var en gång ett orört underjordiskt tempel tillägnat Elune. Det heliga förflutna krossades när en uråldrig Old Gods fördärv trängde upp genom berget, förgiftade templets Moon Well och släppte lös Aku'mai, en glupsk tjänare åt det uråldriga mörkret. Efter denna vanhelgelse slöt kulten Twilight's Hammer en ohelig allians med lokala naga och förvandlade heliga salar till en plats för rituella mord."},{t="Den fallne väktarens vädjan",b="Argent Guard Thaelrid begav sig till Blackfathom Deeps för sin ordens räkning, men blev svårt sårad och berövad sina krafter. Omringad av fiender inser Thaelrid att han inte kan slutföra sitt uppdrag ensam. Han ber alla modiga resenärer från Alliansen som når fram till honom att döda Twilight Lord Kelris, den ondskefulle kultisten som iscensätter offer av oskyldiga till Aku'mai i utbyte mot mörk kraft."},{t="Rättvisa i Darnassus",b="När Kelris avhuggna huvud överlämnas till Dawnwatcher Selgorm på Craftsmen's Terrace i Darnassus får en lång och bekymmersam jakt äntligen sitt slut. Argent Dawn hade fruktat att Kelris var död eller förlorad i skuggorna, eftersom han gång på gång varit inblandad när mörka krafter rörde sig i Kalimdor. Att döda honom säkrar en viktig seger mot kultens planer i Ashenvale."}},faq={{q="Vem är Argent Guard Thaelrid?",a="Thaelrid är en agent för Argent Dawn som skickats för att undersöka den växande skuggan i Blackfathom Deeps. Han är svårt sårad i djupet, och hans försvagade krafter tvingar honom att be förbipasserande äventyrare stoppa Kelris.",al={"vem är thaelrid","thaelrids bakgrund","argent guard"}},{q="Varför är Twilight Lord Kelris måltavla?",a="Kelris leder kultisterna i Twilight's Hammer som håller till i Blackfathom Deeps. Han har systematiskt offrat oskyldiga fångar till Aku'mai, ett vidrigt odjur med koppling till Old Gods, i utbyte mot ondskefull kraft.",al={"vem är kelris","varför döda kelris","twilight lord kelris"}},{q="Vem är Dawnwatcher Selgorm?",a="Dawnwatcher Selgorm är en representant för Argent Dawn på Craftsmen's Terrace i Darnassus. Han leder ordens arbete med att hejda det korrumperande inflytande som sprider sig över norra Kalimdor.",al={"selgorm darnassus","vem är selgorm","argent dawn darnassus"}},{q="Vad är Blackfathom Deeps historia?",a="Innan grottorna blev ett sjunket tillhåll för monster och kultister rymde de ett stort tempel för nattalver, tillägnat gudinnan Elune. Det föll i ruiner efter att en Old Gods illvilja trängt upp och förorenat dess heliga Moon Well.",al={"blackfathom deepls historia","vad var blackfathom deeps","elunetempel i blackfathom deeps"}},{q="Vem är Aku'mai?",a="Aku'mai är en monstruös, hydraliknande tjänare åt en Old God som kröp fram ur de förgiftade vattnen under Blackfathom Deeps. Twilight's Hammer dyrkar varelsen och matar den med fångar för att få mörka välsignelser.",al={"vad är akumai","aku'mais bakgrund","akumai odjur"}},{q="Varför samarbetar Twilight's Hammer och naga?",a="Orsakerna till deras pakt är inte helt kända, men i Blackfathom Deeps har de allierat sig för att ockupera templets ruiner medan kulten offrar till Aku'mai.",al={"naga och kultister allians","varför finns naga i blackfathom deeps","twilight's hammer och naga"}}},fx={["96533b2d"]={q="Varför vill Argent Guard Thaelrid att Twilight Lord Kelris ska dödas?",a="Thaelrid har upptäckt att Twilight Lord Kelris och hans kultrister offrar oskyldiga fångar till Aku'mai, en tjänare åt en Old God, i utbyte mot mörk makt. Som agent åt Argent Dawn har Thaelrid vigt sig åt att hejda sådan ondska och få slut på den fasansfulla rituella slakten i det förstörda templet.",al={"thaelrids motiv","varför vill thaelrid att kelris ska dö","varför döda kelris"}},["101c08a2"]={q="Vad är Head of Kelris till för?",a="Huvudet är ett obestridligt bevis på kultledarens död. Dawnwatcher Selgorm och Argent Dawn trodde att Kelris var död eller försvunnen efter år av svårfångad skurkaktighet över Kalimdor. När du för hans huvud till Selgorm i Darnassus bekräftar du att hans skräckvälde och blodsoffer äntligen har fått ett slut.",al={"head of kelris","varför behöver jag kelris huvud","vad ska jag göra med kelris huvud"}},["5d00ba2b"]={q="Varför kan inte Argent Guard Thaelrid själv döda Kelris?",a="Thaelrid befinner sig djupt inne i de översvämmade ruinerna, sårad och fullständigt utmattad. Han har förlorat all sin styrka och kan inte kämpa sig igenom kultisterna och naga, än mindre själv fälla Kelris. Han förlitar sig på att du slutför uppdraget i hans ställe.",al={"varför slåss inte thaelrid mot kelris","varför behöver thaelrid mig","kan thaelrid döda kelris"}}},fp="20,239,19.327.0,23.358.0,20.366.1,29.209.0,43.180.0,27.192.0,41.201.0,15.200.0,56.215.0"}
P.entries["quest:1201"] = {n="Theramore Spies",s="Vapenvilan mellan Horde och Alliance är skör, med skärmytslingar och hemliga handlingar på båda sidor. Nazeer Bloodpike i Brackenwall Village vill att Alliance-infiltratörerna öster om byn spåras upp och dödas.",h="Vapenvilan mellan Horde och Alliance är skör, med skärmytslingar och hemliga handlingar på båda sidor.",kw={"brackenwall","dustwallow","infiltratörer","nazeer bloodpike","spioner","theramore"},sec={{t="Spioner öster om byn",b="Alliance-infiltratörer har slagit sig ner öster om Brackenwall Village, där de håller byn under uppsikt och rapporterar Horde-rörelser till Theramore. Nazeer Bloodpike, den lokala spionmästaren, tänker inte tolerera det. Du får i uppdrag att hitta infiltratörerna och döda dem, så att deras överordnade förstår att sådana spioner inte är välkomna."}},faq={{q="Vem beordrar att Theramore-infiltratörerna ska dödas?",a="Nazeer Bloodpike, den lokala spionmästaren i Brackenwall Village.",al={"vem ger uppdraget theramore spies","nazeer bloodpikes spionuppdrag","vem startar theramore spies"}},{q="Var gömmer sig infiltratörerna?",a="Öster om Brackenwall Village, på öarna.",al={"theramore-infiltratörernas plats","var hittar man theramore-spionerna","infiltratörernas platser i dustwallow"}},{q="Varför bevakar spionerna Brackenwall Village?",a="De håller byn under uppsikt och rapporterar Horde-rörelser till Theramore.",al={"varför spionerar människor på brackenwall","brackenwall villages spionmotiv"}},{q="Vad händer efter att spionerna har tagits om hand?",a="Nästa steg i berättelsen är The Theramore Docks.",al={"fortsättning på theramore spies","vilket uppdrag kommer efter theramore spies"}}},fp="15,217,25.298.0,51.61.0,34.44.0,47.74.0,40.50.0"}
P.entries["quest:1202"] = {n="The Theramore Docks",s="Två spioner skickades för att stjäla papper från ett skepp i Theramore, men de blev upptäckta och tvingades kasta papperen i havet. Nu ger Nazeer Bloodpike dig i uppdrag att hitta dem.",h="Två spioner skickades för att stjäla papper från ett skepp i Theramore, men de blev upptäckta och tvingades...",kw={"brackenwall village","captain's documents","hamn","dustwallow marsh","fotkista","nazeer bloodpike","spioner","theramore"},sec={{t="Papper i vattnet",b="När du hade tagit hand om spionerna i Theramore har Nazeer Bloodpike ett nytt ärende åt dig. Två spioner skickades för att hämta papper från ett skepp vid Theramores hamn. De fick tag i dem, blev upptäckta och tvingades kasta sitt byte i havet. En av dem kom undan men kunde inte hämta papperen, och återvände för att rapportera misslyckandet."},{t="Under hamnen",b="Papperen ligger i en fotkista någonstans under vattnet vid Theramores hamn. Du skickas för att hitta Captain's Documents och ta dem till Nazeer Bloodpike i Brackenwall Village. Nazeer säger att de är mycket viktiga för Alliansens stabilitet och därmed för Hordens säkerhet."}},faq={{q="Vem skickar dig till Theramore Isle?",a="Nazeer Bloodpike i Brackenwall Village.",al={"vem ger uppdraget","var börjar uppdraget","uppdragsgivare"}},{q="Vad letar du efter under hamnen?",a="En fotkista i vattnet under Theramores hamn, med Captain's Documents i.",al={"vad måste jag hitta","vilket föremål finns i vattnet","hamnens mål"}},{q="Varför kastades dokumenten i vattnet?",a="Två spioner stal papperen från ett skepp vid hamnen, men de blev upptäckta och tvingades kasta dem i havet. En kom undan utan dem.",al={"varför ligger papperen i havet","hur hamnade fotkistan där","varför släppte spionerna den"}},{q="Varför vill Horden ha de här dokumenten?",a="Nazeer Bloodpike säger att de är mycket viktiga för Alliansens stabilitet och därmed för Hordens säkerhet.",al={"varför är papperen viktiga","vad står i dokumenten","varför vill bloodpike ha dem"}},{q="Vad händer före detta i berättelsen?",a="Det följer på Theramore Spies, där du jagade infiltratörerna öster om Brackenwall Village.",al={"förkunskapsuppdrag","föregående uppdrag","vad leder fram till detta"}}},fp="19,173,19.316.0,17.282.0,32.41.0,43.88.0,45.138.0,40.107.0,40.93.0"}
P.entries["quest:1203"] = {n="Jarl Needs a Blade",s="\"Swamp Eye\" Jarl i Dustwallow Marsh har något att skära till, men säger inte vad. Jarl vill ha ett visst svärd, ett bredsvärd av månmetall, och vill inte att du dröjer.",h="\"Swamp Eye\" Jarl i Dustwallow Marsh har något att skära till, men säger inte vad.",kw={"dustwallow marsh","jarl","bredsvärd av månmetall","swamp eye jarl","huggsvärd"},sec={{t="Ett visst svärd",b="\"Swamp Eye\" Jarl har något att skära till, men kan inte säga vad. Jarl behöver ett särskilt svärd, som vissa kallar ett bredsvärd av månmetall och Jarl kallar ett huggsvärd. Du kanske hittar ett i staden, eller så kan en smed tillverka ett särskilt åt dig. Jarl varnar dig för att inte ligga på saken, eftersom det som ska skäras till inte håller för evigt."}},faq={{q="Vem ber om svärdet?",a="\"Swamp Eye\" Jarl, som finns i Dustwallow Marsh.",al={"vem ger jarl behöver ett svärd","vem är jarl","swamp eye jarl"}},{q="Vilket vapen behöver Jarl?",a="Ett bredsvärd av månmetall, som Jarl kallar ett huggsvärd.",al={"vilket svärd vill jarl ha","jarls vapen","vilket svärd behöver jarl"}},{q="Varför behöver Jarl ett svärd så brådskande?",a="Jarl har något att skära till, kan inte säga vad och varnar för att det inte håller för evigt.",al={"varför behöver jarl ett svärd","vad skär jarl","jarls syfte"}},{q="Var föreslår Jarl att du letar efter svärdet?",a="Jarl säger att du kanske hittar ett i staden eller kan tala med en smed som kan tillverka ett särskilt åt dig.",al={"hur får man ett bredsvärd av månmetall åt jarl","var hittar man ett svärd åt jarl"}}},fp="18,164,15.319.0,28.51.0,30.55.0,39.94.0,42.86.0"}
P.entries["quest:1204"] = {n="Mudrock Soup and Bugs",s="I Theramore lagar Morgan Stern en rätt som kallas Mudrock Soup and Bugs, kanske nästa stora succé på värdshusen i Stormwind City. Morgan Stern tvivlar på att de skulle klara en lång färd genom Dustwallow Marsh och ber dig därför samla tungor från Mudrock-sköldpaddorna.",h="I Theramore lagar Morgan Stern en rätt som kallas Mudrock Soup and Bugs, kanske nästa stora succé på...",kw={"blue recluse","insekter","dustwallow marsh","kluvna tungor","morgan stern","mudrock","soppa","theramore"},sec={{t="En rätt tar form",b="Morgan Stern lagar en rätt som kallas Mudrock Soup and Bugs och behöver fortfarande de viktigaste ingredienserna. En lång färd genom Dustwallow Marsh är mer än Morgan Stern tror sig klara, så du ombeds jaga lite. Först behövs tungor från Mudrock-sköldpaddor."},{t="Kluvna tungor",b="Mudrocks strövar längs kusten, mest kring bukten. Morgan Stern vill inte ha vilka tungor som helst. Morgan Stern har hört att vissa Mudrocks har kluvna tungor och att de har en särskild smak som passar i rätten."},{t="På väg till bordet",b="Morgan Stern ska prova olika sätt att tillaga tungorna för att hitta det som bäst framhäver smaken. Förhoppningen är att rätten ska passa att serveras på Blue Recluse i Stormwind."}},faq={{q="Vem ber om sköldpaddstungorna?",a="Morgan Stern i Theramore, som lagar en rätt som kallas Mudrock Soup and Bugs.",al={"vem startar mudrock soup and bugs","morgan stern theramore"}},{q="Var hittar man Mudrock-sköldpaddorna?",a="Längs kusten i Dustwallow Marsh, mest kring bukten.",al={"mudrock-sköldpaddans plats","var finns mudrocks"}},{q="Varför vill Morgan Stern särskilt ha kluvna tungor?",a="Morgan Stern har hört att de har en särskild smak och vill ha den smaken i rätten.",al={"varför kluvna tungor","varför kluvna mudrock-tungor"}},{q="Varför samlar Morgan Stern inte själv in ingredienserna?",a="Morgan Stern tror inte att de skulle klara en lång färd genom Dustwallow Marsh.",al={"varför jagar inte morgan stern","morgan stern i träsket"}},{q="Vad kommer efter det här uppdraget?",a="Nästa steg heter ... and Bugs.",al={"nästa uppdrag efter mudrock soup","fortsättning på mudrock soup"}}},fp="21,279,20.265.0,14.216.0,16.178.1,37.82.0,39.59.0,55.87.0,56.84.0,28.37.0"}
P.entries["quest:1205"] = {n="Deadmire",s="Deadmire är en jaktprövning som taurenjägaren Melor Stonehoof erbjuder på Hunter Rise i Thunder Bluff. Uppdraget skickar jägare österut till Dustwallow Marsh för att spåra upp och döda en uråldrig, plågad krokolisk vid namn Deadmire och ta med dess tand som bevis. Det är en övning i både krävande spårning och jägarens plikt att visa barmhärtighet.",h="Deadmire är en jaktprövning som taurenjägaren Melor Stonehoof erbjuder på Hunter Rise i Thunder Bluff.",kw={"krokolisk","deadmire","dustwallow marsh","hunter rise","melor stonehoof","stonemaul ruins","thunder bluff"},ang={["class:Hunter"]="För jägare visar spårandet av Deadmire balansen mellan krigisk skicklighet och andligt ansvar. Det betonar att ett hedervärt dödande kan vara en nådshandling.",["faction:Horde"]="Jakter åt Thunder Bluffs äldste hjälper resande från Horde att knyta an till landet och taurenallierades andliga traditioner.",["race:Tauren"]="Jakten speglar taurenfolkets grundläggande värderingar om harmoni med Jordmoderns varelser. Den lär ut att en sann jägare hedrar sitt byte och respekterar livets och dödens naturliga kretslopp."},sec={{t="En barmhärtig jakt",b="På Hunter Rise i Thunder Bluff undervisar Melor Stonehoof lovande spårare i jaktens djupare andliga traditioner. Taurenernas jaktfilosofi lär ut vördnad och samhörighet med naturen, till skillnad från tanklöst dödande eller troféjakt. Melor ber jägarna resa långt österut till Dustwallow Marshs grumliga våtmarker för att söka upp Deadmire, en uråldrig krokolisk av väldig storlek vars långa liv har blivit en plågsam börda."},{t="Träskets uråldriga best",b="Deadmire är inget vanligt vilddjur. Han är en enorm, blek krokolisk som strövar i vattendragen norr om Stonemaul Ruins. Hans ungdomliga raseri och fysiska styrka visar sig ännu i plötsliga utbrott, men hans åldrande kropp är nedbruten av värkande ben och oupphörlig smärta. Melor ber jägarna ge varelsen ett hedervärt och snabbt slut, låta dess ande få ro och ta en enda tand som tecken på att besten befriats."}},faq={{q="Vem är Deadmire?",a="Deadmire är en väldig, uråldrig vit krokolisk som lever i träskmarkerna i Dustwallow Marsh. Han är fortfarande farligt stark, men lider av outhärdlig fysisk smärta på grund av sin sviktande, åldrade kropp.",al={"vad är deadmire","deadmire-lore","vem är krokoliskerna"}},{q="Varför vill Melor Stonehoof att Deadmire ska dödas?",a="Melor ser jakten som en barmhärtighetshandling snarare än en erövring. Deadmires åldrande ben orsakar honom vansinniga smärtor, och taurenjägaren anser att det är en helig plikt att befria den ädla besten från dess lidande och ge den ro.",al={"varför döda deadmire","melor stonehoofs motiv","syftet med deadmire-jakten"}},{q="Var finns Deadmire?",a="Deadmire hemsöker Dustwallow Marshs grumliga vatten och öar. Vanligtvis strövar han i flodfårorna strax norr om Stonemaul Ruins.",al={"var finns deadmire","deadmire-plats","hitta deadmire"}},{q="Vilket bevis vill Melor ha från jakten?",a="Melor ber dig ta med Deadmire's Tooth som bevis på att den mäktiga varelsens lidande äntligen har fått ett slut.",al={"föremål från deadmire-uppdraget","vad vill melor ha","bevis för deadmire"}},{q="Vad lär jakten blivande jägare?",a="Jakten lär ut att jägarens väg inte handlar om tanklöst dödande, utan om andlig samhörighet med naturen. En del av den kallelsen är att inse när en varelses liv har blivit ett lidande och ge den en barmhärtig och hedervärd död.",al={"jägarfilosofi","taurenjägarnas lärdom","jaktens innebörd"}},{q="Vem ger det här uppdraget?",a="Uppdraget erbjuds av Melor Stonehoof, en taurenjägare som finns på Hunter Rise med utsikt över staden Thunder Bluff.",al={"deadmire-uppdragets uppdragsgivare","vem startar deadmire-uppdraget","var finns melor stonehoof"}}},fp="8,249,15.322.0,24.316.0,16.157.0,46.173.0,28.79.0,44.74.0,43.152.0,21.82.0"}
P.entries["quest:1206"] = {n="Jarl Needs Eyes",s="\"Swamp Eye\" Jarl på Swamplight Manor vill ha 40 opoppade Darkmist-ögon, eftersom saften från Darkmist-ögon är len och salt. Spindlarna bor i Darkmist Cavern, väster om herrgården.",h="\"Swamp Eye\" Jarl på Swamplight Manor vill ha 40 opoppade Darkmist-ögon, eftersom saften från Darkmist-ögon är...",kw={"darkmist","darkmist cavern","dustwallow marsh","jarl","spindelögon","swamp eye jarl","swamplight manor"},sec={{t="En smak av spindelögon",b="Efter Soothing Spices vänder sig Jarl till ögonsaft, som är god att dricka. De flesta småkryp har bara ett par ögon, medan spindlar har väldigt många, och Jarl tycker att saften från Darkmist-ögon är god. Darkmist-spindlarna bor i Darkmist Cavern, väster om herrgården, och Jarl funderar på om grottan gav spindlarna deras namn eller tvärtom."},{t="En fest för Jarl",b="Jarl jublar när ögonen anländer och kallar dem goda. Jarl råder dig att spara dem som stirrar tillbaka när man stirrar på dem till sist, eftersom de ger en person sällskap i träsket. Sedan hälsar Jarl på de små ögonen, smakar på dem och säger att de smakar som kladdig, salt kyckling."}},faq={{q="Vem ber om spindelögonen?",a="\"Swamp Eye\" Jarl ber om dem på Swamplight Manor i Dustwallow Marsh.",al={"vem ger uppdraget","jarl uppdragsgivare","swamp eye jarl"}},{q="Varför vill Jarl ha spindelögon?",a="Jarl gillar ögonsaft att dricka och tycker att saften från Darkmist-ögon är len och salt. De flesta småkryp har bara två ögon, medan spindlar har väldigt många.",al={"varför spindelögon","vad gör jarl med ögonen","ögonsaft"}},{q="Var finns Darkmist-spindlarna?",a="Jarl säger att Darkmist-spindlarna finns i Darkmist Cavern, väster om Swamplight Manor.",al={"darkmist cavern plats","var finns darkmist-spindlar","var hittar man ögon"}},{q="Hur många ögon vill Jarl ha?",a="Jarl vill ha 40 opoppade Darkmist-ögon.",al={"hur många ögon","antal ögon"}},{q="Vad kommer före detta?",a="Soothing Spices kom först.",al={"föregående uppdrag","förutsättning","vad leder fram till detta"}}},fp="15,173,23.343.0,16.276.1,29.72.0,31.147.0,31.85.0,29.37.0,23.27.0"}
P.entries["quest:121"] = {n="Messenger to Stormwind",s="Du för General Marcus Jonathans svar från Stormwind till Lakeshire, där Blackrock-orcher och gnoller hotar staden. Huvudstaden erbjuder inga trupper, så samhället får möta faran medan Stormwinds ledare dröjer.",h="Du för General Marcus Jonathans svar från Stormwind till Lakeshire, där Blackrock-orcher och gnoller hotar...",kw={"blackrock-orcher","bolvar","lakeshire","magistrate solomon","marcus jonathan","messenger to stormwind","redridge mountains","stormwind"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur det politiska dödläget lämnar kungarikets mänskliga territorier utsatta för regionala hot.",["race:Human"]="Som människa i kungariket för du denna korrespondens mellan Stormwind Citys skyddade trygghet och de sönderfallande gränsområdena hos dess grannar i Elwynn."},sec={{t="Ett meddelande till Lakeshire",b="Du förde Magistrate Solomons vädjan om förstärkningar till General Marcus Jonathan i Stormwind. Nu för du hans preliminära svar tillbaka till Redridge medan han väntar på tronens godkännande. Utan kungligt tillstånd kan generalen inte sätta in armén. Lakeshires invånare står fortfarande utan stadsvakter, och för varje dag kommer samhället närmare att falla för Blackrock-klanen."},{t="Oro i kungariket",b="Magistrate Solomon ser inga utlovade bataljoner marschera österut längs Elwynn-gränsen i Jonathans svar. Brevet erbjuder undanflykter och procedurer i stället för trupper, och Solomon anar att något är fel vid det kungliga hovet. King Varian Wrynn är försvunnen, och regentskapet har låst sig. Avlägsna städer som Lakeshire lämnas att försvara sig själva."}},faq={{q="Vad står det i General Marcus Jonathans svar?",a="I brevet skriver General Marcus Jonathan att han inte kan skicka Stormwinds armé utan formellt tillstånd från kungen eller det kungliga hovet. Han säger att frågan har tagits upp med kronan, så Lakeshire får vänta.",al={"vad står det i brevet","generalens svar","marcus jonathans brev"}},{q="Varför kan Stormwind inte bara skicka soldater till Redridge?",a="När King Varian Wrynn är försvunnen vilar regeringsbesluten hos den unge King Anduin, Regent Lord Bolvar Fordragon och House of Nobles. Splittringen och dröjsmålen i huvudstaden hindrar General Jonathan från att marschera utan kungligt godkännande.",al={"varför hjälper stormwind inte","varför hjälper stormwind inte lakeshire","stormwinds armé redridge"}},{q="Vem är Magistrate Solomon?",a="Magistrate Solomon styr Lakeshire och Redridge Mountains. Han leder samhället och samordnar dess knappa försvar mot Blackrock-orcher, gnoller och lokala stråtrövare.",al={"magistrate solomon","vem är solomon","lakeshires magistrat"}},{q="Vem är General Marcus Jonathan?",a="General Marcus Jonathan för befäl över Stormwind City Guard och huvudstadens stående väpnade styrkor. Han är stationerad vid Valley of Heroes, strax innanför Stormwind Citys huvudportar.",al={"vem är marcus jonathan","general jonathan","stormwinds general"}},{q="Vad gör Solomon efter att ha läst brevet?",a="Efter att ha läst brevet söker Solomon hjälp från grannregionerna och skickar dig för att ta reda på läget i Westfall.",al={"vad händer sedan","uppdrag efter messenger to stormwind","vart ska man gå sedan"}},{q="Varför säger Solomon ”något är på tok i vårt kungarike”?",a="Solomon ser ingen militär logik i att neka eller dröja med hjälp till en gränsstad som är under attack. Dröjsmålet varnar honom för att Stormwinds politiska ledare manipuleras eller lamslås inifrån.",al={"något är på tok","varför är solomon orolig","stormwind-konspiration"}}},fx={["53d96341"]={q="Varför skickar General Marcus Jonathan dig tillbaka till Lakeshire?",a="Magistrate Solomon vädjade skyndsamt till Stormwind om militära förstärkningar för att värja sig mot hoten från gnolls och orcher som omringar Lakeshire. General Jonathan bad tronen om hjälp, men han kan inte skicka ut kungliga trupper utan kronans tillstånd. Han skickar tillbaka dig med sitt officiella svar, så att Lakeshires ledare inte lämnas ovetande medan överläggningarna i huvudstaden drar ut på tiden.",al={"varför skickar marcus jonathan ett brev","marcus jonathans svar till lakeshire","varför behöver general jonathan få detta gjort"}},["64d074bd"]={q="Varför anförtror General Jonathan brevet åt dig i stället för en kunglig kurir?",a="Det var du som bar Solomons ursprungliga vädjan från Redridge till Valley of Heroes. Stormwinds stadsgarnison är redan hårt ansträngd med att upprätthålla ordningen och bevaka huvudstadens portar. Därför tycker General Jonathan att det är mycket mer praktiskt att skicka en duglig äventyrare som känner vägen tillbaka till Lakeshire än att ta en av sina egna posterade vakter från tjänsten.",al={"varför skickar marcus jonathan mig","varför inte en kunglig vakts kurir","varför leverera till lakeshire som äventyrare"}}},fp="22,205,23.372.0,21.320.1,46.198.0,51.229.0,26.175.0,31.180.0,51.112.1,57.192.0"}
P.entries["quest:1218"] = {n="Soothing Spices",s="\"Swamp Eye\" Jarl älskar matlagning på träskvis och behöver lugnande krydda till en gryta. Jarl i Dustwallow Marsh ber dig ta med tre Soothing Spices.",h="\"Swamp Eye\" Jarl älskar matlagning på träskvis och behöver lugnande krydda till en gryta.",kw={"dustwallow marsh","grodlår","lugnande kryddor","gryta","swamp eye jarl"},sec={{t="Krydda till grytan",b="\"Swamp Eye\" Jarl tycker om att laga mat på träskvis, med bland annat friterade gröna grodlår. En gryta ska lagas, och till den behöver Jarl lugnande krydda. Den som kommer med den får en andel. Jarl vill ha tre Soothing Spices och undrar om du tycker om gryta."}},faq={{q="Vem vill ha de lugnande kryddorna?",a="\"Swamp Eye\" Jarl, som finns i Dustwallow Marsh.",al={"vem ger lugnande kryddor","uppdragsgivare lugnande kryddor","swamp eye jarl kryddor"}},{q="Vad tänker Swamp Eye Jarl laga med kryddorna?",a="En gryta. Jarl tycker om träskmatlagning, bland annat friterade gröna grodlår, och planerar att dela grytan med dig.",al={"vad lagar jarl","vilken gryta lagar jarl","jarls mat"}},{q="Hur många kryddor behöver Jarl?",a="Jarl ber om tre Soothing Spices.",al={"hur många lugnande kryddor","antal lugnande kryddor","krav på lugnande kryddor"}}},fp="15,147,17.268.0,30.51.0,56.107.0,31.36.0"}
P.entries["quest:1219"] = {n="The Orc Report",s="När du sållar bland lös jord i Dustwallow Marsh hittar du en avhuggen orc-hand som håller fast ett rör skuret ur ben. Inuti ligger ett jordfläckat pergament med orcisk skrift, som verkar viktigt. Det är avsett för en Theramore Lieutenant.",h="När du sållar bland lös jord i Dustwallow Marsh hittar du en avhuggen orc-hand som håller fast ett rör skuret...",kw={"benrör","dustwallow marsh","lös jord","orc-rapport","theramore lieutenant"},sec={{t="En hand i jorden",b="I den lösa jorden ligger en avhuggen orc-hand som håller fast ett rör skuret ur ben. Inuti finns ett pergament fläckat av jord, och skriften är orcisk, vilket verkar betydelsefullt. Det är en Theramore Lieutenant du ska visa det för."},{t="Löjtnantens bedömning",b="Löjtnanten medger att hen läser orciska dåligt, men tar pergamentet för en orcisk spions rapport."}},faq={{q="Vad döljer sig i den lösa jorden?",a="När du sållar igenom den hittar du en avhuggen orc-hand som håller fast ett rör skuret ur ben, med ett jordfläckat pergament inuti.",al={"vad hittar man i lös jord","föremål i lös jord","orc-hand i dustwallow"}},{q="Vem ska få pergamentet?",a="En Theramore Lieutenant.",al={"vart tar jag rapporten","vem får spionrapporten","theramore lieutenant plats"}},{q="Vilket språk är pergamentet skrivet på?",a="Skriften är orcisk och verkar betydelsefull.",al={"pergamentets språk","kan jag läsa pergamentet"}}},fp="14,236,18.220.0,24.96.1,33.122.0,29.23.0,42.48.0"}
P.entries["quest:122"] = {n="Underbelly Scales",s="Verner Osgood behöver bukfjäll från svarta draklingar för att betala sin handelsskuld till Smith Argus i Goldshire. För att samla in dem måste du jaga de unga drakar som strövar bland klipporna söder om Lakeshire. Fjällen löser Verners skuld och ger tillräckligt med råhud för att tillverka en utrustningsdel.",h="Verner Osgood behöver bukfjäll från svarta draklingar för att betala sin handelsskuld till Smith Argus i...",kw={"svart drakling","drakflykt","goldshire","lakeshire","redridge","smith argus","bukfjäll","verner osgood"},ang={["faction:Alliance"]="Hotet från den svarta drakflykten växer söder om Lakeshire och belastar ytterligare en redan överansträngd garnison som kämpar för att hålla Redridge.",["profession:Blacksmithing"]="Smith Argus krav visar hur sällsynta ingredienser som drakfjäll används som värdefull bytesvara mellan smeder när det råder brist på vanliga mynt.",["race:Human"]="Handelsvägarna mellan Elwynn och Redridge förser städer som Lakeshire med varor, men hantverkare vid gränsen måste ofta betala höga priser till stadsborna."},sec={{t="En skuld vid gränsen",b="Att driva en smedja i utkanten av Lakeshire kräver sällsynta förnödenheter, och Verner Osgood handlar ofta med hantverkare bortom Redridge Mountains. Efter att ha fått en leverans hästskor från Smith Argus i Goldshire saknar Verner vanliga mynt. Argus kräver i stället betalning i värdefullt drakskinn: närmare bestämt de mjukare, högt värderade bukfjällen från de svarta draklingar som har sina bon i trakten. Utan dem riskerar Verner att indrivare skickas från Elwynn Forest för att kräva in skulden."},{t="Den svarta flyktens yngel",b="Att svarta draklingar finns i Redridge Mountains är ett illavarslande tecken för de lokala försvararna. Gnoller och orcher strider öppet om vägarna, men den svarta drakflykten har sina bon i de höga topparna och svävar över himlen söder om Lake Everstill. De unga rovdjurens bukfjäll är tåliga men smidiga, vilket gör dem till eftertraktade hantverksmaterial för rustningsmakare, smeder och läderarbetare i hela kungariket som vågar samla in dem."}},faq={{q="Varför behöver Verner Osgood drakfjäll?",a="Verner är skyldig Smith Argus i Goldshire för en leverans hästskor. Argus kräver betalning i bukfjäll från svarta draklingar i stället för vanliga mynt. Verner behöver få fjällen levererade snabbt, innan Argus skickar indrivare för att kräva in skulden.",al={"varför drakfjäll","verners skuld","argus fjäll"}},{q="Var hittar man svarta draklingar i Redridge?",a="Svarta draklingar strövar ofta bland de klippiga branterna och dalarna söder om Lakeshire. De rör sig fritt över de södra bergssluttningarna, så jägare måste ofta patrullera stigarna och höjdryggarna för att få syn på dem i luften.",al={"draklingars platser","var finns draklingar","draklingars plats redridge"}},{q="Vem är Smith Argus?",a="Smith Argus är smeden som håller till i Goldshire i Elwynn Forest. Han tillverkar smidesvaror åt närliggande bosättningar, däribland hästskor åt Verner Osgood i Redridge.",al={"argus goldshire","vem är argus","smith argus"}},{q="Varför finns svarta draklingar i Redridge Mountains?",a="Den svarta drakflykten håller till i Burning Steppes och de omgivande topparna i Redridge. Dess draklingar jagar och strövar söderut genom bergspassen till Redridges bergssluttningar.",al={"varför finns drakar i redridge","svarta drakar redridge","svarta drakflykten redridge"}},{q="Vad gör bukfjäll speciella?",a="Medan drakarnas ryggfjäll är tjocka och styva, är bukfjällen mjuka och böjliga samtidigt som de står emot hetta och genomträngning väl. Därför passar de utmärkt för specialiserat läderarbete, förstärkningar som skräddarsys och exotiska handelsvaror.",al={"varför bukfjäll","fjällens värde","drakskinnets kvalitet"}},{q="Leder det till fler uppgifter åt Verner när skulden är betald?",a="Det här är en av Verner Osgoods förfrågningar efter att du har hämtat hästskoleveransen åt honom. Förutom det här frivilliga insamlingsuppdraget ber Verner äventyrare att möta det växande gnollhotet i Redridge genom att jaga deras spejare och ledare.",al={"what comes next","verners uppdragskedja","uppföljning osgood"}}},fx={["43de1078"]={q="Varför ber Verner dig jaga drakungar i stället för att göra det själv?",a="Verner Osgood är upptagen med att sköta Lakeshires livliga stall och smedja, medan de lokala vakterna är fullt sysselsatta med att försvara sig mot gnollernas och orchernas intrång. Att bege sig söderut bland kullarna för att jaga kringströvande svarta drakungar kräver skickliga äventyrare som kan spåra farligt vilt och klara sig i vildmarken.",al={"varför behöver verner mig","varför kan inte verner jaga drakungar","varför frågar han mig om underbelly scales"}}},fp="17,275,15.420.0,25.379.0,42.236.0,52.194.0,19.184.0,50.199.0,37.247.0,55.208.0"}
P.entries["quest:1220"] = {n="Captain Vimes",s="Lieutenant Aden skickar dig med orcrapporten du hittade till Captain Garran Vimes, som läser orchspråk bättre än de flesta. Nyheten om Hordens spioner nära Theramore ska följa med.",h="Lieutenant Aden skickar dig med orcrapporten du hittade till Captain Garran Vimes, som läser orchspråk bättre...",kw={"captain vimes","dustwallow marsh","garran vimes","lieutenant aden","orcrapport","spionrapport","theramore","theramore isle"},sec={{t="En rapport till kaptenen",b="Lieutenant Aden tycker att orcrapporten du hittade hör hemma hos Captain Garran Vimes, som läser orchspråk bättre än de flesta. Aden vill också att kaptenen får veta att Hordens spioner håller sig gömda nära Theramore. Du hittar Vimes i kasernen på nordöstra sidan av Theramore Isle."}},faq={{q="Vem skickar dig till Captain Vimes?",a="Lieutenant Aden, som vill att kaptenen ska se orcrapporten du hittade.",al={"vem startar captain vimes","var hittar jag captain vimes"}},{q="Var finns Captain Garran Vimes?",a="I kasernen på nordöstra sidan av Theramore Isle.",al={"var finns captain vimes","captain vimes plats","vimes kasern"}},{q="Varför behöver Captain Vimes se rapporten?",a="Aden säger att Vimes läser orch bättre än de flesta och bör få veta att Hordens spioner är nära Theramore.",al={"varför captain vimes","varför behöver vimes rapporten"}}},fp="13,168,24.285.0,31.71.0,38.55.0,46.103.0"}
P.entries["quest:1221"] = {n="Blueleaf Tubers",s="Blueleaf Tubers är ett uppdrag att hämta varor, beställt av goblinköpmannen Mebok Mizzyrix i Ratchet. För att tjäna på en sällsynt delikatess från underjorden förser Mizzyrix äventyrare med tränade snufflenose-gofrar som ska hitta och gräva upp knölarna, begravda i Razorfen Krauls taggiga djup.",h="Blueleaf Tubers är ett uppdrag att hämta varor, beställt av goblinköpmannen Mebok Mizzyrix i Ratchet.",kw={"blueleaf tubers","kommandostav","delikatess","mebok mizzyrix","quilboar","ratchet","razorfen kraul","snufflenose-gofer","the barrens"},ang={["faction:Alliance"]="Alliansexpeditioner som kommer till den neutrala hamnen Ratchet kan utnyttja Mizzyrix handelskontrakt som förevändning för att ge sig in i fientligt territorium intill Horde.",["faction:Horde"]="Hordekrigare som försvarar The Barrens mot quilboarernas räder kan enkelt tjäna lite extra på att låta Mizzyrix tränade gofrar löpa genom Kraul.",["profession:Cooking"]="Kulinära hantverkare vet att blueleaf-knölar räknas bland Azeroths sällsyntaste delikatesser och betingar höga priser hos förnäma köpare som uppskattar deras särpräglade, jordiga smak.",["profession:Herbalism"]="Till skillnad från vanliga växter ovan jord trivs blueleaf-knölar endast under marken, bland Razorfen Krauls törnrötter, skyddade från solljus."},sec={{t="En eftertraktad delikatess från underjorden",b="Blueleaf-knölar är eftertraktade världen över som en sällsynt och lyxig delikatess. Trots sitt höga värde är de ökända för att vara svåra att skörda, eftersom de inte växer på öppna fält eller i vanliga vildmarker. I stället finns de nästan bara djupt nere i den solfria jorden under södra The Barrens, intrasslade bland Razorfen Krauls labyrintiska rötter."},{t="Mizzyrix uppfinningsrikedom",b="Eftersom knölarna ligger helt begravda och är nästan omöjliga för vanliga humanoider att upptäcka, kom köpmannen Mebok Mizzyrix i Ratchet på en ovanlig lösning. Genom att träna lokala snufflenose-gofrar, varelser som kan känna lukten av en begravd knöl på femtio stegs avstånd, gjorde Mizzyrix skadedjur till födosöksredskap. Han förser asätare med en kommandostav, en ventilerad låda och en instruktionsbok som ska vägleda djuren genom quilboarernas område."},{t="Skörd bland törnena",b="För att hämta knölarna måste man ta sig in på den fientliga Death's Head-stammens quilboarers område. Födosökare måste skydda sina tränade gofrar från Krauls vilddjur och taggiga snår och beordra gnagarna att gräva upp de gömda lökarna innan de packar ner dem för transport tillbaka till Ratchet, där Mizzyrix högbetalande utländska köpare väntar."}},faq={{q="Vad används Blueleaf Tubers till?",a="De anses vara en sällsynt och mycket eftertraktad delikatess världen över. Förmögna köpare betalar stora summor för färska knölar, vilket gör dem till en lönsam handelsvara för gobliner som Mebok Mizzyrix.",al={"användning av blueleaf tuber","vad är blueleaf tubers","varför samla blueleaf tubers"}},{q="Var finns Blueleaf Tubers?",a="De växer begravda i jorden under marken och bland de taggiga rotsystemen under södra The Barrens, särskilt inne i quilboarernas fäste Razorfen Kraul.",al={"var hittar man blueleaf tubers","blueleaf tubers plats","var växer de"}},{q="Varför behövs en Snufflenose Gopher för att hitta dem?",a="Knölarna är helt gömda under jord och kan inte upptäckas med vanlig syn. Snufflenose-gofren har ett skarpt luktsinne och kan känna lukten av begravda knölar på upp till femtio stegs avstånd, så att den kan gräva upp dem ur jorden.",al={"varför använda gofrar","snufflenose-gofrens uppgift","hur hittar gofrar knölar"}},{q="Vem är Mebok Mizzyrix?",a="Mebok Mizzyrix är en företagsam goblinköpman som håller till i den neutrala hamnstaden Ratchet i The Barrens. Han specialiserar sig på att träna inhemska vilda djur och skaffa exotiska varor för utrikeshandel.",al={"vem ger uppdraget med blueleaf tubers","mebok mizzyrix bakgrund","uppdragsgivare i ratchet"}},{q="Vilken utrustning tillhandahåller Mizzyrix för uppdraget?",a="Mizzyrix ger äventyrare en Crate With Holes med en tränad gofer, en Snufflenose Command Stick som används för att styra djuret när det gräver och en Snufflenose Owner's Manual med instruktioner för hur besten ska hanteras.",al={"föremål till knöluppdraget","kommandostav för gofer","crate with holes"}},{q="Varför samlar inte Mebok in knölarna själv?",a="Razorfen Kraul bevakas hårt av aggressiva quilboarstammar, taggiga rankor och farliga rovdjur under jord. Mizzyrix föredrar att riskera legoknekters liv framför att själv ge sig in i de farliga gravkamrarna.",al={"varför hämtar mebok dem inte själv","varför anlita äventyrare"}}},fx={["8175ef8b"]={q="Varför vill Mebok Mizzyrix ha Blueleaf Tubers?",a="Mebok Mizzyrix drivs av enkel goblinhandel: vinst. Blueleaf tubers är en ytterst sällsynt delikatess i världen och finns bara djupt under jorden i Razorfen Kraul. Eftersom vanliga samlare inte lätt kan hitta dem betingar de ett enormt pris. Mebok tänker sälja allt du hämtar tillbaka till sina välbärgade kontakter för en rejäl slant och ge dig en blygsam del av intäkterna för att du riskerar liv och lem för att hämta dem.",al={"mebok mizzyrix motiv","varför vill mebok ha knölar","varför samla blueleaf tubers"}},e7d11e5c={q="Vad är Crate With Holes till för?",a="Crate With Holes är en specialbyggd transportlåda som Mebok har gjort för att hålla en tränad snufflenose-gopher. Lufthålen håller djuret vid liv och låter det andas bekvämt tills du når djupen i Razorfen Kraul, där du tryggt kan släppa ut det så att det kan börja nosa upp begravda knölar.",al={"användning av crate with holes","vad är crate with holes","varför crate with holes"}},["91901628"]={q="Vad är Snufflenose Command Stick till för?",a="Kommando käppen är ett träningsredskap som Mebok har utformat för att styra snufflenose-gophern. När du håller i den får varelsen signalen att fokusera sitt skarpa luktsinne, söka igenom grottgolvet i närheten och gräva upp alla gömda blueleaf tubers som den känner doften av.",al={"kommando käppens syfte","vad gör snufflenose command stick","snufflenose command stick"}},af9e7fb9={q="Vad är Snufflenose Owner's Manual till för?",a="Manualen innehåller Meboks skriftliga instruktioner om hur du hanterar gophern, styr den med kommando käppen och lyckas hitta knölarna utan att tappa bort hans tränade best i quilboar-tunnlarna.",al={"snufflenose-manualens syfte","vad är ägarmanualen till för","snufflenose owner's manual"}}},fp="15,170,30.266.0,20.311.0,24.305.0,34.183.0,32.129.0,50.158.0,22.166.0,49.185.0,42.184.0"}
P.entries["quest:1222"] = {n="Stinky's Escape",s="\"Stinky\" Ignatz är ute i träsket, dit Morgan Stern, en kock i Theramore, skickade honom för att samla sumpbönsblad. Småkryp har omringat honom, och han ber dig hjälpa honom och hålla ryggen fri medan han letar efter en sumpbönsplanta. Efteråt ska du besöka Morgan Stern i Theramore.",h="\"Stinky\" Ignatz är ute i träsket, dit Morgan Stern, en kock i Theramore, skickade honom för att samla...",kw={"blue recluse","sumpböna","dustwallow marsh","morgan stern","stinky ignatz","theramore"},sec={{t="Omringad",b="Ignatz är lättad över att träffa någon som inte ser honom som en måltid. Han säger att Morgan Stern, en kock, arbetar på ett nytt recept och skickade ut honom för att samla sumpbönsblad, som Ignatz gissar att Stern tycker är goda. Medan han letade efter en planta blev Ignatz omringad, och han ber dig hjälpa honom och hålla ryggen fri medan han letar vidare."},{t="En väntande kock",b="Morgan Stern i Theramore är orolig: Ignatz gav sig av mot träsket för en stund sedan och har fortfarande inte kommit tillbaka."},{t="Tack från kocken",b="Stern säger att Ignatz kom förbi med sumpbönsbladen och berättade hur du hjälpte honom ur knipan. Som tack ska Stern be en farbror att bjuda dig på en festmåltid nästa gång du besöker Blue Recluse i Stormwind."}},faq={{q="Vem är \"Stinky\" Ignatz?",a="Kocken Morgan Stern skickade \"Stinky\" Ignatz ut i träsket för att samla sumpbönsblad.",al={"stinky ignatz","vem är stinky","ignatz dustwallow"}},{q="Varför är Ignatz i knipa?",a="Medan han letade efter en sumpbönsplanta slöt småkrypen omkring honom och omringade honom.",al={"varför är stinky instängd","ignatz strandsatt","varför är stinky i dustwallow"}},{q="Vad används sumpbönsblad till?",a="Morgan Stern arbetar på ett nytt recept och skickade Ignatz efter bladen. Ignatz gissar att Stern tycker att de är goda.",al={"sumpbönsblad","vad är sumpbönor","sumpbönsplanta"}},{q="Vem är Morgan Stern?",a="Morgan Stern är en kock i Theramore som arbetar på ett nytt recept.",al={"morgan stern theramore","vem är morgan stern","kocken morgan stern"}}},fp="15,285,10.324.0,14.101.0,20.204.1,23.90.0,25.90.0,28.110.0,20.67.0"}
P.entries["quest:123"] = {n="The Collector",s="Ett avlyssnat meddelande från gnollrövare i Elwynn Forest anger när guldsändningar lämnar de övergivna gruvorna. Det är adresserat till en person som kallas ”The Collector” och pekar på en organiserad verksamhet nära Stormwinds garnison.",h="Ett avlyssnat meddelande från gnollrövare i Elwynn Forest anger när guldsändningar lämnar de övergivna...",kw={"brackwell pumpkin patch","elwynn forest","gold pickup schedule","goldshire","manhunt","marshal dughan","gruvor","the collector"},ang={["class:Rogue"]="Som rogue kan du läsa det avlyssnade schemat och spåra smuggelsaker genom de kriminella nätverken i Elwynns vildmark.",["faction:Alliance"]="Varje uns guld som smugglas ut från Elwynn berövar kronan skatteintäkter och råmaterial medan kungariket kämpar för att skydda sina gränser.",["profession:Mining"]="Som gruvarbetare vet du att Elwynns stängda gruvor fortfarande innehåller koppar och ädelmetaller. Någon arbetar olagligt i de ådrorna medan hederliga gruvarbetare håller sig hemma av rädsla."},sec={{t="Ett spår av papper i gnollernas klor",b="Riverpaw-gnollflockar i västra Elwynn Forest bär på mer än pälsar och primitiva vapen. Bland dem finns ett pergament kallat Gold Pickup Schedule, med datum och tider för guld från de lokala gruvorna. Den avlyssnade anteckningen skickar varje sändning till en tillsyningsman som bara identifieras som ”The Collector”."},{t="Oroande nyheter för Goldshire",b="Marshal Dughan får höra nyheten på Lion's Pride Inn och får veta att guld fortfarande bryts och transporteras. De officiella gruvorna i Elwynn har varit stängda i månader på grund av gnollattacker, koboldinvasioner och kringströvande banditer. Gnoller med fraktscheman tyder på ett organiserat kriminellt nätverk som stjäl kungarikets rikedomar."},{t="Ögon på Brackwell Patch",b="Schemat placerar den misstänkta Collector nära Brackwell Pumpkin Patch i östra Elwynn Forest. Marshal Dughan har hört viskningar om namnet, men saknar tydliga bevis för vem som leder ligan eller vart guldet tar vägen. Meddelandet ger garnisonen dess första konkreta spår i jakten på den som styr sändningarna."}},faq={{q="Vad är Gold Pickup Schedule?",a="Gold Pickup Schedule är en avlyssnad anteckning som gnoller bar på i Elwynn Forest. Den listar datum och tider då utvunnet guld ska överlämnas till en person som kallas ”The Collector”.",al={"upphämtningsschema","collector-anteckning","guldschema för elwynn"}},{q="Vem är ”The Collector”?",a="”The Collector” är en kriminell person som tros hålla till nära Brackwell Pumpkin Patch i östra Elwynn Forest och samordna en olaglig guldhandel.",al={"collectors identitet","vem är collector","collector vid brackwell"}},{q="Varför blir Marshal Dughan chockad av schemat?",a="Marshal Dughan blir chockad eftersom guld fortfarande bryts och skeppas trots att de officiella gruvorna varit stängda i månader. Gnollattacker, koboldinvasioner och kringströvande banditer tvingade fram stängningarna, så schemat avslöjar en dold verksamhet som stjäl från kronan.",al={"varför är dughan förvånad","dughans reaktion","elwynns gruvor stängda"}},{q="Varför har gnollerna den här anteckningen?",a="Riverpaw-gnollerna i västra Elwynn verkar bära schemat som kurirer, vakter eller medbrottslingar i guldet de smugglar, med order om upphämtningarna.",al={"gnoller och guld","varför gnoller lämnar schemat","gnollernas inblandning"}},{q="Vart leder utredningen härnäst?",a="Om du lämnar schemat till Marshal Dughan leder det till Manhunt, som skickar dig för att hitta och döda Collector nära Brackwell Pumpkin Patch.",al={"uppföljning om collector","uppdraget manhunt","efter collector"}},{q="Var ligger Brackwell Pumpkin Patch?",a="Brackwell Pumpkin Patch ligger i östra Elwynn Forest, norr om floden och öster om Maclure- och Stonefield-vingårdarna.",al={"brackwells läge","var ligger brackwell","pumpaodling i elwynn"}}},fp="13,214,35.237.0,29.314.0,27.320.1,33.177.0,23.146.0,46.268.0,29.159.0,40.141.0,45.127.0"}
P.entries["quest:1238"] = {n="The Lost Report",s="När du sållar bland lös jord i Dustwallow Marsh hittar du en avhuggen orchhand som håller i ett rör av ben, med ett jordfläckigt pergament inuti. Det är en rapport skriven av en orch som spionerade på Theramore i flera veckor. Den är avsedd för Nazeer Bloodpike, orchernas spionmästare i Brackenwall Village.",h="När du sållar bland lös jord i Dustwallow Marsh hittar du en avhuggen orchhand som håller i ett rör av ben...",kw={"brackenwall village","dustwallow marsh","lös jord","nazeer bloodpike","spionrapport","den förlorade rapporten","theramore"},sec={{t="En hand i jorden",b="I den lösa jorden ligger en avhuggen orchhand som håller i ett rör av ben. Pergamentet inuti är en rapport från en orch som spionerade på Theramore i flera veckor. När du granskar den ser du att den ska till Nazeer Bloodpike, orchernas spionmästare i Brackenwall Village."},{t="Besked från spionmästaren",b="Nazeer Bloodpike säger att författaren var Marg Nighteye, en agent stationerad utanför Theramore för att hålla staden under uppsikt. Det här är Margs senaste rapport, och kanske den sista. Av det du berättar drar Bloodpike slutsatsen att Marg kan ha gått en våldsam död till mötes i träsket."}},faq={{q="Var hittas rapporten?",a="Den ligger i lös jord i Dustwallow Marsh, gripen av en avhuggen orchhand.",al={"var finns rapporten","den förlorade rapportens plats","hur startar man den förlorade rapporten"}},{q="Vad handlar rapporten om?",a="En orch skrev den efter att ha spionerat på Theramore i flera veckor.",al={"vad står i rapporten","vad säger spionrapporten","pergamentets innehåll"}},{q="Vem ska få rapporten?",a="Orchernas spionmästare Nazeer Bloodpike i Brackenwall Village.",al={"vem lämnar jag rapporten till","lämna in den förlorade rapporten","var lämnar man spionrapporten"}}},fp="15,184,18.259.0,23.247.1,26.86.0,25.60.0,20.80.0"}
P.entries["quest:1239"] = {n="The Severed Head",s="I den lösa jorden hittar du genom ivrigt grävande huvudet av en orcman, sönderslitet där det skilts från halsen. Ta det till Nazeer Bloodpike i Brackenwall Village.",h="I den lösa jorden hittar du genom ivrigt grävande huvudet av en orcman, sönderslitet där det skilts från...",kw={"brackenwall village","trotsigt orc-huvud","dustwallow marsh","lös jord","marg nighteye","nazeer bloodpike","avhugget huvud"},sec={{t="Ett hemskt fynd",b="När du gräver ivrigt i den lösa jorden får du upp huvudet av en orcman, sönderslitet där det skilts från halsen. Läpparna är krökta i en grimas och de mörka ögonen stirrar trotsigt. Ta det till Nazeer Bloodpike i Brackenwall Village."},{t="Nazeer undersöker närmare",b="Nazeer Bloodpike känner genast igen huvudet som Marg Nighteyes och hade fruktat att Marg var död. När Nazeer studerar det sönderslitna såret vid halsen undrar hen om det är ett vapen som orsakat snittet eller om ett odjur dödat agenten. Det är ett mysterium att lösa, och Nazeer vill veta om Alliansen låg bakom Margs död."}},faq={{q="Vart lämnar du det avhuggna huvudet?",a="Till Nazeer Bloodpike i Brackenwall Village.",al={"var lämnar man det avhuggna huvudet","lämna in avhugget huvud","vem tar emot huvudet"}},{q="Hur ser huvudet ut?",a="Det är en orcmans huvud, sönderslitet där det skilts från halsen, med läpparna krökta i en grimas och mörka ögon som stirrar trotsigt.",al={"vad finns i den lösa jorden","trotsigt orc-huvud","beskrivning av avhugget huvud"}},{q="Vad kommer efter det avhuggna huvudet?",a="Nästa steg är The Troll Witchdoctor.",al={"nästa uppdrag efter avhugget huvud","uppföljning på avhugget huvud"}}},fp="16,112,11.195.0,19.280.1,36.66.0,29.123.0,34.39.0"}
P.entries["quest:124"] = {n="A Baying of Gnolls",s="Verner Osgood, stallmästaren i Lakeshire, får sin verksamhet belägrad av gnoller som härjar söderut från Redridgebergens utlöpare. Blackrock-orkernas intrång har redan satt honom under press, och nu ber han resande driva bort bestarna och mystikerna som hotar hans boskap.",h="Verner Osgood, stallmästaren i Lakeshire, får sin verksamhet belägrad av gnoller som härjar söderut från...",kw={"gnoller","hästar","lakeshire","redridge-best","redridge mountains","redridge-mystiker","stallar","verner osgood"},ang={["class:Hunter"]="Redridges vilda bestar och förvildade flockar har blivit allt djärvare när ingen organiserad jakt håller dem tillbaka. De utgör ett oberäkneligt hot mot tamdjur och resande.",["faction:Alliance"]="Stormwinds försummelse tynger varje litet samhälle i det södra kungariket. Därför tvingas enkla handelsmän som Verner anlita privat hjälp för att skydda viktiga försörjningsvägar."},sec={{t="Hästar på åsen",b="Det har blivit allt farligare att driva ett stall i Lakeshire. Blackrock-orker behärskar regionens höjder, medan flockar av gnoller strövar omkring på åsarna. För Verner Osgood blev situationen ohållbar när aggressiva gnollgäng smög sig nära de norra gränserna av hans hästhagar och angrep alla hästar som kom för nära branterna."},{t="Ett samordnat hot",b="Det här är inte bara kringströvande asätare. Flockarna norr om staden förenar brutal styrka med primitiv trolldom. De använder kraftfulla bestar för att övermanna byten och mystiker som brukar vild magi. När deras antal minskar får samhället en kort andhämtningspaus, men snart står det klart att deras aggression drivs av en större makt som lurar högre upp i bergen."}},faq={{q="Varför behöver Verner Osgood hjälp med gnollerna?",a="Gnoller från de norra åsarna har börjat tränga in på Verners stallområde och rövar hästar så snart de lämnar hagarna. Med både det hotet och Blackrock-orkernas invasion kan han inte skydda sina hästar utan hjälp utifrån.",al={"verners problem","varför verner vill döda gnoller","gnoller vid stallet i lakeshire"}},{q="Var finns gnollerna?",a="Redridge-bestarna och mystikerna stryker längs de höga åsarna och bergens utlöpare direkt norr och öster om Lakeshire. Därifrån har de uppsikt över staden och vägen mot Everstill Bridge.",al={"var finns redridge-bestarna","redridge-mystikernas plats","gnoller norr om stallarna"}},{q="Varför är gnollerna ett problem vid sidan av Blackrock-orkerna?",a="Blackrock-klanen är den främsta militära styrkan som hotar Redridge, men de lokala gnollflockarna utnyttjar distraktionen. Lakeshires försvarare är hårt ansatta och Stormwind skickar knappast några förstärkningar, så de inhemska rovdjuren har kunnat breda ut sig ända fram till byns utkant.",al={"orker och gnoller i redridge","varför både gnoller och orker"}},{q="Vad händer när gnollerna har besegrats?",a="När bestarna och mystikerna har blivit färre konstaterar Verner att ylandet i bergen fortsätter. Det tyder på ett större ledarskapshot som måste hanteras i höjderna runtomkring.",al={"fortsättning på a baying of gnolls","vad händer efter a baying of gnolls"}},{q="Varför är mystikerna särskilt farliga?",a="Redridge-mystikerna utövar enkel natur- och elementarmagi och vänder oberäkneliga, vilda besvärjelser mot inkräktare. Att de finns bland bestarna tyder på en organiserad klanstruktur, snarare än ensamma vilda asätare.",al={"redridge-mystikernas historia","gnollschamaner i redridge"}},{q="Skickar Stormwind soldater för att skydda stallarna i Lakeshire?",a="Nej. Stormwinds kungliga hov har i stort sett lämnat Redridge åt sig självt, mitt i den pågående politiska oron och bristen på trupper. Därför tvingas Magistrate Solomon och invånare som Verner Osgood rekrytera kringvandrande äventyrare.",al={"stormwind-vakter i redridge","varför hjälper inga vakter verner"}}},fx={["114f5694"]={q="Vilka gnolls hotar Verners hästar?",a="Du skickas mot Redridge-brutorna och mystikerna som stryker omkring i kullarna strax norr om Verner Osgoods stall. Dessa förvildade hyenafolk håller till på höjderna med utsikt över Lakeshire och utnyttjar stadens bekymmer för att stjäla oförsiktig boskap och terrorisera gårdarna i trakten.",al={"redridge-gnolls","redridge-brutor och mystiker","vilka gnolls anfaller lakeshire"}}},fp="18,208,19.268.0,20.268.1,45.205.0,31.168.0,53.259.0,43.146.1,39.205.0,61.203.0"}
P.entries["quest:1240"] = {n="The Troll Witchdoctor",s="Nazeer Bloodpike vill ta reda på vad som hände kring Marg Nighteyes död och säger att bara trollens häxkonst kan avslöja det. Du tar Marg till Kin'weelay på Grom'gol Base Camp i Stranglethorn Vale.",h="Nazeer Bloodpike vill ta reda på vad som hände kring Marg Nighteyes död och säger att bara trollens häxkonst...",kw={"darkspear-häxdoktor","trotshövdat orc-huvud","grom'gol base camp","kin'weelay","marg nighteye","nazeer bloodpike","stranglethorn vale"},sec={{t="Trollens häxkonst",b="När det avhuggna huvudet dök upp insisterade Nazeer Bloodpike på att man måste få veta vad som hände kring Margs död, och att bara trollens häxkonst kan avslöja det. Margs huvud ska föras till Kin'weelay i Stranglethorn Vale, på Grom'gol Base Camp. Ingen häxdoktor bland Darkspear Trolls är mäktigare än Kin'weelay, och Nazeer tror att Kin'weelay, om någon, kan nå Margs ande."},{t="Ord på Grom'gol",b="Kin'weelay känner en vredgad ande omkring dig när du anländer. När häxdoktorn betraktar huvudet ser hen att orkens ande är bunden till den här världen och kokar av vrede över en plikt som lämnats ogjord. Kin'weelay föreslår att tala med den."}},faq={{q="Varför måste Marg Nighteyes huvud föras till Stranglethorn Vale?",a="Nazeer Bloodpike säger att trollens häxkonst är det enda sättet att få veta vad som hände vid Margs död, och att Kin'weelay finns på Grom'gol Base Camp.",al={"varför ta sig till stranglethorn","varför grom'gol","varför kin'weelay"}},{q="Vem är Kin'weelay?",a="Den mäktigaste häxdoktorn bland Darkspear Trolls, på Grom'gol Base Camp i Stranglethorn Vale.",al={"vem är häxdoktorn","häxdoktorn kin'weelay"}},{q="Vad kommer efter det här steget?",a="Nästa steg är Marg Speaks.",al={"vilket uppdrag kommer härnäst","efter trollhäxdoktorn"}}},fp="21,206,25.377.0,17.225.1,61.141.0,18.104.0,27.29.0"}
P.entries["quest:1241"] = {n="The Missing Diplomat",s="I Stormwind börjar en brådskande utredning när en diplomat inte kommer fram till Theramore Isle. Bishop DeLavey misstänker att Defias ligger bakom och skickar betrodda agenter till Jorgen, en diskret kontakt i Valley of Heroes.",h="I Stormwind börjar en brådskande utredning när en diplomat inte kommer fram till Theramore Isle.",kw={"defias","delavey","jaina","jorgen","försvunnen diplomat","stormwind","theramore","valley of heroes"},ang={["class:Priest"]="Bishop DeLavey använder kyrkans kontakter för att i tysthet utreda statsbrott när de vanliga kungliga kanalerna kan vara komprometterade.",["class:Rogue"]="Jorgen är en långvarig kontakt vars låga profil hjälper till att spåra försvunna sändebud genom spionnätverken under Stormwinds fläckfria gator.",["faction:Alliance"]="Den försvunna kungliga diplomaten riskerar att äventyra de känsliga förhandlingarna mellan Stormwind och Lady Jaina Proudmoores utpost i Theramore.",["race:Human"]="Hotet från Defias Brotherhood sträcker sig bortom Westfall och in i huvudstaden, vilket hotar det mänskliga kungarikets stabilitet."},sec={{t="Ett försvinnande i skuggorna",b="En högt uppsatt diplomat seglade från Eastern Kingdoms för att träffa Lady Jaina Proudmoore i Theramore Isle för känsliga samtal, men kom aldrig fram. Kungliga utredare letar efter ledtrådar i Stormwind. Försvinnandet hålls hemligt för att förhindra panik och hindra konspiratörerna från att få veta att kronan håller uppsikt."},{t="Privata efterforskningar",b="Bishop DeLavey tror att Defias Brotherhood har fört bort diplomaten, men förlitar sig inte enbart på kungens garde. Han vänder sig till diskreta kontakter och söker upp Jorgen, en gammal bekant som håller låg profil medan han fiskar i Valley of Heroes, precis innanför stadsportarna."},{t="En motvillig informatör",b="Jorgen har ett bistert sätt och en anspråkslös plats vid stadens vatten, men håller sina gamla förpliktelser gentemot DeLavey. Han varnar för att spåra diplomatens väg innebär dödliga risker. Alla som dras in i utredningen måste tiga."}},faq={{q="Vem är den försvunna diplomaten?",a="The Church of the Light och Stormwinds tron skyddar diplomatens identitet och hänvisar bara till denne som en viktig diplomat som skickats över Great Sea till Theramore.",al={"den försvunna diplomatens identitet","vem försvann","diplomatens identitet"}},{q="Varför reste diplomaten till Theramore?",a="Diplomaten skickades för att träffa Lady Jaina Proudmoore och föra viktiga samtal om säkerheten och läget för alliansen mellan Eastern Kingdoms och Kalimdor.",al={"varför theramore","diplomatens syfte","vad gjorde diplomaten"}},{q="Vem misstänker Bishop DeLavey?",a="Bishop DeLavey misstänker att Defias Brotherhood har fört bort diplomaten, men deras metoder och medhjälpare i staden är fortfarande okända.",al={"vem tog diplomaten","delaveys misstanke","vem kidnappade diplomaten"}},{q="Vem är Jorgen?",a="Jorgen är en agent och en långvarig personlig kontakt till Bishop DeLavey. Han fiskar i Stormwinds Valley of Heroes, precis innanför stadsportarna.",al={"var är jorgen","jorgens identitet","vem är fiskaren"}},{q="Varför hålls saken hemlig för allmänheten?",a="Myndigheterna håller saken tyst eftersom avslöjandet att ett viktigt sändebud förts bort mitt framför tronen kan skapa kaos och varna konspiratörerna om att kungliga agenter jagar dem.",al={"varför hemlighetsmakeri","varför hålla det hemligt","varför inte berätta för staden"}},{q="Vart leder utredningen?",a="Jorgen leder utredningen mot Stormwinds undre värld och dess dolda nätverk för att ta reda på var diplomaten stoppades.",al={"vad händer härnäst","vart efter jorgen"}}},fx={["02dad4d3"]={q="Varför behöver Bishop DeLavey en äventyrare i stället för kungliga vakter?",a="Kungens agenter genomsöker redan Stormwind, men Bishop DeLavey föredrar att följa sina egna diskreta vägar utanför den kungliga tillsynen. Genom att anlita en privat kurir kan han ta hjälp av oberoende kontakter som Jorgen utan att dra till sig allmänhetens blickar eller varna konspiratörer i staden.",al={"varför jag i missing diplomat","varför inte stadsvakter för missing diplomat","bishop delavey varför jag"}}},fp="20,213,26.310.0,17.285.0,21.223.1,28.163.0,44.158.0,32.127.0,14.144.0,46.205.0,35.125.0"}
P.entries["quest:1242"] = {n="The Missing Diplomat",s="Jorgen skickar betrodda agenter genom Stormwind med ett förseglat brev till Elling Trias. Leveransen för sökandet efter den försvunne diplomaten från Valley of Heroes till Trias' Cheese i Trade District.",h="Jorgen skickar betrodda agenter genom Stormwind med ett förseglat brev till Elling Trias.",kw={"elling trias","jorgen","försvunnen diplomat","förseglat brev","stormwind","trade district","trias cheese"},ang={["class:Rogue"]="Som skurk kan du ana att Trias' Cheese är mer än en ostbutik. Ägaren håller tysta kontakter långt bortom Trade District.",["faction:Alliance"]="Som medlem av Alliansen kan du se hur det diskreta sökandet efter den försvunne sändebudet blottar Stormwinds lednings dolda sårbarheter."},sec={{t="Ett diskret ärende",b="Efter de första efterforskningarna kring diplomatens försvinnande ber Jorgen betrodda agenter att hålla tyst och bära ett förseglat brev genom staden. Det är avsett för Trias' Cheese i Stormwinds Trade District, inte en kasern eller ett magistratkontor. Överlämningen går utanför de vanliga kanalerna för vakterna, medan oron för den försvunne diplomaten sprider sig bortom palatset."},{t="Bakom butiksfasaden",b="Elling Trias är en gladlynt och arbetsam osthandlare samt en respekterad köpman på Trias' Cheese. Hans historia med Jorgen och hans egna kontakter sträcker sig långt bortom butiken. När Jorgens brev har levererats övergår sökandet efter den försvunne diplomaten i tysthet till Trias."}},faq={{q="Vem är Elling Trias?",a="Elling Trias är en respekterad köpman som driver Trias' Cheese i Stormwinds Trade District. Han har en gemensam historia med Jorgen och kontakter som han kan anlita i känsliga ärenden.",al={"vem är trias","osthandlare","elling trias identitet"}},{q="Varför säger Jorgen åt mig att hålla tyst?",a="Jorgen kräver tystnad eftersom diplomatens försvinnande är en statshemlighet. Ryktesspridning kan väcka panik eller varna den som låg bakom bortrövandet och avslöja att en utredning pågår.",al={"varför tystnad","jorgens varning","håll tyst"}},{q="Var hittar jag Trias' Cheese?",a="Trias' Cheese ligger i Stormwind Citys Trade District, längs huvudgatorna bland köpmän och hantverkare.",al={"trias plats","ostbutikens plats","var finns elling trias"}},{q="Vad står det i det förseglade brevet till Elling?",a="I sitt förseglade brev underrättar Jorgen Elling Trias om den försvunne diplomaten och ber honom att använda sina kontakter och öron i undre världen för att hitta spår som de vanliga myndigheterna inte kan följa.",al={"brevets innehåll","vad står det i brevet","sealed note to elling"}},{q="Vem är den försvunne diplomaten som nämns i uppdraget?",a="Det kungliga hovet skyddar diplomatens identitet i det här skedet. Hemlighetsmakeriet och oron tyder på att det rör sig om någon med enorm politisk betydelse för kungariket Stormwind.",al={"vem saknas","vem är diplomaten","den försvunnes identitet"}},{q="Varför låter man en osthandlare sköta utredningen i stället för stadsvakten?",a="Stadsvakten är bunden av regler, ansvarsområden och politiska band. Elling Trias kan nå rykten från gatorna och tysta kontakter som soldaterna inte kommer åt.",al={"varför en osthandlare","varför trias i stället för vakterna","vakter mot trias"}}},fx={c433039c={q="Varför vill Jorgen att brevet levereras till Elling Trias?",a="Jorgen vet att sökandet efter den försvunna diplomaten är en känslig och hemlighetsfull angelägenhet, långt bortom vad en enkel fältagent kan hantera. Elling Trias kan verka vara en vanlig osthandlare i Trade District, men han har kontakter i undre världen och underrättelser som är viktiga för utredningen. Jorgen måste överlämna sina rön till Trias utan att väcka misstankar hos någon som håller uppsikt.",al={"varför skicka meddelande till elling trias","jorgens motiv i missing diplomat","varför leverera förseglat meddelande"}}},fp="20,209,19.323.0,20.260.1,20.161.0,38.190.0,31.106.0,37.171.0,51.169.0,73.156.0"}
P.entries["quest:1243"] = {n="The Missing Diplomat",s="Elling Trias skickar dig söderut för att söka efter nyheter om den försvunna diplomaten. Spår i Stormwind leder mot Duskwood och Watcher Backus, en kontakt nära Darkshire som kan känna till Defias verksamhet.",h="Elling Trias skickar dig söderut för att söka efter nyheter om den försvunna diplomaten.",kw={"darkshire","defias","duskwood","elling trias","jorgen","försvunnen diplomat","night watch","watcher backus"},ang={["class:Rogue"]="Som skurk ser du hur Elling Trias arbetar genom ett nätverk. Han förlitar sig på fristående fotsoldater för att samla information och håller samtidigt sina egna händer rena.",["faction:Alliance"]="Som hjälte i Alliansen hjälper du till att utreda ett försvinnande som berör Stormwinds kungliga intressen. Sökandet för samman kungliga spionmästare, fristående skurkar och regionala miliser."},sec={{t="Spaning i skymningen",b="Efter ett frustrerande samtal med Jorgen vänder sig osthandlaren Elling Trias till sin större krets av informatörer. För att spara sina egna pengar skickar han dig på fältarbete i stället för att anlita agenter. Du bär ett förseglat brev över gränsen till Duskwood, där bestar och de odöda gör resan farlig."},{t="Ett vänligt öra i Night Watch",b="Watcher Backus tjänstgör i Night Watch och patrullerar den norra infarten till Darkshire. Trias litar på att han rapporterar olovliga rörelser genom Duskwood, trots farorna på vägarna. Visa Backus det förseglade meddelandet, så kan han dela med sig av vaktjournaler och lokalt skvaller om Defias Brotherhoods verksamhet i söder."}},faq={{q="Varför skickar Elling Trias mig till Duskwood?",a="Elling Trias följer upp spår efter den försvunna diplomaten och misstänkt aktivitet från Defias Brotherhood. För att utnyttja sina kontakter utan att lägga pengar på agenter skickar han dig för att fråga Watcher Backus vad som händer i Duskwood.",al={"varför till duskwood","trias ärende i duskwood","varför darkshire"}},{q="Var hittar jag Watcher Backus?",a="Watcher Backus patrullerar grusvägen norr om Darkshire i Duskwood, längs vägen mot Redridge och Elwynn Forest.",al={"watcher backus plats","var finns backus","hitta backus"}},{q="Vem är Watcher Backus?",a="Watcher Backus är soldat i Darkshires lokala milis, Night Watch. Han känner Elling Trias personligen och berättar vad han ser av misstänkta resenärer och kriminella rörelser.",al={"backus bakgrund","vem är backus"}},{q="Vad står det i det förseglade brevet till Backus?",a="Elling Trias förseglade brev ber Watcher Backus om upplysningar om lokala iakttagelser av eller rörelser från Defias Brotherhood genom Duskwood.",al={"innehållet i det förseglade brevet","vad står det i brevet","sealed note to watcher backus"}},{q="Vad har Duskwood med Defias Brotherhood att göra?",a="Defias Brotherhood har sitt centrum i Westfall och håller sig gömt under The Deadmines. Dess celler, kurirer och gömställen sträcker sig också genom de södra mänskliga provinserna, däribland Duskwoods skuggiga utkanter.",al={"defias i duskwood","finns defias i duskwood"}},{q="Varför klagar Trias på Jorgen?",a="Jorgen vägrade ge Trias några svar eller krävde ett högt pris under utredningen. Trias blev så irriterad att han förbannade Jorgen till Twisting Nether innan han vände sig till andra kontakter ute på fältet.",al={"vem är jorgen","trias och jorgen"}}},fx={["8b2965b1"]={q="Varför vill Elling Trias få det här gjort?",a="Elling Trias kan se ut som en ödmjuk mästare på fina ostar, men han har ett brett nätverk av kontakter och har gått med på att undersöka den försvunna diplomatens försvinnande. Varje tecken på att Defias Brotherhood är inblandat kan vara ledtråden som löser fallet, så han skickar dig till Duskwood medan han själv använder sina kontakter i staden.",al={"varför bryr sig trias","trias motiv","elling trias motiv"}},c3fdc8e2={q="Varför låter Elling Trias dig göra grovjobbet i stället för att göra det själv?",a="Trias döljer inte att han är praktisk: genom att skicka en äventyrare sparar han en rejäl slant och kan fortsätta arbeta med sina diskreta kontakter i Stormwind City. En välkänd köpman som vandrar in i dystra Duskwood skulle väcka onödig uppmärksamhet, medan en kringresande utredare kan ställa lokala vakter som Watcher Backus frågor utan att väcka Defias uppmärksamhet.",al={"varför skicka mig","varför behöver trias mig","varför går han inte själv"}}},fp="20,191,21.306.0,33.283.0,43.217.0,32.131.0,22.179.0,43.142.0,58.201.0,37.189.0"}
P.entries["quest:1244"] = {n="The Missing Diplomat",s="I Duskwood följer sökandet efter Stormwinds försvunna diplomat ett spår från Watcher Backus till Defias-papper vid Addle's Stead.",h="I Duskwood följer sökandet efter Stormwinds försvunna diplomat ett spår från Watcher Backus till...",kw={"addle's stead","defias docket","duskwood","fotkista","night watch","den försvunna diplomaten","watcher backus"},ang={["class:Rogue"]="Som skurk måste du navigera bland kriminella nätverk och skilja verklig underrättelse från Defias vilseledning.",["faction:Alliance"]="Kungarikets försvunna sändebud utsätter Stormwinds säkerhet för risk. Defias intriger sträcker sig långt bortom småaktiga vägöverfall i Westfall."},sec={{t="Ett spår i dunkel",b="Watcher Backus från Night Watch leder sökandet till Duskwood. Han berättar att en ovanligt stor grupp Defias-banditer kom till Addle's Stead för flera veckor sedan. Banditerna håller sig vanligtvis för sig själva på andra sidan gränsen i Westfall, så samlingen i de mörka skogarna är ett ovanligt drag. Nu söker du igenom den övergivna gården efter pappren de lämnade kvar."},{t="Defias-dossiern",b="På den övertagna gården hittar du en låst fotkista med en Defias Docket. Pappren bekräftar brödraskapets inblandning, men Watcher Backus varnar dig för att vara försiktig. Defias kan ha förfalskat dem för att vilseleda utredarna."}},faq={{q="Var ligger Addle's Stead?",a="Addle's Stead ligger i västra Duskwood, strax söder om huvudvägen från Westfall. Fientliga Defias-agenter har tagit över det förfallna boningshuset.",al={"addle's stead läge","var ligger addle's stead","hitta addle's stead"}},{q="Vad är Defias Docket?",a="Defias Docket är en samling officiella papper i en fotkista vid Addle's Stead. Den beskriver några av brödraskapets senaste hemliga operationer i området.",al={"defias docket","vad är dossiern","dokument vid addle's stead"}},{q="Vem är Watcher Backus?",a="Watcher Backus är medlem i Night Watch och stationerad i Duskwood. Hans kontakter i staden och hans bevakning av hot vid gränsen hjälper honom att spåra ovanliga Defias-rörelser längs gränsen mot Westfall.",al={"watcher backus","vem är backus","backus i duskwood"}},{q="Varför verkar Defias inne i Duskwood?",a="Defias-agenter gör diskreta intrång i västra Duskwood, trots att deras fäste ligger på andra sidan gränsen i Westfall. Addle's Stead är en avskild anhalt långt från Stormwinds patruller.",al={"varför är defias i duskwood","defias vid addle's stead"}},{q="Går det att lita på innehållet i Defias Docket?",a="Watcher Backus varnar för att Defias kan ha planterat falska spår för att leda utredarna bort från sin egen väg. Dossiern verkar äkta, men innehållet kan vara vilseledande.",al={"är dossiern äkta","förfalskad dossier","är det en kopia"}},{q="Vem hänvisade ursprungligen utredarna till Watcher Backus?",a="Watcher Backus säger att Elling Trias, en osthandlare och hemlig informationsmäklare i Stormwind, hänvisade utredningen till Night Watch i Duskwood.",al={"vem skickade mig till backus","trias koppling"}}},fx={["860270d2"]={q="Varför skickar Watcher Backus dig till Addle's Stead?",a="Watcher Backus ser varje närvaro av Defias i Duskwood som ett växande hot mot Darkshires gränser, även när de håller låg profil. För ett par veckor sedan lade Night Watch märke till en ovanlig samling av deras agenter vid Addle's Stead. Backus misstänkte att något stort hade hänt där, vilket gjorde platsen till den mest lovande ledtråden i din utredning av brödraskapets hemliga rörelser.",al={"varför vill backus få detta gjort","watcher backus motiv","varför undersöka addle's stead"}}},fp="20,151,19.342.0,17.221.1,31.137.0,26.172.0,22.179.0,41.191.0,49.163.0,59.162.0"}
P.entries["quest:1245"] = {n="The Missing Diplomat",s="Du för tillbaka det återfunna Defias Docket till Stormwind medan sökandet efter en försvunnen diplomat blir allt farligare.",h="Du för tillbaka det återfunna Defias Docket till Stormwind medan sökandet efter en försvunnen diplomat blir...",kw={"defias docket","duskwood","elling trias","fist","försvunnen diplomat","stormwind","watcher backus"},ang={["class:Rogue"]="Elling Trias visar hur skurkaktighet kan byta ut dolkar mot underrättelsenätverk. Som rogue ser du hur en spionmästare tyder Defias chiffer i kronans skuggkrig.",["faction:Alliance"]="Som medlem av Alliance ser du hur djupt Stormwinds säkerhet har urholkats sedan det tredje kriget, medan Defias planer hotar kungariket inifrån."},sec={{t="För tungt för nattväktarna",b="I Duskwood vill Watcher Backus inte ha något med Defias Docket att göra, som du har återfunnit. Dokumenten beskriver planer som är alltför invecklade för att handla om enkelt banditeri eller en avledningsmanöver. Backus fruktar kungligt straff och aktar sig för sina överordnade i Night Watch. Han ber dig därför att hålla hans inblandning hemlig. Dokumenten pekar på intriger som är farliga nog att kosta karriärer eller liv, så du för dem till Stormwind."},{t="En osthandlares verkliga syssla",b="Tillbaka i Stormwinds Trade District överger Master Cheesemonger Elling Trias sin fasad som butiksägare när du återvänder. Han granskar dokumenten som en kontaktperson i kungarikets hemliga underrättelsenätverk. Dokumenten beskriver Defias Brotherhoods noggranna planering och nämner ett illavarslande kodnamn: ”Fist”. Den försvunna diplomaten blev måltavla för ett välorganiserat nätverk med goda förbindelser och förgreningar djupt inne i kungariket."}},faq={{q="Vad är Defias Docket?",a="Defias Docket är en samling känsliga dokument som du återfann i Duskwood. De beskriver Defias Brotherhoods planer. Dokumentens invecklade innehåll skrämmer de lokala vakterna och ger Master Trias nya spår i sökandet efter den försvunna diplomaten.",al={"defias docket","vad är dokumenten","innehållet i dokumenten"}},{q="Varför är Watcher Backus så rädd för att behålla dokumenten?",a="Watcher Backus fruktar att dokumenten innehåller information som ligger utanför en nattväktares befogenheter i Duskwood. Han oroar sig för att hans befälhavare eller överordnade i Stormwind kan få veta att han hanterat eller undanhållit sådan underrättelseinformation. Då kan han hängas för förräderi.",al={"varför är backus rädd","watcher backus rädsla"}},{q="Varför ta dokumenten till en osthandlare i Stormwind?",a="Elling Trias utger sig för att vara osthandlare, men han är spionmästare i Stormwind och en central person i kungarikets hemliga underrättelsenätverk. Hans kunskap och kontakter hjälper honom att tyda Defias planer.",al={"varför elling trias","varför trias ost"}},{q="Vem är ”Fist”, som nämns i dokumenten?",a="Elling Trias känner igen ”Fist” i dokumenten som ett kodnamn för någon med koppling till Defias Brotherhoods samordning av kidnappningsplanen.",al={"vem är fist","fist och defias","kodnamnet fist"}},{q="Vart leder utredningen härnäst?",a="Detaljerna i dokumenten låter Trias spåra konspiratörerna vidare. Han skickar dig för att förhöra kontakter och jaga ”Fist”, så att ni kan ta reda på vart diplomaten fördes.",al={"nästa steg","vad händer efter dokumenten","vart går jag härnäst"}},{q="Vad har det här med King Varian Wrynn att göra?",a="Dokumenten nämner inte King Varian Wrynn. Du söker efter en icke namngiven diplomat som aldrig kom fram till Theramore, och Trias tolkning av dokumenten avslöjar inte måltavlans identitet.",al={"är varian diplomaten","kung varian koppling"}}},fx={["74ee0470"]={q="Varför behöver Watcher Backus dig i stället för att själv ta med sig handlingen?",a="Watcher Backus är livrädd för det som står i Defias Docket. Som medlem i Night Watch är han skyldig att rapportera statsangelägenheter till sina befälhavare, men han vet att han kan förlora livet om han hanterar dokument om förrädiska konspirationer utanför de officiella kanalerna. Om hans överordnade upptäcker att han hade informationen och undanhöll den, fruktar han att han blir hängd. Du är en oberoende utredare som redan arbetar med Trias, så Backus kan tvätta sina händer från den livsfarliga intrigen och samtidigt se till att handlingarna hamnar hos någon som kan tyda dem.",al={"varför jag","varför levererar inte backus handlingen","varför skicka mig till trias"}}},fp="20,113,29.338.0,27.390.1,26.232.0,51.225.0,56.198.0,38.125.0,40.153.0,49.190.1"}
P.entries["quest:1246"] = {n="The Missing Diplomat",s="I Old Town leder ett spår i fallet med den försvunne diplomaten till en gatukämpe. Elling Trias skickar dig för att hitta Dashel Stonefist och få svar om de misstänkta dokumenten. Utredningen når Stormwinds hårda gator.",h="I Old Town leder ett spår i fallet med den försvunne diplomaten till en gatukämpe.",kw={"dashel stonefist","elling trias","fist","försvunnen diplomat","old town","stormwind"},ang={["class:Rogue"]="Som skurk känner du dig hemma i Old Town, bland informatörer som Trias och våldsamma hantlangare som Stonefist.",["faction:Alliance"]="Som medlem i Alliansen vet du att det är viktigt för Alliansens stabilitet och kungariket i dess hjärta att avslöja sammansvärjningen bakom den försvunne diplomaten.",["race:Human"]="Som människa från Stormwind ser du oroande bevis för att lokalt gatupack hjälper till med högförräderi mot kungarikets ledning."},sec={{t="Ett spår i Old Town",b="Elling Trias minns ett namn med koppling till de kodade anteckningarna och ledtrådarna: Dashel Stonefist, känd som Fist. Han är en hårdför gatukämpe, långt från adeln kring Cathedral Square. Stonefist håller till i Old Towns trånga gränder. När du hittar honom lämnar sökandet Stormwind Keeps storslagna salar och går in i stadens kriminella kretsar."},{t="Övertalning med knytnäven",b="Elling Trias varnar för att Dashel Stonefist inte talar öppet med nyfikna främlingar, särskilt när förräderi och kidnappningar är inblandade. Om frågor inte hjälper, säger Trias att våld får tala. Stonefist ser gränderna som sitt område och ogillar främlingar som rotar i sådant som kan kosta honom försörjningen eller livet."}},faq={{q="Vem är Dashel Stonefist?",a="Dashel Stonefist är en ökänd slagskämpe som håller till i de centrala gränderna i Stormwinds Old Town. Trias kopplar honom till komprometterande dokument som hittades under sökandet efter den försvunne diplomaten.",al={"dashel stonefist","vem är fist","dashel"}},{q="Var hittar jag Dashel Stonefist?",a="Dashel Stonefist håller till utomhus i gränderna nära mitten av Old Town, bort från huvudgatorna.",al={"dashel stonefists plats","var är dashel","var är stonefist"}},{q="Varför skickar Elling Trias mig efter honom?",a="Trias kopplar Dashels namn till dokument om kungens sändebuds försvinnande. Dashel kan känna till namn, platser eller order med koppling till dem som organiserade bortrövandet.",al={"varför slåss mot dashel","trias skäl"}},{q="Kommer Dashel att samarbeta frivilligt?",a="Nej. Stonefist är fientligt inställd till främlingar som lägger sig i hans affärer. Trias räknar med att han gör motstånd och råder dig att använda ett vapen eller knytnävarna för att få honom att tala.",al={"talar dashel","är stonefist vänligt sinnad"}},{q="Vad händer när jag har hittat Dashel?",a="När du konfronterar Dashel blir det slagsmål. När han väl är kuvad ger han dig spår till nätverket bakom diplomatens bortrövande och pekar ut andra sammansvurna i kungariket.",al={"nästa steg i jakten på den försvunne diplomaten","vad händer efter dashel"}},{q="Vem är den försvunne diplomaten som nämns i uppdraget?",a="Stormwinds myndigheter talar bara om en namnlös diplomat som försvann på väg till Theramore för att träffa Jaina Proudmoore. Sändebudets identitet är fortfarande en väl bevarad hemlighet i det här skedet av utredningen.",al={"vem är den försvunne diplomaten","vilken diplomat"}}},fx={["8d360f6b"]={q="Varför skickar Elling Trias dig i stället för stadsvakterna?",a="Elling verkar genom hemligheter, rykten och känsliga politiska band snarare än genom officiell makt. En framstående diplomats försvinnande är en explosiv fråga, och om Stormwinds stadsvakt blandas in riskerar det att skapa panik bland allmänheten och varna konspiratörerna om att någon är dem på spåren. Trias behöver en oberoende utredare som kan smyga genom Old Towns bakgator, ställa farliga frågor och knäcka några knogar utan att dra dit lagens hårda hand och väcka uppmärksamhet.",al={"varför skicka mig","varför inte stormwinds vakter","varför inte stadsvakten"}}},fp="20,198,18.280.0,22.325.1,24.189.0,34.104.0,41.163.0,32.155.0,34.175.1,51.215.2"}
P.entries["quest:1247"] = {n="The Missing Diplomat",s="Dashel Stonefist har erkänt i Old Town, och du för hans varning till Elling Trias. Skurken avslöjar en reservplan för kidnappning och en kontakt i Menethil Harbor.",h="Dashel Stonefist har erkänt i Old Town, och du för hans varning till Elling Trias.",kw={"addle's stead","dashel stonefist","elling trias","menethil","försvunnen diplomat","slim","stormwind"},ang={["class:Rogue"]="Som skurk vet du hur nära gatubrott och statshemligheter kan mötas, från Dashels slagsmål i bakgränderna till Trias tysta underrättelsearbete.",["faction:Alliance"]="Som medlem av alliansen vet du att det försvunna sändebudet är viktigt för alliansens stabilitet, och att sabotage hotar Stormwinds ledning.",["race:Human"]="Som människa ser du en konspiration ta form inom Stormwinds gränser medan pojkkungen sitter på tronen."},sec={{t="En spricka i muren",b="Dashel Stonefist ger vika när han fruktar för sin hälsa. I en gränd i Old Town erkänner han att konspiratörernas första kidnappningsplan gick om intet, vilket ödelade hans roll i planen. För att skjuta skulden ifrån sig berättar han om ett hemligt möte för flera veckor sedan vid Addle's Stead i Duskwood. Han nämner också ett spår i reservplanen: en insider i Menethil Harbor som bara är känd som Slim."},{t="Rapport till Fromager",b="Elling Trias samlar hemligheter åt kronan bakom disken i Trias' Cheese i Trade District. Medan du förhörde Dashel studerade Trias tillfångatagna meddelanden om planen. Erkännandet stämmer med vad de avslöjar: konspiratörerna siktade in sig på en diplomat vars namn inte nämns, deras första bakhåll misslyckades och en reservplan inleddes via Wetlands. Med namnet Slim går sökandet norrut från Stormwind mot träskmarkerna."}},faq={{q="Vem är Dashel Stonefist?",a="Dashel Stonefist är en fixare och torped i Stormwinds Old Town. Han har kopplingar till Defias undre värld och hjälpte till att genomföra den första planen att tillfångata Stormwinds sändebud. När han konfronterades lämnade han upplysningar.",al={"dashel stonefist","vem är dashel","stonefist stormwind"}},{q="Varför är Elling Trias inblandad i utredningen?",a="Elling Trias samlar hemligheter åt Stormwind medan han utger sig för att vara expert på fina ostar. Hans butik i Trade District låter honom samordna diskreta efterforskningar utanför stadsvaktens räckvidd.",al={"varför elling trias","osthandlare spion","trias underrättelser"}},{q="Vad hände vid Addle's Stead?",a="Konspiratörerna möttes för flera veckor sedan vid Addle's Stead, en övergiven gård i västra Duskwood, för att planera sina kidnappningar efter att deras första försök hade avbrutits.",al={"möte vid addle's stead","addle's stead","möte i westfall"}},{q="Vem är diplomaten de försökte kidnappa?",a="Konspiratörernas dokument och gatuhuliganer beskriver målet endast som en icke namngiven diplomat på väg till Theramore. Sändebudets identitet hålls fortfarande hemlig vid det här laget i utredningen.",al={"vem är den försvunna diplomaten","vem blev kidnappad","diplomatens identitet"}},{q="Vem är Slim?",a="Slim är namnet Dashel Stonefist ger på kontakten som hanterar reservplanen från Menethil Harbor i Wetlands. Kontakten står för konspiratörernas andra rutt för att transportera människor och förnödenheter.",al={"vem är slim","slim menethil","kontakt i menethil"}},{q="Vart leder spåret härnäst?",a="Spåret leder norrut till Menethil Harbor i Wetlands, där Slim sägs finnas. Elling Trias bekräftar Dashels uppgifter.",al={"nästa steg för den försvunna diplomaten","vart efter dashel","vad händer härnäst"}}},fx={a7b1abaf={q="Varför pratar Dashel Stonefist nu?",a="Dashel pratar bara för att du just har slagit honom till underkastelse. När han insåg att hans hantlangare inte kunde skydda honom från dig försöker han rädda sitt eget skinn genom att avslöja det lilla han vet om konspirationens reservplan och leda dig bort från sig själv.",al={"varför pratar dashel","dashel stonefists motiv","varför erkände dashel"}}},fp="20,145,19.357.0,25.433.1,24.206.0,51.185.0,31.155.0,47.196.2,12.204.0,37.127.0"}
P.entries["quest:1248"] = {n="The Missing Diplomat",s="The Missing Diplomat är ett undersökande uppdrag där du följer kidnappningen av ett icke namngivet sändebud från Stormwind. Med ledtrådar från ett beslagtaget dokument reser agenter till Menethil Harbor i Wetlands för att rådfråga en pensionerad kontakt och spåra upp en misstänkt vid namn Slim.",h="The Missing Diplomat är ett undersökande uppdrag där du följer kidnappningen av ett icke namngivet sändebud...",kw={"dokument","menethil harbor","mikhail","slim","stormwind","the missing diplomat","trias","wetlands"},ang={["class:Rogue"]="Att tyda hemliga dokument, spåra upp pensionerade kontakter och diskret förhöra misstänkta på fullsatta krogar är precis vad hemligt underrättelsearbete kräver.",["faction:Alliance"]="Utredningen av den kidnappade diplomaten berör direkt säkerhetsfrågor på hög nivå i Stormwind och konspiratörernas räckvidd över Alliance territorier."},sec={{t="Ett spår till Wetlands",b="Utredningen av en kidnappad diplomat leder bortom Stormwinds portar till Menethil Harbors dimhöljda kajer i Wetlands. Ett beslagtaget dokument bekräftar att en diplomat utsattes för ett angrepp och fördes bort, men viktiga uppgifter saknas. Pappren avslöjar varken diplomatens verkliga identitet eller konspiratörernas slutmål. För att bryta tystnaden måste utredarna söka bland hamnens skiftande folkmassor och hemliga affärer."},{t="Diskreta kontakter i Menethil",b="För att följa spåret i Menethil skickas agenter till Mikhail, en tidigare medarbetare till Elling Trias som lämnade Stormwind flera år tidigare för att sköta den lokala krogens bar. Mikhail är den viktiga länken till en person som bara är känd som Slim, och som kanske vet vart fången fördes eller vem som ordnade kidnappningen. Diskretion är avgörande på en fullsatt krog. Bara omnämnandet av Trias namn räcker för att få alla att genast tiga, innan konspiratörerna får nys om utredningen."}},faq={{q="Vem är Mikhail?",a="Mikhail är en tidigare medarbetare till Elling Trias som lämnade Stormwind för flera år sedan för att gå i pension i Menethil Harbor, där han nu arbetar som bartender. Trias hänvisar utredarna till honom som en pålitlig kontakt som kan hjälpa till att identifiera en misstänkt vid namn Slim.",al={"vem är mikhail","mikhail wetlands","menethils bartender"}},{q="Vem är Slim och varför letar de efter honom?",a="Slim är en person i Menethil Harbor som tros ha viktig information om den kidnappade diplomaten. Mikhail kontaktas särskilt för att hjälpa till att spåra upp Slim och ta reda på vad han vet.",al={"vem är slim","hitta slim","the missing diplomat slim"}},{q="Vem är den kidnappade diplomaten?",a="Diplomatens identitet hålls hemlig och är okänd även för utredarna. Det beslagtagna dokumentet beskriver en kidnappning men utelämnar både diplomatens verkliga identitet och konspiratörernas planer efter tillfångatagandet.",al={"vem kidnappades","den kidnappade diplomatens identitet","vem är den försvunna diplomaten"}},{q="Varför leder spåret till Menethil Harbor?",a="Menethil Harbor är en stor hamnstad vid Wetlands kust. Utredarna skickas dit eftersom Trias pensionerade kontakt Mikhail arbetar bakom baren i staden och viktiga ledtrådar om kidnappningen leder genom hamnen.",al={"var ligger menethil harbor","varför wetlands","varför åka till menethil"}},{q="Vad avslöjar dokumentet om planen?",a="Dokumentet är ett beslagtaget papper som beskriver kidnappningen av diplomaten. Det bekräftar bortrövandet, men har stora luckor: det avslöjar inte vart fången fördes eller vad kidnapparna tänker göra härnäst.",al={"vad är dokumentet","trias dokument","vad står det i dokumentet"}},{q="Vilken roll har Trias i uppdraget?",a="Elling Trias är kontakten i Stormwind som leder utredningen. Han skickar agenter till Mikhail eftersom Mikhail var en gammal medarbetare som lovat att hjälpa Trias enbart på hans ord, utan att väcka uppmärksamhet.",al={"vem skickade oss till mikhail","trias koppling","varför nämna trias"}}},fp="20,197,23.285.0,29.369.1,15.225.0,45.149.0,30.211.0,43.201.0,43.141.0,44.179.0"}
P.entries["quest:1249"] = {n="The Missing Diplomat",s="The Missing Diplomat är en omfattande utredning av hur ett viktigt sändebud från Stormwind försvunnit, där dunkla spår leder från huvudstaden till avlägsna hamnar. I Menethil Harbor korsas utredningens vägar med personer ur undre världen och gamla agenter med kopplingar till Stormwinds underrättelsenätverk.",h="The Missing Diplomat är en omfattande utredning av hur ett viktigt sändebud från Stormwind försvunnit, där...",kw={"elling trias","menethil harbor","the missing diplomat","slim","stormwind","wetlands","våtmarkerna"},ang={["class:Rogue"]="Agenter och uppdragsgivare i undre världen, som Elling Trias, förlitar sig på diskret fotarbete och gatukontakter för att spåra personer som slinker undan.",["faction:Alliance"]="Utredningen av den försvunna diplomaten drar in Alliansens äventyrare i den dunkla undre värld som förbinder Stormwinds politiska kretsar med kajerna i Wetlands."},sec={{t="Dolda strömningar i Menethil Harbor",b="Sökandet efter Stormwinds försvunna sändebud leder utredarna långt norr om huvudstaden, till den fuktiga hamnstaden Menethil Harbor. Bakom stadens livliga kajer och väderbitna tavernor döljer sig ett underjordiskt nätverk av skumma handelsmän och hemliga kurirer som verkar mitt framför näsan på stadsvakten. Att följa spåren genom denna kustknutpunkt kräver att man har direktkontakt med personer som känner till den mörkare sidan av Alliansens territorium."},{t="En välbekant skurk",b="Gripandet av Slim innebär ett oväntat genombrott i sökandet och överrumplar de lokala informatörerna, som inte väntat sig att han var direkt inblandad. Gripandet ger viktiga svar, men väcker också minnen hos pensionerade agenter som slagit sig till ro i Wetlands. De måste väga hjälpen till kronan mot risken att dras tillbaka in i Stormwinds intrigerande undre värld."}},faq={{q="Vem är Slim?",a="Slim är en skum kontakt i Menethil Harbor som grips under utredningen av den försvunna diplomaten. De lokala kontakterna blir överraskade, eftersom de inte väntade sig att han skulle vara inblandad.",al={"vem är slim","slim the missing diplomat","gripa slim"}},{q="Vem är Elling?",a="Elling Trias är en inflytelserik person som verkar från Stormwind City och upprätthåller ett underjordiskt nätverk av före detta skurkar och informatörer i Alliansens länder.",al={"elling trias","vem är elling","elling stormwind"}},{q="Var utspelar sig den här delen av utredningen?",a="Den här delen av utredningen utspelar sig i Menethil Harbor, en hamnstad i Wetlands som förbinder kungariket Ironforge med avlägsna kuster och Stormwinds handelsvägar.",al={"var utspelar det sig","menethil harbor the missing diplomat","wetlands diplomat"}},{q="Vad handlar uppdragskedjan The Missing Diplomat om?",a="The Missing Diplomat är en utredning av ett viktigt sändebud från Stormwind som försvunnit. Spåren leder till hemliga agenter, konspiratörer och kontakter i undre världen i kungariket och bortom dess gränser.",al={"vad är the missing diplomat","the missing diplomat uppdrag","vem är försvunnen"}},{q="Varför varnar kontakten för att nämna det här för Elling?",a="Kontakten i Menethil Harbor arbetade tidigare med Elling Trias i Stormwinds underjordiska kretsar och vill inte låta Elling få veta att han saknar sitt gamla liv, eftersom han då kanske kallas tillbaka till huvudstaden.",al={"varför nämns elling","trias ost","elling trias koppling"}},{q="Vad hände med utredningen i Menethil Harbor?",a="Efter att ha följt spåren till hamnstaden Menethil Harbor i Wetlands konfronterar utredaren Slim och griper honom. Det bekräftar de lokala misstankarna om olaglig verksamhet i stadens underjordiska kretsar.",al={"vad hände i menethil harbor","spår menethil","slim gripen"}}},fp="20,205,32.304.0,16.330.1,12.156.0,14.143.0,53.144.0,47.164.0,60.198.0,56.151.0"}
P.entries["quest:125"] = {n="The Lost Tools",s="Med Lakeshire pressat av fientliga styrkor är stadens underhåll och försvar helt beroende av lokal arbetskraft. Foreman Oslows oumbärliga verktyg, som skickades från Goldshire, gick förlorade när Blackrocks katapulteld sänkte transportbåten i Lake Everstill. Att hämta upp den sjunkna kistan från sjöbotten är avgörande för att återuppbygga stadens förstörda bro.",h="Med Lakeshire pressat av fientliga styrkor är stadens underhåll och försvar helt beroende av lokal...",kw={"katapult","foreman oslow","goldshire","lake everstill","lakeshire","murloc","redridge","thresher","verktygslåda"},ang={["faction:Alliance"]="Lakeshire står som Alliansens östra fäste mot Blackrock-klanen. Att se till att stadens byggare har sin utrustning är avgörande för att hålla Stormwinds gränsland.",["profession:Blacksmithing"]="Det är svårt att smida kvalitetsverktyg under belägring, så verktygen för smide och byggarbete från Goldshire är oumbärliga för staden."},sec={{t="En leverans som gick snett",b="Lakeshires livlina till Elwynn Forest har kapats när Great Bridge förstördes. När en ersättningsleverans med verktyg för stenarbete och snickeri skickades landvägen från Goldshire kunde den inte nå staden direkt. Besättningen lastade över förnödenheterna i en roddbåt för att korsa Lake Everstill, men båten träffades direkt av en Blackrock-orcs katapult. Båten slogs i spillror, och Oslows tunga, järnbeslagna verktygslåda sjönk ända till sjöbotten."},{t="Faror i djupet",b="Att hämta verktygslådan är mycket farligare än ett vanligt dyk. Lake Everstills vatten är fullt av aggressiva murlocstammar som stryker omkring i det grunda vattnet, medan rovlystna threshers jagar i de grumliga djupen. Trots faran måste verktygen återfås för att Foreman Oslow ska kunna återuppta arbetet med bron och hindra Lakeshire från att förfalla helt."}},faq={{q="Varför skickades verktygen med båt från början?",a="Huvudvägen in till Lakeshire går över en stenbro som sträcker sig över Lake Everstill, men Blackrock-orcer sprängde bort en stor del av den. Eftersom försörjningsvagnarna från Goldshire inte längre kunde ta sig över var besättningen tvungen att lasta av verktygen och försöka färja dem över vattnet.",al={"varför båt","hur sjönk verktygen","varför transport över sjön"}},{q="Hur sjönk båten?",a="Under överfarten besköts transportbåten av Blackrock-orcer, som träffade den direkt med en katapultprojektil från höjderna runt sjön. Båten och lasten sjönk omedelbart.",al={"vem förstörde båten","hur träffades den"}},{q="Vem är Foreman Oslow?",a="Foreman Oslow är Lakeshires främste byggmästare och arbetsledare. Han ansvarar för offentliga byggprojekt och underhåll i staden, framför allt den brådskande uppgiften att återuppbygga den förstörda bron.",al={"foreman oslow","oslows roll"}},{q="Vilka hot finns i Lake Everstill?",a="I sjön finns fientliga murlocstammar som patrullerar nära stränderna och ruinerna, samt glupska, köttätande threshers som jagar på öppet vatten och i djupare vattenlager.",al={"vad finns i sjön","sjömonster","faror i lake everstill"}},{q="Varför behöver Lakeshire verktygen så mycket?",a="Lakeshire är i praktiken belägrat och avskuret från omedelbara förstärkningar och regelbundna leveranser. Utan tunga verktyg kan Oslow inte återuppbygga bron eller reparera försvaret som behövs för att stå emot attackerande orcer och gnoller.",al={"varför är verktygen viktiga","verktyg för broreparation"}},{q="Vart leder uppdraget härnäst?",a="När verktygslådan har återfåtts ber Foreman Oslow äventyrare samla in råmaterialen som behövs för att reparera Great Bridge i uppföljningsuppdraget The Everstill Bridge.",al={"nästa uppdrag","vad händer efter the lost tools"}}},fx={fed346ea={q="Vad används Oslow's Toolbox till?",a="Oslow's Toolbox innehåller de tunga järnverktyg som behövs för att återuppbygga Lakeshires förstörda infrastruktur. Blackrock-orcherna belägrar staden och spränger den stora bron till grus, så byggarbetet och reparationerna har helt stannat av. Oslow kan inte reparera bron eller förstärka stadens försvar utan sin specialutrustning. Lakeshire förblir sårbart och avskuret tills verktygslådan bärgas från sjöbottnen.",al={"oslow's toolbox","vad är verktygslådan till för","foreman oslows verktyg"}},b04d784a={q="Varför ber Foreman Oslow en äventyrare om hjälp i stället för stadsvakten?",a="Lakeshire är pressat till bristningsgränsen under en pågående belägring. De få kvarvarande stadsvakterna och magistraterna är upptagna med att försvara stadens utkanter mot Blackrock-orcher, gnolls och inkommande katapulteld. Oslow är byggmästare, inte krigare eller dykare, och Lake Everstill kryllar av aggressiva murlocs och väldiga threshers. Han behöver en kapabel resenär som vågar sig ut i fientliga vatten medan Lakeshires försvarare håller stånd.",al={"varför jag i lost tools","varför hämtar inte oslow den själv","varför skickar man inte lakeshires vakter"}}},fp="14,216,20.377.0,19.257.0,51.207.0,22.156.0,21.162.0,35.134.0,45.204.0,31.158.1"}
P.entries["quest:1251"] = {n="The Black Shield",s="Shady Rest Inn står utbränt, och en av de få delarna som fortfarande står kvar är en sönderfallande skorsten. En sköld, svärtad av lågorna, sitter fäst vid dess tegel. Krog i Brackenwall Village är den du ska visa den för.",h="Shady Rest Inn står utbränt, och en av de få delarna som fortfarande står kvar är en sönderfallande skorsten.",kw={"svart sköld","blackened iron shield","brackenwall village","dustwallow marsh","krog","shady rest inn"},sec={{t="En sköld på skorstenen",b="Elden härjade genom Shady Rest Inn, och lite finns kvar av värdshuset. Fäst vid den sönderfallande skorstenen sitter en järnsköld, svedd svart, och den går att lirka loss från teglet. Den ska du ta med till Krog i Brackenwall Village, som kommer att fråga om den räknas som bevis från värdshusets ruiner."},{t="Vad Krog tror om den",b="Krog medger att människor har märklig smak när det gäller utsmyckning, men tvivlar på att någon skulle hänga en vanlig järnsköld över en eldstad. Krog misstänker att den som satte eld på värdshuset lämnade den där, kanske som en varning eller ett hot."}},faq={{q="Var hittar man den svarta skölden?",a="Den sitter fäst vid skorstenen på det nedbrända Shady Rest Inn, en av få kvarlevor av byggnaden.",al={"svart sköld plats","var finns skölden","shady rest inn sköld"}},{q="Vem ska ha skölden?",a="Den ska du ta med till Krog i Brackenwall Village.",al={"vem vill ha den svarta skölden","var lämnar man in skölden","krog plats"}},{q="Går det att ta loss skölden från skorstenen?",a="Ja, den går att lirka loss från skorstenens tegel.",al={"kan jag ta loss skölden","ta loss skölden från skorstenen"}}},fp="16,209,23.289.0,21.211.1,32.97.0,20.56.0,41.53.0"}
P.entries["quest:1252"] = {n="Lieutenant Paval Reethe",s="Något glänser under rasmassorna: ett märke med Theramores symbol, ett gyllene ankare på vit emalj, med namnet Lieutenant Paval Reethe ingraverat under ankaret. Det ska lämnas till Captain Garran Vimes i Theramore.",h="Något glänser under rasmassorna: ett märke med Theramores symbol, ett gyllene ankare på vit emalj, med namnet...",kw={"dustwallow marsh","garran vimes","paval reethe","shady rest inn","theramores vaktbricka"},sec={{t="En glimt bland rasmassorna",b="Något glänser under rasmassorna. När askan och bråten borstas bort syns ett märke med Theramores symbol och Lieutenant Paval Reethes namn ingraverat under den. Captain Garran Vimes i Theramore bör få se det och kommer att fråga vad som hittades i ruinerna av Shady Rest Inn."},{t="Kaptenens svar",b="Vimes säger att det aldrig är goda nyheter när någon lämnar in en vaktbricka. Vissa vakter faller i strid, och Vimes måste meddela deras sörjande familjer. För andra får ingen någonsin veta vad som hände dem, och ibland är sanningen ännu värre."}},faq={{q="Var hittas märket?",a="Det ligger under rasmassor, täckt av aska och bråte. Captain Garran Vimes kommer att fråga vad som hittades i ruinerna av Shady Rest Inn.",al={"märkets plats","var hittar man reethes märke","märket vid shady rest inn"}},{q="Vems namn står på märket?",a="Namnet Lieutenant Paval Reethe är ingraverat under ankaret.",al={"vem är paval reethe","namn på märket","vem tappade märket"}},{q="Vem ska få märket?",a="Det är Captain Garran Vimes i Theramore som bör få se det.",al={"vem ska jag ge märket till","var lämnar man in märket","captain garran vimes plats"}},{q="Hur ser märket ut?",a="Ett gyllene ankare på vit emalj, vilket är Theramores symbol.",al={"theramores symbol","vaktbrickans utseende","hur ser märket ut"}}},fp="23,231,21.283.0,19.235.1,25.129.0,27.64.0,19.57.0,30.64.0"}
P.entries["quest:1253"] = {n="The Black Shield",s="En järnsköld, svärtad av eld, sitter fast på den förfallna skorstenen vid det nedbrunna Shady Rest Inn. Captain Garran Vimes i Theramore väntar på bevis från värdshusets område.",h="En järnsköld, svärtad av eld, sitter fast på den förfallna skorstenen vid det nedbrunna Shady Rest Inn.",kw={"svart sköld","skorsten","dustwallow marsh","garran vimes","järnsköld","shady rest inn","theramore"},sec={{t="En sköld på skorstenen",b="Shady Rest Inn brann ner, och en av de få delar som står kvar är en förfallen skorsten. En eldsvedd järnsköld sitter fast i teglet och går att ta loss. Captain Garran Vimes i Theramore vill ha bevis från värdshusets område."},{t="Kaptenens bedömning",b="Vimes säger att han inte är någon expert på hur vapen och rustningar tillverkas, bara på hur de används. För kaptenen ser skölden ut som vilken sköld som helst, bortsett från skadorna efter branden."}},faq={{q="Var finns den svarta skölden?",a="Fäst i teglet på den förfallna skorstenen, bland de få delarna av det nedbrunna Shady Rest Inn som fortfarande står kvar.",al={"var finns skölden","den svarta sköldens plats","hitta den svarta skölden"}},{q="Vem vill ha bevis från Shady Rest Inn?",a="Captain Garran Vimes i Theramore, som väntar på bevis från värdshusets ruiner.",al={"vem vill ha skölden","utredare vid shady rest","vem är garran vimes"}}},fp="16,176,23.234.0,21.178.1,34.109.0,43.86.0"}
P.entries["quest:1258"] = {n="... and Bugs",s="Morgan Stern i Theramore arbetar på ett recept som kan bli nästa stora mattrend i Stormwind. Med Mudrock-tungorna redan i sin ägo behöver rätten sedan skalade ben från en jättekrabba, och de måste vara helt felfria.",h="Morgan Stern i Theramore arbetar på ett recept som kan bli nästa stora mattrend i Stormwind.",kw={"crawler legs","dustwallow marsh","morgan stern","mudrock soup and bugs","felfritt crawler leg","stormwind","theramore","swamp of sorrows"},sec={{t="Ben utan en skråma",b="Morgan Stern vill att krabbskalets utseende ska vara en viktig del av hur rätten presenteras, så varje ben måste vara helt felfritt. En vuxen krabba kanske bara har ett eller två sådana ben, och forskningen kräver många. Muckshells i Dustwallow Marsh duger inte. Bara krabborna i det avlägsna Swamp of Sorrows passar, så en resa väntar."}},faq={{q="Vem är Morgan Stern?",a="Morgan Stern arbetar i Theramore på ett nytt recept som kanske blir nästa stora mattrend i Stormwind.",al={"vem är morgan stern","morgan stern theramore","vem ger and bugs"}},{q="Var kommer krabbbenen ifrån?",a="Inte från Dustwallow Marsh, där Muckshells inte duger till rätten. Morgan Stern pekar ut det avlägsna Swamp of Sorrows, där det finns krabbor som passar.",al={"var hittar man crawler legs","var finns spiny rock crawlers","crawler legs plats"}},{q="Varför måste krabbbenen vara felfria?",a="Skalet är en viktig del av hur rätten presenteras, så Morgan Stern vill ha ben utan skråmor.",al={"varför felfria crawler legs","varför ben utan skråmor","crawler leg presentation"}},{q="Vilket uppdrag kommer före det här?",a="Det följer på Mudrock Soup and Bugs, den första delen av arbetet du utförde åt Morgan Stern med det nya receptet.",al={"föregående uppdrag and bugs","förkunskapsuppdrag mudrock soup and bugs"}}},fp="12,255,22.357.0,20.104.0,33.152.0,41.103.0,29.99.0"}
P.entries["quest:1259"] = {n="Lieutenant Paval Reethe",s="Captain Garran Vimes känner inte igen namnet Lieutenant Paval Reethe och skickar dig till Adjutant Tesoran i Theramore, som ansvarar för Theramores vakts rullor.",h="Captain Garran Vimes känner inte igen namnet Lieutenant Paval Reethe och skickar dig till Adjutant Tesoran i...",kw={"adjutant tesoran","captain garran vimes","dustwallow marsh","paval reethe","theramore"},sec={{t="Vem är Reethe?",b="Captain Garran Vimes kan inte placera namnet Lieutenant Paval Reethe. Adjutant Tesoran för Theramores vakts rullor, som omfattar både dess folk och utrustning, och Vimes väntar sig att en genomgång av böckerna ska visa vem Reethe är."}},faq={{q="Vem skickar dig för att ta reda på mer om Reethe?",a="Captain Garran Vimes, som inte känner igen namnet Lieutenant Paval Reethe.",al={"vem inleder uppdraget lieutenant paval reethe","reethe uppdragsgivare","vem ger reethe-uppdraget"}},{q="Vem för Theramores vakts rullor?",a="Adjutant Tesoran i Theramore för dem; de omfattar vaktens folk och utrustning.",al={"var finns adjutant tesoran","theramores rullförare","vem har vaktens böcker"}},{q="Vad kan Adjutant Tesoran berätta för dig?",a="Vimes väntar sig att Tesorans böcker ska visa vem Reethe är.",al={"vad vet tesoran","tesorans böcker"}}},fp="23,173,14.240.0,39.78.0,40.88.0,35.52.0"}
P.entries["quest:126"] = {n="Howling in the Hills",s="Howling in the Hills är ett alliansuppdrag med belöning som Verner Osgood erbjuder i Lakeshire för att jaga Yowler, den fruktade alfahanen som leder Redridges gnoller. Stormwinds militär är upptagen med att bekämpa Blackrock-orcherna och kan inte försvara de lokala gränserna, så Lakeshire förlitar sig på besökande äventyrare för att slå ut gnollflockens ledning.",h="Howling in the Hills är ett alliansuppdrag med belöning som Verner Osgood erbjuder i Lakeshire för att jaga...",kw={"blackrock","gnoller","lakeshire","tass","redridge","stormwinds armé","verner osgood","yowler"},ang={["class:Hunter"]="Att spåra upp en dominant alfahanne som Yowler i hans bergslya kräver ett skarpt öga för revirspår och flockbeteende.",["class:Warrior"]="Att ge sig på Yowler innebär att möta en motståndare som styr sin brutala flock med ren fysisk överlägsenhet. Det kräver en direkt kraftmätning.",["faction:Alliance"]="Att Lakeshire förlitar sig på legoknektar i stället för kungliga soldater visar hur hårt den administrativa pressen just nu försvagar Stormwinds kungarike."},sec={{t="Rösten bland höjderna",b="Även efter att de mindre gnollerna som härjar längs stigarna kring Lakeshire har rensats ut fortsätter deras olycksbådande läten att eka mellan Redridges höjder. Verner Osgood, Lakeshires flitige hovslagare, inser att dödandet av spejare och asätare aldrig kommer att hejda anstormningen så länge flockens ledare lever. Yowler reser sig över pöbeln. Han är en ovanligt listig och väldig gnoll vars läten styr flocken över kullarna. Verner ger äventyrarna i uppdrag att jaga besten och skära av dess tass för att försäkra sig om att ylandet tystnar en gång för alla."},{t="En stad övergiven av armén",b="Det här kontraktet visar den bistra verkligheten vid Stormwinds kungarikets östra gränser. Den försvunne kung Varian Wrynn och regentskapsstriderna lamslår det högsta befälet, och de kungliga soldaterna fokuserar nästan uteslutande på Blackrocks befästa orchklaner i norr. Vanliga bosättningar som Lakeshire lämnas helt utan försvar mot inhemska hot som gnoller. Därför måste stadsbor som Verner Osgood ordna egna belöningar för att hindra att deras hem blir övermannade."}},faq={{q="Vem är Yowler?",a="Yowler är den vildsinte ledaren för Redridges gnoller, som stryker omkring i kullarna utanför Lakeshire. Verner Osgood säger att Yowler är mycket starkare och farligare än vanliga byrackor. Han är alfahanen som håller flocken samman och leder den mot resande och lokala gårdar.",al={"yowler","vem är gnollbossen","yowlers bakgrund","yowler gnoll"}},{q="Varför utfärdar Verner Osgood den här belöningen i stället för stadsvakten?",a="Lakeshires officiella ledning och den lokala milisen är helt överväldigade av de framryckande Blackrock-orcherna. Verner Osgood är en lokal hantverkare och stallmästare vars försörjning är beroende av säkra vägar. Han anlitar ofta kringvandrande legoknektar för att undanröja omedelbara lokala hot.",al={"varför verner","varför inte magistrate solomon","varför anlitar osgood"}},{q="Var är Stormwinds soldater som borde skydda Lakeshire?",a="Stormwinds stående styrkor är upptagna på annat håll. Armén i Redridge är bunden av att bevaka och hålla tillbaka Blackrock-klanens orcher längre upp i bergen. Därför står stadsborna helt utan stöd mot det lokala djurlivet, murlocer och gnoller.",al={"var är armén","varför finns inga stormwind-vakter","stormwinds militär lakeshire"}},{q="Vad händer med Redridges gnoller när Yowler är död?",a="När Yowler dödas skingras gnollflockens ledning, vilket hejdar samordnade räder mot stadens gränser. Gnoller förblir dock en envis och ihärdig plåga i Redridges klippiga höjder.",al={"har gnollerna lämnat området","vad händer när yowler dör"}},{q="Vilka förhandsuppdrag leder fram till det här kontraktet?",a="Uppdragskedjan börjar med att Verner Osgood skickar dig på ärenden för att skaffa hästutrustning i ”The Price of Shoes” och ”Return to Verner”. När du har tagit hand om bukfjäll och tunnat ut flocken i ”A Baying of Gnolls” ger Verner dig uppdraget att jaga Yowler direkt.",al={"förhandskrav för yowler-uppdraget","låsa upp howling in the hills","uppdragskedja för howling in the hills"}},{q="Varför behöver Verner Yowlers tass som bevis?",a="Belöningar för farliga bestar kräver obestridliga fysiska bevis innan betalningen lämnas ut. Om du tar tillbaka Yowlers avskurna tass kan Verner och Lakeshires oroliga invånare vara säkra på att den skräckinjagande besten som ekat genom kullarna verkligen har fallit.",al={"varför yowlers tass","yowlers tass som bevis"}}},fx={f0418674={q="Varför vill Verner Osgood att Yowler dödas?",a="Verner hör gnollerna yla när de strövar omkring på höjderna ovanför Lakeshire dag och natt. Stormwinds armé är helt upptagen med att bekämpa Blackrock-orcher, så ortsbor som Verner står försvarslösa mot kringströvande rovdjur. Han tror att om Yowler, den våldsamma flockledaren, fälls, kommer gnollernas stridsmoral att krossas och bestarna skingras innan de går till direkt angrepp mot staden.",al={"verner osgoods motiv","varför döda yowler","vern ers motiv till ylandet i kullarna"}}},fp="20,217,24.377.0,28.394.0,14.189.0,67.253.0,68.223.0,56.168.0,50.204.0,43.185.0"}
P.entries["quest:1260"] = {n="Morgan Stern",s="Angus Stern på Blue Recluse i Stormwind håller på att sätta ihop en ny meny med lantliga rätter i bayoustil. Angus har en brorson, Morgan, som skickades till Theramore för att samla recept från lokalbefolkningen, och han vill höra vad Morgan har hittat hittills.",h="Angus Stern på Blue Recluse i Stormwind håller på att sätta ihop en ny meny med lantliga rätter i bayoustil.",kw={"angus stern","bayou","blue recluse","dustwallow marsh","morgan stern","stormwind","theramore"},sec={{t="En bayoumeny",b="Angus Stern tror att gästerna på Blue Recluse kommer att älska en meny med lantliga rätter i bayoustil. För att skapa den skickade Angus sin brorson Morgan till Theramore, en stad intill Dustwallow Marsh, för att samla lokalbefolkningens recept. Resan är för lång för att Angus ska kunna göra den själv, så en ung resenär som du behövs för att ge dig av och tala med Morgan."},{t="Vad Morgan har att berätta",b="När du hittar Morgan Stern i Theramore får du höra att receptforskningen har lett till några spår, men att hjälp behövs för att följa upp dem. Hjälparen måste vara någon som är villig att blöta ner fötterna."}},faq={{q="Vem är Morgan Stern?",a="Morgan Stern är brorson till Angus Stern på Blue Recluse. Morgan skickades till Theramore för att samla recept från lokalbefolkningen.",al={"vem är morgan stern","morgan sterns bakgrund","angus sterns brorson"}},{q="Varför vill Angus Stern få kontakt med Morgan?",a="Angus utvecklar en ny meny med lantliga rätter i bayoustil för Blue Recluse och vill veta vad Morgan har hittat hittills.",al={"varför skicka till theramore","blue recluse meny","angus stern uppdrag"}},{q="Var hittar man Morgan Stern?",a="Morgan är i Theramore, staden intill Dustwallow Marsh.",al={"var finns morgan stern","morgan stern plats","var finns theramores kock"}}},fp="12,248,12.334.0,22.195.1,20.126.0,42.135.0,32.57.0"}
P.entries["quest:1261"] = {n="Marg Speaks",s="Från andra sidan döden berättar Marg om musselskalet som dödade Marg och om en plikt som ännu inte är fullgjord. Marg ber dig hitta musselskalet, återta det juvelbesatta hänget som stulits från allianssoldater och bära det till Nazeer Bloodpike i Brackenwall Village.",h="Från andra sidan döden berättar Marg om musselskalet som dödade Marg och om en plikt som ännu inte är...",kw={"bloodpike","brackenwall","marg","musselskal","nazeer","hänge","stormwind","theramore"},sec={{t="Vad Marg såg nära Theramore",b="Nära Theramore fick Marg syn på allianssoldater som slagit läger på stranden. En av dem bar ett hänge prytt med fler ädelstenar än en soldat någonsin skulle ha råd med. Den natten smög Marg in i lägret och stal det, men en musselskalad krabbmänniska dödade Marg på vägen tillbaka till basen. Nu ber Marg dig hitta musselskalet, återta hänget och ta det till Nazeer i Brackenwall Village."},{t="Vad Nazeer tror om det",b="Nazeer blir förvånad när han får veta att en soldat från Stormwind bar hänget. Du har avslöjat hemligheten bakom Margs död, men hänget är ett nytt mysterium, och Nazeer varnar för att det kan få allvarliga följder för både Alliansen och Horden."}},faq={{q="Vem är Marg och hur dog Marg?",a="Marg stal ett juvelbesatt hänge från allianssoldater som slagit läger nära Theramore och dödades sedan av en musselskalad krabbmänniska på vägen tillbaka till basen.",al={"hur dog marg","vem är marg","margs berättelse"}},{q="Varifrån kom det juvelbesatta hänget?",a="En soldat i ett alliansläger på stranden nära Theramore bar det, prytt med långt fler ädelstenar än en soldat hade råd med. Marg smög sig in den natten och stal det.",al={"varifrån kom hänget","vem hade hänget","hängets ursprung marg"}},{q="Vem får det återfunna hänget?",a="Nazeer Bloodpike i Brackenwall Village.",al={"vem får hänget","var ska jag lämna hänget","nazeer bloodpike hänge"}},{q="Vilket uppdrag kommer direkt före det här uppdraget?",a="Det följer efter The Troll Witchdoctor.",al={"föregående uppdrag","vilket uppdrag kommer före marg speaks"}}},fp="11,244,28.373.0,23.234.1,33.139.0,40.162.0,35.41.0,38.33.0"}
P.entries["quest:1262"] = {n="Report to Zor",s="Nazeer Bloodpike tycker att det är märkligt att vanliga soldater bar det smyckade hängsmycke som Marg stal. Nazeer kallar det ett adligt smycke och skickar dig med det till Zor Lonetree i Orgrimmar, som är väl insatt i Alliansens politik.",h="Nazeer Bloodpike tycker att det är märkligt att vanliga soldater bar det smyckade hängsmycke som Marg stal.",kw={"brackenwall village","smyckat hängsmycke","marg speaks","nazeer bloodpike","orgrimmar","rapportera till zor","stormwind","zor lonetree"},sec={{t="Ett adligt hängsmycke",b="Nazeer Bloodpike tycker att det är märkligt att vanliga soldater hade ett hängsmycke som detta. Ägaren kan ha varit förklädd, eller så stal soldaterna det själva. Hur det än ligger till bedömer Nazeer att det är ett adligt hängsmycke, och dess rättmätiga ägare måste hittas för att mysteriet ska kunna lösas. Zor Lonetree i Orgrimmar vet mycket om Alliansens politik och kan säga om hängsmycket tillhör Stormwinds adel."},{t="Zors dom",b="Zor Lonetree beundrar det stora hantverk som ligger bakom hängsmycket. Orcher skulle inte ha någon användning för en sådan juvel, säger Zor, men många människor skulle det. Zor låter undersöka det och hoppas att dess mysterier med tiden ska avslöjas."}},faq={{q="Varför skickas hängsmycket till Orgrimmar?",a="Nazeer Bloodpike bedömer att det är ett adligt hängsmycke. Zor Lonetree i Orgrimmar vet mycket om Alliansens politik och kan säga om det har en historia bland Stormwinds adel.",al={"varför skicka hängsmycket till orgrimmar","varför åka till orgrimmar","varför träffa zor lonetree"}},{q="Vem hade det smyckade hängsmycket tidigare?",a="Marg stal det från soldater i ett alliansläger nära Theramore. Nazeer tycker att det är märkligt att vanliga soldater hade det och undrar om ägaren var förklädd eller om soldaterna stal det.",al={"vem hade hängsmycket","varifrån kom hängsmycket"}},{q="Vad hände före det här uppdraget?",a="Det följer efter Marg Speaks, där Marg berättade att hon stal hängsmycket från soldater som slagit läger nära Theramore.",al={"föregående uppdrag","vilket uppdrag kommer före"}},{q="Var finns Zor Lonetree?",a="Zor Lonetree finns i Orgrimmar.",al={"zor lonetrees plats","var finns zor lonetree"}}},fp="13,227,17.410.0,13.218.1,44.177.0,39.189.0,28.100.0,22.29.0"}
P.entries["quest:1268"] = {n="Suspicious Hoofprints",s="Hovspår löper bort från Shady Rest Inn, vars kala stomme fortfarande ryker. Några syns tydligt, medan fler rader nästan försvinner i träskets mjuka mark. Krog i Brackenwall Village är den du ska rapportera dem till.",h="Hovspår löper bort från Shady Rest Inn, vars kala stomme fortfarande ryker.",kw={"brackenwall village","centaur","dustwallow marsh","hovspår","kagoro","krog","quilboar","shady rest inn","misstänkta hovspår"},sec={{t="Spår i leran",b="Shady Rest Inn är nu bara en kal stomme som fortfarande ryker, och hovspår löper bort därifrån. Vissa avtryck syns tydligt, andra går knappt att urskilja i den mjuka marken. Krog i Brackenwall Village bör få veta om dem."},{t="Krogs svar",b="Krog medger att quilboar kan ha gjort det, eller rentav centaur, eftersom båda har en betydande närvaro i The Barrens och dådet inte vore svårt att tro om dem. Krog tillägger att värdshuset inte bara brändes ner: ägaren förlorade också en kvinna och en valp, som båda dödades. Krog ska skicka Kagoro för att ta reda på vart spåren leder."}},faq={{q="Var finns hovspåren?",a="De leder bort från Shady Rest Inn, vars kala stomme fortfarande ryker, över träskets mjuka mark.",al={"hovspårens plats","var finns spåren","spår vid shady rest inn"}},{q="Vem ska få veta om hovspåren?",a="Krog i Brackenwall Village är den du ska rapportera dem till.",al={"vem ska jag säga till","var finns krog","var rapporterar jag hovspår"}},{q="Hur många spår finns det?",a="Några syns tydligt, medan fler rader nästan är omöjliga att se i leran.",al={"hur många hovspår","hur många spår"}}},fp="21,229,17.236.0,12.326.1,25.100.0,37.59.0,26.84.0"}
P.entries["quest:1269"] = {n="Lieutenant Paval Reethe",s="Under rasmassorna ligger ett märke med Theramores emblem, ett gyllene ankare över vit emalj. Under ankaret är namnet Lieutenant Paval Reethe präglat. Det ska lämnas till Krog i Brackenwall Village.",h="Under rasmassorna ligger ett märke med Theramores emblem, ett gyllene ankare över vit emalj.",kw={"märke","brackenwall","insignier","krog","ogron","paval","reethe","theramore"},sec={{t="Ett skimmer i rasmassorna",b="Något glänser under rasmassorna. När du borstar bort aska och bråte syns Theramores emblem på ett märke, med namnet Lieutenant Paval Reethe präglat under det. Krog i Brackenwall Village väntar på det och frågar om du har fått någon ledtråd om vad som hände med Shady Rest Inn."},{t="Vad Krog vet",b="Krog känner till människan Paval Reethe och kallar honom ynklig. Enligt Krog övergav Reethe soldaterna han tjänstgjorde med och gömmer sig nu i skogen. Krog skickade Ogron för att leta rätt på honom, eftersom andra misstänker att Reethe stulit förråd. Krog tror att Ogron sågs på väg åt sydost."}},faq={{q="Vad står på märket?",a="Theramores emblem, ett gyllene ankare över vit emalj, med namnet Lieutenant Paval Reethe präglat under det.",al={"vad står det på märket","märkning på theramores vaktmärke","vem äger märket"}},{q="Vem ska ha märket?",a="Det ska visas för Krog i Brackenwall Village.",al={"vem ska jag lämna märket till","vart ska reethes märke lämnas","lämna in märke"}},{q="Var hittades märket?",a="Under rasmassor, täckt av aska och bråte. Krog frågar om du har fått någon ledtråd om vad som hände med Shady Rest Inn.",al={"märkets plats","var hittades reethes märke"}}},fp="23,212,21.276.0,15.285.1,21.116.0,19.51.0,26.104.0"}
P.entries["quest:127"] = {n="Selling Fish",s="Dockmaster Baren sköter den livliga piren i Lakeshire, men det har blivit svårt att hitta färsk fisk till handeln. Han betalar resenärer för att fånga Spotted Sunfish, en uppskattad lokal stapelvara från Lake Everstill som blivit farlig att samla in på grund av murlocernas framryckning.",h="Dockmaster Baren sköter den livliga piren i Lakeshire, men det har blivit svårt att hitta färsk fisk till...",kw={"dockmaster baren","lake everstill","lakeshire","murloc","redridge","sälja fisk","spotted sunfish"},ang={["faction:Alliance"]="Kungariket Stormwind erbjuder Redridge föga militär hjälp, så även den lokala matförsörjningen är beroende av att självständiga Alliance-resenärer hjälper till.",["profession:Cooking"]="Lakeshires rykte om fina sötvattensdelikatesser som Spotted Sunfish gör de lokala vattnen till ett bestående intresse för blivande kockar."},sec={{t="En stapelvara från Lake Everstill",b="Lake Everstill är känt i hela trakten för sin Spotted Sunfish, en fin fångst som ständigt efterfrågas av stadsbor och handelsmän på genomresa. Trots att sjön är full av fisk tryter stadens förråd regelbundet. Lakeshire är pressat av flera lokala hot, så även den grundläggande handeln kräver hjälp från äventyrare på uppdrag."},{t="Problem i det grunda vattnet",b="Vanligtvis skulle lokala fiskare inte ha några större problem med att uppfylla Dockmaster Barens beställningar. Men aggressiva murlocstammar har spridit sig längs grunda vatten och stränder, och drivit bort vanligt folk från vattnet. Resenärer som vill hjälpa Baren måste antingen kasta ut sina egna linor och se upp för faror, eller ta fångsten direkt från de födosökande murlocerna som plågar stränderna."}},faq={{q="Vem är Dockmaster Baren?",a="Dockmaster Baren ansvarar för kajerna och båttrafiken på Lake Everstill i Lakeshire. Han sköter stadens handel med vattenprodukter och förlitar sig på kapabla resenärer för att säkra färsk fisk och röja undan hot kring vattnet.",al={"baren","vem är hamnmästaren","dockmaster baren"}},{q="Varför är Spotted Sunfish så efterfrågad?",a="Lake Everstill är berömt för sin Spotted Sunfish, vilket gör den till en eftertraktad delikatess och en viktig handelsvara för Lakeshire. Dockmaster Barens förråd sinar eftersom stadens vanliga fiskare inte kan fiska säkert så länge sjön är full av fiender.",al={"varför sunfish","spotted sunfish berättelse","varför vill lakeshire ha fisk"}},{q="Hur får murlocer tag på sunfish?",a="Murlocstammarna vid Lake Everstill söker aktivt föda och jagar på grunt vatten. När de dödar eller driver bort lokala fiskare samlar de fisken till sina egna läger, där äventyrare som hellre slåss än fiskar kan lägga beslag på förråden.",al={"murlocfisk","varför släpper murlocer fisk","murlocer stjäl fisk"}},{q="Var finns Spotted Sunfish?",a="Spotted Sunfish lever i Lake Everstill i Redridge Mountains. Du kan fånga dem direkt med ett fiskespö eller plundra dem från murlocer som håller till kring sjöns stränder och grunda vatten.",al={"var finns sunfish","fiskplats lake everstill","hur får man tag på spotted sunfish"}},{q="Hur hänger det här uppdraget ihop med Murloc Poachers?",a="Dockmaster Baren erbjuder båda uppdragen samtidigt. Eftersom murlocer patrullerar sjön och lägger beslag på dess resurser går det naturligt att ta itu med tjuvfiskarna samtidigt som du återtar den Spotted Sunfish de har hämtat upp ur vattnet.",al={"koppling till murloc poachers","barens andra uppdrag","hamnmästarens uppdrag"}},{q="Måste jag fiska för att hjälpa Dockmaster Baren?",a="Nej, du behöver varken fiskeutrustning eller fiskefärdighet. Fiske är ett fredligt sätt att samla Spotted Sunfish, men Dockmaster Baren föreslår öppet att du tar dem med våld från murlocstammarna som jagar i sjön.",al={"behöver jag fiska","kan jag göra det utan fishing pole","krävs fiske"}}},fx={["2b5f9eab"]={q="Varför behöver Dockmaster Baren mer Spotted Sunfish?",a="Lake Everstill är känt för sina Spotted Sunfish, vilket skapar en stadig handel och efterfrågan som håller Dockmaster Baren sysselsatt vid Lakeshires kajer. Hans lokala lager börjar ta slut, så han behöver ett nytt parti på tio fiskar för att möta efterfrågan och hålla byteshandeln igång.",al={"varför vill baren ha fisk","dockmaster barens motiv","varför sälja fisk"}},d0647bad={q="Vad används Spotted Sunfish till?",a="Spotted Sunfish är sötvattensfiskar som hör hemma i Lake Everstill och uppskattas för sin smak i hela Redridge. De är en viktig lokal födokälla och en värdefull handelsvara för Lakeshires handel, som ger pålitlig avkastning från både resande och invånare.",al={"vad är spotted sunfish","spotted sunfish i historien","vad används spotted sunfish till"}}},fp="12,172,26.305.0,23.278.0,24.213.0,44.237.0,39.204.0,35.155.0,45.202.0,45.182.0"}
P.entries["quest:1270"] = {n="Stinky's Escape",s="\"Stinky\" Ignatz är omringad av träskvarelser och har inte hittat den sumpböna han kom för. Mebok Mizzyrix, en goblin från Ratchet, vill ha sumpbönsblad för att brygga en dryck, och Ignatz ber dig hjälpa honom därifrån och hålla vakt medan han letar. Efteråt ska du hitta Mebok Mizzyrix i Ratchet.",h="\"Stinky\" Ignatz är omringad av träskvarelser och har inte hittat den sumpböna han kom för.",kw={"sumpböna","dustwallow marsh","eskort","mebok mizzyrix","ratchet","stinky ignatz"},sec={{t="Omringad i träsket",b="Ignatz är lättad över att träffa någon som inte tänker äta upp honom. Han säger att Mebok Mizzyrix, en goblin från Ratchet, behöver sumpbönsblad för att brygga någon sorts dryck. Ignatz säger att han inte bryr sig om varför, eftersom betalningen var bra och han känner till träsket. Han blev omringad innan han hittade växten och ber dig hjälpa honom ur knipan och vakta honom medan han letar efter den."},{t="Besked från Mebok",b="Mebok säger att Ignatz kom med örterna och berättade hur du hjälpte honom ur knipan. En vän till Stinky, säger Mebok, är en vän till Mebok. Ignatz bad Mebok att ge dig något om ni två någonsin träffades, precis innan han begav sig söderut mot träskmarkerna igen."}},faq={{q="Vem är \"Stinky\" Ignatz?",a="\"Stinky\" Ignatz letar efter sumpbönsblad i träsket åt Mebok Mizzyrix. Han säger att han känner till platsen, men blev ändå omringad av varelser innan han hittade växten.",al={"vem är stinky","stinky ignatz","vem är eskortpersonen"}},{q="Varför samlar Ignatz sumpbönsblad?",a="Goblinen Mebok Mizzyrix från Ratchet behöver dem till en dryck. Ignatz säger att han inte bryr sig om varför, eftersom betalningen var bra.",al={"varför sumpböna","vad används sumpböna till","mebok sumpböna"}},{q="Vem är Mebok Mizzyrix?",a="Mebok Mizzyrix är en goblin från Ratchet som vill ha sumpbönsblad för att brygga en dryck.",al={"mebok","vem är mebok mizzyrix","goblin i ratchet"}},{q="Vem ska du prata med efteråt?",a="När du har hjälpt Ignatz igenom träsket ska du hitta Mebok Mizzyrix i Ratchet.",al={"vart ska stinky","var lämnar man in stinkys flykt"}}},fp="15,299,23.362.0,15.256.1,23.166.0,39.125.0,22.82.0,34.60.0"}
P.entries["quest:1271"] = {n="Feast at the Blue Recluse",s="Ditt arbete för Morgan Stern i Dustwallow Marsh, som avslutas med ... and Bugs, leder dig tillbaka till Angus Stern på Blue Recluse.",h="Ditt arbete för Morgan Stern i Dustwallow Marsh, som avslutas med ...",kw={"angus stern","dustwallow marsh","fest på blue recluse","familjen stern","blue recluse","morgan stern"},sec={{t="Tillbaka till Blue Recluse",b="Angus Stern är morbror till Morgan Stern, vars receptforskning du hjälpte till med i Dustwallow Marsh. Vägen leder dig nu tillbaka till Angus på Blue Recluse."},{t="Vad Angus har hört",b="Angus har hört från sin brorson att du hjälpte till med hans forskning och räddade en av hans medarbetare ur en knipa. Familjen Stern tar hand om sina vänner, och en fest till din ära ska just börja."}},faq={{q="Vem är Angus Stern?",a="Angus Stern är morbror till Morgan Stern, som samlar recept i Theramore, och har anknytning till Blue Recluse.",al={"angus stern","värd på blue recluse","vem ordnar festen"}},{q="Hur är Angus Stern släkt med Morgan Stern?",a="Angus är Morgans morbror. Angus skickade Morgan till Theramore för att samla recept till Blue Recluse nya meny med träsktema.",al={"angus och morgan släkt","familjen stern","är morgan angus brorson"}},{q="Vad kommer före det här uppdraget?",a="Det följer på ... and Bugs, det sista i arbetet du gjorde åt Morgan Stern i Theramore.",al={"föregående uppdrag","vad kommer före festen"}}},fp="25,124,24.155.0,20.209.1,19.113.0,45.119.0,29.84.0"}
P.entries["quest:1273"] = {n="Questioning Reethe",s="Ogron, som Krog skickade för att spåra upp människan Reethe, har äntligen hittat honom efter ett långt sökande och säger att han gömde sig väl för att vara människa. Ogron oroar sig för att tiden i träsket kan ha gjort Reethe galen och ber dig följa med för att få svar av honom. Sedan går färden tillbaka till Krog i Brackenwall Village.",h="Ogron, som Krog skickade för att spåra upp människan Reethe, har äntligen hittat honom efter ett långt...",kw={"brackenwall","dustwallow","förhör","krog","träsk","ogron","reethe"},sec={{t="Ogrons sökande",b="Efter ett långt sökande hittade Ogron Reethe, som enligt Ogron gömde sig väl för att vara människa. Ogron befarar att så många dagar i träsket kan ha gjort Reethe galen och vill att du följer med för att få svar av honom. Sedan väntar Krog i Brackenwall Village på att du återvänder."},{t="Tillbaka hos Krog",b="Krog är nöjd med att Reethe har lämnat träsket och hånar människor för att de är så klena att de inte ens återhämtar sig från ett litet pilsår. Krog drar slutsatsen att den här delen av mysteriet inte ledde någonstans och att sökandet måste fortsätta på annat håll."}},faq={{q="Vem hittade Reethe?",a="Ogron hittade Reethe efter ett långt sökande och vill att du följer med för att få svar av honom.",al={"vem ger uppdraget questioning reethe","uppdragsgivare för questioning reethe","ogron reethe"}},{q="Varför vill Ogron ha sällskap?",a="Ogron oroar sig för att Reethe kan ha blivit galen efter så lång tid i träsket.",al={"varför hjälpa ogron","är reethe galen","varför konfrontera reethe"}},{q="Vem ska du rapportera till efteråt?",a="Krog i Brackenwall Village.",al={"var lämnar man in questioning reethe","vem pratar jag med efter reethe","lämna in reethe"}}},fp="18,310,14.266.0,14.230.1,17.84.0,28.71.0,31.29.0"}
P.entries["quest:1274"] = {n="The Missing Diplomat",s="En stillsam förfrågan i Stormwind för dig till Bishop DeLavey i Stormwind Keep. Kyrkan och kronan behöver hjälp med en alltför farlig sak för offentliga kanaler.",h="En stillsam förfrågan i Stormwind för dig till Bishop DeLavey i Stormwind Keep.",kw={"bishop delavey","diplomat","utredning","stormwind keep","den försvunna diplomaten","thomas"},ang={["faction:Alliance"]="Att hitta den försvunna diplomaten är viktigt för Alliansens anseende och försvar. Utredningen kan blottlägga hot inom Stormwinds eget hov.",["race:Human"]="Som människa från Stormwind står du inför en fråga som rör ditt hemlands stabilitet under en skör regenttid."},sec={{t="En stillsam kallelse",b="När du färdas genom Stormwind kommer Thomas, en altarpojke, fram med en stillsam förfrågan. Bishop DeLavey, en respekterad präst i Church of the Holy Light, behöver hjälp av någon utifrån i Stormwind Keep. Han säger att saken är känslig och brådskande. Du måste hålla den hemlig, så att folket inte grips av panik."},{t="Viskningar i borgen",b="I Stormwind Keep berättar Bishop DeLavey varför saken måste förbli hemlig: en högt uppsatt kunglig dignitär har försvunnit under mystiska omständigheter. Oro inom riket håller på att gro, och King Varian Wrynn är försvunnen. Minsta tecken på fulspel bland rikets högsta skikt kan hota den sköra freden."}},faq={{q="Vem är Thomas?",a="Thomas är altarpojke vid Cathedral of Light och springer ärenden åt Bishop DeLavey. Han håller utkik efter dugliga äventyrare på Stormwinds gator och visar dem till borgen när kyrkan eller staten behöver diskret hjälp.",al={"vem är thomas","thomas stormwind","thomas uppdragsgivare"}},{q="Vem är Bishop DeLavey?",a="Bishop DeLavey är en högt uppsatt präst i Church of the Holy Light vid Stormwind Keep. Han samarbetar med det kungliga hovet kring diskreta säkerhetsfrågor och känsliga utredningar som stadsvakterna inte öppet kan driva.",al={"vem är bishop delavey","delavey","bishop delavey"}},{q="Varför hanteras saken i hemlighet?",a="Stormwind är redan oroligt: King Varian Wrynn är försvunnen, och Defias Brotherhood hetsar till uppror i hela Westfall. Nyheten om att ännu en framstående diplomat eller ämbetsman har försvunnit kan sprida panik eller blotta svagheter vid hovet.",al={"varför diskret","varför hemlighetsmakeri","varför hemligt"}},{q="Vart leder utredningen?",a="Utredningen börjar hos Bishop DeLavey i Stormwind Keep. Den går genom Stormwind och de omgivande människoterritorierna och fortsätter sedan till farliga trakter på andra sidan havet.",al={"vart leder den försvunna diplomaten","nästa steg för den försvunna diplomaten"}},{q="Vem är den försvunna diplomaten?",a="Bishop DeLavey håller diplomatens identitet hemlig i början av utredningen. Om den avslöjas kan utredningen hotas och den försvunna ämbetsmannen och riket utsättas för fara.",al={"vem är diplomaten","den försvunna diplomatens identitet"}}},fx={["46e2b0bf"]={q="Varför vill Thomas att du träffar Bishop DeLavey?",a="Unge Thomas handlar direkt på Bishop DeLaveys order. DeLavey bad honom att diskret leta efter dugliga äventyrare i Stormwind som kan hantera ett känsligt och brådskande ärende åt kungariket. Thomas har inget personligt intresse i saken; han vill bara tjäna biskopen plikttroget och se till att du når fästet utan att väcka uppmärksamhet.",al={"varför skickar thomas dig","thomas motiv i the missing diplomat","varför träffa bishop delavey"}},["227c4a3f"]={q="Varför rekryterar Bishop DeLavey äventyrare i stället för stadsvakten?",a="Uppdraget rör en mycket viktig fråga som måste hållas strikt hemlig. Om Stormwinds stadsvakt mobiliseras eller militären får officiell uppmärksamhet kan känslig information läcka ut i staden. Genom att låta Thomas diskret kontakta självständiga äventyrare som du kan biskopen undersöka saken i tysthet utan att varna möjliga fiender eller oroa allmänheten.",al={"varför inte stadsvakten","varför rekrytera äventyrare i the missing diplomat","varför behöver bishop delavey dig"}}},fp="20,154,15.290.0,20.306.1,14.221.0,22.207.0,37.236.0,35.165.0,28.177.0"}
P.entries["quest:1275"] = {n="Researching the Corruption",s="Gershala Nightwhisper i Auberdine söker efter fördärvade hjärnstammar från varelserna som hemsöker Blackfathom Deeps. Rapporter om att blodsalverna ägnar sig åt demonisk magi på andra sidan havet oroar honom. Han hoppas kunna studera naga- och satyrernas fysiologiska förfall för att förutse och kanske förhindra ännu en katastrofal alvisk mutation.",h="Gershala Nightwhisper i Auberdine söker efter fördärvade hjärnstammar från varelserna som hemsöker...",kw={"ashenvale","auberdine","blackfathom deeps","blodsalver","corrupted brain stem","corruption abroad","gershala nightwhisper","naga","satyr"},ang={["class:Druid"]="Druider känner en medfödd avsky för satyrerna, vars demoniska fördärvelse besudlar den naturliga drömmen och förvrider själva landet.",["class:Mage"]="Gershalas mörka undersökning påminner bryskt om de fysiska och andliga kostnaderna av vårdslöst och okontrollerat magiskt beroende.",["faction:Alliance"]="Alliansen håller ett vakande öga på rapporter om att blodsalverna på andra sidan havet förfaller till mörk magi och fruktar att ett nytt demoniskt hot ska uppstå.",["race:NightElf"]="För nattalverna berör forskningen deras smärtsammaste historiska sår: deras släktingars katastrofala förfall till satyrer och naga som hemsöker Kalimdor."},sec={{t="En varning ur historien",b="För Kalimdors nattalver är deras forna släktingars undergång ett levande minne, inristat i monster. För tiotusen år sedan dukade Highborne under för de demoniska krafternas lockelse och förvandlades till hornprydda satyrer eller slingrande naga. Att se högalverna kalla sig blodsalver och omfamna mörk magi är för Gershala Nightwhisper ingen avlägsen kuriositet, utan historia som är dömd att upprepa sig."},{t="Ned i djupet",b="Blackfathom Deeps är en idealisk plats för Gershalas mörka undersökning. Under The Zoram Strand i Ashenvale ligger ruinerna av ett underjordiskt tempel, fulla av både satyrkultister och slingrande naga. Genom att skicka en äventyrare för att samla hjärnstammar från båda monstren hoppas han kunna undersöka det biologiska sambandet mellan arkan beroendeställning, demonisk fördärvelse och katastrofal kroppslig förvandling."},{t="Ett desperat botemedel",b="Gershalas metoder är kyligt anatomiska, men hans uttalade avsikt är att förebygga. Han tror att kunskap om de exakta fysiologiska mutationer som satyrer och naga delar kan hjälpa till att rädda blodsalverna från fullständig fördömelse. Om forskning i Darkshore verkligen kan påverka de desperata alverna i Quel'Thalas är fortfarande en öppen fråga."}},faq={{q="Varför bryr sig Gershala Nightwhisper om blodsalverna?",a="Gershala fruktar att blodsalvernas flirt med demoniska krafter ska skapa ännu en ras förvridna monster som hotar Azeroth, liksom alvernas högmod förr gav upphov till satyrerna och naga.",al={"varför hjälpa blodsalver","gershala och blodsalverna","auberdine och blodsalverna"}},{q="Var samlar du in de fördärvade hjärnstammarna?",a="De samlas in från satyrerna och naga som bor i Blackfathom Deeps, ett gammalt tempelkomplex begravt längs The Zoram Strand på Ashenvales nordvästra kust.",al={"var finns hjärnstammar","hjärnstammarnas plats","byte fördärvad hjärnstam"}},{q="Varför vill han särskilt ha prover från satyrer och naga?",a="Både satyrerna och naga härstammar från alver som förvreds av onaturliga krafter: satyrerna genom demoniska pakter och naga genom Sundering. Gershala vill jämföra deras hjärnmutationer för att kartlägga hur alvers fysiologi bryts ned under mörk makt.",al={"varför satyrer och naga","sambandet mellan satyrer och naga"}},{q="Vem leder dig till uppdraget?",a="Du kan hänvisas till Gershala Nightwhisper i Auberdine via ett inledande uppdragssteg, 'The Corruption Abroad', men han erbjuder också undersökningen direkt.",al={"förutsättningsuppdrag","samband med corruption abroad"}},{q="Vad tänker Gershala göra med proverna?",a="Han tänker studera de fysiologiska sambanden mellan de två formerna av fördärvelse. Han hoppas att kunskapen kan hjälpa till att hindra blodsalverna från att sjunka djupare ner i monstrositet.",al={"studie av hjärnstammar","gershalas forskningsmål"}},{q="Hotas Auberdine direkt av Blackfathom Deeps?",a="Blackfathom Deeps ligger precis över den södra gränsen i Ashenvale, och nattalverna i Auberdine bevakar hela kustområdet efter tecken på att den demoniska fördärvelsen och Twilight-fördärvelsen tilltar.",al={"varför auberdine bryr sig","hot från blackfathom deeps mot darkshore"}}},fx={["57dc4e51"]={q="Vilka skickas du mot i Blackfathom Deeps?",a="Gershala skickar dig mot satyrerna och nagorna som håller till i Blackfathom Deeps längs Ashenvales kust. Båda folken var en gång nattalver, innan de förvandlades på groteska sätt av magi. Satyrerna förvreds av demonisk korruption under De äldstes krig, medan nagorna muterades av uråldriga mörka krafter under havet. Nu håller båda fraktionerna till i templets översvämmade ruiner.",al={"vilka fiender finns i researching the corruption","vem slåss jag mot i blackfathom deeps","målen i researching the corruption"}}},fp="26,233,22.331.0,14.305.0,16.273.1,58.152.0,46.148.0,53.212.0,27.148.0,49.142.0,54.164.0"}
P.entries["quest:1276"] = {n="The Black Shield",s="Krog minns nu varifrån namnet Mosarn kommer: en högt ansedd smed i Thunder Bluff, vars rustning en gång gavs till Krog av The Earthen Ring. Krog hoppas att Mosarn kan berätta mer om den svärtade järnskölden, eftersom Reethe inte gav några användbara svar. Mosarn finns i Thunder Bluff.",h="Krog minns nu varifrån namnet Mosarn kommer: en högt ansedd smed i Thunder Bluff, vars rustning en gång gavs...",kw={"blackened iron shield","smed","dustwallow","earthen ring","krog","mosarn","reethe","thunder bluff"},sec={{t="En smeds namn",b="Krog minns var han hört namnet Mosarn förut: en högt ansedd smed i Thunder Bluff. The Earthen Ring tackade en gång Krog med en rustning som Mosarn hade tillverkat, och Krog talar väl om arbetet. Krog säger att Mosarn också tillverkade skölden och kanske kan berätta mer om den. Det är ett svagt spår, medger Krog, men Reethe gav inga användbara svar, så det är allt som finns. Den svärtade järnskölden ska till Mosarn, som finns i Thunder Bluff."},{t="Mosarns ord",b="Mosarn håller med om att skölden är ett verk av hans hand, men kan inte säga mycket mer än så. Han har tillverkat så många sköldar och rustningar att han inte kan minnas dem alla."}},faq={{q="Vem är Mosarn?",a="Mosarn är en högt ansedd smed i Thunder Bluff, som tillverkade en rustning som The Earthen Ring gav till Krog.",al={"vem är mosarn","var finns mosarn","mosarn thunder bluff"}},{q="Varför ta skölden till Mosarn?",a="Krog säger att Mosarn tillverkade skölden och kanske kan berätta mer om den. Krog kallar det ett svagt spår, men eftersom Reethe inte gav några användbara svar är det allt som finns.",al={"varför visa mosarn skölden","spår efter svärtad sköld","vad vet mosarn"}},{q="Hur känner Krog Mosarn?",a="The Earthen Ring tackade Krog med en rustning som Mosarn hade tillverkat.",al={"krogs koppling till mosarn","hur känner krog smeden"}}},fp="16,300,14.436.0,13.161.1,14.112.0,30.163.0,26.71.0"}
P.entries["quest:128"] = {n="Blackrock Bounty",s="Blackrock Bounty är ett försvarsavtal utfärdat av Guard Howe i Lakeshire på uppdrag av Magistrate Solomon. När Stormwind inte skickar förstärkningar betalar staden fristående äventyrare för att rensa bort de elitära Blackrock Champions som samlas i de norra bergen. Genom att slå ut dessa befälhavare på slagfältet hoppas man störa orc-klanens samordnade angrepp mot Redridge.",h="Blackrock Bounty är ett försvarsavtal utfärdat av Guard Howe i Lakeshire på uppdrag av Magistrate Solomon.",kw={"blackrock","prispengar","burning steppes","champion","guard howe","lakeshire","magistrate solomon","redridge","stormwind"},ang={["class:Warrior"]="Blackrock Champions är tungt bepansrade, erfarna veteraner och slagskämpar som sätter en krigares disciplin och uthållighet på prov i närstrid.",["faction:Alliance"]="Lakeshire står som Stormwinds östra sköld. Om Blackrock-orcherna bryter igenom bergslägren blir Alliancens centrala jordbruksmarker direkt utsatta för invasion.",["race:Human"]="Blackrock-klanen förstörde det ursprungliga kungariket Stormwind under det första kriget. För människornas försvarare är det ett bittert, nedärvt måste att stoppa deras återkomst söderut."},sec={{t="Att hålla den suveräna gränsen",b="Redridge har länge lytt under kungariket Stormwinds suveräna styre, men Blackrock-klanen respekterar inte människornas gränser. Orcherna strömmar ner genom bergspassen från Burning Steppes och har upprättat kraftigt befästa läger i hela norra Redridge. Med kung Varian Wrynn försvunnen och regentskapet i Stormwind ovilligt att skicka kungliga soldater har lokala ledare som Magistrate Solomon tvingats betala ut prispengar ur stadens krympande kassa för att skydda Lakeshire."},{t="Jakt på Champions",b="Guard Howe pekar ut Blackrock Champions som ryggraden i invasionsstyrkornas förtrupp. De tjänstgör som gruppledare och härdade veteraner i sina krigsband, samordnar truppernas rörelser och driver på de lägre rankade grunt-styrkorna. Genom att sätta ett pris på deras huvuden hoppas Lakeshires försvarare slå ut klanens taktiska ledning och hejda en fullskalig framryckning söderut innan stadens yttre försvarslinje kollapsar."}},faq={{q="Varför erbjuder Guard Howe prispengar i stället för att skicka stadsvakten?",a="Lakeshires lokala garnison är hårt pressad. Mellan patrullering av Lake Everstill, bevakning av broarna och försvar mot gnoller och orcher på plundringståg kan vakterna inte avvara en tillräckligt stor styrka för att anfalla befästa orcherläger direkt utan att lämna staden försvarslös.",al={"varför prispengar","var är stadsvakten","guard howes prispengar"}},{q="Var finns Blackrock Champions?",a="De är stationerade i de vidsträckta Blackrock-lägren i norra Redridge Mountains, strax väster om landsvägen som klättrar mot Burning Steppes.",al={"var finns champions","championernas plats","blackrock champions läger"}},{q="Varför invaderar Blackrock-orcherna Redridge?",a="Blackrock-klanen opererar från Blackrock Mountain i norr och ser de omgivande kullarna som strategiskt territorium att erövra och plundra. Med Stormwinds försvar splittrat försöker de driva bort människornas bosättningar och ta kontroll över bergspassen.",al={"varför blackrock i redridge","varför anfaller orcher lakeshire","blackrock-invasionen"}},{q="Varför skickar inte Stormwind kungliga soldater för att rensa bort dem?",a="Kung Varian Wrynn är försvunnen, och det kungliga hovet under regent Bolvar Fordragon och Lady Prestor hävdar att kungariket inte kan avvara sina arméer. Lakeshire har gång på gång begärt hjälp från huvudstaden, men fått avslag och lämnats att anlita förbipasserande legoknektar.",al={"varför ingen stormwind-armé","var finns hjälp från stormwind","magistrate solomons förstärkningar"}},{q="Vilken roll har Champions i Blackrock-klanen?",a="Champions fungerar som taktiska ledare vid fronten. Varje Blackrock-stridsgrupp förlitar sig på en champion som leder angrepp, upprätthåller brutal disciplin och för sina styrkor in på Alliancens territorium.",al={"vad är blackrock champions","champion-rang","blackrocks befälsenhet"}},{q="Vem godkände detta priskontrakt?",a="Magistrate Solomon, Lakeshires civila ledare, godkände prispengarna och gav Guard Howe i uppdrag att rekrytera dugliga kämpar för att utföra utrensningen.",al={"vem betalar prispengarna","vem vill se champions döda","magistrate solomons prispengar"}}},fx={ae8dcd14={q="Varför vill Guard Howe att Blackrock Champions dödas?",a="Blackrock-klanen har öppet invaderat Stormwinds suveräna territorium och hotar Lakeshire och de omgivande Redridge Mountains. Guard Howe följer direkta order från Magistrate Solomon om att försvara staden. Genom att angripa mästarna, de stridshärdade ledare som styr lägret, hoppas staden bryta inkräktarnas befälsstruktur innan en fullskalig attack övermannar Redridges klena försvar.",al={"varför döda blackrock champions","guard howes motiv","varför vill howe ha dem döda"}}},fp="16,272,26.389.0,23.375.0,70.240.0,42.169.0,45.234.0,60.275.0,55.141.0,36.150.0"}
P.entries["quest:1282"] = {n="They Call Him Smiling Jim",s="Guard Byron tycker synd om en man som kallas Smiling Jim och antyder att han inte alltid har varit som nu. Byron vill helst inte prata om det och skickar dig till Captain Garran Vimes i Theramore.",h="Guard Byron tycker synd om en man som kallas Smiling Jim och antyder att han inte alltid har varit som nu.",kw={"captain garran vimes","dustwallow marsh","guard byron","james hyal","shady rest inn","smiling jim","theramore"},sec={{t="En sorglig historia",b="Byron tycker synd om Jim och säger att det inte alltid har varit så här för honom. Jim drev en gång ett värdshus i träsket, och ett fantastiskt sådant. Byron vill helst inte gå in på detaljer. Den som verkligen vill höra historien får ta upp saken med Captain Garran Vimes i Theramore."},{t="Vimes berättar",b="Vimes säger att mannen heter James Hyal. Hyal byggde ett värdshus i utkanten av The Barrens, tänkt som ett trevligt stopp för resenärer, och det gick bra ett tag. Sedan tappade Theramore greppet om vägarna genom träsket, och ogres flyttade in. Hyal var envis och ville inte byta sin dröm mot tryggheten bakom Theramores murar, och Shady Rest Inn slukades av lågorna. Vimes säger att utredningen hittills haft föga framgång och föreslår att den som vill hjälpa till söker igenom ruinerna."}},faq={{q="Vem är Smiling Jim?",a="Guard Byron tycker synd om honom och säger att han inte alltid var sådan här. Byron minns att Jim en gång drev ett värdshus i träsket, och ett fantastiskt sådant.",al={"vem är jim","smiling jims identitet","vem är den leende mannen"}},{q="Varför skickar Guard Byron dig till Captain Vimes?",a="Byron vill helst inte prata om Jims förflutna och hänvisar dig i stället till Captain Garran Vimes.",al={"varför prata med vimes","byrons uppdrag","guard byrons anledning"}},{q="Var hittar jag Captain Garran Vimes?",a="Captain Garran Vimes finns i Theramore.",al={"vem är captain vimes","captain vimes i dustwallow"}}},fp="25,194,11.246.0,15.479.1,19.146.0,47.90.0,37.37.0"}
P.entries["quest:1284"] = {n="Suspicious Hoofprints",s="Hovspår leder bort från de rykande resterna av Shady Rest Inn. Några är lätta att se, medan andra nästan försvinner i den mjuka träskleran. Captain Garran Vimes i Theramore är den du ska rapportera dem till.",h="Hovspår leder bort från de rykande resterna av Shady Rest Inn.",kw={"the barrens","captain garran vimes","kentaur","dustwallow marsh","falgran hastil","hovspår","shady rest inn","theramore"},sec={{t="Spår i leran",b="Rader av spår leder bort från Shady Rest Inn, vars ruiner fortfarande ryker. Några av avtrycken syns tydligt, medan längre bort är raderna nästan osynliga i träskets mjuka lera. Captain Garran Vimes i Theramore bör få veta om dem."},{t="Vad Vimes tror",b="Vimes påpekar att det finns gott om kentauraktivitet i trakterna nära Dustwallow Marsh. Korta utflykter till The Barrens avslöjade deras läger och boplatser utspridda över området. Vimes skickar Falgran Hastil, en av spårarna, för att ta reda på vart spåren leder."}},faq={{q="Var finns hovspåren?",a="De leder bort från Shady Rest Inn, som fortfarande ryker, över den mjuka träskleran.",al={"var finns spåren","hovspårens plats","spår vid shady rest inn"}},{q="Vem ska få rapporten om spåren?",a="Captain Garran Vimes i Theramore.",al={"vem ska jag berätta om hovspåren för","vem får rapporten om hovspåren","garran vimes hovspår"}},{q="Hur lätta är spåren att följa?",a="Några är tydliga, men många fler rader är nästan osynliga i leran.",al={"är spåren svåra att se","svaga spår i träsket"}}},fp="21,208,17.246.0,22.272.1,31.91.0,41.35.0,34.68.0"}
P.entries["quest:1285"] = {n="Daelin's Men",s="Adjutant Tesoran har hittat Lieutenant Paval Reethe i vaktens register. Där står det att han tog värvning i Kul Tiras marinkår vid sexton års ålder, utmärkte sig i tjänsten och befordrades flera gånger. Han blev sedan en del av vakten i Theramore, bland rekryterna som seglade över med Lady Proudmoore. Den sista anteckningen anger att Reethe saknas, och Captain Garran Vimes ska få veta det.",h="Adjutant Tesoran har hittat Lieutenant Paval Reethe i vaktens register.",kw={"adjutant tesoran","daelins män","desertörer","dustwallow marsh","garran vimes","kul tiras","paval reethe","theramore"},sec={{t="Vad registren berättar",b="Captain Garran Vimes skickade dig till Adjutant Tesoran, som nu har gått igenom böckerna och hittat Lieutenant Paval Reethe. Reethe tog värvning i Kul Tiras marinkår vid sexton års ålder, och hans utmärkta tjänstgöring ledde till befordringar. Han gick senare med i vakten i Theramore, liksom de flesta rekryterna som seglade över med Lady Proudmoore. Anteckningen slutar med att Reethe står som saknad. Vimes i Theramore ska få beskedet."},{t="Kaptenens reaktion",b="Vimes tolkar ”saknad” som Tesorans vänliga omskrivning för förrädare. Vimes är säker på att Reethe är en av dårarna vars blinda lojalitet mot Admiral Daelin får dem att bli förrädare, och ser en bitter ironi i det, eftersom desertörerna anklagar Theramore för att förråda Alliansen."}},faq={{q="Vem är Adjutant Tesoran?",a="Adjutant Tesoran är den som slog upp Lieutenant Paval Reethe i vaktens register och läste upp vad det stod.",al={"tesoran","vem ger daelins män"}},{q="Vad säger registren om Paval Reethe?",a="Reethe tog värvning i Kul Tiras marinkår vid sexton års ålder, befordrades för utmärkt tjänstgöring och gick senare med i vakten i Theramore bland rekryterna som seglade över med Lady Proudmoore. Anteckningen slutar med att Reethe står som saknad.",al={"reethe bakgrund","reethe register","paval reethe historia"}},{q="Vem får beskedet om Reethe?",a="Captain Garran Vimes i Theramore.",al={"varför återvända till vimes","garran vimes reethe"}}},fp="12,352,20.404.0,22.272.1,24.116.0,43.244.0,31.35.0"}
P.entries["quest:1286"] = {n="The Deserters",s="Captain Garran Vimes säger att desertörer har slagit sig ner i ett torn som Theramore hade övergett. Tornet står vid Lost Point, sydost om värdshuset. En man vid namn Jacken leder desertörerna, och Vimes vill få information om Reethe från honom.",h="Captain Garran Vimes säger att desertörer har slagit sig ner i ett torn som Theramore hade övergett.",kw={"balos jacken","captain garran vimes","desertörer","dustwallow marsh","lost point","reethe","vakttorn"},sec={{t="Ett övertaget torn",b="Vimes medger att det har varit svårt att hålla ut i träsket, men hans folks beslutsamhet har hållit flera försvarstorn stående. Spaningsrapporter säger att desertörer har flyttat in i ett övergivet torn vid Lost Point, sydost om värdshuset. En man vid namn Jacken leder dem. Vimes ber dig ta reda på vilken information Jacken kan lämna om Reethe och varnar för att Jacken kanske inte ger upp den lätt."}},faq={{q="Vem skickar dig för att ta itu med desertörerna?",a="Captain Garran Vimes, vars spaningsrapporter säger att desertörer har slagit sig ner i ett av tornen som Theramore övergav.",al={"vem startar desertörerna","vem ger uppdraget om desertörerna"}},{q="Var gömmer sig desertörerna?",a="Vid Lost Point, sydost om värdshuset, i ett övergivet torn i Dustwallow Marsh.",al={"desertörernas plats","var ligger lost point"}},{q="Vem leder desertörerna vid Lost Point?",a="En man vid namn Jacken, även kallad Balos Jacken, leder dem. Vimes varnar för att Jacken kanske inte lämnar ut information lätt.",al={"vem är balos jacken","desertörernas ledare"}},{q="Vad vill Captain Vimes ha från Balos Jacken?",a="Information om Reethe från Jacken och desertörerna.",al={"varför hitta jacken","vad vill vimes ha"}}},fp="13,248,13.415.0,41.115.0,31.90.0,38.109.0,47.56.0"}
P.entries["quest:1287"] = {n="The Deserters",s="När du frågar om Reethe kallar Balos Jacken, ledare för avhopparna vid Lost Point, honom feg och säger att de drev bort honom från lägret. Jacken ber dig sedan glömma att ni någonsin träffats. Captain Garran Vimes i Theramore är den du ska berätta om Reethe för.",h="När du frågar om Reethe kallar Balos Jacken, ledare för avhopparna vid Lost Point, honom feg och säger att de...",kw={"balos jacken","brackenwall village","caldwell","avhoppare","garran vimes","lost point","reethe","theramore"},sec={{t="Utkastad",b="Jacken säger att avhopparna drev bort Reethe för att han gång på gång plundrade ogreernas förråd i Brackenwall Village. Enligt Jacken är avhopparna för få för att stå emot ogreerna, och Reethe gick för långt en gång för mycket, så gruppen lämnade honom att klara sig själv. Som tack för svaret ber Jacken dig glömma mötet."},{t="Tillbaka i Theramore",b="Vimes säger att Lieutenant Caldwell ska skickas mot avhopparna vid Lost Point och även få i uppdrag att hitta Reethe. Vimes anser att träsket varken är så stort eller så svårt att ta sig fram i att Caldwell inte skulle kunna hitta Reethe."}},faq={{q="Varför kastades Reethe ut ur avhopparnas läger?",a="Jacken säger att Reethe fortsatte att plundra ogreernas förråd i Brackenwall Village. Avhopparna är för få för att stå emot dem, så de lämnade Reethe att klara sig själv.",al={"varför förvisade avhopparna reethe","reethe brackenwall village","varför sparkade balos ut reethe"}},{q="Vem är Balos Jacken?",a="Jacken leder avhopparna vid Lost Point. När han får frågor om Reethe kallar han honom feg.",al={"vem är balos jacken","balos jacken historia","balos jacken dustwallow"}},{q="Vem vill höra om Reethe?",a="Captain Garran Vimes i Theramore, även om Jacken själv hoppas att du ska glömma att du någonsin träffat avhopparna.",al={"var lämnar man in avhopparna","vem vill ha information om reethe"}}},fp="13,260,10.335.0,17.214.1,47.162.0,20.81.0,31.106.0"}
P.entries["quest:1288"] = {n="Vimes's Report",s="Captain Garran Vimes anser att ditt arbete är det bästa Vimes har sett från en amatör. Lady Jaina Proudmoore bad Vimes hålla henne underrättad om en känslig situation, och Vimes ger dig rapporten att ta med till henne i Theramore.",h="Captain Garran Vimes anser att ditt arbete är det bästa Vimes har sett från en amatör.",kw={"dustwallow","garran vimes","jaina proudmoore","rapport","theramore","vimes"},sec={{t="En rapport till Lady Proudmoore",b="Lady Proudmoore bad Captain Vimes hålla henne underrättad om en känslig situation, och Vimes har inte talat med henne på ett tag. Vimes tänkte överlämna rapporten senare, men anser nu att det passar bättre att du talar med henne om den, eftersom du mycket väl kan ha bättre svar på hennes frågor än Vimes skulle ha."}},faq={{q="Vem ger dig rapporten som du ska ta till Jaina Proudmoore?",a="Captain Garran Vimes räcker dig Vimes rapport att ta med till Lady Jaina Proudmoore i Theramore.",al={"vem inleder vimes rapport","vem ger rapporten","vem skrev vimes rapport"}},{q="Varför skickar Captain Vimes dig i stället för att själv gå dit?",a="Vimes har inte talat med Lady Proudmoore på ett tag och tycker att det passar bättre att du går i hans ställe. Vimes tror att du kan ha bättre svar på hennes frågor.",al={"varför skicka mig","varför lämnar vimes inte över den","varför rapport till jaina"}},{q="Vart ska rapporten?",a="Till Lady Jaina Proudmoore i Theramore.",al={"var lämnar jag in vimes rapport","var finns jaina proudmoore","rapportens destination"}}},fp="14,221,28.313.0,53.93.0,57.166.0,33.38.0"}
P.entries["quest:1289"] = {n="Vimes's Report",s="Lady Jaina Proudmoore har läst Captain Garran Vimes rapport och tackar dig för hjälpen med utredningen. Hon ber dig återvända till Vimes och hjälpa till att lösa mysteriet.",h="Lady Jaina Proudmoore har läst Captain Garran Vimes rapport och tackar dig för hjälpen med utredningen.",kw={"captain garran vimes","dustwallow marsh","utredning","lady jaina proudmoore","theramore","vimes rapport"},sec={{t="Tillbaka till kaptenen",b="Utifrån Captain Vimes rapport ser Lady Proudmoore att du har varit till stor hjälp i hans utredning, och hon tackar dig för det. Hon känner sig lugnare när hon vet att ärendet är i så goda händer. Hon ber dig återvända till Captain Vimes i Theramore och hjälpa honom att lösa mysteriet."}},faq={{q="Vem skickar dig tillbaka till Captain Vimes?",a="Lady Jaina Proudmoore, efter att hon har läst Vimes rapport i Theramore.",al={"vem ger vimes rapporten","jaina uppdragsgivare","vem skickar mig till vimes"}},{q="Vad tycker Lady Jaina om rapporten?",a="Hon säger att du har varit till stor hjälp i utredningen och tackar dig för det. Vetskapen om att ärendet är i goda händer gör henne lugnare.",al={"jainas reaktion","vad säger jaina om vimes rapport"}},{q="Var hittar du Captain Garran Vimes?",a="Captain Garran Vimes är i Theramore.",al={"var är captain vimes","captain vimes plats","var lämnar jag in vimes rapport"}}},fp="14,188,19.309.0,36.69.0,41.140.0,39.37.0"}
P.entries["quest:129"] = {n="A Free Lunch",s="A Free Lunch är ett uppdrag för Alliansen från Lakeshire, där värdshuskocken Darcy ber en äventyrare ta en färdig måltid till Guard Parker. Parker patrullerar den farliga södra vägen mot Duskwood och håller infarten till Lakeshire fri från fientliga gnoller och Blackrock-orcher.",h="A Free Lunch är ett uppdrag för Alliansen från Lakeshire, där värdshuskocken Darcy ber en äventyrare ta en...",kw={"blackrock-orcher","darcy","darkshire","gratis lunch","gnoller","guard parker","lakeshire","parker's lunch","redridge mountains"},ang={["faction:Alliance"]="När du levererar Darcys mat blir det tydligt hur hårt vardagen drabbar vanligt folk och vakter vid frontlinjen i avlägsna alliansbosättningar, som till stor del lämnats att klara sig själva.",["profession:Cooking"]="En varm och vällagad fältranson är ofta det enda som håller en isolerad vakt vid liv när hen försvarar en fientlig vägkorsning."},sec={{t="En måltid för vägen",b="Vardagen i Redridge präglas av oro, men Darcy, som bor i Lakeshire, försöker hjälpa dem som försvarar staden på sitt eget sätt. Hon har packat en rejäl måltid åt Guard Parker, men kan inte själv leverera den. Vildmarken strax utanför stadsportarna kryllar av aggressiva gnoller från Redridge och kringströvande orchkrigarskaror, så det är alldeles för farligt för en obeväpnad civilperson att ta sig utanför stadens gränser. I stället förlitar hon sig på förbipasserande resenärer som kan bära ransonen längs vägen mot Darkshire."},{t="Gränsvakt",b="Guard Parker är posterad längs vägen söder om Lakeshire och håller vakt över rutten mellan Redridge och Duskwood. Vakterna i Redridge är oroväckande få, och Stormwinds armé skickar inte tillräckligt med förstärkningar mot de växande gnollflockarna från Redridge och Blackrock-klanen, som har förskansat sig i bergen. Att ensam hålla vakt i så fientliga trakter sliter hårt på vakter som Parker. Därför är enkla omtankar från civilbefolkningen och varm mat viktiga för truppernas moral."}},faq={{q="Var hittar man Guard Parker?",a="Guard Parker patrullerar grusvägen söderut från Lakeshire, mot gränsen till Duskwood och staden Darkshire.",al={"guard parker plats","var är parker","hitta guard parker"}},{q="Varför levererar inte Darcy lunchen själv?",a="Darcy är en vanlig civilperson och tycker att det är alldeles för farligt att ge sig ensam ut i utkanten av Lakeshire. Fientliga gnoller och Blackrock-orcher stryker längs vägarna precis utanför staden.",al={"varför kan inte darcy gå","darcy redridge"}},{q="Vilka hot måste Guard Parker hantera?",a="Parker måste försvara den södra vägen mot kringströvande gnollflockar från Redridge Mountains och aggressiva krigsskaror av Blackrock-orcher.",al={"parkers fiender","hot i redridge"}},{q="Vad händer när Guard Parker får sin lunch?",a="När Parker får Darcys måltid blir han tacksam, och så småningom skickar han äventyraren på fler vardagsärenden mellan vakterna och stadsborna. Det första blir ett besök hos den lokala örtkunniga.",al={"nästa uppdrag efter a free lunch","uppföljning för parker"}},{q="Varför har Stormwinds vakter svårt att hålla Redridge tryggt?",a="Kung Varian Wrynn är försvunnen och rikets politiska ledning är upptagen i Stormwind City. Därför får utposter som Lakeshire väldigt lite, om ens något, militärt stöd, och stadens vakter blir i praktiken helt isolerade.",al={"varför är lakeshire oförsvarat","stormwinds försummelse av redridge"}},{q="Vilken belöning lovar Darcy?",a="Som tack för att du bär Parkers måltid genom den farliga vildmarken lovar Darcy att laga och bjuda budbäraren på en gratis lunch när du kommer tillbaka till staden.",al={"vad är a free lunch","darcys belöning"}}},fx={a6c03f8c={q="Varför vill Darcy att Parker ska få den här lunchen?",a="Darcy har ett gott hjärta och tar hand om stadens försvarare. Guard Parker är posterad långt bort längs vägen mot Duskwood och hotas ständigt av gnoller och Blackrock-orcher utan avlösning. Darcy vet hur utmattande och ensamt patrulltjänsten kan vara i dessa farliga tider. Därför har hon lagat en färsk måltid som ska ge honom kraft och visa att Lakeshire uppskattar hans tjänst.",al={"darcys motiv till lunchen","varför skicka lunch till parker","bryr sig darcy om parker"}}},fp="12,185,19.312.0,19.332.0,32.89.0,44.147.0,42.85.0,47.158.1,58.146.0,32.96.0"}
P.entries["quest:13"] = {n="The People's Militia",s="Över hela Westfall möter The People's Militia ett växande hot från Defias. Gryan Stoutmantles frivilliga konfronterar nu tjuvar som lämnat vägöverfall bakom sig för att plundra Moonbrook och Gold Coast Quarry, och milisen kräver hårdare vedergällning.",h="Över hela Westfall möter The People's Militia ett växande hot från Defias.",kw={"alexston farmstead","defias looter","defias pillager","gold coast quarry","gryan stoutmantle","moonbrook","folkets milis","sentinel hill","westfall"},ang={["class:Paladin"]="Som paladin hör du Gryan Stoutmantle vädja till Ljuset om att rena Westfall från kriminell korruption. Det här fälttåget är ett direkt rättvisuppdrag för dig.",["faction:Alliance"]="Som Alliance-krigare ser du den bittra klyftan mellan Stormwind Citys bekväma murar och dess svältande gränstrakter, som lämnats helt åt sitt öde.",["race:Human"]="Som människa ställs du inför en tragisk kamp mot före detta stenhuggare och grannar som vänt sig våldsamt mot sitt eget folk."},sec={{t="Våldet trappas upp",b="Defias angrepp har gått från småskaligt röveri längs vägarna till ett större hot. Defias Looters och Pillagers, som slungar eld, har tagit över Westfalls ekonomiska centrum. De ockuperar Moonbrook, länsar Alexston Farmstead och har tagit kontroll över Gold Coast Quarry. Gryan Stoutmantle ser faran: om rövarna behåller dessa platser kan Westfall bli omöjligt att återta utan en reguljär kunglig armé."},{t="Milisens filosofi",b="Stormwind har inte skickat några soldater eller förnödenheter till Gryan Stoutmantle, så han vädjar till det heliga ljuset och de återstående böndernas beslutsamhet i Westfall. Milisens utnötningskrig bygger på att frivilliga för striden till Defias fästen. Om plundrarna drivs bort förvägras Brotherhood resurser, och de rädda invånarna får se att försvarare fortfarande kämpar för Westfalls fred och välstånd."}},faq={{q="Vad är The People's Militia?",a="Gryan Stoutmantle organiserade The People's Militia som en beväpnad frivilligstyrka för att försvara Westfall. Ledet består till stor del av bönder från Westfall som tvingats lämna sina hem och resande som sympatiserar med dem. De bildades för att göra motstånd mot Defias Brotherhood efter att Stormwinds kungliga hov vägrat skicka stadsvakter.",al={"folkets milis","vilka är milisen","westfalls milis"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en erfaren mänsklig befälhavare som leder Westfalls försvar från skansen högst upp på Sentinel Hill. Han är hängiven Ljuset och sitt hem och leder The People's Militia i dess desperata motstånd mot laglösas kontroll.",al={"gryan","vem är stoutmantle","stoutmantles bakgrund"}},{q="Varför plundrar Defias gårdar och stenbrott?",a="Defias Brotherhood försöker slå ut Westfalls livsmedelsförsörjning och lägga beslag på råmaterial. Genom att ta Gold Coast Quarry kontrollerar de sten och mineraler; när de erövrar Moonbrook och gårdar driver de bort hederligt folk och får baser för sin kriminella verksamhet.",al={"varför plundrar defias","defias i moonbrook","varför finns pillagers vid stenbrottet"}},{q="Varför har Stormwind inte skickat soldater till Westfall?",a="Stormwind har inte skickat soldater eftersom kung Varian Wrynn mystiskt har försvunnit, vilket lämnat pojkkungen Anduin på tronen under Highlord Bolvar Fordragons förmyndarskap. De adliga i House of Nobles har låst sig i omfattande politiska låsningar, vilket tänjer på kronans resurser och lämnar avlägsna områden som Westfall åt lokala försvarare.",al={"var är stormwinds vakter","varför hjälper inte stormwind","kung varian westfall"}},{q="Var finns Defias Pillagers och Looters?",a="Defias Pillagers och Looters samlas kring erövrade bosättningar i södra och västra Westfall. De finns i den övergivna staden Moonbrook, i Gold Coast Quarry längs de västra klipporna och vid den förstörda Alexston Farmstead.",al={"pillagers plats","var finns looters","defias platser"}}},fx={["3f9873c1"]={q="Varför vill Gryan Stoutmantle att Defias Pillagers och Looters dödas?",a="Defias Pillagers och Looters plundrar aktivt Westfalls kvarvarande gårdar och viktiga resurser, däribland Moonbrook, Gold Coast Quarry och Alexston Farmstead. Gryan Stoutmantle tänker inte låta tjuvarna beröva lokala familjer den lilla trygghet och försörjning de har kvar. Genom att slå ut deras rövarband hoppas han hejda deras framfart, skydda de överlevande nybyggarna och tydligt visa att laglöshet och korruption möts med våld.",al={"varför döda defias pillagers","gryan stoutmantles motiv","varför vill gryan ha pillagers dödade"}},["599e05d4"]={q="Vilka är Defias Pillagers och Looters som uppdraget riktar sig mot?",a="De är vanliga rövare och trollkarlar i Defias Brotherhood, utsända för att länsa Westfall. Medan enklare ficktjuvar stryker omkring på öppna fält angriper dessa plundrare och rövare etablerade bosättningar som Moonbrook och Gold Coast Quarry. Beväpnade med vapen och förödande eldmagi samlar de förråd, plundrar övergivna gårdar och driver brutalt bort alla nybyggare som försöker hindra dem.",al={"vilka är defias pillagers","vilka är defias looters","defias mål i westfall"}},["7d97eb03"]={q="Varför behöver Gryan Stoutmantle din hjälp i stället för att förlita sig på milisen?",a="The People's Militia är hårt pressad. Stormwind vägrar att skicka militärt stöd, så Sentinel Hill har bara en handfull frivilliga, bönder och pensionerade veteraner som kan vakta vägen och försvara den befästa kullen. De kan inte avvara soldater för omfattande motanfall i hela regionen utan att lämna basen försvarslös. Dugliga äventyrare som du ger milisen den offensiva kraft den så väl behöver.",al={"varför behöver gryan mig","varför inte använda milisen","varför använda äventyrare"}}},fp="20,249,19.343.0,24.368.0,29.282.0,25.223.0,46.263.0,47.298.0,45.231.0"}
P.entries["quest:130"] = {n="Visit the Herbalist",s="Efter att du levererat en måltid till hans avlägsna post ber Guard Parker dig om en tjänst innan du återvänder till Lakeshire Inn. Han vill visa Darcy vad han känner och ber dig köpa blommor hos stadens örtmästare. Parker insisterar på att örtmästaren inte får veta vem som beställt dem eller vem de är till.",h="Efter att du levererat en måltid till hans avlägsna post ber Guard Parker dig om en tjänst innan du...",kw={"påskliljor","darcy","blommor","guard parker","lakeshire","martie jainrose","redridge","besök örtmästaren"},ang={["faction:Alliance"]="Trots det ständiga hotet från gnollflockar och blackrockorcher som tränger in i Redridge fortsätter små romanser att spira bland Lakeshires försvarare.",["profession:Herbalism"]="Besöket hos Martie Jainrose visar samlare var de hittar Lakeshires främsta handlare inom örtmästeri och alkemi, i stadens västra utkant."},sec={{t="En vakts hemliga önskan",b="Guard Parker är stationerad längs den ensliga södra infarten till Lakeshire och håller utkik efter blackrockorcher och gnoller under sitt vaktpass. När du kommer med en varm måltid från Darcy på Lakeshire Inn passar han på att återgälda hennes vänlighet. I stället för att låta dig gå tillbaka direkt ber han dig stanna till i den lokala örtbutiken i stadens västra ände och köpa en bukett blommor åt henne."},{t="Skvaller och hemlig uppvaktning",b="Livet i den lilla staden Lakeshire lämnar inte mycket utrymme för hemligheter, så Parker varnar dig uttryckligen för att avslöja för örtmästaren Martie Jainrose vem blommorna kommer från eller vem de är till. När du kommer till hennes butik kan Martie inte låta bli att retas med dig och antar att du snabbt har hittat någon att hålla kär i här i staden. I en trakt som hemsöks av orcher och banditer är även en anspråkslös romantisk gest ett välkommet avbrott."}},faq={{q="Vem ger dig uppdraget att besöka örtmästaren?",a="Guard Parker ger dig uppdraget. Han är stationerad vid södra vägen in i Redridge Mountains, strax norr om gränsen till Duskwood.",al={"vem ger uppdraget","uppdragsgivare","guard parker"}},{q="Vem är örtmästaren i Lakeshire?",a="Martie Jainrose är den lokala örtmästaren och blomsterhandlaren i Lakeshire. Hennes butik ligger i stadens västra ände.",al={"vem är martie jainrose","var finns örtmästaren","örtmästare i lakeshire"}},{q="Varför vill Guard Parker ha blommor?",a="Parker vill skicka blommor till Darcy, servitrisen på Lakeshire Inn som skickade honom en gratis lunch. Det är en gest som visar både romantiskt intresse och tacksamhet.",al={"varför köpa blommor","vem är blommorna till","parkers motiv"}},{q="Varför vill Parker hålla köpet hemligt?",a="Lakeshire är en liten stad där alla känner varandra och nyheter sprids snabbt. Parker är blyg när det gäller att uppvakta Darcy och vill undvika skvaller från Martie Jainrose och de andra stadsborna.",al={"varför hemlighålla","varför dölja vem blommorna är till","berätta inte för martie"}},{q="Vad händer efter att du har pratat med Martie Jainrose?",a="Martie gör i ordning en bukett påskliljor. Därefter ska du leverera blommorna direkt till Darcy på Lakeshire Inn.",al={"what comes next","delivering daffodils","efter örtmästaren"}},{q="Var passar uppdraget in i uppdragskedjan?",a="Det här uppdraget länkar samman ”A Free Lunch”, där du lämnar lunch till Guard Parker, och ”Delivering Daffodils”, där du tar med blommorna tillbaka till Darcy.",al={"uppdragskedja","förutsättning","a free lunch-kedjan"}}},fx={["07240ec3"]={q="Varför ber Guard Parker dig besöka örtläkaren i stället för att gå själv?",a="Parker har tjänstgöring med att vakta vägarna i Redridge och kan inte bara överge sin post för att uträtta privata ärenden i staden. Än viktigare är att han skäms djupt över sina känslor för Darcy. Han vill särskilt hålla den romantiska gesten hemlig för Martie Jainrose och resten av Lakeshire, vilket vore omöjligt om någon såg honom köpa blommor själv.",al={"varför behöver parker mig","varför kan parker inte hämta blommorna själv","varför be mig besöka örtläkaren"}}},fp="19,121,24.278.0,31.392.0,37.124.0,34.93.0,35.127.0,46.118.0,46.85.1,39.155.1"}
P.entries["quest:1302"] = {n="James Hyal",s="\"James Hyal\" är ett alliansuppdrag om en mänsklig nybyggare som seglade till Kalimdor med Lady Jaina Proudmoores expedition. Efter att ha gett sig av för att öppna ett värdshus vid gränslandet tappade hans familj i Eastern Kingdoms kontakten med honom och söker nu besked om hans öde i Theramores administrativa register.",h="\"James Hyal\" är ett alliansuppdrag om en mänsklig nybyggare som seglade till Kalimdor med Lady Jaina...",kw={"clerk lendry","kock","värdshusvärd","jaina proudmoore","james hyal","kalimdor","theramore"},ang={["faction:Alliance"]="James seglade västerut tillsammans med Lady Jaina Proudmoore under det tredje kriget. Det visar hur personliga band knyter många alliansfamiljer över det Stora havet till Theramore Isle.",["profession:Cooking"]="Hemma var James känd som en ovanligt skicklig kock. Han reste till Kalimdor för att försörja sig på ett värdshus och servera resenärer."},sec={{t="Över det Stora havet",b="Under det tredje kriget lämnade otaliga själar sina förfäders hem i Eastern Kingdoms för att följa Lady Jaina Proudmoore över det Stora havet. Bland dem fanns James Hyal, som hans släkt mindes med värme som en skicklig kock. När striderna hade lagt sig och Theramore Isle hade grundats valde James att skapa sig en försörjning på den karga kontinenten Kalimdor genom att öppna ett eget värdshus för resenärer och nybyggare."},{t="På jakt efter en bror",b="Hemma i Eastern Kingdoms har James bror blivit orolig eftersom inga brev har kommit från andra sidan havet på sistone. Han hoppas att James bara är upptagen med att sköta en livlig vägkrog och ber resenärer att leta reda på honom. Första steget är att söka i Theramore, där Clerk Lendry ansvarar för de lokala registren och håller reda på expeditionsmedlemmar som har gett sig ut i vildmarken."}},faq={{q="Vem är James Hyal?",a="James Hyal är en mänsklig nybyggare och skicklig kock som reste över det Stora havet med Lady Jaina Proudmoores flotta. När striderna hade lagt sig sökte han en ny försörjning i Kalimdor och gav sig av för att öppna ett värdshus på kontinenten.",al={"vem är james hyal","james hyals bakgrund","vem är james"}},{q="Var hittar jag James Hyal?",a="James gav sig av för att öppna ett värdshus någonstans på kontinenten Kalimdor efter att ha anlänt med Lady Proudmoores expedition. Hans familj har inte hört från honom på sistone, men Clerk Lendry på Theramore Isle har hand om registren och kanske känner till hans exakta vistelseort.",al={"var finns james hyal","hitta james hyal","james hyals plats"}},{q="Vem är Clerk Lendry?",a="Clerk Lendry är en alliansämbetsman stationerad på Theramore Isle, med ansvar för stadens administration och frågor från invånarna. Resenärer som letar efter nybyggare som James Hyal hänvisas till Lendry för att söka i Theramores register.",al={"vem är clerk lendry","clerk lendrys plats","theramores skrivare"}},{q="Varför reste James till Kalimdor?",a="James seglade med Lady Jaina Proudmoores flotta under det tredje kriget som en del av människornas utvandring från Eastern Kingdoms. När de stora konflikterna hade lagt sig valde han att stanna och bygga ett värdshus för resenärer och nybyggare.",al={"varför reste james till kalimdor","james hyals expedition"}},{q="Vem letar efter James Hyal?",a="Förfrågan kommer från James bror i Eastern Kingdoms, som inte har hört av honom på ett tag. Brodern minns James som en skicklig kock och antar att han helt enkelt är upptagen med att öppna sitt nya värdshus.",al={"vem ger uppdraget om james hyal","vem är james bror"}},{q="Är James Hyal i fara?",a="Hans bror tror att James bara är upptagen med att driva sin nya verksamhet och antar att freden på kontinenten har låtit honom få det att gå bra. Men familjen har inte fått något direkt livstecken från honom på ett tag.",al={"är james hyal i säkerhet","vad hände med james hyal"}}},fp="10,300,20.416.0,22.438.0,18.233.0,28.252.0,20.226.0,33.225.0,30.217.0,28.210.0"}
P.entries["quest:131"] = {n="Delivering Daffodils",s="Delivering Daffodils avslutar ett litet ärende mellan vaktposten och torget i Lakeshire. Efter att ha hämtat lunch åt Guard Parker och en bukett hos örtakunniga Martie Jainrose lämnar du blommorna till Darcy på Lakeshire Inn, och hamnar genast mitt i en besvärlig lokal rivalitet.",h="Delivering Daffodils avslutar ett litet ärende mellan vaktposten och torget i Lakeshire.",kw={"daffodil bouquet","darcy","deliverering av påskliljor","guard parker","lakeshire","martie jainrose","redridge","stekt solfisk"},ang={["faction:Alliance"]="När du hjälper stadsvakten och värdshusvärden i Lakeshire stärker du civilbefolkningens moral medan staden kämpar mot anfall från Blackrock och gnoller.",["profession:Cooking"]="Darcy belönar leveransen med kryddad stekt solfisk, ett exempel på enkel hemlagad mat från Redridgesjöns strand.",["profession:Herbalism"]="Ärendet bygger på Martie Jainroses botaniska kunskap och hennes blick för färska blommor vid sjön, och visar örtinsamlingens fridfulla sida."},sec={{t="Ett väldoftande ärende",b="Det som började som en enkel tjänst, att leverera en varm måltid till Guard Parker, blir en finstämd romantisk gest. Tacksam för lunchen ber Parker dig hämta blommor hos Martie Jainrose som en överraskning åt Darcy, kocken som lagade maten. Martie ordnar en färsk bukett med sina egna favoritblommor, påskliljor, utan att veta vem som ska få dem."},{t="Rivalitet i byn",b="När du kommer tillbaka med buketten till Lakeshire Inn övergår Darcys första glädje snabbt i misstänksamhet. Hon känner igen påskliljorna som Marties personliga favorit och misstänker genast att Parker haft att göra med en kvinna som hon ser som en svartsjuk rival. Darcy oroar sig för att Martie skulle ha förgiftat stjälkarna av illvilja om hon hade känt till mottagaren, men fritar dig från skuld och ger dig en varm portion stekt solfisk som tack för besväret."}},faq={{q="Vem är Darcy?",a="Darcy arbetar på Lakeshire Inn i Redridge Mountains och lagar mat åt lokalbor och stadsvakter. Hon är kocken som skickade lunch till Guard Parker, vilket fick Parker att skicka tillbaka en blombukett som tack.",al={"darcy","vem är darcy i lakeshire","kocken darcy i lakeshire"}},{q="Vem är Martie Jainrose?",a="Martie Jainrose är Lakeshires örtakunniga invånare och blomsterentusiast. Guard Parker hänvisar dig till henne för att köpa en fin bukett, och Martie sätter glatt ihop en bukett med påskliljor och nämner att de råkar vara hennes favoritblommor.",al={"martie jainrose","örtakunnig i lakeshire","vem gav blommorna"}},{q="Varför är Darcy upprörd över påskliljorna?",a="Darcy känner genast igen påskliljorna som Marties favoritblomma. Hon ser Martie som en svartsjuk rival och är rädd att Martie skulle ha förgiftat stjälkarna om hon hade vetat att buketten var till Darcy.",al={"varför är darcy arg","darcy och marties fejd","varför förgiftades blommorna"}},{q="Förgiftade Martie faktiskt buketten?",a="Nej. Martie visste inte att blommorna var till Darcy. Parker bad dig bara hämta ett arrangemang, och Martie valde i förbifarten sina egna favoriter till buketten.",al={"är påskliljorna förgiftade","är buketten förgiftad"}},{q="Vilka uppdrag leder fram till leveransen?",a="Kedjan börjar med 'A Free Lunch', där du bär Darcys måltid till Guard Parker. Sedan ger Parker dig 'Visit the Herbalist' så att du kan köpa en gåva av Martie Jainrose, och kedjan avslutas med 'Delivering Daffodils'.",al={"uppdragskedja","krav för påskliljorna","kedjan deliverering av påskliljor"}},{q="Vilken belöning får du för att leverera blommorna?",a="Darcy tackar dig med en rejäl portion stekt solfisk, lite koppar och erfarenhet, samt förbättrat anseende hos kungariket Stormwind.",al={"uppdragsbelöning","belöningar för påskliljorna"}}},fx={["12ade65f"]={q="Varför vill Martie Jainrose att du lämnar över påskliljor till Darcy?",a="Martie Jainrose valde påskliljor helt enkelt för att de är hennes favoritblommor, utan att veta vem Parker tänkte ge dem till. Guard Parker bad dig hämta en bukett för att återgälda Darcys vänlighet, och Martie satte glatt ihop sina personliga favoriter till gesten. Det hon ser som ett vackert arrangemang uppfattar Darcy däremot genast som en förolämpning från en småaktig romantisk rival.",al={"varför påskliljor","martie jainroses motiv","varför skicka påskliljor"}}},fp="20,207,17.245.0,14.330.1,13.186.0,23.163.0,39.194.1,39.130.1,37.199.0,50.123.0"}
P.entries["quest:1319"] = {n="The Black Shield",s="Captain Garran Vimes beklagar att han inte kan hjälpa dig mycket med Blackened Iron Shield, men vet vem som kan göra mer: Caz Twosprocket, en av de bästa smederna i trakten, som sköter ässjan i smedjan i Theramore.",h="Captain Garran Vimes beklagar att han inte kan hjälpa dig mycket med Blackened Iron Shield, men vet vem som...",kw={"blackened iron shield","captain garran vimes","caz twosprocket","dustwallow marsh","den svarta skölden","theramore"},sec={{t="En smed med svar",b="Vimes ber om ursäkt för att han inte kan hjälpa till så mycket med skölden, men nämner någon som kan. Du får ta den till Caz Twosprocket, en av de bästa smederna, som sköter ässjan i smedjan i Theramore. Kanske kan Caz berätta något om den."},{t="Smedens utlåtande",b="Caz granskar järnet och kallar det ett intressant föremål. Det är inte Caz eget arbete, och definitivt inte gjort av någon smed som Caz känner till på den här sidan av vattnet."}},faq={{q="Vem skickar dig för att undersöka skölden?",a="Captain Garran Vimes i Theramore, som beklagar att han inte kan hjälpa mycket med den och hänvisar dig till någon bättre.",al={"vem ger den svarta skölden","starta uppdraget med svarta skölden","vem startar uppdraget med svarta skölden"}},{q="Vem är Caz Twosprocket?",a="En smed som sköter ässjan i smedjan i Theramore. Vimes räknar honom till de bästa.",al={"caz twosprocket","vem är smeden i theramore"}},{q="Vilken sköld visar du för Caz?",a="Blackened Iron Shield.",al={"blackened iron shield","vilken sköld ska jag visa caz"}}},fp="16,207,19.248.0,19.161.1,36.110.0,23.88.0,28.26.0"}
P.entries["quest:132"] = {n="The Defias Brotherhood",s="I Westfall bygger Defias Brotherhood upp ett nätverk som sträcker sig bortom röveri. Wiley the Black berättar om dess band till gnoller, kobolder och gobliner. Gryan Stoutmantle behöver uppgifterna för att förstå hela omfattningen av konspirationen som stryper Westfall.",h="I Westfall bygger Defias Brotherhood upp ett nätverk som sträcker sig bortom röveri.",kw={"defias brotherhood","gnoller","gobliner","gryan stoutmantle","kobolder","sentinel hill","westfall","wiley the black","wiley's note"},ang={["class:Rogue"]="Som skurk ser du hur Wiley the Black balanserar mellan laglös och användbar informatör, och hur kontakter i den undre världen förmedlar underrättelser under krigstid.",["faction:Alliance"]="För Alliansen visar samarbetet mellan mänskliga laglösa, gnoller och gobliner hur allvarligt säkerhetsvakuumet är vid Stormwinds västra gränser.",["race:Human"]="Som människa vet du att meddelandet bekräftar att banditerna som plundrar familjegårdar i Westfall och Redridge genomför en avsiktlig, samordnad kampanj."},sec={{t="Ett farligt meddelande",b="Wiley the Black säger att det kan kosta honom livet att berätta vad han vet om Defias. I trakterna kring Redridge och Westfall har han fått nys om en verksamhet långt större än stråtröveri. Hans förseglade meddelande beskriver hur Brotherhood har samordnat grupper som vanligtvis är fientligt inställda till varandra ute på landsbygden."},{t="Oväntade allianser",b="Wiley varnar för att Defias har byggt upp ett oroväckande nätverk omkring sig. De rödmaskerade laglösa har värvat gnollflockar, koboldgrävare och gobliningenjörer i stället för att arbeta ensamma. Tillsammans pekar deras brutala styrka, grävarbete och mekaniska slughet på en verksamhet långt större än vad People's Militia först hade väntat sig."},{t="Stoutmantles motvilliga förtroende",b="Gryan Stoutmantle hyser föga kärlek till Wiley och beklagar öppet att han inte lät skurken ruttna i fängelse när han hade chansen. Men Westfall har inte råd med stolthet. När Stormwind ignorerar vädjanden om militär hjälp måste People's Militia ta emot användbar information var den än kommer ifrån."}},faq={{q="Vad handlar Wiley's Note om?",a="Wiley the Blacks meddelande varnar för att Defias Brotherhood samarbetar med gnoller, kobolder och gobliningenjörer. Det upplyser People's Militia om att de laglösa förbereder en operation som går långt bortom småskaligt röveri.",al={"wiley's note","vad står i meddelandet","meddelande från wiley the black"}},{q="Vem är Wiley the Black?",a="Wiley the Black är en skum kontakt som håller till i Lakeshire i Redridge. Gryan Stoutmantle ser honom som en opålitlig skurk, men Wiley har omfattande kontakter i den undre världen och viktig information om Defias verksamhet.",al={"vem är wiley","wiley the black berättelse","wiley i lakeshire"}},{q="Varför skulle Defias liera sig med gnoller och kobolder?",a="Defias använder lokala varelser för att kontrollera områden och få billig arbetskraft. Gnoller fungerar som brutala skärmytslare som distraherar försvararna, kobolder gräver tunnlar i traktens gruvor och goblinmekaniker bidrar med tunga maskiner och sprängverktyg.",al={"varför använder defias gnoller","kobolder och defias","defias allierade"}},{q="Varför ogillar Gryan Stoutmantle Wiley?",a="Gryan Stoutmantle är en disciplinerad före detta soldat som ser Wiley som en vanlig ficktjuv och brottsling. Han ångrar att han skonade Wiley från fängelset, trots att Wileys kontakter i den undre världen är oumbärliga.",al={"stoutmantle och wiley","varför ogillar de wiley"}},{q="Hur passar det här meddelandet in i milisens utredning?",a="Wileys meddelande för milisens utredning från lokal spaning vidare mot den djupare Defias-konspirationen. När det återvänder får Stoutmantle anledning att undersöka konspirationens ledare och samlingsplatser.",al={"steg i defias uppdragskedja","vilket uppdrag är det här"}},{q="Varför hanterar inte Stormwind det här hotet?",a="Med kung Varian Wrynn försvunnen vägrar Stormwinds adelsråd att omdirigera kungliga soldater eller anslag för att försvara Westfall. Stoutmantles brokiga People's Militia får ensam försvara regionen.",al={"stormwind hjälper westfall","var finns vakterna"}}},fx={["3bfb9fad"]={q="Varför skickar Wiley the Black dig till Gryan Stoutmantle?",a="Wiley vet att Defias Brotherhood planerar något katastrofalt. Han har pusslat ihop rykten om att de samarbetar med gnoller, kobolder och gobliner. Han förstår att hans eget liv står på spel när han känner till sådana farliga hemligheter. Genom att skriva ner sin kunskap i ett förseglat meddelande till Gryan Stoutmantle överlåter Wiley ansvaret för att agera till The People's Militia. På så sätt gör han sin del för att stoppa sammansvärjningen och håller sig själv utanför farozonen.",al={"varför hjälper wiley","wiley the blacks motiv","varför skicka wileys meddelande"}},["6813809b"]={q="Varför förlitar sig Wiley på dig i stället för att lämna över meddelandet själv?",a="Wiley är en kriminell skurk som håller låg profil på värdshuset i Lakeshire, långt från både myndigheternas och Defias vaksamma ögon. Om han färdades hela vägen genom fientligt territorium till Westfall skulle han utsätta sig för stor fara, och hans tidigare historia med Gryan Stoutmantle gör honom avskydd snarare än välkommen. Du är en pålitlig kurir som kan ta dig obemärkt genom vildmarken och lämna varningen direkt vid Sentinel Hill.",al={"varför behöver wiley dig","varför kan wiley inte åka till westfall","varför jag ska bära wileys meddelande"}}},fp="22,190,20.216.0,18.318.0,29.235.0,27.217.0,23.229.0,50.238.0,41.187.0,61.203.0,41.193.0"}
P.entries["quest:1320"] = {n="The Black Shield",s="Caz Twosprocket granskar den svarta skölden i mysteriet kring Shady Rest Inn och missar nästan en sista detalj. Caz skickar dig till Captain Garran Vimes i Theramore med det som hittats.",h="Caz Twosprocket granskar den svarta skölden i mysteriet kring Shady Rest Inn och missar nästan en sista...",kw={"svart sköld","caz twosprocket","dustwallow marsh","garran vimes","shady rest inn","tauren","theramore"},sec={{t="Ett avbränt remfäste",b="När Caz Twosprocket granskar den svarta skölden missar Caz nästan en sista detalj: läderremmen på baksidan har bränts bort, men verkar ha varit gjord för en stor person. Caz gissar på en tauren. Det är allt Caz kan säga, och du skickas till Captain Garran Vimes i Theramore med beskedet och med Caz ursäkt för att inte kunna hjälpa mer."},{t="Vad Vimes drar för slutsats",b="Vimes tycker att det här ger få ledtrådar, men säger att det ska finnas i åtanke. Förhoppningen är att andra delar av mysteriet faller på plats och visar tydligare vad som hände."}},faq={{q="Vad får Caz Twosprocket reda på om skölden?",a="Läderremmen på baksidan har bränts bort, men verkar ha varit gjord för en stor person. Caz gissar på en tauren.",al={"caz fynd","sköldledtrådar","ledtråd om svart sköld"}},{q="Vem ska få höra vad Caz hittade?",a="Captain Garran Vimes i Theramore.",al={"vem ska jag berätta om skölden för","lämna in svart sköld","var rapporterar jag skölden"}}},fp="16,186,19.337.0,22.202.1,52.128.0,31.34.0"}
P.entries["quest:1321"] = {n="The Black Shield",s="Krog granskar Blackened Iron Shield men ser inget ovanligt. Han föreslår att smeden Do'gol undersöker den, fast utan större hopp, och skickar dig till Brackenwall Village.",h="Krog granskar Blackened Iron Shield men ser inget ovanligt.",kw={"svarta skölden","blackened iron shield","brackenwall village","do'gol","dustwallow marsh","krog"},sec={{t="En andra bedömning",b="Krog ser inget ovanligt med skölden. Smeden Do'gol kanske kan säga mer om den, säger Krog, men varnar dig för att inte hoppas på för mycket. Do'gol finns i Brackenwall Village."},{t="Do'gols svar",b="Do'gol kallar den en bra sköld, stark och tung. Han behöver den dock inte, eftersom han tillverkar sköldar i stället för att köpa dem, och säger att du borde förstå det."}},faq={{q="Vem skickar dig till Do'gol med skölden?",a="Krog, som granskade Blackened Iron Shield och inte fann något ovanligt med den.",al={"vem ger uppdraget med den svarta skölden","var börjar jag uppdraget med den svarta skölden","uppdragsgivare för svarta skölden"}},{q="Var finns Do'gol?",a="Do'gol är smeden i Brackenwall Village.",al={"dogols plats","var finns dogol","hitta dogol"}},{q="Varför skickar Krog dig till Do'gol?",a="Krog hoppas att smeden kan säga mer om skölden, men tror inte att det kommer att leda till särskilt mycket.",al={"varför besöka dogol","varför visa skölden för smeden"}}},fp="16,193,16.183.0,15.155.1,40.83.0,26.48.0,33.105.0"}
P.entries["quest:1322"] = {n="The Black Shield",s="I Brackenwall Village har Do'gol lagt märke till skrift längs sköldens kant, men brända rester döljer den. För att få bort dem behövs syra, och Do'gol ber dig hämta sex giftsäckar från träskets Darkfang-spindlar.",h="I Brackenwall Village har Do'gol lagt märke till skrift längs sköldens kant, men brända rester döljer den.",kw={"sura giftsäckar","brackenwall village","darkfang","do'gol","dustwallow marsh","the black shield"},sec={{t="Rengör kanten",b="Do'gol kan se skrift runt sköldens kant, men den fastbrända smutsen gör den svår att läsa. Syra skulle få bort den, och träskets Darkfang-spindlar bär på ett gift som fungerar bra. Do'gol vill ha sex av deras sura giftsäckar för att rengöra skölden."},{t="När giftsäckarna kommer",b="Do'gol tycker illa om spindlar som är för stora för att kunna sitta på och mosa, och tackar dig sedan för giftsäckarna. Do'gol sliter upp dem och häller innehållet över skölden."}},faq={{q="Vem ber om spindelgiftet?",a="Do'gol i Brackenwall Village.",al={"vem ger black shield","dogols uppdrag","vem startar black shield"}},{q="Varför behöver Do'gol giftsäckar?",a="Do'gol behöver syra för att få bort de brända resterna som döljer skriften på sköldens kant, och gift från Darkfang-spindlar duger.",al={"varför spindelsyra","syftet med sura giftsäckar","varför rengöra skölden"}},{q="Varifrån kommer de sura giftsäckarna?",a="Från Darkfang-spindlarna som lever i träsket nära Brackenwall Village.",al={"vilka spindlar har giftsäckar","var finns darkfang-spindlar","var hittar man surt gift"}},{q="Hur många säckar vill Do'gol ha?",a="Sex sura giftsäckar.",al={"hur många giftsäckar"}}},fp="16,209,16.249.0,20.149.1,30.31.0,32.120.0,41.74.0,31.22.0"}
P.entries["quest:1323"] = {n="The Black Shield",s="Do'gol har gnuggat skölden tillräckligt ren för att se något som verkar stava Mosarn, ett namn som inte säger Do'gol något. Krog i Brackenwall Village känner många, så Do'gol skickar dig dit för att fråga.",h="Do'gol har gnuggat skölden tillräckligt ren för att se något som verkar stava Mosarn, ett namn som inte säger...",kw={"syra","svart sköld","brackenwall village","do'gol","dustwallow marsh","krog","mosarn"},sec={{t="Ett namn på kanten",b="Do'gol använde lite för mycket syra, men efter lite gnuggande framträder en text som fortfarande är svår att läsa och verkar säga Mosarn. Namnet säger Do'gol ingenting. Krog i Brackenwall Village känner många, så Do'gol skickar dig för att tala med Krog."},{t="Krogs svar",b="Krog tycker att namnet Mosarn låter bekant men kan inte placera det, och hoppas att det ska komma tillbaka senare. Krog tillägger att det troligen inte spelar någon roll, eftersom sköldar dyker upp från alla möjliga platser och inte betyder något."}},faq={{q="Vem är Do'gol?",a="Personen i Brackenwall Village som har rengjort skölden med syra för att läsa skriften.",al={"dogol","vem ger den svarta skölden"}},{q="Vilket namn står på skölden?",a="Do'gol tycker att skriften säger Mosarn, även om den är svår att läsa, och har aldrig hört talas om någon med det namnet.",al={"vilket namn står på skölden","vem är mosarn","namn i sköldens inskrift"}},{q="Varför prata med Krog om skölden?",a="Do'gol vet inte vem Mosarn är, men säger att Krog känner många.",al={"varför prata med krog","vem är krog"}},{q="Var finns Krog?",a="Krog är i Brackenwall Village.",al={"krogs plats","var hittar jag krog"}}},fp="16,196,17.249.0,13.204.1,14.94.0,27.111.0,34.68.0,22.31.0"}
P.entries["quest:133"] = {n="Ghoulish Effigy",s="Djupt inne i Duskwoods dystra vildmark hävdar den excentriske eremiten Abercrombie att hans avskilda hydda belägras av de levande döda. För att skydda sitt hem ber han förbipasserande äventyrare samla ghoulrevben till en bisarr skyddsfågelskrämma.",h="Djupt inne i Duskwoods dystra vildmark hävdar den excentriske eremiten Abercrombie att hans avskilda hydda...",kw={"abercrombie","bone chewers","darkshire","duskwood","avbild","flesh eaters","ghoul rib","eremit"},ang={["class:Paladin"]="Att jaga Flesh Eaters och Bone Chewers renar Duskwoods jord från plågan, även om det känns obehagligt att lämna deras kvarlevor till en eremit.",["class:Priest"]="Att hjälpa en skräckslagen eremit som är strandsatt bland mörka andar är ett ädelt uppdrag, även om det sätter magen på prov att sätta ihop avbilder av insamlade kvarlevor.",["faction:Alliance"]="Night Watch kämpar för att skydda vägarna, så isolerade skogsbor som Abercrombie måste förlita sig på förbipasserande Alliance-resenärer för att få skydd mot de rastlösa döda."},sec={{t="En eremits belägenhet",b="Abercrombie bor långt bortom Darkshires bevakade gränser, avskild bland Duskwoods skuggiga träd. Här ute strövar kringirrande gastar som Flesh Eaters och Bone Chewers fritt omkring. Han hävdar att glupska lik nyligen slog sönder hans väggar, och den panikslagne eremiten ber om revben från dessa fasor för att skapa ett avskräckande skydd. Han hoppas att en makaber avbild ska hålla de hungriga döda på avstånd."},{t="Ett bisarrt försvar",b="Sunt förnuft kanske säger att han borde söka sig till Night Watch i säkerhet eller befästa sin träkoja, men Abercrombie insisterar på makabra metoder. Han tror att en avbild gjord av gastrester ska skrämma bort andra döda som letar efter as. Även om det känns obehagligt att bygga en fågelskrämma av slaktade odöda tar resande i Duskwood ofta den excentriske eremiten på orden för att tjäna välbehövliga mynt."}},faq={{q="Var bor Abercrombie?",a="Abercrombie bor i en enslig hydda i västra Duskwood, strax nordost om Raven Hill Cemetery och långt från Darkshires beskydd.",al={"abercrombies plats","var ligger abercrombies hydda","eremitens hydda i duskwood"}},{q="Varför behöver Abercrombie ghoulrevben?",a="Abercrombie hävdar att flockar av gastar bankar på väggarna till hans hydda. Han tänker använda benen till att skapa en otäck fågelskrämmeavbild som ska skrämma bort odöda som letar efter as.",al={"ghoulrevbenens syfte","varför ghoulrevben","vad är avbilden till för"}},{q="Vilka varelser lämnar Ghoul Rib efter sig?",a="Revbenen kan samlas in från alla lokala odöda som strövar längs Duskwoods vägar och på dess kyrkogårdar, närmare bestämt Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones och Plague Spreaders.",al={"var hittar man revben","vilka lämnar ghoul rib efter sig","vilka gastar lämnar revben efter sig"}},{q="Skrämmer en fågelskrämma av odöda verkligen bort gastar?",a="Odöda blir sällan rädda, så Abercrombies plan verkar tvivelaktig för erfarna monsterjägare. Ändå insisterar eremiten på sitt märkliga projekt, och få ifrågasätter en arbetsgivare som betalar i en så farlig vildmark.",al={"fungerar avbilder mot gastar","tanken bakom gastfågelskrämman"}},{q="Varför flyttar Abercrombie inte bara till Darkshire?",a="Abercrombie väljer att leva avskilt, långt från Night Watch och stadens styre. Trots de uppenbara farorna i Duskwoods vildmark föredrar han att sköta sin hydda ensam med sina egna egendomliga försvar.",al={"varför bo i skogen","varför flyttar inte abercrombie","trygghet i darkshire"}},{q="Vad händer efter att revbenen har samlats in?",a="När Abercrombie har fått ghoulrevbenen hittar han ännu ett bisarrt problem att lösa och skickar äventyrare längre ut i vildmarken för att ta hand om lokala ogres som stulit hans tillhörigheter.",al={"nästa uppdrag","vad händer efter ghoulish effigy"}}},fx={d0d16021={q="Vad används Ghoul Ribs till?",a="Abercrombie hävdar att han behöver revben från lokala gastar för att bygga en kuslig avbildning, ett odött fågelskrämma, som ska stå utanför hans avlägsna skjul. Han bor långt utanför Darkshires trygga gränser och insisterar på att den groteska skapelsen ska skrämma bort de köttätande fasor som stryker omkring utanför väggarna.",al={"vad används ghoul ribs till","användning av ghoul rib","varför samla ghoul ribs"}},["0ad10362"]={q="Varför behöver Abercrombie att du samlar in revbenen?",a="Abercrombie är en excentrisk och skör eremit som är strandsatt ute i skogen och inte tycker om Darkshire eller dess Night Watch. Han är skräckslagen för gastarna som bankar på skjulväggarna och saknar styrkan att själv möta de ruttnande fasorna. Därför är han beroende av förbipasserande äventyrare som är villiga att riskera farorna i Duskwood för pengar.",al={"varför be mig","varför gör inte abercrombie det själv","varför inte be night watch"}},cd024384={q="Varför strövar gastar omkring i Duskwood?",a="Den annalkande skugga som slukade regionen och omslöt den i evig skymning störde också de döda. Rastlösa odöda, från glupska Bone Chewers till köttätande gastar, reser sig nu i mörkret och på kyrkogårdarna. De stryker genom de förfallna skogarna och jagar obevekligt varje levande själ som är dum nog att lämna de befästa bosättningarna.",al={"varför finns det gastar här","gastar i duskwood","var kommer gastarna ifrån"}}},fp="15,150,17.329.0,17.300.0,28.133.0,37.158.0,36.153.0,56.163.0,53.180.0,41.161.0"}
P.entries["quest:1338"] = {n="Stormpike's Order",s="I Loch Modan beställer Mountaineer Stormpike en sköld av Furen Longbeard. Rustningssmeden arbetar långt söderut i Stormwind City, så Stormpike ber en resenär att ta med hans beställning dit.",h="I Loch Modan beställer Mountaineer Stormpike en sköld av Furen Longbeard.",kw={"rustningssmed","dwarven district","furen longbeard","ironforge","loch modan","sköld","stormpike","stormwind"},ang={["faction:Alliance"]="Som resenär i Alliansen kan du se handels- och kulturbanden mellan dvärgarnas fästen i Khaz Modan och Stormwind, som Deeprun Tram knyter samman.",["profession:Blacksmithing"]="Som smed kan du lägga Furen Longbeard på minnet. Han är en enastående rustningssmed som är känd även i andra kungariken, och du färdas genom Stormwind.",["race:Dwarf"]="Som dvärg ser du hur långt en klans rykte kan nå. Stormpikes beställning väcker också frågan varför en mästerlig rustningssmed skulle välja människornas sten framför Ironforge."},sec={{t="En sköld värd resan",b="Mountaineer Stormpike vill ha en ny sköld och litar bara på att Furen Longbeard kan smida den. Bergsryttaren är villig att betala bra för att överlämna beställningen till smeden, trots att Loch Modan och Stormwind City ligger långt ifrån varandra."},{t="Från Ironforge till Dwarven District",b="Stormpike undrar varför Furen arbetar så långt från Ironforge och Great Forge, där många dvärgar bor. Han misstänker att människorna i Stormwind betalar smeden en kunglig förmögenhet. När beställningen når Furen vid hans städ är rustningssmeden stolt över att höra från den ansedda Stormpike-klanen och förbereder ivrigt arbetet med att smida skölden."}},faq={{q="Vem är Mountaineer Stormpike?",a="Mountaineer Stormpike är en vaktpost i Alliansen som är stationerad i Loch Modan. Han tillhör den stolta och inflytelserika Stormpike-klanen och tjänstgör bland dvärgarnas bergsryttare, som skyddar bergspassen och dalarna.",al={"mountaineer stormpike","vem ger uppdraget","uppdragsgivare"}},{q="Vem är Furen Longbeard?",a="Furen Longbeard är en skicklig dvärgisk rustningssmed som bor i Dwarven District i Stormwind City. Hans rykte om att smida utmärkta sköldar och rustningar har nått norrut till Khaz Modan.",al={"furen longbeard","vem är furen","rustningssmeden"}},{q="Varför bor Furen i Stormwind i stället för Ironforge?",a="Furen Longbeard arbetar i Dwarven District i Stormwind, där han betjänar mänskliga adelsmän, stadsvakter och äventyrare på genomresa. Mountaineer Stormpike undrar varför en mästerlig dvärg skulle lämna Ironforge, men Furen tjänar troligen bra med människornas mynt.",al={"varför är furen i stormwind","varför dwarven district","furen lämnar ironforge"}},{q="Vilken roll spelar Deeprun Tram när beställningen levereras?",a="Resenärer som bär Stormpikes meddelande färdas vanligtvis västerut från Loch Modan till Ironforge och tar sedan Deeprun Tram genom tunneln till Dwarven District i Stormwind City, där Furens smedja ligger.",al={"resa till stormwind","hur tar man sig till stormwind","deeprun tram"}},{q="Vad händer före det här uppdraget?",a="Innan Mountaineer Stormpike anförtror dig leveransen till Stormwind prövar han ditt mod och din pålitlighet i Loch Modan med ”Mountaineer Stormpike's Task”.",al={"förkunskapskrav","föregående uppdrag","mountaineer stormpike's task"}},{q="Smider Furen Longbeard skölden genast?",a="När Furen Longbeard får brevet och inser vilken prestige Stormpike-namnet har, åtar han sig beställningen och lovar att börja hamra ut skölden före dagens slut.",al={"vad händer sedan","uppföljningsuppdrag","furens reaktion"}}},fx={["317873dc"]={q="Varför vill Mountaineer Stormpike att det här görs?",a="Mountaineer Stormpike behöver en ny sköld och har mycket höga tankar om Furen Longbeards hantverk. Han anser att smedens skicklighet saknar motstycke. Stormpike begriper inte varför en mästersmed bland dvärgarna skulle bo så långt bort bland människorna i Stormwind i stället för nära Ironforge, men han tänker inte nöja sig med sämre skydd. Han insisterar på att få en sköld smidd av Furen själv.",al={"varför behöver stormpike en sköld","mountaineer stormpikes motiv","varför beställa från furen"}},["02c191af"]={q="Varför ber Mountaineer Stormpike dig i stället för att gå själv?",a="Som aktiv Mountaineer posterad i Loch Modans höga bergspass kan Stormpike inte överge sin post där han vaktar dvärgarnas gränsland för att färdas söderut till människornas länder. Att leverera en beställning till Dwarven District i Stormwind kräver en lång resa, så han vänder sig till resande äventyrare med tid över och vilja att bära hans brev mot skälig betalning.",al={"varför skicka en äventyrare till furen","varför kan inte stormpike lämna beställningen","varför jag ska bära stormpikes beställning"}}},fp="17,152,26.173.0,38.326.0,29.208.0,23.180.0,54.242.0,57.195.0,29.160.0,50.191.0"}
P.entries["quest:1339"] = {n="Mountaineer Stormpike's Task",s="Mountaineer Stormpike's Task är ett kort kuriruppdrag för Alliansen i Loch Modan. Mountaineer Kadrell hänvisar kringvandrande äventyrare till det norra vakttornet, där Mountaineer Stormpike behöver en pålitlig budbärare för ett uppdrag långt bortom dalen. Det är början på ett längre ärende som sträcker sig in i grannländerna.",h="Mountaineer Stormpike's Task är ett kort kuriruppdrag för Alliansen i Loch Modan.",kw={"vakttorn","ironforge","loch modan","mountaineer kadrell","mountaineer stormpike","budbärare","stormpike's order","thelsamar"},ang={["faction:Alliance"]="När du tar kuriruppdrag åt bergsvakterna i regionen hjälper du till att hålla Ironforges garnisoner försörjda och samordnade i de östra territorierna.",["race:Dwarf"]="Att hjälpa en annan dvärg från den berömda Stormpike-linjen är en naturlig plikt för varje vandrare som värnar om klanbanden i Khaz Modan."},sec={{t="En vaktpost behöver en budbärare",b="Patrulleringen av vägarna och utposterna i Loch Modan gör att bergsvakterna får kämpa med begränsade styrkor mot trogginvasioner och kringströvande vilda djur. Mountaineer Kadrell hänvisar ofta dugliga resenärer till vakter som inte kan lämna sina poster. Mountaineer Stormpike, som är stationerad högt uppe i det norra vakttornet, är bunden av sina vaktsysslor just när ett brådskande privat ärende kräver att en budbärare reser långt bortom regionens gränser."},{t="Från tornet till avlägsna vägar",b="För att nå Stormpike måste du ta dig upp i det norra vakttornet med utsikt över dalen. Som medlem av den framstående Stormpike-klanen sträcker sig hans ärenden ofta bortom Thelsamars vardagliga gränsförsvar. Om du åtar dig hans uppdrag går du med på att på hans vägnar föra meddelanden och förnödenheter över regiongränserna. Det blir unga äventyrares första stora steg ut ur sjöområdet och ut på Khaz Modans större landsvägar."}},faq={{q="Var hittar jag Mountaineer Stormpike?",a="Mountaineer Stormpike är stationerad högst upp i det norra vakttornet i Loch Modan och håller uppsikt över stigarna i området.",al={"stormpikes plats","var är stormpike","hitta stormpikes torn"}},{q="Vem inleder det här uppdraget?",a="Mountaineer Kadrell, som patrullerar kring Thelsamar i Loch Modan, inleder uppdraget genom att hänvisa dig till Stormpikes torn.",al={"vem ger mountaineer stormpikes uppdrag","uppdragsgivare","kadrells plats"}},{q="Varför behöver Stormpike en äventyrare?",a="Som aktiv bergsvakt kan Stormpike inte lämna sin post i tornet. Hans personliga ärende kräver en resa långt utanför Loch Modan, så en äventyrare utan andra åtaganden passar utmärkt som kurir.",al={"varför behövs en budbärare","stormpikes problem","vad vill stormpike"}},{q="Vad händer efter att jag rapporterat till Stormpike?",a="När du talar med Stormpike slutför du det här inledande steget och låser upp hans fortsättningsuppdrag, 'Stormpike's Order', som skickar dig på en leverans till ett annat område.",al={"nästa uppdrag","vad händer efter mountaineer stormpikes uppdrag","stormpikes fortsättningsuppdrag"}},{q="Har det här något samband med Stormpike Guard i Alterac?",a="Mountaineer Stormpike delar namn och blod med den berömda Stormpike-klanen, känd för Stormpike Guard och sina gruvexpeditioner, men just det här uppdraget är ett enkelt lokalt ärende.",al={"stormpike-klanens koppling","stormpike i alterac valley","är det här av-stormpikes"}},{q="Har Horde-spelare ett motsvarande uppdrag här?",a="Nej. Loch Modan är självständigt dvärgterritorium som helt står på Alliansens sida, och bergsvakterna attackerar Horde-resenärer så fort de får syn på dem.",al={"horde-version","kan horde göra det här"}}},fx={d38a276d={q="Varför vill Mountaineer Kadrell att det här ska göras?",a="Mountaineer Kadrell håller helt enkelt utkik och fungerar som kontaktperson för sina medvakter. Han är posterad längs vägen och vet att Mountaineer Stormpike behöver en duglig budbärare för ett avlägset uppdrag som vakter i tjänst inte kan lämna sina poster för att utföra. När Kadrell får syn på en kapabel resenär för han vidare beskedet, så att Stormpike kan få den hjälp han behöver.",al={"varför skickar kadrell dig till stormpike","mountaineer kadrells motiv","varför prata med stormpike"}}},fp="28,185,30.320.0,27.323.0,38.115.0,22.96.0,38.140.0,42.141.0,50.168.0,47.116.0"}
P.entries["quest:134"] = {n="Ogre Thieves",s="Abercrombie, den säregne eremiten i västra Duskwood, ber resande ta sig till Vul'Gol Ogre Mound. Han säger att ogres överföll honom när han samlade föda och stal en låda med oersättliga örter och verktyg.",h="Abercrombie, den säregne eremiten i västra Duskwood, ber resande ta sig till Vul'Gol Ogre Mound.",kw={"abercrombie","låda","duskwood","eremit","ogre","vul'gol"},ang={["class:Paladin"]="Abercrombies ivriga, hemlighetsfulla glädje över att få tillbaka lådan bör få alla som tjänar det Heliga Ljuset att vara på sin vakt innan de hjälper den tillbakadragne eremiten utan eftertanke.",["class:Warlock"]="Häxmästare som känner till förbjudna konster inser lätt att Abercrombies felsägning hyllar mörk magi, inte enkel entusiasm över växter.",["profession:Herbalism"]="Abercrombie hävdar att lådan bara innehåller örter, men en örtkännare kan undra vilken sorts märkliga växter som kräver så desperat hämtning från en ogrehög."},sec={{t="En eremits förlorade ägodelar",b="Avsides längs de fuktiga vägarna i västra Duskwood hävdar den åldrade eremiten Abercrombie att han blev angripen när han samlade förnödenheter ute i vildmarken. Enligt honom drev råbarkade varelser från den södra ogrehögen bort honom och tvingade honom att överge en stadig trälåda full av dyrbara örter och ömtåliga instrument."},{t="Hotet från Vul'Gol",b="Vul'Gol Ogre Mound i södra Duskwood är ett befäst näste för fientliga ogres som trakasserar oförsiktiga vandrare. Lådan står precis vid ingången till deras väldiga håla och lockar främlingar att ta sig förbi rytande råskinn och magiker som väver besvärjelser för att bära tillbaka den till eremiten."},{t="En felsägning",b="När han får tillbaka sina förlorade ägodelar brister Abercrombies excentriska fasad i manisk upphetsning. Han hejdar sig när han nästan ropar ut sitt lov till ”Nec—”, skyndar sig sedan att tacka äventyraren i stället och vill genast stänga in sig för att använda förnödenheterna i mörkret."}},faq={{q="Vem är Abercrombie?",a="Abercrombie är en excentrisk enstöring som bor i en sliten koja i västra Duskwood. Han verkar skröplig och hjälplös och tycks behöva hjälp, men hans hetsiga beteende och märkliga önskemål antyder mörkare och oroande motiv.",al={"abercrombies bakgrund","vem gav mig uppdraget","vem är eremiten"}},{q="Vart tog ogres Abercrombies låda?",a="Lådan fördes till Vul'Gol Ogre Mound i södra Duskwood. Den står oskyddad på marken precis utanför ogrehålans mynning.",al={"var finns lådan","lådans plats","vul'gol-lådan"}},{q="Varför finns det ogres i Duskwood?",a="Ogrerna i Vul'Gol-klanen har skapat sig ett fäste i de karga kullarna i södra Duskwood. De är aggressiva och opportunistiska och plundrar regelbundet förbipasserande, överfaller ensamma vandrare och samlar stöldgods kring sin hög.",al={"ogres i duskwood","vul'gol-ogres ursprung","varför finns ogres här"}},{q="Vad finns egentligen i lådan?",a="Abercrombie säger att lådan innehåller sällsynta örter och särskilda skörderedskap som han övergav under angreppet. Han är överlycklig över att ha fått tillbaka dem.",al={"vad förlorade abercrombie","lådans innehåll"}},{q="Vad höll Abercrombie nästan på att säga när han fick lådan?",a="När Abercrombie får tillbaka lådan börjar han tacka någon annan, men hejdar sig plötsligt och tackar i stället äventyraren. Sedan ser han glatt fram emot nätterna som väntar.",al={"tacka nec","vad sade abercrombie","abercrombies citat"}},{q="Har uppdraget koppling till andra ärenden vid ogrehögen?",a="Äventyrare som reser till Vul'Gol Ogre Mound kan också samla ogremonokler åt Viktori Prism'Antras.",al={"uppdrag vid ogrehögen","uppdrag nära vulgol"}}},fx={["7ac39a32"]={q="Varför vill Abercrombie ha tillbaka sin låda?",a="Abercrombie påstår att han samlade växter långt från sin koja när ogres överföll honom och tvingade honom att överge en samling sällsynta örter och ömtåliga verktyg. För en isolerad eremit som bor vid kyrkogårdens utkant är det nästan omöjligt att skaffa ersättningar på egen hand. Men hans starka oro och desperata lättnad när lådan återlämnas antyder att innehållet tjänar ett betydligt mer ondskefullt syfte än vanlig örtmedicin.",al={"varför hämta lådan","abercrombies motiv med lådan","varför vill han ha lådan"}},["1d020e8a"]={q="Vilka är ogres som håller lådan?",a="Tjuvarna tillhör Vul'Gol-ogrerna, råbarkade utstötta som har huggit ut en vidrig kulle bland klipporna i södra Duskwood. De är kända för att plundra resenärer längs de mörka stigarna. De stötte på Abercrombie när han strövade utanför sina vanliga marker, drev bort den gamle eremiten och släpade tillbaka hans last till sitt näste tillsammans med annat byte.",al={"vem tog lådan","vul'gol-ogrer","duskwoods ogres och lådan"}},["504b8e87"]={q="Varför ber Abercrombie dig i stället för Night Watch?",a="Abercrombie är en bräcklig och folkskygg eremit som varken har styrkan att konfrontera ett läger med väldiga råskinn eller något gott förhållande till Darkshire. Misstänksamma stadsbor och den överansträngda Night Watch håller sig på avstånd från hans skjul och bevakar bara huvudvägarna och stadens utkanter. Eftersom eremiten inte kan lita på de lokala myndigheterna är han beroende av resande äventyrare som vågar trotsa farorna vid Vul'Gol Ogre Mound.",al={"varför fråga mig","varför inte night watch","varför behöver abercrombie hjälp"}}},fp="12,193,21.258.0,18.190.0,20.264.1,19.202.0,45.143.0,32.211.0,34.145.1,57.170.1,57.100.0"}
P.entries["quest:135"] = {n="The Defias Brotherhood",s="I Westfall når Defias Brotherhoods bekymmer Stormwind. Gryan Stoutmantle skickar dig för att överlämna Wiley's Note till Master Mathias Shaw och misstänker ett samband mellan Defias och det gamla Stonemasons Guild.",h="I Westfall når Defias Brotherhoods bekymmer Stormwind.",kw={"brödraskap","defias","gryan stoutmantle","mathias shaw","old town","si:7","stonemasons","westfall","wiley's note"},ang={["class:Rogue"]="På SI:7:s högkvarter träffar du Mathias Shaw, Stormwinds mästare över skurkar och spioner. Hans arbete knyter samman oron i Westfall med ett större nät av underrättelseverksamhet.",["faction:Alliance"]="Som medlem av Alliansen ser du sprickor i Alliansens främsta kungarike. Vissa hot kommer från förrådda medborgare, inte monstruösa främlingar.",["race:Human"]="Som människa från Stormwind ser du Westfalls laglösa gränsland möta de bittra, olösta politiska skandaler som följde på återuppbyggnaden av din huvudstad."},sec={{t="En felsägning",b="Ett omnämnande av Stonemasons i Wiley's meddelanden fångar Gryan Stoutmantles uppmärksamhet. Byggarna återuppbyggde Stormwind City efter det första kriget, men man har länge trott att gillet skingrats eller upplösts. Om Defias Brotherhood har band till dem är Westfalls uppror på landsbygden mer än ett oorganiserat band fredlösa."},{t="Hemligheter i Old Town",b="Från Sentinel Hill kan Gryan Stoutmantle inte bekräfta sina misstankar. Han skickar dig till Master Mathias Shaw, chef för Stormwinds hemliga underrättelsegren, SI:7. Shaw arbetar från kasernen i Old Town och samlar rykten och hemligheter från hela riket. Han kanske kan reda ut Defias Brotherhoods ursprung."},{t="Skuggan över kronan",b="Wiley's Note väcker allvarlig oro hos Master Mathias Shaw: upproret i Westfall har djupare rötter och är politiskt mer komplicerat än Gryan Stoutmantle förstår. Shaw pekar på Stormwinds egen turbulenta historia."}},faq={{q="Varför skickar Gryan Stoutmantle dig till Stormwind?",a="Ett omnämnande av Stonemasons i Wiley's Note får Gryan Stoutmantle att misstänka politiska intriger bakom röveriet. Han skickar dig till Master Mathias Shaw för att bekräfta sambandet.",al={"varför till stormwind","varför stormwind-uppdraget","stoutmantles ärende till stormwind"}},{q="Vem är Mathias Shaw?",a="Master Mathias Shaw leder SI:7, Stormwinds hemliga underrättelse- och spionagegren. Han arbetar från kasernen i Old Town.",al={"vem är shaw","mathias shaws roll","si:7-ledare"}},{q="Var hittar jag Mathias Shaw?",a="Du hittar Master Mathias Shaw på andra våningen i SI:7:s högkvarter i kasernen i Old Town, Stormwind City.",al={"var finns shaw","shaws plats","hitta mathias shaw"}},{q="Vad är sambandet mellan Defias och Stonemasons?",a="Stonemasons Guild återuppbyggde Stormwind efter stadens förstörelse i det första kriget. Gryan Stoutmantle misstänker att Wileys omnämnande av gillet knyter det till Defias, och Mathias Shaw kan bekräfta eller förneka sambandet.",al={"defias och stonemasons","är defias stonemasons","samband med stonemasons"}},{q="Vad är Wiley's Note?",a="Wiley's Note kommer från Wiley the Black, en skurk som Gryan Stoutmantle har haft att göra med tidigare. Den varnar för att Defias smider planer med gnoller, kobolder och gobliner, och Wileys omnämnande av Stonemasons kan knyta Defias Brotherhood till det tidigare gillet.",al={"wileys meddelande","vad är meddelandet","meddelande till shaw"}},{q="Känner Highlord Bolvar eller pojkkungen till detta?",a="Hemliga statsärenden passerar genom Mathias Shaw och SI:7 innan de når Highlord Bolvar Fordragon och tronen. Shaw säger att saken kan vara mer komplicerad än Stoutmantle inser.",al={"vet kungen om det","vet bolvar om det","stormwinds regering vet"}}},fx={f764ce01={q="Varför skickar Gryan Stoutmantle dig i stället för en soldat från People's Militia?",a="People's Militia är nära bristningsgränsen bara av att försvara Sentinel Hill och Westfalls utspridda gårdar. Gryan Stoutmantle har inte råd att dra bort stridsberedda försvarare från frontlinjen för att skicka meddelanden tillbaka till huvudstaden. Dessutom är du en främling som redan har lagt ihop Wileys ledtrådar, vilket gör dig till en betrodd kurir som kan föra känsliga frågor direkt till Stormwinds spionmästare.",al={"varför skicka mig","varför inte milisen","varför behöver stoutmantle dig"}}},fp="22,147,20.262.0,16.290.0,25.216.1,49.178.0,20.125.0,29.118.0,62.212.1,21.254.0,53.181.0"}
P.entries["quest:1358"] = {n="Sample for Helbrim",s="Vid The Crossroads väntar Apothecary Helbrim på ett varghjärta från andra sidan havet. Apothecary Zinge skickar det från Undercity för att stödja Forsakens forskning i centrala Kalimdor.",h="Vid The Crossroads väntar Apothecary Helbrim på ett varghjärta från andra sidan havet.",kw={"apothecary helbrim","apothecary zinge","the crossroads","royal apothecary society","sample for helbrim","the barrens","undercity","wolf heart sample"},ang={["faction:Horde"]="Som medlem av Horde ser du orcher och tauren välkomna Forsakens hjälp med att försvara The Crossroads. Apotekarnas stillsamma studier av pestsmittade kvarlevor för med sig en oroande närvaro till det fridfulla The Barrens.",["race:Undead"]="Som odöd bär du Royal Apothecary Societys förgiftade prover över hela världen, som en del av dess omfattande försök att säkra Forsakens herravälde genom kemisk överlägsenhet."},sec={{t="Smitta över havet",b="Apothecary Zinge skickar ett Wolf Heart Sample från Undercity till Apothecary Helbrim i The Barrens. Royal Apothecary Societys experiment sträcker sig bortom Ruins of Lordaeron. Efter att Apothecary Renferrel skickat förgiftade organ från Silverpine Forest ville Zinge utvidga deras forskning över hela världen. Nu för en kurir provet över havet till Helbrim, en alkemist stationerad på The Barrens torra savann."},{t="Helbrims ambition",b="Vid The Crossroads studerar Apothecary Helbrim hur Kalimdors inhemska djur reagerar på föreningar från Plaguelands. Vargens hjärta kan visa hur dessa gifter påverkar lokala varelser. Helbrim tror att dissekering och testning av det tillsammans med dem kommer att hjälpa Forsaken att bemästra gifter och onaturliga åkommor."}},faq={{q="Vad är det för paket som ska levereras till Helbrim?",a="Paketet innehåller ett Wolf Heart Sample, som Apothecary Renferrel samlat in från Silverpine Forests korrumperade vargar och Apothecary Zinge analyserat i Undercity.",al={"vad är provet","varghjärtpaket","vad gav zinge mig"}},{q="Varför vill Apothecary Helbrim ha ett förgiftat varghjärta?",a="Helbrim studerar hur gifter från Lordaeron påverkar Kalimdors djurliv. Han hoppas att hjärtats extrema giftighet ska hjälpa till att utveckla starkare blandningar och gifter åt Royal Apothecary Society.",al={"varför behöver helbrim varghjärta","helbrims forskning","helbrims syfte"}},{q="Var finns Apothecary Helbrim?",a="Apothecary Helbrim är stationerad vid The Crossroads i The Barrens, på det centrala vakttornets övre utvändiga däck med utsikt över bosättningen.",al={"var finns helbrim","helbrims plats","hitta helbrim"}},{q="Hur tar sig en resenär från Undercity till The Crossroads?",a="Ta zeppelinaren från tornet utanför Undercity till Orgrimmar i Durotar. Res söderut genom Durotar, korsa Southfury River in i The Barrens och följ sedan huvudvägen västerut till The Crossroads.",al={"resa till the crossroads","hur tar man sig till helbrim","undercity till the barrens"}},{q="Vilka är Apothecary Renferrel och Apothecary Zinge?",a="Apothecary Renferrel och Apothecary Zinge är forskare i Royal Apothecary Society. Renferrel arbetar från The Sepulcher i Silverpine Forest, medan Zinge studerar i Apothecarium i Undercity.",al={"vem är renferrel","vem är zinge","zinge och renferrels historia"}},{q="Vilken fraktion tjänar den här forskningen?",a="Forskningen tjänar Forsaken och Royal Apothecary Society under Lady Sylvanas Windrunner. Den för deras arbete med att skapa dödliga kemiska och biologiska vapen framåt.",al={"vem gynnas","är det här för sylvanas","apotekarnas mål"}}},fx={d2670c0d={q="Varför vill Apothecary Zinge att det här provet levereras till Helbrim?",a="Apothecary Zinge vill bidra till Royal Apothecary Societys bredare forskning på båda kontinenterna. Hennes kollega Apothecary Helbrim är stationerad i Kalimdor och undersöker hur Lordaerons fördärvade gifter reagerar med inhemska bestar. Zinge tror att de förgiftade varghjärtan från Silverpine kan föra deras gemensamma kunskap om smittsamma gifter framåt, så hon skickar dig för att se till att Helbrim får materialet till sina experiment.",al={"varför skicka provet till helbrim","zinges motiv med provet","varför vill zinge att det levereras"}}},fp="18,179,26.403.0,18.310.0,47.165.0,54.192.0,36.146.0,57.199.0,50.205.0,38.172.0"}
P.entries["quest:1359"] = {n="Zinge's Delivery",s="Zinge's Delivery är ett buduppdrag som Apothecary Renferrel skickar från The Sepulcher i Silverpine Forest. Det för märkligt giftig varghjärtvävnad till Apothecary Zinge i Undercity för vetenskaplig undersökning.",h="Zinge's Delivery är ett buduppdrag som Apothecary Renferrel skickar från The Sepulcher i Silverpine Forest.",kw={"apothecarium","apothecary renferrel","apothecary zinge","the sepulcher","silverpine","undercity","wolf heart samples","zinge's delivery"},ang={["faction:Horde"]="Bud som transporterar biologiska reagenser håller avlägsna utposter som The Sepulcher förenade med ledningen och forskningscentrumen i Undercity.",["race:Undead"]="Prover från fältet i Lordaeron går direkt till de centrala alkemilaboratorierna under ruinerna av huvudstaden och stärker de Fördömdas vetenskapliga makt."},sec={{t="En giftig anomali",b="När Apothecary Renferrel undersökte det lokala djurlivet i Silverpine Forest lade han märke till ett oroande fysiologiskt särdrag hos vargarna som strövade omkring i de förstörda skogarna. Deras hjärtan innehöll så höga halter av gift att det under vanliga omständigheter borde ha dödat djuren som bar på dem. I stället för att kasta vävnaden packade Renferrel flera prover för att dela dem med kollegor på Apothecarium i Undercity."},{t="Apothecariums blick",b="De bevarade organen levereras direkt till Apothecary Zinge, en forskare som arbetar vid Royal Apothecary Societys underjordiska högkvarter. För sällskapet, vars främsta ambition är att framställa kraftfulla farsoter och nya alkemiska föreningar, är naturligt förekommande gifter som håller vid liv i stället för att döda av största intresse. Zinge tar emot leveransen som grund för ytterligare laboratorieförsök i hela de Fördömdas alkemiska nätverk."}},faq={{q="Vad är varghjärtproverna?",a="De är bevarad biologisk vävnad från vargar i Silverpine Forest. Apothecary Renferrel upptäckte att hjärtana innehåller naturliga gifter som är så dödliga att djuren inte borde ha överlevt med dem i kroppen.",al={"varghjärtan","vad är varghjärtprover","renferrels prover"}},{q="Vem är Apothecary Renferrel?",a="Apothecary Renferrel är medlem i Royal Apothecary Society och stationerad vid The Sepulcher i Silverpine Forest. Han leder fältforskning om regionens växter och djur för att samla ingredienser och biologisk kunskap till de Fördömdas alkemi.",al={"vem är renferrel","renferrel silverpine"}},{q="Vem är Apothecary Zinge?",a="Apothecary Zinge är en alkemiforskare verksam i Apothecarium-kvarteret i Undercity. Hon undersöker inkommande biologiska prover för att upptäcka nya gifter och alkemiska ämnen åt de Fördömda.",al={"vem är zinge","zinge undercity","apothecary zinge bakgrund"}},{q="Vart går leveransen härnäst?",a="När Zinge har tagit emot och undersökt den märkliga hjärtvävnaden fortsätter forskningen, och prover skickas vidare till andra alkemiutposter, som Apothecary Helbrim, stationerad på andra sidan havet i The Barrens.",al={"nästa uppdrag","vad händer efter zinge's delivery","fortsättningsuppdrag"}},{q="Varför är Royal Apothecary Society intresserat av varghjärtan?",a="Royal Apothecary Society söker ständigt efter exotiska gifter, sjukdomar och biologiska anomalier. Ett odjur som överlever sin egen dödliga giftighet uppvisar unika kemiska förlopp som kan bidra till utvecklingen av nya farsoter och föreningar.",al={"varför vill apotekarna ha varghjärtan","royal apothecary society varghjärtan"}},{q="Var ligger Apothecarium i Undercity?",a="Apothecarium utgör Undercitys sydvästra flygel. Det fungerar som Royal Apothecary Societys främsta laboratoriekomplex och högkvarter.",al={"apotekarläge i undercity","var finns zinge","apothecarium karta"}}},fx={["37fb7d35"]={q="Varför skickar Apothecary Renferrel dig i stället för att åka själv?",a="Apothecary Renferrel är stationerad vid The Sepulcher i Silverpine Forest, där han bedriver fältarbete och fortsatt forskning om det lokala djurlivet. Om han lämnade sin utpost för att föra prover tillbaka till huvudstaden skulle han behöva avbryta sina experiment. Därför passar en stark resenär bäst som kurir för att transportera de ömtåliga exemplaren direkt till Apothecary Zinge i Apothecarium.",al={"varför jag och renferrel","varför behöver renferrel en kurir","varför skicka en äventyrare med leveransen"}}},fp="16,255,15.290.0,28.351.0,32.186.0,28.226.0,24.187.0,35.183.1,62.196.0,39.144.0"}
P.entries["quest:136"] = {n="Captain Sander's Hidden Treasure",s="En sliten pergamentkarta sätter Captain Sanders' Hidden Treasure i rörelse längs Westfalls kust. Jakten börjar med att leta längs strandlinjen efter den avlidne kaptenens personliga sjökista och leder sedan mot hans gömda byte i regionen.",h="En sliten pergamentkarta sätter Captain Sanders' Hidden Treasure i rörelse längs Westfalls kust.",kw={"captain sanders","sjökista","gömd skatt","rostat ankare","skeppsvrak","skattkarta","westfalls kust"},ang={["class:Rogue"]="Som skurk känner du till värdet av att följa en död sjömans karta längs en laglös kust. En pirats skattjakt passar skurkar och kapare.",["faction:Alliance"]="Som Alliance-äventyrare är det en liten seger att bärga en förmögenhet från Westfalls kust, full av skeppsvrak, mitt i kungarikets oroliga gränstrakter där kustens murlocer hotar stranden."},sec={{t="En sjömans sista gåva",b="Skeppsvrak och de rastlösa andarna efter drunknade sjömän präglar Westfalls västra kust. Captain Sanders, en gammal sjöfarare, mötte sin våta grav där. Han lämnade kryptiska instruktioner så att hans hårt förvärvade förmögenhet inte skulle gå förlorad i Stora havet eller tas av asätare. En beslutsam äventyrare kan följa spåren han lämnade efter sig."},{t="Det rostiga ankaret",b="Den första ledtråden pekar mot ett ensamt rostigt ankare i bränningarna vid Westfalls västra kust. Nära ett vrak ligger Captain Sanders gamla sjökista, halvt begravd i sanden och sliten av vågorna. Inuti finns havsvatten, sand och en krabba som kilar omkring med nästa bit av Sanders gåta i klorna."}},faq={{q="Vem var Captain Sanders?",a="Captain Sanders var en gammal sjökapten vars karta säger att han ligger i en våt grav. Han lämnade kartan och en rad ledtrådar som leder till hans gömda byte.",al={"captain sanders bakgrund","vem är sanders","sanders bakgrundshistoria"}},{q="Var finns sjökistan?",a="Sjökistan ligger halvt begravd i sanden längs Westfalls västra kust, nära ett ensamt rostigt ankare vid strandlinjen.",al={"sjökistans plats","var finns det rostiga ankaret","hitta sanders sjökista"}},{q="Innehåller sjökistan kaptenens skatt?",a="Kartan leder dig till en sjökista och nästa ledtråd i en längre skattjakt.",al={"finns skatten i kistan","vad finns i sjökistan","var finns guldet"}},{q="Hur många ledtrådar finns i Captain Sanders skattjakt?",a="Jakten består av fyra steg längs Westfalls kust och landsbygd. Den börjar med kartan och slutar med Captain Sanders verkliga skattkista på en ö utanför kusten.",al={"hur lång är sanders uppdrag","hur många delar","sanders uppdragskedja"}},{q="Varför begravde Captain Sanders sin skatt i Westfall?",a="Captain Sanders karta säger aldrig varför han valde Westfall. Den säger att han väntade sig en våt grav och ville att den som följde hans ledtrådar skulle hitta skatten, med ledtrådar utspridda längs kusten och på klipporna ovanför den.",al={"varför gömma skatten","varför westfalls kust"}},{q="Kan Horde-spelare följa den här skattkartan?",a="Ja. Captain Sanders karta och ledtrådar är neutrala, så alla äventyrare som tar sig till Westfalls kust kan följa hans spår.",al={"kan horde göra detta","horde sanders uppdrag","fraktionsneutral skatt"}}},fx={["1a1a7b8a"]={q="Varför lämnade Captain Sanders den här skattkartan efter sig?",a="Captain Sanders visste att han gick mot en våt grav och tänkte inte låta sina samlade rikedomar ruttna bort, bortglömda under havet. Han lade ut en kryptisk ledtrådsstig för den som hade list och mod nog att hitta hans pergament. Genom att utmana ambitiösa resenärer att leta efter hans gamla fotkista ser han till att hans namn och eftermäle lever vidare långt efter hans död.",al={"varför sanders karta","sanders motiv med skattkartan","varför lämna skattkartan"}}},fp="32,203,23.321.0,16.274.1,24.149.0,32.122.0,51.78.1,53.168.0,54.220.0,43.117.0"}
P.entries["quest:1361"] = {n="Regthar Deathgate",s="I The Barrens kallar Regthar Deathgate erfarna krigare från Horde västerut. Den rutinerade krigaren samlar frivilliga till ett fälttåg över bergen in i Desolace, där centaurklanerna terroriserar gränstrakterna.",h="I The Barrens kallar Regthar Deathgate erfarna krigare från Horde västerut.",kw={"belgrom rockmaul","the crossroads","desolace","kolkar","krusk","nazgrel","regthar deathgate","the barrens","vol'jin"},ang={["class:Warrior"]="Som krigare kan du besvara Regthars kallelse med direkt stridsförmåga och disciplin i Desolaces fientliga ödemarker.",["faction:Horde"]="Horde försöker säkra sin gräns genom att kuva centaurerna i grannlandet Desolace innan de kan plundra djupare in i The Barrens.",["race:Tauren"]="Som tauren har du ett personligt skäl att hjälpa Regthar att slå till mot Kolkar, efter generationer av konflikt med centaurerna i centrala Kalimdor."},sec={{t="Warchiefens löjtnanters kallelse",b="Hordes ledare håller uppsikt över gränserna efter hot. I The Barrens har Regthar Deathgate upprättat en försvarspost som bevakar de västra passen. Hordes officerare skickar beprövade äventyrare väster om The Crossroads för att besvara hans kallelse efter härdade krigare."},{t="Vägen till Desolace",b="Regthar Deathgate väntar i en befäst skans längs höjderna väster om The Crossroads. Därifrån bevakar han bergslederna in i Desolace. Han samlar en förtrupp för att ta sig över fientlig mark och slå till mot Kolkar och andra stridande centaurklaner innan deras expansion hotar Hordes territorium."}},faq={{q="Vem är Regthar Deathgate?",a="Regthar Deathgate är en orcisk krigare och befälhavare för Horde, stationerad i The Barrens. Han leder spejare och militära anfall in i Desolace.",al={"vem är regthar","regthar deathgate bakgrund","vem ger uppdraget"}},{q="Var finns Regthar Deathgate?",a="Regthar Deathgate finns i The Barrens, inne i Hordes bunkrar på bergsstigen väster om The Crossroads, med utsikt över det västra bergspasset.",al={"var finns regthar","regthars plats","hitta regthar deathgate"}},{q="Vem ger uppdraget att söka upp Regthar?",a="Shadow Hunter Vol'jin, Nazgrel, Belgrom Rockmaul och Krusk uppmanar dig att söka upp Regthar. Vol'jin, Nazgrel och Belgrom Rockmaul finns i Orgrimmar; Krusk finns i Tarren Mill.",al={"vem startar regthar deathgate-uppdraget","var får man regthar-uppdraget"}},{q="Vad är huvudmålet med Regthars uppdrag?",a="Regthar samlar krigare för att ta sig över bergen in i Desolace och anfalla de fientliga centaurklanerna, särskilt Kolkar.",al={"vad vill regthar","regthar deathgates syfte"}},{q="Varför oroar sig Horde för Desolace?",a="Aggressiva centaurklaner härjar i Desolace. Om de inte hejdas kan deras räder ta sig över bergen in i The Barrens och närliggande bosättningar tillhörande Horde.",al={"varför bege sig till desolace","hordens intresse i desolace"}},{q="Vad händer efter att du talat med Regthar Deathgate?",a="När du rapporterar till Regthar berättar han om länderna bortom de västra bergen och skickar dig över gränsen på ditt första anfall mot Kolkar.",al={"nästa uppdrag efter regthar","fortsättning efter regthar"}}},fp="17,208,34.239.0,20.300.0,25.135.0,35.141.0,40.173.0,51.127.0,41.146.0,54.157.0"}
P.entries["quest:1362"] = {n="The Kolkar of Desolace",s="Kolkar hotar Hordeområden från sitt fäste i Desolace. Regthar Deathgate skickar Hordens mästare västerut över bergen för att förstärka spejaren Felgur Twocuts vid Ghost Walker Post.",h="Kolkar hotar Hordeområden från sitt fäste i Desolace.",kw={"kentaur","desolace","felgur twocuts","ghost walker post","horden","kolkar","regthar deathgate","the barrens"},ang={["faction:Horde"]="För Horden innebär detta en övergång från att försvara unga bosättningar i Durotar och The Barrens till att föra striden in i fientliga områden.",["race:Orc"]="Som orc har du säkrat ett fotfäste i östra Kalimdor. De otämjda centaurklanerna hotar fortfarande Hordens försörjningslinjer.",["race:Tauren"]="Som tauren vet du att centaurernas aggression nästan utplånade dina nomadstammar innan din allians med Thrall. Att strida mot dem i deras hemland Desolace har ett personligt pris."},sec={{t="Ett hot bortom bergen",b="Centaurernas plundrare fortsätter att tränga in i The Barrens, och Regthar Deathgate vet att strider där inte kommer att få slut på hotet. Kolkar-klanen hämtar sin styrka från de karga trakterna på Kalimdors västkust. Så länge deras förfäders fäste ligger utanför Hordens kontroll kommer plundrarna att fortsätta strömma genom bergspassen. För att stoppa dem måste Horden slå till mot deras hem."},{t="Ghost Walker Post",b="Ghost Walker Post ger Horden ett fotfäste långt inne i Desolace. Spejaren Felgur Twocuts håller uppsikt över de rivaliserande centaurklanerna från utposten. Regthar skickar erfarna kämpar från The Barrens för att tjäna under Felgur och föra Hordens kampanj västerut, från försvar till direkt angrepp."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Regthar Deathgate, en orc-krigare vid bunkern väster om The Crossroads i The Barrens, ger dig i uppdrag att föra striden in i Kolkars förfäders land.",al={"uppdragsgivare","vem ger uppdraget","regthar"}},{q="Var ligger Ghost Walker Post?",a="Ghost Walker Post är ett avskilt Horde-läger längs de karga stigarna i Desolace, väster om bergsryggen i Kalimdor.",al={"var ligger ghost walker post","felgur twocuts plats","läger i desolace"}},{q="Varför riktar Horden in sig på Desolace?",a="Kolkar som plundrar The Barrens kommer från de större centaurklaner som har sina rötter i Desolace. Regthar vet att försvar ensamt inte kan stoppa invasionerna så länge Kolkars fäste står kvar.",al={"varför åka till desolace","varför bekämpa kolkar i desolace","kentaurernas koppling"}},{q="Vem är Felgur Twocuts?",a="Felgur Twocuts är en Horde-spejare vid Ghost Walker Post. Han håller uppsikt över de rivaliserande centaurklanerna i Desolace och organiserar anfall mot dem.",al={"felgur twocuts","vem är felgur"}},{q="Innebär det här uppdraget strid?",a="Nej. Du för med dig ett meddelande från The Barrens till Desolace, där svårare utmaningar väntar Hordens äventyrare.",al={"strid i uppdraget","stridsuppdrag"}},{q="Vilken kentaurklan är målet för det här uppdraget?",a="Kolkar-klanen är målet. Dess centaurplundrare kommer från Desolace och har trängt in i The Barrens och Durotar.",al={"vilken kentaurklan","vilken klan","kolkar-klanen"}}},fx={["4557df46"]={q="Varför behöver Regthar Deathgate att du reser till Desolace?",a="Regthar Deathgate samordnar försvaret av frontlinjen och spaningen mot Kolkar i The Barrens. Han håller de lokala Horde-styrkorna upptagna med omedelbara hot mot oaserna. För att slå till mot problemets rot behöver han en duglig och rörlig äventyrare som kan ta sig bortom gränsen, in i ödemarkerna i Desolace, och få direkt kontakt med spanaren Felgur Twocuts.",al={"varför skicka mig till desolace","varför behöver regthar mig","varför jag och kolkar i desolace"}}},fp="22,188,29.380.0,17.271.0,29.152.0,35.116.0,38.184.0,22.136.0,31.104.0,42.115.0"}
P.entries["quest:1365"] = {n="Khan Dez'hepah",s="Efter The Kolkar of Desolace låter Felgur Twocuts dig ta dig an Kolkars ledare, Khan Dez'hepah. Många kentaurklanerna strider mot varandra i Desolace, och Felgur vill störa Kolkar innan klanerna enas.",h="Efter The Kolkar of Desolace låter Felgur Twocuts dig ta dig an Kolkars ledare, Khan Dez'hepah.",kw={"kentaur","desolace","dez'hepah","felgur twocuts","khan dez'hepah","kolkar","kolkar village"},sec={{t="Splittrade klaner",b="Kolkar är bara en av kentaurklanerna i Desolace. Många strövar över de torra slätterna och slåss mot varandra tills de dör. Felgur Twocuts har inget emot det, eftersom kentaurerna är starka och brutala, och ett enat kentaurfolk skulle vara en fruktansvärd fiende för Horden. De måste tas om hand innan det händer."},{t="Kolkarledaren",b="Felgurs första drag är att störa Kolkar genom att döda deras ledare, Khan Dez'hepah. Kolkar Village ligger nordost om platsen där Felgur står, och Felgur vill att khanens huvud förs tillbaka."}},faq={{q="Varför vill Felgur Twocuts att Khan Dez'hepah ska dö?",a="Felgur oroar sig för att kentaurklanerna kan enas mot Horden. Tanken är att dödandet av Khan Dez'hepah först ska störa Kolkar-klanen.",al={"varför döda dezhepah","khan dezhepahs syfte","orsak till att döda dezhepah"}},{q="Var finns Khan Dez'hepah?",a="I Kolkar Village, nordost om Felgur Twocuts i Desolace.",al={"khan dezhepahs plats","var är dezhepah","kolkar villages plats"}},{q="Vad vill Felgur få tillbaka?",a="Khan Dez'hepahs huvud, återfört till Felgur Twocuts.",al={"bevis på khan dezhepah","vad ska föras till felgur"}},{q="Vad kommer före Khan Dez'hepah?",a="The Kolkar of Desolace. Efter det skickar Felgur Twocuts dig mot Kolkars ledare, Khan Dez'hepah.",al={"föregående uppdrag dezhepah","förutsättning för khan dezhepah"}}},fp="14,214,13.309.0,17.190.0,49.132.0,32.63.0,35.54.0,33.101.0"}
P.entries["quest:1366"] = {n="Centaur Bounty",s="Efter Khan Dez'hepah säger Felgur Twocuts att de skrämda centaurklanerna nu måste blöda. Jaga centaur från vilken klan som helst i Desolace och ta med femton av deras öron till Felgur.",h="Efter Khan Dez'hepah säger Felgur Twocuts att de skrämda centaurklanerna nu måste blöda.",kw={"centaur","centaurbelöning","centauröron","desolace","felgur twocuts","khan dez'hepah"},sec={{t="Dags att låta dem blöda",b="Felgur Twocuts säger att det är dags att låta centaurklanerna blöda nu när de har skrämts. Jaga centaur när du färdas genom Desolace. Felgur bryr sig inte om vilken klan du jagar, bara att du samlar öron, femton stycken. Färre av dem försvagar deras beslutsamhet och sätter stopp för alla tankar på expansion."},{t="Felgurs dom",b="När du återvänder säger Felgur att centaurerna vid det här laget måste känna till ditt namn och respektera och frukta det. De känner också till fanan du rider under: Hordens."}},faq={{q="Vem har utfärdat den här belöningen för centaur?",a="Felgur Twocuts i Desolace. Femton centauröron ska föras tillbaka till Felgur.",al={"vem ger centaurbelöningen","uppdragsgivare för centaurbelöning"}},{q="Vilka centaurklaner ska jag jaga?",a="Vilka som helst. Felgur bryr sig inte om vilken klan du jagar, bara att du samlar öron.",al={"vilka centaur ska jag döda","vilken klan för centaurbelöning"}},{q="Varför vill Felgur ha så många centauröron?",a="För att minska antalet centaur. Färre centaur innebär svagare beslutsamhet och sätter stopp för alla tankar på expansion.",al={"varför döda centaur i desolace","orsak till centaurbelöningen"}},{q="Vad kom före den här belöningen?",a="Den följer efter Khan Dez'hepah. Felgur säger att centaurklanerna har skrämts och att det nu är dags att låta dem blöda.",al={"förkunskapskrav för centaurbelöning","föregående uppdrag för centaurbelöning"}}},fp="14,165,18.314.0,16.151.1,38.83.0,38.81.0,42.111.0,29.108.0"}
P.entries["quest:1367"] = {n="Magram Alliance",s="Gurda Wildmane föreslår att vända centaurklanernas hat mot dem: bli vän med en klan och lär dig hur alla kan besegras. Om du ställer dig på Magrams sida måste du döda deras fiender Gelkis och sedan tala med Magrams talesperson Warug vid utkanten av Magram Village, i sydöstra Desolace.",h="Gurda Wildmane föreslår att vända centaurklanernas hat mot dem: bli vän med en klan och lär dig hur alla kan...",kw={"centaur","desolace","gelkis","gurda wildmane","magram","magram village","warug"},sec={{t="Hat som vapen",b="Gurda Wildmanes plan går ut på att utnyttja centaurernas hat mot varandra. En enda klan väljs som allierad, och det den lär ut visar hur alla klaner kan besegras. Välj Magram och du hugger ner deras fiender Gelkis, vilket vinner dig respekt bland Magram."},{t="Talespersonen",b="När du har vunnit tillräckligt med respekt väntar Warug, Magrams talesperson, i utkanten av Magram Village i sydöstra Desolace. Innan dess har han inget att säga dig. Magram har inget till övers för de svaga och dödar dem i stället, så han skickar iväg dig för att bevisa din styrka mot många Gelkis."},{t="Warugs dom",b="Warug berättar att Gelkis gråter när de hör ditt namn, rädda för dig och hatfulla mot dig, precis som de är mot Magram. Kanske, medger han, är du lika stark som Magram. Det återstår att se."}},faq={{q="Vem föreslår en allians med Magram?",a="Gurda Wildmane, som vill vända centaurklanernas hat mot dem genom att alliera sig med en klan och lära sig av den hur alla kan besegras.",al={"vem ger magram-alliansen","magram-uppdragsgivare","gurda wildmane-uppdrag"}},{q="Hur vinner du Magrams respekt?",a="Genom att döda deras fiender Gelkis.",al={"hur blir man vän med magram","magram-rykte","gör magram vänliga"}},{q="Var finns Warug?",a="I utkanten av Magram Village, i sydöstra Desolace. Han är Magrams talesperson.",al={"var finns warug","hitta warug","warugs plats"}},{q="Varför vägrar Warug att tala till en början?",a="Han säger att Magram inte talar med de svaga, utan dödar dem. Bevisa först din styrka genom att döda många Gelkis.",al={"varför vill warug inte prata","warug arg","warugs dialog"}}},fp="15,310,18.256.0,13.301.0,16.176.1,41.142.0,42.34.0,15.86.0,40.110.0"}
P.entries["quest:1368"] = {n="Gelkis Alliance",s="Gurda Wildmane föreslår att vända kentaurklanernas hat mot dem själva: bli vän med en klan och lär dig hur alla kan besegras. Ställer du dig på Gelkis sida dödar du deras värsta fiender, Magram, och möter sedan Uthek the Wise, en schaman bland Gelkis, i utkanten av Gelkis Village i sydvästra Desolace.",h="Gurda Wildmane föreslår att vända kentaurklanernas hat mot dem själva: bli vän med en klan och lär dig hur...",kw={"kentaur","desolace","gelkis","gelkis village","gurda wildmane","magram","uthek the wise"},sec={{t="Hat som vapen",b="Gurda Wildmanes plan går ut på att utnyttja kentaurernas hat mot varandra. En enda klan väljs som allierad, och det den lär ut visar hur varje klan kan besegras. Väljer du Gelkis dödar du Magram, som Gelkis hatar mest, och vinner deras respekt."},{t="Schamanen",b="När du har vunnit deras respekt ska du möta Uthek the Wise, schaman bland Gelkis, i utkanten av Gelkis Village i sydvästra Desolace. Innan dess är du inte välkommen där: Uthek säger att du går på Gelkis mark och att du måste bevisa din vänskap genom att döda kentaurer från Magram. Kom tillbaka när Magram-blod har dränkt marken."},{t="Utheks ord",b="Uthek säger att jorden berättar hur många Magram du har dödat, och att det är bra. Uthek har mer arbete åt en vän till Gelkis."}},faq={{q="Vem föreslår en allians med Gelkis?",a="Gurda Wildmane, som vill vända kentaurklanernas hat mot dem genom att alliera sig med en klan och lära sig av den hur alla kan besegras.",al={"vem ger gelkis-alliansen","uppdragsgivare för gelkis-alliansen"}},{q="Hur vinner du Gelkis gunst?",a="Genom att döda Magram, som Gelkis hatar mest.",al={"hur blir man vän med gelkis","gelkis-rykte"}},{q="Vem talar du med bland Gelkis?",a="Uthek the Wise, en schaman bland Gelkis, i utkanten av Gelkis Village i sydvästra Desolace.",al={"var finns uthek","uthek the wise plats"}},{q="Vad kräver Uthek innan hen välkomnar dig?",a="Uthek säger att du inte är välkommen på Gelkis mark förrän du bevisar din vänskap genom att döda kentaurer från Magram.",al={"varför avvisar uthek mig","gelkis village fientligt"}}},fp="15,321,18.248.0,10.326.0,12.141.1,41.142.0,40.49.0,37.90.0,45.100.0"}
P.entries["quest:1369"] = {n="Broken Tears",s="Warug säger att Gelkis i sin dumhet tror att centaurernas moder, Theradras, skyddar dem. Han skickar in dig i grottan i deras by för att förstöra kristallerna de samlar där, Theradras tårar, och hämta tre av de krossade bitarna till honom.",h="Warug säger att Gelkis i sin dumhet tror att centaurernas moder, Theradras, skyddar dem.",kw={"broken tears","centaur","desolace","gelkis","magram","theradras","warug"},sec={{t="Kristaller i grottan",b="Warug hånar Gelkis för att de litar på att Theradras, centaurernas moder, ska skydda dem. För honom skyddar ingen centaurerna, och Magram, som är starkast, behöver inget skydd. Han skickar dig till grottan i Gelkis Village, där de samlar ett förråd av kristaller som kallas Theradras tårar. Krossa dem och ta med tre bitar till Warug. Han litar bara på dig med detta om du inte är fiende till Magram."},{t="Warugs skryt",b="Warug är förtjust: när tårarna har krossats kommer Gelkis att inse att Theradras inte kan hjälpa dem, och inga tårar från henne kommer att falla när Magram krossar dem. Han förklarar att Magram ska härska och kallar dig klok som ställer dig på de starkastes sida."}},faq={{q="Vem är Warug?",a="En centaur från Magram i Magram Village i Desolace. Han ber dig förstöra Theradras tårar i Gelkis grotta.",al={"warug","vem ger uppdraget broken tears","uppdragsgivare för broken tears"}},{q="Vad är Theradras tårar?",a="Kristaller som Gelkis samlar i en grotta i sin by.",al={"theradras tårar","lore om broken tears","gelkis kristaller"}},{q="Varför vill Warug att tårarna förstörs?",a="Gelkis tror att centaurernas moder, Theradras, skyddar dem. Warug kallar dem dumma, säger att Magram inte behöver något skydd och vill visa Gelkis att de har fel.",al={"varför förstöra tårarna","magrams motiv","varför krossa kristallerna"}},{q="Var finns kristallerna?",a="I grottan i Gelkis Village. Warug vill att du tar med tre krossade bitar tillbaka till honom.",al={"var finns broken tears","gelkis grottas plats","var finns tårarna"}}},fp="12,237,20.411.0,13.235.1,13.113.0,32.53.0,40.168.0,29.87.0"}
P.entries["quest:1370"] = {n="Stealing Supplies",s="Uthek the Wise säger att kött ger Gelkis deras styrka och att Magram håller extra förråd för att kunna slåss längre mellan jakterna. Du skickas för att plundra byn Magram i öster och hämta sex säckar torkat kött.",h="Uthek the Wise säger att kött ger Gelkis deras styrka och att Magram håller extra förråd för att kunna slåss...",kw={"kentaur","desolace","gelkis","magram","kött","förråd","uthek"},sec={{t="Kött och styrka",b="Mellan krigen jagar Gelkis, eftersom kött betyder styrka och en mätt mage slåss hårdare än en tom. Uthek the Wise säger att Magram håller extra förråd för att klara sig mellan jakterna. Plundra deras by i öster, ta förråden och deras styrka kommer att svikta. Sex säckar grovtorkat kött ska hämtas och lämnas till Uthek vid Gelkis Village."}},faq={{q="Vem skickar dig för att hämta förråden?",a="Uthek the Wise bland Gelkis, i Desolace.",al={"uppdragsgivare","vem ger uppdraget stjäla förråd","uthek the wise"}},{q="Varför vill Uthek att Magram-köttet ska tas?",a="För Gelkis betyder kött styrka. Magram håller ett reservförråd så att de kan fortsätta slåss mellan jakterna, och Uthek säger att om du tar det försvagas de.",al={"varför stjäla kött","magrams mat","orsak till köttraid"}},{q="Var förvaras Magrams förråd?",a="I byn Magram, i öster.",al={"var ligger magram village","var finns förråden","magrams plats"}},{q="Hur mycket kött vill Uthek ha?",a="Sex säckar grovtorkat kött, som Uthek the Wise tar emot vid Gelkis Village.",al={"hur mycket kött","vad ska jag lämna till uthek"}}},fp="17,226,17.353.0,37.42.0,42.140.0,35.35.0,30.84.0"}
P.entries["quest:1371"] = {n="Gizmo for Warug",s="Warug i Magram Village minns en gnom som en gång kom till Desolace med en kärra full av märkliga saker. Han behöll en människa av trä från kärran tills han slog sönder den, och nu vill han ha en ny: en avancerad måldocka.",h="Warug i Magram Village minns en gnom som en gång kom till Desolace med en kärra full av märkliga saker.",kw={"centaur","desolace","gnom","magram","måldocka","warug"},sec={{t="Gnomens kärra",b="För länge sedan kom en liten gnom till Desolace med hästar och en kärra. Kärran var full av märkliga saker: några brann i olika färger, andra rörde sig trots att de inte levde. Warug dödade gnomen, men först fick gnomen honom att skratta. Warug behöll sin favoritsak från kärran, en människa av trä som vinkade åt honom tills han slog till den och den gick sönder. Nu vill han ha en ny, en avancerad måldocka, och förväntar sig att få den av vem som helst som inte är en fiende till Magram."}},faq={{q="Vem är Warug?",a="Warug är en Magram-centaur som finns i Magram Village. Han förväntar sig att de han gör affärer med ska stå väl till hos Magram.",al={"warug","vem ger gizmo for warug"}},{q="Vad vill Warug ha?",a="En avancerad måldocka som ersättning för människan av trä från gnomens kärra som han slog sönder.",al={"vilket föremål behöver warug","warug gizmo föremål"}},{q="Varför vill Warug ha en måldocka?",a="För länge sedan dödade han en gnom som kom till Desolace med en kärra full av märkliga, roliga saker. Gnomen fick honom att skratta, och Warugs favorit var en träfigur föreställande en människa som vinkade åt honom tills han slog till den och den gick sönder. Han vill ha en ny.",al={"varför vill warug ha en måldocka","warugs anledning till måldockan"}},{q="Vad händer före detta i Magram-berättelsen?",a="Den följer efter Broken Tears, tidigare i dina förehavanden med Magram.",al={"gizmo for warug uppdragskedja","vad händer före gizmo for warug"}}},fp="15,215,16.457.0,13.121.0,21.90.0,35.231.0,43.66.0"}
P.entries["quest:1373"] = {n="Ongeku",s="Uthek the Wise från Gelkis säger att du fortfarande har mer att bevisa, och att Gelkis tills vidare ska ta sig an Magram utan din hjälp. Jorden har viskat till Uthek om draenethyst, och du skickas långt bort till Swamp of Sorrows för en skärva som den förlorade Ongeku håller.",h="Uthek the Wise från Gelkis säger att du fortfarande har mer att bevisa, och att Gelkis tills vidare ska ta...",kw={"desolace","draenethyst","gelkis","lost one","magram","ongeku","swamp of sorrows","uthek the wise"},sec={{t="En kristall från fjärran",b="Efter Stealing Supplies berättar Uthek the Wise att ditt nästa uppdrag ligger långt bort. De som lyssnar hör många hemligheter i jorden, och en av dem Uthek har hört handlar om en röd kristall som kallas draenethyst, som nyligen kommit till detta land från en plats med flygande berg och härskande demoner. En skärva av den, säger Uthek, kommer att göra magin stark. Den förlorade Ongeku håller en skärva i Swamp of Sorrows i Eastern Kingdoms. När du återvänder kommer Uthek att söka bevis på att Gelkis fortfarande kan kalla dig vän."}},faq={{q="Vem är Uthek the Wise?",a="En Gelkis-centaur vid Gelkis Village i Desolace som säger att jorden viskar sina hemligheter till dem som lyssnar.",al={"uthek","gelkis-äldste","centaur-uppdragsgivare"}},{q="Vad är draenethyst?",a="En röd kristall som Uthek kallar ny för vår jord. Uthek säger att den kommer från ett land med flygande berg där demoner härskar.",al={"draenethyst-skärva","röd kristall","vad är draenethyst"}},{q="Vem är Ongeku?",a="En Lost One som håller en skärva draenethyst i centrala Swamp of Sorrows i Eastern Kingdoms.",al={"var finns ongeku","ongekus plats","hitta ongeku"}},{q="Varför vill Uthek ha en skärva draenethyst?",a="Uthek säger att en skärva kommer att göra magin stark.",al={"varför hämta draenethyst","uthek magi"}},{q="Vad hände före detta?",a="Stealing Supplies, som Uthek gav dig tidigare.",al={"föregående uppdrag","förutsättning"}}},fp="6,274,23.525.0,22.107.0,20.119.0,14.101.0,40.46.0,22.48.0"}
P.entries["quest:1374"] = {n="Khan Jehn",s="Efter Ongeku berättar Uthek the Wise att jorden säger att Magram blir svagare och att stunden har kommit att döda deras khan. Uthek vill att du för med dig Khan Jehns huvud till Gelkis Village.",h="Efter Ongeku berättar Uthek the Wise att jorden säger att Magram blir svagare och att stunden har kommit att...",kw={"centaur","desolace","gelkis","gelkis village","jehns huvud","khan jehn","magram","uthek the wise"},sec={{t="Magram-khanen",b="Uthek the Wise vid Gelkis Village säger att jorden talar till Uthek och berättar att Magram blir svagare. Uthek pekar ut deras khan, Jehn, som den som ska fällas och ber om huvudet från Magram-khanen. Uthek räknar med att du fortfarande ses som en vän av Gelkis när du återvänder."}},faq={{q="Vem är Khan Jehn?",a="Khan över Magram-centaurerna.",al={"khan jehn","vem är jehn","magramledare"}},{q="Varför vill Uthek the Wise döda Khan Jehn?",a="Uthek säger att jorden berättar för honom att Magram blir svagare, så nu är det dags att döda deras khan.",al={"varför döda jehn","utheks motiv","varför döda magram-khanen"}},{q="Vad kom före det här?",a="Det kommer efter Ongeku.",al={"vad kommer före khan jehn","ordning i uppdragskedjan","föregående uppdrag"}},{q="Var finns Uthek the Wise?",a="I Gelkis Village i Desolace.",al={"utheks plats","var finns uthek"}}},fp="9,194,15.282.0,17.31.0,44.91.0,22.22.0,24.30.0"}
P.entries["quest:1375"] = {n="Khan Shaka",s="Warug från Magram är nöjd med din hjälp efter Gizmo for Warug och vill nu ha huvudet av Khan Shaka, Gelkis khan. Han tänker stirra på det och skratta åt sin fiende.",h="Warug från Magram är nöjd med din hjälp efter Gizmo for Warug och vill nu ha huvudet av Khan Shaka, Gelkis...",kw={"centaur","desolace","gelkis","khan shakas huvud","khan shaka","magram","warug"},sec={{t="En rivaliserande khan",b="I Magram Village berättar Warug att du har hjälpt Magram och att han tycker om dig. Nu vill han att du dödar Khan Shaka, Gelkis khan, och tar med hans huvud. Han säger att han vill stirra på det och skratta åt honom. Han förväntar sig att du fortsätter stå på god fot med Magram."}},faq={{q="Vem är Khan Shaka?",a="Khan för centaurklanen Gelkis i Desolace, vars huvud Warug från Magram vill ha.",al={"khan shaka historia","vem är shaka","shaka centaur"}},{q="Varför vill Warug att Khan Shaka ska dö?",a="Han vill ha Shakas huvud så att han kan stirra på det och skratta åt honom.",al={"varför döda shaka","warug och shakas oförrätt"}},{q="Var är Warug?",a="I Magram Village i Desolace.",al={"khan shakas plats","var är warug"}},{q="Vad ledde fram till detta?",a="Gizmo for Warug, efter vilket Warug säger att han tycker om dig för att du hjälpt Magram.",al={"förkunskapskrav för khan shaka","föregående uppdrag shaka"}}},fp="10,172,12.273.0,18.86.0,36.61.0,15.30.0,20.76.0"}
P.entries["quest:138"] = {n="Captain Sander's Hidden Treasure",s="I Westfall leder Captain Sanders' Hidden Treasure dig inåt landet efter en ledtråd som hittats vid stranden. Spåret går österut från kusten mot en tunna nära ruinerad stenbyggnad.",h="I Westfall leder Captain Sanders' Hidden Treasure dig inåt landet efter en ledtråd som hittats vid stranden.",kw={"trasig tunna","captain sanders","skorsten","pirat","sanders skatt","skattjakt","westfall"},ang={["class:Rogue"]="Som Rogue kan du använda smygande och list för att tyda piratkoder och söka efter bortglömda byten i övergivna ruiner.",["faction:Alliance"]="Som Alliance-resenär kan du följa Sanders spår längs Westfalls laglösa kust och vanvårdade vägar inåt landet, medan den lokala milisen kämpar mot organiserade laglösa."},sec={{t="En rad gåtor inåt landet",b="Captain Sanders skickar dig inåt landet när den första chiffergåtan är löst. Ledtråden pekar bort från stranden och uppför de klippiga branterna, mot Westfalls huvudvägar."},{t="Ruiner längs vägen",b="En gammal skorsten bland ruinerna vid vägen visar var nästa stopp ligger. En övergiven tunna i närheten döljer ett nytt meddelande, och den ruinerade gården ger Sanders ett riktmärke för spåret."}},faq={{q="Vem var Captain Sanders?",a="Captain Sanders var en piratkapten som seglade längs Westfalls kuster. Han spred ledtrådar och gåtor över regionen för alla som sökte hans gömda rikedomar.",al={"captain sanders bakgrund","vem är sanders","sanders pirat"}},{q="Vart leder den här ledtråden?",a="Ledtråden skickar dig österut från det västra havet, uppför branterna och mot vägen. Bredvid en gammal stenskorsten i ruinerna döljer en trasig tunna nästa pusselbit.",al={"vart ska jag gå","ledtrådens plats","skorstenens plats"}},{q="Varför gömde Sanders skatten i flera delar?",a="Sanders delade upp vägbeskrivningen i flera gåtor för att hindra rivaler och myndigheterna från att hitta hans gömda rikedomar. Bara en ihärdig och påhittig skattletare kan följa spåret till dess slutgömma.",al={"varför ledtrådar","varför skattjakten"}},{q="Är skattjakten farlig att följa?",a="Ledtrådarna består bara av pergament och gamla behållare, men Westfalls vägar och fält är farliga. Strövande bestar, kringstrykande gnoller och fientliga medlemmar av Defias Brotherhood hotar resande nära övergivna gårdar.",al={"är det säkert","faror i westfall"}},{q="Vilka slags ruiner ligger tunnan nära?",a="Tunnan står intill den sönderfallande stenskorstenen på en ruinerad byggnad nära vägen. Många gårdar i Westfall har övergivits eller rivits under de senaste årens oroligheter.",al={"skorstensruiner","vilken byggnad"}},{q="Avslöjar det här uppdraget själva skatten?",a="Nej. Det här steget avslöjar ännu en ledtråd. Sanders lade ut flera etapper över regionen innan själva skatten kan hittas.",al={"är det här den slutliga kistan","får jag byte nu"}}},fp="32,143,25.169.0,20.186.0,24.159.0,30.174.0,44.198.0,41.216.0,45.177.0,43.126.0"}
P.entries["quest:1380"] = {n="Khan Hratha",s="Uthek the Wise minns hur du hjälpte Gelkis mot Magram och ber dig nu slå till mot Maraudine genom att döda klanens ledare, Khan Hratha. Hratha har en nyckeldel som Uthek vill att du hämtar åt honom.",h="Uthek the Wise minns hur du hjälpte Gelkis mot Magram och ber dig nu slå till mot Maraudine genom att döda...",kw={"centaur","desolace","gelkis village","khan hratha","maraudine","maraudine war horn","uthek the wise","valley of spears"},sec={{t="Utmaning av Maraudine",b="Uthek the Wise säger att Gelkis nu behöver hjälp mot Maraudine. Maraudine War Horn står på en hög klippa i Valley of Spears, och när du blåser i den kallas Khan Hratha ut. Men hornet är värdelöst utan ett munstycke till krigshornet, som är sällsynt och bara bärs av betrodda Maraudine-centaurer. När hornet ljuder kommer fler centaurer, och Hratha kommer sist."},{t="En nyckeldel",b="Khan Hratha har en nyckeldel som Uthek vill att du hämtar till Gelkis Village."},{t="När du återvänder",b="När du återvänder jublar Uthek över att Hratha är död och att Maraudine går sin undergång till mötes. Han lovar att Gelkis kommer att minnas dig när de styr över landet och att jordens andar för alltid ska sjunga ditt namn."}},faq={{q="Vem skickar dig att strida mot Khan Hratha?",a="Uthek the Wise i Gelkis Village i Desolace ber dem som har hjälpt Gelkis att göra det.",al={"vem ger khan hratha","khan hratha uppdragsgivare","var hittar man khan hratha"}},{q="Hur lockar man fram Khan Hratha till strid?",a="Uthek hänvisar dig till Maraudine War Horn i Valley of Spears, som måste blåsas i. Centaurerna svarar på ljudet, och Hratha följer efter.",al={"khan hratha plats","var finns khan hratha","hitta khan hratha"}},{q="Hur blåser du i Maraudine War Horn?",a="Hornet är värdelöst utan ett munstycke till krigshornet, och det är bara betrodda Maraudine-centaurer som sällan bär sådana.",al={"munstycke till krigshorn","hur använder man maraudine war horn","blåsa i maraudine war horn"}},{q="Vad kommer före det här?",a="Det följer på Khan Jehn. Uthek påminner dig om att du hjälpte Gelkis mot Magram.",al={"förkunskapskrav för khan hratha","vilket uppdrag före khan hratha","khan hratha uppdragskedja"}},{q="Vad har Khan Hratha?",a="Khan Hratha har en nyckeldel som Uthek ber dig ta med till honom i Gelkis Village.",al={"khan hratha föremål","maraudine nyckelfragment","vad släpper hratha"}}},fp="11,223,25.369.0,16.81.0,14.204.1,35.91.0,40.131.0,39.105.0,23.86.0,27.91.0"}
P.entries["quest:1381"] = {n="Khan Hratha",s="Warug tillkännager att Gelkis Khan har dött och säger att Maraudine står näst på tur. Warug skickar dig efter deras Khan, Hratha, och vill ha nyckeldelen som Hratha bär på.",h="Warug tillkännager att Gelkis Khan har dött och säger att Maraudine står näst på tur.",kw={"desolace","nyckelfragment","khan hratha","magram","maraudine","valley of spears","krigshorn","warug"},sec={{t="Ett horn på klippan",b="Warug vill att Maraudine Khan, Hratha, ska dö. Ett horn på en klippa i Valley of Spears utmanar honom, men det ljuder inte utan ett munstycke. Du hittar ett munstycke genom att döda Maraudine-centaurer. Efter stöten samlas Maraudine-centaurer vid tornet, och till slut visar sig Hratha."},{t="En nyckeldel",b="Hratha har en del av en nyckel, och Warug vill att du tar den till Warug i Magram Village. Warug förväntar sig att du bevisar att du är en allierad till Magram."},{t="Centaurernas herrar",b="När Hratha är död utropar Warug Magram till de mäktigaste av centaurerna, ämnade att krossa sina rivaler och härska över Desolace. Warug säger att du kommer att bli ihågkommen och skonas när resten trampas ner."}},faq={{q="Vem skickar dig för att besegra Khan Hratha?",a="Warug, i Magram Village i Desolace, efter Gelkis Khans död.",al={"vem ger uppdraget khan hratha","uppdragsgivare för khan hratha"}},{q="Hur hittar du Khan Hratha?",a="Warug säger att vägen till Hratha går genom att blåsa i hornet på klippan i Valley of Spears. Det behöver ett munstycke, som du hittar genom att döda Maraudine-centaurer. Sedan samlas centaurerna vid tornet innan Hratha visar sig.",al={"hur man tillkallar hratha","hitta khan hratha","blåsa i hornet i valley of spears"}},{q="Var visar sig Khan Hratha?",a="Hratha visar sig vid tornet i Valley of Spears när hornet har blåsts och Maraudine-centaurerna som samlas där har dödats.",al={"khan hrathas plats","var finns hratha"}},{q="Vad bär Khan Hratha på?",a="Hratha bär på en del av en nyckel, och Warug ber dig ta den till Warug.",al={"vad tappar hratha","maraudine-nyckelfragment"}}},fp="11,169,19.295.0,16.141.0,22.197.1,36.68.0,29.215.0,30.137.0,27.76.0"}
P.entries["quest:1382"] = {n="Strange Alliance",s="Captain Pentigast ser en möjlighet i att centaurklanerna i Desolace bekämpar varandra, eftersom de inte skulle kunna stoppas om de enades. Gelkis ligger i ett blodigt krig med Magram, så Pentigast skickar dig till Uthek the Wise i sydvästra Desolace för att söka en allians.",h="Captain Pentigast ser en möjlighet i att centaurklanerna i Desolace bekämpar varandra, eftersom de inte...",kw={"centaur","desolace","gelkis","magram","pentigast","strange alliance","uthek"},sec={{t="Splittrade klaner",b="Captain Pentigast ser det som tur att centaurklanerna strider mot varandra, för tillsammans skulle de inte kunna stoppas. Pentigast vill utnyttja det övertaget. Gelkis och Magram ligger i ett blodigt krig, så ett angrepp mot Magram kan vinna Gelkis förtroende."},{t="Söker Uthek",b="Uthek the Wise finns där Gelkis läger börjar, i sydvästra Desolace, och genom henne kan en allians kanske slutas. Först avvisar hon dig och säger åt dig att gå och återvända när du har dödat många Magram."},{t="Utheks svar",b="När du har besegrat tillräckligt många Magram säger Uthek att Gelkis nu viskar ditt namn, och hon ger sitt godkännande. Hon är villig att tala om vad du kan erbjuda klanen och vad den kan erbjuda dig."}},faq={{q="Vem skickar dig för att ta kontakt med Gelkis?",a="Captain Pentigast, som hoppas kunna sluta en allians med Gelkisklanen.",al={"vem ger uppdraget strange alliance","uppdragsgivare för strange alliance","vem startar strange alliance"}},{q="Var finns Uthek the Wise?",a="Där Gelkis läger börjar, i sydvästra Desolace.",al={"utheks plats","hitta uthek the wise","var finns uthek"}},{q="Varför vill Uthek the Wise inte prata med nykomlingar direkt?",a="Hon säger åt dig att gå och återvända när du har dödat många Magram.",al={"varför är uthek fientlig","uthek vill inte prata","hur pratar man med uthek"}},{q="Varför vill Alliansen sluta en pakt med Gelkis?",a="Captain Pentigast resonerar att centaurklaner som enade sig inte skulle kunna stoppas, så deras strider är en lyckträff. Gelkis ligger i krig med Magram, så ett angrepp mot Magram kan vinna Gelkis vänskap.",al={"varför alliera sig med gelkis","varför samarbeta med centaurerna","varför gelkisklanen"}}},fp="16,272,13.266.0,13.223.0,14.185.1,36.76.0,32.59.0,57.63.0,50.210.0"}
P.entries["quest:1384"] = {n="Raid on the Kolkar",s="Efter Strange Alliance skickar Uthek the Wise dig mot Kolkar-kentaurerna i nordost. Döda dem, ta deras amuletter och ta med tio tillbaka till Uthek.",h="Efter Strange Alliance skickar Uthek the Wise dig mot Kolkar-kentaurerna i nordost.",kw={"kentaur","crude charms","desolace","gelkis","kolkar","uthek"},sec={{t="Förakt för Kolkars magi",b="Uthek hånar Kolkar-kentaurerna för att de tror att deras magi är stark. Enligt Uthek vet de ingenting om magi. Du beger dig nordost till Kolkar, dödar dem och tar deras amuletter. Uthek vill ha tio Crude Charms att kasta i elden och skratta medan de brinner."},{t="Utheks dom",b="Uthek prisar dådet som en god gärning för Gelkis. Kolkar är svaga och dömda, säger Uthek, och deras magi kommer inte att rädda dem. När de har sett vad du gjort kommer de att frukta ännu mer, och rädsla gör dem svagare. I Gelkis land dör de svaga snart."}},faq={{q="Vem är Uthek the Wise?",a="Uthek the Wise väntar i Gelkis Village i Desolace. Uthek vill ha Kolkars amuletter.",al={"vem ger uppdraget raid on the kolkar","uthek","uthek the wise historia"}},{q="Var finns Kolkar?",a="I nordost, enligt Uthek.",al={"var hittar man kolkar","kolkars plats i desolace"}},{q="Vad är Crude Charms?",a="Amuletter tagna från Kolkar. Uthek vill ha tio av dem att kasta i elden och skratta åt.",al={"crude charm","kolkars amuletter"}},{q="Hur passar det här in i Gelkis-kedjan?",a="Det följer efter Strange Alliance.",al={"gelkis-kedjan","vad kommer före raid on the kolkar"}}},fp="18,169,25.252.0,15.253.1,22.84.0,29.37.0,26.85.0,40.28.0"}
P.entries["quest:1385"] = {n="Brutal Politics",s="Captain Pentigast tror att den centaurklan som vinner krigen i Desolace kommer att välla ut och hota Alliansens fästen. För att lära sig besegra dem vill Pentigast sluta en allians med en klan: bekämpa Gelkis, vinn över Magram och tala med Warug.",h="Captain Pentigast tror att den centaurklan som vinner krigen i Desolace kommer att välla ut och hota...",kw={"brutal politik","centaur","desolace","gelkis","magram","pentigast","warug"},sec={{t="Ett land i krig",b="Krig rasar genom Desolace, centaur mot centaur, och Alliansen tror att segraren kommer att välla ut mot dess fästen. Det får inte ske. För att lära sig besegra centaurerna säger Captain Pentigast att Alliansen behöver en av klanerna som vän."},{t="Magram",b="Magram strider mot Gelkis, så ett angrepp mot Gelkis kan få Magram att överväga en allians. Vinn deras gunst och bege dig sedan till Warug i Magram Village, i sydöstra Desolace. Warug varnar att du måste döda Gelkis för att bli vän med Magram."}},faq={{q="Varför vill Alliansen sluta en allians med en centaurklan?",a="Captain Pentigast tror att segraren i centaurernas krig kommer att välla ut och hota Alliansens fästen. För att lära sig besegra dem behöver Alliansen en av klanerna som vän.",al={"varför alliera sig med magram","pentigasts plan","orsak till centaurallians"}},{q="Hur vinner du Magrams gunst?",a="Magram ligger i krig med Gelkis, och om du strider mot Gelkis kan Magram överväga en allians. Warug säger att du måste döda Gelkis för att bli vän med Magram.",al={"hur får man rykte hos magram","vän med magram","döda gelkis"}},{q="Var finns Warug?",a="I Magram Village, i sydöstra Desolace.",al={"warugs plats","var finns warug","kontakt med magram"}}},fp="15,260,13.260.0,10.247.0,59.183.0,40.166.0,15.47.0"}
P.entries["quest:1386"] = {n="Assault on the Kolkar",s="Efter Brutal Politics vill Warug i Magram Village ha bevis på att du kan döda Kolkar på samma sätt som Magram gör. Gå norrut och döda Kolkar-centaurer, spejare och krossare.",h="Efter Brutal Politics vill Warug i Magram Village ha bevis på att du kan döda Kolkar på samma sätt som Magram...",kw={"brutal politics","centaur","desolace","kolkar","magram","magram village","warug"},sec={{t="Vi skrattar och dödar",b="Warug hånar Kolkar för att de tror sig vara starka, medan Magram skrattar åt dem när de dödar dem. Warug vill att du bevisar att du kan döda Kolkar på samma sätt som Magram gör, så du beger dig norrut: tolv Kolkar-centaurer, tolv spejare och sex krossare ska falla."},{t="Warugs godkännande",b="När du återvänder säger Warug att Kolkar nu är rädda för dig. Warug hoppas att du skrattade medan du dödade dem, för när du skrattar medan du dödar ser fienden sin egen svaghet."}},faq={{q="Vem skickar dig för att anfalla Kolkar?",a="Warug, från Magram, i Magram Village i Desolace.",al={"vem ger assault on the kolkar","uppdragsgivare assault on the kolkar","var får man assault on the kolkar"}},{q="Vad föregick det här steget?",a="Det följer efter Brutal Politics.",al={"föregående uppdrag","förutsättning assault on the kolkar","förkunskapsuppdrag assault on the kolkar"}},{q="Var finns Kolkar?",a="Warug säger åt dig att gå norrut för att hitta dem.",al={"kolkars plats","var finns kolkar-centaurer","var hittar man kolkar"}},{q="Varför vill Warug att Kolkar ska dödas?",a="Warug hånar Kolkar för att de tror sig vara starka och vill att du visar att du kan döda dem på samma sätt som Magram gör.",al={"varför döda kolkar","magram och kolkars rivalitet","varför hatar warug kolkar"}}},fp="21,163,20.253.0,16.165.1,35.52.0,27.27.0,29.43.0,38.112.0"}
P.entries["quest:1387"] = {n="Centaur Bounty",s="Corporal Melkins vid Nijel's Point säger att alla centaurklaner i Desolace har en sak gemensamt: grymhet. Fred kan inte råda så länge centaurerna finns kvar. Melkins ber dig jaga dem över hela landet och ta med femton öron.",h="Corporal Melkins vid Nijel's Point säger att alla centaurklaner i Desolace har en sak gemensamt: grymhet.",kw={"alliansen","belöning","centaur","centauröra","corporal melkins","desolace","öron","nijel's point"},sec={{t="En sak gemensam",b="Vid Nijel's Point beskriver Corporal Melkins ett centaurfolk uppdelat i många klaner, var och en med en ledare och egna planer, men alla lika grymma. Fred, säger Melkins, kan bara råda om centaurerna fördrivs."},{t="Öron åt Alliansen",b="Du strövar genom Desolace, jagar centaurer och tar deras öron. Melkins vill ha många, femton sammanlagt, och kallar arbetet en tjänst åt Alliansen som för krigsslutet närmare."}},faq={{q="Vem utfärdar belöningen för centaurer?",a="Corporal Melkins, stationerad vid Nijel's Point i Desolace.",al={"uppdragsgivare för centaurbelöning","vem ger belöning för centaurer","melkins belöning"}},{q="Varför vill Corporal Melkins att centaurerna dödas?",a="Melkins säger att klanerna skiljer sig åt i fråga om ledare och mål, men att alla är grymma och att fred är omöjlig så länge centaurerna finns kvar.",al={"varför döda centaurer","melkins motiv","varför centauröron"}},{q="Vad ber Corporal Melkins dig att ta med?",a="Femton centauröron från centaurer du jagar när du strövar genom Desolace.",al={"vad ska samlas in","föremål för centaurbelöning","trofé från centaurbelöning"}},{q="Vilka centaurklaner ska jagas?",a="Melkins nämner ingen särskild klan. Han säger att alla klaner delar sin grymhet och ber dig bara jaga centaurer i Desolace.",al={"vilka centaurer","mål för centaurklan","vilken klan för öron"}}},fp="14,230,19.211.0,21.180.0,37.57.0,50.123.0,44.75.0,38.114.0"}
P.entries["quest:1389"] = {n="Draenethyst Crystals",s="Magtoor vid The Harborage ber om sex draenethystkristaller, heliga för Magtoors folk och stulna av Lost Ones i Fallow Sanctuary. Utan dem fruktar Magtoors folk att också de kan gå vilse.",h="Magtoor vid The Harborage ber om sex draenethystkristaller, heliga för Magtoors folk och stulna av Lost Ones...",kw={"draenethyst","fallow sanctuary","the harborage","lost ones","magtoor","swamp of sorrows"},sec={{t="Lost Ones",b="Lost Ones i Fallow Sanctuary ser ut som Magtoors folk, men resans vedermödor till Azeroth drev dem till vansinne. De var en gång bröder, men bor nu i Sanctuary, österut, och griper eller dödar alla som kommer för nära. De har också stulit något heligt: draenethystkristaller."},{t="Utan kristallerna",b="Magtoors folk har inte styrkan att ta sig in i Fallow Sanctuary och hämta draenethysten bland hyddorna och lägereldarna. Utan kristallerna fruktar de att också de kan gå vilse. Magtoor ber dig hämta tillbaka sex stycken."}},faq={{q="Vem ber om draenethystkristallerna?",a="Magtoor, som finns vid The Harborage.",al={"vem ger draenethystkristaller","magtoors uppdrag","vem vill ha draenethyst"}},{q="Varför är draenethystkristallerna viktiga för Magtoor?",a="De är heliga för Magtoors folk. Utan dem fruktar Magtoor att också de kan gå vilse.",al={"varför draenethystkristaller","vad gör draenethystkristaller","draenethystens syfte"}},{q="Vem tog kristallerna?",a="Lost Ones i Fallow Sanctuary, österut. De var en gång Magtoors bröder, tills resans vedermödor till Azeroth drev dem till vansinne.",al={"vem stal draenethyst","vem har kristallerna","fiender i fallow sanctuary"}},{q="Var finns kristallerna?",a="Bland hyddorna och lägereldarna i Fallow Sanctuary, som ligger österut.",al={"draenethystkristallernas plats","var finns draenethystkristaller","hitta draenethyst"}},{q="Varför kan inte Magtoors folk hämta dem själva?",a="De har inte styrkan att ta sig in i Sanctuary och hämta tillbaka kristallerna.",al={"varför slåss inte magtoor","varför hjälpa magtoor"}}},fp="20,206,13.294.0,20.233.0,43.39.0,54.93.0,22.145.0,32.77.0,52.80.0"}
P.entries["quest:139"] = {n="Captain Sander's Hidden Treasure",s="En trasig tunna på Westfalls västra kust gömmer en ledtråd till Captain Sanders' Hidden Treasure. Den leder dig norrut mot en gammal kruka vid en väderkvarn nära kusten, ännu ett steg längs den avlidne piratens spår mot hans gömda rikedomar.",h="En trasig tunna på Westfalls västra kust gömmer en ledtråd till Captain Sanders' Hidden Treasure.",kw={"klippor","trasig tunna","captain sanders","gömd skatt","gammal kruka","piratledtråd","westfall","väderkvarn"},ang={["class:Rogue"]="Som skurk kan det kännas bekant att följa en skurks spår av dolda meddelanden och gömda markörer längs klipporna.",["faction:Alliance"]="Med Westfall härjat av svält och Defias-laglösa erbjuder Sanders förlorade piratbyte dig ett välkommet tillskott."},sec={{t="En pirats spår av brödsmulor",b="Captain Sanders spred ut sina anvisningar längs Westfalls västra kust. Varje ledtråd leder bara till nästa behållare, aldrig direkt till skatten. Du måste följa spåret från en tunna, kista eller kruka till nästa över klipporna för att nå hans byte."},{t="Norrut mot klipporna",b="Från den trasiga tunnan pekar pergamentet rakt norrut mot havsklipporna. Vid en avskild väderkvarn på klipporna innehåller en övergiven kruka nästa ledtråd. Murlocs och Defias-skattletare strövar omkring i kustnära Westfall, så vägen norrut är farlig."}},faq={{q="Vad är Captain Sanders' Hidden Treasure?",a="Captain Sanders var en sjörövare som gömde sina rikedomar längs Westfalls kust. I stället för en karta lämnade han nedskrivna gåtor i tunnor, kistor och krukor runt om i landskapet.",al={"sanders skatt","vad är det här för uppdrag","vem är sanders"}},{q="Vart leder den tredje ledtråden?",a="Pergamentet pekar rakt norrut från den trasiga tunnan mot havsklipporna. Nära en ensam väderkvarn innehåller en gammal kruka nästa ledtråd.",al={"vart ska jag gå","krukans plats","var ligger väderkvarnen"}},{q="Varför gömde Sanders sina anvisningar i flera delar?",a="Sanders delade upp sina anvisningar för att skydda skatten från myteriska besättningsmän och rivaliserande plundrare. En enda ledtråd skulle inte avslöja hela rutten.",al={"varför ledtrådar","varför ingen hel karta"}},{q="Kan Horde-spelare följa det här spåret?",a="Ja. Alla äventyrare kan interagera med ledtrådarna och föremålen som hör till Captain Sanders' gömma, även om Westfall ligger djupt inne på Alliance-territorium.",al={"är det här bara för alliance","horde sanders skatt"}},{q="Avslöjar den här ledtråden kistan direkt?",a="Nej. Krukan nära kustens väderkvarn innehåller ännu en ledtråd som pekar mot Sanders' kista, vilket gör detta till det näst sista steget i jakten.",al={"ligger skatten i krukan","sista steget"}},{q="Vilka faror omger stigen till väderkvarnen?",a="Riverpaw-gnoller, kustnära murlocs och kringströvande Defias-banditer jagar på Westfalls västra klippor och stränder. En rak marsch norrut kan vara förrädisk.",al={"faror på klipporna","vilka fiender finns där"}}},fx={["03354d32"]={q="Varför är ledtråden gömd i en trasig tunna?",a="Tunnan har ingen egen vilja eller något personligt på spel. Den är bara en livlös avlämningsplats som lämnats längs Westfalls kust. Captain Sanders gömde medvetet sina gåtor bland oansenligt vrakgods och övergivet skräp, så att tillfälliga plundrare och konkurrerande skurkar inte skulle kunna pussla ihop hela vägen till hans kista.",al={"varför en trasig tunna","varför ligger lappen i en tunna","sanders trasiga tunna"}}},fp="32,198,27.177.0,23.231.0,41.171.0,32.128.0,46.146.0,38.144.0,41.126.0,48.147.0"}
P.entries["quest:1392"] = {n="Noboru the Cudgel",s="I månader har Noboru plågat draeneierna i The Harborage. Noborus klubba står som ett tecken på den grymhet som Lost Ones har utsatt dem för, och du ombeds ta den till ledaren för The Harborage.",h="I månader har Noboru plågat draeneierna i The Harborage.",kw={"klubba","draenei","the harborage","lost ones","magtoor","noboru","swamp of sorrows"},sec={{t="En symbol för brutalitet",b="I månader har Noboru plågat draeneierna i The Harborage. Klubban har blivit en symbol för den grymhet som Lost Ones har utsatt dem för. Med klubban i handen bär du den till ledaren för The Harborage."},{t="Magtoors välkomsthälsning",b="Magtoor frågar om vapnet betyder att Noboru är död och kallar det en glädjens dag där. Noboru och hans gäng terroriserade draeneierna, strövade genom träskmarkerna och dödade alla som kom i deras väg. Noboru hotade deras blotta överlevnad, och de saknade styrkan att möta honom."}},faq={{q="Vem är Noboru?",a="En av Lost Ones, som har plågat draeneierna i The Harborage i månader.",al={"vem är noboru","noborus bakgrund","noboru klubba person"}},{q="Varför vill The Harborage ha Noborus klubba?",a="Klubban står för den grymhet som Lost Ones har utsatt draeneierna i The Harborage för.",al={"varför lämna in klubban","noborus klubbas syfte","varför ta klubban till magtoor"}},{q="Vem tar emot klubban?",a="Magtoor, som leder The Harborage.",al={"vem är magtoor","vart ska klubban"}},{q="Var ligger The Harborage?",a="I Swamp of Sorrows, där draeneierna från The Harborage bor.",al={"var ligger the harborage","the harborage plats"}}},fp="17,203,21.194.0,17.274.1,14.75.0,44.93.0,24.33.0,31.65.0"}
P.entries["quest:1393"] = {n="Galen's Escape",s="Galen Goodward befinner sig i Fallow Sanctuary och ber om räddning från varelserna där. Han lovar en stor skatt till den som hjälper honom ut. Den väntar i en låst kassakista vid hans läger norr om Stonard.",h="Galen Goodward befinner sig i Fallow Sanctuary och ber om räddning från varelserna där.",kw={"svart kåda","fallow sanctuary","galen goodward","galens flykt","stonard","kassakista","swamp of sorrows"},sec={{t="En vädjan om räddning",b="Galen Goodward ropar att varelserna omkring honom kommer att äta upp honom. Den som hjälper honom ur faran utlovas en stor skatt. Den finns vid hans läger, ute i träsket norr om Stonard, inlåst i en kassakista som bara kan öppnas med ett knep som endast Galen känner till. Om du hjälper honom att fly lär han dig knepet."},{t="Vid kassakistan",b="Vid lägret upptäcker du att kassakistans nyckelhål är igentäppt med svart kåda, så den går inte att öppna på det sättet. Men Galen berättade om en spärr som är gömd på kassakistans undersida. Du hittar den snabbt, och när du fäller om den öppnas kassakistan."}},faq={{q="Vem är Galen Goodward?",a="En person som hålls fången i Fallow Sanctuary och fruktar att varelserna där ska äta upp hen, och som erbjuder en stor skatt till den som hjälper hen att fly.",al={"vem är galen","galen goodward lore","galen goodward flykt"}},{q="Var ligger Galens läger?",a="I träsket norr om Stonard, i Swamp of Sorrows.",al={"var ligger galens läger","galens kassakista plats","var finns kassakistan"}},{q="Varför går det inte att öppna kassakistan på vanligt sätt?",a="Galens skatt är inlåst i en kassakista som bara kan öppnas med ett knep som endast Galen känner till. Galen lär ut knepet till den som hjälper honom att fly.",al={"hur öppnar man kassakistan","galens kassakistenyckel"}}},fp="14,206,17.322.0,16.227.1,22.146.0,30.55.0,51.149.0"}
P.entries["quest:1394"] = {n="Final Passage",s="Parqual Fintallas säger att du har klarat det här provet och de tidigare. Du skickas tillbaka till Dorn Plainstalker i Thousand Needles, som kommer att märka förändringen hos dig och se om du har blivit starkare i sinne, kropp och själ, tillräckligt för att hedras för dina insatser.",h="Parqual Fintallas säger att du har klarat det här provet och de tidigare.",kw={"dorn plainstalker","final passage","freewind post","parqual fintallas","test of faith","test of lore","thousand needles","the weathered nook"},ang={["faction:Horde"]="Den här kedjan av prövningar är avsedd för Horde och slutar med Dorn Plainstalker."},sec={{t="Tillbaka till The Weathered Nook",b="Det här är det sista steget i Test of Faith, kedjan av prövningar som Dorn Plainstalker inledde. Dorn väntar i The Weathered Nook, i en grotta som nås via en ramp norr om Freewind Post. Parqual Fintallas uppmanar dig att hålla fast vid den balans du har visat under prövningarna."},{t="Dorns välkomst",b="Dorn säger att du har varit borta från hans hem länge, och att många månar har gått sedan ditt första språng ledde dig in på den här vägen. Han tycker att du är starkare och mer upplyst än förut, vilket gläder honom, och säger att du förtjänar att hedras för att ha fullföljt hans prövningar."}},faq={{q="Vem skickar dig på det här sista steget?",a="Parqual Fintallas, som säger att du har klarat hans prov och proven före det.",al={"uppdragsgivare","vem startar final passage","parqual fintallas"}},{q="Vart ska jag gå härnäst?",a="Tillbaka till Dorn Plainstalker i Thousand Needles. Han väntar i The Weathered Nook, i en grotta som nås via en ramp norr om Freewind Post.",al={"var finns dorn","var lämnar man in uppdraget","dorn plainstalker plats","the weathered nook plats"}},{q="Vad kommer före det här?",a="Det följer på Test of Lore, en tidigare prövning i samma kedja.",al={"föregående uppdrag","förkunskapskrav","vad leder till final passage"}},{q="Vad var det allra första steget på den här resan?",a="Test of Faith, som Dorn Plainstalker gav dig i The Weathered Nook. Det här är det sista steget i den kedjan.",al={"första uppdraget","var började det här","test of faith kedja"}},{q="Varför skickar Parqual dig tillbaka till Dorn?",a="Parqual säger att Dorn kommer att märka förändringen hos dig och se att ditt sinne, din kropp och din själ är tillräckligt starka för att du ska förtjäna att hedras.",al={"varför dorn","parquals anledning"}}},fp="13,279,26.276.0,14.279.1,33.88.0,19.131.0,23.60.0,45.102.0,39.116.0"}
P.entries["quest:1396"] = {n="Encroaching Wildlife",s="Watcher Biggs var på väg mot östkusten med en karavan när Lost Ones anföll. Bara Biggs överlevde, och nu smyger vilda varelser nära lägret. Biggs ber dig hjälpa till att försvara det. Detta följer efter Help Watcher Biggs.",h="Watcher Biggs var på väg mot östkusten med en karavan när Lost Ones anföll.",kw={"karavan","lost ones","sawtooth crocolisk","sorrow spinner","förråd","swamp jaguar","swamp of sorrows","watcher biggs"},sec={{t="Ett läger under bevakning",b="Watcher Biggs karavan var på väg mot östkusten, men kom aldrig fram. Lost Ones anföll, dödade vakterna och slog sönder förråden. Bara Biggs överlevde. Biggs har svurit att skydda de förråd som finns kvar, men vilda varelser smyger nära lägret. Biggs vill att du hjälper till att försvara det."},{t="Varelser i närheten",b="Biggs nämner tre sorters varelser som tränger sig nära lägret: unga sawtooth crocolisks, sorrow spinners och swamp jaguars. Åtta crocolisks, tio spinners och tio jaguarer ska dödas."}},faq={{q="Vart var Watcher Biggs karavan på väg?",a="Mot östkusten, men karavanen nådde aldrig fram.",al={"vart var biggs på väg","karavanens destination","biggs karavanrutt"}},{q="Vilka anföll Watcher Biggs karavan?",a="Lost Ones. De dödade vakterna och slog sönder förråden. Bara Biggs överlevde.",al={"vem anföll biggs","vem förstörde karavanen","karavanöverfall"}},{q="Vilka bestar hotar lägret?",a="Unga sawtooth crocolisks, sorrow spinners och swamp jaguars smyger nära det.",al={"vilka bestar tränger sig på","vilka djur anfaller biggs","träskbestar"}},{q="Varför stannar Watcher Biggs vid lägret?",a="Biggs har svurit att skydda förråden som finns kvar från karavanen.",al={"varför stannar biggs","varför flyr han inte","biggs förråd"}}},fp="20,227,18.303.0,20.185.0,44.61.0,37.85.0,30.75.0,42.69.0"}
P.entries["quest:1398"] = {n="Driftwood",s="Efter The Lost Caravan har Watcher Biggs fortfarande en vagn att laga innan han når Nethergarde. Biggs behöver starkt, torrt trä och skickar dig österut till kusten för att leta efter drivved som torkat i solen.",h="Efter The Lost Caravan har Watcher Biggs fortfarande en vagn att laga innan han når Nethergarde.",kw={"drivved","nethergarde","soltorkad drivved","swamp of sorrows","vagn","watcher biggs"},sec={{t="Trä till vagnen",b="Watcher Biggs säger att du förtjänar stort tack och ber dig om hjälp igen. Om Biggs någonsin ska nå Nethergarde måste vagnen lagas, och då behövs starkt, torrt trä. Trä från träden i träsket är svampigt och trassligt, så det duger inte."},{t="Drivved från kusten",b="Biggs skickar dig österut till kusten för att leta efter drivved som torkats av solen. Åtta bitar ska lämnas till Biggs i Swamp of Sorrows."}},faq={{q="Varför behöver Watcher Biggs trä?",a="Vagnen måste lagas om Biggs någonsin ska nå Nethergarde, och trä från träden i träsket är för svampigt och trassligt.",al={"orsak till drivved","varför behöver biggs drivved","varför drivved"}},{q="Var skickar Watcher Biggs dig för att hämta träet?",a="Österut till kusten, för att leta efter drivved som torkats av solen.",al={"plats för drivved","var hittar man drivved","var finns träet"}},{q="Vad hände före detta?",a="The Lost Caravan kommer först, och sedan ber Biggs om mer hjälp.",al={"föregående uppdrag till drivved","vad leder till drivved","vilket uppdrag kommer före drivved"}},{q="Hur mycket drivved behövs?",a="Åtta bitar soltorkad drivved.",al={"antal drivved","hur mycket drivved"}},{q="Vad händer efter att drivveden samlats in?",a="Deliver the Shipment följer.",al={"uppföljning till drivved","vad händer efter drivved","nästa uppdrag efter drivved"}}},fp="9,196,18.244.0,24.152.0,33.121.0,47.66.0,22.64.0,29.35.0,41.29.0"}
P.entries["quest:14"] = {n="The People's Militia",s="Uppdraget är kulmen på Gryan Stoutmantles kampanj för att rensa Westfalls vägar och jordbruk från Defias Brotherhood. Genom att jaga bort de luttrade banditerna i södra The Dagger Hills visar frivilliga sitt engagemang och blir fullvärdiga medlemmar i Sentinel Hills People's Militia.",h="Uppdraget är kulmen på Gryan Stoutmantles kampanj för att rensa Westfalls vägar och jordbruk från Defias...",kw={"the dagger hills","defias highwayman","defias knuckleduster","defias pathstalker","gryan stoutmantle","people's militia","sentinel hill","westfall"},ang={["class:Paladin"]="Stoutmantle åkallar Ljusets välsignelse över de nyantagna, vilket speglar de heliga idealen om rättvisa och att skydda de värnlösa från rovgiriga laglösa.",["faction:Alliance"]="När Stormwind misslyckas med att skydda Westfall tvingas Alliansens vanliga folk utgjuta sitt eget blod för att upprätthålla ordningen i sitt hemland.",["race:Human"]="För människor från Stormwind handlar uppdraget om att stå upp för bortglömda landsmän, vars försörjning övergavs av huvudstadens politiska elit."},sec={{t="Rensa The Dagger Hills",b="Westfalls norra jordbruksmarker har lidit svårt under Defias Brotherhood, men de laglösa som undkom Stoutmantles första räder drog sig söderut till The Dagger Hills klippiga bergskammar. Från den oländiga terrängen fortsätter Defias Highwaymen, Pathstalkers och Knuckledusters att plundra gårdar och överfalla resande. För att bryta deras grepp om regionens södra halva skickar People's Militia härdade rekryter upp i bergen för att slå sönder dessa rövarband direkt."},{t="Stoutmantles korståg",b="Gryan Stoutmantle bildade People's Militia efter att ha återvänt hem från striderna mot Scourge i Lordaeron, bara för att upptäcka att Stormwinds kungliga garnison helt hade övergett Westfall. Inför ett okontrollerat kriminellt syndikat och svältande bönder som drivits bort från sin mark organiserade han lokala frivilliga för att ta till vapen. Den som fullgör denna sista patrullnivå blir formellt upptagen i milisen och får Stoutmantles välsignelse i Ljusets namn, medan kampen mot brödraskapet hårdnar."}},faq={{q="Var ligger The Dagger Hills?",a="The Dagger Hills ligger i södra Westfall, sydväst om Sentinel Hill. De oländiga åsarna och övergivna gruvmynningarna där fungerar som uppmarschområde och tillflyktsort för Defias Brotherhoods mer hårdföra kämpar.",al={"the dagger hills läge","var hittar man the dagger hills","var finns rövarna"}},{q="Varför strider People's Militia ensam mot Defias?",a="Med kung Varian Wrynn försvunnen och resurserna hårt ansträngda vägrar adelsrådet i Stormwind att skicka den kungliga armén för att skydda lantliga Westfall. Gryan Stoutmantle och de lokala bönderna hade inget val, utan måste bilda sin egen frivilligstyrka för att försvara sina hem.",al={"varför finns inga vakter från stormwind","var finns stormwinds armé","varför är westfall övergivet"}},{q="Vad får du ut av att slutföra uppdraget?",a="När rövarna, stigjägarna och knogkämparna röjs undan bryts Defias grepp om vägarna i södra Westfall, och du blir formellt upptagen i People's Militia under Gryan Stoutmantles befäl.",al={"slutföra people's militia","bli upptagen i milisen","vad får jag när jag blir klar"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en veteran som stred i Lordaeron under det tredje kriget. När han återvände hem till Westfall och såg hur Stormwinds kungarike övergav bönderna på landsbygden grundade han People's Militia vid Sentinel Hill för att göra motstånd mot Defias.",al={"gryans bakgrund","vem är stoutmantle","ledare vid sentinel hill"}},{q="Vilka Defias gömmer sig i The Dagger Hills?",a="I The Dagger Hills gömmer sig erfarna Defias Highwaymen, dödliga Pathstalkers och brutala Knuckledusters. De organiserar räder mot södra Westfall och vaktar brödraskapets inre fästen.",al={"defias fiender i södra westfall","vad är pathstalkers och knuckledusters","vilka finns i the dagger hills"}},{q="Hur hänger det här ihop med Lordaeron?",a="Gryan Stoutmantle nämner att han nyligen återvänt från Lordaerons ”besmittade länder”, där Alliansen stred mot Scourge. Att överleva den dystra krigsskådeplatsen gav honom beslutsamheten att organisera Westfalls försvar när de lokala myndigheterna svek.",al={"stoutmantle och lordaeron","lordaerons besmittade länder","gryans krigshistoria"}}},fx={["12e61ece"]={q="Varför vill Gryan Stoutmantle att de här Defias ska dödas?",a="Defias-rövare har trängt djupt in i södra Westfall, plundrat gårdar och undkommit milisens patruller. Gryans spanare spårade dem till The Dagger Hills, där de aktivt samlas för att planera nästa attack. Om de inte rensas ut och besegras nu kommer de återstående gårdarna i söder helt att hamna under deras kontroll.",al={"varför döda defias i the dagger hills","gryans motiv","varför vill gryan ha dem döda"}}},fp="20,276,24.379.0,21.422.0,27.188.0,54.236.0,39.201.0,25.264.0,45.192.0,35.225.0"}
P.entries["quest:140"] = {n="Captain Sander's Hidden Treasure",s="En whiskeydränkt ledtråd leder jakten på Captain Sanders' Hidden Treasure västerut från Westfalls kust. Spåret går ut över Great Sea, bort från fastlandets bekymmer, till en avlägsen liten ö.",h="En whiskeydränkt ledtråd leder jakten på Captain Sanders' Hidden Treasure västerut från Westfalls kust.",kw={"captain sanders","sista ledtråden","gömd skatt","ö","låst kista","gammal kanna","skattjakt","westfall"},ang={["class:Rogue"]="Det faller sig naturligt för en skurk som värdesätter piratgods att följa en skurks spår över öde stränder och ut till havs.",["race:Human"]="Som människa som försvarar Westfall mot Defias-banditer och gnoller kan du välkomna en paus från gårdspatrullen medan du letar efter en bortglömd lokal pirats gömma."},sec={{t="En sjömans spår",b="Captain Sanders strödde ut ledtrådar längs Westfalls kust för varje äventyrare som var djärv nog att följa dem. Den sista pergamentlappen kom från bottensatsen i hans favoritkanna med whiskey och anger den sista riktningen. Kaptenens ord är tydliga: gå västerut till vattenbrynet och simma sedan ut bland vågorna."},{t="Den ensliga lilla ön",b="Små klippiga utsprång reser sig ur Great Sea utanför Westfall. Simma rakt västerut så kommer du till den isolerade ön där Captain Sanders gömde sitt byte. Där väntar en låst kista vars gångjärn rostat av åratal av saltstänk. Den som är ihärdig nog kan tvinga upp den och avsluta sjörövarens spår."}},faq={{q="Vart leder den sista ledtråden?",a="Lappen i Old Jug skickar dig västerut till Westfalls kust och sedan ut på havet. Kistan väntar på en liten ö.",al={"var finns kistan","sanders skattens plats","den sista ledtrådens mål"}},{q="Vem var Captain Sanders?",a="Captain Sanders var en sjörövare som seglade längs Westfall. Han lämnade ett gåtfullt spår av ledtrådar längs strandlinjen, som ledde till en kista på en avlägsen ö i stället för att förvara bytet i en bank eller fästning.",al={"vem är captain sanders","sanders bakgrundshistoria","captain sanders bakgrund"}},{q="Varför luktar den sista ledtråden whiskey?",a="De sista instruktionerna låg gömda i Captain Sanders övergivna whiskeykanna nära kusten. Fukt och sprit fick bläcket att flyta ut med tiden, men vägbeskrivningen går fortfarande att läsa.",al={"whiskeylapp","ledtråd i gammal kanna"}},{q="Hur många steg ingår i skattjakten?",a="Jakten har fyra etapper. Den börjar med en sjöskadad karta vid kusten och fortsätter sedan genom en fotkista, en tunna och en whiskeykanna innan den slutar vid kistan på ön.",al={"hur lång är sanders uppdragskedja","sanders uppdragsdelar","captain sanders uppdragskedja"}},{q="Är det farligt att ta sig till ön?",a="Den största utmaningen är den långa simturen ut i Great Sea. I Westfalls kustvatten finns ofta aggressiva murlocs och havsbestar, medan ön är platsen där Sanders förvarade sitt gömda byte.",al={"simma till sanders kista","fara på ön","murlocs nära kistan"}},{q="I vilket skick är skattkistan?",a="Havsluften och de brusande vågorna har slitit hårt på kistan. Gångjärnen är kraftigt rostiga, men med hävstångskraft kan du tvinga upp den och nå innehållet.",al={"kistans skick","är kistan låst","rostig kista"}}},fp="32,165,16.229.0,16.257.1,31.123.0,24.189.0,44.178.0,41.169.0,33.176.0,36.139.0"}
P.entries["quest:141"] = {n="The Defias Brotherhood",s="Mathias Shaw skickar en konfidentiell rapport från Stormwind till Gryan Stoutmantle på Sentinel Hill. Shaw har undersökt det tidigare Stonemasons Guild för att hjälpa Stoutmantle att avslöja Defias Brotherhoods ursprung.",h="Mathias Shaw skickar en konfidentiell rapport från Stormwind till Gryan Stoutmantle på Sentinel Hill.",kw={"defias","sentinel hill","shaw","stenhuggare","stormwind","stoutmantle","vancleef","westfall"},ang={["class:Rogue"]="Som rogue ser du hur tvister bland Stormwinds tidigare hantverkare kan skapa problem för avlägsna bosättningar.",["faction:Alliance"]="För alliansen blottlägger stenhuggarnas uppror djupa sprickor i riket. Arbetarna som byggde upp Stormwinds stenmurar hotar nu att riva ner dem.",["race:Human"]="Som människa från Stormwind kommer den här upptäckten dig nära. Murarna kring era hem och själva katedralen byggdes av samma män som nu plundrar landsbygden i Westfall."},sec={{t="En byggmästare blir bandit",b="I månader har Gryan Stoutmantle och People's Militia kämpat mot ett till synes ansiktslöst uppror i hela Westfall. Vägstråtrövare, tjuvar och mördare slår till från vägarna och landsbygden. Master Mathias Shaw från SI:7 studerar Wiley's Note och lägger pusslet. Gillet av arkitekter och stenhuggare som byggde upp Stormwinds vita murar upplöstes aldrig. Deras ledare, Edwin VanCleef, förde dem under jord."},{t="Bitterhet och svek",b="Efter att första kriget lämnat Stormwind i aska började VanCleefs Stonemasons' Guild återuppbygga rikets huvudstad. Deras arbete gjorde åter Stormwind till mänsklighetens juvel. När arbetet var klart bröt en bitter tvist om ersättningen ut. VanCleef och hans hantverkare var missnöjda med hur kronan och House of Nobles behandlade dem. De tog till dolkar och röda bandanor och övergav sitt hantverk för ett våldsamt uppror mot tronen."},{t="Stoutmantles tvivel",b="Shaws rapport når Sentinel Hill, och Gryan Stoutmantle har svårt att ta till sig innehållet. Han minns VanCleef som en flitig och begåvad hantverkare, inte som en mördare som gömmer sig i landsbygdens skuggor. VanCleefs arbete gav tusentals återvändande invånare tak över huvudet. Milisens befälhavare kräver konkreta bevis innan han fullt ut godtar den alarmerande anklagelsen om att Stormwinds chefsarkitekt ligger bakom Westfalls förfall."}},faq={{q="Vad är Shaw's Report?",a="Mathias Shaws konfidentiella rapport innehåller hans rön om det tidigare Stonemasons Guild och Defias. Du överlämnar den till Gryan Stoutmantle.",al={"shaws rapport","mathias shaws dokument","rapporten till stoutmantle"}},{q="Vem är Edwin VanCleef?",a="Edwin VanCleef ledde Stonemasons Guild, som byggde upp Stormwind. Shaws rapport undersöker gillets senare historia.",al={"vancleefs identitet","vem är edwin vancleef","edwin vancleefs bakgrund"}},{q="Varför tvivlar Gryan Stoutmantle på rapporten?",a="Gryan Stoutmantle har svårt att smälta Shaws anklagelser och kräver konkreta bevis innan han fullt ut godtar dem. Detaljerna framkommer när han läser rapporten.",al={"varför tror gryan inte på det","stoutmantles reaktion","varför kräver gryan bevis"}},{q="Varför vände sig stenhuggarna mot Stormwind?",a="Stenhuggarna byggde upp Stormwind, men hamnade sedan i en bitter tvist om ersättningen. De var missnöjda med hur kronan och House of Nobles behandlade dem.",al={"varför är defias arga","tvisten bland stenhuggarna","vancleefs motiv"}},{q="Vilken roll spelar SI:7 i det här uppdraget?",a="Mathias Shaw från SI:7 undersöker möjliga band mellan det tidigare gillet och laglösa, och skickar sedan sina rön till Stoutmantle.",al={"varför mathias shaw","si7:s inblandning","rogue, gille och stormwind"}},{q="Vart leder utredningen härnäst?",a="Du överlämnar rapporten och hjälper sedan Stoutmantle att söka vidare efter bevis i den pågående utredningen av Defias.",al={"what comes next","nästa defias-uppdrag","efter shaws rapport"}}},fx={b90c31ae={q="Varför vill Master Mathias Shaw att den här rapporten levereras?",a="Mathias Shaw skickar sina rön till Gryan Stoutmantle så att People's Militia kan fortsätta undersöka Defias. Den konfidentiella rapporten bygger på Shaws forskning om det tidigare Stonemasons Guild.",al={"varför skicka rapporten","shaws motiv","varför skickar shaw rapporten till gryan"}},d51cfbac={q="Varför litar Mathias Shaw på att du bär rapporten?",a="Du kom till Stormwind på Gryan Stoutmantles personliga rekommendation och har redan bevisat vad du går för ute på fältet. I stället för att riskera de officiella SI:7-kurirerna eller stadsvakterna när Defias-infiltratörer kanske håller utkik litar Shaw på att du för hans konfidentiella rön direkt tillbaka till People's Militia.",al={"varför inte skicka vakter","varför använda en äventyrare","varför jag och shaw"}}},fp="22,201,23.426.1,23.458.1,23.423.1,22.139.0,22.118.0,49.171.0,47.167.0,39.129.0,40.106.1"}
P.entries["quest:1418"] = {n="Neeka Bloodscar",s="Helgrum the Swift skickar dig från Stonard till Kargaths utpost i Badlands för att tala med dess spejarmästare, Neeka Bloodscar. Förbindelsen mellan Stonard och Kargath bryts ofta.",h="Helgrum the Swift skickar dig från Stonard till Kargaths utpost i Badlands för att tala med dess...",kw={"badlands","spejarmästare","helgrum the swift","kargath","loch modan","neeka bloodscar","stonard","swamp of sorrows"},sec={{t="En bruten förbindelse",b="Badlands är ett ogästvänligt område nära Loch Modan, som kontrolleras av Alliansen. Därför bryts förbindelsen mellan Stonard och Kargath ofta. Helgrum ber dig visa vad du går för genom att resa till Badlands och tala med Neeka Bloodscar, som är områdets spejarmästare. Neekas rapport ska sedan skickas tillbaka till Helgrum."},{t="Neekas svar",b="Neeka berättar att en kurir skickades mot Stonard för knappt tre dagar sedan. Om Stonard inte har fått något från Neeka måste kuriren ha misslyckats. Neeka hoppas att nästa kurir är skickligare eller har mer tur."}},faq={{q="Vart skickar Helgrum the Swift dig?",a="Från Stonard till utposten Kargath i Badlands för att tala med Neeka Bloodscar.",al={"vart ska jag gå","neeka bloodscars plats","var finns neeka"}},{q="Varför har förbindelsen mellan Stonard och Kargath brutits?",a="Badlands är ogästvänligt och ligger nära Loch Modan, som kontrolleras av Alliansen. Därför bryts förbindelsen mellan Stonard och Kargath ofta.",al={"varför bryts förbindelsen","kommunikationsproblem i badlands","varför från stonard till kargath"}},{q="Vem är Neeka Bloodscar?",a="Neeka Bloodscar är spejarmästare vid utposten Kargath i Badlands.",al={"vem är neeka","neekas roll","neeka bloodscar-bakgrund"}},{q="Vad händer efter att du har talat med Neeka Bloodscar?",a="Därefter ska du rapportera till Helgrum.",al={"vad händer sedan","uppföljningsuppdrag","efter neeka bloodscar"}}},fp="15,170,10.325.0,14.199.1,38.86.0,57.128.0,23.73.0,47.26.0"}
P.entries["quest:1419"] = {n="Coyote Thieves",s="I Kargaths utpost vill Neeka Bloodscar att du jagar Badlands klippprärievargar, tåliga bestar som vågat smyga in i Kargath och stjäla dess mat. Neeka ber om trettio käkben.",h="I Kargaths utpost vill Neeka Bloodscar att du jagar Badlands klippprärievargar, tåliga bestar som vågat smyga...",kw={"badlands","tjuvar i kargath","klippprärievarg","käkben","kargath","neeka bloodscar"},sec={{t="Tjuvar i Kargath",b="Neeka Bloodscar frågar om du har tillbringat många dagar i Badlands, känt hettan och mött bestarna på de dammiga slätterna. Klippprärievargar är en tålig ras, och de har smugit sig in i Kargath för att stjäla mat från utposten. Neeka vill att du jagar dem och tar med deras käkben tillbaka. Ta med tillräckligt många, så kanske Neeka tror att du känner till Badlands."}},faq={{q="Varför vill Neeka Bloodscar ha käkben från prärievargar?",a="Klippprärievargar har smugit sig in i Kargath och stulit från matförråden. Neeka vill att du jagar dem och tar med käkben som bevis på att du känner till Badlands.",al={"varför käkben från prärievargar","neeka bloodscars motiv","varför samla käkben"}},{q="Var orsakar prärievargarna problem?",a="Klippprärievargar strövar omkring på Badlands dammiga slätter och har smugit sig in i utposten Kargath för att stjäla mat.",al={"prärievargarnas plats","var hittar man klippprärievargar","var finns prärievargarna"}},{q="Hur många käkben vill Neeka Bloodscar ha?",a="Trettio käkben från prärievargar, lämnade till Neeka Bloodscar i Kargath.",al={"hur många käkben","antal käkben från prärievargar"}},{q="Vem är Neeka Bloodscar?",a="Neeka Bloodscar finns vid utposten Kargath i Badlands, där Neeka delar ut den här jakten.",al={"vem är neeka","neeka bloodscar"}}},fp="14,206,18.339.0,46.154.0,38.116.0,44.62.0,23.94.0"}
P.entries["quest:142"] = {n="The Defias Brotherhood",s="I Westfall förmedlar Defias Brotherhood order via kurirer. Gryan Stoutmantle skickar ut Folkets milis efter en svårfångad budbärare vars meddelanden kan avslöja hur banditerna leder sina styrkor.",h="I Westfall förmedlar Defias Brotherhood order via kurirer.",kw={"defias","jangolode","budbärare","moonbrook","stenbrott","saldean","stoutmantle","vancleef","westfall"},ang={["class:Rogue"]="Som skurk kan du se hur skickliga spejare och ficktjuvar samordnar ett omfattande skuggnätverk mitt framför milisens näsa.",["faction:Alliance"]="Utan stöd från Stormwinds kungliga garnison sköter Folkets milis Westfalls underrättelsearbete på egen hand och spårar kurirer längs ensliga grusvägar.",["race:Human"]="Som människa kan du följa meddelandena till Edwin VanCleef och se de bittra, kvarstående följderna av Stormwinds politiska konflikter och arbetsmarknadstvister."},sec={{t="Fånga kuriren",b="Gryan Stoutmantles spejare har sett en svårfångad Defias Messenger färdas mellan Moonbrook, Gold Coast Quarry och Jangolode Mine. Till skillnad från busarna som håller landsbygden i sitt grepp bär kuriren skriftliga order genom trakten. Stoutmantle vill att han fångas eller dödas, så att Folkets milis kan läsa hans väska och ta reda på var broderskapet leder sina styrkor."},{t="Ett spår av bläck",b="Det återfunna meddelandet bekräftar att Edwin VanCleef, den legendariske före detta ledaren för Stonemasons Guild, personligen styr Defias-upproret. Det bekräftar hans befäl över de lokala cellerna, men avslöjar inte var han har sin hemliga bas."},{t="En lyckosam vändning",b="Meddelandet bekräftar VanCleefs ledarskap, och Folkets milis får en oväntad chans. En desperat bandit ertappas när han försöker stjäla Farmer Saldeans vagn och går med på att förråda sina kumpaner i utbyte mot sitt liv. Med skriftliga bevis i handen riktar Stoutmantle nu in sig på förrädaren och hoppas att han kan leda en eskort till hjärtat av Defias gömställe."}},faq={{q="Var färdas Defias Messenger?",a="Defias Messenger börjar sin patrull i Moonbrook, utanför smedjan. Han går norrut till Gold Coast Quarry och Jangolode Mine, går in i båda gruvorna och följer sedan samma väg tillbaka till Moonbrook.",al={"budbärarens rutt","var finns defias messenger","hitta budbäraren"}},{q="Vad avslöjar det uppsnappade meddelandet?",a="Stoutmantle hoppas att kurirens order ska avslöja Brotherhoods befälsstruktur och hjälpa till att hitta dess gömställe. Meddelandets innehåll blir känt när det har återfunnits.",al={"vad stod i meddelandet","mystiskt meddelande","vancleefs lapp"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle leder Folkets milis från dess högkvarter i Sentinel Hill. Eftersom det finns för få kungliga vakter från Stormwind organiserar han frivilliga och äventyrare för att försvara Westfall mot Defias-rövare.",al={"stoutmantles roll","vem ger uppdraget"}},{q="Varför besöker budbäraren gruvorna?",a="Broderskapet har lagt beslag på Westfalls mineraltillgångar och använder Jangolode Mine och Gold Coast Quarry för råmaterial, skydd och samlingsplatser. Budbäraren förmedlar information mellan verksamheterna och Brotherhoods ledning.",al={"varför gold coast quarry","varför jangolode mine"}},{q="Avslöjar fångsten av budbäraren var Defias gömställe finns?",a="Stoutmantle tänker använda de uppsnappade orderna för att fortsätta sökandet efter gömstället. Du får nästa ledtråd när du återvänder till honom.",al={"hittade vi gömstället","var finns gömstället"}},{q="Vem är Edwin VanCleef?",a="Edwin VanCleef var stormästare i Stonemasons Guild, som återuppbyggde Stormwind. Stoutmantles utredning undersöker VanCleefs möjliga koppling till Brotherhood.",al={"vem är vancleef","defias ledare"}}},fx={["885172ef"]={q="Varför vill Gryan Stoutmantle att det här ska göras?",a="Gryan Stoutmantle och People's Militia utkämpar en desperat kampanj för att återta Westfall från Defias Brotherhood. Milisen vet att tjuvarna verkar på provinsens gårdar och i dess gruvor, men vet fortfarande inte var brödraskapets främsta gömställe ligger. Att genskjuta den här budbäraren är Stoutmantles bästa ledtråd till var deras fäste finns och hur han kan slå direkt mot deras ledning.",al={"gryan stoutmantles motiv","varför genskjuta budbäraren","varför fånga defias-budbäraren"}},fc5d2b39={q="Vem är Defias-budbäraren?",a="Kuriren är en Defias-agent som har i uppdrag att föra meddelanden mellan brödraskapets viktigaste fästen i Westfall: den ockuperade staden Moonbrook, Gold Coast Quarry och Jangolode Mine. Eftersom han samordnar rörelserna mellan dessa utspridda utposter kan milisen få en sällsynt inblick i konspiratörernas befälsstruktur genom att fånga honom eller beslagta hans order.",al={"defias-budbärare","vem är budbäraren","mål för budbäraren"}},a4c1678d={q="Varför behöver Gryan Stoutmantle dig för det här uppdraget?",a="People's Militia är pressad till sin yttersta gräns. Den måste hålla en tunn försvarslinje runt Sentinel Hill samtidigt som den skyddar flyktingbönder från härjande banditer och gnolls. Stormwind har vägrat skicka förstärkningar eller kungliga trupper till Westfall, så Stoutmantle saknar de extra soldater som behövs för att jaga kurirer genom fientligt territorium.",al={"varför skicka mig","varför gör gryan det inte själv","varför behöver milisen dig"}}},fp="22,116,24.376.0,14.251.1,17.347.1,39.213.0,41.173.1,25.204.0,40.235.0,54.134.0,22.171.1"}
P.entries["quest:1420"] = {n="Report to Helgrum",s="Neeka Bloodscar har skrivit en ny rapport till Helgrum the Swift i Stonard och ber dig ta med den dit. Det här följer på ditt besök hos Neeka i Kargath.",h="Neeka Bloodscar har skrivit en ny rapport till Helgrum the Swift i Stonard och ber dig ta med den dit.",kw={"badlands","helgrum the swift","hordens underrättelser","neeka bloodscar","outrunner","rapport","stonard"},sec={{t="En rapport till Stonard",b="Neeka Bloodscar har skrivit en ny rapport till Helgrum i Stonard och räcker över den till dig. Neeka tillägger att den som kallar sig outrunner inte får gå vilse eller falla för en fiende."},{t="Helgrum läser rapporten",b="När Helgrum läser Neekas rapport ser han att även Alliansen har sina egna problem. Helgrum tror också att Horde och Alliansen kanske visar sig ha några gemensamma fiender."}},faq={{q="Vem skickar dig med rapporten?",a="Neeka Bloodscar, som har skrivit en ny rapport till Helgrum.",al={"vem ger rapporten till helgrum","uppdragsgivare rapport till helgrum","vem startar det här uppdraget"}},{q="Vart ska rapporten levereras?",a="Till Helgrum the Swift i Stonard.",al={"var lämnar man in rapporten till helgrum","helgrums plats","var finns helgrum"}},{q="Vad kommer före detta?",a="Det följer på det tidigare steget där Helgrum skickade dig för att tala med Neeka Bloodscar i Kargath.",al={"föregående uppdrag","förutsättning för rapport till helgrum","vilket uppdrag kommer först"}}},fp="17,153,20.185.0,24.162.1,30.60.0,43.32.0,23.95.0"}
P.entries["quest:1421"] = {n="The Lost Caravan",s="Efter Encroaching Wildlife har Watcher Biggs ännu ett ärende åt dig. Biggs blev omtöcknad när Lost Ones anföll karavanen, men såg ändå en vagn släpas bort till Fallow Sanctuary, Lost Ones by i norr. En kista med värdefulla reagenser fanns i vagnen, och Biggs vill att du hämtar tillbaka dem.",h="Efter Encroaching Wildlife har Watcher Biggs ännu ett ärende åt dig.",kw={"the dark portal","fallow sanctuary","lost ones","nethergarde keep","swamp of sorrows","watcher biggs","magikernas reagenser"},sec={{t="Den stulna vagnen",b="Biggs slogs medvetslös under anfallet, men såg i hast en av karavanens vagnar släpas bort till Fallow Sanctuary, Lost Ones by i norr. I vagnen fanns en kista med reagenser som Nethergarde Keeps magiker värdesätter i sina studier. Biggs vill att du hittar kistan och för tillbaka innehållet."},{t="Besked från Biggs",b="När du återvänder med reagenserna är Biggs nöjd, för nu kan Nethergardes magiker fortsätta sitt arbete. Biggs vet inte vad det arbetet går ut på, bara att det har med The Dark Portal i Blasted Lands att göra och är mycket viktigt för att hålla Alliansen trygg."}},faq={{q="Vem är Watcher Biggs?",a="Watcher Biggs förlorade en vagn från karavanen till Lost Ones och vill få tillbaka reagenserna den bar.",al={"watcher biggs","vem ger uppdraget lost caravan"}},{q="Vart förde Lost Ones karavanens kista?",a="Biggs såg vagnen släpas bort till Fallow Sanctuary, Lost Ones by i norr, med kistan ombord.",al={"karavanens kista plats","var ligger fallow sanctuary","var finns reagenserna"}},{q="Varför är reagenserna viktiga?",a="Nethergarde Keeps magiker behöver dem för sina studier.",al={"varför reagenserna är viktiga","nethergardes reagenser syfte"}},{q="Vad händer när kistan har återfunnits?",a="Driftwood följer när Biggs har fått reagenserna.",al={"nästa uppdrag efter lost caravan","lost caravan uppdragskedja"}}},fp="16,303,16.322.0,15.274.1,21.103.0,47.116.0,31.65.0,38.46.0"}
P.entries["quest:1422"] = {n="Threat From the Sea",s="Efter Lack of Surplus börjar Tok'Kar arbeta på ditt vapen och säger åt dig att tala med Katar i Swamp of Sorrows. Katar har sagt att patrullerna längs stranden skulle behöva hjälp.",h="Efter Lack of Surplus börjar Tok'Kar arbeta på ditt vapen och säger åt dig att tala med Katar i Swamp of...",kw={"strand","katar","patrull","kust","swamp of sorrows","hotet från havet","tok'kar"},sec={{t="Ett ord med Katar",b="Medan Tok'Kar arbetar på ditt vapen föreslår han att du talar med Katar, som har sagt att patrullerna längs stranden skulle behöva hjälp. Tok'Kar delar läger med några fyllon och föredrar att du håller huvudet klart och vapnen redo framför att slå dig ihop med dem."},{t="Över havets dån",b="Katar ber dig vara tyst en stund. Ovanför havets dova dån hörs fortfarande fiskmännens vidriga gurglande."}},faq={{q="Varför skickar Tok'Kar dig till Katar?",a="Tok'Kar har fullt upp med ditt vapen och föredrar att du håller huvudet klart och vapnen redo i stället för att supa med fyllona som delar läger med honom.",al={"varför tala med katar","tok'kars anledning","varför besöka katar"}},{q="Vad behöver Katar hjälp med?",a="Katar har sagt att patrullerna längs stranden skulle behöva hjälp, och det är den hjälpen Katar vill ha.",al={"katars problem","vad vill katar","katars patrull"}},{q="Vad hände före det här steget?",a="Det följer efter Lack of Surplus, då Tok'Kar börjar arbeta på ditt vapen.",al={"föregående uppdrag","förutsättning","hotet från havet uppdragskedja"}}},fp="19,176,17.260.0,24.126.1,35.133.0,37.105.0,27.75.0"}
P.entries["quest:1423"] = {n="The Lost Supplies",s="En liten, stadig tunna har skarvarna tätade med starkt luktande gult vax. En stämpel på botten anger Quartermaster Lungertz och Nethergarde Keep, och dit hör den.",h="En liten, stadig tunna har skarvarna tätade med starkt luktande gult vax.",kw={"tunna","darkshire","lost supplies","nethergarde keep","quartermaster lungertz","swamp of sorrows"},sec={{t="En stämplad tunna",b="Starkt luktande gult vax tätar skarvarna på den här kompakta, bastanta tunnan. På undersidan står det Quartermaster Lungertz, Nethergarde Keep på en stämpel, så tunnan är avsedd för kvartermästaren där."},{t="Hälsning från kvartermästaren",b="Quartermaster Lungertz tackar dig. Förnödenheter kommer på avvägar hela vägen från Darkshire till Nethergarde, så det är glädjande att några har återfunnits."}},faq={{q="Vem ska få de förlorade förnödenheterna?",a="Tunnan är märkt till Quartermaster Lungertz vid Nethergarde Keep.",al={"vem ska få tunnan","mottagare av förlorade förnödenheter","vart ska tunnan"}},{q="Hur kan du se vem tunnan tillhör?",a="På tunnans botten finns en stämpel med Quartermaster Lungertz och Nethergarde Keep.",al={"tunnans märkning","läsa tunnans märkning","quartermaster lungertz stämpel"}},{q="Hur ser tunnan ut?",a="Det är en liten, stadig tunna med starkt luktande gult vax längs skarvarna.",al={"tunna med förlorade förnödenheter","beskrivning av tunnan"}}},fp="17,169,16.185.0,27.134.1,42.68.0,37.90.0,31.69.0"}
P.entries["quest:1424"] = {n="Pool of Tears",s="I Stonard ber Fel'zerul dig att leta efter Atal'ai-artefakter kring Pool of Tears. Hövdingen skickade Fel'zeruls folk för att undersöka märkliga händelser vid The Temple of Atal'Hakkar, men när de kom fram fann de att det hade sjunkit.",h="I Stonard ber Fel'zerul dig att leta efter Atal'ai-artefakter kring Pool of Tears.",kw={"artefakter","atal'ai","fel'zerul","gröna drakar","pool of tears","stonard","swamp of sorrows","the temple of atal'hakkar","hövding"},sec={{t="Sunken Temple",b="Atal'ai-trollen är mörka magiker, en stam ökänd för förbjuden magi. När Fel'zeruls grupp nådde The Temple of Atal'Hakkar blev de häpna över att finna det sjunket. Gröna drakar vakar nu över platsen och kallar sig Azeroths beskyddare."},{t="Pusselbitar",b="Fel'zerul vill ta reda på vad som hände och ber dig söka igenom Pool of Tears efter Atal'ai-artefakter, så att pusslet kan börja läggas. Ingen vet vilka mörka riter som utövades i templet, bara att stora magiska krafter användes. Fel'zerul hoppas att Atal'ais besvärjelser kan visa sig användbara för Horden och vill förstå vad trollen hoppades uppnå och vad som gick så fruktansvärt fel."}},faq={{q="Vem är Fel'zerul?",a="Fel'zerul finns i Stonard och är en av dem som Hövdingen skickade för att undersöka märkliga händelser vid The Temple of Atal'Hakkar.",al={"fel'zerul","vem ger pool of tears"}},{q="Varför är Horden intresserad av Atal'ai-trollen?",a="Fel'zerul påpekar att stora magiska krafter användes där och tror att Atal'ais besvärjelser kan visa sig användbara för Horden.",al={"varför horden vill ha atal'ai","atal'ai-magi horden"}},{q="Var finns Atal'ai-artefakterna?",a="De ligger på botten av Pool of Tears, nära templet.",al={"atal'ai-artefakternas plats","var hitta artefakter","pool of tears-artefakter"}},{q="Vem vaktar det sjunkna templet nu?",a="Gröna drakar vakar över platsen och kallar sig Azeroths beskyddare.",al={"varför är gröna drakar här","gröna drakar temple of atal'hakkar","gröna drakar swamp of sorrows"}},{q="Vad händer när artefakterna har lämnats in?",a="Därefter följer Atal'ai Exile.",al={"nästa uppdrag efter pool of tears","fortsättning på pool of tears","vad efter pool of tears"}}},fp="13,217,17.253.0,18.423.0,17.114.0,50.126.0,40.58.0,33.77.0,50.26.0"}
P.entries["quest:1425"] = {n="Deliver the Shipment",s="Efter Driftwood har Watcher Biggs ett sista uppdrag åt dig medan vagnen repareras. Biggs har packat ihop de viktiga förnödenheter som räddats undan ogreangreppen och vill att du tar dem till Quartermaster Lungertz vid Nethergarde Keep.",h="Efter Driftwood har Watcher Biggs ett sista uppdrag åt dig medan vagnen repareras.",kw={"azoran crystals","blasted lands","the dark portal","nethergarde keep","quartermaster lungertz","försändelse","swamp of sorrows","watcher biggs"},sec={{t="En sista leverans åt Biggs",b="Medan Biggs reparerar vagnen har de viktiga förnödenheter som räddats undan ogreangreppen packats ihop åt dig att ta till Nethergarde Keep. Fästet ligger i Blasted Lands norra kullar och vakar över The Dark Portal. Biggs beskriver vägen: följ vägen österut, ta söderut in i Blasted Lands där den delar sig och sväng vänster vid nästa vägskäl. Han varnar dig för att vara försiktig."},{t="Vid Nethergarde",b="Quartermaster Lungertz blir förvånad över att få ett paket från Biggs karavan, eftersom fästet hade gett upp både karavanen och Biggs som förlorade. Lungertz tackar dig och hoppas att förnödenheterna innehåller Azoran Crystals, ett välbehövligt reagens som börjar ta slut i fästets förråd."}},faq={{q="Vem skickar leveransen till Nethergarde?",a="Watcher Biggs, som stannar kvar för att reparera vagnen, packade ihop viktiga förnödenheter som räddats undan ogreangreppen.",al={"vem ger uppdraget leverera försändelsen","uppdragsgivare för leverera försändelsen","watcher biggs leverans"}},{q="Vart ska leveransen?",a="Den ska till Quartermaster Lungertz vid Nethergarde Keep, i Blasted Lands norra kullar.",al={"var ligger nethergarde keep","hur tar man sig till nethergarde","quartermaster lungertz plats"}},{q="Vad kommer direkt före den här leveransen?",a="Den följer efter Driftwood.",al={"förutsättning för leverera försändelsen","vilket uppdrag kommer före leverera försändelsen"}},{q="Vilken väg leder från träsket till fästet?",a="Följ vägen österut, ta söderut in i Blasted Lands där vägen delar sig och välj sedan vänster väg vid nästa vägskäl.",al={"vägbeskrivning till nethergarde keep","vägen till blasted lands"}},{q="Vad vakar Nethergarde Keep över?",a="Det vakar över The Dark Portal.",al={"nethergarde keeps syfte","varför ligger nethergarde i blasted lands"}}},fp="20,232,25.377.0,14.263.1,38.99.0,36.92.0,41.21.0,44.117.0,39.36.0"}
P.entries["quest:1426"] = {n="Threat From the Sea",s="När Tok'Kar skickar dig att tala med Katar, gör Katar sitt hat mot havet tydligt. Katar finner ett visst nöje i att se fiskmännen dödas av alla som gör Hordens vilja, och frågar hur många du kan dräpa och om du vill mäta dig med deras starkaste sort.",h="När Tok'Kar skickar dig att tala med Katar, gör Katar sitt hat mot havet tydligt.",kw={"katar","träskköttätare","träskbläckspottare","träskmurlock","murlock","swamp of sorrows","threat from the sea"},sec={{t="Ett agg mot havet",b="Katar känner ingen tillgivenhet för havet eller någon varelse som kommer därifrån och kallar det en härskarinna som är stark men blind, känslokall och brutal. Det skulle glädja Katar att döda hundratals fiskmän, om det vore möjligt, och det ger en viss tillfredsställelse att se dem falla för dem som tjänar Horden. Katar, i Swamp of Sorrows, ber dig dräpa träskmurlocker, träskbläckspottare och träskköttätare."},{t="Katars dom",b="När du återvänder säger Katar att havet kan verka vidsträckt och obevekligt, men att dess egna avkommor nu bär dina blodiga spår. Fiskmännen känner nu smärta och måste återuppbygga sina led, vilket Katar finner gott, och Katar ler varje gång någon tystas. Katar bjuder in dig att återvända och dräpa fler."}},faq={{q="Varför vill Katar att murlockerna ska utrotas?",a="Katar hyser ingen kärlek till havet eller det som kommer därifrån och skulle gärna se hundratals fiskmän dödas. Att se dem dö för dem som gör Hordens vilja ger ett visst nöje.",al={"varför döda murlocker","katar murlocker","varför hata havet"}},{q="Var äger jakten rum?",a="I Swamp of Sorrows, bland träskmurlocker, träskbläckspottare och träskköttätare.",al={"var finns träskmurlocker","threat from the sea plats"}},{q="Vem ger dig jakten?",a="Katar, som Tok'Kar skickade dig till i Swamp of Sorrows.",al={"vem ger threat from the sea","uppdragsgivare för threat from the sea"}},{q="Vad föregår den här jakten?",a="Den följer den första Threat From the Sea, där Tok'Kar skickade dig till Katar.",al={"förutsättning för threat from the sea","föregående uppdrag till threat from the sea"}}},fp="19,288,24.401.0,15.279.1,42.185.0,32.85.0,20.67.0,28.88.0"}
P.entries["quest:1427"] = {n="Threat From the Sea",s="Efter ditt arbete för Katar får du höra att du ska träffa Tok'Kar en gång till innan du vilar. Katar tror att Tok'Kar har färdigställt några vapen medan du var borta, och att du får ett som tack för din hjälp.",h="Efter ditt arbete för Katar får du höra att du ska träffa Tok'Kar en gång till innan du vilar.",kw={"katar","murloc","sågtandskött","swamp of sorrows","hot från havet","tok'kar"},sec={{t="Tillbaka till Tok'Kar",b="Katar tror att Tok'Kar har färdigställt några vapen medan du var borta, och att Tok'Kar ger dig ett som tack för din hjälp. Katar tillägger att du gärna får pröva dess styrka mot fiskmännen när du är redo, men bara för att göra Katar ännu nöjdare."},{t="Tok'Kars tack",b="Tok'Kar är glad att se dig tillbaka och säger att fler vapen har tillverkats för kriget mot murlocerna. Som tack för att du kom med färskt sågtandskött och fick Katar att le lite, ger han dig ett."}},faq={{q="Vem skickar dig för att tala med Tok'Kar?",a="Det gör Katar, som säger åt dig att träffa Tok'Kar en gång till innan du vilar i Swamp of Sorrows.",al={"vem ger uppdraget","var får jag hot från havet","vem startar det här"}},{q="Varför erbjuder Tok'Kar ett vapen?",a="Katar tror att Tok'Kar har färdigställt några vapen medan du var borta, och att du får ett som tack för din hjälp.",al={"varför ger tok'kar ett vapen","vad tillverkade tok'kar","varför får man belöning av tok'kar"}},{q="Vad händer efter att du talat med Tok'Kar?",a="Continued Threat följer.",al={"vad är nästa uppdrag","vart går man efter det här","vad följer efter hot från havet"}}},fp="19,199,15.236.0,16.208.1,36.89.0,33.127.0,44.25.0"}
P.entries["quest:1428"] = {n="Continued Threat",s="Katar gläds åt att ditt hat mot fiskmännen växer i takt med hennes eget och skickar dig att jaga fler fiskmän på stranden i Swamp of Sorrows.",h="Katar gläds åt att ditt hat mot fiskmännen växer i takt med hennes eget och skickar dig att jaga fler fiskmän...",kw={"continued threat","fiskmän","katar","marsh flesheater","marsh inkspewer","marsh oracle","murlocs","swamp of sorrows"},sec={{t="Fler längs stranden",b="Katar säger åt dig att leta upp fler fiskmän längs stranden och återvända när du har fått nog av striderna. Marsh inkspewers, marsh flesheaters och marsh oracles är målen. Katar kommer inte att känna någon glädje förrän havet och alla dess barn har tystats, allra minst de motbjudande fiskmännen."}},faq={{q="Vem ger uppdraget?",a="Katar, i Swamp of Sorrows.",al={"vem startar continued threat","uppdragsgivare för continued threat","katar swamp of sorrows"}},{q="Vilka varelser ska jagas?",a="Katar vill att du jagar marsh inkspewers, marsh flesheaters och marsh oracles längs stranden.",al={"vad ska dödas i continued threat","målen i continued threat","vilka murlocs"}},{q="Varför vill Katar att murlocs ska utrotas?",a="Katar kommer inte att känna någon glädje förrän havet och dess avkomma har tystats, framför allt fiskmännen.",al={"varför döda murlocs","katars motiv","varför hata fiskmän"}},{q="Vad hände före det här steget?",a="Det följer på det föregående Threat From the Sea, efter vilket Tok'Kar erbjöd dig ett vapen.",al={"förutsättning för continued threat","föregående uppdrag till continued threat"}}},fp="16,160,20.310.0,21.31.0,33.82.0,39.95.0,27.86.0"}
P.entries["quest:1429"] = {n="The Atal'ai Exile",s="När du var vid Pool of Tears kom en av Fel'zeruls spejare tillbaka med en skriftrulle, skriven i blod på torkat skinn. Fel'zerul packar nu ihop artefakterna du samlade och skickar dig långt norrut till The Hinterlands för att hitta en landsförvisad Atal'ai-präst.",h="När du var vid Pool of Tears kom en av Fel'zeruls spejare tillbaka med en skriftrulle, skriven i blod på...",kw={"atal'ai exile","fel'zerul","hakkar","the hinterlands","jammal'an","pool of tears","shadra'alor","swamp of sorrows","witherbark"},sec={{t="En dom i blod",b="Skriftrullen innehåller en dom mot en Atal'ai-präst, ett öde värre än döden bland hans eget folk. Han förvisades till att leva bland Witherbark-trollen, långt norrut i The Hinterlands. Fel'zerul packar ihop artefakterna och skickar dig för att hitta den landsförvisade, ta reda på vad de egentligen används till och återvända."},{t="Den landsförvisades ord",b="När den landsförvisade får se paketet känner han igen artefakterna som Atal'ais kallelseredskap. Han säger att lärjungarna i Chamber of Blood leds av Jammal'an the Prophet mot sitt utvalda öde och undrar om Hakkar har återvänt till templet."}},faq={{q="Vem skickar dig för att hitta Atal'ai Exile?",a="Fel'zerul i Stonard, som packar ihop artefakterna du samlade och skickar dig norrut till The Hinterlands.",al={"vem ger atal'ai exile","uppdragsgivare för atal'ai exile","vem startar uppdraget"}},{q="Var finns Atal'ai Exile?",a="I The Hinterlands, där han lever bland Witherbark-trollen vid templet i Shadra'Alor.",al={"var finns den landsförvisade","atal'ai exile plats","var hittar man atal'ai exile"}},{q="Vilken dom fick prästen?",a="En skriftrulle, skriven i blod på torkat skinn, dömer prästen till ett öde värre än döden bland Atal'ai: förvisning bland Witherbark-trollen i The Hinterlands.",al={"varför förvisades han","vilken dom fick han","atal'ai exile bakgrund"}},{q="Vad tar du med dig till den landsförvisade?",a="Ett paket med Atal'ai-artefakter som samlades vid Pool of Tears. Fel'zerul vill att den landsförvisade ska avslöja vad de egentligen används till.",al={"vilket paket tar du med","vad är artefakterna","atal'ai-artefakternas syfte"}},{q="Vad kommer direkt före den här resan?",a="Den följer efter Pool of Tears, där Fel'zerul lät dig samla Atal'ai-artefakter.",al={"föregående uppdrag","förutsättning","vad leder fram till atal'ai exile"}}},fp="17,242,19.310.0,17.256.1,40.100.0,35.83.0,39.158.0,35.116.0,40.75.0"}
P.entries["quest:143"] = {n="Messenger to Westfall",s="Bud till Westfall är ett alliansuppdrag som förmedlar en brådskande vädjan från Magistrate Solomon i Redridge genom Elwynn till Westfall. Efter att Stormwinds militär helt övergett Lakeshire söker stadens ledning ömsesidig hjälp från Gryan Stoutmantles nybildade People's Militia.",h="Bud till Westfall är ett alliansuppdrag som förmedlar en brådskande vädjan från Magistrate Solomon i Redridge...",kw={"gryan stoutmantle","lakeshire","magistrate solomon","peoples militia","redridge mountains","sentinel hill","solomons vädjan","westfall"},ang={["faction:Alliance"]="Detta meddelande visar hur kungariket Stormwinds centrala försvar har kollapsat helt och tvingat gränsstäderna att förhandla fram privata försvarspakter.",["race:Human"]="Meddelandet visar hur mänskliga nybyggare i Redridge och Westfall delar samma svåra situation. De måste förlita sig på frivilliga och legosoldater medan huvudstaden står overksam."},sec={{t="En desperat vädjan",b="Magistrate Solomon befinner sig i en desperat situation i Lakeshire. Redridge Mountains är belägrat av Blackrock-orcher och gnoller, men Stormwind Army har inte anlänt med tillräckliga styrkor. Solomon inser att Lakeshire inte kan överleva med enbart stadsvakter och irreguljära styrkor och skriver därför en formell vädjan om hjälp. När inga reguljära kungliga reserver syns till vänder han blicken västerut. Han har hört talas om en medborgarmilis som håller på att bildas bortom Elwynn Forest."},{t="Över gränserna",b="Mottagaren av meddelandet är Gryan Stoutmantle, en erfaren befälhavare som har börjat samla frivilliga kämpar under People's Militia-fanan. Genom att skicka en kurir tvärs genom kungariket hoppas Solomon att Westfalls organiserade frivilliga kan avvara soldater för att förstärka Lakeshires gränser tills kronans arméer till slut mobiliseras. Men som budbärarna snart upptäcker är Westfall själv fast i en katastrofal kamp mot Defias Brotherhood."}},faq={{q="Varför ber Magistrate Solomon Westfall om hjälp?",a="Stormwind har inte skickat de förstärkningar som Lakeshire så brådskande behöver mot orcherna och gnollerna. Solomon har hört rapporter om en beväpnad medborgarstyrka som samlas i Westfall och hoppas att Gryan Stoutmantle kan avvara soldater för att förstärka Redridge.",al={"varför westfall","solomons vädjan","varför be gryan"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en erfaren soldat som är stationerad vid Sentinel Hill i Westfall. När kronans myndigheter och skydd saknas organiserade han People's Militia och leder den för att försvara gårdarna mot banditer och Defias Brotherhood.",al={"vem är gryan","stoutmantles roll","vem leder westfall"}},{q="Vart leder kurirens färd?",a="Meddelandet ska bäras hela vägen västerut från stadshuset i Lakeshire, genom Redridge och Elwynn Forest, till Sentinel Hill mitt i Westfall.",al={"var ska jag leverera","var finns stoutmantle","redridge till westfall"}},{q="Varför har Stormwind Army inte undsatt Lakeshire?",a="Magistrate Solomon säger att något märkligt är i görningen med armén, eftersom de utlovade trupperna inte har dykt upp. Kungen är frånvarande och Highlord Bolvar Fordragon styr som regent. De väntade reserverna kommer aldrig, så avlägsna områden lämnas åt sig själva.",al={"varför saknas stormwinds armé","var är kungens vakter","stormwinds armé saknas"}},{q="Kan Westfall verkligen avvara soldater till Redridge?",a="Nej. När du kommer till Sentinel Hill upptäcker du att Westfall knappt håller stånd mot Defias Brotherhood. People's Militia har inga soldater att avvara och kämpar för att skydda sina egna gränser.",al={"hjälper westfall","kommer milisen","kan gryan hjälpa"}},{q="Vad händer när brevet har levererats?",a="Gryan Stoutmantle tar emot meddelandet och skriver genast ett svar som förklarar Westfalls svåra situation. Han skickar tillbaka dig med ett svar till Magistrate Solomon.",al={"vad händer sedan","uppföljningsuppdrag","efter bud till westfall"}}},fx={dcf2b619={q="Varför skickar Magistrate Solomon en äventyrare i stället för sina egna vakter?",a="Lakeshires lokala stadsvakt är pressad till bristningsgränsen. Gnolls, murlocs och Blackrock-orcer tränger på från alla håll och hotar att när som helst ta över staden. Solomon kan inte avvara en enda vakt för den långa färden genom Elwynn Forest till Westfall. Därför måste han lita på dugliga resenärer som du för att föra fram sina desperata vädjanden om hjälp.",al={"varför skicka mig","varför behöver solomon en äventyrare","varför inte skicka en vakt till westfall"}}},fp="21,198,18.367.0,23.332.0,51.217.0,25.222.0,37.125.0,49.253.0,52.187.1,39.154.1"}
P.entries["quest:1430"] = {n="Fresh Meat",s="I Swamp of Sorrows säger Dar att kunderna i Orgrimmar efterfrågar mycket krabbkött, särskilt från de monstruösa krabborna. Dar ber dig hämta några av deras ben från kusten.",h="I Swamp of Sorrows säger Dar att kunderna i Orgrimmar efterfrågar mycket krabbkött, särskilt från de...",kw={"krabbben","dar","färskt kött","monstruös krabba","orgrimmar","swamp of sorrows"},sec={{t="Krabbben till Orgrimmar",b="Dars kunder tycker om saftigt krabbkött, särskilt från de monstruösa krabborna. Dar lovar att göra resan till kusten värd mödan om du hämtar några av deras ben, som ska skickas vidare till Orgrimmar. Kusten ligger österut, där varelserna kilar över stränderna och ut i bränningarna. En vintunna väntar om du lyckas, och Dar tänker smaka på varorna innan de skickas iväg."},{t="En smak för resan",b="Dar är nöjd med benen och föreställer sig hur perfekta de blir tillagade över öppen eld. Dar uppmanar dig att ta med ett tillagat smakprov på dina resor och lovar att det är riktigt gott."}},faq={{q="Vem vill ha krabbkött i Swamp of Sorrows?",a="Dar, vars kunder i Orgrimmar efterfrågar mycket av det.",al={"vem ger färskt kött","dar uppdrag","vem är dar"}},{q="Var finns de monstruösa krabborna?",a="På kusten österut, där de kilar över stränderna och ut i bränningarna.",al={"krabbornas plats","var finns krabborna","monstruös krabba kust"}},{q="Varför behöver Dar just de här benen?",a="Dars kunder tycker om krabbkött, allra helst från de monstruösa krabborna, och benen ska skickas tillbaka till Orgrimmar.",al={"varför krabbkött","vad ska köttet användas till","krabbkött till orgrimmar"}}},fp="10,198,26.401.0,20.174.1,47.60.0,41.71.0,38.130.0"}
P.entries["quest:1431"] = {n="Alliance Relations",s="Thrall söker en varsam hand för att bevara freden med Alliansen. I Orgrimmar skickar Craven Drok erfarna äventyrare från Horden för att hitta Keldran nära den västra utgången. Uppdraget kräver diskret diplomati och underrättelsearbete för att skydda Thralls bräckliga fred.",h="Thrall söker en varsam hand för att bevara freden med Alliansen.",kw={"alliance relations","craven drok","diplomati","horde","keldran","orgrimmar","thrall"},ang={["class:Rogue"]="Som tjuv passar dina färdigheter i diskretion och varseblivning för Keldrans uppdrag.",["faction:Horde"]="För Horden visar uppdraget klyftan mellan traditionell råstyrka och Thralls mer återhållsamma, diplomatiska statsmannaskap.",["race:Orc"]="Som ork kanske du känner till yxan som ett sätt att lösa konflikter. Keldrans metod kräver tålamod och taktisk finkänslighet."},sec={{t="Ett diplomatiskt dilemma",b="Thrall vet att ett krig med Alliansen skulle kunna ödelägga hans unga nation. Uppväxt i mänsklig fångenskap lärde sig krigshövdingen mänskligt statsmannaskap och militär strategi. Craven Drok håller utkik efter krigare och hjältar med tålamod för en mer subtil väg, en som ser bortom rå styrka."},{t="Keldrans koja",b="Nära Orgrimmars västra utgång har Keldran en enkel bostad. Han utövar magi och hemliga konster och arbetar med skenbilder, varseblivning och statsmannaskap. Keldran söker diskreta agenter som kan tjäna krigshövdingen medan Horden står i en spänd konfrontation med sina bittra rivaler."}},faq={{q="Vem ger uppdraget Alliance Relations?",a="Craven Drok erbjuder detta uppdrag i Orgrimmar till äventyrare från Horden som har nått sin trettionde erfarenhetssäsong.",al={"uppdragsgivare alliance relations","vem startar alliance relations","var får man alliance relations"}},{q="Var hittar jag Keldran?",a="Keldran bor i en liten hydda nära Orgrimmars västra utgång, långt från stadens centrum.",al={"keldrans plats","var är keldran","keldran orgrimmar"}},{q="Vilken roll har Keldran i Orgrimmar?",a="Keldran studerar magi och mystiska konster och hjälper krigshövding Thrall med diskreta frågor om diplomati, underrättelser och Hordens anseende.",al={"vem är keldran","keldrans bakgrund"}},{q="Varför bryr sig Thrall om diplomati med Alliance?",a="Eftersom Thrall växte upp bland människor förstår han deras politik och militära styrka. Han vet att ett öppet krig kan förgöra hans unga folk, så han förlitar sig på försiktighet och återhållsamt statsmannaskap för att skydda Hordens framtid.",al={"thralls diplomati","varför fred mellan horde och alliance","thrall och människor"}},{q="Leder uppdraget till fler uppdrag?",a="Ja. Om du tar upp saken med Keldran inleder du ett djupare samtal om Hordens ställning bland andra fraktioner och får fler uppdrag inom regional diplomati och spionage.",al={"fortsättning på alliance relations","vad händer efter alliance relations"}},{q="Varför är diskretion så viktig för det här uppdraget?",a="En öppen konflikt med Alliansen riskerar stora förluster och kan destabilisera Kalimdor. Thrall förlitar sig på subtila agenter för att hantera känsliga diplomatiska spänningar innan de övergår i krig.",al={"varför finkänslighet","keldrans finkänslighet"}}},fx={f7a9da96={q="Varför skickar Craven Drok dig till Keldran?",a="Craven Drok förstår att det krävs mer än råstyrka för att begripa Hordens känsliga politiska ställning. Orcerna är stolta och krigiska, men Thrall följer en diplomatisk väg som han lärde sig under sin tid bland människor. Drok börjar berätta för att pröva ditt intresse, men hänvisar dig till Keldran, en utövare av subtila konster som ansvarar för de diskreta frågor som behövs för att styra hur allierade och fiender uppfattar Horden.",al={"craven droks motiv","varför prata med keldran","varför vill craven drok att det här ska göras"}}},fp="18,251,20.265.0,15.271.0,39.117.0,25.90.0,36.148.0,55.210.0,41.172.0,45.189.0"}
P.entries["quest:1432"] = {n="Alliance Relations",s="I Orgrimmar väcker Alliansens framryckning över Kalimdor farhågor om farliga politiska följder. Horden skickar order till Desolace om att rensa bort demoner innan Alliansen kan anklaga Thralls folk för förnyade band till Burning Legion.",h="I Orgrimmar väcker Alliansens framryckning över Kalimdor farhågor om farliga politiska följder.",kw={"relationerna mellan horde och alliance","burning legion","the charred vale","desolace","ghost walker post","keldran","kodo graveyard","takata steelblade"},ang={["class:Warlock"]="Soldater som Takata Steelblade ser på mörka krafter med misstänksamhet, men operationer mot vilda demoner korsar ofta vägar med Hordens pragmatiska användning av häxmästare.",["faction:Horde"]="Uppdraget speglar överhövding Thralls försök att ge den nya Horden legitimitet och begrava arvet från demoniskt slaveri innan fientliga grannar kan utnyttja det.",["race:Orc"]="För orcher som vill hedra Thralls vision om återlösning hotar varje kvardröjande spår av demonisk besmittelse i Kalimdor deras dyrköpta frihet."},sec={{t="En fråga om hur det uppfattas",b="Alliansens spejare och expeditioner som korsar Kalimdor försätter Horden i en känslig situation. Demoniska rester över centrala Kalimdor kan bekräfta gamla misstankar om att orcherna och deras allierade fortfarande tjänar Burning Legion. Med överhövding Thralls godkännande leder Keldran operationerna från Orgrimmar för att röja undan resterna innan fientliga fraktioner inom Alliansen kan använda dem för att rättfärdiga krig."},{t="Utpost i ödemarken",b="Orderna söderut går genom The Charred Vale i Stonetalon Mountains och vidare in i Desolace. Strax norr om den väldiga Kodo Graveyard ligger Ghost Walker Post. Hordens agenter, som Takata Steelblade, håller uppsikt över ödemarken, där härjande kentaurstammar och en växande demonisk korrumpering båda hotar regionen."},{t="Pragmatiska allianser",b="Takata Steelblade ser uppdraget med bister pragmatism. Att rensa bort de lokala demonerna minskar också trycket från våldsamma kentaurstammar och hjälper Hordens bofasta häxmästare. Ändå kommer plikten först: att avlägsna Burning Legions fästen skyddar Horden, oavsett vilka andra som gynnas av utrensningen."}},faq={{q="Varför bryr sig Horde om Alliance här?",a="Alliansstyrkor som rycker fram över Kalimdor kan använda aktiva demonhärdar som bevis för att Horden fortfarande umgås med Burning Legion. Genom att rensa bort de lokala demonerna hoppas Horden kunna dämpa anklagelserna.",al={"varför oroa sig för alliance","horde och alliance i desolace","anklagelser från alliance"}},{q="Vem är Keldran?",a="Keldran är en agent för Horden i Orgrimmar som med överhövdingens godkännande leder operationer mot demoner som hotar Hordens anseende.",al={"keldran","vem är keldran","keldran i orgrimmar"}},{q="Var ligger Ghost Walker Post?",a="Ghost Walker Post ligger i centrala Desolace, rakt söder om passet från The Charred Vale i Stonetalon Mountains och strax norr om Kodo Graveyard.",al={"ghost walker posts plats","var finns takata steelblade","hitta ghost walker post"}},{q="Vem är Takata Steelblade?",a="Takata Steelblade är en soldat i Horden vid Ghost Walker Post i Desolace. Överhövdingen ger honom i uppdrag att hålla regionala hot, däribland demoner och fientliga kentaurer, i schack.",al={"takata steelblade","vem är steelblade","steelblade i desolace"}},{q="Varför nämner Takata att centaur får hjälp?",a="Kentaurerna gör anspråk på Desolace som sitt territorium men kan inte hejda det växande demonhotet. Att gallra ut demonerna hjälper också kentaurerna att överleva, en kompromiss som Takata godtar för Hordens säkerhet.",al={"hjälpa centaur","centaur i desolace","varför hjälpa centaur"}},{q="Hur hänger warlocks ihop med uppdraget?",a="Takata konstaterar med avsmak att rensningen av vilda demoner och deras inflytande också hjälper de omstridda häxmästarna som verkar inom Horden.",al={"kopplingen till warlocks","varför hjälpa warlocks","warlocks inom horde"}}},fp="18,228,22.382.0,21.298.0,19.298.1,51.210.0,15.147.0,35.158.0,25.172.0,43.195.0,38.139.0"}
P.entries["quest:1437"] = {n="Vahlarriel's Search",s="Vahlarriel Demonslayer har kommit till Desolace för att ta reda på vad som hänt två försvunna adelsmän ur House Malem, en darnassisk köpmannafamilj. Deras far befarar det värsta, och det senaste någon hört från syskonen var att de befann sig i Stonetalon Mountains för några veckor sedan. Vahlarriel ber dig hitta deras vagn.",h="Vahlarriel Demonslayer har kommit till Desolace för att ta reda på vad som hänt två försvunna adelsmän ur...",kw={"kista","dalinda","darnassus","desolace","malem","stonetalon","tyranis","vahlarriel"},sec={{t="Två försvunna adelsmän",b="Vahlarriel Demonslayer letar efter Tyranis och Dalinda Malem. Deras far befarar det värsta och har gett Vahlarriel i uppdrag att göra allt som står i hans makt för att hitta dem. Sökandet har knappt börjat, och Vahlarriel hoppas att det inte ska hålla dem kvar länge i Desolace. Senast rapporterades syskonen vara på väg genom Stonetalon Mountains för några veckor sedan. Vahlarriel ber dig hitta deras vagn i Desolace och komma tillbaka genast när du gör det. Där ligger dess förkolnade rester, med en kista bland dem."},{t="Bland vrakdelarna",b="När du söker igenom vraket ser du att vagnen föll offer för både besvärjelser och vapen. Striden verkar ha varit kort och ensidig, utan blod eller kroppar kvar på platsen. Den som gjorde detta var effektiv och snabb."}},faq={{q="Vem letar Vahlarriel efter?",a="Tyranis och Dalinda Malem, två adelsmän ur House Malem, en darnassisk köpmannafamilj.",al={"vem är försvunnen","vilka är adelsmännen","house malems försvunna barn"}},{q="Var hörde man senast av syskonen?",a="Senast rapporterades de vara på väg genom Stonetalon Mountains några veckor innan Vahlarriel talade med dig.",al={"var sågs malem-syskonen senast","vart tog de vägen","vagnens färdväg"}},{q="Varför söker Vahlarriel?",a="Deras far befarar det värsta, och Vahlarriel har fått i uppdrag att göra allt som står i hans makt för att hitta hans försvunna barn.",al={"vem anlitade vahlarriel","vem vill hitta syskonen"}},{q="Vad vill Vahlarriel att du hittar?",a="Tyranis och Dalinda Malems vagn i Desolace. Om du hittar den ber Vahlarriel dig att komma tillbaka genast.",al={"hur börjar vahlarriels sökande","vad är första steget"}}},fp="19,290,18.474.0,18.217.1,30.83.0,40.100.0,28.122.0,38.104.0"}
P.entries["quest:1438"] = {n="Vahlarriel's Search",s="Efter den andra delen av Vahlarriel's Search skickar Vahlarriel Demonslayer dig för att leta efter Dalinda och Tyranis Malem, med början vid fästningen. Nyheten når Vahlarriels överordnade i Darnassus, som oroar sig för Tyranis motiv och framför allt vill att Dalinda förs hem oskadd.",h="Efter den andra delen av Vahlarriel's Search skickar Vahlarriel Demonslayer dig för att leta efter Dalinda...",kw={"burning blade","dalinda","darnassus","demonbesegrare","desolace","malem","thunder axe fortress","tyranis","vahlarriel"},sec={{t="En efterforskning vid fästningen",b="Vahlarriel Demonslayer vill att du letar efter både Dalinda och Tyranis, med början vid fästningen, och återvänder med det du får veta. Vahlarriel kontaktar genast sina överordnade i Darnassus. Sedan får du veta i förtroende att de oroar sig över varför Tyranis kom till Desolace, och att det viktigaste för dem är att Dalinda kommer hem oskadd. När det gäller Tyranis vill de först bedöma honom, innan han får återvända hem."},{t="En fånges berättelse",b="Dalinda, som du hittar i den stora byggnaden mittemot ingången, berättar att Burning Blade tillfångatog henne och Tyranis och förde dem hit. Hon tror att hon ska offras åt deras demoniska herrar. Hon säger att färden var ett misstag från början. Tyranis hade blivit hungrig efter arkan kunskap, mot sitt folks vilja, och gav sig av trots varningar om demonerna här. Hon fruktar vad som har hänt honom."}},faq={{q="Var finns Dalinda Malem?",a="I området kring Thunder Axe Fortress i Desolace, i den stora byggnaden mittemot ingången.",al={"dalinda malem plats","var hittar man dalinda","hitta dalinda desolace"}},{q="Vem skickar dig för att leta efter Dalinda och Tyranis?",a="Vahlarriel Demonslayer ber dig hitta båda om du kan, med början vid fästningen, medan Vahlarriel underrättar sina överordnade i Darnassus.",al={"vem ger vahlarriel's search","uppdragsgivare vahlarriel","vahlarriel demonslayer uppdrag"}},{q="Varför bryr sig Darnassus mer om Dalinda än om Tyranis?",a="Vahlarriels överordnade tvivlar på Tyranis skäl till att komma till Desolace och värdesätter framför allt att Dalinda återvänder oskadd.",al={"varför misstänks tyranis","tyranis motiv","varför prioritera dalinda"}},{q="Vad hände före den här delen av efterforskningen?",a="Den följer på den andra delen av Vahlarriel's Search.",al={"föregående uppdrag","förutsättning vahlarriel","vahlarriel search uppdragskedja"}}},fp="19,280,24.374.0,19.390.1,23.92.0,46.132.0,56.118.0,41.50.0"}
P.entries["quest:1439"] = {n="Search for Tyranis",s="Dalinda Malem berättar att orcherna slaktade alla deras vakter och tjänare innan de förde henne och Tyranis hit. Tyranis försökte tala med dem, och hon kan inte ge sig av förrän hon vet vad som hänt hennes bror. Hon ber dig hitta honom och komma tillbaka när hans öde är känt.",h="Dalinda Malem berättar att orcherna slaktade alla deras vakter och tjänare innan de förde henne och Tyranis...",kw={"burning blade","dalinda","desolace","malem","hänge","thunder axe fortress","tyranis","vahlarriel"},sec={{t="En bortrövad bror",b="Dalinda berättar att orcherna dödade alla deras vakter och tjänare innan de släpade henne och Tyranis hit. Hon trodde att hon skulle dö direkt, men orcherna hade tydligtvis andra planer. Tyranis försökte tala med dem, kanske i hopp om att imponera på dem med sina magiska kunskaper, men hon kan inte säga varför. Hon tänker inte fly förrän hon vet hans öde, så hon ber dig hitta honom och återvända när du vet. Han finns i en byggnad till vänster om fästningens ingång."},{t="Dalindas rädsla",b="Dalinda fruktar att Tyranis, om han får chansen, kommer att söka efter Burning Blades hemligheter och bli en av dem. Makt har alltid lockat honom, precis som den lockar alla som förtrollas av magi. För hennes folk är det ett allvarligt brott att ens studera sådant, och hon tvivlar på att hon skulle kunna möta sin familj med beskedet att hans ande lekte med den faran."},{t="Vad Dalinda får veta",b="När du kommer tillbaka kallar Dalinda det hemskt men nödvändigt. Om du inte hade gjort det, skulle hennes eget folk ha gjort det. Hon ber om ursäkt om hennes tack låter tomt. Nu när hon känner till hans öde är hon redo att fly och tar emot din hjälp om du fortfarande är villig."}},faq={{q="Vem är Tyranis Malem?",a="Dalindas bror. Han talade med deras fångvaktare, kanske i hopp om att imponera på dem med sina magiska kunskaper. Hon säger att magins kraft alltid har lockat honom.",al={"vem är tyranis","tyranis bakgrund","tyranis malem"}},{q="Varför vägrar Dalinda att ge sig av än?",a="Hon tänker inte ge sig av förrän hon vet vad som har hänt hennes bror. Hon ber dig hitta honom och komma tillbaka för att hämta henne när hans öde är känt.",al={"varför vill dalinda inte ge sig av","varför stannar dalinda","varför vänta med att fly"}},{q="Vad hände med vakterna och tjänarna?",a="Orcherna dödade dem alla och tog sedan Dalinda och Tyranis levande, tydligen med andra planer i åtanke.",al={"vad hände med deras vakter","vilka dödades","vakter och tjänare"}},{q="Var finns Tyranis?",a="I Thunder Axe Fortress i Desolace, i byggnaden till vänster när du går in.",al={"var finns tyranis","tyranis plats"}},{q="Vad kom före det här steget?",a="Det följer efter den tredje delen av Vahlarriel's Search, där Vahlarriel skickade dig för att hitta Dalinda.",al={"vilket uppdrag kom före detta","uppdragsordning","vahlarriels uppdragskedja"}}},fp="18,276,15.446.0,14.312.0,19.257.1,21.152.0,37.139.0,41.93.0,17.78.0,27.92.0"}
P.entries["quest:144"] = {n="Messenger to Westfall",s="Ett brev från Westfall ger Magistrate Solomon ett hårt besked i Lakeshire. Han bad Gryan Stoutmantle om soldater för att försvara Redridge, men Westfall har lämnats att hantera sina egna problem.",h="Ett brev från Westfall ger Magistrate Solomon ett hårt besked i Lakeshire.",kw={"gryan stoutmantle","lakeshire","magistrate solomon","messenger to westfall","people's militia","redridge","sentinel hill","westfall"},ang={["faction:Alliance"]="Den här korrespondensen visar klyftan mellan härskarna i Stormwind Keep och de avlägsna provinserna. Westfall och Redridge lämnas att klara sig själva.",["race:Human"]="Som mänsklig resenär ser du hur isolerade provinsstäderna är. Vanligt folk och veteraner blöder för att försvara marker som Stormwinds adelsmän vägrar skydda."},sec={{t="En vädjan över skiftande gränser",b="Magistrate Solomon står inför växande problem i Redridge Mountains utan Stormwinds kungliga garnison. Han söker hjälp vid den södra gränsen och skriver till Gryan Stoutmantle, befälhavare för People's Militia i Westfall. Solomon hoppas att frivilliga vid Sentinel Hill kan avvara soldater för att stärka Lakeshires försvar. Han vet inte hur hårt de västra slätterna är pressade."},{t="Ett bittert avslag",b="Gryan Stoutmantle säger nej, även om beskedet tynger honom. Westfall strider mot Defias Brotherhood och kringströvande gnoller eftersom House of Nobles och kronan har övergett kungarikets kornbod. People's Militia bildades för att folket skulle kunna överleva. Dess led förlorar dugliga män varje dag, och Stoutmantle kan inte avvara en enda soldat till Redridge."},{t="Kungariket slits isär",b="När du bär tillbaka Stoutmantles svar till Lakeshire ser Solomon att gränsområdena delar samma försummelse. Lokala magistrater och medborgarmiliser lämnas att försvara sig själva medan Stormwind Army hålls tillbaka. Solomon vänder blicken söderut, mot Darkshire i Duskwood, i hopp om att hitta hjälp där."}},faq={{q="Varför bad Magistrate Solomon Westfall om hjälp?",a="Magistrate Solomon sökte hjälp eftersom Lakeshire står inför växande hot utan Stormwinds armé. Han visste att Gryan Stoutmantle hade organiserat People's Militia för att försvara Westfall och hoppades att den kunde avvara soldater till Redridge.",al={"varför be westfall om hjälp","solomons brev till stoutmantle","varför westfalls milis"}},{q="Varför vägrar Gryan Stoutmantle att skicka hjälp?",a="Westfall strider redan mot Defias Brotherhood och försvarar sig mot kringströvande gnoller. Stoutmantle säger att milisen finns eftersom Stormwind övergav Westfall, och att den inte har några soldater att avvara.",al={"varför stoutmantle säger nej","milisen vägrar lakeshire","stoutmantles svar"}},{q="Var befinner sig Stormwind Army under dessa kriser?",a="Ingen i breven vet varför Stormwind Army är borta. Solomon och Stoutmantle kan bara undra vad som hindrar den från att försvara rikets utkanter.",al={"varför stormwind inte hjälper","var är armén","stormwinds desertering"}},{q="Vad händer efter att Stoutmantles brev har återlämnats till Solomon?",a="När Magistrate Solomon får veta att Westfall inte kan hjälpa vänder han sig till Duskwood. Han skickar dig vidare till Darkshire i hopp om att Mayor Ello Ebonlockes Night Watch kan erbjuda hjälp.",al={"nästa uppdrag efter messenger to westfall","vad gör solomon sedan"}},{q="Vad är People's Militia?",a="People's Militia är en frivilligstyrka som organiserats av Gryan Stoutmantle och har sin bas vid Sentinel Hill. Lokala bönder, veteraner och invånare försvarar Westfall mot laglösa och gnoller utan kronans trupper.",al={"vilka är people's militia","westfalls milis"}},{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en erfaren soldat som leder försvaret av Westfall. Från tornet vid Sentinel Hill samlar han frivilliga och leder striden mot Defias Brotherhood.",al={"gryan stoutmantles bakgrund","vem är stoutmantle"}}},fx={["84b4f9a5"]={q="Varför skickar Gryan Stoutmantle dig i stället för sin egen milis?",a="People's Militia är nära bristningsgränsen när den försvarar Westfalls gårdar mot Defias Brotherhood och kringströvande gnolls. Stoutmantle kan inte avvara en enda kämpe för den långa resan österut genom Elwynn Forest till Redridge. Eftersom du redan kom med Magistrate Solomons begäran är du Redridges kurir och bäst lämpad att föra det dystra svaret tillbaka.",al={"varför skicka mig","varför inte skicka en miliskurir","varför behöver gryan en budbärare"}}},fp="21,170,32.385.0,16.361.0,30.296.1,49.224.0,46.180.0,48.144.0,61.158.1,29.201.0,25.177.0"}
P.entries["quest:1440"] = {n="Return to Vahlarriel",s="Dalinda Malem är redo att lämna Thunder Axe Fortress. Hon tackar dig för allt du har gjort för henne och hennes familj och säger att du får välja när det är dags. Du följer henne ut och beger dig sedan till Vahlarriel Demonslayer.",h="Dalinda Malem är redo att lämna Thunder Axe Fortress.",kw={"dalinda malem","darnassus","desolace","eskort","nijel's point","thunder axe fortress","tyranis","vahlarriel"},sec={{t="När hon lämnar fästningen",b="Dalinda frågar om tiden är inne och tackar för allt du har gjort för henne och hennes familj, ifall allt inte går som hon hoppas. Om du är redo finns inget annat som håller henne kvar, och hon ger sig av när du bedömer att stunden är rätt. Du följer henne ut från Thunder Axe Fortress och beger dig sedan till Vahlarriel Demonslayer i Desolace."},{t="Besked från Vahlarriel",b="Vahlarriel tackar dig. Dalinda nådde Nijel's Point i mycket bättre skick än Vahlarriel hade kunnat hoppas på, och att hon kom dit av egen kraft var ett gott tecken. Vahlarriel sörjer att inget av syskonen återvände, men får själv bära skammen över Tyranis val när hon är tillbaka i Darnassus."}},faq={{q="Vem ber dig följa med henne?",a="Dalinda Malem, som är redo att lämna Thunder Axe Fortress när du bedömer att stunden är rätt.",al={"vem ger uppdraget return to vahlarriel","uppdragsgivare return to vahlarriel","vem är dalinda malem"}},{q="Var börjar det här?",a="Vid Thunder Axe Fortress i Desolace, där Dalinda befinner sig.",al={"dalinda malem plats","var finns dalinda malem","var börjar return to vahlarriel"}},{q="Vem beger du dig till när Dalinda har kommit ut?",a="Vahlarriel Demonslayer i Desolace.",al={"var lämnar man in return to vahlarriel","vem avslutar return to vahlarriel","return to vahlarriel slut"}},{q="Vad kom före det här steget?",a="Det följer efter Search for Tyranis, som ingår i den längre berättelsen Vahlarriel's Search.",al={"förkrav return to vahlarriel","return to vahlarriel föregående uppdrag","vilket uppdrag kommer före return to vahlarriel"}}},fp="20,207,20.327.0,20.311.1,27.90.0,22.54.0,38.36.0,27.70.0"}
P.entries["quest:1442"] = {n="Seeking the Kor Gem",s="”Seeking the Kor Gem” är ett paladinuppdrag för Alliansen som skickar en novis djupt in i de forntida ruinerna i norra Kalimdor. Nattalven Thundris Windweaver i Auberdine visar vägen, och paladiner ger sig in i Blackfathom Deeps för att ta en mäktig Kor Gem från naga som fördärvar den. Stenen de hämtar blir ett viktigt material i Jordan Stilwells hantverk.",h="”Seeking the Kor Gem” är ett paladinuppdrag för Alliansen som skickar en novis djupt in i de forntida...",kw={"auberdine","blackfathom deeps","darkshore","jordan stilwell","kor gem","naga","paladin","the test of righteousness","thundris windweaver"},ang={["class:Paladin"]="Det här uppdraget är ett viktigt prov på karaktär och uthållighet för en paladin i Alliansen. Det prövar din vilja att färdas ner i Kalimdors fientliga djup för att smida ett vapen helgat åt Ljuset.",["faction:Alliance"]="Uppdraget visar Alliansens enighet i praktiken: en mänsklig smed förlitar sig på nattalvisk visdom och dvärgastål för att smida vapen mot det växande mörkret.",["race:NightElf"]="Thundris Windweavers samarbete visar den sköra men växande förbindelsen mellan de forntida kaldorei och de nyallierade utövarna av det Heliga Ljuset från Eastern Kingdoms."},sec={{t="En betrodd allians",b="När paladiner under utbildning söker material åt den mänsklige smeden Jordan Stilwell går färden över kontinentgränser till Darkshore. Där i Auberdine minns Thundris Windweaver smeden med respekt. Trots nattalvernas naturliga reserverade sätt och vissa fallna människor som gått över gränsen tror Thundris på paladiner som följer en rättfärdig väg och berättar gärna var sådana forntida ädelstenar finns."},{t="Ner i djupet",b="Sökandet leder direkt till tempelkomplexet under jord i Blackfathom Deeps, vid Ashenvales dimmiga nordvästra kust. De vattenfyllda djupen hyser Twilight's Hammers kultister och förrädiska havsvarelser, men också naga-prästinnor som kanaliserar mörk magi genom forntida Kor Gem. En paladin måste våga sig genom de mörka salarna, besegra trollkvinnorna och säkra en ädelsten genomsyrad av ormlik ondska."},{t="Att rena stenen",b="När du återlämnar en fördärvad Kor Gem till Thundris Windweaver blir det tydligt varför du skulle söka upp en alvisk mystiker. Naga laddar ädelstenen med rå magisk kraft, men deras förtrollningar förvrider den mot det onda. Innan Jordan Stilwell kan smida den till ett heligt vapen måste Thundris avlägsna mörkret och se till att dess kraft förblir ren och stabil inför den kommande heliga smidesritualen."}},faq={{q="Vem skickar dig för att hitta Kor Gem?",a="Uppdraget ges av Thundris Windweaver, en nattalv i kusthamnen Auberdine i Darkshore. Han vägleder paladiner på vapensmeden Jordan Stilwells uppdrag.",al={"uppdragsgivare för kor gem","vem ger uppdraget seeking the kor gem","thundris windweaver uppdrag"}},{q="Var finns Kor Gem?",a="Ädelstenen finns i Blackfathom Deeps, en forntida underjordisk grotta vid Ashenvales nordvästra kust. Den bärs av naga-prästinnorna som håller till i ruinerna.",al={"kor gem plats","var får man kor gem","var finns corrupted kor gem"}},{q="Varför behöver Jordan Stilwell en Kor Gem?",a="Ädelstenen innehåller mäktig magisk energi som behövs för att tillverka Jordans förfinade vapen under paladinprovet The Test of Righteousness.",al={"varför kor gem","vad används kor gem till","stilwell ädelsten"}},{q="Varför måste Thundris rena ädelstenen?",a="Naga laddar Kor Gem med ansenlig arkansk kraft, men deras onda natur besudlar magin. Thundris renar ädelstenen från detta fördärv så att dess återstående styrka tryggt kan kanaliseras in i ett vapen helgat åt Ljuset.",al={"varför rena kor gem","corrupted kor gem renad","rena ädelstenen"}},{q="Varför nämner Thundris ett ”fallet släkte”?",a="Thundris anspelar troligen på uppmärksammade förräderier bland människor, som prins Arthas Menethil, vars fall i mörkret fläckade Silver Hands rykte i hela Azeroth. Trots det väljer Thundris att bedöma varje paladin efter egna meriter.",al={"vem är den fallne","thundris fallna släkte","hänvisning till fallen paladin"}},{q="Behöver jag en grupp för att få Kor Gem?",a="Thundris varnar uttryckligen äventyrare för att ge sig av ensamma. Eftersom ädelstenen faller från elitnaga djupt inne i Blackfathom Deeps rekommenderas starkt att du går dit med en äventyrsgrupp.",al={"går kor gem att klara ensam","kan man klara kor gem ensam","grupp till blackfathom deeps"}}},fx={["5bec2e5c"]={q="Varför vill Thundris Windweaver att det här ska göras?",a="Thundris Windweaver minns Jordan Stilwell från länge sedan som en man med anspråkslös men hedervärd karaktär. Kor-juveler är farliga och genomsyrade av mörk magi, men Thundris litar på att Stilwells syfte är ädelt. Han ser att du är en förkämpe på en helig väg och går med på att hjälpa till att hitta och rena artefakten, så att Stilwell kan slutföra sitt arbete tryggt och dess vidriga energier avlägsnas innan den används.",al={"thundris motiv","varför hjälper thundris","varför hjälpa stilwell"}},c21b70e4={q="Vad används Corrupted Kor Gem till?",a="Corrupted Kor Gem är ett arkaniskt fokus som nagorna i Blackfathom Deeps nedsänkta ruiner har genomsyrat med mörk kraft. Jordan Stilwell behöver en Kor-gem som en viktig beståndsdel när han smider sitt mästerverk till vapen. Men innan den kan användas i ett rättskaffens vapen måste ädelstenens vedervärdiga nagafördärv renas bort, samtidigt som dess råa inre kraft bevaras till Stilwells smidesritual.",al={"vad används kor-gemen till","användning av corrupted kor gem","kor-gemets syfte"}},["35f248ef"]={q="Vem har Kor-gemen i Blackfathom Deeps?",a="Gemen hålls av nagorna som har tagit över den sjunkna alviska helgedomen Blackfathom Deeps längs Ashenvales kust. Dessa ormlika varelser värdesätter Kor-gemerna och genomsyrar dem med oren, skuggfylld kraft för att driva sina egna ondskefulla riter i de översvämmade djupen.",al={"vem har kor-gemen","måltavla för kor-gemen","vem släpper kor-gemen"}}},fp="19,221,18.399.0,14.325.0,19.338.1,34.164.0,29.161.0,40.146.0,41.183.0,42.203.0,37.153.0"}
P.entries["quest:1444"] = {n="Return to Fel'Zerul",s="En Atal'ai Exile i The Hinterlands har granskat artefakterna du tog med och kallar dem ofarliga. De oroar sig mer för Jammal'an the Prophet och vill att Fel'zerul i Stonard ska få höra vad de har att säga.",h="En Atal'ai Exile i The Hinterlands har granskat artefakterna du tog med och kallar dem ofarliga.",kw={"atal'ai exile","fel'zerul","the hinterlands","jammal'an","stonard","åkallningsritual","the temple of atal'hakkar"},sec={{t="Ord från en exil",b="Atal'ai Exile ansåg en gång att Jammal'an the Prophet var en värdig överstepräst. Men profetens orubbliga tro på profetian kan döma Atal'ai till undergång, om det inte redan har skett. När exilen sa ifrån blev hen utpekad som otrogen och fördriven från The Temple of Atal'Hakkar. Artefakterna du tog med är ofarliga. Det som skrämmer exilen är möjligheten att Jammal'an har funnit rätt fetischförtrollning för åkallningsritualen, vilket skulle försätta världen i stor fara. Fel'zerul i Stonard väntar på att få höra vad du fick veta."}},faq={{q="Vart måste jag gå för att tala med Fel'zerul?",a="Fel'zerul är i Stonard.",al={"fel'zeruls plats","var är fel'zerul","lämna in åter till fel'zerul"}},{q="Varför blev Atal'ai Exile förvisad?",a="Exilen sa ifrån om Jammal'an the Prophets orubbliga tro på sin profetia, som exilen tror kommer att förgöra Atal'ai. För att ha uttryckt sin oro kallades exilen otrogen och fördrevs från The Temple of Atal'Hakkar.",al={"varför blev atal'ai exile förvisad","varför är exilen i the hinterlands","atal'ai exiles bakgrund"}},{q="Är artefakterna du tog med till exilen farliga?",a="Exilen säger att de är ofarliga. Oron gäller åkallningsritualen och huruvida Jammal'an har funnit rätt fetischförtrollning för den.",al={"är artefakterna farliga","fara med fetischartefakter"}}},fp="19,203,19.525.0,40.24.0,35.228.0,49.137.0"}
P.entries["quest:1447"] = {n="The Missing Diplomat",s="I Stormwind ställs du öga mot öga med Dashel Stonefist när du söker efter den försvunna diplomaten i Old Town. Du behöver svar från en man som helst håller dem för sig själv.",h="I Stormwind ställs du öga mot öga med Dashel Stonefist när du söker efter den försvunna diplomaten i Old Town.",kw={"slagsmål","konspiration","dashel","försvunnen diplomat","old town","stonefist","stormwind","busar"},ang={["class:Rogue"]="Som Rogue tar du hand om råskinn som Dashel Stonefist när du pressar kontakter på information från gatan.",["faction:Alliance"]="Som medlem av Alliance kan varje ledtråd om diplomatens försvinnande avslöja förräderiet som hotar ledningens stabilitet.",["race:Human"]="Som människa ser du busar från Stormwind hindra sökandet efter den försvunna diplomaten, ett hot mot kungarikets säkerhet."},sec={{t="Ett vänskapligt samtal i Old Town",b="I Old Town leder sökandet efter den försvunna diplomaten dig bland ficktjuvar och skumma mäklare, bortom katedralens vakande blick. Dashel Stonefist är en lokal kontakt med band till Stormwinds kriminella fraktioner, och han vet något om kidnappningen. Han vill inte dela med sig av vad han vet till utredare som ställer känsliga frågor."},{t="Slagsmål i gränden",b="Dashel Stonefist vägrar samarbeta när du söker upp honom. Hans lojala busar från Old Town hjälper honom när han försöker slå ner dig och sätta stopp för utredningen. När du väl har oskadliggjort Dashel och hans män ändrar han ton och öppnar vägen till nästa ledtråd i konspirationen."}},faq={{q="Vem är Dashel Stonefist?",a="Dashel Stonefist är en skum lokal kontakt i Old Town med band till Stormwinds kriminella undre värld. Han vet mer än han låtsas om olaglig verksamhet i staden.",al={"dashel stonefist","vem är stonefist","dashel"}},{q="Varför måste jag slåss mot Dashel i stället för att bara prata med honom?",a="Dashel är inte intresserad av att samarbeta med utredare. När du frågar om den försvunna diplomaten antar han att det är lätt att skrämma dig och kallar in sina busar för att tysta dig. Först efter en ordentlig omgång går han med på att prata.",al={"varför slåss mot dashel","kan jag prata med stonefist","varför spöa dashel"}},{q="Måste jag döda Dashel Stonefist?",a="Nej. Du måste få Dashel att ge upp, inte döda honom. När hans hälsa sjunker tillräckligt lågt ger han sig, kallar tillbaka sina kumpaner och går med på att svara på dina frågor.",al={"ska jag döda dashel","stonefist vid liv","är dashel död"}},{q="Var äger striden rum?",a="Striden äger rum öppet i Old Town, nära gränderna bakom Pig and Whistle Tavern och de lokala träningshallar där Dashel Stonefist brukar hålla till.",al={"stonefists plats","var är dashel","slagsmål i old town"}},{q="Vad händer efter att jag besegrat Dashel?",a="När du har besegrat Dashel ber han om ursäkt och går med på att berätta vad han vet om konspirationen. Han riktar utredningen mot nästa länk utanför huvudstaden.",al={"vad händer efter dashel","stonefists nästa uppdrag","nästa del i diplomatkedjan"}},{q="Vad handlar uppdragskedjan ”The Missing Diplomat” egentligen om?",a="Sökandet efter en försvunnen ambassadör avslöjar ett nät av svek kring diplomatens kidnappning och de skuggfigurer som ligger bakom den.",al={"lore om den försvunna diplomaten","vem är diplomaten","försvunnen kung"}}},fx={c22a58c4={q="Vem slåss du mot i den här konfrontationen?",a="Du slåss mot Dashel Stonefist och två av hans storväxta skurkar från Old Town. Dashel håller till i Old Towns ruffiga gränder, omgiven av lokala busar som sköter hans smutsiga arbete och skrämmer alla som lägger näsan i blöt. I stället för att svara på frågor om sina olagliga kontakter kallar Dashel på sina vänner för att tysta dig med våld, så att du aldrig lämnar staden.",al={"vem slåss jag mot i missing diplomat","vem anfaller tillsammans med dashel","målet i missing diplomat åtta"}},["15b1a9ee"]={q="Varför anfaller Dashel Stonefist dig?",a="Dashel vill inte att någon ställer frågor om den försvunna diplomaten eller hans egna skumma kontakter. Han verkar i Old Towns skuggor och överlever genom hemlighetsmakeri, hot och råstyrka. När du pressar honom på svar ser han dig som en ovälkommen snok och ett lätt byte, och räknar med att hans busar ska tysta dig för gott innan hans inblandning i mörkare planer avslöjas.",al={"varför slåss dashel stonefist mot dig","varför anfaller dashel","dashel stonefists motiv"}}},fp="20,149,27.304.0,18.260.1,24.173.0,61.224.0,35.163.0,33.166.0,34.164.1,50.126.2"}
P.entries["quest:145"] = {n="Messenger to Darkshire",s="Messenger to Darkshire är ett brådskande diplomatiskt uppdrag från Magistrate Solomon i Lakeshire till Lord Ello Ebonlocke i Duskwood. Solomon är desperat efter militär förstärkning mot Blackrock-orcherna och gnollerna som hotar Redridge, och vänder sig till grannbosättningen för att få hjälp. Kuriren måste trotsa Duskwoods skuggiga vägar för att överlämna Solomons formella vädjan till borgmästaren i Darkshire.",h="Messenger to Darkshire är ett brådskande diplomatiskt uppdrag från Magistrate Solomon i Lakeshire till Lord...",kw={"darkshire","duskwood","ebonlocke","lakeshire","budbärare","night watch","redridge","solomon"},ang={["faction:Alliance"]="Solomons desperata brev visar hur splittrade och försummade Alliansens avlägsna städer har blivit medan Stormwinds kungliga hov förblir handlingsförlamat.",["race:Human"]="Uppdraget visar hur de mänskliga bosättningarna i söder delar samma svåra läge. Var och en måste förlita sig på oregelbundna lokala miliser sedan kungariket drog tillbaka arméns vanliga patruller."},sec={{t="En desperat vädjan om hjälp",b="Stormwinds kungliga hov ignorerar hans vädjanden, och grannlandet Westfall är upptaget med sitt eget uppror. Därför blickar Magistrate Solomon söderut, mot Duskwood. Redridge är under allt hårdare belägring av Blackrock-orkklanerna och aggressiva gnollflockar, och Lakeshires lokala vakter pressas till bristningsgränsen. I desperation skriver Solomon ett brev direkt till borgmästare Ello Ebonlocke i hopp om att få hyra in eller låna Darkshires omtalade Night Watch för att förstärka stadens försvar."},{t="Vägen in i mörkret",b="För att bära Solomons brev måste du ta dig söderut in i Duskwood, en skogstrakt höljd i övernaturligt mörker. Solomon varnar kurirer för att strikt hålla sig till vägarna, eftersom vildmarken mellan Lakeshire och Darkshire har blivit ökänt farlig. När du når stadshuset i Darkshire kan du överlämna brevet till Lord Ebonlocke, men om Duskwood har några styrkor att avvara är en helt annan fråga."}},faq={{q="Varför ber Lakeshire Darkshire om hjälp?",a="Stormwind har nekat till formell militär hjälp och lämnat städer som Lakeshire att försvara sig själva mot övermäktiga hot som Blackrock-orcherna. Magistrate Solomon försöker få hjälp av varje närliggande allierad, i hopp om att Darkshires stadsmilis, Night Watch, har tränade kämpar att låna ut.",al={"varför be duskwood","varför darkshire","solomons vädjan till darkshire"}},{q="Vem är Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke är borgmästare i Darkshire och Duskwoods framträdande civila ledare. Han styr staden från stadshuset och samordnar stadens angelägenheter tillsammans med Commander Althea Ebonlocke, som leder Night Watch.",al={"ello ebonlocke","vem är ebonlocke","borgmästare i darkshire"}},{q="Vad är Night Watch?",a="Night Watch är Darkshires självständiga civila milis. Den bildades för att patrullera stadens utkanter och bekämpa odöda, bestar och skuggor som tränger fram genom Duskwood när Stormwinds garnisonstrupper saknas.",al={"night watch i duskwood","vilka är night watch"}},{q="Varför varnar Solomon mig för att hålla mig till vägarna?",a="Duskwoods vildmark kryllar av odöda fasor, spindlar och vilda bestar. Om du lämnar den asfalterade vägen och går in i snåren utsätter du dig för aggressiva rovdjur och bakhåll.",al={"varning för vägarna i duskwood","håll dig till vägarna i duskwood"}},{q="Var började den här uppdragskedjan?",a="Det här uppdraget ingår i Magistrate Solomons serie desperata meddelanden. Det följer på hans tidigare vädjan till Gryan Stoutmantle i Westfall och fortsätter hans outtröttliga försök att hitta hjälp åt Lakeshire.",al={"föregående uppdrag","ordning på messenger-uppdragen"}},{q="Har Darkshire verkligen några vakter att avvara?",a="Duskwood står inför en egen existentiell kris och plågas av återuppståndna döda, förrymda worgen och lurande vidunder. Night Watch har knappt nog med kämpar för att försvara Darkshire, så Solomons vädjan är ett bittert långskott.",al={"kommer darkshire att hjälpa","skickar ebonlocke vakter"}}},fx={["532260e8"]={q="Varför skickar Magistrate Solomon en äventyrare i stället för sina egna vakter?",a="Lakeshires lokala vaktstyrka är hårt pressad och kämpar för att hålla Blackrock-orcherna och Redridge-kobolderna borta från staden. Magistrate Solomon kan inte avvara en enda vakt från försvarslinjen för den farliga färden söderut genom Duskwood. Stormwind ignorerar hans vädjanden om kungliga trupper, så han måste förlita sig på pålitliga resenärer som du för att framföra sina brådskande vädjanden till grannstäderna.",al={"varför skickas jag till darkshire","varför skickar inte solomon en vakt","varför jag i messenger to darkshire"}}},fp="22,288,24.391.0,23.317.0,43.224.0,27.211.0,24.179.0,46.142.0,31.155.0,45.186.0"}
